def set_ui_font(root, wanted=""):
    """Use the chosen font if Windows has it, else the nicest one available."""
    global FONT_UI
    try:
        import tkinter.font as tkfont
        have = {f.lower(): f for f in tkfont.families(root)}
    except Exception:
        have = {}
    for name in ([wanted] if wanted else []) + ["Zen Maru Gothic", "Segoe UI Variable Display", "Segoe UI Variable Text", "Segoe UI"]:
        if name and name.lower() in have:
            FONT_UI = have[name.lower()]
            break
    return FONT_UI


def available_fonts(root):
    try:
        import tkinter.font as tkfont
        have = {f.lower() for f in tkfont.families(root)}
    except Exception:
        have = set()
    return [f for f in FONT_CHOICES if f.lower() in have]

