def _mixhex(c1, c2, t):
    a, b = c1.lstrip("#"), c2.lstrip("#")
    v = [int(int(a[i:i + 2], 16) * (1 - t) + int(b[i:i + 2], 16) * t) for i in (0, 2, 4)]
    return "#%02x%02x%02x" % tuple(max(0, min(255, x)) for x in v)


def _realm(night, paper, card, ink, grey, acc, accd, gold, glow, onacc, good="#5fd39a", bad="#ff6b7d"):
    """A night-shrine colour scheme for the whole app (dark lacquer, moonlight text, gold trim, foxfire glow)."""
    return dict(ink=ink, paper=paper, acc=acc, accd=accd, grey=grey, card=card, night=night, gold=gold, glow=glow,
                onacc=onacc, good=good, bad=bad,
                night2=_mixhex(night, acc, 0.16), banner=_mixhex(paper, acc, 0.10),
                field=_mixhex(card, ink, 0.07), line=_mixhex(card, ink, 0.16), edge=_mixhex(card, ink, 0.30),
                hover=_mixhex(card, ink, 0.12), foot=_mixhex(paper, acc, 0.05),
                start=_mixhex(card, acc, 0.24), nowbg=_mixhex(card, acc, 0.17), soonbg=_mixhex(card, gold, 0.07),
                donebg=_mixhex(card, good, 0.13), missbg=_mixhex(card, bad, 0.13),
                donebtn=_mixhex(card, good, 0.34), delbtn=_mixhex(card, bad, 0.32), fill=glow,
                bub=_mixhex(night, card, 0.35), bubink=ink)


