def apply_theme(name):
    """Colours are module globals so every window picks them up (ORANGE/ORANGE_D = the accent colours)."""
    global INK, PAPER, ORANGE, ORANGE_D, GREY, T, ACTIVE_PAL, NIGHT, FIELD, LINE, ON_ACC, GOLD, GLOW
    t = THEMES.get(name) or THEMES["snow"]
    INK, PAPER, ORANGE, ORANGE_D, GREY = t["ink"], t["paper"], t["acc"], t["accd"], t["grey"]
    NIGHT, FIELD, LINE, ON_ACC, GOLD, GLOW = t["night"], t["field"], t["line"], t["onacc"], t["gold"], t["glow"]
    T = t
    ACTIVE_PAL = dict(FUR.get(name) or SNOW_PAL)


