def load_config():
    cfg = json.loads(json.dumps(DEFAULTS))
    try:
        with open(CONFIG_PATH, "r", encoding="utf-8") as f:
            cfg.update(json.load(f))
    except Exception:
        pass
    if not cfg.get("bgm_quiet_v2"):                   # zenko8: music became much quieter; start everyone on the new soft level
        cfg["bgm_quiet_v2"] = True
        cfg["bgm_volume"] = 2
    if cfg.get("whisper_model") == "base.en" and not cfg.get("whisper_model_set"):
        cfg["whisper_model"] = "small.en"            # upgrade older installs to the more accurate model
    return cfg


def save_config(cfg):
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        with open(CONFIG_PATH, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2)
    except Exception:
        pass


def load_stats():
    try:
        with open(STATS_PATH, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def add_stats(seconds):
    st = load_stats()
    day = datetime.date.today().isoformat()
    st[day] = round(st.get(day, 0) + seconds)
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        with open(STATS_PATH, "w", encoding="utf-8") as f:
            json.dump(st, f)
    except Exception:
        pass


def today_focus_minutes():
    return int(load_stats().get(datetime.date.today().isoformat(), 0) // 60)


