#  Timetable storage
# ----------------------------------------------------------------------------------
def parse_clock(text):
    """'4pm', '16:30', '4.30 pm', '9' -> 'HH:MM' (or None)."""
    m = re.match(r"^\s*(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm|a|p)?\s*$", (text or "").lower())
    if not m:
        return None
    h, mi, ap = int(m.group(1)), int(m.group(2) or 0), m.group(3)
    if ap:
        if not 1 <= h <= 12:
            return None
        h = h % 12 + (12 if ap.startswith("p") else 0)
    if h > 23 or mi > 59:
        return None
    return "%02d:%02d" % (h, mi)


def load_tt():
    try:
        with open(TIMETABLE_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return []
    out = []
    for it in data if isinstance(data, list) else []:
        if isinstance(it, dict) and parse_clock(it.get("start", "")) and it.get("task"):
            it["start"] = parse_clock(it["start"])
            it["mins"] = int(it.get("mins") or 30)
            it.setdefault("daily", False)
            it.setdefault("date", datetime.date.today().isoformat())
            it.setdefault("done", [])
            out.append(it)
    return out


def save_tt(items):
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        with open(TIMETABLE_PATH, "w", encoding="utf-8") as f:
            json.dump(items, f, indent=2)
    except Exception:
        pass


def tt_today(items, day=None):
    d = (day or datetime.date.today()).isoformat()
    return sorted([i for i in items if (i.get("daily") and d not in i.get("skip", ())) or i.get("date") == d],
                  key=lambda i: i["start"])


def tt_done(it, day=None):
    return (day or datetime.date.today()).isoformat() in it.get("done", [])


def tt_window(it, day=None):
    """(start, end) datetimes of an item on a day (today by default)."""
    d = day or datetime.date.today()
    h, m = map(int, it["start"].split(":"))
    st = datetime.datetime(d.year, d.month, d.day, h, m)
    return st, st + datetime.timedelta(minutes=it["mins"])


def fmt_hm(minutes):
    h, m = divmod(int(minutes), 60)
    return ("%dh %02dm" % (h, m) if m else "%dh" % h) if h else "%dm" % m


def shade(hex_color, f=0.92):
    if not hex_color.startswith("#"):
        hex_color = {"white": "#ffffff"}.get(hex_color, "#ffffff")
    c = hex_color.lstrip("#")
    return "#%02x%02x%02x" % tuple(min(255, int(int(c[i:i + 2], 16) * f)) for i in (0, 2, 4))


_mutex_handle = None

if IS_WIN:
    from ctypes import wintypes
    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32
    user32.GetForegroundWindow.restype = ctypes.c_void_p
    user32.GetWindowTextLengthW.argtypes = [ctypes.c_void_p]
    user32.GetWindowTextW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p, ctypes.c_int]
    user32.GetWindowThreadProcessId.argtypes = [ctypes.c_void_p, ctypes.POINTER(ctypes.c_ulong)]
    kernel32.OpenProcess.restype = ctypes.c_void_p
    kernel32.OpenProcess.argtypes = [ctypes.c_ulong, ctypes.c_int, ctypes.c_ulong]
    kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
    kernel32.QueryFullProcessImageNameW.argtypes = [ctypes.c_void_p, ctypes.c_ulong,
                                                    ctypes.c_wchar_p, ctypes.POINTER(ctypes.c_ulong)]
    kernel32.GetTickCount.restype = ctypes.c_ulong

    class _LASTINPUTINFO(ctypes.Structure):
        _fields_ = [("cbSize", ctypes.c_uint), ("dwTime", ctypes.c_uint)]


def make_dpi_aware():
    if not IS_WIN:
        return
    try:
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
    except Exception:
        try:
            user32.SetProcessDPIAware()
        except Exception:
            pass


def dpi_scale():
    if not IS_WIN:
        return 1.0
    try:
        return max(1.0, user32.GetDpiForSystem() / 96.0)
    except Exception:
        return 1.0


def single_instance():
    """Return False if another Zenko is already running."""
    global _mutex_handle
    if not IS_WIN:
        return True
    k32 = ctypes.WinDLL("kernel32", use_last_error=True)
    _mutex_handle = k32.CreateMutexW(None, False, "FoxBuddy_SingleInstance_Mutex")
    return ctypes.get_last_error() != 183      # 183 = ERROR_ALREADY_EXISTS (another fox is running)


def foreground_info():
    """(window title, process exe name in lower case) of the window you are using right now."""
    if not IS_WIN:
        path = os.environ.get("FOX_FAKE_TITLE_FILE")      # only used for testing off-Windows
        if path and os.path.exists(path):
            try:
                parts = open(path, encoding="utf-8").read().strip().split("\n")
                return parts[0].strip(), (parts[1].strip().lower() if len(parts) > 1 else "")
            except Exception:
                pass
        return "", ""
    try:
        hwnd = user32.GetForegroundWindow()
        if not hwnd:
            return "", ""
        n = user32.GetWindowTextLengthW(hwnd)
        buf = ctypes.create_unicode_buffer(n + 1)
        user32.GetWindowTextW(hwnd, buf, n + 1)
        pid = ctypes.c_ulong()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        proc = ""
        h = kernel32.OpenProcess(0x1000, False, pid.value)       # PROCESS_QUERY_LIMITED_INFORMATION
        if h:
            size = ctypes.c_ulong(520)
            pb = ctypes.create_unicode_buffer(520)
            if kernel32.QueryFullProcessImageNameW(h, 0, pb, ctypes.byref(size)):
                proc = os.path.basename(pb.value).lower()
            kernel32.CloseHandle(h)
        return buf.value, proc
    except Exception:
        return "", ""


_PID_NAMES = {"t": 0.0, "map": {}}


def _pid_name(pid):
    now = time.monotonic()
    if now - _PID_NAMES["t"] > 60:
        _PID_NAMES["t"], _PID_NAMES["map"] = now, {}
    m = _PID_NAMES["map"]
    if pid not in m:
        name = ""
        h = kernel32.OpenProcess(0x1000, False, pid)
        if h:
            size = ctypes.c_ulong(520)
            pb = ctypes.create_unicode_buffer(520)
            if kernel32.QueryFullProcessImageNameW(h, 0, pb, ctypes.byref(size)):
                name = os.path.basename(pb.value).lower()
            kernel32.CloseHandle(h)
        m[pid] = name
    return m[pid]


def spotify_window():
    """Spotify desktop app state from its window title (works offline, no account needed).
    None = Spotify isn't open. {'playing': bool, 'title': str, 'artist': str} otherwise (title empty when paused)."""
    if not IS_WIN:
        v = os.environ.get("FOX_FAKE_SPOTIFY")
        if not v:
            return None
        parts = (v.split("|") + ["", "", "1"])[:3]
        return {"playing": parts[2] == "1", "title": parts[0], "artist": parts[1]}
    titles = []
    try:
        WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, ctypes.c_void_p, ctypes.c_void_p)

        def cb(hwnd, _):
            n = user32.GetWindowTextLengthW(hwnd)
            if n <= 0:
                return True
            pid = ctypes.c_ulong()
            user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
            if _pid_name(pid.value) == "spotify.exe":
                buf = ctypes.create_unicode_buffer(n + 1)
                user32.GetWindowTextW(hwnd, buf, n + 1)
                t = buf.value.strip()
                if t and not re.search(r"GDI\+|IME|MSCTF|Legacy Window|^Default", t):
                    titles.append(t)
            return True
        user32.EnumWindows(WNDENUMPROC(cb), 0)
    except Exception:
        return None
    if not titles:
        return None
    for t in titles:
        if " - " in t and not t.lower().startswith("spotify"):
            artist, title = t.split(" - ", 1)
            return {"playing": True, "title": title.strip(), "artist": artist.strip()}
    return {"playing": False, "title": "", "artist": ""}


def media_key(which):
    """Press a media key (works with the Spotify app even without connecting your account)."""
    vk = {"playpause": 0xB3, "next": 0xB0, "previous": 0xB1}[which]
    if not IS_WIN:
        CLOSED_LOG.append("media:" + which)
        return
    try:
        user32.keybd_event.argtypes = [ctypes.c_ubyte, ctypes.c_ubyte, ctypes.c_ulong, ctypes.c_size_t]
        user32.keybd_event(vk, 0, 1, 0)
        user32.keybd_event(vk, 0, 1 | 2, 0)
    except Exception:
        pass


