def idle_seconds():
    if not IS_WIN:
        return 0.0
    try:
        li = _LASTINPUTINFO()
        li.cbSize = ctypes.sizeof(li)
        if user32.GetLastInputInfo(ctypes.byref(li)):
            return ((kernel32.GetTickCount() - li.dwTime) & 0xFFFFFFFF) / 1000.0
    except Exception:
        pass
    return 0.0


def work_area(root):
    """Screen area not covered by the taskbar: left, top, right, bottom."""
    if IS_WIN:
        try:
            r = wintypes.RECT()
            user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(r), 0)    # SPI_GETWORKAREA
            return r.left, r.top, r.right, r.bottom
        except Exception:
            pass
    return 0, 0, root.winfo_screenwidth(), root.winfo_screenheight()


def monitor_area(x, y, root):
    """Work area (no taskbar) of the screen that holds point x, y: left, top, right, bottom. Works with 2+ monitors."""
    if IS_WIN:
        try:
            mu = ctypes.WinDLL("user32")

            class _MI(ctypes.Structure):
                _fields_ = [("cbSize", ctypes.c_ulong), ("rcMonitor", wintypes.RECT), ("rcWork", wintypes.RECT),
                            ("dwFlags", ctypes.c_ulong)]
            mu.MonitorFromPoint.restype = ctypes.c_void_p
            mu.MonitorFromPoint.argtypes = [wintypes.POINT, ctypes.c_ulong]
            mu.GetMonitorInfoW.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            hm = mu.MonitorFromPoint(wintypes.POINT(int(x), int(y)), 2)          # MONITOR_DEFAULTTONEAREST
            mi = _MI()
            mi.cbSize = ctypes.sizeof(mi)
            if hm and mu.GetMonitorInfoW(hm, ctypes.byref(mi)):
                rc = mi.rcWork
                return rc.left, rc.top, rc.right, rc.bottom
        except Exception:
            pass
    return work_area(root)


