# ---- the sound kit: koto plucks, a suzu shrine bell, a furin wind chime, wooden taps ----------
# Every sound is synthesised here in plain Python (no sound files to download) and saved once as a
# small .wav in the app's data folder, then played with Windows' own winsound module.
SR = 22050
_NOTE = {"D4": 293.66, "E4": 329.63, "G4": 392.0, "A4": 440.0, "Bb4": 466.16, "B4": 493.88, "Eb4": 311.13,
         "D5": 587.33, "E5": 659.26, "G5": 783.99, "A5": 880.0, "B5": 987.77, "D6": 1174.66, "E6": 1318.51,
         "A6": 1760.0, "Eb5": 622.25, "Bb5": 932.33}


def _koto(freq, dur=0.7, bright=0.55, seed=1):
    """A plucked string (Karplus-Strong): sounds like a koto when kept short and bright."""
    rnd = random.Random(seed)
    n = max(2, int(SR / freq))
    buf = [rnd.uniform(-1, 1) for _ in range(n)]
    for _ in range(2 - int(bright * 2)):                  # duller pluck = pre-smoothed noise
        buf = [(buf[i] + buf[i - 1]) * 0.5 for i in range(n)]
    out = []
    i = 0
    damp = 0.996 if freq < 700 else 0.993
    for _ in range(int(dur * SR)):
        a = buf[i]
        b = buf[(i + 1) % n]
        buf[i] = (a + b) * 0.5 * damp
        out.append(a)
        i = (i + 1) % n
    return out


def _bell(freq, dur, partials, decay, seed=0):
    """A struck metal bell: inharmonic partials that ring and fade."""
    out = [0.0] * int(dur * SR)
    for k, (mul, amp) in enumerate(partials):
        f = freq * mul
        d = decay * (1.0 - 0.12 * k)
        w = 2 * math.pi * f / SR
        for i in range(len(out)):
            out[i] += amp * math.sin(w * i + k) * math.exp(-i / (SR * d))
    att = int(0.002 * SR)
    for i in range(min(att, len(out))):
        out[i] *= i / float(att)
    return out


def _tap(freq=1700, dur=0.06):
    """A dry wooden tap (like hyoshigi clappers)."""
    rnd = random.Random(7)
    out = []
    for i in range(int(dur * SR)):
        t = i / float(SR)
        e = math.exp(-t / 0.012)
        out.append(e * (0.75 * math.sin(2 * math.pi * freq * t) + 0.35 * math.sin(2 * math.pi * freq * 1.58 * t))
                   + rnd.uniform(-1, 1) * math.exp(-t / 0.003) * 0.4)
    return out


def _drum(freq=90, dur=0.32):
    """A soft taiko thump: a low tone that drops in pitch."""
    out, ph = [], 0.0
    for i in range(int(dur * SR)):
        t = i / float(SR)
        f = freq * (1 + 0.8 * math.exp(-t / 0.03))
        ph += 2 * math.pi * f / SR
        out.append(math.sin(ph) * math.exp(-t / 0.11))
    return out


def _pop(f0=420, f1=1100, dur=0.07):
    out, ph = [], 0.0
    for i in range(int(dur * SR)):
        t = i / float(dur * SR)
        ph += 2 * math.pi * (f0 + (f1 - f0) * t) / SR
        out.append(math.sin(ph) * math.sin(math.pi * t))
    return out


def _suzu(start=0.0, hits=4, seed=3):
    """A little shake of a shrine bell (suzu)."""
    rnd = random.Random(seed)
    parts = []
    t = start
    for h in range(hits):
        f = 2350 * rnd.uniform(0.97, 1.03)
        parts.append((t, _bell(f, 0.32, ((1, 0.6), (2.32, 0.3), (4.25, 0.18), (6.63, 0.1)), 0.07, h), rnd.uniform(0.35, 0.6)))
        t += rnd.uniform(0.045, 0.075)
    return parts


def _furin(start=0.0, f=2093.0, gain=0.5):
    """A glass wind chime (furin): long, airy ring."""
    return [(start, _bell(f, 1.3, ((1, 0.55), (2.76, 0.25), (5.40, 0.12)), 0.45), gain),
            (start + 0.11, _bell(f * 1.335, 1.0, ((1, 0.4), (2.76, 0.18)), 0.35), gain * 0.6)]


def _arp(notes, start=0.0, step=0.11, dur=0.8, gain=0.8):
    return [(start + i * step, _koto(_NOTE[n], dur, seed=i + 3), gain) for i, n in enumerate(notes)]


def _sound_parts(kind):
    """What each sound is made of: [(start seconds, samples, gain)]. 'a+b' mixes two (b = her voice, on top)."""
    if "+" in kind:
        a, b = kind.split("+", 1)
        return [(st, sm, g * 0.5) for st, sm, g in _sound_parts(a)] + _sound_parts(b)
    ex = extra_sound_parts(kind)
    if ex is not None:
        return ex
    if kind == "tap":                  # buttons
        return [(0.0, _tap(), 0.55)]
    if kind == "toggle":               # check boxes, choices
        return [(0.0, _koto(_NOTE["A5"], 0.28, 0.8), 0.45), (0.0, _tap(2400, 0.03), 0.25)]
    if kind == "nav":                  # switching pages in the hub
        return [(0.0, _koto(_NOTE["E5"], 0.45, 0.7), 0.42), (0.05, _koto(_NOTE["A5"], 0.45, 0.7, 2), 0.32)]
    if kind == "open":                 # a window opens: wind chime
        return _furin(0.0, 2093.0, 0.42)
    if kind == "close":
        return [(0.0, _koto(_NOTE["B5"], 0.35, 0.6), 0.35), (0.07, _koto(_NOTE["E5"], 0.45, 0.6, 2), 0.35)]
    if kind == "send":                 # chat message sent
        return [(0.0, _pop(), 0.5)]
    if kind == "reply":                # Zenko answers in chat
        return [(0.0, _koto(_NOTE["D6"], 0.35, 0.8), 0.35), (0.08, _koto(_NOTE["A5"], 0.4, 0.8, 4), 0.3)]
    if kind == "hello":                # "kon kon!"
        return _arp(["D5", "A5"], step=0.13, dur=0.5, gain=0.6) + _suzu(0.22, 2)
    if kind == "pet":
        return _arp(["E6", "A6"], step=0.07, dur=0.35, gain=0.5) + _suzu(0.1, 2, 9)
    if kind == "happy":
        return _arp(["D5", "E5", "A5", "D6"], step=0.09, dur=0.6, gain=0.55)
    if kind == "start":                # a focus session begins: bell shake, then a rising phrase
        return _suzu(0.0, 5) + _arp(["D5", "E5", "G5", "A5", "D6"], start=0.28, step=0.09, dur=0.7, gain=0.5)
    if kind == "done":                 # a session is complete
        return _suzu(0.0, 6, 5) + _arp(["A4", "D5", "E5", "A5", "B5", "D6"], start=0.3, step=0.1, dur=0.9, gain=0.5) \
            + _furin(0.95, 2349.0, 0.32)
    if kind == "ding":                 # a gentle heads-up (timetable, deadlines, breaks)
        return _furin(0.0, 2349.0, 0.5)
    if kind == "eyes_done":            # the 20-20-20 eye break is over: a clear double bell ding
        return _suzu(0.0, 3, 7) + _arp(["A5", "E6"], start=0.12, step=0.16, dur=0.9, gain=0.6) + _furin(0.45, 2637.0, 0.45)
    if kind == "sad":
        return _arp(["Bb4", "A4", "Eb4", "D4"], step=0.2, dur=0.9, gain=0.6)
    if kind == "nag":                  # caught you! two soft taiko beats and a bell
        return [(0.0, _drum(), 0.9), (0.18, _drum(110), 0.7)] + _suzu(0.34, 3, 11)
    return []


def _wav_bytes(kind, vol=2):
    import io
    import wave
    import struct
    parts = _sound_parts(kind)
    if not parts:
        return None
    n = max(int(st * SR) + len(sm) for st, sm, _ in parts) + int(0.02 * SR)
    mixb = [0.0] * n
    for st, sm, gn in parts:
        o = int(st * SR)
        for i, v in enumerate(sm):
            mixb[o + i] += v * gn
    peak = max(1e-6, max(abs(v) for v in mixb))
    level = {1: 0.3, 2: 0.55, 3: 0.85}.get(int(vol), 0.55)
    k = 32767 * level / max(peak, 1.0)
    fade = int(0.015 * SR)
    for i in range(fade):
        mixb[n - 1 - i] *= i / float(fade)
    data = struct.pack("<%dh" % n, *[int(max(-1.0, min(1.0, v * k / 32767)) * 32767) for v in mixb])
    bio = io.BytesIO()
    w = wave.open(bio, "wb")
    w.setnchannels(1)
    w.setsampwidth(2)
    w.setframerate(SR)
    w.writeframes(data)
    w.close()
    return bio.getvalue()


SOUND_KINDS = ("tap", "toggle", "nav", "open", "close", "send", "reply", "hello", "pet", "happy", "start", "done",
               "ding", "sad", "nag", "eyes_done")
SOUND_DIR = os.path.join(DATA_DIR, "sounds")
_SND_FILES = {}


def sound_file(kind, vol=None):
    """Path of the .wav for this sound (made on first use, then kept)."""
    vol = int(SOUND["vol"] if vol is None else vol)
    key = (kind, vol)
    p = _SND_FILES.get(key)
    if p and os.path.exists(p):
        return p
    tag = "k1" + (("p%d" % int(float(SOUND.get("pitch", 1.0)) * 100)) if "v_" in kind else "")
    key = (kind, vol, tag)
    p = _SND_FILES.get(key)
    if p and os.path.exists(p):
        return p
    p = os.path.join(SOUND_DIR, "%s_v%d_%s.wav" % (kind.replace("+", "_"), vol, tag))
    if not os.path.exists(p):
        data = _wav_bytes(kind, vol)
        if not data:
            return None
        os.makedirs(SOUND_DIR, exist_ok=True)
        tmp = p + ".part"
        with open(tmp, "wb") as f:
            f.write(data)
        os.replace(tmp, p)
    _SND_FILES[key] = p
    return p


def prepare_sounds():
    """Make all the sound files in the background (takes a second or two the very first time)."""
    def run():
        for k in SOUND_KINDS:
            try:
                sound_file(k)
            except Exception:
                pass
    threading.Thread(target=run, daemon=True).start()


def play_sound(kind, voiced=False):
    if not IS_WIN:
        return False
    try:
        import winsound
        p = voice_clip_file(kind) if voiced else sound_file(kind)
        if not p:
            return False
        winsound.PlaySound(p, winsound.SND_FILENAME | winsound.SND_ASYNC | winsound.SND_NODEFAULT)
        return True
    except Exception:
        return False


def ui_sound(kind):
    """Little interface sounds (buttons, pages, toggles). Settings > General > Interface sounds."""
    if SOUND.get("ui") and IS_WIN:
        threading.Thread(target=play_sound, args=(kind,), daemon=True).start()


def beep(kind="nag"):
    """Zenko's own sounds (greetings, nags, praise...). Settings > Sound."""
    if not (IS_WIN and SOUND["on"]):
        return

    def run():
        if play_sound(kind, voiced=True) or kind not in TUNES:
            return
        if not _snd_lock.acquire(False):
            return
        try:
            import winsound
            for f, ms in TUNES[kind]:
                winsound.Beep(f, ms)
        except Exception:
            pass
        finally:
            _snd_lock.release()
    threading.Thread(target=run, daemon=True).start()


# ---- Zenko learns (on this PC only) ---------------------------------------------------
# Not a self-rewriting AI: she remembers replies you teach her and notices your focus habits,
# then uses them in chat, in hints and in the smart brain's context. Stored in learned.json.
LEARN_PATH = os.path.join(DATA_DIR, "learned.json")


def load_learned():
    try:
        with open(LEARN_PATH, "r", encoding="utf-8") as f:
            d = json.load(f)
    except (OSError, ValueError):
        d = {}
    d.setdefault("replies", {})
    d.setdefault("sessions", [])
    d.setdefault("distractions", {})
    return d


def save_learned(d):
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        tmp = LEARN_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=1)
        os.replace(tmp, LEARN_PATH)
    except OSError:
        pass


def _norm_phrase(t):
    return re.sub(r"[^a-z0-9 ]+", "", t.lower()).strip()


def learn_reply(phrase, answer):
    d = load_learned()
    d["replies"][_norm_phrase(phrase)[:80]] = answer.strip()[:300]
    save_learned(d)


def forget_reply(phrase):
    d = load_learned()
    k = _norm_phrase(phrase)
    if k == "everything":
        n = len(d["replies"]) + len(d["sessions"]) + len((d.get("style") or {}).get("aliases") or {}) + len(d.get("facts") or {})
        save_learned({})
        return n
    hit = d["replies"].pop(k, None)
    save_learned(d)
    return 1 if hit is not None else 0


def learned_reply(text, fuzzy=False):
    reps = load_learned()["replies"]
    k = _norm_phrase(text)
    if k in reps:
        return reps[k]
    if fuzzy and reps:
        best = difflib.get_close_matches(k, list(reps), n=1, cutoff=0.86)
        if best:
            return reps[best[0]]
    return None


def learn_session(planned_min, focused_min, completed, dist_min):
    d = load_learned()
    now = datetime.datetime.now()
    d["sessions"].append({"day": now.strftime("%Y-%m-%d"), "hour": now.hour, "wd": now.weekday(),
                          "planned": int(planned_min), "focused": int(focused_min), "done": bool(completed),
                          "dist": int(dist_min)})
    d["sessions"] = d["sessions"][-300:]
    save_learned(d)


def learn_distraction(site):
    d = load_learned()
    k = str(site)[:40]
    d["distractions"][k] = int(d["distractions"].get(k, 0)) + 1
    save_learned(d)


def fact_store(question, answer):
    d = load_learned()
    f = d.setdefault("facts", {})
    f[_norm_phrase(question)[:80]] = {"q": question.strip()[:120], "a": answer[:1500], "t": time.time()}
    for k in sorted(f, key=lambda k: f[k].get("t", 0))[:max(0, len(f) - 60)]:
        f.pop(k, None)
    save_learned(d)


def fact_recall(question, max_age=12 * 3600):
    f = (load_learned().get("facts") or {}).get(_norm_phrase(question)[:80])
    if f and time.time() - float(f.get("t", 0)) < max_age:
        return f.get("a")
    return None


def facts_recent(n=8):
    f = load_learned().get("facts") or {}
    return [v.get("q", k) for k, v in sorted(f.items(), key=lambda kv: -kv[1].get("t", 0))[:n]]


def _part_of_day(h):
    return "morning" if 5 <= h < 12 else ("afternoon" if h < 17 else ("evening" if h < 22 else "late at night"))


def learned_habits():
    """What the sessions say: best time of day, a session length you usually finish, top distraction."""
    d = load_learned()
    ss = d["sessions"][-80:]
    out = {"n": len(d["sessions"]), "replies": len(d["replies"])}
    if len(ss) >= 3:
        parts = {}
        for s in ss:
            p = _part_of_day(int(s.get("hour", 12)))
            ok, n = parts.get(p, (0, 0))
            parts[p] = (ok + (1 if s.get("done") and s.get("dist", 0) <= max(2, s.get("planned", 25) // 5) else 0), n + 1)
        good = [(ok / float(n), n, p) for p, (ok, n) in parts.items() if n >= 2]
        if good:
            out["best_time"] = max(good)[2]
        done = sorted(s["planned"] for s in ss if s.get("done"))
        if done:
            out["good_len"] = done[len(done) // 2]
        out["finish_rate"] = int(100 * sum(1 for s in ss if s.get("done")) / float(len(ss)))
    if d["distractions"]:
        out["top_distraction"] = max(d["distractions"].items(), key=lambda kv: kv[1])[0]
    return out


def learned_summary():
    h = learned_habits()
    lines = []
    if h.get("best_time"):
        lines.append("You focus best in the %s." % h["best_time"])
    if h.get("good_len"):
        lines.append("You usually finish %d-minute sessions." % h["good_len"])
    if "finish_rate" in h:
        lines.append("You finish %d%% of the sessions you start." % h["finish_rate"])
    if h.get("top_distraction"):
        lines.append("Your biggest distraction is %s." % PRETTY.get(h["top_distraction"], h["top_distraction"]))
    reps = load_learned()["replies"]
    if reps:
        lines.append("Things you taught me: " + "; ".join("'%s'" % k for k in list(reps)[:8]) + ("..." if len(reps) > 8 else ""))
    al = shorthand_aliases()
    if al:
        lines.append("Your shorthand: " + ", ".join("%s = %s" % kv for kv in list(al.items())[-8:]))
    looked = facts_recent(5)
    if looked:
        lines.append("Things I looked up for you: " + "; ".join(looked))
    if not lines:
        lines.append("Nothing yet. Do a few focus sessions and I'll start noticing your habits. "
                     "You can also teach me: learn: good morning = Ohayo! Let's get to work.")
    return "\n".join(lines)


def learned_hint():
    h = learned_habits()
    bits = []
    if h.get("good_len"):
        bits.append("you usually finish %d-min sessions" % h["good_len"])
    if h.get("best_time"):
        bits.append("you focus best in the %s" % h["best_time"])
    return ("I've noticed " + " and ".join(bits) + ".") if bits else ""


# ---- Her own voice, and your shorthand ------------------------------------------------------
# Zenko talks like Zenko: a little fox girl with anime-style fox exclamations ("Kon kon~", "ehehe~",
# "hmph!", "...kon!"). She does NOT copy how you type. She only learns your shorthand so she understands
# you (sched = timetable), stored in learned.json and wiped by "Forget everything".
FOX_TICS = {"happy": ["Kon!", "Kon kon~", "Yatta!", "Ehehe~", "Sugoi!", "Waai~", "Kon! Kon!"],
            "think": ["Hmm hmm~", "Ne, ne~", "Fumu fumu...", "Uwaa~", "Kon?"],
            "sad": ["Uu~", "Auu...", "Kon...", "Gomen ne~"],
            "cross": ["Hmph!", "Mou~!", "Kon!!"]}
_TIC_START = re.compile(r"^(kon|ehehe|yatta|sugoi|waai|hmm|ne[,~]|fumu|uwaa|uu~|auu|gomen|hmph|mou~|kya|poof|okay~)", re.I)
FOX_VOICE = ("Zenko's voice: she is a cute, cheerful fox girl and talks like a fox girl from an anime. She sprinkles in fox "
             "exclamations like 'Kon!', 'Kon kon~', 'ehehe~', 'yatta!', 'sugoi!', 'uwaa~', 'hmph!' (when you slack off), "
             "'ne~?', and sometimes ends a sentence with '~kon!' (e.g. 'You've got this~kon!'). Use one or two per reply, "
             "never so many that the answer gets hard to read. She has her own voice and does not copy how the user types.")


def fox_voice(text, mood="happy", tail=True):
    """Give one of her lines Zenko's fox voice: an exclamation in front, sometimes a '~kon!' at the end.
    Facts, lists and numbers keep their words; only the start (and the end of one-liners) changes."""
    t = (text or "").strip()
    if not t:
        return t
    lvl = VOICE.get("level", 1)
    if lvl <= 0:
        return t
    if not _TIC_START.match(t) and (lvl >= 2 or random.random() < 0.92):
        t = random.choice(FOX_TICS.get(mood, FOX_TICS["happy"])) + " " + t
    if tail and "\n" not in t and len(t) < 160 and t[-1] in ".!" and not t.endswith(("~kon!", "Kon!", "kon!", "...")) \
            and random.random() < (0.85 if lvl >= 2 else 0.45):
        t = t[:-1] + "~kon!"
    return t


