def _style_store():
    d = load_learned()
    st = d.setdefault("style", {})
    for k in [k for k in st if k != "aliases"]:          # older versions kept more; now only your shorthand
        st.pop(k, None)
    st.setdefault("aliases", {})
    return d, st


def learn_alias(word, meaning):
    word, meaning = word.strip().lower()[:30], meaning.strip().lower()[:60]
    if not word or not meaning or word == meaning:
        return False
    d, st = _style_store()
    st["aliases"][word] = meaning
    if len(st["aliases"]) > 200:
        st["aliases"].pop(next(iter(st["aliases"])))
    save_learned(d)
    return True


def learn_aliases_from(missed, understood):
    """She didn't get `missed`, then got `understood` right after: learn the words you swapped.
    e.g. 'sched pls' then 'timetable pls' -> sched = timetable."""
    a, b = missed.lower().split(), understood.lower().split()
    if not a or not b or len(a) > 12 or difflib.SequenceMatcher(None, a, b).ratio() < 0.34:
        return []
    out = []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b).get_opcodes():
        if op == "replace" and i2 - i1 == 1 and 1 <= j2 - j1 <= 2:
            old, new = a[i1].strip("?,.!"), " ".join(b[j1:j2]).strip("?,.!")
            if old and new and old != new and not old.isdigit() and old not in VOCAB and len(old) <= 12 and \
                    (old[0] == new[0] or len(old) <= 3 or len(a) > 1) and old not in _STOP:
                if learn_alias(old, new):
                    out.append((old, new))
    return out


def shorthand_aliases():
    return dict((load_learned().get("style") or {}).get("aliases") or {})


def expand_shorthand(text):
    """'wat's next tmrw' -> 'what's next tomorrow' (your learned shorthand + common chat slang)."""
    al = shorthand_aliases()

    def sub(m):
        w = m.group(0)
        lw = w.lower()
        return al.get(lw) or SHORTHAND.get(lw) or w
    return re.sub(r"[A-Za-z0-9/']+", sub, text)


def shorthand_summary():
    al = shorthand_aliases()
    if not al:
        return ("Ne~ I haven't learned any of your shorthand yet! I already know the usual ones (tmrw, rn, pls, hw...). "
                "Teach me more: when I say sched I mean timetable")
    return "Kon kon~ Your shorthand I've learned: " + ", ".join("%s = %s" % kv for kv in list(al.items())[-12:])


