def close_distraction(kind):
    """kind 'tab' = Ctrl+W in a browser (closes just that tab); 'window' = polite WM_CLOSE to a game/app."""
    if not IS_WIN:
        CLOSED_LOG.append(kind)
        return True
    try:
        hwnd = user32.GetForegroundWindow()
        if not hwnd:
            return False
        if kind == "tab":
            user32.keybd_event.argtypes = [ctypes.c_ubyte, ctypes.c_ubyte, ctypes.c_ulong, ctypes.c_size_t]
            for vk, flag in ((0x11, 0), (0x57, 0), (0x57, 2), (0x11, 2)):     # Ctrl down, W down, W up, Ctrl up
                user32.keybd_event(vk, 0, flag, 0)
        else:
            user32.PostMessageW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_size_t, ctypes.c_size_t]
            user32.PostMessageW(hwnd, 0x0010, 0, 0)                          # WM_CLOSE
        return True
    except Exception:
        return False


def autostart_enabled():
    return IS_WIN and os.path.exists(STARTUP_VBS)


def set_autostart(on):
    if not IS_WIN:
        return
    try:
        if on:
            pyw = sys.executable
            if pyw.lower().endswith("python.exe"):
                pyw = pyw[:-10] + "pythonw.exe"
            script = os.path.abspath(__file__)
            with open(STARTUP_VBS, "w", encoding="utf-8") as f:
                f.write('CreateObject("Wscript.Shell").Run """%s"" ""%s""", 0, False\n' % (pyw, script))
        elif os.path.exists(STARTUP_VBS):
            os.remove(STARTUP_VBS)
    except Exception:
        pass


