def _edit_distance(a, b):
    """Edit distance where swapping two neighbouring letters (tiem -> time) counts as ONE mistake."""
    d = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        d[i][0] = i
    for j in range(len(b) + 1):
        d[0][j] = j
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] != b[j - 1]))
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[-1][-1]


def fix_word(w, first=False):
    lw = w.lower()
    if lw in VOCAB or len(lw) < 3 or not lw.isalpha():
        return w
    limit = 1 if len(lw) <= 6 else 2
    if first and len(lw) >= 5:
        limit = max(limit, 2)
    # typos rarely change the first letter: this keeps "text" from turning into "next"
    cands = [(_edit_distance(lw, v), i, v) for i, v in enumerate(VOCAB) if v[0] == lw[0] or _edit_distance(lw[:2], v[:2]) <= 1 and sorted(lw[:2]) == sorted(v[:2])]
    best = min(cands) if cands else None
    return best[2] if best and best[0] <= limit else w


def fix_typos(text):
    """Spelling-tolerant version of what the user typed, used only to recognise commands."""
    return re.sub(r"[A-Za-z]+", lambda m: fix_word(m.group(0)), text)


def fix_first(text):
    """Fix only the first word (the command verb), keep the rest (task names) exactly as typed."""
    parts = text.strip().split(None, 1)
    if not parts:
        return text
    return fix_word(parts[0], True) + (" " + parts[1] if len(parts) > 1 else "")


# ----------------------------------------------------------------------------------
#  Internet lookups: weather, search, news, currency, time in a city (and questions she can't answer).
#  Free services, no accounts or keys. Only your question (e.g. a city name) is sent.
# ----------------------------------------------------------------------------------
WEB = {
    "geo": "https://geocoding-api.open-meteo.com/v1/search",
    "forecast": "https://api.open-meteo.com/v1/forecast",
    "wiki_api": "https://en.wikipedia.org/w/api.php",
    "wiki_sum": "https://en.wikipedia.org/api/rest_v1/page/summary/",
    "rates": "https://open.er-api.com/v6/latest/",
    "news": "https://feeds.bbci.co.uk/news/rss.xml",
    "news_q": "https://news.google.com/rss/search?hl=en&q=",
    "ddg_api": "https://api.duckduckgo.com/",
    "ddg_html": "https://html.duckduckgo.com/html/",
    "bing": "https://www.bing.com/search",
    "dict": "https://api.dictionaryapi.dev/api/v2/entries/en/",
    "gtx": "https://translate.googleapis.com/translate_a/single",
    "mymemory": "https://api.mymemory.translated.net/get",
}
if os.environ.get("FOX_WEB_BASE"):                      # testing hook: point everything at a local stub
    _b = os.environ["FOX_WEB_BASE"].rstrip("/")
    WEB = {k: _b + "/" + k for k in WEB}
    WEB["wiki_sum"] += "/"
    WEB["rates"] += "/"
    WEB["dict"] += "/"

WMO = {0: "clear sky", 1: "mostly clear", 2: "partly cloudy", 3: "overcast", 45: "fog", 48: "freezing fog",
       51: "light drizzle", 53: "drizzle", 55: "heavy drizzle", 56: "freezing drizzle", 57: "freezing drizzle",
       61: "light rain", 63: "rain", 65: "heavy rain", 66: "freezing rain", 67: "freezing rain",
       71: "light snow", 73: "snow", 75: "heavy snow", 77: "snow grains", 80: "light showers", 81: "showers",
       82: "violent showers", 85: "snow showers", 86: "heavy snow showers", 95: "thunderstorm",
       96: "thunderstorm with hail", 99: "thunderstorm with heavy hail"}
CURRENCY_WORDS = {"dollar": "USD", "dollars": "USD", "usd": "USD", "euro": "EUR", "euros": "EUR", "pound": "GBP",
                  "pounds": "GBP", "sterling": "GBP", "rupee": "INR", "rupees": "INR", "yen": "JPY",
                  "ecd": "XCD", "ec": "XCD", "xcd": "XCD", "gyd": "GYD", "cad": "CAD", "aud": "AUD",
                  "nzd": "NZD", "yuan": "CNY", "franc": "CHF", "francs": "CHF"}
WEB_KEYS = {"weather": "weather", "forecast": "weather", "temperature": "weather", "news": "news",
            "headlines": "news", "search": "search", "google": "search", "lookup": "search",
            "wiki": "search", "wikipedia": "search", "convert": "convert"}
WEB_FILLER = {"what", "whats", "what's", "how", "hows", "how's", "the", "show", "me", "tell", "check", "get",
              "current", "todays", "today's", "is", "it", "like", "please", "can", "you", "give", "my",
              "latest", "top", "a", "do", "i", "need", "want", "see", "up", "look", "now", "right"}
WEB_LEAD = {"in", "for", "at", "of", "near", "about", "on", "is", "the", "like", "report", "me", "today",
            "tomorrow", "now", "to", "a", "an"}


class WebError(Exception):
    pass


def http_get(url, timeout=12):
    req = urllib.request.Request(url, headers={"User-Agent": "FoxBuddy/1.0 (personal focus app)",
                                                "Accept": "application/json, application/xml, */*"})
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read()
    except urllib.error.HTTPError as e:
        raise WebError("The website answered with an error (%s). Try again in a moment." % e.code)
    except Exception:
        raise WebError("I can't reach the internet right now. Check your Wi-Fi, or turn the VPN off/on, and try again.")


def http_json(url, timeout=12):
    try:
        return json.loads(http_get(url, timeout).decode("utf-8", "replace"))
    except WebError:
        raise
    except Exception:
        raise WebError("I got a reply I couldn't read. Try again later.")


def _q(s):
    return urllib.parse.quote(s, safe="")


def geocode(place):
    """'Paris' or 'Paris, France' -> dict(name, country, lat, lon, ...) """
    parts = [p.strip() for p in place.split(",") if p.strip()]
    name = parts[0] if parts else place.strip()
    j = http_json("%s?name=%s&count=10&language=en&format=json" % (WEB["geo"], _q(name)))
    res = j.get("results") or []
    if not res:
        raise WebError("I couldn't find a place called “%s”. Try 'weather in Paris, France'." % place)
    if len(parts) > 1:
        want = " ".join(parts[1:]).lower()
        for r in res:
            blob = " ".join(str(r.get(k, "")) for k in ("country", "country_code", "admin1", "admin2")).lower()
            if want in blob or (len(want) == 2 and r.get("country_code", "").lower() == want):
                return r
    return res[0]


def place_label(g):
    bits = [g.get("name", "")]
    if g.get("admin1") and g.get("admin1") != g.get("name") and g.get("country_code") in ("US", "CA", "AU", "IN"):
        bits.append(g["admin1"])
    if g.get("country"):
        bits.append(g["country"])
    return ", ".join(b for b in bits if b)


def weather_text(place, unit="C"):
    g = geocode(place)
    f = unit.upper() == "F"
    url = ("%s?latitude=%s&longitude=%s&current=temperature_2m,apparent_temperature,relative_humidity_2m,"
           "weather_code,wind_speed_10m,precipitation&daily=weather_code,temperature_2m_max,temperature_2m_min,"
           "precipitation_probability_max&forecast_days=3&timezone=auto&temperature_unit=%s&wind_speed_unit=kmh"
           % (WEB["forecast"], g["latitude"], g["longitude"], "fahrenheit" if f else "celsius"))
    j = http_json(url)
    cur = j.get("current")
    if not isinstance(cur, dict) or cur.get("temperature_2m") is None:
        raise WebError("The weather service had no data for that place.")
    u = (j.get("current_units") or {})
    tu = u.get("temperature_2m") or ("°F" if f else "°C")
    def t(v):
        return "?" if v is None else "%d%s" % (round(v), tu)
    desc = WMO.get(cur.get("weather_code"), "")
    lines = ["%s: %s now%s." % (place_label(g), t(cur.get("temperature_2m")), (", " + desc) if desc else "")]
    extra = []
    if cur.get("apparent_temperature") is not None:
        extra.append("feels like %s" % t(cur["apparent_temperature"]))
    if cur.get("relative_humidity_2m") is not None:
        extra.append("humidity %d%%" % round(cur["relative_humidity_2m"]))
    if cur.get("wind_speed_10m") is not None:
        extra.append("wind %d km/h" % round(cur["wind_speed_10m"]))
    if extra:
        e0 = ", ".join(extra)
        lines.append(e0[:1].upper() + e0[1:] + ".")
    d = j.get("daily") or {}
    days = d.get("time") or []
    for i, label in ((0, "Today"), (1, "Tomorrow")):
        try:
            hi, lo = d["temperature_2m_max"][i], d["temperature_2m_min"][i]
            wc = WMO.get(d["weather_code"][i], "")
            rain = (d.get("precipitation_probability_max") or [None] * 3)[i]
            s = "%s: %s to %s" % (label, t(lo), t(hi))
            if wc:
                s += ", " + wc
            if rain is not None:
                s += ", %d%% chance of rain" % round(rain)
            lines.append(s + ".")
        except (KeyError, IndexError, TypeError):
            pass
    if cur.get("time"):
        lines.append("(Local time there: %s)" % str(cur["time"]).replace("T", " "))
    return "\n".join(lines)


def time_text(place):
    g = geocode(place)
    j = http_json("%s?latitude=%s&longitude=%s&current=temperature_2m&timezone=auto" % (
        WEB["forecast"], g["latitude"], g["longitude"]))
    ts = (j.get("current") or {}).get("time")
    if not ts:
        raise WebError("I couldn't get the time there.")
    try:
        dt = datetime.datetime.strptime(ts[:16], "%Y-%m-%dT%H:%M")
        return "It's %s on %s in %s (%s)." % (dt.strftime("%I:%M %p").lstrip("0"), dt.strftime("%A %d %B"),
                                               place_label(g), j.get("timezone", ""))
    except ValueError:
        return "Local time in %s: %s" % (place_label(g), ts)


def _trim_sentences(txt, n=3, limit=480):
    parts = re.split(r"(?<=[.!?])\s+(?=[A-Z0-9])", (txt or "").strip())
    out = " ".join(parts[:n])
    return out if len(out) <= limit else out[:limit].rsplit(" ", 1)[0] + "…"


def wiki_text(query):
    j = http_json("%s?action=query&list=search&srsearch=%s&srlimit=1&format=json" % (WEB["wiki_api"], _q(query)))
    hits = ((j.get("query") or {}).get("search")) or []
    if not hits:
        raise WebError("I found nothing on that. Try different words.")
    title = hits[0].get("title", query)
    s = http_json(WEB["wiki_sum"] + _q(title.replace(" ", "_")))
    ext = s.get("extract") or ""
    url = (((s.get("content_urls") or {}).get("desktop")) or {}).get("page") or \
        "https://en.wikipedia.org/wiki/" + _q(title.replace(" ", "_"))
    if s.get("type") == "disambiguation" or not ext:
        return "“%s” could mean several things. See: %s" % (title, url)
    return "%s: %s\n(Wikipedia: %s)" % (s.get("title", title), _trim_sentences(ext), url)


def news_text(topic=""):
    import xml.etree.ElementTree as ET
    raw = http_get(WEB["news_q"] + _q(topic) if topic else WEB["news"])
    try:
        root = ET.fromstring(raw)
    except Exception:
        raise WebError("I couldn't read the news feed. Try later.")
    titles = [(i.findtext("title") or "").strip() for i in root.iter("item")]
    titles = [t for t in titles if t][:5]
    if not titles:
        return "No headlines found."
    return ("Headlines%s:\n" % (" on “%s”" % topic if topic else "")) + "\n".join("• " + t for t in titles)


# ---- "Look it up": search the web, read the top pages, summarise --------------------------
# Search uses the free, keyless ddgs package (github.com/deedy5/ddgs) when it is installed;
# otherwise DuckDuckGo, Bing and Wikipedia through Python's own tools (no pip needed).
# The summary comes from the smart brain when Ollama is running, else from a small built-in
# summariser that picks the sentences that best answer your question.
from html.parser import HTMLParser

_STOP = set(("a an the of to in on at for and or is are was were be been being do does did done what who whom whose "
             "when where why how which that this these those it its with by from as about into than then so if not no "
             "can could would should will shall may might must i me my you your u ur we our they them their he she his "
             "her him tell explain define meaning mean means please pls search look up find out know google wiki "
             "something anything thing things really just like also very much many some any there here have has had "
             "get got one two use used using way ways").split())
_JUNK = re.compile(r"cookie|subscribe|sign up|sign in|log in|javascript|newsletter|all rights reserved|©|click here|"
                   r"advertis|privacy policy|terms of (use|service)|your browser|enable js|accept all", re.I)
PAGE_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) "
           "Chrome/124.0 Safari/537.36")


def _terms(text):
    out = []
    for w in re.findall(r"[a-z0-9]+", (text or "").lower()):
        if w in _STOP or len(w) < 2:
            continue
        out.append(_stem(w))
    return out


def _stem(w):
    if len(w) > 4:
        if w.endswith("ies"):
            return w[:-3] + "y"
        if w.endswith(("oes", "ses", "xes", "zes", "ches", "shes")):
            return w[:-2]
        if w.endswith("s") and not w.endswith(("ss", "us", "is")):
            return w[:-1]
    return w


def clean_query(text):
    """'hey can you search up how do volcanoes work?' -> 'how do volcanoes work'"""
    q = (text or "").strip().strip("?!. ")
    q = re.sub(r"^(?:(?:hey|hi|ok|okay|so|um|yo|zenko)[,!]?\s+)+", "", q, flags=re.I)
    q = re.sub(r"^(?:(?:can|could|would) (?:you|u)\s+|please\s+|pls\s+|plz\s+)*"
               r"(?:search(?: the web| online| the internet)?(?: for| up| about)?|look\s*(?:up|into)|google|find(?: out)?"
               r"(?: about)?|tell me(?: about| more about)?|explain(?: to me)?|define|research)\s+", "", q, flags=re.I)
    return q.strip(" ?!.") or (text or "").strip()


def wiki_topic(text):
    q = clean_query(text)
    return re.sub(r"^(who|what|when|where|why|how|which)\s+(is|are|was|were|does|did|do)?\s*(a |an |the )?", "", q,
                  flags=re.I).strip() or q


def wants_lookup(text):
    """Would a person answer this by searching? (questions, 'tell me about...', 'explain...', topics)"""
    t = (text or "").strip().lower()
    words = t.split()
    if len(words) < 2 or len(t) > 300:
        return False
    if looks_like_question(t):
        return True
    if re.match(r"(tell me|explain|define|describe|meaning of|facts? about|info(?:rmation)? (?:on|about)|who'?s|what'?s|"
                r"how (?:to|do|does|did|many|much)|search|look ?up|research)\b", t):
        return True
    if re.match(r"(i|im|i'm|i've|ive|my|me|you|u|ur|you're|lol|lmao|haha|ok|okay|k|yes|no|nah|yeah|yep|hmm|bruh|wow|"
                r"cool|nice|sure|fine|good|bad|great|same|sorry|please|pls|lets|let's|can|could|will|would)\b", t):
        return False
    # a plain topic ("the capital of peru", "photosynthesis in plants"), not chit-chat about you or me
    bare = [w.strip("?!.,'\"") for w in words]
    chatty = {"i", "im", "i'm", "me", "my", "mine", "we", "us", "our", "you", "u", "ur", "your", "you're", "lol", "lmao",
              "haha", "bruh", "omg", "ugh", "pls", "plz", "rn", "tmrw", "idk", "so", "really", "very", "boring", "tired"}
    return 3 <= len(words) <= 8 and not (set(bare) & chatty) and not set(bare) & set(SHORTHAND) and \
        not _EMOJI_RE.search(t)


def _page_get(url, timeout=8, limit=900000, data=None):
    req = urllib.request.Request(url, data=data, headers={"User-Agent": PAGE_UA, "Accept-Language": "en;q=0.9",
                                                          "Accept": "text/html,application/xhtml+xml,*/*;q=0.8"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        ctype = r.headers.get("Content-Type", "") or ""
        raw = r.read(limit)
    if ctype and "html" not in ctype and "text" not in ctype:
        return ""
    m = re.search(r"charset=([\w-]+)", ctype)
    try:
        return raw.decode(m.group(1) if m else "utf-8", "replace")
    except LookupError:
        return raw.decode("utf-8", "replace")


class _TextGrab(HTMLParser):
    """Keeps the readable paragraphs of a web page, drops menus, scripts, footers and adverts."""
    SKIP = {"script", "style", "noscript", "nav", "footer", "header", "aside", "form", "svg", "button", "select",
            "template", "iframe", "figure", "table"}
    BLOCK = {"p", "li", "h1", "h2", "h3", "h4", "dd", "dt", "blockquote", "div", "br", "section", "article", "td",
             "tr", "ul", "ol", "main"}

    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.skip, self.buf, self.out, self.title, self._in_title = 0, [], [], "", False

    def handle_starttag(self, tag, attrs):
        if tag in self.SKIP:
            self.skip += 1
        elif tag in self.BLOCK:
            self.flush()
        if tag == "title":
            self._in_title = True

    def handle_endtag(self, tag):
        if tag in self.SKIP:
            self.skip = max(0, self.skip - 1)
        elif tag in self.BLOCK:
            self.flush()
        if tag == "title":
            self._in_title = False

    def handle_data(self, d):
        if self._in_title:
            self.title += d
        elif not self.skip:
            self.buf.append(d)

    def flush(self):
        t = " ".join("".join(self.buf).split())
        self.buf = []
        if len(t) >= 70 and t.count(" ") >= 9 and not _JUNK.search(t[:160]):
            self.out.append(t)


def page_text(url, limit=7000):
    """(title, readable text) of a web page, or ('', '') if it can't be read."""
    if re.search(r"\.(pdf|jpe?g|png|gif|mp4|mp3|zip|exe)(\?|$)", url, re.I) or \
            re.search(r"(youtube\.com|youtu\.be|tiktok\.com|instagram\.com|facebook\.com|x\.com|twitter\.com)/", url):
        return "", ""
    try:
        html = _page_get(url)
    except Exception:
        return "", ""
    g = _TextGrab()
    try:
        g.feed(html)
        g.close()
    except Exception:
        pass
    text = " ".join(g.out)
    return " ".join(g.title.split())[:120], text[:limit]


def _unwrap_ddg(href):
    href = href.replace("&amp;", "&")
    if href.startswith("//"):
        href = "https:" + href
    q = urllib.parse.urlparse(href)
    if "duckduckgo.com" in q.netloc and q.path.startswith("/l/"):
        u = urllib.parse.parse_qs(q.query).get("uddg")
        if u:
            return u[0]
    return href


def _strip_tags(s):
    import html as _html
    return " ".join(_html.unescape(re.sub(r"<[^>]+>", " ", s or "")).split())


def _search_ddgs(q, n):
    from ddgs import DDGS                                   # optional: pip install ddgs
    res = DDGS(timeout=8).text(q, max_results=n, safesearch="moderate")
    return [{"title": r.get("title", ""), "url": r.get("href", ""), "snippet": r.get("body", "")}
            for r in (res or []) if r.get("href")]


def _search_ddg_html(q, n):
    html = _page_get(WEB["ddg_html"], data=urllib.parse.urlencode({"q": q, "kl": "wt-wt"}).encode())
    out = []
    for block in re.split(r'<div[^>]+class="[^"]*\bresult\b', html)[1:]:
        if "result--ad" in block[:200]:
            continue
        a = re.search(r'class="result__a"[^>]*href="([^"]+)"[^>]*>(.*?)</a>', block, re.S) or \
            re.search(r'href="([^"]+)"[^>]*class="result__a"[^>]*>(.*?)</a>', block, re.S)
        if not a:
            continue
        url = _unwrap_ddg(a.group(1))
        if "duckduckgo.com/y.js" in url:
            continue
        sn = re.search(r'class="result__snippet"[^>]*>(.*?)</(?:a|div|td)>', block, re.S)
        out.append({"title": _strip_tags(a.group(2)), "url": url, "snippet": _strip_tags(sn.group(1) if sn else "")})
        if len(out) >= n:
            break
    return out


def _search_bing_html(q, n):
    html = _page_get(WEB["bing"] + "?q=" + _q(q) + "&setlang=en")
    out = []
    for block in re.split(r'<li class="b_algo', html)[1:]:
        a = re.search(r'<h2[^>]*>\s*<a[^>]+href="(https?://[^"]+)"[^>]*>(.*?)</a>', block, re.S)
        if not a:
            continue
        sn = re.search(r"<p[^>]*>(.*?)</p>", block, re.S)
        out.append({"title": _strip_tags(a.group(2)), "url": a.group(1).replace("&amp;", "&"),
                    "snippet": _strip_tags(sn.group(1) if sn else "")})
        if len(out) >= n:
            break
    return out


def _search_wiki(q, n):
    j = http_json("%s?action=query&list=search&srsearch=%s&srlimit=%d&format=json" % (WEB["wiki_api"], _q(q), n), 8)
    return [{"title": h.get("title", ""), "url": "https://en.wikipedia.org/wiki/" + _q(h.get("title", "").replace(" ", "_")),
             "snippet": _strip_tags(h.get("snippet", ""))} for h in ((j.get("query") or {}).get("search") or [])]


def search_results(q, n=6):
    """[{title, url, snippet}], plus which engine answered. Tries each free engine in turn."""
    for name, fn in (("ddgs", _search_ddgs), ("DuckDuckGo", _search_ddg_html), ("Bing", _search_bing_html),
                     ("Wikipedia", _search_wiki)):
        try:
            res = [r for r in fn(q, n) if r.get("url", "").startswith("http")]
        except Exception:
            res = []
        if res:
            return res, name
    return [], ""


def ddg_instant(q):
    """DuckDuckGo's free instant answer (short facts, definitions), or None."""
    try:
        j = http_json("%s?q=%s&format=json&no_html=1&skip_disambig=1&t=zenko" % (WEB["ddg_api"], _q(q)), 6)
    except Exception:
        return None
    for key, src in (("Answer", "AbstractURL"), ("AbstractText", "AbstractURL"), ("Definition", "DefinitionURL")):
        txt = j.get(key)
        if isinstance(txt, str) and len(txt) > 3:
            return {"title": j.get("Heading") or j.get("AbstractSource") or "DuckDuckGo", "url": j.get(src) or "",
                    "text": txt}
    return None


def wiki_extract(topic):
    try:
        hits = _search_wiki(topic, 1)
        if not hits:
            return None
        s = http_json(WEB["wiki_sum"] + _q(hits[0]["title"].replace(" ", "_")), 8)
        if s.get("type") == "disambiguation" or not s.get("extract"):
            return None
        url = (((s.get("content_urls") or {}).get("desktop")) or {}).get("page") or hits[0]["url"]
        return {"title": s.get("title", hits[0]["title"]) + " (Wikipedia)", "url": url, "text": s["extract"]}
    except Exception:
        return None


def _sentences(text):
    parts = re.split(r"(?<=[.!?])\s+(?=[A-Z0-9\"“(])", text or "")
    return [p.strip() for p in parts if 35 <= len(p.strip()) <= 420 and not _JUNK.search(p)]


def summarise_extract(question, docs, n=3, limit=600):
    """Built-in summariser (no AI): scores each sentence by how much of your question it covers and how
    central it is to all the pages (the Luhn method), then keeps the best few, without repeats."""
    qt = set(_terms(question))
    cands, freq = [], {}
    for di, d in enumerate(docs):
        for si, s in enumerate(_sentences(d["text"])[:60]):
            ts = _terms(s)
            if len(ts) < 4:
                continue
            cands.append((di, si, s, ts))
            for w in set(ts):
                freq[w] = freq.get(w, 0) + 1
    if not cands:
        return ""
    top = max(freq.values())

    def score(c):
        di, si, s, ts = c
        st = set(ts)
        cover = len(qt & st) / float(len(qt)) if qt else 0.0
        central = sum(freq[w] for w in st) / (top * float(len(st)))
        lead = 0.35 if si == 0 else (0.15 if si < 3 else 0.0)
        defn = 0.3 if re.search(r"\b(is|are|was|were|refers to|means)\b", s[:80]) and si < 4 else 0.0
        return 2.2 * cover + central + lead + defn - 0.15 * di / max(1, len(docs))
    chosen, per_doc = [], {}
    for c in sorted(cands, key=score, reverse=True):
        if len(chosen) >= n or (chosen and sum(len(x[2]) for x in chosen) + len(c[2]) > limit + 120):
            break
        st = set(c[3])
        if per_doc.get(c[0], 0) >= 2:
            continue
        head = " ".join(c[2].lower().split()[:3])
        if any(len(st & set(x[3])) / float(len(st | set(x[3]))) > 0.35 or " ".join(x[2].lower().split()[:3]) == head
               for x in chosen):
            continue
        chosen.append(c)
        per_doc[c[0]] = per_doc.get(c[0], 0) + 1
    chosen.sort(key=lambda c: (c[0], c[1]))
    return " ".join(c[2] for c in chosen)


def summarise_llm(question, docs, model, style=""):
    """Ask the offline smart brain to answer from the pages it was given (and only from those)."""
    src, room = [], 5200
    for i, d in enumerate(docs[:5]):
        chunk = d["text"][:min(1600, room)]
        if not chunk:
            continue
        src.append("[%d] %s\n%s" % (i + 1, d["title"], chunk))
        room -= len(chunk)
        if room < 300:
            break
    sys_msg = ("You are Zenko, a friendly fox assistant. Answer the user's question using ONLY the web sources "
               "given. Plain text, at most 90 words, no lists unless needed, no links. If the sources don't answer "
               "it, say so honestly. Keep the facts exact; the fox voice is only a light touch. " + style)
    j = _ollama_json("/api/chat", {"model": model, "stream": False,
                                   "messages": [{"role": "system", "content": sys_msg},
                                                {"role": "user", "content": "Question: %s\n\nSources:\n%s" % (
                                                    question, "\n\n".join(src))}],
                                   "options": {"temperature": 0.2, "num_predict": 260}}, 150)
    return ((j.get("message") or {}).get("content") or "").strip()


def pick_model(names, wanted):
    if not names:
        return None
    if wanted in names:
        return wanted
    base = (wanted or "").split(":")[0]
    local = [n for n in names if "cloud" not in n] or names          # Ollama's cloud models need an account: stay local
    good = [n for n in local if n.split(":")[0] == base] or \
        [n for n in local if not re.search(r"vl|vision|llava|embed|moondream", n)] or local
    return good[0]


def research(query, question=None, model=None, style=""):
    """Search the web, read the best pages and summarise them. Returns (answer text, [sources])."""
    question = (question or query).strip()
    q = clean_query(query)
    docs = []
    inst = ddg_instant(q)
    if inst:
        docs.append(inst)
    results, engine = search_results(q)
    pages = []
    picks, seen = [], set()
    for r in results:
        host = urllib.parse.urlparse(r["url"]).netloc.replace("www.", "")
        if host in seen:
            continue
        seen.add(host)
        picks.append(r)
        if len(picks) >= 4:
            break
    if picks:
        import concurrent.futures as _cf
        with _cf.ThreadPoolExecutor(max_workers=4) as ex:
            got = list(ex.map(lambda r: page_text(r["url"]), picks))
        for r, (title, text) in zip(picks, got):
            if len(text) >= 300:
                pages.append({"title": r["title"] or title or r["url"], "url": r["url"], "text": text})
    docs += pages[:3]
    if not any("wikipedia.org" in d.get("url", "") for d in docs):
        w = wiki_extract(wiki_topic(q))
        if w and (set(_terms(w["text"][:400])) & set(_terms(q))):
            docs.append(w)
    snippets = " ".join(r["snippet"].rstrip(".") + "." for r in results[:6] if len(r.get("snippet", "")) > 40)
    if snippets:
        docs.append({"title": "search results (%s)" % engine, "url": "", "text": snippets})
    if not docs:
        raise WebError("I searched the web but couldn't find anything useful on that. Try different words?")
    answer = ""
    if model:
        try:
            answer = summarise_llm(question, docs, model, style)
        except Exception:
            answer = ""
    if not answer:
        answer = summarise_extract(question, docs) or _trim_sentences(docs[0]["text"], 3, 520)
    sources = [(d["title"], d["url"]) for d in docs if d.get("url")][:3]
    return answer, sources


def research_text(answer, sources, intro="Kon! Yatta, I found it~"):
    out = intro + "\n" + answer
    if sources:
        out += "\n\nSources:\n" + "\n".join("• %s - %s" % (clip(t, 60), u) for t, u in sources)
    return out


def _cur_code(s):
    s = s.strip().lower().rstrip(".")
    if s in CURRENCY_WORDS:
        return CURRENCY_WORDS[s]
    s2 = s.replace(" ", "")
    if re.fullmatch(r"[a-z]{3}", s2):
        return s2.upper()
    return CURRENCY_WORDS.get(s.split(" ")[0] if s else s)


def convert_text(amount, a, b):
    ca, cb = _cur_code(a), _cur_code(b)
    if not ca or not cb:
        raise WebError("I didn't recognise a currency. Use codes, e.g. 'convert 100 usd to xcd'.")
    j = http_json(WEB["rates"] + ca)
    if j.get("result") not in (None, "success") or not isinstance(j.get("rates"), dict) or cb not in j["rates"]:
        raise WebError("I couldn't get a rate for %s to %s." % (ca, cb))
    r = float(j["rates"][cb])
    when = str(j.get("time_last_update_utc", ""))[:16]
    return "%s %s = %s %s\n(1 %s = %.4g %s; daily rate%s. Rates by exchangerate-api.com)" % (
        ("%g" % amount), ca, "{:,.2f}".format(amount * r), cb, ca, r, cb, (", updated " + when) if when else "")


def web_route(text):
    """Return (kind, arg) when the text is an internet lookup request, else None. Typos are tolerated."""
    t = text.strip()
    low = t.lower()
    m = re.match(r"(?:what(?:'s|s| is)? )?(?:the )?(?:current |local )?time (?:is it )?in\s+(.+?)\s*\??$", low)
    if m:
        return ("time", t[m.start(1):m.end(1)])
    m = re.match(r"look\s*up\s+(.+)", low)
    if m:
        return ("search", t[m.start(1):])
    m = re.match(r"(?:convert\s+)?([\d,]*\.?\d+)\s*([a-z$ ]{1,22}?)\s+(?:to|in|into|=)\s+([a-z ]{2,22}?)\s*\??$", low)
    if m and (low.startswith("convert") or _cur_code(m.group(2)) and _cur_code(m.group(3))):
        try:
            return ("convert", (float(m.group(1).replace(",", "")), m.group(2), m.group(3)))
        except ValueError:
            pass
    toks = t.split()
    for i, w in enumerate(toks[:5]):
        key = WEB_KEYS.get(fix_word(w.strip("?,.!'\"")).lower())
        if key and all(x.lower().strip("?,.!") in WEB_FILLER for x in toks[:i]):
            rest = toks[i + 1:]
            while rest and rest[0].lower().strip("?,.") in WEB_LEAD:
                rest = rest[1:]
            arg = " ".join(rest).strip(" ?.!")
            arg = re.sub(r"\s+(today|tomorrow|now|right now|please)$", "", arg, flags=re.I)
            return (key, arg)
    return None


def looks_like_question(text):
    return bool(re.match(r"(who|what|when|where|why|how|which)\b.*|.*\?\s*$", text.strip(), re.I)) and len(text.split()) >= 2


OLLAMA = "http://127.0.0.1:11434"     # Ollama's local address: this PC only
_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))      # never go through a VPN/proxy


def _ollama_json(path, payload=None, timeout=3):
    if path == "/api/chat" and isinstance(payload, dict) and payload.pop("online", False) and online_ready():
        try:                                               # online brain first (switched on in Settings), the PC's models if it fails
            txt, srcs = online_chat(payload.get("messages") or [], json_mode=bool(payload.get("format")),
                                    max_tokens=int((payload.get("options") or {}).get("num_predict", 1000)) + 200,
                                    temperature=float((payload.get("options") or {}).get("temperature", 0.3)), timeout=min(120, timeout + 30))
            return {"message": {"role": "assistant", "content": txt}, "online": True, "sources": srcs}
        except Exception as ex:
            ONLINE["last_err"] = str(ex)
            if payload.get("model") == "online":
                raise
    if path == "/api/chat" and isinstance(payload, dict) and payload.get("messages") \
            and not any(m.get("images") for m in payload["messages"]):
        payload = dict(payload, messages=ib_msgs(payload["messages"]))     # IB DP terms for every local answer too
    data = json.dumps(payload).encode("utf-8") if payload is not None else None
    req = urllib.request.Request(OLLAMA + path, data=data, method="POST" if data else "GET",
                                 headers={"content-type": "application/json"})
    with _OPENER.open(req, timeout=timeout) as r:
        j = json.loads(r.read().decode("utf-8"))
    # newer Ollama "thinking" models (qwen3, deepseek-r1, gemma...) may put their reasoning in <think> tags: drop it
    try:
        msg = j.get("message") if isinstance(j, dict) else None
        if msg and isinstance(msg.get("content"), str):
            msg["content"] = _strip_think(msg["content"])
        if isinstance(j, dict) and isinstance(j.get("response"), str):
            j["response"] = _strip_think(j["response"])
    except Exception:
        pass
    return j


def _strip_think(t):
    t = re.sub(r"(?s)<think>.*?</think>", "", t)
    if "</think>" in t:
        t = t.split("</think>", 1)[1]
    return t.strip()


def ollama_models():
    """Installed model names, or None if Ollama isn't running."""
    try:
        return [m.get("name", "") for m in _ollama_json("/api/tags", None, 1.5).get("models", [])]
    except Exception:
        return None


def brain_names():
    """Like ollama_models(), but when the online brain is ready and Ollama is off it still says 'there is a brain'."""
    names = ollama_models()
    if online_ready() and not names:
        return ["online"]
    return names


