def json_latex_fix(raw):
    """Small models write LaTeX inside JSON with single backslashes (like frac or sqrt). Double the ones that are not
    real JSON escapes, and the \f \b \t \n \r ones that are clearly the start of a LaTeX command."""
    latexy = re.compile(r"(?:frac|beta|b?inom|times|theta|text|tan\b|tau\b|to\b|triangle|therefore|tilde|nabla|neq|ne\b|"
                        r"nu\b|not|newline|rightarrow|rho\b|right\b|rangle|f\b|forall|bar|big|boxed|bf\b)")

    def fix(m):
        if m.group(0) == "\\\\":
            return m.group(0)
        c = m.group(1)
        if c in '"/u\\':
            return m.group(0)
        if c == "'":
            return "'"
        if c in "bfnrt" and not latexy.match(raw, m.start() + 1):
            return m.group(0)
        return "\\\\" + c
    return re.sub(r"\\\\|\\(.)", fix, raw or "", flags=re.S)


def parse_brain(raw):
    try:
        d = json.loads(json_latex_fix(raw))
    except Exception:
        m = re.search(r"\{.*\}", raw or "", re.S)
        try:
            d = json.loads(json_latex_fix(m.group(0))) if m else None
        except Exception:
            d = None
    if not isinstance(d, dict):
        d = {"action": "chat", "args": {}, "reply": (raw or "").strip() or "..."}
    return d


def pdf_esc(t):
    t = (t or "").encode("latin-1", "replace").decode("latin-1")
    return t.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def make_timetable_pdf(path, title, rows):
    """Black-and-white, 3:4 page (same shape as the reMarkable screen). rows = [(time, task, minutes, done)]."""
    W, H, per = 504, 672, 10
    chunks = [rows[i:i + per] for i in range(0, len(rows), per)] or [[]]
    objs = [None, None, b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
            b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>"]
    kids = []
    for pi, chunk in enumerate(chunks):
        ops = []

        def text(x, y, size, t, bold=False):
            ops.append("BT /%s %d Tf %d %d Td (%s) Tj ET" % ("F2" if bold else "F1", size, x, y, pdf_esc(t)))
        text(36, 626, 20, title + ("  (page %d)" % (pi + 1) if len(chunks) > 1 else ""), True)
        ops.append("1.5 w 36 614 m 468 614 l S")
        y = 580
        for (tm, task, mn, done) in chunk:
            ops.append("1.2 w 36 %d 18 18 re S" % (y - 2))
            if done:
                ops.append("2 w 39 %d m 44 %d l 52 %d l S" % (y + 6, y + 1, y + 13))
            text(66, y + 2, 16, tm, True)
            text(122, y + 2, 15, task[:34])
            text(122, y - 12, 9, "%d min" % mn)
            ops.append("0.4 w 36 %d m 468 %d l S" % (y - 22, y - 22))
            y -= 46
        text(36, 112, 11, "Notes", True)
        for i in range(5):
            ops.append("0.4 w 36 %d m 468 %d l S" % (92 - i * 18, 92 - i * 18))
        content = "\n".join(ops).encode("latin-1", "replace")
        objs.append(b"<< /Length %d >>\nstream\n" % len(content) + content + b"\nendstream")
        cobj = len(objs)
        objs.append(("<< /Type /Page /Parent 2 0 R /MediaBox [0 0 %d %d] /Resources << /Font << /F1 3 0 R "
                     "/F2 4 0 R >> >> /Contents %d 0 R >>" % (W, H, cobj)).encode())
        kids.append(len(objs))
    objs[0] = b"<< /Type /Catalog /Pages 2 0 R >>"
    objs[1] = ("<< /Type /Pages /Kids [%s] /Count %d >>" % (" ".join("%d 0 R" % k for k in kids), len(kids))).encode()
    out = bytearray(b"%PDF-1.4\n")
    offs = []
    for i, o in enumerate(objs):
        offs.append(len(out))
        out += b"%d 0 obj\n" % (i + 1) + o + b"\nendobj\n"
    xref = len(out)
    out += b"xref\n0 %d\n0000000000 65535 f \n" % (len(objs) + 1)
    for o in offs:
        out += b"%010d 00000 n \n" % o
    out += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (len(objs) + 1, xref)
    with open(path, "wb") as f:
        f.write(out)


def mins(seconds):
    return max(1, int(round(seconds / 60.0)))


def clip(text, n):
    return text if len(text) <= n else text[: n - 1] + "…"


