def _hex_rgb(h):
    h = h.lstrip("#")
    return int(h[0:2], 16), int(h[2:4], 16), int(h[4:6], 16)


def _box_down(px, n):
    """Shrink a square RGBA picture to n x n by averaging (smooth small icons)."""
    g = len(px)
    out = []
    for y in range(n):
        y0, y1 = y * g // n, max(y * g // n + 1, (y + 1) * g // n)
        row = []
        for x in range(n):
            x0, x1 = x * g // n, max(x * g // n + 1, (x + 1) * g // n)
            acc, cnt = [0, 0, 0, 0], 0
            for yy in range(y0, y1):
                for xx in range(x0, x1):
                    r, gg, b, a = px[yy][xx]
                    acc[0] += r * a
                    acc[1] += gg * a
                    acc[2] += b * a
                    acc[3] += a
                    cnt += 1
            a = acc[3]
            row.append((acc[0] // a, acc[1] // a, acc[2] // a, a // cnt) if a else (0, 0, 0, 0))
        out.append(row)
    return out


def icon_pixels(n=64, theme="snow"):
    """n x n list of (r,g,b,a): Zenko's face on a night-sky tile with a gold rim."""
    pal = FUR.get(theme) or SNOW_PAL
    th = THEMES.get(theme) or THEMES["snow"]
    top, bot = _hex_rgb(th["night"]), _hex_rgb(_mixhex(th["night"], th["acc"], 0.45))
    gold = _hex_rgb(th["gold"])
    g = 64
    px = [[(0, 0, 0, 0)] * g for _ in range(g)]
    r = 13
    for y in range(g):
        for x in range(g):
            dx = max(r - x, 0, x - (g - 1 - r))
            dy = max(r - y, 0, y - (g - 1 - r))
            d2 = dx * dx + dy * dy
            if d2 <= r * r:
                t = y / float(g - 1)
                c = tuple(int(top[i] + (bot[i] - top[i]) * t) for i in range(3))
                if d2 > (r - 2) * (r - 2) and (dx or dy) or x in (0, 1, g - 1, g - 2) or y in (0, 1, g - 1, g - 2):
                    c = gold
                elif ((x * 37 + y * 91) ^ (x * y)) % 61 == 0 and y < 34:
                    c = (255, 255, 230)
                px[y][x] = (c[0], c[1], c[2], 255)
    layers = [build_tails(3, 0, shadow=False), build_frame("happy", "up", 1)]
    ox, oy = -4, 8
    for rows in layers:
        for y, row in enumerate(rows):
            for x, ch in enumerate(row):
                col = pal.get(ch)
                X, Y = ox + x, oy + y
                if col and ch not in "gYV" and 2 <= X < g - 2 and 2 <= Y < g - 2 and px[Y][X][3]:
                    rr, gg, bb = _hex_rgb(col)
                    px[Y][X] = (rr, gg, bb, 255)
    if n == g:
        return px
    if n > g:
        return [[px[min(g - 1, y * g // n)][min(g - 1, x * g // n)] for x in range(n)] for y in range(n)]
    return _box_down(px, n)


def _png(px, level=9):
    import zlib, struct
    h, w = len(px), len(px[0])
    raw = b"".join(b"\x00" + b"".join(bytes(p) for p in row) for row in px)

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 6, 0, 0, 0)) + \
        chunk(b"IDAT", zlib.compress(raw, level)) + chunk(b"IEND", b"")


def _cov(d):
    """Edge coverage from a signed distance (inside > 0): a one-pixel soft edge = anti-aliasing."""
    return 0.0 if d <= -0.5 else (1.0 if d >= 0.5 else d + 0.5)


def _poly_d(pts, x, y):
    """Signed distance to a polygon (inside > 0)."""
    inside = False
    best = 1e9
    n = len(pts)
    j = n - 1
    for i in range(n):
        (xi, yi), (xj, yj) = pts[i], pts[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-9) + xi:
            inside = not inside
        dx, dy = xj - xi, yj - yi
        L = dx * dx + dy * dy or 1e-9
        t = max(0.0, min(1.0, ((x - xi) * dx + (y - yi) * dy) / L))
        best = min(best, math.hypot(x - xi - t * dx, y - yi - t * dy))
        j = i
    return best if inside else -best


def _shape_d(sh, x, y):
    k = sh[0]
    if k == "circle":                                  # ("circle", cx, cy, r, colour)
        return sh[3] - math.hypot(x - sh[1], y - sh[2])
    if k == "ring":                                    # ("ring", cx, cy, r, width, colour)
        d = math.hypot(x - sh[1], y - sh[2])
        return min(sh[3] - d, d - (sh[3] - sh[4]))
    if k == "poly":                                    # ("poly", [(x, y)...], colour)
        return _poly_d(sh[1], x, y)
    if k == "rrect":                                   # ("rrect", x1, y1, x2, y2, r, colour)
        x1, y1, x2, y2, r = sh[1:6]
        cx, cy = (x1 + x2) / 2.0, (y1 + y2) / 2.0
        qx, qy = abs(x - cx) - ((x2 - x1) / 2.0 - r), abs(y - cy) - ((y2 - y1) / 2.0 - r)
        out = math.hypot(max(qx, 0), max(qy, 0)) + min(max(qx, qy), 0)
        return r - out
    return -1.0


def _bbox(sh):
    k = sh[0]
    if k in ("circle", "ring"):
        return sh[1] - sh[3] - 1, sh[2] - sh[3] - 1, sh[1] + sh[3] + 1, sh[2] + sh[3] + 1
    if k == "poly":
        xs, ys = [p[0] for p in sh[1]], [p[1] for p in sh[1]]
        return min(xs) - 1, min(ys) - 1, max(xs) + 1, max(ys) + 1
    if k == "rrect":
        return sh[1] - 1, sh[2] - 1, sh[3] + 1, sh[4] + 1
    return 0, 0, 0, 0


def aa_pixels(w, h, shapes, bg=None):
    """Draw simple shapes with smooth (anti-aliased) edges into a w x h RGBA picture.
    A shape's colour is '#rrggbb' or ('#rrggbb', alpha 0..1); colour None erases (cuts a hole)."""
    px = [[(bg[0], bg[1], bg[2], 1.0) if bg else (0, 0, 0, 0.0) for _ in range(w)] for _ in range(h)]
    for sh in shapes:
        col = sh[-1]
        a0 = 1.0
        if isinstance(col, tuple):
            col, a0 = col
        rgb = _hex_rgb(col) if col else None
        bx1, by1, bx2, by2 = _bbox(sh)
        for y in range(max(0, int(by1)), min(h, int(by2) + 2)):
            row = px[y]
            for x in range(max(0, int(bx1)), min(w, int(bx2) + 2)):
                c = _cov(_shape_d(sh, x + 0.5, y + 0.5)) * a0
                if c <= 0:
                    continue
                r, g, b, a = row[x]
                if rgb is None:
                    row[x] = (r, g, b, a * (1 - c))
                    continue
                na = c + a * (1 - c)
                if na <= 0:
                    continue
                row[x] = ((rgb[0] * c + r * a * (1 - c)) / na, (rgb[1] * c + g * a * (1 - c)) / na,
                          (rgb[2] * c + b * a * (1 - c)) / na, na)
    return [[(int(r), int(g), int(b), int(round(a * 255))) for (r, g, b, a) in row] for row in px]


def aa_png(w, h, shapes, bg=None):
    return _png(aa_pixels(w, h, shapes, bg), 6)


def aa_photo(w, h, shapes, bg=None):
    """A smooth Tk image (PNG with real alpha) from simple shapes."""
    return tk.PhotoImage(data=base64.b64encode(aa_png(w, h, shapes, bg)))


def seigaiha_photo(w, h, top, bottom, line, r=14, fade=True):
    """Smooth seigaiha (blue-ocean wave) pattern over a vertical gradient, fading out to the left."""
    return tk.PhotoImage(data=base64.b64encode(seigaiha_png(w, h, top, bottom, line, r, fade)))


def seigaiha_png(w, h, top, bottom, line, r=14, fade=True):
    t_rgb, b_rgb, l_rgb = _hex_rgb(top), _hex_rgb(bottom), _hex_rgb(line)
    dy = r // 2
    rows = []
    for y in range(h):
        t = y / float(max(1, h - 1))
        base = tuple(t_rgb[k] + (b_rgb[k] - t_rgb[k]) * t for k in range(3))
        out = []
        for x in range(w):
            col = base
            fx, fy = x + 0.5, y + 0.5
            best = None                                   # lower rows overlap upper ones, so the last hit wins
            k0 = int(fy // dy)
            for row in range(k0, k0 + r // dy + 2):
                cy = row * dy
                if cy < fy - 0.5:
                    continue
                off = r if row % 2 else 0
                cx = round((fx - off) / (2.0 * r)) * 2 * r + off
                d = math.hypot(fx - cx, fy - cy)
                if d <= r + 0.5:
                    best = (cx, cy, d)
            if best:
                d = best[2]
                a = 0.0
                for rr in (r - 1.0, r - 5.0, r - 9.0):
                    a = max(a, _cov(0.75 - abs(d - rr)))
                k = a * (min(1.0, x / (w * 0.55)) if fade else 1.0)
                col = tuple(col[i] + (l_rgb[i] - col[i]) * k for i in range(3))
            out.append((int(col[0]), int(col[1]), int(col[2]), 255))
        rows.append(out)
    return _png(rows, 6)


def icon_png(size=64, theme="snow"):
    """PNG bytes, crisp pixel art scaled up by whole steps."""
    base = icon_pixels(64, theme)
    k = max(1, size // 64)
    px = [[p for p in row for _ in range(k)] for row in base for _ in range(k)]
    return _png(px)


_RGB = {}


def sprite_png(layers, pal, bg=None):
    """Palette-letter grids (drawn in order) -> PNG bytes with real transparency (cached by the zenko20 art cache)."""
    h, w = len(layers[0]), len(layers[0][0])
    clear = (0, 0, 0, 0) if bg is None else _hex_rgb(bg) + (255,)
    px = [[clear] * w for _ in range(h)]
    for rows in layers:
        for y, row in enumerate(rows):
            line = px[y]
            for x, ch in enumerate(row):
                if ch != ".":
                    col = pal.get(ch)
                    if col:
                        rgb = _RGB.get(col)
                        if rgb is None:
                            rgb = _RGB[col] = _hex_rgb(col) + (255,)
                        line[x] = rgb
    return _png(px, 1)


def sprite_photo(layers, pal, zoom=1, bg=None):
    """Palette-letter grids (drawn in order) -> a Tk PhotoImage with real transparency, zoomed by whole steps."""
    img = tk.PhotoImage(data=base64.b64encode(sprite_png(layers, pal, bg)))
    return img.zoom(zoom, zoom) if zoom > 1 else img


def write_ico(path, theme="snow"):
    import struct
    sizes = [16, 24, 32, 48, 64, 256]
    imgs = []
    for s in sizes:
        if s == 256:
            base = icon_pixels(64, theme)
            px = [[base[y // 4][x // 4] for x in range(256)] for y in range(256)]
            imgs.append((256, _png(px)))
        else:
            px = icon_pixels(s, theme)
            body = bytearray()
            for row in reversed(px):                               # BMP is bottom-up, BGRA
                for (r, g, b, a) in row:
                    body += bytes((b, g, r, a))
            mask_row = ((s + 31) // 32) * 4
            mask = bytes(mask_row * s)
            hdr = struct.pack("<IiiHHIIiiII", 40, s, s * 2, 1, 32, 0, len(body) + len(mask), 0, 0, 0, 0)
            imgs.append((s, hdr + bytes(body) + mask))
    out = bytearray(struct.pack("<HHH", 0, 1, len(imgs)))
    off = 6 + 16 * len(imgs)
    for s, data in imgs:
        out += struct.pack("<BBBBHHII", s % 256, s % 256, 0, 0, 1, 32, len(data), off)
        off += len(data)
    for s, data in imgs:
        out += data
    with open(path, "wb") as f:
        f.write(out)


