import base64 as _b64
import hashlib
import secrets
import subprocess
import shutil
import zipfile

NO_WINDOW = 0x08000000 if IS_WIN else 0      # CREATE_NO_WINDOW: helper processes stay invisible


def popen_hidden(args, **kw):
    return subprocess.Popen(args, creationflags=NO_WINDOW, **kw)


def run_hidden(args, timeout=60, **kw):
    return subprocess.run(args, creationflags=NO_WINDOW, capture_output=True, timeout=timeout, **kw)


def system_python():
    """A real python.exe (even when Zenko runs as a built .exe), or None."""
    if not getattr(sys, "frozen", False) and sys.executable and os.path.basename(sys.executable).lower().startswith("python"):
        exe = sys.executable
        if exe.lower().endswith("pythonw.exe"):
            exe2 = exe[:-11] + "python.exe"
            if os.path.exists(exe2):
                return exe2
        return exe
    for name in ("python", "py", "python3"):
        p = shutil.which(name)
        if p and "windowsapps" not in p.lower():
            return p
    return None


def _ext_dir(*parts):
    p = os.path.join(DATA_DIR, *parts)
    os.makedirs(p, exist_ok=True)
    return p


