MED_PROMPT = ("Pathology, histology, glomerulonephritis, nephrotic, nephritic, creatinine, BUN, USMLE, "
              "renal, hepatic, neoplasia, timetable, Zenko, Spotify, reMarkable.")


_WHISPER_OK = {"t": 0.0, "ok": False}


def whisper_ready():
    """Is the Python Whisper engine (faster-whisper) installed? Checked at most every 10 minutes (it's slow)."""
    if time.monotonic() - _WHISPER_OK["t"] < 600 and _WHISPER_OK["t"]:
        return _WHISPER_OK["ok"]
    py = system_python()
    ok = False
    if py:
        try:
            r = run_hidden([py, "-c", "import faster_whisper, sounddevice, numpy"], timeout=40)
            ok = r.returncode == 0
        except Exception:
            ok = False
    _WHISPER_OK.update(t=time.monotonic(), ok=ok)
    return ok


class VoiceEngine:
    """Background speech-to-text helper. Results arrive on self.q as ("text"|"status"|"error", value)."""

    def __init__(self):
        self.q = queue.Queue()
        self.proc = None
        self.kind = None
        self.ready = False
        self.listening = False

    def alive(self):
        return self.proc is not None and self.proc.poll() is None

    def start(self, prefer="auto", model="base.en"):
        if self.alive():
            return True
        try:
            if prefer in ("auto", "whisper") and whisper_ready():
                path = os.path.join(_ext_dir("helpers"), "whisper_worker.py")
                with open(path, "w", encoding="utf-8") as f:
                    f.write(WHISPER_WORKER)
                self.proc = popen_hidden([system_python(), path, model, MED_PROMPT], stdin=subprocess.PIPE,
                                         stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True, bufsize=1)
                self.kind = "whisper"
            elif IS_WIN:
                path = os.path.join(_ext_dir("helpers"), "winspeech.ps1")
                with open(path, "w", encoding="utf-8") as f:
                    f.write(WINSPEECH_WORKER)
                self.proc = popen_hidden(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", path],
                                         stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                                         text=True, bufsize=1)
                self.kind = "windows"
            else:
                self.q.put(("error", "Voice needs Windows, or the free Whisper engine (Settings > Voice)."))
                return False
        except Exception as e:
            self.q.put(("error", "Couldn't start voice (%s)." % e))
            return False
        self.ready = False
        threading.Thread(target=self._reader, daemon=True).start()
        return True

    def _reader(self):
        p = self.proc
        try:
            for line in p.stdout:
                line = line.strip()
                if not line:
                    continue
                try:
                    d = json.loads(line)
                except Exception:
                    continue
                if d.get("ready"):
                    self.ready = True
                    self.q.put(("status", "ready"))
                elif d.get("listening"):
                    self.q.put(("status", "listening"))
                elif d.get("cancelled"):
                    self.listening = False
                    self.q.put(("status", "cancelled"))
                elif "text" in d:
                    self.listening = False
                    self.q.put(("text", d.get("text") or ""))
                elif d.get("error"):
                    self.q.put(("error", d["error"]))
        except Exception:
            pass
        self.listening = False
        self.q.put(("status", "stopped"))

    def send(self, cmd):
        try:
            self.proc.stdin.write(cmd + "\n")
            self.proc.stdin.flush()
            return True
        except Exception:
            return False

    def press(self):
        """Start listening. Whisper records until release(); Windows speech stops by itself at a pause."""
        if not self.alive() or self.listening:
            return False
        self.listening = True
        return self.send("start")

    def release(self):
        if self.kind == "whisper" and self.listening:
            self.send("stop")

    def cancel(self):
        if self.kind == "whisper" and self.listening:
            self.send("cancel")

    def stop(self):
        if self.alive():
            self.send("quit")
            try:
                self.proc.terminate()
            except Exception:
                pass
        self.proc = None


