# Free, offline, natural-sounding voices (Piper). About 60 MB each, downloaded the first time you pick one.
PIPER_VOICES = [("Alan (British, male)", "en_GB-alan-medium"),
                ("Jenny (British, female)", "en_GB-jenny_dioco-medium"),
                ("Alba (Scottish, female)", "en_GB-alba-medium"),
                ("Northern English (male)", "en_GB-northern_english_male-medium"),
                ("Amy (American, female)", "en_US-amy-medium"),
                ("Lessac (American, female)", "en_US-lessac-medium"),
                ("Ryan (American, male)", "en_US-ryan-medium")]
VOICE_DIR = os.path.join(DATA_DIR, "voices")


# --- Windows' own speech engine (SAPI), used directly: no PowerShell, works on locked-down PCs too ---
_SAPI = {"CLSID_SpVoice": "{96749377-3391-11D2-9EE3-00C04F797396}",
         "IID_ISpVoice": "{6C44DF74-72B9-4992-A1EC-EF996E0422D4}",
         "CLSID_Cat": "{A910187F-0C7A-45AC-92CC-59EDAFB77B53}",
         "IID_Cat": "{2D3D3845-39AF-4850-BBF9-40B49780011D}"}
VOICE_KEYS = [r"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Speech\Voices",
              r"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Speech_OneCore\Voices"]


class _GUID(ctypes.Structure):
    _fields_ = [("a", ctypes.c_ulong), ("b", ctypes.c_ushort), ("c", ctypes.c_ushort), ("d", ctypes.c_ubyte * 8)]


def _guid(text):
    g = _GUID()
    hr = ctypes.windll.ole32.CLSIDFromString(ctypes.c_wchar_p(text), ctypes.byref(g))
    if hr:
        raise OSError("bad GUID %s" % text)
    return g


def _vt(obj, idx, argtypes, *args):
    """Call method number idx of a COM object."""
    vtbl = ctypes.cast(obj, ctypes.POINTER(ctypes.POINTER(ctypes.c_void_p)))[0]
    fn = ctypes.WINFUNCTYPE(ctypes.c_long, ctypes.c_void_p, *argtypes)(vtbl[idx])
    return fn(obj, *args)


def _release(obj):
    try:
        if obj:
            _vt(obj, 2, [])
    except Exception:
        pass


def _create(clsid, iid):
    obj = ctypes.c_void_p()
    hr = ctypes.windll.ole32.CoCreateInstance(ctypes.byref(_guid(clsid)), None, 1 | 4,
                                              ctypes.byref(_guid(iid)), ctypes.byref(obj))
    if hr or not obj:
        raise OSError("CoCreateInstance failed 0x%08X" % (hr & 0xFFFFFFFF))
    return obj


def _sapi_tokens():
    """[(name, token_pointer)] for every voice Windows has (SAPI + newer 'OneCore' voices). Caller releases."""
    out, seen = [], set()
    for key in VOICE_KEYS:
        cat = None
        try:
            cat = _create(_SAPI["CLSID_Cat"], _SAPI["IID_Cat"])
            if _vt(cat, 15, [ctypes.c_wchar_p, ctypes.c_int], key, 0):                 # SetId
                continue
            enum = ctypes.c_void_p()
            if _vt(cat, 18, [ctypes.c_wchar_p, ctypes.c_wchar_p, ctypes.POINTER(ctypes.c_void_p)],
                   None, None, ctypes.byref(enum)) or not enum:                          # EnumTokens
                continue
            while True:
                tok, got = ctypes.c_void_p(), ctypes.c_ulong()
                if _vt(enum, 3, [ctypes.c_ulong, ctypes.POINTER(ctypes.c_void_p), ctypes.POINTER(ctypes.c_ulong)],
                       1, ctypes.byref(tok), ctypes.byref(got)) or not got.value:        # Next
                    break
                pname = ctypes.c_wchar_p()
                name = ""
                if not _vt(tok, 6, [ctypes.c_wchar_p, ctypes.POINTER(ctypes.c_wchar_p)], None, ctypes.byref(pname)):
                    name = pname.value or ""                                              # GetStringValue(default)
                    ctypes.windll.ole32.CoTaskMemFree(pname)
                short = name.split(" - ")[0].strip()
                if short and short.lower() not in seen:
                    seen.add(short.lower())
                    out.append((short, tok))
                else:
                    _release(tok)
            _release(enum)
        except Exception:
            pass
        finally:
            _release(cat)
    return out


def windows_voices():
    if not IS_WIN:
        return []
    try:
        ctypes.windll.ole32.CoInitializeEx(None, 0)
        toks = _sapi_tokens()
        names = [n for n, _ in toks]
        for _, t in toks:
            _release(t)
        return names
    except Exception:
        return []


class SapiVoice:
    """Speaks with Windows' built-in voices from a background thread, straight through the speech engine."""

    def __init__(self, name="", rate=0):
        self.q = queue.Queue()
        self.error = None
        self.ready = threading.Event()
        self.alive = True
        self.stdin = self
        threading.Thread(target=self._run, args=(name, rate), daemon=True).start()
        self.ready.wait(8)
        if not self.ready.is_set():
            self.error = self.error or "Windows speech didn't start in time."
        if self.error:
            self.alive = False
            raise OSError(self.error)

    def _run(self, name, rate):
        voice = None
        try:
            ctypes.windll.ole32.CoInitializeEx(None, 0)
            voice = _create(_SAPI["CLSID_SpVoice"], _SAPI["IID_ISpVoice"])
            if name:
                toks = _sapi_tokens()
                pick = [t for n, t in toks if n.lower() == name.lower()] or \
                       [t for n, t in toks if name.lower() in n.lower()]
                if pick:
                    _vt(voice, 18, [ctypes.c_void_p], pick[0])                       # SetVoice
                for _, t in toks:
                    _release(t)
            _vt(voice, 28, [ctypes.c_long], max(-10, min(10, int(rate))))             # SetRate
        except Exception as e:
            self.error = "Windows speech isn't available on this PC (%s)." % e
            self.ready.set()
            _release(voice)
            return
        self.ready.set()
        spk = [ctypes.c_wchar_p, ctypes.c_ulong, ctypes.POINTER(ctypes.c_ulong)]
        while True:
            item = self.q.get()
            if item is None:
                break
            try:
                if item == "__STOP__":
                    _vt(voice, 20, spk, "", 1 | 2, None)                                # purge
                else:
                    hr = _vt(voice, 20, spk, item, 1 | 2 | (8 if item.startswith("<") else 0), None)   # async + purge (+XML)
                    if hr < 0:
                        self.error = "Windows couldn't speak (error 0x%08X)." % (hr & 0xFFFFFFFF)
            except Exception as e:
                self.error = "Windows couldn't speak (%s)." % e
        _release(voice)
        self.alive = False

    # looks like a subprocess to the Speaker class
    def write(self, line):
        line = line.strip()
        if line:
            self.q.put(line)

    def flush(self):
        pass

    def poll(self):
        return None if self.alive and not self.error else 1

    def terminate(self):
        self.q.put(None)


def piper_ready():
    py = system_python()
    if not py:
        return False
    try:
        return run_hidden([py, "-c", "import piper"], timeout=40).returncode == 0
    except Exception:
        return False


class Speaker:
    """The fox's voice. 'win:<name>' = a voice built into Windows; 'piper:<id>' = a free natural voice."""

    def __init__(self):
        self.proc = None
        self.key = None
        self.status = ""

    def _start(self, voice, speed):
        self.stop()
        speed = max(-3, min(3, int(speed)))
        if voice.startswith("piper:"):
            py = system_python()
            if not py:
                raise RuntimeError("Python not found")
            path = os.path.join(_ext_dir("helpers"), "piper_worker.py")
            with open(path, "w", encoding="utf-8") as f:
                f.write(PIPER_WORKER)
            os.makedirs(VOICE_DIR, exist_ok=True)
            ls = "%.2f" % (1.0 / (1.0 + 0.12 * speed))
            self.proc = popen_hidden([py, path, voice[6:], VOICE_DIR, ls], stdin=subprocess.PIPE,
                                     stdout=subprocess.PIPE, stderr=self._log(), text=True, bufsize=1)
            self.status = "loading"

            def watch(p=self.proc):
                try:
                    for line in p.stdout:
                        self.status = {"DOWNLOADING": "downloading", "READY": "ready"}.get(line.strip(), self.status)
                except Exception:
                    pass
                if self.status != "ready":
                    self.status = "failed"
            threading.Thread(target=watch, daemon=True).start()
        else:
            name = voice[4:] if voice.startswith("win:") else ""
            try:
                self.proc = SapiVoice(name, speed * 2)
                self.status = "ready"
                self.key = (voice, speed)
                return
            except OSError as e:
                self.sapi_error = str(e)                 # fall back to PowerShell below
            path = os.path.join(_ext_dir("helpers"), "tts.ps1")
            with open(path, "w", encoding="utf-8") as f:
                f.write(TTS_WORKER)
            env = dict(os.environ, KX_VOICE=name, KX_RATE=str(speed * 2))
            self.proc = popen_hidden(["powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-File", path],
                                     stdin=subprocess.PIPE, stdout=subprocess.DEVNULL, stderr=self._log(),
                                     text=True, bufsize=1, env=env)
            self.status = "ready"
        self.key = (voice, speed)

    LOG = os.path.join(DATA_DIR, "helpers", "voice_log.txt")

    def _log(self):
        try:
            _ext_dir("helpers")
            return open(self.LOG, "w", encoding="utf-8", errors="replace")
        except OSError:
            return subprocess.DEVNULL

    sapi_error = ""

    def problem(self):
        """A plain-English reason the voice isn't working, or '' if it seems fine."""
        if not IS_WIN:
            return "Talking only works on Windows."
        if isinstance(self.proc, SapiVoice):
            return self.proc.error or ""
        if self.proc is None:
            return "The voice helper couldn't start." + (" " + self.sapi_error if self.sapi_error else "")
        if self.proc.poll() is not None or self.status == "failed":
            try:
                with open(self.LOG, encoding="utf-8", errors="replace") as f:
                    lines = [x.strip() for x in f.read().splitlines() if x.strip()]
            except OSError:
                lines = []
            last = lines[-1][:180] if lines else "no details"
            if "VOICE_DOWNLOAD_BLOCKED" in last:
                return ("Couldn't download that natural voice (the network may be blocking it). "
                        "Try again at home, or pick a Windows voice.")
            if "piper" in last.lower() and "module" in last.lower():
                return "Natural voices aren't installed. Press 'Install natural voices', or pick a Windows voice."
            return "The voice helper stopped (%s)." % last
        return ""

    def say(self, text, voice="", speed=0, pitch=0):
        if not IS_WIN or not text:
            return
        try:
            if self.proc is None or self.proc.poll() is not None or self.key != (voice, int(speed)):
                self._start(voice, speed)
            clean = re.sub(r"https?://\S+", "", text)
            clean = re.sub(r"[\r\n•]+", ". ", clean)[:600]
            if pitch and isinstance(self.proc, SapiVoice):
                esc = clean.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                clean = '<pitch absmiddle="%d">%s</pitch>' % (max(0, min(10, int(pitch))), esc)
            self.proc.stdin.write(clean + "\n")
            self.proc.stdin.flush()
        except Exception:
            self.proc = None

    def hush(self):
        try:
            if self.proc and self.proc.poll() is None:
                self.proc.stdin.write("__STOP__\n")
                self.proc.stdin.flush()
        except Exception:
            pass

    def stop(self):
        try:
            if self.proc:
                self.proc.terminate()
        except Exception:
            pass
        self.proc = None
        self.key = None

    restart = stop


def key_down(vk):
    if not IS_WIN:
        return False
    try:
        return bool(user32.GetAsyncKeyState(vk) & 0x8000)
    except Exception:
        return False


HOTKEYS = {"F6": 0x75, "F7": 0x76, "F8": 0x77, "F9": 0x78, "F10": 0x79, "F11": 0x7A, "F12": 0x7B,
           "Right Ctrl": 0xA3, "Right Alt": 0xA5, "Pause": 0x13, "Scroll Lock": 0x91}


# ---------- Spotify (uses your own Premium account; nothing else involved) -----------
SPOTIFY = {"auth": "https://accounts.spotify.com/authorize", "token": "https://accounts.spotify.com/api/token",
           "api": "https://api.spotify.com/v1"}
if os.environ.get("FOX_SPOTIFY_BASE"):                  # testing hook
    _sb = os.environ["FOX_SPOTIFY_BASE"].rstrip("/")
    SPOTIFY = {"auth": _sb + "/authorize", "token": _sb + "/api/token", "api": _sb + "/v1"}
SPOTIFY_PORT = 8765
SPOTIFY_REDIRECT = "http://127.0.0.1:%d/callback" % SPOTIFY_PORT
SPOTIFY_SCOPES = ("user-read-playback-state user-modify-playback-state user-read-currently-playing "
                  "playlist-read-private playlist-read-collaborative user-library-read user-library-modify")
SPOTIFY_TOKEN_PATH = os.path.join(DATA_DIR, "spotify_token.json")


class SpotifyError(Exception):
    pass


class Spotify:
    def __init__(self, client_id=""):
        self.client_id = client_id.strip()
        self.tok = None
        try:
            with open(SPOTIFY_TOKEN_PATH, encoding="utf-8") as f:
                self.tok = json.load(f)
        except Exception:
            self.tok = None
        self.lock = threading.RLock()

    def connected(self):
        return bool(self.tok and self.tok.get("refresh_token"))

    def _save(self):
        try:
            os.makedirs(DATA_DIR, exist_ok=True)
            with open(SPOTIFY_TOKEN_PATH, "w", encoding="utf-8") as f:
                json.dump(self.tok, f)
        except Exception:
            pass

    def forget(self):
        self.tok = None
        try:
            os.remove(SPOTIFY_TOKEN_PATH)
        except OSError:
            pass

    def _post_token(self, fields):
        data = urllib.parse.urlencode(fields).encode()
        req = urllib.request.Request(SPOTIFY["token"], data=data,
                                     headers={"Content-Type": "application/x-www-form-urlencoded"})
        try:
            with urllib.request.urlopen(req, timeout=15) as r:
                return json.loads(r.read().decode())
        except urllib.error.HTTPError as e:
            try:
                msg = json.loads(e.read().decode()).get("error_description", "")
            except Exception:
                msg = ""
            raise SpotifyError("Spotify refused the sign-in (%s %s). Check the Client ID and Redirect URI." % (e.code, msg))
        except Exception:
            raise SpotifyError("Couldn't reach Spotify. Check your internet/VPN.")

    def login(self, open_browser=True, timeout=180):
        """PKCE sign-in: opens your browser, catches the reply on 127.0.0.1. Blocking; run in a thread."""
        import http.server
        if not self.client_id:
            raise SpotifyError("Paste your Spotify Client ID in Settings first.")
        verifier = secrets.token_urlsafe(64)[:100]
        challenge = _b64.urlsafe_b64encode(hashlib.sha256(verifier.encode()).digest()).decode().rstrip("=")
        state = secrets.token_urlsafe(12)
        url = SPOTIFY["auth"] + "?" + urllib.parse.urlencode({
            "client_id": self.client_id, "response_type": "code", "redirect_uri": SPOTIFY_REDIRECT,
            "code_challenge_method": "S256", "code_challenge": challenge, "scope": SPOTIFY_SCOPES, "state": state})
        got = {}

        class H(http.server.BaseHTTPRequestHandler):
            def log_message(self, *a):
                pass

            def do_GET(self):
                q = urllib.parse.parse_qs(urllib.parse.urlparse(self.path).query)
                if not urllib.parse.urlparse(self.path).path.startswith("/callback"):
                    self.send_response(404)
                    self.end_headers()
                    return
                got["code"] = (q.get("code") or [None])[0]
                got["state"] = (q.get("state") or [None])[0]
                got["error"] = (q.get("error") or [None])[0]
                ok = bool(got["code"]) and got["state"] == state
                body = ("<html><body style='font-family:Segoe UI;background:#26304a;color:white;text-align:center;"
                        "padding-top:80px'><h2>%s</h2><p>You can close this tab and go back to Zenko.</p>"
                        "</body></html>") % ("Zenko is connected to Spotify!" if ok else "Sign-in was cancelled.")
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.end_headers()
                self.wfile.write(body.encode())
        try:
            srv = http.server.HTTPServer(("127.0.0.1", SPOTIFY_PORT), H)
        except OSError:
            raise SpotifyError("Port %d is busy. Close other Zenko windows and try again." % SPOTIFY_PORT)
        srv.timeout = 1
        if open_browser:
            webbrowser.open(url)
        end = time.time() + timeout
        try:
            while not got and time.time() < end:
                srv.handle_request()
        finally:
            srv.server_close()
        if not got.get("code") or got.get("state") != state:
            raise SpotifyError("Spotify sign-in didn't finish (%s)." % (got.get("error") or "timed out"))
        t = self._post_token({"grant_type": "authorization_code", "code": got["code"], "redirect_uri": SPOTIFY_REDIRECT,
                              "client_id": self.client_id, "code_verifier": verifier})
        t["expires_at"] = time.time() + int(t.get("expires_in", 3600)) - 60
        self.tok = t
        self._save()
        return url

    def _token(self):
        if not self.connected():
            raise SpotifyError("Spotify isn't connected yet (Settings > Spotify > Connect).")
        if time.time() >= self.tok.get("expires_at", 0):
            t = self._post_token({"grant_type": "refresh_token", "refresh_token": self.tok["refresh_token"],
                                  "client_id": self.client_id})
            self.tok["access_token"] = t["access_token"]
            if t.get("refresh_token"):
                self.tok["refresh_token"] = t["refresh_token"]
            self.tok["expires_at"] = time.time() + int(t.get("expires_in", 3600)) - 60
            self._save()
        return self.tok["access_token"]

    def api(self, method, path, params=None, body=None, retry=True):
        with self.lock:
            url = SPOTIFY["api"] + path + (("?" + urllib.parse.urlencode(params)) if params else "")
            data = json.dumps(body).encode() if body is not None else (b"" if method in ("PUT", "POST") else None)
            req = urllib.request.Request(url, data=data, method=method,
                                         headers={"Authorization": "Bearer " + self._token(),
                                                  "Content-Type": "application/json"})
            try:
                with urllib.request.urlopen(req, timeout=12) as r:
                    raw = r.read()
                    return json.loads(raw.decode()) if raw.strip() else None
            except urllib.error.HTTPError as e:
                try:
                    err = json.loads(e.read().decode()).get("error", {})
                except Exception:
                    err = {}
                reason = err.get("reason", "") if isinstance(err, dict) else ""
                if e.code == 401 and retry:
                    self.tok["expires_at"] = 0
                    return self.api(method, path, params, body, False)
                if e.code == 404 and ("NO_ACTIVE_DEVICE" in reason or "device" in str(err).lower()):
                    raise SpotifyError("NO_DEVICE")
                if e.code == 403:
                    m = (err.get("message", "") if isinstance(err, dict) else "") or reason
                    raise SpotifyError("SPOTIFY_403:" + m)
                if e.code == 429:
                    raise SpotifyError("Spotify asked me to slow down. Try again in a minute.")
                raise SpotifyError("Spotify error %s %s" % (e.code, (err.get("message", "") if isinstance(err, dict) else "")))
            except SpotifyError:
                raise
            except Exception:
                raise SpotifyError("Couldn't reach Spotify. Check your internet/VPN.")

    def call(self, method, path, params=None, body=None):
        """Like api() but wakes up a device (your PC's Spotify app) if nothing is playing anywhere."""
        try:
            return self.api(method, path, params, body)
        except SpotifyError as e:
            if str(e) != "NO_DEVICE":
                raise
        devs = (self.api("GET", "/me/player/devices") or {}).get("devices") or []
        if not devs and IS_WIN:
            try:
                os.startfile("spotify:")                          # open the Spotify app, then wait for it
            except OSError:
                pass
            for _ in range(10):
                time.sleep(1.5)
                devs = (self.api("GET", "/me/player/devices") or {}).get("devices") or []
                if devs:
                    break
        if not devs:
            raise SpotifyError("No Spotify device is open. Open the Spotify app on this PC (or your phone) once, then try again.")
        pick = sorted(devs, key=lambda d: (d.get("type") != "Computer", not d.get("is_active")))[0]
        self.api("PUT", "/me/player", body={"device_ids": [pick["id"]], "play": False})
        time.sleep(0.6)
        return self.api(method, path, params, body)

    # -- friendly actions (return a sentence) --
    def now(self):
        d = self.api("GET", "/me/player")
        if not d or not d.get("item"):
            return None
        it = d["item"]
        people = it.get("artists") or ([it["show"]] if it.get("show") else [])
        artists = ", ".join(a.get("name", "") for a in people)
        return {"title": it.get("name", ""), "artist": artists, "playing": bool(d.get("is_playing")),
                "uri": it.get("uri"), "volume": (d.get("device") or {}).get("volume_percent"),
                "shuffle": d.get("shuffle_state"), "progress": d.get("progress_ms", 0), "duration": it.get("duration_ms", 1)}

    def play_query(self, q):
        q = q.strip()
        want_pl = bool(re.search(r"\bplaylist\b", q, re.I))
        q2 = re.sub(r"\b(my|the|playlist|some|music|songs?)\b", " ", q, flags=re.I).strip()
        if q2:
            try:
                pls = (self.api("GET", "/me/playlists", {"limit": 50}) or {}).get("items") or []
            except SpotifyError:
                pls = []
            best, score = None, 0.0
            for p in pls:
                if not p:
                    continue
                s = difflib.SequenceMatcher(None, q2.lower(), (p.get("name") or "").lower()).ratio()
                if q2.lower() in (p.get("name") or "").lower():
                    s += 0.5
                if s > score:
                    best, score = p, s
            if best and (score >= 0.75 or (want_pl and score >= 0.45)):
                self.call("PUT", "/me/player/play", body={"context_uri": best["uri"]})
                return "Playing your playlist “%s”." % best.get("name")
        if not q2:
            self.call("PUT", "/me/player/play")
            return "Music on."
        kind = "playlist" if want_pl else "track"
        res = self.api("GET", "/search", {"q": q2, "type": kind, "limit": 5}) or {}
        items = [i for i in ((res.get(kind + "s") or {}).get("items") or []) if i]
        if not items:
            return "I couldn't find “%s” on Spotify." % q2
        it = items[0]
        if kind == "playlist":
            self.call("PUT", "/me/player/play", body={"context_uri": it["uri"]})
            return "Playing the playlist “%s”." % it.get("name")
        self.call("PUT", "/me/player/play", body={"uris": [it["uri"]]})
        return "Playing “%s” by %s." % (it.get("name"), ", ".join(a["name"] for a in it.get("artists", [])))

    def do(self, action, arg=None):
        try:
            return self._do(action, arg)
        except SpotifyError as e:
            if not str(e).startswith("SPOTIFY_403"):
                raise
            detail = str(e).split(":", 1)[1].strip()
            n = None
            try:
                n = self.now()
            except SpotifyError:
                pass
            if action == "pause" and (not n or not n["playing"]):
                return "The music is already paused."
            if action == "play" and not arg and n and n["playing"]:
                return "It's already playing: “%s”." % n["title"]
            raise SpotifyError("Spotify wouldn't do that right now%s. If the music is on another device "
                               "(phone, speaker), control it there or switch it to this PC." %
                               (" (%s)" % detail if detail else ""))

    def _do(self, action, arg=None):
        if action == "play":
            return self.play_query(arg) if arg else (self.call("PUT", "/me/player/play") or "Music on.")
        if action == "pause":
            self.call("PUT", "/me/player/pause")
            return "Music paused."
        if action == "next":
            self.call("POST", "/me/player/next")
            return "Skipped."
        if action == "previous":
            self.call("POST", "/me/player/previous")
            return "Back one song."
        if action == "volume":
            v = max(0, min(100, int(arg)))
            self.call("PUT", "/me/player/volume", {"volume_percent": v})
            return "Volume %d%%." % v
        if action == "shuffle":
            self.call("PUT", "/me/player/shuffle", {"state": "true" if arg else "false"})
            return "Shuffle %s." % ("on" if arg else "off")
        if action == "like":
            n = self.now()
            if not n:
                return "Nothing is playing."
            self.api("PUT", "/me/library", {"uris": n["uri"]})
            return "Saved “%s” to your library." % n["title"]
        if action == "now":
            n = self.now()
            if not n:
                return "Nothing is playing on Spotify right now."
            return "%s “%s” by %s." % ("Now playing:" if n["playing"] else "Paused:", n["title"], n["artist"])
        return "I don't know that music command."


def spotify_route(text, _typo_pass=False):
    """('play'|'pause'|..., arg) for music commands, else None. Spelling mistakes are tolerated."""
    t = text.strip()
    low = t.lower().strip(" .!?")
    if not _typo_pass:
        r = _spotify_route(t, low)
        if r:
            return r
        fixed = fix_typos(t)
        if fixed.lower() == t.lower():
            return None
        r = _spotify_route(fixed.strip(), fixed.lower().strip(" .!?"))
        if r and r[0] == "play" and r[1]:            # keep what to play exactly as typed
            parts = t.split(None, 1)
            r = ("play", parts[1] if len(parts) > 1 else "")
        return r
    return _spotify_route(t, low)


def _spotify_route(t, low):
    if re.match(r"^(?:what'?s|whats|what is|what|wat)(?: is)?(?: \w+)? (?:playing|this song|the song|on spotify)"
                r"|^(?:which|what) song|^(?:now|currently) playing|^current song|^what music", low):
        return ("now", None)
    if re.match(r"^(?:stop|pause) (?:playing|the music|music|the song|song|spotify)$", low):
        return ("pause", None)
    m = re.match(r"^(?:play|paly|plya|ply|put on|spotify play|start music|play music)(?:\s+(.+))?$", low)
    if m and not re.match(r"^play\s*(time|date)\b", low):
        arg = t[len(t) - len(m.group(1)):] if m.group(1) else ""
        return ("play", arg.strip())
    if re.match(r"^(?:pause|stop) (?:the )?(?:music|song|spotify)$|^(?:music|spotify) (?:pause|stop|off)$", low):
        return ("pause", None)
    if re.match(r"^(?:resume|unpause) (?:the )?(?:music|song|spotify)$|^(?:music|spotify) (?:on|resume|play)$", low):
        return ("play", "")
    if re.match(r"^(?:skip|next song|next track|skip (?:this )?(?:song|track)|skip it)$", low):
        return ("next", None)
    if re.match(r"^(?:previous|last|prev|back) (?:song|track)$|^go back a song$", low):
        return ("previous", None)
    m = re.match(r"^(?:set )?(?:the )?volume(?: to)? (\d{1,3})%?$|^(?:spotify|music) volume (\d{1,3})%?$", low)
    if m:
        return ("volume", int(m.group(1) or m.group(2)))
    if re.match(r"^(?:volume|music) (?:up|louder)$|^louder$", low):
        return ("volume_rel", 15)
    if re.match(r"^(?:volume|music) (?:down|quieter|softer)$|^quieter$", low):
        return ("volume_rel", -15)
    m = re.match(r"^shuffle (on|off)$", low)
    if m:
        return ("shuffle", m.group(1) == "on")
    if re.match(r"^(?:like|save|heart) (?:this|the) (?:song|track)$|^i like this song$", low):
        return ("like", None)
    return None


