def rm_tool():
    if os.path.exists(RM_TOOL):
        if IS_WIN:
            try:
                with open(RM_TOOL, "rb") as f:
                    head = f.read(4096)
                if not _check_windows_exe(head):
                    os.remove(RM_TOOL)                   # a wrong (Mac/Linux) download from an older version
                    return shutil.which("rmapi")
            except OSError:
                pass
        return RM_TOOL
    w = shutil.which("rmapi")
    return w


def _ps_get(url, out_path=None, timeout=180):
    """Download with Windows' own networking (uses the system proxy/VPN and certificate store)."""
    if not IS_WIN:
        raise RMError("no powershell")
    cmd = ("[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12; "
           "$ProgressPreference='SilentlyContinue'; ")
    if out_path:
        cmd += "Invoke-WebRequest -UseBasicParsing -Uri '%s' -OutFile '%s'" % (url, out_path.replace("'", "''"))
    else:
        cmd += "(Invoke-WebRequest -UseBasicParsing -Uri '%s').Content" % url
    r = run_hidden(["powershell", "-NoProfile", "-Command", cmd], timeout=timeout)
    if r.returncode != 0:
        raise RMError(((r.stderr or b"").decode("utf-8", "replace").strip().splitlines() or ["download failed"])[0][:160])
    return r.stdout


def _check_windows_exe(data):
    """True if these bytes are a Windows program this PC can run (64-bit Intel/AMD, or ARM64)."""
    if data[:2] != b"MZ" or len(data) < 0x40:
        return False
    import struct
    off = struct.unpack_from("<I", data, 0x3C)[0]
    if data[off:off + 4] != b"PE\0\0":
        return False
    machine = struct.unpack_from("<H", data, off + 4)[0]
    return machine in (0x8664, 0x14C, 0xAA64)


def rm_install_from_file(path):
    """Use an rmapi.exe (or the .zip it comes in) that you downloaded yourself."""
    os.makedirs(RM_DIR, exist_ok=True)
    if path.lower().endswith(".zip"):
        z = zipfile.ZipFile(path)
        exe = [n for n in z.namelist() if os.path.basename(n).lower() == ("rmapi.exe" if IS_WIN else "rmapi")]
        if not exe:
            raise RMError("That zip isn't the Windows version (no rmapi.exe inside). On the GitHub page, download "
                          "the file whose name has 'windows' in it - not 'darwin' (Mac) or 'linux'.")
        data = z.read(exe[0])
    else:
        with open(path, "rb") as f:
            data = f.read()
    if IS_WIN and not _check_windows_exe(data):
        raise RMError("That file isn't a Windows program. Download the one with 'windows' in its name "
                      "(not 'darwin' = Mac, not 'linux').")
    with open(RM_TOOL, "wb") as f:
        f.write(data)
    if not IS_WIN:
        os.chmod(RM_TOOL, 0o755)
    return True


def rm_install_tool():
    """Download the latest Windows build of rmapi (free, open source) into Zenko's folder."""
    os.makedirs(RM_DIR, exist_ok=True)
    errors = []
    rel = None
    try:
        rel = http_json(RM_RELEASES, 20)
    except Exception as e:
        errors.append(str(e))
        try:
            rel = json.loads(_ps_get(RM_RELEASES).decode("utf-8", "replace"))
        except Exception as e2:
            errors.append(str(e2))
    if not rel:
        raise RMError("I couldn't reach GitHub to download the helper. Use 'Download manually' instead "
                      "(details: %s)" % " / ".join(errors)[:200])
    assets = rel.get("assets") or []
    want = "windows" if IS_WIN else ("linux" if sys.platform.startswith("linux") else "mac")

    def score(a):
        n = a.get("name", "").lower()
        if "darwin" in n or "macos" in n or (IS_WIN and "linux" in n):
            return -10                                   # "darwin" (Mac) contains "win": never pick it
        is_os = (want in n) or (IS_WIN and re.search(r"(^|[-_.])win(64|32|dows)?([-_.]|$)", n) is not None)
        return is_os * 4 + ("amd64" in n or "x86_64" in n or "x64" in n) * 2 + \
            n.endswith((".zip", ".exe", ".tar.gz")) * 1 - ("arm" in n) * 3
    assets = sorted(assets, key=score, reverse=True)
    if not assets or score(assets[0]) < 4:
        raise RMError("I couldn't find a Windows download of rmapi. Use 'Download manually' instead.")
    a = assets[0]
    tmp = os.path.join(RM_DIR, a["name"])
    try:
        with open(tmp, "wb") as f:
            f.write(http_get(a["browser_download_url"], 120))
    except Exception:
        try:
            _ps_get(a["browser_download_url"], tmp, 300)
        except Exception as e:
            raise RMError("The download was blocked (%s). Use 'Download manually' instead." % str(e)[:120])
    name = a["name"].lower()
    if name.endswith(".tar.gz"):
        import tarfile
        tf = tarfile.open(tmp)
        m = [x for x in tf.getmembers() if os.path.basename(x.name) == "rmapi"]
        if not m:
            raise RMError("The rmapi download didn't contain rmapi.")
        with open(RM_TOOL, "wb") as f:
            f.write(tf.extractfile(m[0]).read())
        if not IS_WIN:
            os.chmod(RM_TOOL, 0o755)
    else:
        rm_install_from_file(tmp)
    try:
        os.remove(tmp)
    except OSError:
        pass
    return rel.get("tag_name", "")


def rm_run(args, code=None, timeout=90, cwd=None):
    tool = rm_tool()
    if not tool:
        raise RMError("rmapi isn't installed yet (Notes > Set up).")
    env = dict(os.environ, RMAPI_CONFIG=RM_CONF)
    try:
        r = subprocess.run([tool] + args, input=(code + "\n") if code else "", capture_output=True, text=True,
                           timeout=timeout, env=env, cwd=cwd or RM_DIR, creationflags=NO_WINDOW)
    except OSError as e:
        if getattr(e, "winerror", None) in (193, 216) or "not compatible" in str(e) or "not a valid" in str(e):
            try:
                os.remove(tool)
            except OSError:
                pass
            raise RMError("The helper was the wrong version for Windows, so I removed it. "
                          "Press Download again (fixed now), or Download manually.")
        raise RMError("Couldn't start the helper (%s)." % e)
    except subprocess.TimeoutExpired:
        raise RMError("reMarkable didn't answer in time. Check your internet and try again.")
    out = (r.stdout or "") + (r.stderr or "")
    if "one-time code" in out.lower() and not code:
        raise RMError("NEED_CODE")
    if r.returncode != 0:
        msg = out.strip().splitlines()[-1] if out.strip() else "unknown error"
        raise RMError("reMarkable: " + msg[:160])
    return r.stdout or ""


def rm_paired():
    return os.path.exists(RM_CONF) and os.path.getsize(RM_CONF) > 20


def rm_pair(code):
    code = re.sub(r"\s", "", code or "")
    if len(code) < 6:
        raise RMError("That code looks too short. Get a fresh one at my.remarkable.com/device/desktop/connect")
    rm_run(["ls"], code=code, timeout=120)
    return True


def rm_ls(path="/"):
    out = rm_run(["ls", path])
    items = []
    for line in out.splitlines():
        m = re.match(r"\s*\[(d|f)\]\s+(.*\S)\s*$", line)
        if m:
            items.append((m.group(1), m.group(2)))
    return sorted(items, key=lambda x: (x[0] != "d", x[1].lower()))


def rm_safe(name):
    return re.sub(r'[\\/:*?"<>|]+', "_", name).strip() or "note"


def rm_download(path):
    """Fetch one document as .rmdoc into the notes folder; returns the local file path."""
    os.makedirs(RM_NOTES, exist_ok=True)
    tmp = os.path.join(RM_NOTES, "_dl")
    shutil.rmtree(tmp, ignore_errors=True)
    os.makedirs(tmp)
    rm_run(["get", path], timeout=180, cwd=tmp)
    files = [os.path.join(tmp, f) for f in os.listdir(tmp)]
    if not files:
        raise RMError("Nothing was downloaded for “%s”." % path)
    src = max(files, key=os.path.getsize)
    dst = os.path.join(RM_NOTES, rm_safe(path.strip("/").replace("/", " - ")) + os.path.splitext(src)[1])
    shutil.move(src, dst)
    shutil.rmtree(tmp, ignore_errors=True)
    return dst


def rm_pages(doc_path):
    """[(page_index, rm_bytes)] from a .rmdoc/.zip in reading order, plus any typed/PDF info."""
    z = zipfile.ZipFile(doc_path)
    names = z.namelist()
    content = [n for n in names if n.endswith(".content")]
    order = []
    if content:
        try:
            c = json.loads(z.read(content[0]).decode("utf-8"))
            if isinstance(c.get("cPages"), dict):
                pg = [p for p in c["cPages"].get("pages", []) if not p.get("deleted")]
                pg.sort(key=lambda p: ((p.get("idx") or {}).get("value", "")))
                order = [p.get("id") for p in pg]
            elif isinstance(c.get("pages"), list):
                order = list(c["pages"])
        except Exception:
            order = []
    rms = {os.path.splitext(os.path.basename(n))[0]: n for n in names if n.endswith(".rm")}
    seq = [rms[i] for i in order if i in rms] + sorted(n for k, n in rms.items() if k not in order)
    return [(i, z.read(n)) for i, n in enumerate(seq)]


def rm_page_content(rm_bytes):
    """(typed_text, strokes) for one page. strokes = [[(x, y, width), ...], ...]. Needs the small 'rmscene' package."""
    import io
    try:
        import rmscene
        from rmscene import scene_items as si
    except ImportError:
        raise RMError("NEED_RMSCENE")
    typed, strokes = [], []
    try:
        blocks = list(rmscene.read_blocks(io.BytesIO(rm_bytes)))
    except Exception:
        return "", []
    for b in blocks:
        name = type(b).__name__
        if name == "SceneLineItemBlock":
            line = getattr(getattr(b, "item", None), "value", None)
            if isinstance(line, si.Line) and line.points and getattr(line, "tool", None) not in (
                    getattr(si.Pen, "ERASER", None), getattr(si.Pen, "ERASER_AREA", None)):
                strokes.append([(p.x, p.y, max(1.0, p.width / 4.0)) for p in line.points])
    try:
        tree = rmscene.read_tree(io.BytesIO(rm_bytes))
        if tree.root_text is not None:
            from rmscene.text import TextDocument
            doc = TextDocument.from_scene_item(tree.root_text)
            for p in doc.contents:
                s = "".join(str(x) for x in p.contents).strip()
                if s:
                    typed.append(s)
    except Exception:
        pass
    return "\n".join(typed), strokes


def render_strokes_png(strokes, max_w=900):
    """Draw handwriting strokes in black on white and return PNG bytes (no extra libraries)."""
    pts = [(x, y) for s in strokes for (x, y, w) in s]
    if not pts:
        return None
    x0, x1 = min(p[0] for p in pts), max(p[0] for p in pts)
    y0, y1 = min(p[1] for p in pts), max(p[1] for p in pts)
    pad = 20
    sc = min(1.0, (max_w - 2 * pad) / max(1.0, x1 - x0))
    W = int((x1 - x0) * sc) + 2 * pad
    H = int((y1 - y0) * sc) + 2 * pad
    H = min(H, 3000)
    buf = bytearray(b"\xff" * (W * H))

    def dot(cx, cy, r):
        ri = int(r)
        for yy in range(max(0, int(cy) - ri), min(H, int(cy) + ri + 1)):
            row = yy * W
            for xx in range(max(0, int(cx) - ri), min(W, int(cx) + ri + 1)):
                buf[row + xx] = 0
    for s in strokes:
        prev = None
        for (x, y, w) in s:
            px, py = (x - x0) * sc + pad, (y - y0) * sc + pad
            r = max(0.8, min(3.0, w * sc * 0.5))
            if prev:
                dx, dy = px - prev[0], py - prev[1]
                n = int(max(abs(dx), abs(dy))) + 1
                for k in range(n):
                    dot(prev[0] + dx * k / n, prev[1] + dy * k / n, r)
            else:
                dot(px, py, r)
            prev = (px, py)
    import zlib
    import struct
    raw = b"".join(b"\x00" + bytes(buf[y * W:(y + 1) * W]) for y in range(H))

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", W, H, 8, 0, 0, 0, 0)) + \
        chunk(b"IDAT", zlib.compress(raw, 6)) + chunk(b"IEND", b"")


def ollama_vision(prompt, png_list, model, timeout=240, system=None, fmt=None):
    names = ollama_models()
    if names is None:
        raise RMError("NO_OLLAMA")
    if model not in names:
        base = model.split(":")[0]
        cand = [n for n in names if n.split(":")[0] == base]
        if not cand:
            alt = pick_vision(names, "")
            if not alt:
                raise RMError("NO_VISION:" + model)
            cand = [alt]
        model = cand[0]
    msgs = []
    if system:
        msgs.append({"role": "system", "content": system})
    msgs.append({"role": "user", "content": prompt, "images": [_b64.b64encode(p).decode() for p in png_list]})
    payload = {"model": model, "messages": msgs, "stream": False, "options": {"temperature": 0.1, "num_predict": 700}}
    if fmt:
        payload["format"] = fmt
    j = _ollama_json("/api/chat", payload, timeout)
    return (j.get("message") or {}).get("content", "").strip()


def rm_read_doc(doc_path, vision_model, progress=None):
    """Typed text straight from the file + handwriting read by the local vision model. Returns markdown."""
    pages = rm_pages(doc_path)
    out = []
    for i, data in pages:
        typed, strokes = rm_page_content(data)
        part = []
        if typed:
            part.append(typed)
        if strokes:
            png = render_strokes_png(strokes)
            if png:
                if progress:
                    progress("Reading handwriting, page %d of %d..." % (i + 1, len(pages)))
                try:
                    txt = ollama_vision("Transcribe ALL the handwriting in this image exactly, keeping line breaks. "
                                        "Medical/pathology terms are likely. Output only the text.", [png], vision_model)
                except RMError as e:
                    if str(e) == "NO_OLLAMA":
                        txt = "[handwriting not read: Ollama isn't running]"
                    elif str(e).startswith("NO_VISION"):
                        txt = "[handwriting not read: run  ollama pull %s]" % vision_model
                    else:
                        raise
                part.append(txt)
        if part:
            out.append("## Page %d\n\n%s" % (i + 1, "\n\n".join(part)))
    return "\n\n".join(out) or "(No writing found in this notebook.)"


def notes_index():
    """{name: path_to_md} of notebooks already read."""
    res = {}
    if os.path.isdir(RM_NOTES):
        for f in os.listdir(RM_NOTES):
            if f.endswith(".md"):
                res[f[:-3]] = os.path.join(RM_NOTES, f)
    return res


def notes_find(query):
    idx = notes_index()
    if not idx:
        return None, None
    q = query.lower().strip()
    best, sc = None, 0.0
    for name, path in idx.items():
        s = difflib.SequenceMatcher(None, q, name.lower()).ratio() + (0.6 if q and q in name.lower() else 0)
        try:
            with open(path, encoding="utf-8") as f:
                body = f.read()
        except OSError:
            body = ""
        if q and q in body.lower():
            s += 0.3
        if s > sc:
            best, sc = (name, path), s
    return best if sc > 0.45 else (None, None)


# ---------- "look at my screen" --------------------------------------------------
def grab_screen_png(max_w=1280):
    """Screenshot of the main screen, scaled down, as (png_bytes, (img_w, img_h), (screen_w, screen_h)). Windows only."""
    if not IS_WIN:
        raise RuntimeError("Screen reading works on Windows.")
    import ctypes.wintypes as wt
    gdi = ctypes.windll.gdi32
    u = ctypes.windll.user32
    sw, sh = u.GetSystemMetrics(0), u.GetSystemMetrics(1)
    sc = min(1.0, max_w / float(sw))
    w, h = int(sw * sc), int(sh * sc)
    hdc = u.GetDC(0)
    mdc = gdi.CreateCompatibleDC(hdc)
    bmp = gdi.CreateCompatibleBitmap(hdc, w, h)
    old = gdi.SelectObject(mdc, bmp)
    gdi.SetStretchBltMode(mdc, 4)                        # HALFTONE: smooth downscale
    gdi.SetBrushOrgEx(mdc, 0, 0, None)
    gdi.StretchBlt(mdc, 0, 0, w, h, hdc, 0, 0, sw, sh, 0x00CC0020)

    class BIH(ctypes.Structure):
        _fields_ = [("biSize", wt.DWORD), ("biWidth", wt.LONG), ("biHeight", wt.LONG), ("biPlanes", wt.WORD),
                    ("biBitCount", wt.WORD), ("biCompression", wt.DWORD), ("biSizeImage", wt.DWORD),
                    ("biXPelsPerMeter", wt.LONG), ("biYPelsPerMeter", wt.LONG), ("biClrUsed", wt.DWORD),
                    ("biClrImportant", wt.DWORD)]
    bi = BIH(ctypes.sizeof(BIH), w, -h, 1, 32, 0, 0, 0, 0, 0, 0)
    buf = ctypes.create_string_buffer(w * h * 4)
    gdi.GetDIBits(mdc, bmp, 0, h, buf, ctypes.byref(bi), 0)
    gdi.SelectObject(mdc, old)
    gdi.DeleteObject(bmp)
    gdi.DeleteDC(mdc)
    u.ReleaseDC(0, hdc)
    bgra = buf.raw
    rgb = bytearray(w * h * 3)
    rgb[0::3] = bgra[2::4]
    rgb[1::3] = bgra[1::4]
    rgb[2::3] = bgra[0::4]
    import zlib
    import struct
    stride = w * 3
    raw = b"".join(b"\x00" + bytes(rgb[y * stride:(y + 1) * stride]) for y in range(h))

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)) + \
        chunk(b"IDAT", zlib.compress(raw, 3)) + chunk(b"IEND", b"")
    return png, (w, h), (sw, sh)


SCREEN_PROMPT = ("You are Zenko, a friendly zenko (one of Inari's kind messenger foxes) and study buddy looking at the user's screen (a %dx%d screenshot). "
                 "%s Answer their question about what is on screen clearly and briefly "
                 "(at most 4 sentences, plain text). If your answer is about one particular spot on the screen "
                 "(a button, word, image region...), give its centre in pixel coordinates of this screenshot. "
                 'Reply with ONLY JSON: {"answer": "...", "point": [x, y] or null, "label": "2-4 word name of that spot or empty"}')


def screen_route(text):
    low = text.lower().strip()
    m = re.match(r"^(?:look at|check|read|see|scan) (?:my |the |this )?screen[,:\s]*(.*)$|^(?:what'?s|whats|what is) on (?:my |the )?screen\??\s*(.*)$|^screen[,:]\s*(.+)$|^(?:explain|what is|what's) (?:this|that)(?: on (?:my|the) screen)?\??$|^where (?:do i|should i) click.*$|^point (?:at|to) (.+)$", low)
    if not m:
        return None
    q = next((g for g in m.groups() if g), "") if m.groups() else ""
    return q.strip() or text.strip()



