DEADLINES_PATH = os.path.join(DATA_DIR, "deadlines.json")
MONTHS = {m: i + 1 for i, m in enumerate(["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"])}
_MON = r"(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)"
_DAYW = r"(?:(?:mon|tue|tues|wed|thu|thur|thurs|fri|sat|sun)(?:day|nesday|sday|urday)?,?\s+)?"
DEADLINE_WORDS = {"exam": "Exam", "test": "Exam", "quiz": "Quiz", "midterm": "Exam", "final": "Exam", "shelf": "Exam",
                  "nbme": "Exam", "usmle": "Exam", "osce": "Exam", "viva": "Exam", "assignment": "Assignment",
                  "essay": "Assignment", "report": "Assignment", "submit": "Deadline", "submission": "Deadline",
                  "due": "Deadline", "deadline": "Deadline", "presentation": "Presentation", "project": "Project",
                  "meeting": "Event", "lecture": "Class", "class": "Class", "interview": "Event"}


def load_deadlines():
    try:
        with open(DEADLINES_PATH, encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, list) else []
    except Exception:
        return []


def save_deadlines(items):
    os.makedirs(DATA_DIR, exist_ok=True)
    items.sort(key=lambda d: (d.get("date", "9999"), d.get("time") or "99:99"))
    tmp = DEADLINES_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(items, f, indent=1)
    os.replace(tmp, DEADLINES_PATH)


def guess_kind(title):
    low = title.lower()
    for w, k in DEADLINE_WORDS.items():
        if re.search(r"\b" + w, low):
            return k
    return "Deadline"


def _mk_date(y, m, d):
    try:
        return datetime.date(int(y), int(m), int(d))
    except (ValueError, TypeError):
        return None


def _future_year(m, d, today):
    """No year given: the next time this day comes round (a few weeks back still counts as this year)."""
    dt = _mk_date(today.year, m, d)
    if dt and dt < today - datetime.timedelta(days=45):
        dt = _mk_date(today.year + 1, m, d)
    return dt


def find_dates(line, today=None, day_first=True):
    """[(date, start, end)] for every date written in a line of text."""
    today = today or datetime.date.today()
    out = []
    for m in re.finditer(r"\b(20\d\d)[-/.](\d{1,2})[-/.](\d{1,2})\b", line):
        d = _mk_date(m.group(1), m.group(2), m.group(3))
        if d:
            out.append((d, m.start(), m.end()))
    for m in re.finditer(r"\b(\d{1,2})[/.-](\d{1,2})(?:[/.-](\d{2,4}))?\b", line):
        if any(s <= m.start() < e for _, s, e in out):
            continue
        a, b, y = int(m.group(1)), int(m.group(2)), m.group(3)
        if not y and (m.group(0).count(".") or a > 31 or b > 31):
            continue                                            # "3.5" is a number, not a date
        day, mon = (a, b) if day_first else (b, a)
        if mon > 12 and day <= 12:
            day, mon = mon, day
        if y:
            yy = int(y) + (2000 if len(y) == 2 else 0)
            d = _mk_date(yy, mon, day)
        else:
            d = _future_year(mon, day, today)
        if d:
            out.append((d, m.start(), m.end()))
    pats = [r"\b" + _DAYW + r"(\d{1,2})(?:st|nd|rd|th)?\s+(?:of\s+)?" + _MON + r"\.?,?(?:\s+(20\d\d))?\b",
            r"\b" + _DAYW + _MON + r"\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?(?:\s+(20\d\d))?\b"]
    for k, pat in enumerate(pats):
        for m in re.finditer(pat, line, re.I):
            if any(s <= m.start() < e or s < m.end() <= e for _, s, e in out):
                continue
            if k == 0:
                day, mon, y = int(m.group(1)), MONTHS[m.group(2)[:3].lower()], m.group(3)
            else:
                mon, day, y = MONTHS[m.group(1)[:3].lower()], int(m.group(2)), m.group(3)
            d = _mk_date(y, mon, day) if y else _future_year(mon, day, today)
            if d:
                out.append((d, m.start(), m.end()))
    rel = re.search(r"\b(today|tonight|tomorrow|next (?:mon|tues|wednes|thurs|fri|satur|sun)day)\b", line, re.I)
    if rel and not out:
        w = rel.group(1).lower()
        if w in ("today", "tonight"):
            d = today
        elif w == "tomorrow":
            d = today + datetime.timedelta(days=1)
        else:
            names = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
            target = names.index(w.split()[1][:3])
            d = today + datetime.timedelta(days=(target - today.weekday()) % 7 or 7)
        out.append((d, rel.start(), rel.end()))
    return sorted(out, key=lambda x: x[1])


def find_time(line):
    m = re.search(r"\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b|\b([01]?\d|2[0-3]):([0-5]\d)\b", line, re.I)
    if not m:
        return "", None
    if m.group(3):
        h = int(m.group(1)) % 12 + (12 if m.group(3).lower() == "pm" else 0)
        return "%02d:%02d" % (h, int(m.group(2) or 0)), (m.start(), m.end())
    return "%02d:%s" % (int(m.group(4)), m.group(5)), (m.start(), m.end())


def extract_deadlines(text, day_first=True, today=None):
    """Offline reader: every line with a date becomes a deadline; the rest of the line is its name."""
    today = today or datetime.date.today()
    found, seen = [], set()
    lines = [ln.strip() for ln in text.replace("\t", "  ").splitlines()]
    prev = ""
    for ln in lines:
        if not ln:
            continue
        ds = find_dates(ln, today, day_first)
        if not ds:
            if len(ln) < 120:
                prev = ln
            continue
        t, tspan = find_time(ln)
        title = ln
        cuts = sorted([(s, e) for _, s, e in ds] + ([tspan] if tspan else []), reverse=True)
        for s, e in cuts:
            title = title[:s] + " " + title[e:]
        title = re.sub(r"\b(due|on|by|at|date|deadline|from|to|until|-|–|:|\|)\s*$", "", title.strip(), flags=re.I)
        title = re.sub(r"\s*[|;,–\-:]+\s*", " - ", title).strip(" -|,;:.")
        title = re.sub(r"\s{2,}", " ", title)
        if len(title) < 3 and prev:
            title = prev
        if len(title) < 3:
            continue
        for d, _, _ in ds[:1]:
            k = (title.lower(), d.isoformat())
            if k in seen:
                continue
            seen.add(k)
            found.append({"title": title[:90], "date": d.isoformat(), "time": t, "kind": guess_kind(title)})
    return found


def _xml_text(xml, para_tag):
    xml = re.sub(r"</" + para_tag + r">", "\n", xml)
    xml = re.sub(r"<w:tab/>|</w:tc>|</a:p>", "  ", xml)
    txt = re.sub(r"<[^>]+>", "", xml)
    import html
    return html.unescape(txt)


def _xlsx_text(z):
    import html
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        x = z.read("xl/sharedStrings.xml").decode("utf-8", "replace")
        for si in re.findall(r"<si>(.*?)</si>", x, re.S):
            shared.append(html.unescape("".join(re.findall(r"<t[^>]*>(.*?)</t>", si, re.S))))
    out = []
    for n in sorted(n for n in z.namelist() if re.match(r"xl/worksheets/sheet\d+\.xml", n)):
        x = z.read(n).decode("utf-8", "replace")
        for row in re.findall(r"<row[^>]*>(.*?)</row>", x, re.S):
            cells = []
            for attrs, body in re.findall(r"<c([^>]*)>(.*?)</c>", row, re.S):
                v = re.search(r"<v>(.*?)</v>", body, re.S)
                inline = re.search(r"<t[^>]*>(.*?)</t>", body, re.S)
                if 't="s"' in attrs and v:
                    try:
                        cells.append(shared[int(v.group(1))])
                    except (ValueError, IndexError):
                        pass
                elif inline:
                    cells.append(html.unescape(inline.group(1)))
                elif v:
                    val = v.group(1)
                    try:
                        f = float(val)
                        if 40000 <= f <= 60000 and 's="' in attrs:      # a spreadsheet date
                            val = (datetime.date(1899, 12, 30) + datetime.timedelta(days=int(f))).isoformat()
                    except ValueError:
                        pass
                    cells.append(val)
            if cells:
                out.append("  |  ".join(c.strip() for c in cells if c.strip()))
    return "\n".join(out)


def _ics_items(text):
    items = []
    for ev in re.findall(r"BEGIN:VEVENT(.*?)END:VEVENT", text, re.S):
        ev = re.sub(r"\r?\n[ \t]", "", ev)
        summ = re.search(r"^SUMMARY[^:]*:(.*)$", ev, re.M)
        st = re.search(r"^DTSTART[^:]*:(\d{8})(?:T(\d{2})(\d{2}))?", ev, re.M)
        if summ and st:
            d = st.group(1)
            title = summ.group(1).strip().replace("\\,", ",")
            items.append({"title": title[:90], "date": "%s-%s-%s" % (d[:4], d[4:6], d[6:]),
                          "time": ("%s:%s" % (st.group(2), st.group(3))) if st.group(2) else "",
                          "kind": guess_kind(title)})
    return items


def pdf_text(path):
    try:
        import pypdf
    except ImportError:
        py = system_python()
        if getattr(sys, "frozen", False) or not py:
            raise RuntimeError("Reading PDFs needs a free add-on: rebuild with build_exe.bat, or run  pip install pypdf")
        r = run_hidden([py, "-m", "pip", "install", "pypdf"], timeout=600)
        if r.returncode != 0:
            raise RuntimeError("Couldn't install the PDF reader. Run:  pip install pypdf")
        import importlib
        importlib.invalidate_caches()
        import pypdf
    reader = pypdf.PdfReader(path)
    return "\n".join((pg.extract_text() or "") for pg in reader.pages[:60])


def read_any_file(path, vision_model=""):
    """(text, ready_items). ready_items is set for calendar files that already hold exact dates."""
    ext = os.path.splitext(path)[1].lower()
    if ext in (".txt", ".md", ".csv", ".tsv", ".rtf", ".json", ".html", ".htm"):
        with open(path, "rb") as f:
            raw = f.read(2_000_000)
        txt = raw.decode("utf-8", "replace")
        if ext in (".html", ".htm", ".rtf"):
            txt = re.sub(r"<br\s*/?>|</p>|</tr>|</li>|\\par\b", "\n", txt, flags=re.I)
            txt = re.sub(r"<[^>]+>|\\[a-z]+\d*\s?|[{}]", " ", txt)
        if ext in (".csv", ".tsv"):
            txt = txt.replace(",", "  |  ").replace("\t", "  |  ")
        return txt, None
    if ext == ".ics":
        with open(path, encoding="utf-8", errors="replace") as f:
            t = f.read()
        return t, _ics_items(t)
    if ext in (".docx", ".pptx", ".xlsx"):
        z = zipfile.ZipFile(path)
        if ext == ".docx":
            parts = [n for n in z.namelist() if re.match(r"word/(document|header\d*|footer\d*)\.xml", n)]
            return "\n".join(_xml_text(z.read(n).decode("utf-8", "replace"), "w:p") for n in parts), None
        if ext == ".pptx":
            parts = sorted((n for n in z.namelist() if re.match(r"ppt/slides/slide\d+\.xml", n)),
                           key=lambda n: int(re.findall(r"\d+", n)[-1]))
            return "\n".join(_xml_text(z.read(n).decode("utf-8", "replace"), "a:p") for n in parts), None
        return _xlsx_text(z), None
    if ext == ".pdf":
        return pdf_text(path), None
    if ext in (".png", ".jpg", ".jpeg", ".bmp", ".gif", ".webp"):
        with open(path, "rb") as f:
            img = f.read()
        try:
            return ollama_vision("Transcribe all the text in this image exactly, keeping each line and every date.",
                                 [img], vision_model or "qwen2.5vl:3b"), None
        except RMError as e:
            if str(e) == "NO_OLLAMA":
                raise RuntimeError("To read pictures I need Ollama running with the vision model (Settings > Smart brain).")
            raise RuntimeError("To read pictures, install my 'eyes' once:  ollama pull %s" % (vision_model or "qwen2.5vl:3b"))
    raise RuntimeError("I can't read %s files yet. Try PDF, Word, Excel, PowerPoint, text, calendar (.ics) or a picture." % ext)


DEADLINE_PROMPT = ("Today is %s. Find every exam, test, assignment, submission, deadline or important dated event in this "
                   "text. Use the year that makes sense (upcoming). Dates in this text are written day-first unless "
                   "obviously not. Reply with ONLY JSON: {\"items\": [{\"title\": \"short name\", \"date\": \"YYYY-MM-DD\", "
                   "\"time\": \"HH:MM or empty\", \"kind\": \"Exam|Quiz|Assignment|Deadline|Presentation|Class|Event\"}]}")


def llm_deadlines(text, model):
    names = ollama_models()
    if not names:
        return None
    m = model if model in names else ([n for n in names if n.split(":")[0] == model.split(":")[0]] or names)[0]
    j = _ollama_json("/api/chat", {"model": m, "stream": False, "format": "json",
                                   "options": {"temperature": 0.0, "num_predict": 1500},
                                   "messages": [{"role": "system", "content": DEADLINE_PROMPT % datetime.date.today().isoformat()},
                                                {"role": "user", "content": text[:9000]}]}, 300)
    d = parse_brain((j.get("message") or {}).get("content", ""))
    out = []
    for it in d.get("items") or []:
        if not isinstance(it, dict):
            continue
        try:
            dt = datetime.date.fromisoformat(str(it.get("date", ""))[:10])
        except ValueError:
            continue
        title = str(it.get("title") or "").strip()[:90]
        if title:
            tm = str(it.get("time") or "")
            out.append({"title": title, "date": dt.isoformat(), "time": tm if re.match(r"^\d\d:\d\d$", tm) else "",
                        "kind": str(it.get("kind") or guess_kind(title))[:14]})
    return out


def when_text(date_iso, today=None):
    today = today or datetime.date.today()
    try:
        d = datetime.date.fromisoformat(date_iso)
    except ValueError:
        return ""
    n = (d - today).days
    if n == 0:
        return "today"
    if n == 1:
        return "tomorrow"
    if n == -1:
        return "yesterday"
    if n < 0:
        return "%d days ago" % -n
    if n < 14:
        return "in %d days" % n
    if n < 60:
        return "in %d weeks" % (n // 7)
    return "in %d months" % round(n / 30.4)


