def start_menu_apps():
    """{name: shortcut path} for everything in the Start Menu."""
    res = {}
    roots = [os.path.join(os.environ.get("ProgramData", r"C:\ProgramData"), "Microsoft", "Windows", "Start Menu", "Programs"),
             os.path.join(os.environ.get("APPDATA", ""), "Microsoft", "Windows", "Start Menu", "Programs")]
    for r in roots:
        for dp, dn, fn in os.walk(r):
            for f in fn:
                if f.lower().endswith((".lnk", ".url")) and "uninstall" not in f.lower():
                    res.setdefault(os.path.splitext(f)[0], os.path.join(dp, f))
    return res


def open_app(name):
    """Open an app (or a website) by name. Returns a friendly sentence."""
    n = re.sub(r"\b(the|app|application|program|please|for me|up)\b", " ", name.lower())
    n = re.sub(r"\s+", " ", n).strip(" .!?")
    if not n:
        return "Open what? e.g. 'open spotify'."
    if not IS_WIN:
        return "Opening apps works on Windows."
    target = APPS.get(n)
    if target:
        try:
            os.startfile(target)
            return "Opening %s." % n.title()
        except OSError:
            pass
    apps = start_menu_apps()
    best, score = None, 0.0
    for k, v in apps.items():
        kl = k.lower()
        s = difflib.SequenceMatcher(None, n, kl).ratio() + (0.5 if kl.startswith(n) else 0) + (0.3 if n in kl else 0)
        if s > score:
            best, score = (k, v), s
    if best and score >= 0.75:
        try:
            os.startfile(best[1])
            return "Opening %s." % best[0]
        except OSError:
            pass
    if n in SITES:
        webbrowser.open(SITES[n])
        return "Opening %s in your browser." % n.title()
    try:
        os.startfile(n.replace(" ", ""))
        return "Opening %s." % n
    except OSError:
        return "I couldn't find an app called “%s” on this PC." % name.strip()


# ---------- battery ---------------------------------------------------------------
def battery_status():
    """(percent, charging) or None when there's no battery (desktop PC)."""
    if not IS_WIN:
        if os.environ.get("FOX_FAKE_BATTERY"):
            p, c = os.environ["FOX_FAKE_BATTERY"].split(",")
            return int(p), c == "1"
        return None

    class SPS(ctypes.Structure):
        _fields_ = [("ac", ctypes.c_ubyte), ("flag", ctypes.c_ubyte), ("pct", ctypes.c_ubyte), ("saver", ctypes.c_ubyte),
                    ("life", ctypes.c_ulong), ("full", ctypes.c_ulong)]
    s = SPS()
    try:
        if not ctypes.windll.kernel32.GetSystemPowerStatus(ctypes.byref(s)):
            return None
    except Exception:
        return None
    if s.flag == 128 or s.pct == 255:
        return None
    return int(s.pct), (s.ac == 1)


def spotify_link_to_uri(v):
    """Turn a Spotify share link into a spotify:type:id URI."""
    v = v.strip()
    if v.startswith("spotify:"):
        return v
    m = re.search(r"open\.spotify\.com/(?:intl-[a-z]+/)?(track|playlist|album|artist)/([A-Za-z0-9]+)", v)
    return "spotify:%s:%s" % (m.group(1), m.group(2)) if m else None


def drop_files_hook(widget, callback):
    """Let files be dragged from Explorer onto a window (Windows). callback(list_of_paths) runs on the Tk thread."""
    if not IS_WIN:
        return False
    try:
        from ctypes import wintypes as wt
        u, sh = ctypes.windll.user32, ctypes.windll.shell32
        widget.update_idletasks()
        hwnd = u.GetParent(widget.winfo_id()) or widget.winfo_id()
        WNDPROC = ctypes.WINFUNCTYPE(ctypes.c_ssize_t, wt.HWND, ctypes.c_uint, wt.WPARAM, wt.LPARAM)
        u.CallWindowProcW.argtypes = [ctypes.c_void_p, wt.HWND, ctypes.c_uint, wt.WPARAM, wt.LPARAM]
        u.CallWindowProcW.restype = ctypes.c_ssize_t
        setp = getattr(u, "SetWindowLongPtrW", None) or u.SetWindowLongW
        setp.argtypes = [wt.HWND, ctypes.c_int, ctypes.c_void_p]
        setp.restype = ctypes.c_void_p
        sh.DragQueryFileW.argtypes = [ctypes.c_void_p, ctypes.c_uint, ctypes.c_wchar_p, ctypes.c_uint]
        sh.DragFinish.argtypes = [ctypes.c_void_p]
        pending = []

        def proc(h, msg, wp, lp):
            if msg == 0x0233:                                  # WM_DROPFILES
                try:
                    n = sh.DragQueryFileW(wp, 0xFFFFFFFF, None, 0)
                    files = []
                    for i in range(n):
                        buf = ctypes.create_unicode_buffer(520)
                        sh.DragQueryFileW(wp, i, buf, 520)
                        files.append(buf.value)
                    sh.DragFinish(wp)
                    pending.append(files)
                    widget.after(10, lambda: callback(pending.pop(0)) if pending else None)
                except Exception:
                    pass
                return 0
            return u.CallWindowProcW(old, h, msg, wp, lp)
        cb = WNDPROC(proc)
        old = setp(hwnd, -4, ctypes.cast(cb, ctypes.c_void_p))
        sh.DragAcceptFiles(hwnd, True)
        widget._kx_drop_proc = (cb, old)                       # keep the callback alive
        return True
    except Exception:
        return False



def _stair(r, step, kind="round"):
    """Offsets for a top-left corner, from (0, r) round to (r, 0), as pixel stairs."""
    if r <= 0:
        return [(0, 0)]
    pts = [(0, r)]
    n = max(1, int(round(r / float(step))))
    px, py = 0, r
    for k in range(1, n + 1):
        y = r - k * r / float(n)
        if kind == "cut":
            x = r - y
        else:
            x = r - math.sqrt(max(0.0, r * r - (r - y) ** 2))
        x = round(x / step) * step if k < n else r
        y = round(y)
        pts.append((px, y))
        pts.append((x, y))
        px, py = x, y
    out = []
    for p in pts:                                   # drop repeats
        if not out or out[-1] != p:
            out.append(p)
    return out


def round_pts(x1, y1, x2, y2, r=10, step=2, corners=None, notch=0):
    """Polygon points for a box with pixel-stepped corners.
    corners = [(kind, radius)] for top-left, top-right, bottom-right, bottom-left (kind 'round' or 'cut');
    notch = radius of little half-circle bites in the middle of the left and right sides (a ticket)."""
    r = max(0, min(int(r), int((x2 - x1) // 2), int((y2 - y1) // 2)))
    cs = corners or [("round", r)] * 4
    cs = [(k, max(0, min(int(rr), int((x2 - x1) // 2), int((y2 - y1) // 2)))) for (k, rr) in cs]
    out = []
    tl = _stair(cs[0][1], step, cs[0][0])
    out += [(x1 + ox, y1 + oy) for (ox, oy) in tl]
    tr = _stair(cs[1][1], step, cs[1][0])
    out += [(x2 - oy, y1 + ox) for (ox, oy) in tr]
    if notch:
        my = (y1 + y2) / 2.0
        for a in range(-90, 91, 30):
            out.append((x2 - round(notch * math.cos(math.radians(a)) / step) * step, my + round(notch * math.sin(math.radians(a)))))
    br = _stair(cs[2][1], step, cs[2][0])
    out += [(x2 - ox, y2 - oy) for (ox, oy) in br]
    bl = _stair(cs[3][1], step, cs[3][0])
    out += [(x1 + oy, y2 - ox) for (ox, oy) in bl]
    if notch:
        my = (y1 + y2) / 2.0
        for a in range(90, -91, -30):
            out.append((x1 + round(notch * math.cos(math.radians(a)) / step) * step, my + round(notch * math.sin(math.radians(a)))))
    flat = []
    for (x, y) in out:
        flat += [x, y]
    return flat


SHAPES = {   # the different box shapes used round the app (so not everything is a plain rectangle)
    "round": lambda r: [("round", r)] * 4,
    "ema": lambda r: [("cut", r + 4), ("cut", r + 4), ("round", r), ("round", r)],      # a wooden wish plaque
    "leaf": lambda r: [("round", r * 2), ("round", r // 2), ("round", r * 2), ("round", r // 2)],
    "pill": lambda r: [("round", 999)] * 4,
}


def rbox(cv, x1, y1, x2, y2, r=10, fill="", outline="", width=1, tags=(), shape="round", step=2, notch=0):
    """Draw a pixel-rounded box on a canvas."""
    pts = round_pts(x1, y1, x2, y2, r, step, SHAPES.get(shape, SHAPES["round"])(r), notch)
    return cv.create_polygon(pts, fill=fill, outline=outline, width=width, tags=tags, joinstyle="miter")


class PixelButton(tk.Canvas if tk else object):
    """A rounded, pixel-edged button drawn on a little canvas (hover glow, press dip, a soft tap sound)."""

    def __init__(self, parent, text, cmd, bg, fg, size=10, padx=10, pady=3, enabled=True, shape="pill"):
        try:
            pbg = getattr(parent, "_zk_fill", None) or parent.cget("bg")
        except Exception:
            pbg = PAPER
        import tkinter.font as tkfont
        self._font = tkfont.Font(family=FONT_UI, size=size, weight="bold")
        self._size0, self._pad, self._fs = size, (padx, pady), size
        self._text, self._bg, self._fg, self._cmd, self._on = text, bg, fg, cmd, enabled
        self._shape, self._hover, self._down = shape, False, False
        w = self._font.measure(text) + 2 * padx + 10
        h = self._font.metrics("linespace") + 2 * pady + 6
        tk.Canvas.__init__(self, parent, width=w, height=h, bg=pbg, highlightthickness=0, bd=0,
                           cursor="hand2" if enabled else "arrow")
        self._wh = (w, h)
        self.bind("<Configure>", self._resized)
        if enabled:
            self.bind("<Enter>", lambda e=None: self._set(hover=True))
            self.bind("<Leave>", lambda e=None: self._set(hover=False, down=False))
            self.bind("<Button-1>", lambda e=None: self._set(down=True))
            self.bind("<ButtonRelease-1>", self._release)
        self._draw()

    def _resized(self, e):
        self._wh = (max(4, e.width), max(4, e.height))
        self._draw()

    def zk_rescale(self, f, sizer=None):
        """Grow or shrink with the window (zenko14)."""
        n = sizer(self._size0) if sizer else max(6, int(round(self._size0 * f)))
        if n == self._fs:
            return
        self._fs = n
        try:
            self._font.configure(size=n)
            padx, pady = self._pad
            w = self._font.measure(self._text) + 2 * padx + 10
            h = self._font.metrics("linespace") + 2 * pady + 6
            tk.Canvas.configure(self, width=w, height=h)
            self._draw()
        except tk.TclError:
            pass

    def _set(self, hover=None, down=None):
        if hover is not None:
            self._hover = hover
        if down is not None:
            self._down = down
        self._draw()

    def _release(self, e):
        was = self._down
        self._set(down=False)
        if was and 0 <= e.x < self.winfo_width() and 0 <= e.y < self.winfo_height():
            ui_sound("tap")
            self._cmd()

    def _draw(self):
        try:
            tk.Canvas.delete(self, "all")
            W, H = self._wh
        except tk.TclError:
            return
        bg = self._bg
        if not self._on:
            fill, edge, fg = _mixhex(bg, PAPER, 0.35), LINE, _mixhex(bg, INK, 0.35)
        else:
            fill = _mixhex(bg, "#000000", 0.22) if self._down else (_mixhex(bg, "#ffffff", 0.12) if self._hover else bg)
            edge = GOLD if self._hover else (_mixhex(bg, "#ffffff", 0.35) if bg == ORANGE else _mixhex(bg, "#ffffff", 0.2))
            fg = self._fg
        dy = 1 if self._down else 0
        r = min(H // 2, 14)
        rbox(self, 1, 1 + dy, W - 2, H - 2 + dy, r, fill=fill, outline=edge, width=1, shape=self._shape)
        if self._on and not self._down:                              # a thin lit edge along the top (pixel bevel)
            hi = _mixhex(fill, "#ffffff", 0.22)
            self.create_line(1 + r, 3, W - 2 - r, 3, fill=hi)
        self.create_text(W // 2, H // 2 + dy, text=self._text, fill=fg, font=self._font)

    def configure(self, cnf=None, **kw):
        kw = dict(cnf or {}, **kw)
        changed = False
        for k_in, attr in (("text", "_text"), ("bg", "_bg"), ("background", "_bg"), ("fg", "_fg"), ("foreground", "_fg")):
            if k_in in kw:
                v = kw.pop(k_in)
                if getattr(self, attr, None) != v:           # nothing new: don't repaint
                    setattr(self, attr, v)
                    changed = True
        if kw:
            tk.Canvas.configure(self, **kw)
        if changed:
            self._draw()

    config = configure

    def cget(self, key):
        if key == "text":
            return self._text
        if key in ("bg", "background"):
            return self._bg
        if key in ("fg", "foreground"):
            return self._fg
        return tk.Canvas.cget(self, key)

    __getitem__ = cget


class _CanvasText:
    """A text item on a canvas that behaves like a Label for .config(text=...)."""
    def __init__(self, cv):
        self.cv, self.item, self.text = cv, None, ""

    def place(self, x, y, width):
        try:
            if self.item is None or not self.cv.find_withtag(self.item):
                self.item = self.cv.create_text(x, y, anchor="nw", text=self.text, width=width, fill=_mixhex(NIGHT, INK, 0.7),
                                                font=(FONT_UI, 10), tags="status")
            else:
                self.cv.coords(self.item, x, y)
                self.cv.itemconfigure(self.item, width=width)
        except tk.TclError:
            pass

    def config(self, text=None, **kw):
        if text is not None:
            self.text = text
        if self.item is not None:
            try:
                self.cv.itemconfigure(self.item, text=self.text)
            except tk.TclError:
                pass
    configure = config


_JP = {}


def _jp_font(root):
    """A Japanese-capable font if Windows has one (for the little kanji), else ''."""
    if "f" not in _JP:
        _JP["f"] = ""
        try:
            import tkinter.font as tkfont
            have = {f.lower(): f for f in tkfont.families(root)}
            for n in ("Yu Gothic UI", "Yu Gothic", "Meiryo UI", "Meiryo", "MS Gothic", "Noto Sans CJK JP", "Noto Sans JP", "IPAGothic"):
                if n.lower() in have:
                    _JP["f"] = have[n.lower()]
                    break
        except Exception:
            pass
    return _JP["f"]



