# ---- a safe little calculator ---------------------------------------------------------
def calc_eval(expr):
    """'15% of 240', '2^10', 'sqrt(81) + 3', '12 x 7' -> number (no eval of real code: only maths)."""
    import ast
    import operator as op
    s = expr.lower().strip().rstrip("=?. ")
    s = s.replace("×", "*").replace("÷", "/").replace("−", "-").replace(",", "")
    s = re.sub(r"\b(?:what is|what's|whats|calculate|calc|compute|solve)\b", " ", s)
    s = re.sub(r"(\d+(?:\.\d+)?)\s*%\s*off\s*(\d+(?:\.\d+)?)", r"(\2*(1-\1/100))", s)
    s = re.sub(r"(\d+(?:\.\d+)?)\s*%\s*of\s*", r"(\1/100)*", s)
    s = re.sub(r"(\d+(?:\.\d+)?)\s*%", r"(\1/100)", s)
    for w, o in ((r"\bplus\b", "+"), (r"\bminus\b", "-"), (r"\btimes\b", "*"), (r"\bmultiplied by\b", "*"),
                 (r"\bdivided by\b", "/"), (r"\bover\b", "/"), (r"\bsquared\b", "**2"), (r"\bcubed\b", "**3"),
                 (r"\bto the power of\b", "**"), (r"\bmod\b", "%"), (r"\bsquare root of\b", "sqrt "),
                 (r"\broot of\b", "sqrt ")):
        s = re.sub(w, o, s)
    s = re.sub(r"(?<=[\d)])\s*x\s*(?=[\d(])", "*", s)
    s = s.replace("^", "**")
    s = re.sub(r"\bsqrt\s+(\d+(?:\.\d+)?)", r"sqrt(\1)", s)
    s = s.strip()
    if not s:
        raise ValueError("empty")
    ops = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul, ast.Div: op.truediv, ast.FloorDiv: op.floordiv,
           ast.Mod: op.mod, ast.Pow: op.pow, ast.USub: op.neg, ast.UAdd: op.pos}
    fns = {"sqrt": math.sqrt, "sin": lambda v: math.sin(math.radians(v)), "cos": lambda v: math.cos(math.radians(v)),
           "tan": lambda v: math.tan(math.radians(v)), "log": math.log10, "ln": math.log, "abs": abs, "round": round,
           "exp": math.exp, "floor": math.floor, "ceil": math.ceil}
    names = {"pi": math.pi, "e": math.e}

    def ev(n):
        if isinstance(n, ast.Expression):
            return ev(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return n.value
        if isinstance(n, ast.BinOp) and type(n.op) in ops:
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, ast.Pow) and abs(b) > 200:
                raise ValueError("too big")
            return ops[type(n.op)](a, b)
        if isinstance(n, ast.UnaryOp) and type(n.op) in ops:
            return ops[type(n.op)](ev(n.operand))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id in fns and len(n.args) == 1:
            return fns[n.func.id](ev(n.args[0]))
        if isinstance(n, ast.Name) and n.id in names:
            return names[n.id]
        raise ValueError("not maths")
    return ev(ast.parse(s, mode="eval"))


def fmt_num(v):
    if isinstance(v, float):
        if v != v or v in (float("inf"), float("-inf")):
            return str(v)
        if abs(v - round(v)) < 1e-9 and abs(v) < 1e15:
            return "{:,}".format(int(round(v)))
        return ("{:,.6f}".format(v)).rstrip("0").rstrip(".")
    return "{:,}".format(v)


