def translate_text(text, target, source="auto"):
    """Free translation (Google's public endpoint, then MyMemory). Returns (translation, engine)."""
    try:
        url = "%s?client=gtx&sl=%s&tl=%s&dt=t&dt=rm&q=%s" % (WEB["gtx"], source, target, _q(text))
        j = json.loads(http_get(url, 10).decode("utf-8", "replace"))
        out = "".join(seg[0] for seg in (j[0] or []) if seg and seg[0])
        roman = "".join(seg[2] for seg in (j[0] or []) if seg and seg[0] is None and len(seg) > 2 and isinstance(seg[2], str))
        if out.strip():
            return out.strip(), roman.strip(), "Google Translate"
    except Exception:
        pass
    src = "en" if source == "auto" else source
    if src == target:
        src = "en" if target != "en" else "ja"
    j = http_json("%s?q=%s&langpair=%s|%s" % (WEB["mymemory"], _q(text[:450]), src, target), 10)
    out = ((j.get("responseData") or {}).get("translatedText") or "").strip()
    if not out:
        raise WebError("I couldn't translate that right now. Try again in a moment?")
    return out, "", "MyMemory"


def define_word(word):
    """A dictionary entry (dictionaryapi.dev, free), falling back to DuckDuckGo / Wikipedia."""
    w = word.strip().lower()
    try:
        j = http_json(WEB["dict"] + _q(w), 8)
        if isinstance(j, list) and j:
            e = j[0]
            phon = e.get("phonetic") or next((p.get("text") for p in e.get("phonetics") or [] if p.get("text")), "")
            lines = ["%s%s" % (e.get("word", w), ("  " + phon) if phon else "")]
            n = 0
            for mng in e.get("meanings") or []:
                pos = mng.get("partOfSpeech", "")
                for d in (mng.get("definitions") or [])[:2]:
                    n += 1
                    ex = d.get("example")
                    lines.append("%d. (%s) %s%s" % (n, pos, d.get("definition", ""), ("\n     e.g. “%s”" % ex) if ex else ""))
                    if n >= 4:
                        break
                if n >= 4:
                    break
            syn = []
            for mng in e.get("meanings") or []:
                syn += mng.get("synonyms") or []
            if syn:
                lines.append("Similar: " + ", ".join(syn[:6]))
            return "\n".join(lines) + "\n(Free Dictionary API)"
    except Exception:
        pass
    inst = ddg_instant("define " + w)
    if inst:
        return "%s\n(%s)" % (inst["text"], inst["title"])
    wk = wiki_extract(w)
    if wk:
        return "%s\n(%s)" % (_trim_sentences(wk["text"], 2, 360), wk["title"])
    raise WebError("Ne~ I couldn't find '%s' in the dictionary. Check the spelling?" % word)


def wiki_long(topic, chars=6000):
    """A longer plain-text Wikipedia article intro + body (for flashcards)."""
    hits = _search_wiki(topic, 1)
    if not hits:
        return None, ""
    title = hits[0]["title"]
    j = http_json("%s?action=query&prop=extracts&explaintext=1&exsectionformat=plain&exchars=%d&format=json&redirects=1&titles=%s"
                  % (WEB["wiki_api"], chars, _q(title)), 10)
    pages = (j.get("query") or {}).get("pages") or {}
    for p in pages.values():
        if p.get("extract"):
            return p.get("title", title), p["extract"]
    return title, ""


