def make_flashcards(topic, text, n=6):
    """Fill-in-the-blank flashcards from plain text (works without any AI)."""
    sents = [s for s in _sentences(text) if 50 <= len(s) <= 260]
    cards, used = [], set()
    tw = set(w.lower() for w in re.findall(r"[A-Za-z]{3,}", topic))
    for s in sents:
        if len(cards) >= n:
            break
        cand = None
        m = re.findall(r"(?<!^)(?<![.!?] )\b((?:[A-Z][a-z]+(?:\s+(?:of|de|von|the)?\s*[A-Z][a-z]+)*))", s)
        m = [x.strip() for x in m if x.lower() not in tw and x.split()[0].lower() not in _QSTOP and len(x) > 3]
        nums = re.findall(r"\b(\d{3,4}|\d+(?:\.\d+)?\s?(?:%|percent|km|kg|million|billion|years|degrees))\b", s)
        if nums:
            cand = nums[0]
        elif m:
            cand = max(m, key=len)
        else:
            words = [w for w in re.findall(r"[A-Za-z][a-z\-]{6,}", s) if w.lower() not in _QSTOP and w.lower() not in tw]
            if words:
                cand = max(words, key=len)
        if not cand or cand.lower() in used:
            continue
        q = s.replace(cand, "_____", 1)
        if q == s:
            continue
        used.add(cand.lower())
        cards.append({"q": "Fill the blank: " + q, "a": cand})
    return cards


def answer_close(given, right):
    g = re.sub(r"[^a-z0-9 ]", "", given.lower()).strip()
    r = re.sub(r"[^a-z0-9 ]", "", right.lower()).strip()
    if not g:
        return False
    if g == r or (len(g) >= 4 and (g in r or r in g)):
        return True
    return difflib.SequenceMatcher(None, g, r).ratio() >= 0.78


