    def interact(self, kind, arg=None):
        """Play with her: pet, belly, boop, tickle, tail, treat, yarn, hide, highfive, gift, dance, brush, sing, yawn."""
        now = time.monotonic()
        self.sleeping = False
        if self.sulk_until and now < self.sulk_until:
            if kind in ("treat", "gift", "pet", "brush"):
                self.sulk_until = 0.0
                if kind in ("treat", "gift"):
                    self.bond_add(1)
                return self.forgive(via=kind, arg=arg)
            beep("nag")
            line = random.choice(["Hmph! I'm still sulking. *turns away*", "Mou~! Not talking to you. ...a treat might help.",
                                  "Hmph. Say sorry first~"])
            self.say(line, 5)
            return line
        if kind == "gift":
            return self.give_gift()
        if kind == "treat":
            arg = arg or random.choice(TREATS)
            self.extra["treats"] = int(self.extra.get("treats", 0)) + 1
        self.play = {"kind": kind, "t0": now, "dur": self.PLAY_DUR.get(kind, 2.5), "arg": arg}
        self.mood_override = None
        snd = {"pet": "pet", "belly": "giggle", "boop": "boop", "tickle": "giggle", "tail": "giggle", "treat": "munch",
               "yarn": "happy", "hide": "giggle", "highfive": "happy", "dance": "song", "brush": "pet", "sing": "song",
               "yawn": "yawn", "praise": "pet"}.get(kind, "happy")
        beep(snd)
        self.bond_add({"pet": 1, "belly": 1, "treat": 2, "yarn": 2, "hide": 2, "highfive": 1, "dance": 1, "brush": 2,
                       "sing": 1}.get(kind, 0))
        line = random.choice(self.PLAY_LINES.get(kind, ["Ehehe~"])).replace("{item}", arg or "")
        self.say(line, 7)
        return line

    def give_gift(self):
        now = time.monotonic()
        item = random.choice(GIFTS)
        self.play = {"kind": "gift", "t0": now, "dur": self.PLAY_DUR["gift"], "arg": item}
        beep("gift")
        tr = self.extra.setdefault("treasures", [])
        tr.append(item)
        self.extra["treasures"] = tr[-40:]
        self.bond_add(3)
        line = "A present? For me?! *unwraps* Uwaa~ %s! I'll keep it in my treasure box forever~kon!" % item
        self.root.after(1000, lambda: self.say(line, 8))
        return line

    def start_sulk(self, why=""):
        self.play = None
        self.sulk_until = time.monotonic() + 75
        self.bond_add(-2)
        beep("nag")
        line = why or random.choice(["Hmph! *turns away and sulks*", "Mou~! I'm sulking now. Don't look at me!",
                                     "Hmph. Meanie. *pouts*"])
        self.say(line + " (Say sorry, or give me a treat~)", 8)
        return line + " (Say sorry, or give me a treat~)"

    def forgive(self, auto=False, via="", arg=None):
        self.sulk_until = 0.0
        self.play = {"kind": "treat" if via == "treat" else "forgive", "t0": time.monotonic(),
                     "dur": self.PLAY_DUR["treat" if via == "treat" else "forgive"], "arg": arg or (random.choice(TREATS) if via == "treat" else None)}
        beep("pet")
        if auto:
            line = "...Okay, I can't stay mad at you. Ehehe~ forgiven!"
        elif via == "treat":
            line = "...*sniff sniff* Is that %s? ...Fine. Forgiven! *munch*" % self.play["arg"]
        elif via == "gift":
            line = "A present...? Hmph. ...Okay, okay, I forgive you~ *tail wag*"
        else:
            line = random.choice(self.PLAY_LINES["forgive"])
        self.say(line, 7)
        return line

    def fox_clicked(self, x, y):
        """A click on the fox: where you touch her matters (head, nose, belly, tails)."""
        now = time.monotonic()
        p = self.play
        if p and p["kind"] == "hide" and not p.get("found"):
            p["found"] = True
            self.play = {"kind": "found", "t0": now, "dur": self.PLAY_DUR["found"]}
            beep("giggle")
            self.bond_add(1)
            self.say(random.choice(self.PLAY_LINES["found"]), 6)
            return
        self.pokes = [t for t in self.pokes if now - t < 4.0] + [now]
        if len(self.pokes) >= 8 and not self.sulk_until:
            self.pokes = []
            self.start_sulk("Mou~!! Too many pokes! Hmph!")
            return
        fx = (x - self.COLW) / float(self.Z)
        fy = (y - self.fox_y) / float(self.Z)
        if 31 <= fx <= 41 and 32 <= fy <= 38:
            kind = "boop"
        elif fx >= 58 or (fx >= 50 and fy >= 46 and fy < 64):
            kind = "tail"
        elif fy < 44:
            kind = "pet"
        else:
            kind = "belly"
        if self.sulk_until and now < self.sulk_until:
            beep("nag")
            self.say(random.choice(["Hmph!", "*turns away* Hmph.", "...", "Mou~ still sulking!"]), 3)
            return
        self.interact(kind)

    # ---- the pose for this animation frame (shared by the desktop fox and the Customize preview) ------
    def lock_extra_acc(self):
        return ("headband",) if self.lockin and self.cfg.get("lockin_headband", True) else ()

    # ---- lock-in mode ---------------------------------------------------------------------
    def lockin_start(self, minutes=None, resume=False):
        if resume:
            until = float(self.extra.get("lockin_until", 0))
            if until <= time.time():
                return None
        else:
            m = int(minutes or self.cfg.get("lockin_minutes", 50) or 50)
            until = time.time() + max(1, min(600, m)) * 60
            self.extra["lockin_until"] = until
            self.save_extra()
        self.lockin = {"until": until, "eaten": 0, "good": None, "last_eat": 0.0, "last_hwnd": None,
                       "t0": time.time()}
        mins_left = int(round((until - time.time()) / 60.0))
        if not self.session and self.cfg.get("lockin_session", True) and not resume:
            self.start_session("Lock-in", max(1, mins_left))
        self.images = {}
        self.set_mood("focus", 2)
        beep("start")
        line = ("Lock-in mode ON for %d min! *ties hachimaki* If a distraction shows up, I'll pounce on it and eat it. "
                "To stop early: say 'unlock', right-click me > Exit lock-in, or hold Esc for 2 seconds." % mins_left)
        self.say(line, 12)
        self.lockin_poll()
        return line

    def lockin_stop(self, done=False, quiet=False):
        L, self.lockin = self.lockin, None
        self.extra["lockin_until"] = 0
        self.save_extra()
        self.images = {}
        if not L:
            return "Lock-in isn't on."
        n = L.get("eaten", 0)
        if done:
            self.set_mood("happy", 6)
            beep("done")
            line = "Lock-in complete! Yatta~! I ate %d distraction%s for you. Otsukaresama~kon!" % (n, "" if n == 1 else "s")
        else:
            beep("happy")
            line = "Lock-in off. I ate %d distraction%s while it was on. Rest well, ne~" % (n, "" if n == 1 else "s")
        if not quiet:
            self.say(line, 10)
        return line

    def lockin_distracting(self, title, proc):
        site = self.is_distracting(title, proc)
        if site:
            return site
        t = (title or "").lower()
        for a in self.cfg.get("allow", []):
            if a and a.lower() in t:
                return None
        for w in self.cfg.get("lockin_extra", []):
            w = (w or "").strip().lower()
            if not w:
                continue
            if w.endswith(".exe"):
                if proc == w:
                    return os.path.splitext(w)[0].title()
            elif w in t:
                return PRETTY.get(w, w.title())
        return None

    def lockin_poll(self):
        if not self.lockin:
            return
        try:
            self._lockin_check()
        except Exception:
            pass
        if self.lockin:
            self.root.after(200, self.lockin_poll)

    def _lockin_check(self):
        L = self.lockin
        now = time.monotonic()
        if time.time() >= L["until"]:
            self.lockin_stop(done=True)
            return
        if key_down(0x1B):                                   # hold Esc for 2 s = emergency exit
            if not self._esc_t:
                self._esc_t = now
            elif now - self._esc_t >= 2.0:
                self._esc_t = 0.0
                self.lockin_stop(done=False)
                return
        else:
            self._esc_t = 0.0
        if self.lock_eating:
            return
        hwnd, title, proc, pid = fg_window()
        if not hwnd or (pid and pid == os.getpid()):
            return
        site = self.lockin_distracting(title, proc)
        if not site:
            L["good"] = hwnd
            return
        if hwnd == L.get("last_hwnd") and now - L.get("last_eat", 0) < 1.2:
            return
        self.lockin_eat(hwnd, title, proc, site)

    def lockin_eat(self, hwnd, title, proc, site):
        """She pounces on the distracting window and eats it, then sends you back to work."""
        L = self.lockin
        L["last_eat"], L["last_hwnd"] = time.monotonic(), hwnd
        action = self.cfg.get("lockin_action", "smart")
        did = None
        if proc in BROWSERS and action in ("smart", "close"):
            close_distraction("tab")                         # the browser is still in front: close just that tab now
            did = "tab"
        L["eaten"] = L.get("eaten", 0) + 1
        day = datetime.date.today().isoformat()
        eaten = self.extra.setdefault("eaten", {})
        eaten[day] = int(eaten.get(day, 0)) + 1
        for k in sorted(eaten)[:-60]:
            eaten.pop(k, None)
        self.save_extra()
        if self.cfg.get("learn_habits", True):
            try:
                learn_distraction(site)
            except Exception:
                pass
        rect = window_rect(hwnd) or (100, 100, 900, 600)

        def finish():
            if did is None:
                window_action(hwnd, "close" if action == "close" else "minimise")
            if L.get("good") and L.get("good") != hwnd:
                window_focus(L["good"])
        self.lock_eating = True
        self.play = {"kind": "eat", "t0": time.monotonic(), "dur": self.PLAY_DUR["eat"]}
        beep("chomp")
        if self.cfg.get("lockin_animation", True):
            try:
                self.eat_overlay(rect, site, finish)
            except Exception:
                finish()
                self.lock_eating = False
        else:
            finish()
            self.lock_eating = False
        self.say(random.choice(LOCK_LINES) + "  (%s)" % site, 7)

    def eat_overlay(self, rect, site, finish):
        """A see-through window over the distraction: Zenko leaps in, chomps it to darkness, and it's gone."""
        x1, y1, x2, y2 = rect
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        x1, y1 = max(-8, x1), max(-8, y1)
        x2, y2 = min(sw + 8, x2), min(sh + 8, y2)
        w, h = max(240, x2 - x1), max(180, y2 - y1)
        ov = tk.Toplevel(self.root)
        ov.overrideredirect(True)
        ov.attributes("-topmost", True)
        try:
            ov.attributes("-transparentcolor", KEY)
        except tk.TclError:
            pass
        ov.configure(bg=KEY)
        ov.geometry("%dx%d+%d+%d" % (w, h, x1, y1))
        cv = tk.Canvas(ov, width=w, height=h, bg=KEY, highlightthickness=0, bd=0)
        cv.pack()
        Z = max(2, min(10, int(min(w * 0.6 / W_, h * 0.7 / H_))))

        def img(state, frame=0):
            key = (state, frame, Z, id(self.pal))
            if key not in self.lock_imgs:
                if len(self.lock_imgs) > 40:
                    self.lock_imgs.clear()
                acc = ("headband",) + tuple(a for a in self.accessories() if a not in ("headband",))
                self.lock_imgs[key] = sprite_photo([build_tails(self.tail_count(), frame, shadow=False),
                                                    build_frame(state, "up", frame % 2, None, acc)], self.pal, Z)
            return self.lock_imgs[key]
        fw, fh = W_ * Z, H_ * Z
        sx, sy = w - fw * 0.2, h + fh * 0.1                    # leaps in from the bottom right
        tx, ty = (w - fw) / 2.0 + fw * 0.12, (h - fh) / 2.0
        fox = cv.create_image(sx, sy, anchor="nw", image=img("boop2"))
        rnd = random.Random()
        crumbs, t0 = [], time.monotonic()
        night = _mixhex(NIGHT, "#000000", 0.25)
        state = {"bites": 0, "done": False}

        def step():
            if not ov.winfo_exists():
                return
            e = time.monotonic() - t0
            try:
                if e < 0.32:                                    # the pounce: an arc through the air
                    t = e / 0.32
                    x = sx + (tx - sx) * t
                    y = sy + (ty - sy) * t - math.sin(math.pi * t) * h * 0.25
                    cv.coords(fox, x, y)
                    cv.itemconfigure(fox, image=img("boop2", int(e * 20) % 8))
                elif e < 1.05:                                  # chomp chomp: bites of darkness spread over the window
                    cv.coords(fox, tx + (Z if int(e * 25) % 2 else -Z), ty)
                    cv.itemconfigure(fox, image=img("chomp" if int(e / 0.09) % 2 else "munch2", int(e * 20) % 8))
                    want = int((e - 0.32) / 0.73 * 26)
                    mx_, my_ = tx + fw * 0.33, ty + fh * 0.48
                    while state["bites"] < want:
                        state["bites"] += 1
                        k = state["bites"] / 26.0
                        r = max(w, h) * (0.12 + 0.2 * k)
                        bx = mx_ + rnd.uniform(-1, 1) * w * 0.65 * k
                        by = my_ + rnd.uniform(-1, 1) * h * 0.65 * k
                        cv.create_oval(bx - r, by - r, bx + r, by + r, fill=night, outline="", tags="bite")
                        for _ in range(3):
                            c = cv.create_rectangle(0, 0, 0, 0, fill=rnd.choice((GOLD, ORANGE, INK, GLOW, "#ffffff")),
                                                    outline="", tags="crumb")
                            crumbs.append([c, mx_, my_, rnd.uniform(-9, 9), rnd.uniform(-12, -3), rnd.choice((4, 6, 8))])
                    cv.tag_raise(fox)
                    cv.tag_raise("crumb")
                elif not state["done"]:
                    state["done"] = True
                    cv.create_rectangle(0, 0, w, h, fill=night, outline="", tags="bite")
                    finish()
                    cv.itemconfigure(fox, image=img("hearts", 1))
                    cv.coords(fox, tx, ty)
                    cv.create_text(w / 2, ty + fh + 18 if ty + fh + 30 < h else max(30, ty - 20),
                                   text="Gulp! %s eaten. Back to work~kon!" % site, fill=GOLD,
                                   font=(FONT_UI, max(12, min(26, int(w / 40))), "bold"))
                    cv.tag_raise(fox)
                elif e > 1.75:
                    ov.destroy()
                    self.lock_eating = False
                    return
                for cr in crumbs:
                    it, x, y, vx, vy, s = cr
                    x, y, vy = x + vx, y + vy, vy + 0.9
                    cr[1], cr[2], cr[4] = x, y, vy
                    cv.coords(it, x, y, x + s, y + s)
            except tk.TclError:
                self.lock_eating = False
                return
            ov.after(28, step)
        step()
        self.root.after(4000, lambda: (self.__setattr__("lock_eating", False), ov.destroy() if ov.winfo_exists() else None))

    # ---- reminders, pomodoro ------------------------------------------------------------------
    def extras_tick(self):
        now = time.time()
        rem = self.extra.get("reminders", [])
        due = [r for r in rem if r.get("at", 0) <= now]
        if due:
            self.extra["reminders"] = [r for r in rem if r.get("at", 0) > now]
            self.save_extra()
            for r in due:
                beep("ding")
                self.set_mood("happy", 4)
                msg = "Kon kon! Reminder: %s" % r.get("text", "")
                self.say(msg, 15)
                self.chat_line("Fox", msg)
        if self.quiz and now - self.quiz.get("t", now) > 900:
            self.quiz = None
        # occasional idle yawn
        if self.cfg.get("idle_yawn", True) and not self.session and not self.play and not self.sleeping:
            m = time.monotonic()
            if m >= self.next_yawn:
                self.next_yawn = m + random.uniform(120, 300)
                if self.current_mood() == "idle":
                    self.play = {"kind": "yawn", "t0": m, "dur": self.PLAY_DUR["yawn"]}

    def add_reminder(self, when_epoch, text):
        rem = self.extra.setdefault("reminders", [])
        rem.append({"at": when_epoch, "text": text.strip()[:200]})
        rem.sort(key=lambda r: r["at"])
        self.save_extra()

    def pomo_start(self, work, brk, rounds=4):
        if self.session:
            return "A session is already running. Say 'stop' first, then try again~"
        self.pomo = {"work": work, "brk": brk, "rounds": rounds, "round": 1, "waiting": False}
        self.start_session("Pomodoro 1/%d" % rounds, work)
        return "Pomodoro on! %d rounds of %d min focus + %d min break. Round 1, go~kon!" % (rounds, work, brk)

    def pomo_session_done(self, completed):
        """Called from end_session. Returns True when the pomodoro handled what happens next."""
        p = self.pomo
        if not p:
            return False
        if not completed:
            self.pomo = None
            return False
        if p["round"] >= p["rounds"]:
            self.pomo = None
            self.root.after(2500, lambda: self.say("All %d pomodoros done! Sugoi~! Take a long break, you earned it~kon!" % p["rounds"], 12))
            return True
        p["waiting"] = True
        self.root.after(4000, lambda: self.start_break(p["brk"]) if not (self.session or self.brk) else None)
        return True

    def pomo_break_done(self):
        p = self.pomo
        if not p or not p.get("waiting"):
            return
        p["waiting"] = False
        p["round"] += 1

        def go():
            if self.pomo is p and not self.session:
                self.start_session("Pomodoro %d/%d" % (p["round"], p["rounds"]), p["work"])
        self.root.after(2500, go)

    # ---- weekly report ----------------------------------------------------------------
    def week_report(self):
        st = load_stats()
        today = datetime.date.today()
        days = [today - datetime.timedelta(days=i) for i in range(6, -1, -1)]
        vals = [int(st.get(d.isoformat(), 0) // 60) for d in days]
        prev = sum(int(st.get((today - datetime.timedelta(days=i)).isoformat(), 0) // 60) for i in range(7, 14))
        total = sum(vals)
        top = max(vals + [1])
        lines = ["Your week (%s to %s):" % (days[0].strftime("%a %d %b"), today.strftime("%a %d %b"))]
        for d, v in zip(days, vals):
            bar = "\u2588" * int(round(10.0 * v / top)) if v else "\u00b7"
            lines.append("  %s  %-10s %s" % (d.strftime("%a"), bar, fmt_hm(v) if v else "-"))
        lines.append("Total: %s  ·  daily average %s" % (fmt_hm(total) if total else "0 min", fmt_hm(total // 7) if total >= 7 else "%d min" % (total // 7)))
        if total:
            best = days[vals.index(max(vals))]
            lines.append("Best day: %s (%s)" % (best.strftime("%A"), fmt_hm(max(vals))))
        if prev:
            ch = int(round(100.0 * (total - prev) / prev))
            lines.append("Vs last week: %s%d%%" % ("+" if ch >= 0 else "", ch))
        streak = 0
        for d in reversed(days):
            if int(st.get(d.isoformat(), 0) // 60) >= 10:
                streak += 1
            else:
                break
        lines.append("Focus streak: %d day%s" % (streak, "" if streak == 1 else "s"))
        eaten = sum(int(self.extra.get("eaten", {}).get(d.isoformat(), 0)) for d in days)
        if eaten:
            lines.append("Distractions I ate in lock-in: %d *burp*" % eaten)
        done = [t for t in self.extra.get("todos", []) if t.get("done") and t["done"] >= days[0].isoformat()]
        if done:
            lines.append("To-dos finished: %d" % len(done))
        if total >= 600:
            lines.append("Sugoi~! That's a seriously focused week. I'm so proud of you~kon!")
        elif total >= 180:
            lines.append("Nice work this week, ne~ Let's beat it next week!")
        elif total:
            lines.append("A start is a start! Let's add a little more each day~kon!")
        else:
            lines.append("No focus time yet this week. Double-click me and let's begin, ne~?")
        return "\n".join(lines)

    # ---- the new chat commands ----------------------------------------------------------------
    def quiz_answer(self, text):
        q = self.quiz
        low = text.lower().strip(" !.?")
        if re.match(r"^(stop|end|quit|exit|cancel)( the)? quiz|^no more quiz", low):
            self.quiz = None
            return "Quiz over! You got %d of %d. Otsukare~kon!" % (q["score"], q["i"])
        cards = q["cards"]
        card = cards[q["i"]]
        if low in ("hint", "a hint", "give me a hint"):
            a = card["a"]
            return "Hint: it starts with '%s' and is %d characters long~" % (a[:2], len(a.replace(" ", "")))
        q["t"] = time.time()
        skip = low in ("skip", "next", "pass", "idk", "i don't know", "i dont know", "show answer", "answer", "?")
        ok = (not skip) and answer_close(text, card["a"])
        if ok:
            q["score"] += 1
            beep("happy")
            out = random.choice(["Correct! Yatta~!", "Sugoi! That's right!", "Kon kon~ perfect!"]) + " (%s)" % card["a"]
        else:
            out = ("The answer was: %s" % card["a"]) if skip else ("Ne~ not quite. It was: %s" % card["a"])
        q["i"] += 1
        if q["i"] >= len(cards):
            self.quiz = None
            sc = q["score"]
            verdict = "Perfect score!! Sugoi~!" if sc == len(cards) else ("Great job~kon!" if sc >= len(cards) / 2 else "Let's review and try again, ne~")
            return "%s\n\nDone! You got %d of %d. %s" % (out, sc, len(cards), verdict)
        nxt = cards[q["i"]]
        return "%s\n\nQ%d/%d: %s" % (out, q["i"] + 1, len(cards), nxt["q"])

    def quiz_start(self, topic):
        if not self.cfg.get("web_enabled", True):
            return "Internet lookups are off, so I can't fetch flashcards. Turn them on in Settings~"
        model = self.cfg.get("llm_model") if self.cfg.get("llm_enabled", True) else None

        def job():
            title, text = wiki_long(topic)
            if len(text) < 400:
                res, _ = search_results(topic, 3)
                for r in res[:2]:
                    try:
                        text += "\n" + page_text(r["url"])[1]
                    except Exception:
                        pass
            cards = []
            names = brain_names() if model else None
            if names:
                try:
                    m = pick_model(names, model)
                    j = _ollama_json("/api/chat", {"model": m, "stream": False, "format": "json", "online": True,
                                                   "options": {"temperature": 0.4, "num_predict": 700},
                                                   "messages": [{"role": "user", "content":
                                                                 "Make 6 short study flashcards about '%s' from this text. Reply as JSON "
                                                                 "{\"cards\":[{\"q\":\"question\",\"a\":\"short answer (1-4 words)\"}]}.\n\n%s"
                                                                 % (topic, text[:5000])}]}, 120)
                    got = json.loads(json_latex_fix((j.get("message") or {}).get("content", "{}"))).get("cards") or []
                    cards = [{"q": str(c["q"]).strip(), "a": str(c["a"]).strip()} for c in got if c.get("q") and c.get("a")][:6]
                except Exception:
                    cards = []
            if len(cards) < 3:
                cards = make_flashcards(title or topic, text)
            if not cards:
                raise WebError("Uu~ I couldn't make flashcards on '%s'. Try a more specific topic?" % topic)
            return title or topic, cards

        def done(res, err):
            if err:
                self.fox_reply(str(err) if isinstance(err, WebError) else "Uu~ the flashcards didn't work out (%s)." % err)
                return
            title, cards = res
            self.quiz = {"cards": cards, "i": 0, "score": 0, "topic": title, "t": time.time()}
            self.fox_reply("Kon! %d flashcards on %s. Type your answer, or 'hint', 'skip', 'stop quiz'.\n\nQ1/%d: %s"
                           % (len(cards), title, len(cards), cards[0]["q"]))
        self.bg(job, done)
        return "Kon kon~ making flashcards on '%s'... (one moment)" % topic

    def web_job(self, fn, intro=None):
        if not self.cfg.get("web_enabled", True):
            return "Internet lookups are off. Turn them on in Settings (or right-click me) and ask again~"

        def done(res, err):
            if err:
                self.fox_reply(str(err) if isinstance(err, WebError) else "Uu~ that didn't work (%s)." % err)
            else:
                self.fox_reply(res)
        self.bg(fn, done)
        return intro or "Looking it up~"

    def set_outfit(self, name, on=None):
        cur = list(self.cfg.get("outfit", []))
        if on is None:
            on = name not in cur
        if on and name not in cur:
            cur.append(name)
        if not on and name in cur:
            cur.remove(name)
        self.cfg_set("outfit", cur)
        self.apply_look()
        return on

    def extra_route(self, text):
        raw = text.strip()
        low = raw.lower().strip()
        lw = low.rstrip(" !.?~")
        nm = self.fox_name()
        # --- lock-in
        m = re.match(r"^(?:lock(?:ed)?[ -]?in|lockin|full focus(?: mode)?|focus mode)(?: mode)?(?: on)?(?: for)?\s*(\d{1,3})?\s*(?:m|min|mins|minutes|h|hr|hrs|hours?)?$", lw)
        if m:
            if self.lockin:
                left = int((self.lockin["until"] - time.time()) // 60)
                return "We're already locked in! %d min to go. Say 'unlock' to stop." % max(0, left)
            n = int(m.group(1)) if m.group(1) else None
            if n and re.search(r"\d\s*(h|hr|hrs|hours?)$", lw):
                n *= 60
            return self.lockin_start(n)
        if re.match(r"^(unlock|exit lock[ -]?in|stop lock[ -]?in|end lock[ -]?in|lock[ -]?in off|lock out|i'?m done locking in)$", lw):
            return self.lockin_stop(done=False, quiet=True)
        # --- pomodoro and custom sessions
        m = re.match(r"^(?:pomodoro|pomo|tomato)\s*(?:(\d{1,3})\s*[/:x\- ]\s*(\d{1,3}))?(?:\s*(?:x|times|rounds?)?\s*(\d{1,2})\s*(?:rounds?|x)?)?$", lw)
        if m:
            w, b = int(m.group(1) or 25), int(m.group(2) or 5)
            r = int(m.group(3) or 4)
            return self.pomo_start(max(1, min(180, w)), max(1, min(60, b)), max(1, min(12, r)))
        if re.match(r"^(stop|end|cancel) (the )?pomodoro", lw):
            self.pomo = None
            if self.session:
                self.end_session(False)
            return "Pomodoro stopped. Good effort, ne~"
        m = re.match(r"^(?:focus|study|work)(?: for)?\s+(\d{1,3})\s*(m|min|mins|minutes|h|hr|hrs|hours?)?(?:\s+(?:on|for)\s+(.+))?$", lw)
        if m:
            n = int(m.group(1)) * (60 if (m.group(2) or "").startswith("h") else 1)
            if self.session:
                return "A session is already running. Say 'stop' first."
            task = (m.group(3) or "Focus").strip().capitalize()
            self.start_session(task, max(1, min(600, n)))
            return "Focus session: %d min on \u201c%s\u201d. Ganbatte~kon!" % (n, task)
        # --- reminders
        m = re.match(r"^remind me (?:to )?(.+?) in (\d+(?:\.\d+)?)\s*(seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|hr|h)\b$", lw) or \
            re.match(r"^remind me in (\d+(?:\.\d+)?)\s*(seconds?|secs?|s|minutes?|mins?|m|hours?|hrs?|hr|h)\b\s*(?:to |that |about )?(.+)$", lw)
        if m:
            if m.re.pattern.startswith("^remind me (?:to )?(.+?) in"):
                what, n, unit = m.group(1), float(m.group(2)), m.group(3)
            else:
                n, unit, what = float(m.group(1)), m.group(2), m.group(3)
            sec = n * (3600 if unit.startswith("h") else (1 if unit.startswith("s") else 60))
            what = raw[len(raw) - len(what):] if raw.lower().endswith(what) else what
            self.add_reminder(time.time() + sec, what)
            mn = int(round(sec / 60))
            nice = ("%d sec" % sec) if sec < 60 else (("%d min" % mn) if mn < 60 else ("%d h %02d min" % (mn // 60, mn % 60)))
            return "Okay~ I'll remind you to %s in %s. Kon!" % (what, nice)
        m = re.match(r"^remind me (?:to )?(.+?) at ([\d:.]+\s*(?:am|pm|a|p)?)$", lw) or \
            re.match(r"^remind me at ([\d:.]+\s*(?:am|pm|a|p)?)\s*(?:to |that |about )?(.+)$", lw)
        if m:
            if m.re.pattern.startswith("^remind me at"):
                clock, what = m.group(1), m.group(2)
            else:
                what, clock = m.group(1), m.group(2)
            hm = parse_clock(clock)
            if hm:
                now = datetime.datetime.now()
                t = now.replace(hour=int(hm[:2]), minute=int(hm[3:]), second=0, microsecond=0)
                if t <= now:
                    t += datetime.timedelta(days=1)
                self.add_reminder(t.timestamp(), what)
                return "Okay~ I'll remind you to %s at %s%s." % (what, hm, " tomorrow" if t.date() != now.date() else "")
        if re.match(r"^(my |show |list )?(my )?reminders?$|^what are my reminders", lw):
            rem = self.extra.get("reminders", [])
            if not rem:
                return "No reminders set. Try: remind me in 20 min to stretch"
            return "Your reminders:\n" + "\n".join("  %d. %s  -  %s" % (i + 1, datetime.datetime.fromtimestamp(r["at"]).strftime("%a %H:%M"), r["text"])
                                                   for i, r in enumerate(rem))
        if re.match(r"^(cancel|clear|delete|remove) (all )?(my )?reminders?$", lw):
            n = len(self.extra.get("reminders", []))
            self.extra["reminders"] = []
            self.save_extra()
            return "Cleared %d reminder%s." % (n, "" if n == 1 else "s")
        # --- weekly report
        if re.search(r"how (was|is|did) my week|weekly (report|stats|summary)|week(?:ly)? (?:focus )?report|this week'?s (stats|focus)|my week\b", lw):
            return self.week_report()
        # --- quiz
        if re.match(r"^(stop|end|quit|cancel) (the )?quiz$", lw):
            return "No quiz running. Say 'quiz me on <topic>' to start one~"
        m = re.match(r"^(?:quiz|test) me(?: on| about)?\s+(.+)$|^flash ?cards?(?: on| about| for)?\s+(.+)$", lw)
        if m:
            topic = (m.group(1) or m.group(2) or "").strip()
            if re.search(r"\bnotes?\b", topic) or notes_find(topic)[0]:
                return None                                 # her reMarkable notes quiz handles this
            return self.quiz_start(topic)
        # --- calculator
        m = re.match(r"^(?:calc|calculate|compute|maths?|=)\s*:?\s*(.+)$", lw)
        expr = m.group(1) if m else None
        if not expr and re.fullmatch(r"[\d\s.,+\-*/^()%x×÷=]+", lw) and re.search(r"\d", lw) and re.search(r"[+\-*/^%x×÷]", lw):
            expr = lw
        if not expr:
            mm = re.match(r"^(?:what(?:'s| is)\s+)?(\d[\d.,]*\s*%\s*(?:of|off)\s*\d[\d.,]*|\d[\d.,]*\s*(?:plus|minus|times|divided by|x|\*|/|\+|\-|\^)\s*\d[\d.,]*(?:\s*(?:plus|minus|times|divided by|x|\*|/|\+|\-|\^)\s*\d[\d.,]*)*)\s*\??$", lw)
            expr = mm.group(1) if mm else None
        if expr:
            try:
                v = calc_eval(expr)
                return "%s = %s" % (expr.strip(), fmt_num(v))
            except ZeroDivisionError:
                return "Uwaa~ dividing by zero breaks the universe! Let's not~"
            except Exception:
                if m:
                    return "Hmm hmm~ I couldn't work that out. Try like: calc 15% of 240, or calc (3+4)*2^3"
        # --- define
        m = re.match(r"^(?:define|definition of|meaning of|what does)\s+[\"']?([a-z][a-z\- ']{0,40}?)[\"']?(?:\s+mean)?\s*$", lw)
        if m and (lw.startswith(("define", "definition", "meaning")) or lw.endswith("mean")):
            word = m.group(1).strip()
            return self.web_job(lambda: define_word(word), "Opening my dictionary for '%s'~" % word)
        # --- translate
        m = re.match(r"^translate\s+(.+?)\s+(?:from\s+([a-z ]+?)\s+)?(?:to|into|in)\s+([a-z ]+?)\s*$", raw.strip(" ?!."), re.I)
        if m or re.match(r"^translate\b", lw):
            if not m:
                return "Tell me the language too~ e.g. translate good luck on your exam to Japanese"
            txt, src, dst = m.group(1).strip(" \"'"), (m.group(2) or "").lower().strip(), m.group(3).lower().strip()
            code = LANGS.get(dst) or (dst if re.fullmatch(r"[a-z]{2}(-[a-z]{2})?", dst) else None)
            if not code:
                return "Ne~ I don't know the language '%s'. Try Japanese, Spanish, French, Hindi, Korean..." % dst
            scode = LANGS.get(src, "auto") if src else "auto"

            def job():
                out, roman, eng = translate_text(txt, code, scode)
                extra = ("\n(%s)" % roman) if roman and roman.lower() != out.lower() else ""
                return "%s in %s:\n%s%s\n(%s)" % ("\u201c%s\u201d" % clip(txt, 60), dst.title(), out, extra, eng)
            return self.web_job(job, "Translating to %s~" % dst.title())
        # --- quick notes (her own notes; your reMarkable notes still work too)
        m = re.match(r"^(?:note|take a note|add note|new note|jot(?: down)?)\s*[:\-]\s*(.+)$|^note (?!to self\b)(?!s\b)(.+)$|^note to self[:,]?\s*(.+)$", raw, re.I)
        if m:
            body = (m.group(1) or m.group(2) or m.group(3) or "").strip()
            notes = self.extra.setdefault("notes", [])
            notes.append({"t": datetime.datetime.now().strftime("%Y-%m-%d %H:%M"), "text": body[:1000]})
            self.save_extra()
            return "Noted~ (note %d). Say 'my notes' to see them all." % len(notes)
        if re.match(r"^(my |show (my )?|list (my )?|see (my )?|read (my )?)?(quick )?notes$|^what are my notes", lw):
            notes = self.extra.get("notes", [])
            idx = notes_index()
            out = []
            if notes:
                out.append("Your notes:\n" + "\n".join("  %d. %s  (%s)" % (i + 1, n["text"], n["t"][5:]) for i, n in enumerate(notes[-25:])))
            if idx:
                out.append("reMarkable notebooks I've read: " + ", ".join(sorted(idx)[:12]))
            return "\n\n".join(out) if out else "No notes yet. Try: note: buy more aburaage"
        m = re.match(r"^(?:delete|remove|forget) note\s+#?(\d+)$", lw)
        if m:
            notes = self.extra.get("notes", [])
            i = int(m.group(1)) - 1
            if 0 <= i < len(notes):
                gone = notes.pop(i)
                self.save_extra()
                return "Poof~ deleted note: %s" % clip(gone["text"], 60)
            return "I don't have a note %s." % m.group(1)
        if re.match(r"^(clear|delete|erase) (all )?(my )?(quick )?notes$", lw):
            self.extra["notes"] = []
            self.save_extra()
            return "All your quick notes are cleared~"
        # --- to-dos
        m = re.match(r"^(?:add )?(?:todo|to-do|to do|task)\s*[:\-]?\s+(.+)$", raw, re.I)
        if m and not re.match(r"^(?:todo|to-do|to do)s?\s*(list)?$", lw):
            item = m.group(1).strip()
            if item.lower() not in ("list", "s"):
                todos = self.extra.setdefault("todos", [])
                todos.append({"text": item[:200], "done": None, "added": datetime.date.today().isoformat()})
                self.save_extra()
                left = len([t for t in todos if not t.get("done")])
                return "Added to your to-dos: %s  (%d to go)" % (item, left)
        if re.match(r"^(my |show (my )?|list (my )?|see (my )?)?(to-?dos?|to do|todo list|to-do list|tasks)( list)?$|^what'?s on my (to-?do|to do)", lw):
            todos = self.extra.get("todos", [])
            if not todos:
                return "Your to-do list is empty. Add one: todo finish essay"
            open_ = [t for t in todos if not t.get("done")]
            done_ = [t for t in todos if t.get("done")]
            out = ["To-do:"] + (["  %d. \u2610 %s" % (i + 1, t["text"]) for i, t in enumerate(open_)] or ["  (nothing left, sugoi~!)"])
            if done_:
                out += ["Done:"] + ["  \u2611 %s" % t["text"] for t in done_[-6:]]
            out.append("(say 'done 1' or 'done essay' to tick one off)")
            return "\n".join(out)
        m = re.match(r"^(?:done|finished|completed|tick|check off|did)\s*:?\s+(.+)$", lw)
        if m:
            key = m.group(1).strip()
            open_ = [t for t in self.extra.get("todos", []) if not t.get("done")]
            pick = None
            if key.isdigit() and 1 <= int(key) <= len(open_):
                pick = open_[int(key) - 1]
            else:
                best = difflib.get_close_matches(key, [t["text"].lower() for t in open_], 1, 0.4)
                pick = next((t for t in open_ if best and t["text"].lower() == best[0]), None) or \
                    next((t for t in open_ if key in t["text"].lower()), None)
            if pick:
                pick["done"] = datetime.date.today().isoformat()
                self.save_extra()
                beep("happy")
                self.interact("praise") if random.random() < 0.3 else self.set_mood("happy", 3)
                left = len(open_) - 1
                return "Yatta~! Done: %s. %s" % (pick["text"], ("%d left!" % left) if left else "That's everything! Sugoi~!")
            if open_:
                return None
        if re.match(r"^(clear|delete|remove) (done|finished|completed) (to-?dos?|tasks)$|^clear (my )?(to-?dos?|to do list|todo list)$", lw):
            if "done" in lw or "finished" in lw or "completed" in lw:
                self.extra["todos"] = [t for t in self.extra.get("todos", []) if not t.get("done")]
            else:
                self.extra["todos"] = []
            self.save_extra()
            return "To-do list tidied up~"
        # --- omikuji
        if re.match(r"^(?:draw |get |give me |my |tell my |what'?s my )?(?:an? )?(?:omikuji|fortune|my fortune|today'?s fortune|fortune ?telling|luck)(?: today| please)?$", lw):
            return self.omikuji()
        if re.match(r"^(tie it|tie the fortune|tie it to the branch|tie it to the tree)$", lw):
            o = self.extra.get("omikuji", {})
            if o.get("rank") in ("Kyou", "Suekichi", "Hankichi") and not o.get("tied"):
                o["tied"] = True
                self.save_extra()
                beep("ding")
                return "*ties the paper to the shrine's pine branch* There! The bad luck stays here, and you go on with good luck~kon!"
            return "Ehehe~ that fortune is a good one! Keep it in your wallet for luck~"
        # --- Japanese word of the day
        if re.search(r"word of the day|japanese word|teach me (a )?(japanese|nihongo)|nihongo|today'?s word", lw):
            i = datetime.date.today().toordinal() % len(JP_WORDS)
            if "another" in lw or "more" in lw or "random" in lw:
                i = random.randrange(len(JP_WORDS))
            k, kana, ro, en, ex = JP_WORDS[i]
            return "Today's Japanese word~\n  %s  (%s)  %s\n  = %s\n  e.g. %s" % (k, kana, ro, en, ex)
        # --- sing
        if re.match(r"^(sing|sing (me )?a song|sing for me|sing something|play a tune|koto)$", lw):
            return self.interact("sing")
        # --- outfits and looks
        if re.match(r"^(outfits?|accessor(y|ies)|what can you wear|wardrobe)$", lw):
            on = self.cfg.get("outfit", [])
            return ("I can wear: " + ", ".join(n for n, _ in OUTFITS if n != "glasses_always") + ", glasses (always)."
                    "\nWearing now: %s.\nSay 'outfit crown' to put one on or take it off, 'outfit none' to clear, "
                    "or open the Customize page." % (", ".join(on) if on else "nothing extra"))
        m = re.match(r"^(?:outfit|wear|put on|equip|dress (?:up )?(?:in|as)?|try on)\s+(?:a |an |the |your |my )?(.+)$", lw) or \
            re.match(r"^(take off|remove|unequip)\s+(?:the |your |a )?(.+)$", lw)
        if m:
            off = lw.startswith(("take off", "remove", "unequip"))
            what = m.group(m.lastindex).strip()
            if what in ("none", "nothing", "off", "all", "everything", "default"):
                self.cfg_set("outfit", [])
                self.apply_look()
                return "All accessories off~ Just plain fluffy me!"
            mb = re.match(r"(?:bib|shrine bib|scarf)\s*(\w+)?", what)
            if mb:
                cols = dict((n.lower(), c) for n, c in BIB_COLOURS)
                col = cols.get((mb.group(1) or "red").lower())
                if col is None:
                    return "Bib colours: " + ", ".join(n.lower() for n, _ in BIB_COLOURS[1:])
                self.cfg_set("scarf", "" if off else col)
                self.apply_look()
                return "Bib %s~ How do I look?" % ("off" if off else "on")
            key = OUTFIT_WORDS.get(what) or OUTFIT_WORDS.get(what.split()[0]) or OUTFIT_WORDS.get(what.split()[-1])
            if key:
                on = self.set_outfit(key, False if off else (True if not lw.startswith("outfit") else None))
                self.set_mood("happy", 3)
                beep("happy")
                label = dict(OUTFITS)[key]
                return ("%s on! Ehehe~ kawaii?" % label) if on else ("%s off~" % label)
            if lw.startswith("outfit"):
                return "Ne~ I don't have '%s'. Say 'outfits' to see what I can wear." % what
        m = re.match(r"^(?:coat|fur|change (?:your )?(?:coat|fur)(?: colou?r)?(?: to)?|be)\s+(\w+)(?: fox| coat| fur)?$", lw)
        if m:
            want = m.group(1)
            keys = {k: k for k, _, _ in COATS if k}
            keys.update({lab.lower(): k for k, lab, _ in COATS if k})
            keys.update({"gold": "golden", "red": "orange", "jade": "mint", "pink": "sakura", "desert": "fennec",
                         "dark": "black", "grey": "silver", "gray": "silver", "theme": "", "default": ""})
            if want in keys:
                self.cfg_set("coat", keys[want])
                self.apply_look()
                beep("happy")
                return "New coat: %s! *twirls* Ehehe~" % (dict((k, l) for k, l, _ in COATS).get(keys[want]) or "matching the theme")
            if lw.startswith(("coat", "fur")):
                return "Coats: " + ", ".join(lab.lower() for k, lab, _ in COATS if k)
        m = re.match(r"^(?:your name is|i'?ll call you|call yourself|rename (?:you|yourself)(?: to)?)\s+(.{1,20})$", raw.strip(" .!"), re.I)
        if m:
            self.cfg_set("fox_name", m.group(1).strip().title())
            if self.hub:
                self.root.after(60, lambda: self.hub_side_draw())
            return "Kon! From now on I'm %s! Ehehe~ I like it." % self.fox_name()
        # --- play with her
        m = re.match(r"^(?:give (?:you |her )?|feed (?:you |her )?|here'?s (?:an? |some )?|have (?:an? |some )?|eat (?:an? |some )?)?(?:a |an |some )?(treat|snack|food|inari(?: sushi)?|sushi|aburaage|abura ?age|fried tofu|tofu|dango|onigiri|rice ?ball|mochi)s?\b", lw)
        if m and (re.match(r"^(give|feed|here|have|eat|treat|snack|inari|sushi|aburaage|abura|fried|tofu|dango|onigiri|rice|mochi)", lw)) and len(lw.split()) <= 6:
            word = m.group(1)
            item = TREAT_WORDS.get(word) or next((v for k, v in TREAT_WORDS.items() if k in word), None)
            return self.interact("treat", item)
        if re.match(r"^feed (you|her|zenko|%s)$" % re.escape(nm.lower()), lw):
            return self.interact("treat")
        plays = [
            (r"^(?:\*?(?:head ?pats?|pat ?pat|pats?|pets?|pet you|pet her|headpat you)\*?)(?: (?:you|her|zenko|%s))?$", "pet"),
            (r"^(?:\*?belly ?rubs?\*?|rub (?:your|her) belly)$", "belly"),
            (r"^(?:\*?boop\*?|boop (?:you|your nose|her|the snoot)|\*boops?\*)$", "boop"),
            (r"^(?:\*?tickles?\*?|tickle (?:you|her))$", "tickle"),
            (r"^(?:play with (?:a |the )?(?:ball of )?yarn|yarn|ball of yarn|play ball|play with (?:a |the )?ball|throw (?:the |a )?ball|fetch)$", "yarn"),
            (r"^(?:(?:let'?s |play |wanna )?hide (?:and|n|&) ?seek|hide ?and ?seek)$", "hide"),
            (r"^(?:high ?five|hi ?five|gimme five|paw five|\*high fives?\*|up top)$", "highfive"),
            (r"^(?:give (?:you |her )?a (?:gift|present)|gift|present|here'?s a (?:gift|present)|open (?:a |your )?(?:gift|present))$", "gift"),
            (r"^(?:dance|let'?s dance|do a dance|dance for me|dance party)$", "dance"),
            (r"^(?:brush|brush (?:you|her|your fur|your tails)|groom (?:you|her))$", "brush"),
            (r"^(?:fluff (?:your |her )?tails?|pet (?:your |her )?tails?|touch (?:your |her )?tails?)$", "tail"),
            (r"^(?:good (?:fox|girl|kitsune|zenko)|you'?re (?:cute|adorable|the best|amazing)|i love you|cutie|kawaii)$", "praise"),
            (r"^(?:yawn|are you (?:sleepy|tired))$", "yawn"),
        ]
        for pat, kind in plays:
            if re.match(pat % re.escape(nm.lower()) if "%s" in pat else pat, lw):
                return self.interact(kind)
        if re.match(r"^(?:your |my )?(?:treasures?|treasure box|gifts|presents)(?: box)?$|what (?:gifts|presents) do you have", lw):
            tr = self.extra.get("treasures", [])
            return ("My treasure box: " + ", ".join(tr[-15:]) + ". Ehehe~ I love them all!") if tr else "My treasure box is empty... ne, a gift? *puppy eyes*"
        if re.match(r"^(?:our |my |your )?(?:bond|friendship|affection)(?: level)?$|how much do you like me|do you like me", lw):
            h, name, b = self.bond_text()
            return "Our bond: %s  (%s, %d/100). Pets, treats and focus sessions make it grow~kon!" % (h, name, b)
        if re.match(r"^(?:bad (?:fox|girl|zenko)|you'?re (?:annoying|useless|dumb|stupid|bad)|shut up|go away|i hate you|stupid fox|dumb fox|be quiet)$", lw):
            return self.start_sulk()
        if re.match(r"^(?:sorry|i'?m sorry|im sorry|apologi[sz]e|forgive me|sorry zenko|my bad|gomen(?:nasai)?)!*$", lw):
            if self.sulk_until:
                return self.forgive(via="sorry")
            return "Ehehe~ nothing to be sorry for! *tail wag*"
        return None

    def omikuji(self):
        today = datetime.date.today().isoformat()
        o = self.extra.get("omikuji", {})
        again = o.get("date") == today
        if not again:
            rnd = random.Random()
            pick = rnd.choices(OMIKUJI, weights=[x[4] for x in OMIKUJI])[0]
            kanji, rank, gloss, lvl, _ = pick
            lines = {cat: rnd.choice(OMI_LINES[cat][min(2, lvl)]) for cat in OMI_LINES}
            o = {"date": today, "kanji": kanji, "rank": rank, "gloss": gloss, "lines": lines,
                 "item": rnd.choice(OMI_LUCKY), "colour": rnd.choice(OMI_COLOURS)}
            self.extra["omikuji"] = o
            self.save_extra()
            beep("omikuji")
            self.play = {"kind": "boop" if lvl == 0 else "pet", "t0": time.monotonic(), "dur": 2.4}
        out = ["*shake shake* ...Your omikuji says:" if not again else "You already drew today's omikuji (one a day, ne~):",
               "  %s  %s - %s" % (o["kanji"], o["rank"], o["gloss"])]
        for cat, line in o["lines"].items():
            out.append("  %s: %s" % (cat, line))
        out.append("  Lucky item: %s  ·  Lucky colour: %s" % (o["item"], o["colour"]))
        if o["rank"] in ("Kyou", "Suekichi", "Hankichi") and not o.get("tied"):
            out.append("Don't worry~ say 'tie it' and I'll tie it to the shrine branch so the bad luck stays behind!")
        elif o["rank"] in ("Daikichi", "Kichi"):
            out.append("Sugoi~! Inari is smiling on you today!")
        return "\n".join(out)

    # ---- right-click menu extras --------------------------------------------------------------
    def menu_extras(self, m):
        pm = tk.Menu(m, tearoff=0)
        for lab, kind in (("Headpat", "pet"), ("Belly rub", "belly"), ("Boop her nose", "boop"), ("Tickle", "tickle"),
                          ("Fluff her tails", "tail"), ("Ball of yarn", "yarn"), ("Hide and seek", "hide"),
                          ("High five", "highfive"), ("Give her a gift", "gift"), ("Dance", "dance"),
                          ("Brush her fur", "brush"), ("Sing a song", "sing")):
            pm.add_command(label=lab, command=lambda k=kind: self.interact(k))
        fm = tk.Menu(pm, tearoff=0)
        for t in TREATS:
            fm.add_command(label=t.title(), command=lambda t=t: self.interact("treat", t))
        pm.add_cascade(label="Feed her a treat", menu=fm)
        if self.sulk_until:
            pm.add_command(label="Say sorry", command=lambda: self.forgive(via="sorry"))
        pm.add_separator()
        pm.add_command(label="Draw an omikuji fortune", command=lambda: self.fox_reply(self.omikuji()))
        pm.add_command(label="Japanese word of the day", command=lambda: self.fox_reply(self.extra_route("word of the day")))
        m.add_cascade(label="Play with %s" % self.fox_name(), menu=pm)
        if self.lockin:
            left = int((self.lockin["until"] - time.time()) // 60)
            m.add_command(label="Exit lock-in (%d min left)" % max(0, left), command=lambda: self.lockin_stop(False))
        else:
            m.add_command(label="Lock-in mode (%d min)" % int(self.cfg.get("lockin_minutes", 50) or 50),
                          command=lambda: self.lockin_start(None))
        m.add_command(label="Customize %s..." % self.fox_name(), command=lambda: self.open_hub("customize"))

    # ==== the Customize page ====================================================================
    def hub_build_customize(self, pg):
        self.hub_title(pg, "Customize %s" % self.fox_name(), "Her coat, eyes, foxfire, outfits, voice and little habits. Changes show up right away.")
        outer = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        outer.pack(fill="x", padx=24, pady=12)
        left = tk.Frame(outer, bg=PAPER)
        left.pack(side="left", fill="y", anchor="n", padx=(0, 8))
        right = tk.Frame(outer, bg=PAPER)
        right.pack(side="left", fill="both", expand=True, padx=(8, 0))
        rcol1 = tk.Frame(right, bg=PAPER)
        rcol1.pack(side="left", fill="both", expand=True, anchor="n")
        rcol2 = rcol1
        bg = T["card"]
        kw = dict(bg=bg, fg=INK, activebackground=bg, activeforeground=GOLD, selectcolor=FIELD, highlightthickness=0,
                  font=(FONT_UI, 10), anchor="w")

        def label(parent, text):
            tk.Label(parent, text=text, bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w", justify="left",
                     wraplength=330).pack(fill="x", padx=14, pady=(6, 0))

        def check(parent, text, key, default=True, after=None):
            v = tk.BooleanVar(value=bool(self.cfg.get(key, default)))

            def cmd():
                self.cfg_set(key, bool(v.get()))
                if after:
                    after()
            tk.Checkbutton(parent, text=text, variable=v, command=cmd, **kw).pack(fill="x", padx=14)
            return v

        def radios(parent, items, key, default, after=None, cast=str):
            v = tk.StringVar(value=str(self.cfg.get(key, default)))
            f = tk.Frame(parent, bg=bg)
            f.pack(fill="x", padx=14, pady=(0, 4))

            def cmd():
                self.cfg_set(key, cast(v.get()))
                if after:
                    after()
            for i, (lab, val) in enumerate(items):
                tk.Radiobutton(f, text=lab, value=str(val), variable=v, command=cmd, **kw).grid(row=i // 4, column=i % 4, sticky="w", padx=(0, 8))
            return v

        def swatches(parent, opts, key, after=None, coat=False):
            row = tk.Frame(parent, bg=bg)
            row.pack(fill="x", padx=12, pady=(2, 6))
            cvs = []

            def draw():
                cur = self.cfg.get(key, "")
                for cv, val, col in cvs:
                    cv.delete("all")
                    on = cur == val
                    cv.create_oval(2, 2, 28, 28, outline=GOLD if on else _mixhex(bg, INK, 0.12), width=3 if on else 1)
                    if coat and val and col in FUR:
                        fp = FUR[col]
                        cv.create_oval(7, 7, 23, 23, fill=fp["O"], outline=fp["K"], width=2)
                        cv.create_arc(7, 7, 23, 23, start=200, extent=140, style="chord", fill=fp["W"], outline="")
                        cv.create_oval(7, 7, 23, 23, outline=fp["K"], width=2)
                    elif col and not coat:
                        cv.create_oval(7, 7, 23, 23, fill=col, outline=LINE)
                    else:
                        cv.create_oval(7, 7, 23, 23, fill=bg, outline=GREY)
                        cv.create_line(10, 20, 20, 10, fill=GREY, width=2)

            def pick(val):
                self.cfg_set(key, val)
                ui_sound("toggle")
                self.apply_look()
                draw()
                if after:
                    after()
            for i, (lab, val, col) in enumerate(opts):
                f = tk.Frame(row, bg=bg)
                f.grid(row=i // 6, column=i % 6, padx=2, pady=2)
                cv = tk.Canvas(f, width=30, height=30, bg=bg, highlightthickness=0, cursor="hand2")
                cv.pack()
                lb = tk.Label(f, text=lab, bg=bg, fg=GREY, font=(FONT_UI, 8), cursor="hand2")
                lb.pack()
                for w_ in (cv, lb):
                    w_.bind("<Button-1>", lambda e, v=val: pick(v))
                cvs.append((cv, val, col))
            draw()

        # --- live preview
        c = self.hub_card(left, "Live preview")
        c.pack(fill="x")
        pz = 3
        self.cz_zoom = pz
        pbg = _mixhex(T["card"], NIGHT, 0.55)
        cv = tk.Canvas(c, width=W_ * pz + 20, height=H_ * pz + 20, bg=pbg, highlightthickness=1, highlightbackground=LINE)
        cv.pack(padx=14, pady=(4, 6))
        self.cz_cv = cv
        self.cz_items = (cv.create_image(10, 10, anchor="nw"), cv.create_image(10, 10, anchor="nw"))
        rnd = random.Random(3)
        for _ in range(26):
            x, y = rnd.uniform(4, W_ * pz + 16), rnd.uniform(4, H_ * pz * 0.6)
            cv.create_rectangle(x, y, x + 2, y + 2, fill=_mixhex(pbg, INK, rnd.uniform(0.2, 0.6)), outline="")
        cv.create_text(14, H_ * pz + 12, text="", anchor="w", fill=GREY, font=(FONT_UI, 9), tags="nm")
        cv.tag_lower("all")
        cv.tag_raise(self.cz_items[0])
        cv.tag_raise(self.cz_items[1])
        cv.bind("<Button-1>", lambda e: self.fox_clicked(self.COLW + (e.x - 10) / pz * self.Z, self.fox_y + (e.y - 10) / pz * self.Z))
        label(c, "Try a mood (or click her: head, nose, belly and tails all react differently)")
        mf = tk.Frame(c, bg=bg)
