    def vv_autostart(self, force=False, on_done=None):
        """Open the VOICEVOX engine hidden in the background when her voice is VOICEVOX (never freezes the UI).
        on_done(state, path, error) runs on the UI thread; state is running | started | notfound | exited | timeout."""
        if not force and (self.cfg.get("voice_clips") != "voicevox" or not self.cfg.get("voicevox_autostart", True)):
            return
        if on_done:
            VV_ENGINE["waiters"].append(on_done)
        if VV_ENGINE.get("busy"):
            return
        VV_ENGINE["busy"] = True
        saved = self.cfg.get("voicevox_engine_path", "") or ""

        def job():
            if voicevox_alive():
                return "running", saved
            path = voicevox_find_engine(saved)
            if not path:
                return "notfound", ""
            return voicevox_start_engine(path), path

        def done(res, err):
            VV_ENGINE["busy"] = False
            st, path = res if res else ("error", "")
            if path and path != saved:
                self.cfg_set("voicevox_engine_path", path)
            if st in ("running", "started") and self.cfg.get("voice_clips") == "voicevox":
                sid = int(self.cfg.get("voicevox_speaker", 8) or 8)
                self.bg(lambda: voicevox_make_clips(sid))      # makes any clips still missing
            ws, VV_ENGINE["waiters"] = VV_ENGINE["waiters"], []
            for w in ws:
                try:
                    w(st, path, err)
                except Exception:
                    pass
        self.bg(job, done)

    def voice_demo(self):
        prepare_voice_clips()
        beep(random.choice(["hello", "pet", "happy", "giggle"]))

    def cz_anim(self):
        """Animate the Customize preview: the same pose as the desktop fox, bigger."""
        cv = getattr(self, "cz_cv", None)
        h = getattr(self, "hub", None)
        if cv is None or not h:
            return
        try:
            if not cv.winfo_exists():
                self.cz_cv = None
                return
        except tk.TclError:
            self.cz_cv = None
            return
        if h.get("page") == "customize" and self._pose:
            p = self._pose
            if str(p.get("state", "")).startswith(("qwalk", "rig")):
                p = dict(p, state="idle", dyf=0, dxf=0)          # the preview shows her sitting while she walks about
            z = self.cz_zoom
            cache = self.cz_cache
            if len(cache) > 90:
                cache.clear()
            ti, bi = self.cz_items
            dyf = p.get("dyf", 0)
            dxf = p.get("dxf", 0)
            if p["curled"]:
                cv.itemconfigure(ti, state="hidden")
                k = ("c", p["frame"], p["acc"], p["n"])
                if k not in cache:
                    cache[k] = sprite_photo([build_curl(p["frame"], p["acc"], p["n"])], self.pal, z)
            else:
                tk_ = ("t", p["n"], p["tframe"])
                if tk_ not in cache:
                    cache[tk_] = sprite_photo([build_tails(p["n"], p["tframe"], shadow=False)], self.pal, z)
                cv.itemconfigure(ti, image=cache[tk_], state="normal")
                k = ("b", p["state"], p["frame"], p["look"], p["acc"], p["hx"], p["ear"])
                if k not in cache:
                    cache[k] = sprite_photo([build_frame(p["state"], "up", p["frame"], p["look"], p["acc"], p["hx"], p["ear"])], self.pal, z)
            cv.itemconfigure(bi, image=cache[k])
            for it in (ti, bi):
                cv.coords(it, 10 + dxf * z, 10 + min(dyf, 60) * z)
            hs, nm, b = self.bond_text()
            try:
                cv.itemconfigure("nm", text="%s  ·  %s" % (self.fox_name(), self.catchphrase()))
                cv.tag_raise("nm")
                self.cz_bond.config(text="Bond  %s   %s" % (hs, nm))
            except tk.TclError:
                pass
        cv.after(70, self.cz_anim)

    # ==== Settings: lock-in card ===================================================================
    def hub_lockin_card(self, parent):
        bg = T["card"]
        c = self.hub_card(parent, "Lock-in mode")
        c.pack(fill="x", pady=(12, 0))
        kw = dict(bg=bg, fg=INK, activebackground=bg, activeforeground=GOLD, selectcolor=FIELD, highlightthickness=0,
                  font=(FONT_UI, 10), anchor="w")
        tk.Label(c, text="The moment a distracting site or app comes to the front, she pounces on it, eats it, and sends you "
                         "back to work. Exit any time: say 'unlock', right-click her > Exit lock-in, or hold Esc for 2 seconds.",
                 bg=bg, fg=GREY, font=(FONT_UI, 9), wraplength=420, justify="left", anchor="w").pack(fill="x", padx=14, pady=(2, 6))
        row = tk.Frame(c, bg=bg)
        row.pack(fill="x", padx=14, pady=(0, 6))
        tk.Label(row, text="Length", bg=bg, fg=INK, font=(FONT_UI, 10)).pack(side="left")
        mv = tk.StringVar(value=str(self.cfg.get("lockin_minutes", 50)))
        me = self.tt_entry(row, mv, 4)
        me.pack(side="left", padx=6)
        tk.Label(row, text="min", bg=bg, fg=INK, font=(FONT_UI, 10)).pack(side="left")
        st = tk.Label(c, text="", bg=bg, fg=ORANGE_D, font=(FONT_UI, 9, "bold"), anchor="w")

        def mins_now():
            try:
                n = max(1, min(600, int(float(mv.get()))))
            except ValueError:
                n = 50
            self.cfg_set("lockin_minutes", n)
            return n

        def toggle():
            if self.lockin:
                self.lockin_stop(False)
            else:
                self.lockin_start(mins_now())
            st.config(text="Locked in." if self.lockin else "Lock-in is off.")
            btn.configure(text="Exit lock-in" if self.lockin else "Start lock-in")
        btn = self.tt_btn(row, "Exit lock-in" if self.lockin else "Start lock-in", toggle, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=2)
        btn.pack(side="left", padx=(12, 0))
        st.pack(fill="x", padx=14)
        v = tk.StringVar(value=self.cfg.get("lockin_action", "smart"))
        tk.Label(c, text="What she does with a distraction", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=14, pady=(6, 0))
        for lab, val in (("Smart: close just that browser tab, hide other apps", "smart"),
                         ("Hide it (minimise the window)", "minimise"),
                         ("Close it (tab or the whole app)", "close")):
            tk.Radiobutton(c, text=lab, value=val, variable=v, command=lambda: self.cfg_set("lockin_action", v.get()), **kw
                           ).pack(fill="x", padx=14)
        for text, key in (("Start a focus session with it", "lockin_session"), ("Play the pounce-and-eat animation", "lockin_animation")):
            bv = tk.BooleanVar(value=bool(self.cfg.get(key, True)))
            tk.Checkbutton(c, text=text, variable=bv, command=lambda k=key, bv=bv: self.cfg_set(k, bool(bv.get())), **kw
                           ).pack(fill="x", padx=14)
        tk.Label(c, text="Extra things that count in lock-in (one per line: a word in the window title, or an app like discord.exe). "
                         "Your normal distracting sites always count too.",
                 bg=bg, fg=GREY, font=(FONT_UI, 9), wraplength=420, justify="left", anchor="w").pack(fill="x", padx=14, pady=(8, 2))
        t = tk.Text(c, width=40, height=5, font=("Consolas", 10), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                    highlightthickness=1, highlightbackground=LINE)
        t.pack(anchor="w", padx=14, pady=2)
        t.insert("1.0", "\n".join(self.cfg.get("lockin_extra", [])))
        r2 = tk.Frame(c, bg=bg)
        r2.pack(fill="x", padx=14, pady=(4, 12))

        def save():
            items = [x.strip().lower() for x in t.get("1.0", "end").splitlines() if x.strip()]
            self.cfg_set("lockin_extra", items)
            st.config(text="Saved %d extra item%s." % (len(items), "" if len(items) == 1 else "s"))
        self.tt_btn(r2, "Save list", save, bg=T["start"], size=9, padx=10, pady=2).pack(side="left")
        self.tt_btn(r2, "Edit distracting sites...", self.edit_distractions, bg=FIELD, size=9, padx=10, pady=2).pack(side="left", padx=(8, 0))


