# ---- soothing background music (made right here on this PC, nothing downloaded) ----------------------
MUSIC_TRACKS = [("garden", "Shrine garden", "soft koto, a low hum and a glass wind chime"),
                ("bamboo", "Bamboo rain", "a breathy bamboo flute over gentle rain"),
                ("temple", "Moon temple", "slow temple bowls and a deep, calm drone")]
MUSIC_LEN = 72.0            # seconds; the piece loops seamlessly
_SCALES = {"yo": [0, 2, 5, 7, 9], "minyo": [0, 3, 5, 7, 10], "in": [0, 1, 5, 7, 8]}


def _hz(semi, base=293.66):
    """Semitones above D4."""
    return base * (2.0 ** (semi / 12.0))


def _scale_note(scale, step, base=293.66):
    s = _SCALES[scale]
    octv, i = divmod(step, len(s))
    return _hz(s[i] + 12 * octv, base)


def _flute(freq, dur, seed=0):
    """A breathy bamboo flute (shakuhachi-like): a soft tone that swells, wavers and fades, with breath noise."""
    from array import array
    rnd = random.Random(seed)
    n = int(dur * SR)
    out = array("f", bytes(4 * n))
    ph, lp = 0.0, 0.0
    att, rel = int(0.35 * SR), int(0.7 * SR)
    for i in range(n):
        t = i / float(SR)
        vib = 1.0 + (0.006 * math.sin(2 * math.pi * 4.8 * t) * min(1.0, max(0.0, t - 0.5) / 0.6))
        ph += 2 * math.pi * freq * vib / SR
        env = min(1.0, i / float(att)) * min(1.0, (n - i) / float(rel))
        lp += 0.08 * (rnd.uniform(-1, 1) - lp)
        out[i] = env * (0.62 * math.sin(ph) + 0.16 * math.sin(2 * ph) + 0.05 * math.sin(3 * ph) + 0.55 * lp * (0.6 + 0.4 * env))
    return out


def _pad(freq, dur, swell=16.0):
    """A low, slowly breathing hum under everything."""
    from array import array
    n = int(dur * SR)
    out = array("f", bytes(4 * n))
    w1, w2 = 2 * math.pi * freq / SR, 2 * math.pi * freq * 1.5 / SR
    ws = 2 * math.pi / (swell * SR)
    for i in range(n):
        a = 0.55 + 0.45 * math.sin(ws * i)
        out[i] = a * (0.7 * math.sin(w1 * i) + 0.25 * math.sin(w2 * i + 1.3))
    return out


def _rain(dur, seed=11):
    """Gentle rain: soft filtered noise plus the odd drip."""
    from array import array
    rnd = random.Random(seed)
    n = int(dur * SR)
    out = array("f", bytes(4 * n))
    lp1 = lp2 = 0.0
    for i in range(n):
        x = rnd.uniform(-1, 1)
        lp1 += 0.35 * (x - lp1)
        lp2 += 0.02 * (lp1 - lp2)
        out[i] = (lp1 - lp2) * 0.9
    return out


def _mix_into(buf, start_s, samples, gain):
    """Add samples into the looping buffer (wrapping round the end, so the loop is seamless)."""
    L = len(buf)
    o = int(start_s * SR) % L
    for i, v in enumerate(samples):
        j = o + i
        if j >= L:
            j %= L
        buf[j] += v * gain


def music_samples(track, length=MUSIC_LEN, seed=7):
    """Build one looping piece. Original music, composed by rules in Japanese pentatonic scales."""
    from array import array
    rnd = random.Random(seed + len(track))
    L = int(length * SR)
    buf = array("f", bytes(4 * L))
    if track == "bamboo":
        _mix_into(buf, 0, _rain(length), 0.05)
        _mix_into(buf, 0, _pad(_hz(-24), length, 24.0), 0.06)
        t, step = 1.5, 5
        while t < length - 0.5:
            for _ in range(rnd.randint(3, 5)):
                step = max(3, min(11, step + rnd.choice((-2, -1, -1, 1, 1, 2))))
                d = rnd.choice((1.8, 2.4, 3.2))
                _mix_into(buf, t, _flute(_scale_note("minyo", step, 293.66 / 2), d + 0.6, int(t * 10)), 0.20)
                t += d
            if rnd.random() < 0.6:
                _mix_into(buf, t + 0.3, _koto(_scale_note("minyo", rnd.randint(0, 4), 293.66 / 2), 2.2, 0.3, int(t)), 0.16)
            t += rnd.uniform(3.0, 5.0)
    elif track == "temple":
        _mix_into(buf, 0, _pad(_hz(-24), length, 20.0), 0.10)
        _mix_into(buf, 0, _pad(_hz(-17), length, 29.0), 0.05)
        t = 0.8
        bowls = [_hz(-5), _hz(0), _hz(2), _hz(7)]
        while t < length - 0.5:
            f = rnd.choice(bowls)
            _mix_into(buf, t, _bell(f, 7.0, ((1, 0.6), (2.71, 0.25), (5.15, 0.08), (0.5, 0.2)), 2.4, int(t)), 0.16)
            if rnd.random() < 0.45:
                _mix_into(buf, t + rnd.uniform(2.0, 3.5),
                          _koto(_scale_note("in", rnd.randint(5, 9)), 2.0, 0.35, int(t * 3)), 0.12)
            t += rnd.uniform(6.5, 10.0)
    else:   # garden
        _mix_into(buf, 0, _pad(_hz(-24), length, 16.0), 0.07)
        t, step = 0.6, 7
        while t < length - 0.5:
            n = rnd.randint(4, 6)
            for k in range(n):
                step = max(2, min(12, step + rnd.choice((-2, -1, -1, 1, 1, 2, 0))))
                f = _scale_note("yo", step, 293.66 / 2)
                _mix_into(buf, t, _koto(f, 2.4, 0.45, int(t * 7) + k), 0.30)
                if k == 0 or rnd.random() < 0.25:
                    _mix_into(buf, t, _koto(f / 2, 2.6, 0.3, int(t * 5) + k), 0.14)
                t += rnd.choice((0.55, 0.7, 0.85, 1.1))
            if rnd.random() < 0.55:
                st = t + rnd.uniform(0.3, 1.2)
                for (s0, sm, g) in _furin(0.0, rnd.choice((2093.0, 2349.0, 2637.0)), 0.25):
                    _mix_into(buf, st + s0, sm, g * 0.5)
            t += rnd.uniform(2.6, 4.2)
    # a soft room echo (multi-tap, wrapping, so the loop stays seamless) and a gentle top-end roll-off
    dry = array("f", buf)
    for d_s, g in ((0.113, 0.22), (0.197, 0.17), (0.293, 0.13), (0.419, 0.10), (0.587, 0.07), (0.811, 0.05)):
        d = int(d_s * SR)
        for i in range(L):
            buf[i] += dry[i - d] * g
    lp = buf[-1]
    for i in range(L):
        lp += 0.55 * (buf[i] - lp)
        buf[i] = lp
    return buf


def music_file(track):
    """The .wav for a background track (composed once, then kept in the sounds folder)."""
    import struct
    import wave
    track = track if track in dict((k, 1) for k, _, _ in MUSIC_TRACKS) else "garden"
    p = os.path.join(SOUND_DIR, "bgm_%s_v1.wav" % track)
    if os.path.exists(p):
        return p
    buf = music_samples(track)
    peak = max(1e-6, max(abs(v) for v in buf))
    rms = max(1e-6, math.sqrt(sum(v * v for v in buf) / len(buf)))
    k = min(0.9 / peak, 0.1 / rms)                  # every track equally quiet, never clipping
    os.makedirs(SOUND_DIR, exist_ok=True)
    tmp = p + ".part"
    w = wave.open(tmp, "wb")
    w.setnchannels(1)
    w.setsampwidth(2)
    w.setframerate(SR)
    chunk = 44100
    for s in range(0, len(buf), chunk):
        part = buf[s:s + chunk]
        w.writeframes(struct.pack("<%dh" % len(part), *[int(max(-1.0, min(1.0, v * k)) * 32767) for v in part]))
    w.close()
    os.replace(tmp, p)
    return p


def music_gain(vol):
    """Volume level 1-10 -> loudness multiplier. Level 1 is about -33 dB (well under a whisper), each step adds 3 dB."""
    vol = max(1, min(10, int(vol)))
    return 10.0 ** ((-33.0 + 3.0 * (vol - 1)) / 20.0)


def music_file_vol(track, vol):
    """The track with its volume baked into the file, so it is quiet even when Windows ignores MCI volume.
    Only the file for the current level is kept (older levels are tidied away)."""
    import array as _arr
    import wave
    base = music_file(track)
    vol = max(1, min(10, int(vol)))
    p = os.path.join(SOUND_DIR, "bgm_%s_v1_q%02d.wav" % (track if track in dict((k, 1) for k, _, _ in MUSIC_TRACKS) else "garden", vol))
    if os.path.exists(p):
        return p
    r = wave.open(base, "rb")
    rate, width, nch = r.getframerate(), r.getsampwidth(), r.getnchannels()
    data = r.readframes(r.getnframes())
    r.close()
    a = _arr.array("h")
    a.frombytes(data)
    if sys.byteorder != "little":
        a.byteswap()
    g = music_gain(vol)
    out = _arr.array("h", (int(v * g) for v in a))
    if sys.byteorder != "little":
        out.byteswap()
    tmp = p + ".part"
    w = wave.open(tmp, "wb")
    w.setnchannels(nch)
    w.setsampwidth(width)
    w.setframerate(rate)
    w.writeframes(out.tobytes())
    w.close()
    os.replace(tmp, p)
    try:
        for f in os.listdir(SOUND_DIR):
            if f.startswith("bgm_") and "_q" in f and f.endswith(".wav") and os.path.join(SOUND_DIR, f) != p:
                os.remove(os.path.join(SOUND_DIR, f))
    except Exception:
        pass
    return p


class BackgroundMusic:
    """Loops a track quietly with Windows' own media player engine (MCI), so it plays alongside her other sounds."""
    ALIAS = "zenko_bgm"

    def __init__(self):
        self.track = None
        self.open = False
        self.vol = 3
        self.busy = False

    def _mci(self, cmd):
        if not IS_WIN:
            return 1
        buf = ctypes.create_unicode_buffer(256)
        try:
            err = ctypes.windll.winmm.mciSendStringW(cmd, buf, 255, 0)
        except Exception:
            return 1
        self._last = buf.value
        return err

    def mode(self):
        if not self.open or self._mci("status %s mode" % self.ALIAS):
            return ""
        return getattr(self, "_last", "")

    def play(self, track, vol):
        """Start (or switch) the track. Returns False if it can't play here."""
        if not IS_WIN:
            self.track = track
            return False
        p = music_file_vol(track, vol)
        if self.open and self.track == track and getattr(self, "path", "") == p:
            if self.mode() != "playing":
                self._mci("play %s from 0 repeat" % self.ALIAS) and self._mci("play %s from 0" % self.ALIAS)
            return True
        self.stop()
        if self._mci('open "%s" type mpegvideo alias %s' % (p, self.ALIAS)):
            if self._mci('open "%s" type waveaudio alias %s' % (p, self.ALIAS)):
                return False
        self.open, self.track, self.path = True, track, p
        self.set_volume(vol)
        if self._mci("play %s repeat" % self.ALIAS):
            self._mci("play %s" % self.ALIAS)
        return True

    def set_volume(self, vol):
        self.vol = max(1, min(10, int(vol)))
        if self.open:
            self._mci("setaudio %s volume to 1000" % self.ALIAS)       # the quietness is baked into the file itself

    def keep_going(self):
        """Called every few seconds: restart the loop if Windows stopped it."""
        if self.open and self.mode() == "stopped":
            self._mci("play %s from 0" % self.ALIAS)

    def stop(self):
        if self.open:
            self._mci("stop %s" % self.ALIAS)
            self._mci("close %s" % self.ALIAS)
        self.open = False


