PLAN_KINDS = ("Exam", "Quiz", "Assignment", "Project", "Presentation", "Deadline")
PLAN_HOURS = {"Exam": 6, "Quiz": 2, "Assignment": 4, "Project": 5, "Presentation": 3, "Deadline": 2}
DEFAULT_FREE = {"0": [16, 17, 18, 19], "1": [16, 17, 18, 19], "2": [16, 17, 18, 19], "3": [16, 17, 18, 19],
                "4": [16, 17, 18], "5": [10, 11, 14, 15, 16], "6": [10, 11, 14, 15, 16]}
DAY_NAMES = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
KANJI_NUM = ["十二", "一", "二", "三", "四", "五", "六", "七", "八", "九", "十", "十一"]
WORD_NUM = {"a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8,
            "nine": 9, "ten": 10, "eleven": 11, "twelve": 12, "couple of": 2, "a couple of": 2, "few": 3, "a few": 3}


def deadline_due(d):
    """When a deadline is due, as a datetime (no time given = the start of that day)."""
    day = datetime.date.fromisoformat(d["date"])
    t = d.get("time") or ""
    if re.match(r"^\d\d:\d\d$", t):
        h, m = map(int, t.split(":"))
        return datetime.datetime(day.year, day.month, day.day, h, m)
    return datetime.datetime(day.year, day.month, day.day, 8, 0)


def plan_study(targets, free_hours, busy, now, session_min=50, day_cap=4, horizon=45):
    """Spread study sessions over your free hours before each exam/deadline.

    targets: [{"id", "title", "due" (datetime), "need" (minutes still to study)}]
    free_hours(date) -> sorted list of hours you're free (17 = 17:00-18:00)
    busy(date) -> [(start_minute, end_minute)] already on the timetable that day
    Returns (sessions, short) where sessions = [{"date", "start", "mins", "id", "title", "review"}] and
    short = {id: minutes that didn't fit}."""
    targets = [dict(t) for t in targets if t["need"] > 0 and t["due"] > now]
    if not targets:
        return [], {}
    last = min(max(t["due"] for t in targets).date(), now.date() + datetime.timedelta(days=horizon))
    slots = []
    day = now.date()
    while day <= last:
        taken = busy(day)
        for h in free_hours(day):
            st = datetime.datetime(day.year, day.month, day.day, int(h), 0)
            if st < now + datetime.timedelta(minutes=5):
                continue
            a, b = int(h) * 60, int(h) * 60 + session_min
            if any(a < e and s < b for s, e in taken):
                continue
            slots.append(st)
        day += datetime.timedelta(days=1)
    slots.sort()
    sess_n = {t["id"]: int(math.ceil(t["need"] / float(session_min))) for t in targets}
    per_day = {}
    out = []
    for k, st in enumerate(slots):
        en = st + datetime.timedelta(minutes=session_min)
        best, best_r = None, None
        for t in targets:
            if sess_n[t["id"]] <= 0 or en > t["due"] - datetime.timedelta(minutes=30):
                continue
            left = sum(1 for s2 in slots[k:] if s2 + datetime.timedelta(minutes=session_min) <= t["due"] - datetime.timedelta(minutes=30))
            ratio = left / float(sess_n[t["id"]])                 # how much spare room this one has (small = urgent)
            if per_day.get((st.date(), t["id"]), 0) >= day_cap and ratio > 1.0:
                continue
            if best is None or ratio < best_r or (ratio == best_r and t["due"] < best["due"]):
                best, best_r = t, ratio
        if not best:
            continue
        sess_n[best["id"]] -= 1
        per_day[(st.date(), best["id"])] = per_day.get((st.date(), best["id"]), 0) + 1
        out.append({"date": st.date().isoformat(), "start": st.strftime("%H:%M"), "mins": session_min,
                    "id": best["id"], "title": best["title"], "review": sess_n[best["id"]] == 0})
    short = {t["id"]: sess_n[t["id"]] * session_min for t in targets if sess_n[t["id"]] > 0}
    return out, short


def parse_rel_date(text, today=None):
    """'in 2 days', 'in a week', 'tomorrow', 'day after tomorrow', 'on friday', 'next monday', '12 dec' -> date or None."""
    today = today or datetime.date.today()
    low = text.lower()
    m = re.search(r"\bin\s+(\d{1,3}|a couple of|a few|couple of|few|an?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\s+(day|days|week|weeks)\b", low)
    if m:
        n = int(m.group(1)) if m.group(1).isdigit() else WORD_NUM.get(m.group(1), 1)
        return today + datetime.timedelta(days=n * (7 if m.group(2).startswith("week") else 1))
    if re.search(r"\b(?:the )?day after tomorrow\b", low):
        return today + datetime.timedelta(days=2)
    m = re.search(r"\b(?:on |this |next |coming )?(mon|tues?|wed(?:nes)?|thu(?:rs?)?|fri|sat(?:ur)?|sun)(?:day)?\b", low)
    ds = find_dates(text, today)
    if ds:
        return ds[0][0]
    if m:
        names = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
        target = names.index(m.group(1)[:3])
        ahead = (target - today.weekday()) % 7 or 7
        return today + datetime.timedelta(days=ahead)
    if re.search(r"\btomorrow\b", low):
        return today + datetime.timedelta(days=1)
    if re.search(r"\btoday\b|\btonight\b", low):
        return today
    return None


def parse_hour(s, pm_hint=None):
    """'5', '5pm', '17', '17:30', '5.30pm' -> hour 0-23 (minutes are rounded down), or None."""
    m = re.match(r"^\s*(\d{1,2})(?:[:.](\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?\s*$", s or "", re.I)
    if not m:
        return None
    h = int(m.group(1))
    ap = (m.group(3) or "").lower().replace(".", "")
    if ap:
        if not 1 <= h <= 12:
            return None
        return h % 12 + (12 if ap == "pm" else 0)
    if h > 24:
        return None
    if pm_hint and 1 <= h <= 11:
        return h + 12
    return h % 24


def parse_free_time(text, today=None):
    """"I'm free 4-7pm on weekdays" -> (["0".."4"] or ["2026-11-20"], [16, 17, 18]) or None."""
    today = today or datetime.date.today()
    low = text.lower().strip(" .!~")
    if not re.search(r"\b(?:free|available|can study|study time)\b", low):
        return None
    m = re.search(r"(?:from\s+|between\s+)?(\d{1,2}(?:[:.]\d{2})?\s*(?:am|pm|a\.m\.|p\.m\.)?)\s*(?:-|–|to|till|until|and)\s*"
                  r"(\d{1,2}(?:[:.]\d{2})?\s*(?:am|pm|a\.m\.|p\.m\.)?)", low)
    if not m:
        return None
    b_raw = m.group(2)
    a_raw = m.group(1)
    pm = bool(re.search(r"pm|p\.m\.", b_raw)) or bool(re.search(r"\b(evening|afternoon|tonight|night)\b", low))
    if not re.search(r"am|pm|a\.m\.|p\.m\.|:", m.group(0)) and re.match(r"\s*\d+", a_raw) and int(re.match(r"\s*(\d+)", a_raw).group(1)) < 8:
        pm = True                                     # "free 3 to 6" means the afternoon, not 3 am
    b = parse_hour(b_raw, pm)
    a = parse_hour(a_raw, pm and not re.search(r"am|a\.m\.", a_raw))
    if a is None or b is None:
        return None
    if b <= a and b + 12 > a and b < 12:
        b += 12
    if b <= a:
        return None
    hours = list(range(a, min(24, b)))
    if re.search(r"\b(?:weekdays?|school days?|mon(?:day)?\s*(?:-|to)\s*fri(?:day)?)\b", low):
        keys = ["0", "1", "2", "3", "4"]
    elif re.search(r"\bweekends?\b", low):
        keys = ["5", "6"]
    elif re.search(r"\b(?:every ?day|daily|all week|each day)\b", low):
        keys = [str(i) for i in range(7)]
    else:
        days = []
        for i, nm in enumerate(["mon", "tue", "wed", "thu", "fri", "sat", "sun"]):
            if re.search(r"\b(?:every |on )?" + nm + r"\w*days?\b", low) and re.search(r"\bevery\b|days\b", low):
                days.append(str(i))
        if days:
            keys = days
        else:
            d = parse_rel_date(low[:m.start()] + " " + low[m.end():], today) or today
            keys = [d.isoformat()]
    return keys, hours


def hours_text(hours):
    """[16, 17, 18, 20] -> '16:00-19:00, 20:00-21:00'."""
    hs = sorted(set(int(h) for h in hours))
    if not hs:
        return "none"
    runs, a, prev = [], hs[0], hs[0]
    for h in hs[1:] + [None]:
        if h is not None and h == prev + 1:
            prev = h
            continue
        runs.append("%02d:00-%02d:00" % (a, prev + 1))
        if h is not None:
            a = prev = h
    return ", ".join(runs)


