class ZenkoLife:
    """Her daily life: planner, badges, needs, wellbeing, roaming, seasons, music... Mixed into FoxBuddy (before ZenkoExtras)."""

    # ---- set-up and saving ----------------------------------------------------------------------
    def life_init(self):
        L = self.life = load_life()
        L.setdefault("free", json.loads(json.dumps(DEFAULT_FREE)))
        for k in ("free_dates", "plan_hours", "studied", "facts", "badges", "said", "stats", "counted"):
            L.setdefault(k, {})
        for k in ("journal", "cards", "found", "notes"):
            L.setdefault(k, [])
        L.setdefault("hunger", 30.0)
        L.setdefault("hunger_t", time.time())
        self.bgm = BackgroundMusic()
        self.bgm_state = None
        self.roam = None
        self.roam_next = time.monotonic() + random.uniform(45, 90)
        self.roam_pause_until = 0.0
        self.wx = {"kind": None, "items": [], "code": None, "t": 0.0, "geo": None}
        self.visitor = None
        self.well = {"eyes": 0.0, "posture": 0.0, "water": 0.0, "last": 0.0}
        self.breath_win = None
        self.checkin_win = None
        self.up_cv = None
        self.daily_body = None
        self._plan_sig = None
        self._started = time.monotonic()
        self.life_next_event = time.monotonic() + random.uniform(35, 70) * 60
        self.life_next_mood = time.monotonic() + random.uniform(12, 25) * 60
        self.root.after(3500, self.music_apply)
        self.root.after(8000, self.music_watch)
        self.root.after(6000, self.life_slow_tick)
        self.root.after(9000, self.weather_poll)

    def life_save(self):
        save_life(self.life)

    def said_today(self, key):
        """True once a key has been used today (and marks it)."""
        today = datetime.date.today().isoformat()
        if self.life["said"].get(key) == today:
            return True
        self.life["said"][key] = today
        self.life_save()
        return False

    def stat_add(self, key, n=1):
        st = self.life["stats"]
        st[key] = st.get(key, 0) + n
        self.life_save()
        return st[key]

    # ---- streaks, totals, her mood and hunger -------------------------------------------------------
    def streak(self):
        st = load_stats()
        d = datetime.date.today()
        if st.get(d.isoformat(), 0) < 600:
            d -= datetime.timedelta(days=1)
        n = 0
        while st.get(d.isoformat(), 0) >= 600:
            n += 1
            d -= datetime.timedelta(days=1)
        return n

    def total_hours(self):
        return sum(v for v in load_stats().values() if isinstance(v, (int, float))) / 3600.0

    def days_missed(self):
        """Whole days since the last day with 10+ focused minutes (0 = studied today or yesterday)."""
        st = load_stats()
        d = datetime.date.today()
        for i in range(0, 60):
            if st.get((d - datetime.timedelta(days=i)).isoformat(), 0) >= 600:
                return max(0, i - 1)
        return 2 if st else 0

    def hunger(self):
        L = self.life
        now = time.time()
        h = float(L.get("hunger", 30)) + (now - float(L.get("hunger_t", now))) / 3600.0 * 3.0
        L["hunger"], L["hunger_t"] = max(0.0, min(100.0, h)), now
        return L["hunger"]

    def feed(self, n):
        self.hunger()
        self.life["hunger"] = max(0.0, self.life["hunger"] - n)
        self.life_save()

    def spirit(self):
        """0-100: how bright her foxfire is. Studying lifts it, skipped days and hunger dim it."""
        v = 52 + 6 * min(self.streak(), 5) + min(30, today_focus_minutes() / 2.0) - 16 * min(3, self.days_missed()) \
            - max(0.0, self.hunger() - 60) / 2.0 + int(self.extra.get("bond", 10)) / 10.0
        return int(max(0, min(100, v)))

    def mood_word(self):
        s = self.spirit()
        return "Happy" if s >= 75 else ("Content" if s >= 50 else ("Sleepy" if s >= 30 else "Pouty"))

    def needs_text(self):
        h = self.hunger()
        tummy = "full" if h < 25 else ("peckish" if h < 55 else ("hungry" if h < 80 else "starving"))
        return "Mood: %s (foxfire %d%%)  ·  Tummy: %s  ·  Streak: %d day%s" % (
            self.mood_word(), self.spirit(), tummy, self.streak(), "" if self.streak() == 1 else "s")

    # ---- ema badges ---------------------------------------------------------------------------
    def award(self, bid):
        if not bid in BADGE_BY_ID or bid in self.life["badges"]:
            return False
        self.life["badges"][bid] = datetime.date.today().isoformat()
        self.life_save()
        _, kanji, name, how = BADGE_BY_ID[bid]
        line = "New ema badge! 【%s】 %s - %s. Sugoi~!" % (kanji, name, how)
        self.root.after(2500, lambda: (self.say(line, 10), beep("gift"), self.chat_line("Fox", line)))
        self.set_mood("happy", 5)
        self.daily_refresh()
        return True

    def check_badges(self):
        s = self.streak()
        for n, b in ((3, "streak3"), (7, "streak7"), (30, "streak30")):
            if s >= n:
                self.award(b)
        hrs = self.total_hours()
        for n, b in ((10, "hours10"), (50, "hours50"), (100, "hours100")):
            if hrs >= n:
                self.award(b)

    def life_session_done(self, s, completed, focused):
        """Called from end_session."""
        fm = focused / 60.0
        self.feed(min(60.0, fm * 1.5) if completed else fm * 0.5)
        if completed and s["elapsed"] >= 60:
            self.award("first")
            if s["planned"] >= 90 * 60:
                self.award("marathon")
            if s["planned"] >= 25 * 60 and s["dist"] < 5:
                self.award("spotless")
            started = datetime.datetime.now() - datetime.timedelta(seconds=s["elapsed"])
            if 4 <= started.hour < 8:
                self.award("early")
        self.check_badges()
        if completed and self.cfg.get("pet_needs", True) and random.random() < 0.5:
            self.root.after(16000, lambda: self.say(random.choice(
                ["*munch munch* Yatta~ that session fed me an inari sushi! Thank you~kon!",
                 "Ehehe~ my foxfire got brighter! Focus is my favourite food~"]), 7) if not self.session else None)
        self.daily_refresh()

    def life_tt_marked(self, it, done, day):
        """A planned study session was ticked off (or un-ticked) on the timetable."""
        pid = it.get("plan")
        if not pid:
            return
        key = "%s|%s|%s" % (day, it.get("start"), pid)
        st, cnt = self.life["studied"], self.life["counted"]
        if done and key not in cnt:
            cnt[key] = int(it.get("mins", 50))
            st[pid] = st.get(pid, 0) + cnt[key]
        elif not done and key in cnt:
            st[pid] = max(0, st.get(pid, 0) - cnt.pop(key))
        self.life_save()
        if done:
            left = [i for i in self.tt if i.get("plan") == pid and not i.get("done")]
            if not left and pid in self.life["studied"]:
                self.award("prepared")
        self.up_refresh()

    # ---- overrides of her play/quiz/lock-in so the new things hear about them ---------------------
    def interact(self, kind, arg=None):
        r = super().interact(kind, arg)
        if kind == "treat":
            self.feed(25)
        return r

    def lockin_stop(self, done=False, quiet=False):
        r = super().lockin_stop(done, quiet)
        if done:
            self.award("lockin")
        return r

    def quiz_answer(self, text):
        q = self.quiz
        if not q:
            return super().quiz_answer(text)
        i0, s0 = q["i"], q["score"]
        card = q["cards"][i0] if i0 < len(q["cards"]) else None
        r = super().quiz_answer(text)
        if card is not None and q["i"] == i0 + 1:
            ok = q["score"] > s0
            self.srs_update(card, ok, from_deck=bool(q.get("srs")))
            if not ok and not q.get("srs"):
                q["saved"] = q.get("saved", 0) + 1
            if self.quiz is None and q.get("saved") and isinstance(r, str):
                r += "\n(I saved the %d you missed to your flashcard deck. Say 'review flashcards' tomorrow~)" % q["saved"]
        return r

    # ---- spaced-repetition flashcards ----------------------------------------------------------
    SRS_DAYS = [0, 1, 2, 4, 8, 16, 35]

    def srs_update(self, card, ok, from_deck=False):
        cards = self.life["cards"]
        today = datetime.date.today()
        found = None
        for c in cards:
            if (card.get("id") and c.get("id") == card.get("id")) or (c["q"] == card["q"] and c["a"] == card["a"]):
                found = c
                break
        if found is None:
            if ok:
                return                      # quiz cards you got right aren't saved; misses are
            found = {"id": "%x" % random.getrandbits(36), "q": card["q"], "a": card["a"], "box": 0, "wrong": 0, "right": 0,
                     "added": today.isoformat(), "topic": (self.quiz or {}).get("topic", "")}
            cards.append(found)
        if ok:
            found["box"] = min(len(self.SRS_DAYS) - 1, int(found.get("box", 0)) + 1)
            found["right"] = found.get("right", 0) + 1
        else:
            found["box"] = 0
            found["wrong"] = found.get("wrong", 0) + 1
        found["due"] = (today + datetime.timedelta(days=self.SRS_DAYS[found["box"]] or 1)).isoformat()
        self.life_save()
        if self.stat_add("reviews") >= 50:
            self.award("cards50")
        self.daily_refresh()

    def cards_due(self):
        today = datetime.date.today().isoformat()
        return [c for c in self.life["cards"] if c.get("due", "") <= today]

    def review_start(self):
        due = self.cards_due()
        if not due:
            n = len(self.life["cards"])
            return ("No cards due today~ Yatta! %d card%s in your deck. Add one: 'add flashcard mitochondria = powerhouse of the cell'"
                    % (n, "" if n == 1 else "s")) if n else \
                ("Your deck is empty! Add cards with 'add flashcard Q = A', or say 'quiz me on <topic>': I save the ones you miss.")
        due.sort(key=lambda c: (c.get("box", 0), -c.get("wrong", 0)))
        cards = [{"q": c["q"], "a": c["a"], "id": c["id"]} for c in due[:15]]
        self.quiz = {"cards": cards, "i": 0, "score": 0, "topic": "your review deck", "t": time.time(), "srs": True}
        return "Kon! %d card%s due. Type your answer, or 'hint', 'skip', 'stop quiz'.\n\nQ1/%d: %s" % (
            len(cards), "" if len(cards) == 1 else "s", len(cards), cards[0]["q"])

    def card_add(self, q, a):
        q, a = q.strip(" .")[:200], a.strip(" .")[:200]
        if not q or not a:
            return "Write it like: add flashcard capital of Japan = Tokyo"
        self.life["cards"].append({"id": "%x" % random.getrandbits(36), "q": q, "a": a, "box": 0, "wrong": 0, "right": 0,
                                   "added": datetime.date.today().isoformat(), "due": datetime.date.today().isoformat()})
        self.life_save()
        self.daily_refresh()
        return "Added to your deck: “%s” → %s. Say 'review flashcards' when you're ready~" % (clip(q, 60), clip(a, 40))

    # ---- every second: wellbeing reminders ----------------------------------------------------
    def life_tick(self):
        idle = idle_seconds()
        w = self.well
        if idle >= 300:                                   # they stepped away: that counts as a break
            for k in ("eyes", "posture", "water"):
                w[k] = 0.0
        elif idle < 60:
            for k in ("eyes", "posture", "water"):
                w[k] += 1.0
        if self.brk or self.lock_eating or self.current_mood() == "alert" or idle >= 60:
            return
        if time.monotonic() - w["last"] < 90:
            return
        for k, key, default, lines in (("eyes", "remind_eyes", 20, EYE_LINES), ("posture", "remind_posture", 40, POSTURE_LINES),
                                        ("water", "remind_water", 60, WATER_LINES)):
            every = int(self.cfg.get(key + "_every", default) or default)
            if self.cfg.get(key, True) and w[k] >= every * 60:
                w[k] = 0.0
                w["last"] = time.monotonic()
                self.say(random.choice(lines), 12 if k != "eyes" else 20)
                beep("ding")
                if k == "eyes":
                    def eyes_done():                       # the 20 seconds are up: ding! (even if she's busy)
                        beep("eyes_done")
                        if self.current_mood() != "alert":
                            self.say("...18, 19, 20! *ding* Yatta~ your eyes thank you. Back to it~kon!", 5)
                    self.root.after(20500, eyes_done)
                return

    # ---- every 30 seconds: planner, night, check-in, events, moods, music --------------------------
    def life_slow_tick(self):
        try:
            self._life_slow()
        except Exception:
            pass
        self.root.after(30000, self.life_slow_tick)

    def _life_slow(self):
        now_m = time.monotonic()
        self.hunger()
        self.plan_maybe()
        self.music_keep()
        idle = idle_seconds()
        if idle > 120 or self.lockin or self.brk:
            return
        dt = datetime.datetime.now()
        busy = bool(self.session) or self.current_mood() == "alert"
        # good morning / birthday
        bd = self.life["facts"].get("birthday", "")
        if bd and dt.strftime("%m-%d") == bd[-5:] and not self.said_today("birthday"):
            nm = self.user_short()
            self.say("Happy birthday%s!! *throws sakura petals* Otanjoubi omedetou~! I made you a wish at the shrine~kon!"
                     % ((", " + nm) if nm else ""), 15)
            beep("gift")
            self.play = {"kind": "dance", "t0": now_m, "dur": self.PLAY_DUR["dance"]}
            return
        if self.cfg.get("daynight", True):
            if 5 <= dt.hour < 11 and now_m - self._started > 20 and not self.said_today("morning"):
                self.say(random.choice(["Ohayo~! Good morning! Let's make today a good one, ne~",
                                        "Ohayou gozaimasu~ *stretches tails* Ready when you are!"]), 8)
                return
            if self.is_night(dt) and time.time() - getattr(self, "_night_t", 0.0) > (45 if busy else 30) * 60:
                self._night_t = time.time()
                self.say(random.choice(NIGHT_LINES).format(time=dt.strftime("%H:%M")), 12)
                self.play = None if busy else {"kind": "yawn", "t0": now_m, "dur": self.PLAY_DUR["yawn"]}
                beep("yawn")
                return
        if busy:
            return
        # once a day: how are you feeling?
        if self.cfg.get("daily_checkin", True) and dt.hour >= 6 and now_m - self._started > 90 and \
                self.life.get("last_checkin") != dt.date().isoformat() and not self.said_today("checkin_ask"):
            self.root.after(500, self.open_checkin)
            return
        # flashcards due
        due = self.cards_due()
        if due and dt.hour >= 9 and not self.said_today("cards_due"):
            self.say("Kon! %d flashcard%s due for review today. Say 'review flashcards' when you have 5 minutes~"
                     % (len(due), "" if len(due) == 1 else "s"), 10)
            return
        # her needs show
        if self.cfg.get("pet_needs", True) and now_m >= self.life_next_mood and not self.play:
            self.life_next_mood = now_m + random.uniform(25, 45) * 60
            sp, hu = self.spirit(), self.hunger()
            if hu >= 75:
                self.set_mood("sad", 5)
                self.say(random.choice(HUNGRY_LINES), 9)
            elif sp < 30:
                self.set_mood("sad", 5)
                self.say(random.choice(POUTY_LINES), 9)
            elif sp < 50:
                self.play = {"kind": "yawn", "t0": now_m, "dur": self.PLAY_DUR["yawn"]}
            elif sp >= 75 and random.random() < 0.5:
                self.set_mood("happy", 4)
                self.say(random.choice(HAPPY_LINES), 7)
            return
        # little surprises
        if self.cfg.get("random_events", True) and now_m >= self.life_next_event and not self.play:
            self.life_next_event = now_m + random.uniform(50, 110) * 60
            self.random_event()

    def is_night(self, dt=None):
        dt = dt or datetime.datetime.now()
        bed = parse_clock(self.cfg.get("bedtime", "23:00")) or "23:00"
        wake = parse_clock(self.cfg.get("wake_time", "06:00")) or "06:00"
        t = dt.strftime("%H:%M")
        return (t >= bed or t < wake) if bed > wake else (bed <= t < wake)

    # ---- random events ---------------------------------------------------------------------------
    def season(self, d=None):
        m = (d or datetime.date.today()).month
        return "winter" if m in (12, 1, 2) else ("spring" if m in (3, 4, 5) else ("summer" if m in (6, 7, 8) else "autumn"))

    def haiku(self):
        """A haiku she hasn't said lately (she remembers the last 40)."""
        pool = HAIKU[self.season()] + HAIKU["any"]
        seen = self.life.setdefault("haiku", [])
        fresh = [h for h in pool if h[:24] not in seen] or pool
        h = random.choice(fresh)
        seen.append(h[:24])
        del seen[:-40]
        return h

    def random_event(self, kind=None):
        facts = self.life["facts"]
        kinds = ["haiku", "found", "visitor"] + (["fact"] if facts else [])
        kind = kind or random.choice(kinds)
        if kind == "haiku":
            h = self.haiku()
            self.say("I wrote you a haiku~\n" + h, 16)
            self.chat_line("Fox", "I wrote you a haiku~\n\n" + h + "\n\n- %s" % self.fox_name())
            beep("hello")
            self.play = {"kind": "sing", "t0": time.monotonic(), "dur": 2.4}
        elif kind == "found":
            thing = random.choice(FOUND_THINGS)
            self.life["found"] = (self.life.get("found", []) + [{"what": thing, "date": datetime.date.today().isoformat()}])[-30:]
            self.life_save()
            beep("gift")
            self.play = {"kind": "gift", "t0": time.monotonic(), "dur": self.PLAY_DUR["gift"]}
            line = "Look look! I found %s on my walk round the shrine. It's for you~! (I put it on the Daily page)" % thing
            self.root.after(900, lambda: self.say(line, 10))
        elif kind == "visitor":
            self.visitor_start()
        elif kind == "fact":
            k, v = random.choice(list(facts.items()))
            if k == "birthday":
                return self.random_event("haiku")
            self.say(random.choice(["Ne~ you told me your %s is %s. I still remember, ehehe~",
                                    "Kon! I was thinking about your %s, %s. Tell me more sometime~"]) % (k, v), 9)
        self.daily_refresh()

    # ---- a visiting fox spirit (drawn next to her for a little while) ---------------------------
    def visitor_start(self):
        if self.visitor:
            return
        name, coat, where = random.choice(VISITORS)
        pal = dict(self.pal)
        src = FUR.get(coat) or {}
        for k in COAT_KEYS:
            if k in src:
                pal[k] = src[k]
        z = max(1, self.Z - 1)
        frames = [sprite_photo([build_tails(3, f, shadow=False), build_frame("happy" if f % 4 else "blink", "up", f % 2)], pal, z)
                  for f in range(8)]
        self.visitor = {"name": name, "t0": time.monotonic(), "imgs": frames, "z": z, "item": None}
        self.award("friend")
        beep("hello")
        self.root.after(1600, lambda: self.say("Kon kon! My friend %s %s came to visit~! Say hi!" % (name, where), 9))
        self.root.after(7500, lambda: self.say("%s says: \"Ganbatte with your studies!\" ...and now %s has to go home~"
                                               % (name, "she"), 7))

    def visitor_frame(self, now):
        v = self.visitor
        if not v:
            return
        c = self.canvas
        e = now - v["t0"]
        dur = 13.0
        if e > dur:
            if v["item"]:
                c.delete(v["item"])
            self.visitor = None
            return
        w = W_ * v["z"]
        home = self.COLW - w + int(30 * self.U)
        if e < 1.4:
            x = -w + (home + w) * (1 - (1 - e / 1.4) ** 2)
        elif e > dur - 1.4:
            x = home - (home + w) * ((e - (dur - 1.4)) / 1.4) ** 2
        else:
            x = home
        y = self.H - H_ * v["z"] - int(2 * self.U)
        img = v["imgs"][int(now / 0.15) % 8]
        if v["item"] is None:
            v["item"] = c.create_image(x, y, anchor="nw", image=img, tags="visitor")
        else:
            c.coords(v["item"], int(x), y)
            c.itemconfigure(v["item"], image=img)
        c.tag_raise("bubble")

    # ---- seasons and weather around her ------------------------------------------------------
    def weather_poll(self):
        def job():
            city = self.cfg.get("home_city") or ""
            if not city:
                return None
            g = self.wx.get("geo")
            if not g or g.get("_city") != city:
                g = geocode(city)
                g["_city"] = city
                self.wx["geo"] = g
            j = http_json("%s?latitude=%s&longitude=%s&current=weather_code&timezone=auto"
                          % (WEB["forecast"], g["latitude"], g["longitude"]))
            return (j.get("current") or {}).get("weather_code")

        def done(res, err):
            if not err and res is not None:
                self.wx["code"] = res
        if self.cfg.get("seasons", True) and self.cfg.get("seasons_weather", True) and self.cfg.get("web_enabled", True):
            self.bg(job, done)
        self.root.after(45 * 60 * 1000, self.weather_poll)

    def wx_kind(self):
        code = self.wx.get("code")
        if code is not None and self.cfg.get("seasons_weather", True):
            if code in (71, 73, 75, 77, 85, 86):
                return "snow"
            if code in (51, 53, 55, 56, 57, 61, 63, 65, 66, 67, 80, 81, 82, 95, 96, 99):
                return "rain"
        hr = datetime.datetime.now().hour
        s = self.season()
        if s == "summer" and (hr >= 19 or hr < 5):
            return "fireflies"
        return {"winter": "snow", "spring": "petals", "summer": "fireflies", "autumn": "leaves"}[s]

    WX_LOOK = {"snow": ("#ffffff", "#dfe9ff"), "petals": ("#ffb7d5", "#ff8fbf"), "leaves": ("#e8642c", "#f2a33a"),
               "rain": ("#8fb8ff", "#b9d2ff"), "fireflies": ("#fff3a0", "#d9ff7a")}

    def wx_frame(self, now):
        c = self.canvas
        if not self.cfg.get("seasons", True):
            if self.wx["items"]:
                c.delete("wx")
                self.wx["items"] = []
            return
        kind = self.wx_kind()
        if kind != self.wx["kind"]:
            c.delete("wx")
            self.wx["items"], self.wx["kind"] = [], kind
        Z = self.Z
        x0, x1 = self.COLW, self.W - Z * 2
        items = self.wx["items"]
        want = {"rain": 9, "fireflies": 5, "snow": 8, "petals": 6, "leaves": 5}[kind]
        if len(items) < want and random.random() < 0.08:
            col = random.choice(self.WX_LOOK[kind])
            x, y = random.uniform(x0, x1), (random.uniform(self.fox_y, self.H - 4 * Z) if kind == "fireflies" else -3 * Z)
            if kind == "rain":
                ids = [c.create_rectangle(0, 0, max(1, Z // 2), Z * 3, fill=col, outline="", tags="wx")]
            elif kind == "petals":
                ids = [c.create_rectangle(0, 0, Z * 2, Z, fill=col, outline="", tags="wx"),
                       c.create_rectangle(Z, Z, Z * 2, Z * 2, fill=self.WX_LOOK[kind][1], outline="", tags="wx")]
            elif kind == "leaves":
                ids = [c.create_rectangle(0, 0, Z * 2, Z * 2, fill=col, outline="", tags="wx"),
                       c.create_rectangle(Z * 2, Z * 2, Z * 3, Z * 3, fill="#8a3a1c", outline="", tags="wx")]
            else:
                ids = [c.create_rectangle(0, 0, Z, Z, fill=col, outline="", tags="wx")]
            items.append({"ids": ids, "x": x, "y": y, "ph": random.uniform(0, 6.28), "born": now,
                          "vy": {"rain": 9.0, "snow": 0.9, "petals": 1.1, "leaves": 1.4, "fireflies": 0.0}[kind] * Z * random.uniform(0.7, 1.2)})
        keep = []
        for p in items:
            if kind == "fireflies":
                p["x"] += math.sin(now * 0.9 + p["ph"]) * Z * 0.35
                p["y"] += math.cos(now * 0.7 + p["ph"]) * Z * 0.25
                on = int((now - p["born"]) / 0.8 + p["ph"]) % 3 != 0
                dead = now - p["born"] > 9
                for i in p["ids"]:
                    c.itemconfigure(i, state="normal" if on else "hidden")
            else:
                p["y"] += p["vy"] * 0.6
                if kind != "rain":
                    p["x"] += math.sin(now * 1.3 + p["ph"]) * Z * 0.4 - (0.25 * Z if kind == "leaves" else 0)
                dead = p["y"] > self.H
            if dead:
                for i in p["ids"]:
                    c.delete(i)
                continue
            for k_, i in enumerate(p["ids"]):
                c.coords(i, int(p["x"]), int(p["y"]), int(p["x"]) + (Z * 2 if kind in ("petals", "leaves") and k_ == 0 else
                                                                   (max(1, Z // 2) if kind == "rain" else Z)),
                         int(p["y"]) + (Z * 3 if kind == "rain" else (Z * 2 if kind == "leaves" and k_ == 0 else Z)))
                if k_ == 1:
                    c.coords(i, int(p["x"]) + Z, int(p["y"]) + Z * (2 if kind == "leaves" else 1),
                             int(p["x"]) + Z * (3 if kind == "leaves" else 2), int(p["y"]) + Z * (3 if kind == "leaves" else 2))
            keep.append(p)
        self.wx["items"] = keep
        c.tag_lower("wx")

    # ---- roaming: she wanders along the taskbar, naps on window edges, chases the mouse --------------
    def roam_home(self):
        """zenko17.2: home is always the far right of the screen, just above the taskbar."""
        l, t, r, b = work_area(self.root)
        return int(r - self.W - int(6 * self.U)), int(b - self.H - int(2 * self.U))

    def roam_go_home(self, now, wait=(1.5, 4.0)):
        hx, hy = self.roam_home()
        if abs(self.root.winfo_x() - hx) <= 3 and abs(self.root.winfo_y() - hy) <= 3:
            self.roam = None
            return
        if abs(self.root.winfo_y() - hy) > 3:
            self.roam_go("hop", self.root.winfo_x(), hy, hop=True)
            return
        self.roam_go("walk", hx, hy)
        self.roam["start"] = now + random.uniform(*wait)

    def roam_ok(self):
        return bool(self.cfg.get("roam", True)) and not (self.session or self.brk or self.lockin or self.drag or self.play
                                                         or self.sulk_until or self.lock_eating or self.visitor) \
            and self.current_mood() in ("idle", "happy") and idle_seconds() < 180

    def roam_go(self, mode, tx, ty, hop=False, then=None):
        self.roam = {"mode": mode, "tx": int(tx), "ty": int(ty), "hop": hop, "then": then, "t0": time.monotonic(),
                     "sx": self.root.winfo_x(), "sy": self.root.winfo_y(), "until": 0.0}

    def roam_decide(self, now):
        l, t, r, b = work_area(self.root)
        hx, hy = self.roam_home()
        x = self.root.winfo_x()
        pick = random.random()
        if pick < 0.25:                                           # nap on top of the window you're using
            try:
                rect = window_rect(fg_window())
            except Exception:
                rect = None
            if rect:
                L_, T_, R_, B_ = rect
                if T_ - self.H > t + 10 and R_ - L_ > self.FW + 80 and R_ <= r + 4 and L_ >= l - 4 and B_ - T_ < (b - t) - 20:
                    tx = max(l, min(r - self.W, R_ - self.W - int(40 * self.U)))
                    ty = T_ - self.H + int(3 * self.U)
                    self.roam_go("hop", tx, ty, hop=True, then=("nap", rect))
                    return
        if pick < 0.45:                                           # chase the mouse along the bottom
            self.roam_go("chase", x, hy)
            self.roam["until"] = now + 6.0
            return
        lo, hi = l, r - self.W
        tx = random.uniform(lo, hi) if random.random() < 0.7 else hx
        if abs(tx - x) < 80:
            tx = hx if abs(hx - x) > 80 else (lo + hi) / 2.0
        self.roam_go("walk", tx, hy)

    def roam_step(self, now, st):
        """Called each frame from animate. Moves the window and sets a walking/napping pose."""
        R = self.roam
        if not R:
            if self.roam_ok() and now >= self.roam_next and now >= self.roam_pause_until:
                self.roam_next = now + random.uniform(40, 110)
                self.roam_decide(now)
            return st
        if not self.cfg.get("roam", True) or self.session or self.brk or self.lockin or self.drag:
            self.roam = None
            hx, hy = self.roam_home()
            if not self.drag:
                self.root.geometry("+%d+%d" % (hx, hy))
            return st
        x, y = self.root.winfo_x(), self.root.winfo_y()
        mode = R["mode"]
        if mode == "nap":
            rect = R.get("rect")
            try:
                cur = window_rect(fg_window()) if R.get("check", 0) < now else rect
            except Exception:
                cur = None
            if R.get("check", 0) < now:
                R["check"] = now + 1.0
                same = False
                try:
                    same = bool(cur) and all(abs(a - b_) < 3 for a, b_ in zip(cur, rect))
                except Exception:
                    same = False
                if not same or now > R["until"] or idle_seconds() > 600 or self.mood_override not in (None, "sleep"):
                    hx, hy = self.roam_home()
                    self.roam_go("hop", hx, hy, hop=True)
                    beep("boop")
                    return st
            st.update(state="sleep", hx=0, ear=0, look=(0, 0, 0, 0))
            return st
        if mode == "hop":
            e = (now - R["t0"]) / 0.9
            if e >= 1.0:
                self.root.geometry("+%d+%d" % (R["tx"], R["ty"]))
                then = R.get("then")
                if then and then[0] == "nap":
                    self.roam = {"mode": "nap", "rect": then[1], "until": now + random.uniform(25, 50), "check": now + 1.0}
                    self.say(random.choice(["*hops up* Ooh, a warm window edge... just a little nap~ zzz",
                                            "Kon~ the view is nice up here. *curls up for a nap*"]), 5)
                else:
                    self.roam_go_home(now, (0.4, 1.0))
                return st
            nx = R["sx"] + (R["tx"] - R["sx"]) * e
            ny = R["sy"] + (R["ty"] - R["sy"]) * e - math.sin(math.pi * e) * 90 * self.U
            self.root.geometry("+%d+%d" % (int(nx), int(ny)))
            st.update(state="boop2" if e < 0.5 else "giggle")
            return st
        if mode == "chase":
            try:
                px, py = self.root.winfo_pointerxy()
            except tk.TclError:
                px, py = x, y
            l, t, r, b = work_area(self.root)
            R["tx"] = max(l, min(r - self.W, px - self.COLW - self.FW // 2))
            if now > R["until"]:
                self.set_mood("happy", 2)
                self.roam_go_home(now, (0.8, 1.6))            # then trot back to her spot on the far right
                return st
        if mode == "walk" and now < R.get("start", 0.0):         # a little pause before walking back home
            R["t0"] = now
            return st
        dx = R["tx"] - x
        step = max(2, int(3 * self.U)) * (2 if mode == "chase" else 1)
        if abs(dx) <= step:
            self.root.geometry("+%d+%d" % (R["tx"], R["ty"]))
            if mode == "walk":
                if random.random() < 0.3:
                    self.play = {"kind": "yawn" if random.random() < 0.5 else "tail", "t0": now, "dur": 1.6}
                self.roam_go_home(now)                        # always back to the far right afterwards
            return st
        # ease in for the first steps and ease out near the end, so she doesn't slide
        run = now - R["t0"]
        ease = min(1.0, 0.35 + run / 0.6) * min(1.0, 0.4 + abs(dx) / (40.0 * self.U))
        mv = max(1, int(round(step * ease)))
        nx = x + (mv if dx > 0 else -mv)
        self.root.geometry("+%d+%d" % (int(nx), R["ty"]))
        st.update(self.walk_pose(now, 1 if dx > 0 else -1, fast=(mode == "chase")))
        return st

    def walk_pose(self, now, d, fast=False):
        """A proper fox walk on all four paws (side view, facing where she's going). She puts her ema timer down
        while she walks and picks it up again when she sits."""
        frame = int(now / (0.075 if fast else 0.11)) % 8
        return {"state": "qwalk%s%d" % ("L" if d < 0 else "R", frame), "hx": 0, "ear": 0, "dyf": 0, "look": (0, 0, 0, 0)}

    def life_pose(self, now, st):
        """Hook from animate: roaming pose, weather particles and the visiting fox."""
        try:
            st = self.roam_step(now, st)
        except Exception:
            self.roam = None
        try:
            self.wx_frame(now)
            self.visitor_frame(now)
        except tk.TclError:
            pass
        return st

    # ---- background music ------------------------------------------------------------------
    def music_apply(self):
        """Start/stop/switch the background music to match Settings (and focus-only mode)."""
        on = bool(self.cfg.get("bgm", True))
        if on and self.cfg.get("bgm_when", "always") == "focus":
            on = bool(self.session or self.lockin)
        track = self.cfg.get("bgm_track", "garden")
        vol = int(self.cfg.get("bgm_volume", 2) or 2)
        want = (on, track, vol)
        if want == self.bgm_state:
            return
        self.bgm_state = want
        if not on:
            self.bgm.stop()
            return

        def job():
            music_file_vol(track, vol)            # compose it the first time (a few seconds), then make it this quiet
            return True

        def done(res, err):
            if self.bgm_state == want:
                if not self.bgm.play(track, vol) and IS_WIN:
                    self.say("Uu~ Windows wouldn't play the background music. (It still works for her other sounds.)", 8)
        self.bg(job, done)

    def music_keep(self):
        self.music_apply()

    def music_watch(self):
        """Every few seconds: if Windows stopped the loop, start it again."""
        try:
            if self.bgm_state and self.bgm_state[0]:
                self.bgm.keep_going()
        except Exception:
            pass
        self.root.after(4000, self.music_watch)

    def music_set(self, on=None, track=None, vol=None, when=None):
        if on is not None:
            self.cfg["bgm"] = bool(on)
        if track:
            self.cfg["bgm_track"] = track
        if vol is not None:
            self.cfg["bgm_volume"] = max(1, min(10, int(vol)))
        if when:
            self.cfg["bgm_when"] = when
        save_config(self.cfg)
        self.music_apply()

    # ---- the study planner ------------------------------------------------------------------
    def free_for(self, day):
        L = self.life
        if day.isoformat() in L["free_dates"]:
            return sorted(L["free_dates"][day.isoformat()])
        return sorted(L["free"].get(str(day.weekday()), []))

    def busy_for(self, day):
        out = []
        for it in tt_today(self.tt, day):
            if it.get("plan"):
                continue
            h, m = map(int, it["start"].split(":"))
            out.append((h * 60 + m, h * 60 + m + int(it["mins"])))
        return out

    def plan_targets(self):
        items = load_deadlines()
        changed = False
        now = datetime.datetime.now()
        out = []
        for d in items:
            if not d.get("id"):
                d["id"] = "%x" % random.getrandbits(40)
                changed = True
            if d.get("done") or d.get("kind", "Deadline") not in PLAN_KINDS:
                continue
            try:
                due = deadline_due(d)
            except Exception:
                continue
            if due <= now or (due.date() - now.date()).days > 45:
                continue
            hrs = float(self.life["plan_hours"].get(d["id"], PLAN_HOURS.get(d.get("kind"), 3)))
            out.append({"id": d["id"], "title": d["title"], "due": due, "kind": d.get("kind"), "date": d["date"],
                        "hours": hrs, "need": max(0, int(hrs * 60 - self.life["studied"].get(d["id"], 0)))})
        if changed:
            save_deadlines(items)
        return out

    def plan_sig(self):
        try:
            mt = os.path.getmtime(DEADLINES_PATH)
        except OSError:
            mt = 0
        return (datetime.date.today().isoformat(), mt, json.dumps(self.life["free"], sort_keys=True),
                json.dumps(self.life["free_dates"], sort_keys=True), json.dumps(self.life["plan_hours"], sort_keys=True),
                self.cfg.get("plan_session", 50), self.cfg.get("planner", True))

    def plan_maybe(self):
        sig = self.plan_sig()
        if sig != self._plan_sig:
            self._plan_sig = sig
            if self.cfg.get("planner", True):
                self.replan()

    def replan(self):
        """Re-make all future study sessions on the timetable from your exams and free hours."""
        now = datetime.datetime.now()
        today = now.date().isoformat()
        keep = []
        old = (now.date() - datetime.timedelta(days=14)).isoformat()
        for it in self.tt:
            if it.get("plan") and it.get("date", today) < old:
                continue                         # tidy away planned sessions from weeks ago
            if it.get("plan") and not it.get("done"):
                st = tt_window(it, datetime.date.fromisoformat(it.get("date", today)))[0]
                if st >= now:
                    continue                     # not started yet: it'll be planned again
            keep.append(it)
        self.tt[:] = keep
        targets = self.plan_targets() if self.cfg.get("planner", True) else []
        sessions, short = plan_study(targets, self.free_for, self.busy_for, now,
                                     int(self.cfg.get("plan_session", 50) or 50), int(self.cfg.get("plan_day_cap", 4) or 4))
        for s in sessions:
            self.tt.append({"task": ("Review: " if s["review"] else "Study: ") + s["title"], "start": s["start"], "mins": s["mins"],
                            "daily": False, "date": s["date"], "done": [], "plan": s["id"]})
        save_tt(self.tt)
        self.life["plan_short"] = short
        self.life_save()
        self._plan_sig = self.plan_sig()
        try:
            self.tt_refresh()
        except Exception:
            pass
        self._hub_next_key = None
        self.up_refresh()
        return targets, sessions, short

    def plan_summary(self, only=None, n=8):
        rows = sorted([i for i in self.tt if i.get("plan") and not i.get("done") and (not only or i["plan"] == only)
                       and i.get("date", "") >= datetime.date.today().isoformat()],
                      key=lambda i: (i["date"], i["start"]))
        if not rows:
            return ""
        out = []
        for it in rows[:n]:
            d = datetime.date.fromisoformat(it["date"])
            out.append("• %s %s  %s (%d min)" % (when_text(it["date"]).capitalize() if (d - datetime.date.today()).days <= 1
                                                 else d.strftime("%a %d"), it["start"], it["task"], it["mins"]))
        if len(rows) > n:
            out.append("  ...and %d more on your timetable" % (len(rows) - n))
        return "\n".join(out)

    def plan_reply(self, focus_id=None):
        targets, sessions, short = self.replan()
        if not targets:
            return "Nothing to plan for~ Tell me about an exam, like 'my chemistry exam is in 2 days'."
        self.award("planner")
        lines = []
        for t in targets[:5]:
            n = sum(1 for i in self.tt if i.get("plan") == t["id"] and not i.get("done")
                    and i.get("date", "") >= datetime.date.today().isoformat())
            done = self.life["studied"].get(t["id"], 0)
            lines.append("• %s, %s: %d session%s planned%s%s" % (
                t["title"], when_text(t["date"]), n, "" if n == 1 else "s",
                (", %s already done" % fmt_hm(done)) if done else "",
                ("  (uu~ %s didn't fit in your free hours)" % fmt_hm(short[t["id"]])) if t["id"] in short else ""))
        body = self.plan_summary(focus_id)
        tip = "" if self.life.get("free_set") else \
            "\n(I used my guess of your free hours. Mark your real ones on the Upcoming clock, or say 'I'm free 4-7pm on weekdays'.)"
        self.root.after(300, lambda: self.open_hub("deadlines"))
        return "Kon! Here's your study plan~\n" + "\n".join(lines) + ("\n\nNext up:\n" + body if body else "") + tip

    def set_free(self, keys, hours, add=False):
        L = self.life
        for k in keys:
            if "-" in k:                                  # a date
                cur = set(L["free_dates"].get(k, self.free_for(datetime.date.fromisoformat(k)) if add else []))
                L["free_dates"][k] = sorted(cur | set(hours)) if add else sorted(set(hours))
            else:
                cur = set(L["free"].get(k, [])) if add else set()
                L["free"][k] = sorted(cur | set(hours))
        L["free_set"] = True
        today = datetime.date.today().isoformat()
        L["free_dates"] = dict((k, v) for k, v in L["free_dates"].items() if k >= today)
        self.life_save()

    def countdown_text(self):
        ups = [d for d in self.upcoming_deadlines(8)]
        if not ups:
            return "No exams coming up! Tell me one: 'my maths exam is on Dec 10'."
        out = ["Countdown~"]
        today = datetime.date.today()
        for d in ups[:6]:
            days = (datetime.date.fromisoformat(d["date"]) - today).days
            todays = sum(i["mins"] for i in self.tt if i.get("plan") == d.get("id") and i.get("date") == today.isoformat())
            goal = ("  ·  today's goal: %s" % fmt_hm(todays)) if todays else ""
            out.append("• %s: %s%s" % (d["title"], "TODAY!" if days == 0 else ("tomorrow" if days == 1 else "%d days" % days), goal))
        return "\n".join(out)

    # ---- homework buddy ---------------------------------------------------------------------
    HOMEWORK_PROMPT = ("You are Zenko, a kind fox-girl study buddy and patient tutor. Explain how to solve the student's question "
                       "step by step with numbered steps. Show the working, explain WHY each step is done in simple words, then give "
                       "the final answer on its own line starting 'Answer:'. Finish with one short tip to remember it. Keep it under "
                       "220 words. You may add one short fox-girl word like 'kon!' at the start, but keep the steps clear and plain.")

    def homework(self, q):
        q = q.strip()
        if len(q) < 3:
            return "Paste the question after 'homework:' and I'll explain it step by step~"
        if self.stat_add("homework") >= 5:
            self.award("homework")
        model = self.cfg.get("llm_model") or "llama3.2:3b"
        use_llm = self.cfg.get("llm_enabled", True)
        prof = self.user_profile_text()

        def job():
            names = ollama_models() if use_llm else None
            if names:
                m = pick_model(names, model)
                j = _ollama_json("/api/chat", {"model": m, "stream": False, "options": {"temperature": 0.3, "num_predict": 600},
                                               "messages": [{"role": "system", "content": self.HOMEWORK_PROMPT + " " + prof},
                                                            {"role": "user", "content": q}]}, 240)
                txt = (j.get("message") or {}).get("content", "").strip()
                if txt:
                    return "llm", txt
            try:
                v = calc_eval(q)
                return "calc", v
            except Exception:
                pass
            return "web", None

        def done(res, err):
            if err or not res:
                self.fox_reply("Uu~ I got stuck on that one (%s). Try asking it a bit differently?" % (err or "no answer"))
                return
            kind, val = res
            if kind == "llm":
                self.fox_reply(val)
            elif kind == "calc":
                expr = re.sub(r"^(?:what is|what's|whats|calculate|calc|compute|solve)\s+", "", q.strip(" ?=."), flags=re.I)
                self.fox_reply("Kon! Let's work it out:\n1. Read it carefully: %s\n2. Do brackets and powers first, then x and ÷, "
                               "then + and - (BODMAS).\n3. Work it through step by step.\nAnswer: %s\n\nTip: estimate first, "
                               "so you can tell if the answer looks right~" % (expr, fmt_num(val)))
            else:
                if not self.cfg.get("web_enabled", True):
                    self.fox_reply("I need the smart brain (Ollama) or internet lookups for that one. Turn one on in Settings~")
                    return
                r = self.start_web("search", ("explain step by step " + q, q, True))
                if r:
                    self.fox_reply(r + "\n(Tip: with the free smart brain, I can explain it step by step. Settings > Smart brain setup.)")
        self.bg(job, done)
        self.set_mood("focus", 4)
        return "Fumu fumu~ let me think about that, step by step..."

    # ---- summarise a dropped file without the smart brain ---------------------------------------------
    def summarise_offline(self, name, body):
        text = re.sub(r"[ \t]*\n[ \t]*\n\s*", ". ", body[:60000])
        text = re.sub(r"\n(?=[A-Z0-9•\-*])", ". ", text).replace("\n", " ")
        text = re.sub(r"\.\s*\.", ".", text)
        sents = _sentences(text)
        k = max(1, len(sents) // 8 + 1)
        docs = [{"title": name, "text": " ".join(sents[i:i + k]), "url": ""} for i in range(0, len(sents), k)]
        pts = summarise_extract(name, docs, n=7, limit=1300)
        if not pts:
            return "I read “%s” but couldn't find much to summarise." % name
        out = [x.strip() for x in _sentences(pts) if x.strip()]
        return "Kon! The key points of “%s”:\n" % name + "\n".join("• " + x for x in out[:7])

    # ---- remembering things about you -------------------------------------------------------------
    def fact_set(self, key, val):
        key = re.sub(r"\s+", " ", key.lower().strip(" .!"))[:40]
        key = key.replace("favorite", "favourite").replace("color", "colour")
        val = val.strip(" .!~")[:120]
        if key == "birthday":
            ds = find_dates(val)
            if not ds:
                return "Ehh? When is it? Like 'my birthday is 14 May'."
            val = ds[0][0].strftime("%m-%d")
            self.life["facts"]["birthday"] = val
            self.life_save()
            self.daily_refresh()
            return "Kon! Your birthday is %s~ I'll remember, and I'll have a surprise ready!" % ds[0][0].strftime("%d %B")
        self.life["facts"][key] = val
        self.life_save()
        self.daily_refresh()
        return random.choice(["Kon! I'll remember that your %s is %s~", "Fumu fumu~ your %s is %s. Noted in my fox memory!",
                              "Ehehe~ got it: %s = %s. I won't forget!"]) % (key, val)

    def facts_text(self):
        f = self.life["facts"]
        notes = self.life.get("notes", [])
        if not f and not notes:
            return "I don't know much about you yet~ Tell me! Like 'my favourite subject is biology' or 'remember that I play piano'."
        out = ["Things I remember about you~"]
        for k, v in f.items():
            if k == "birthday":
                try:
                    v = datetime.date(2000, int(v[:2]), int(v[3:5])).strftime("%d %B")
                except Exception:
                    pass
            out.append("• your %s: %s" % (k, v))
        for n in notes[-8:]:
            out.append("• " + n)
        out.append("(Say 'forget my <thing>' to make me forget one.)")
        return "\n".join(out)

    def facts_for_brain(self):
        f = self.life["facts"]
        bits = ["%s: %s" % (k, v) for k, v in f.items()] + self.life.get("notes", [])[-6:]
        return ("Things the user told you about themselves: " + "; ".join(bits) + ".") if bits else ""

    # ---- chat commands -------------------------------------------------------------------
    def life_route(self, text):
        raw = text.strip()
        low = raw.lower().strip()
        lw = low.rstrip(" !.?~")
        if re.match(r"^(?:let'?s |can we |i want to |help me )?(?:do (?:a |some )?|start (?:a )?)?(?:breath(?:e|ing)(?: exercise)?|calm me down|"
                    r"i'?m (?:so )?(?:stressed|anxious|panicking|overwhelmed))", lw):
            self.root.after(200, self.open_breathing)
            return "Okay~ breathe with my foxfire. In as it grows, out as it shrinks. I'm right here, ne~"
        if re.match(r"^(?:daily )?check[ -]?in$|^mood (?:journal|check)$|^(?:open )?(?:my )?journal$|^how am i feeling", lw):
            self.root.after(200, lambda: self.open_checkin(force=True))
            return "How are you feeling today? Pick one~"
        m = re.match(r"^(?:homework|hw|hwk|home work)\s*(?:help)?\s*[:\-]\s*(.+)$", raw, re.I | re.S) or \
            re.match(r"^(?:help me (?:with|solve|understand)|how do (?:i|you) solve|solve|explain(?: to me)?)\s+(.+?)(?:\s+step by step)?\s*[?.]*$",
                     raw, re.I | re.S)
        if m and not re.search(r"\b(?:that|the|this|my) (?:file|document|pdf|notes?)\b|\bnotes\b", low):
            return self.homework(m.group(1))
        # exam told in words: "my chemistry exam is in 2 days", "exam on friday at 9am"
        if re.search(r"\b(exams?|tests?|quiz(?:zes)?|midterms?|finals?|assessments?|mocks?)\b", low) and "?" not in raw and \
                not re.match(r"^(when|what|how|which|is|are|do|does|show|list|open|delete|remove|quiz me)\b", lw):
            d = parse_rel_date(low)
            if d and d >= datetime.date.today():
                return self.exam_from_text(raw, d)
        fr = parse_free_time(raw)
        if fr and re.search(r"\bi(?:'?m| am)?\b|^free\b|\bmy free\b|\bstudy time\b", low):
            keys, hours = fr
            self.set_free(keys, hours)
            where = ("on " + ", ".join(DAY_NAMES[int(k)] + "s" for k in keys)) if "-" not in keys[0] else \
                when_text(keys[0])
            self.replan()
            return "Kon! Free %s: %s. I re-planned your study sessions to fit~ (You can also tap hours on the Upcoming clock.)" % (
                where, hours_text(hours))
        if re.search(r"\b(study plan|plan my (?:study|studies|studying|revision|exams?|week)|re-?plan|make (?:me )?a (?:study )?plan|"
                     r"schedule my (?:study|revision)|plan (?:my )?(?:study )?sessions)\b", low):
            return self.plan_reply()
        m = re.search(r"\b(?:i need|i want|give me|plan)\s+(\d{1,2}(?:\.\d)?)\s*(?:h|hrs?|hours?)\s+(?:of (?:study|revision) )?(?:for|on)\s+(?:my |the )?(.+)$", lw)
        if m:
            want, name = float(m.group(1)), m.group(2).strip()
            best, sc = None, 0.0
            for d in self.upcoming_deadlines(20):
                s_ = difflib.SequenceMatcher(None, name, d["title"].lower()).ratio() + (0.5 if name.split()[0] in d["title"].lower() else 0)
                if s_ > sc:
                    best, sc = d, s_
            if best and sc >= 0.5 and best.get("id"):
                self.life["plan_hours"][best["id"]] = want
                self.life_save()
                self.replan()
                return "Okay~ %s of study for %s. Plan updated!\n%s" % (fmt_hm(want * 60), best["title"], self.plan_summary(best["id"], 5))
            return "Which exam is that? I couldn't match '%s'." % name
        if re.search(r"\bcountdown\b|how (?:many days|long) (?:until|till|before|left)|days (?:left|until|till)", low):
            return self.countdown_text()
        # flashcards
        m = re.match(r"^(?:add |new |make a? ?)?(?:flash ?card|card)s?\s*[:\-]?\s*(.+?)\s*(?:=|->|=>|::| - )\s*(.+)$", raw, re.I)
        if m and re.match(r"^(?:add |new |make)", lw) or (m and lw.startswith(("flashcard", "flash card"))):
            return self.card_add(m.group(1), m.group(2))
        if re.match(r"^(?:review|study|practi[cs]e|do)(?: my)? (?:flash ?cards?|cards|deck|review deck)$|^(?:flash ?cards|review)$", lw):
            return self.review_start()
        if re.match(r"^(?:my|show(?: my)?|how many) (?:flash ?cards|cards|deck)", lw):
            n, due = len(self.life["cards"]), len(self.cards_due())
            hard = sorted(self.life["cards"], key=lambda c: -c.get("wrong", 0))[:3]
            extra = ("\nTrickiest: " + "; ".join("%s (missed %dx)" % (clip(c["q"], 40), c.get("wrong", 0)) for c in hard if c.get("wrong"))) \
                if any(c.get("wrong") for c in hard) else ""
            return "Your deck: %d card%s, %d due today.%s" % (n, "" if n == 1 else "s", due, extra)
        # remembering you
        m = re.match(r"^(?:remember(?: that)?|don'?t forget(?: that)?|note that)\s+(.+)$", raw, re.I)
        if m and "=" not in raw:
            what = m.group(1).strip()
            m2 = re.match(r"^my\s+([a-z' ]{2,30}?)\s+(?:is|are|was)\s+(.+)$", what, re.I)
            if m2:
                return self.fact_set(m2.group(1), m2.group(2))
            what = re.sub(r"^i\b", "you", what, flags=re.I)
            self.life["notes"] = (self.life.get("notes", []) + [what[:160]])[-40:]
            self.life_save()
            self.daily_refresh()
            return "Kon! I'll remember: %s~" % what
        m = re.match(r"^my\s+([a-z' ]{2,30}?)\s+(?:is|are)\s+(.+)$", raw.strip(" .!"), re.I)
        if m and any(k in m.group(1).lower() for k in FACT_KEYS) and not re.search(r"\b(exam|test|quiz|deadline|due)\b", low):
            return self.fact_set(m.group(1), m.group(2))
        if re.search(r"what do you (?:remember|know) about me|what have i told you|things you remember", low):
            return self.facts_text()
        f = self.life_forget(lw)
        if f:
            return f
        # music
        if re.search(r"\b(?:background|bgm|japanese|shrine|zen|calm|relaxing|soothing|study) music\b|\bbgm\b", low):
            if re.search(r"\b(off|stop|quiet|pause|no more|disable|turn off|mute)\b", low):
                self.music_set(on=False)
                return "Okay~ background music off. (Settings > Background music to turn it back on.)"
            for key, name, _ in MUSIC_TRACKS:
                if key in low or name.lower() in low:
                    self.music_set(on=True, track=key)
                    return "Playing “%s” softly~" % name
            self.music_set(on=True)
            name = dict((k, n) for k, n, _ in MUSIC_TRACKS).get(self.cfg.get("bgm_track", "garden"), "")
            return "Kon~ playing soft Japanese music (“%s”). Change the track or volume in Settings." % name
        # desktop life toggles
        m = re.match(r"^(?:turn |switch )?(roam(?:ing)?|walking|seasons?|weather effects|snow|petals|night (?:mode|nags?)|day ?/? ?night)"
                     r"(?: mode)? (on|off)$|^(stop|start) (roaming|walking around|wandering)$", lw)
        if m:
            what = (m.group(1) or m.group(4) or "")
            on = (m.group(2) == "on") if m.group(2) else (m.group(3) == "start")
            key = "roam" if re.match(r"roam|walk|wander", what) else ("seasons" if re.match(r"season|weather|snow|petal", what) else "daynight")
            self.cfg_set(key, on)
            return "%s %s~" % ({"roam": "Roaming", "seasons": "Seasons and weather", "daynight": "Day and night"}[key], "on" if on else "off")
        if re.match(r"^(?:go for a walk|walk around|go explore|go roam)$", lw):
            if self.session or self.lockin:
                return "Not during focus time~ I'm staying right here!"
            self.roam_next = 0
            self.roam_pause_until = 0
            return "Yatta~ walkies! *trots off*"
        # streaks, badges, her mood
        if re.search(r"\b(my )?streak\b|\bbadges?\b|\bachievements?\b|\bema\b", low):
            got = [BADGE_BY_ID[b] for b in self.life["badges"] if b in BADGE_BY_ID]
            self.root.after(200, lambda: self.open_hub("daily"))
            return "Focus streak: %d day%s~  Ema badges: %d of %d%s" % (
                self.streak(), "" if self.streak() == 1 else "s", len(got), len(BADGES),
                ("\n" + "  ".join("【%s】%s" % (b[1], b[2]) for b in got)) if got else "\nFinish a focus session to earn your first one!")
        if re.match(r"^(?:are you (?:hungry|ok|okay|happy|sad|sleepy)|how are you(?: feeling| doing)?(?: today)?|how'?s my fox|you hungry)$", lw):
            sp, hu = self.spirit(), self.hunger()
            feel = random.choice(HAPPY_LINES) if sp >= 75 else ("I'm doing okay~ kon!" if sp >= 50 else
                                                                  ("*yawn* A bit sleepy... a study session would wake me up~" if sp >= 30 else random.choice(POUTY_LINES)))
            if hu >= 60:
                feel += " " + random.choice(HUNGRY_LINES)
            return feel + "\n(" + self.needs_text() + ")"
        if re.match(r"^(?:write (?:me )?a |tell me a |)haiku$", lw):
            return "A haiku for you~\n\n" + self.haiku()
        if re.match(r"^(?:invite|call) (?:a |your )?friend$|^any visitors$", lw):
            self.visitor_start()
            return "Kon kon~ I'll call a friend!"
        return None

    def life_add_typed(self, q):
        """The Upcoming page's box: understands 'chemistry exam in 2 days' too."""
        res = self.deadline_route("add deadline " + q)
        if res and not res.startswith("When is it"):
            self.root.after(100, self.plan_maybe)
            return res
        d = parse_rel_date(q)
        if not d:
            return res
        if re.search(r"\b(exams?|tests?|quiz|midterm|final|assessment|mock)\b", q, re.I):
            return self.exam_from_text(q, d).split("\n")[0]
        title = re.sub(r"\b(?:in\s+\S+\s+(?:days?|weeks?)|(?:the )?day after tomorrow|tomorrow|today|tonight|"
                       r"(?:on |this |next )?(?:mon|tue|tues|wed|wednes|thu|thur|thurs|fri|sat|satur|sun)(?:day)?)\b", " ", q, flags=re.I)
        t, span = find_time(title)
        if span:
            title = title[:span[0]] + " " + title[span[1]:]
        title = re.sub(r"\s+", " ", re.sub(r"\b(on|by|at|due)\s*$", "", title.strip(), flags=re.I)).strip(" -,") or "Deadline"
        title = title[:1].upper() + title[1:]
        self.add_deadline(title, d.isoformat(), t)
        self.root.after(100, self.plan_maybe)
        return "Added: %s on %s (%s)." % (title, d.strftime("%a %d %b %Y"), when_text(d.isoformat()))

    def life_forget(self, text):
        m = re.match(r"^forget (?:my |about my |that my )?(.+?)[.!~]*$", text.lower().strip())
        if m:
            k = m.group(1).strip().replace("favorite", "favourite").replace("color", "colour")
            if k in self.life["facts"]:
                self.life["facts"].pop(k)
                self.life_save()
                self.daily_refresh()
                return "Poof~ I forgot your %s." % k
            for n in list(self.life.get("notes", [])):
                if k in n.lower() and len(k) >= 4:
                    self.life["notes"].remove(n)
                    self.life_save()
                    self.daily_refresh()
                    return "Poof~ I forgot that %s." % n
        return None

    def exam_from_text(self, raw, d):
        low = raw.lower()
        km = re.search(r"\b(exams?|tests?|quiz(?:zes)?|midterms?|finals?|assessments?|mocks?)\b", low)
        kind_w = km.group(1).rstrip("s") if km else "exam"
        kind_w = {"quizze": "quiz", "quizz": "quiz", "final": "final exam", "mock": "mock exam", "midterm": "midterm exam"}.get(kind_w, kind_w)
        before = raw[:km.start()] if km else ""
        after = raw[km.end():] if km else ""
        subj = re.sub(r"^(?:hey|hi|so|ok|okay|yo|um|uh|zenko|guess what)\b[\s,!]*", "", before.strip(), flags=re.I)
        subj = re.sub(r"\b(?:i(?:'ve| have)?|have|got|there'?s|is|my|a|an|the|big|next|an?other|gonna have|will have|have got)\b", " ", subj, flags=re.I)
        subj = re.sub(r"[^\w &+\-]", " ", subj)
        subj = re.sub(r"\s+", " ", subj).strip(" -")
        if not subj:
            m = re.search(r"\b(?:for|on|in)\s+([a-z][a-z &+\-]{2,30}?)(?=\s+(?:is|on|in|at|this|next|tomorrow|today)\b|[,.!]|$)", after, re.I)
            if m and not re.match(r"^(?:\d|a |an |one|two|three|monday|tuesday|wednesday|thursday|friday|saturday|sunday|jan|feb|mar|apr|"
                                  r"may|jun|jul|aug|sep|oct|nov|dec|the morning|the afternoon)", m.group(1).lower()):
                subj = m.group(1).strip()
        subj = " ".join(subj.split()[-4:])
        title = ((subj + " ") if subj else "") + kind_w
        title = title[:1].upper() + title[1:]
        t, _ = find_time(after)
        kind = guess_kind(title)
        if kind == "Deadline":
            kind = "Exam"
        items = load_deadlines()
        for it in items:
            if it.get("date") == d.isoformat() and it.get("title", "").lower() == title.lower() and not it.get("done"):
                break
        else:
            self.add_deadline(title, d.isoformat(), t, kind=kind, source="chat")
        targets, sessions, short = self.replan()
        self.award("planner")
        tid = None
        for it in load_deadlines():
            if it.get("date") == d.isoformat() and it.get("title", "").lower() == title.lower():
                tid = it.get("id")
        mine = [s for s in sessions if s["id"] == tid]
        days = (d - datetime.date.today()).days
        head = "Kon! %s %s (%s)%s. " % (title, "is TODAY" if days == 0 else "on " + d.strftime("%a %d %b"),
                                         when_text(d.isoformat()), (" at " + t) if t else "")
        if mine:
            body = "I planned %d study session%s for it in your free time:\n%s" % (
                len(mine), "" if len(mine) == 1 else "s", self.plan_summary(tid, 6))
            if tid in short:
                body += "\nUu~ %s more didn't fit. Mark more free hours on the Upcoming clock?" % fmt_hm(short[tid])
        else:
            body = "But I couldn't find free time before it! Tell me when you're free ('I'm free 5-8pm today') or tap hours on the clock."
        tip = "" if self.life.get("free_set") else \
            "\n(I guessed your free hours. Set yours on the Upcoming tab's clock, or say 'I'm free 4-7pm on weekdays'.)"
        self.root.after(400, lambda: self.open_hub("deadlines"))
        self.set_mood("happy", 4)
        return head + body + tip

    # ==== the Upcoming page: exam countdown | Japanese clock | study plan ==========================
    SHU = "#c8372d"                       # shu-iro (torii vermilion)

    def up_refresh(self):
        h = getattr(self, "hub", None)
        if h and "deadlines" in h.get("pages", {}) and getattr(self, "dl_body", None) is not None:
            try:
                if not getattr(self, "_up_painting", False):
                    self.dl_render()
            except tk.TclError:
                pass

    def up_row(self, body):
        """The middle of the Upcoming page (called from dl_render)."""
        if not hasattr(self, "up_day"):
            now = datetime.datetime.now()
            self.up_day = now.weekday()
            self.up_pm = now.hour >= 12 or not any(int(h) < 12 for h in self.free_for(now.date()))
        row = tk.Frame(body, bg=PAPER)
        row.pack(fill="x", pady=(12, 0))
        try:
            wide = self.hub["win"].winfo_width() >= 1180
        except Exception:
            wide = True
        row.grid_columnconfigure(0, weight=1, uniform="up")
        row.grid_columnconfigure(2, weight=1, uniform="up")
        left = self.hub_card(row, "Exam countdown", shape="ema")
        left.grid(row=0, column=0, sticky="nsew")
        mid = self.hub_card(row, "Your free hours", shape="leaf")
        mid.grid(row=0, column=1, sticky="nsew", padx=12)
        right = self.hub_card(row, "Study plan")
        right.grid(row=0, column=2, sticky="nsew")
        self.up_countdown(left)
        self.up_clock(mid, 340 if wide else 290)
        self.up_plan(right)

    def up_countdown(self, c):
        bg = T["card"]
        targets = self.plan_targets()
        if not targets:
            tk.Label(c, text="No exams coming up~\n\nTell me in chat, like:\n“my chemistry exam is in 2 days”\n"
                             "“maths test on Friday 9am”\n\nI'll plan study sessions in your free hours.",
                     bg=bg, fg=GREY, font=(FONT_UI, 10), justify="left", anchor="w").pack(fill="x", padx=16, pady=(4, 16))
            return
        today = datetime.date.today()
        for t in targets[:4]:
            days = (t["due"].date() - today).days
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=12, pady=4)
            cv = tk.Canvas(r, width=58, height=58, bg=bg, highlightthickness=0)
            cv.pack(side="left")
            urgent = days <= 2
            wood, edge = (_mixhex(self.SHU, bg, 0.15), _mixhex(self.SHU, "#000000", 0.3)) if urgent else \
                (_mixhex("#c98a35", bg, 0.25), _mixhex("#7a4a1c", bg, 0.1))
            cv.create_polygon(29, 2, 55, 14, 55, 56, 3, 56, 3, 14, fill=wood, outline=edge, width=2)
            cv.create_line(20, 9, 38, 9, fill=edge, width=2)
            cv.create_text(29, 31, text="今日" if days == 0 else str(days), fill="#fff6e0",
                           font=(_jp_font(self.root) or FONT_UI, 15 if days else 12, "bold"))
            cv.create_text(29, 48, text="" if days == 0 else ("day" if days == 1 else "days"), fill="#fff6e0", font=(FONT_UI, 7, "bold"))
            mid = tk.Frame(r, bg=bg)
            mid.pack(side="left", fill="x", expand=True, padx=(8, 0))
            tk.Label(mid, text=clip(t["title"], 24), bg=bg, fg=INK, font=(FONT_UI, 10, "bold"), anchor="w").pack(fill="x")
            done = self.life["studied"].get(t["id"], 0)
            todays = sum(i["mins"] for i in self.tt if i.get("plan") == t["id"] and i.get("date") == today.isoformat())
            tk.Label(mid, text="%s · %s of %s studied%s" % (t["due"].strftime("%a %d %b"), fmt_hm(done) if done else "0m",
                                                             fmt_hm(t["hours"] * 60), ("\nToday's goal: %s" % fmt_hm(todays)) if todays else ""),
                     bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w", justify="left").pack(fill="x")
            bar = tk.Canvas(mid, width=60, height=10, bg=bg, highlightthickness=0)
            bar.pack(fill="x", pady=(2, 0))
            frac = min(1.0, done / max(1.0, t["hours"] * 60))
            bar.bind("<Configure>", lambda e, b=bar, f=frac: (b.delete("all"), self.glow_bar(b, 1, 1, e.width - 2, 9, f)))
            hr = tk.Frame(mid, bg=bg)
            hr.pack(anchor="w", pady=(2, 0))

            def bump(k, tid=t["id"], cur=t["hours"]):
                self.life["plan_hours"][tid] = max(0.5, min(60.0, cur + k))
                self.life_save()
                self.replan()
            self.tt_btn(hr, "−", lambda f=bump: f(-1), bg=FIELD, size=8, padx=6, pady=0).pack(side="left")
            tk.Label(hr, text=" %s total " % fmt_hm(t["hours"] * 60), bg=bg, fg=INK, font=(FONT_UI, 8)).pack(side="left")
            self.tt_btn(hr, "+", lambda f=bump: f(1), bg=FIELD, size=8, padx=6, pady=0).pack(side="left")
        tk.Frame(c, bg=bg, height=8).pack()

    def up_plan(self, c):
        bg = T["card"]
        today = datetime.date.today()
        rows = sorted([i for i in self.tt if i.get("plan") and i.get("date", "") >= today.isoformat()],
                      key=lambda i: (i["date"], i["start"]))
        short = self.life.get("plan_short") or {}
        if not self.cfg.get("planner", True):
            tk.Label(c, text="The auto planner is off (Settings > Study planner).", bg=bg, fg=GREY, font=(FONT_UI, 10),
                     anchor="w", wraplength=260, justify="left").pack(fill="x", padx=16, pady=(4, 10))
        elif not rows:
            tk.Label(c, text="Nothing planned yet. Add an exam and mark your free hours on the clock, and I'll fill this in~",
                     bg=bg, fg=GREY, font=(FONT_UI, 10), anchor="w", wraplength=260, justify="left").pack(fill="x", padx=16, pady=(4, 10))
        last = None
        shown = 0
        for it in rows:
            if shown >= 9:
                break
            d = datetime.date.fromisoformat(it["date"])
            if d != last:
                last = d
                lab = "Today" if d == today else ("Tomorrow" if (d - today).days == 1 else d.strftime("%A %d %b"))
                tk.Label(c, text=lab, bg=bg, fg=GOLD, font=(FONT_UI, 9, "bold"), anchor="w").pack(fill="x", padx=16, pady=(6, 0))
            done = tt_done(it, d)
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=16, pady=1)
            tk.Label(r, text=it["start"], bg=bg, fg=GREY if done else ORANGE_D, font=("Consolas", 10, "bold"), width=6, anchor="w").pack(side="left")
            tk.Label(r, text=clip(it["task"], 22), bg=bg, fg=GREY if done else INK,
                     font=(FONT_UI, 9, "overstrike" if done else "normal"), anchor="w").pack(side="left")
            if d == today and not done and not self.session:
                self.tt_btn(r, "Start", lambda i=it: self.start_session(i["task"], i["mins"], i), bg=T["start"], size=8,
                            padx=6, pady=0).pack(side="right")
            shown += 1
        if len(rows) > shown:
            tk.Label(c, text="+ %d more on your timetable" % (len(rows) - shown), bg=bg, fg=GREY, font=(FONT_UI, 8),
                     anchor="w").pack(fill="x", padx=16)
        for tid, m in short.items():
            title = next((d["title"] for d in load_deadlines() if d.get("id") == tid), "an exam")
            tk.Label(c, text="Uu~ %s more for %s didn't fit. Mark more free hours?" % (fmt_hm(m), clip(title, 20)), bg=bg,
                     fg=T["bad"], font=(FONT_UI, 8), anchor="w", wraplength=260, justify="left").pack(fill="x", padx=16, pady=(4, 0))
        b = tk.Frame(c, bg=bg)
        b.pack(fill="x", padx=16, pady=(8, 12))
        self.tt_btn(b, "Re-plan now", lambda: self.fox_reply(self.plan_reply()), bg=ORANGE, fg=ON_ACC, size=9, padx=10, pady=1).pack(side="left")

    # ---- the clock ----
    def up_clock(self, c, S):
        bg = T["card"]
        chips = tk.Frame(c, bg=bg)
        chips.pack(pady=(0, 4))
        for i, nm in enumerate(["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]):
            on = i == self.up_day
            self.tt_btn(chips, nm, lambda i=i: self.up_pick_day(i), bg=ORANGE if on else FIELD, fg=ON_ACC if on else INK,
                        size=8, padx=5, pady=0).pack(side="left", padx=1)
        cv = tk.Canvas(c, width=S, height=S, bg=bg, highlightthickness=0, cursor="hand2")
        cv.pack(padx=10)
        self.up_cv, self.up_S = cv, S
        self.up_info = tk.Label(c, text="", bg=bg, fg=GREY, font=(FONT_UI, 9), wraplength=S + 20, justify="center")
        self.up_info.pack(pady=(2, 0))
        bb = tk.Frame(c, bg=bg)
        bb.pack(pady=(4, 10))
        self.tt_btn(bb, "午前 AM" if self.up_pm else "午後 PM", self.up_flip, bg=T["start"], size=9, padx=8, pady=1).pack(side="left", padx=2)
        self.tt_btn(bb, "Copy to weekdays", self.up_copy, bg=FIELD, size=9, padx=8, pady=1).pack(side="left", padx=2)
        self.tt_btn(bb, "Clear", self.up_clear, bg=T["delbtn"], size=9, padx=8, pady=1).pack(side="left", padx=2)
        cv.bind("<ButtonPress-1>", self.up_press)
        cv.bind("<B1-Motion>", self.up_drag)
        cv.bind("<ButtonRelease-1>", self.up_release)
        cv.bind("<Motion>", self.up_hover)
        cv.bind("<Leave>", lambda e: self.up_info_default())
        self.up_draw()
        self.up_info_default()
        self.up_tick(cv)

    def up_date(self):
        """The next date that falls on the weekday shown on the clock (today if it's today)."""
        t = datetime.date.today()
        return t + datetime.timedelta(days=(self.up_day - t.weekday()) % 7)

    def up_hours(self):
        return set(int(h) for h in self.free_for(self.up_date()))

    def up_info_default(self):
        try:
            d = self.up_date()
            hrs = sorted(self.up_hours())
            self.up_info.config(text="Free on %s: %s\nTap or drag over the hours on the ring to mark when you can study." % (
                DAY_NAMES[self.up_day] + "s", hours_text(hrs) if hrs else "none yet"))
        except (tk.TclError, AttributeError):
            pass

    def up_geom(self):
        S = self.up_S
        R = S / 2.0 - 6
        return S / 2.0, S / 2.0, R

    def up_hit(self, x, y):
        cx, cy, R = self.up_geom()
        d = math.hypot(x - cx, y - cy)
        if not (R - 36 <= d <= R + 2):
            return None
        a = (math.degrees(math.atan2(x - cx, cy - y)) + 360) % 360       # clockwise from 12 o'clock
        return int(a // 30) + (12 if self.up_pm else 0)

    def up_draw(self):
        cv = self.up_cv
        if cv is None or not cv.winfo_exists():
            return
        cv.delete("face")
        cx, cy, R = self.up_geom()
        bg = T["card"]
        jp = _jp_font(self.root)
        shu = self.SHU
        free = self.up_hours()
        day = self.up_date()
        # outer lacquer rim with a gold line
        cv.create_oval(cx - R, cy - R, cx + R, cy + R, fill=_mixhex(shu, NIGHT, 0.45), outline=GOLD, width=2, tags="face")
        # the 12 hour segments for marking free time
        for k in range(12):
            h = k + (12 if self.up_pm else 0)
            on = h in free
            col = _mixhex(bg, GOLD, 0.62) if on else _mixhex(bg, "#000000", 0.28)
            rm = R - 21
            cv.create_arc(cx - rm, cy - rm, cx + rm, cy + rm, start=90 - (k + 1) * 30 + 1.2, extent=27.6, style="arc",
                          outline=col, width=24, tags=("face", "seg"))
            a = math.radians(k * 30 + 15)
            cv.create_text(cx + rm * math.sin(a), cy - rm * math.cos(a), text="%02d" % h, fill=ON_ACC if on else GREY,
                           font=(FONT_UI, 8, "bold"), tags="face")
        # thin band: what's on the timetable that day (study in foxfire orange, other things in grey)
        rb = R - 40
        cv.create_oval(cx - rb, cy - rb, cx + rb, cy + rb, outline=_mixhex(bg, "#000000", 0.35), width=6, tags="face")
        for it in tt_today(self.tt, day):
            h0, m0 = map(int, it["start"].split(":"))
            a0 = h0 * 60 + m0
            a1 = a0 + int(it["mins"])
            base = 720 if self.up_pm else 0
            s0, s1 = max(a0, base), min(a1, base + 720)
            if s1 <= s0:
                continue
            st_deg = (s0 - base) / 2.0
            ext = (s1 - s0) / 2.0
            col = ORANGE if it.get("plan") else _mixhex(bg, INK, 0.45)
            cv.create_arc(cx - rb, cy - rb, cx + rb, cy + rb, start=90 - st_deg - ext, extent=max(1.0, ext - 0.6), style="arc",
                          outline=col, width=6, tags="face")
        # the face: a soft radial glow, gold ring, ticks, kanji numerals
        rf = R - 45
        for i in range(10, 0, -1):
            r_ = rf * i / 10.0
            cv.create_oval(cx - r_, cy - r_, cx + r_, cy + r_, fill=_mixhex(_mixhex(bg, NIGHT, 0.45), _mixhex(bg, INK, 0.06), 1 - i / 10.0),
                           outline="", tags="face")
        cv.create_oval(cx - rf, cy - rf, cx + rf, cy + rf, outline=GOLD, width=1, tags="face")
        for mnt in range(60):
            a = math.radians(mnt * 6)
            r1 = rf - (9 if mnt % 5 == 0 else 5)
            cv.create_line(cx + (rf - 3) * math.sin(a), cy - (rf - 3) * math.cos(a), cx + r1 * math.sin(a), cy - r1 * math.cos(a),
                           fill=GOLD if mnt % 5 == 0 else _mixhex(bg, INK, 0.35), width=2 if mnt % 5 == 0 else 1, tags="face")
        rn = rf - 24
        for k in range(12):
            a = math.radians(k * 30)
            cv.create_text(cx + rn * math.sin(a), cy - rn * math.cos(a), text=KANJI_NUM[k] if jp else str(k or 12), fill=INK,
                           font=(jp or FONT_UI, 11 if jp else 10, "bold"), tags="face")
        wk = "月火水木金土日"[day.weekday()]
        cv.create_text(cx, cy - rf * 0.42, text=("午後" if self.up_pm else "午前") if jp else ("PM" if self.up_pm else "AM"),
                       fill=GOLD, font=(jp or FONT_UI, 12, "bold"), tags="face")
        cv.create_text(cx, cy - rf * 0.24, text=("%d月%d日 (%s)" % (day.month, day.day, wk)) if jp else day.strftime("%a %d %b"),
                       fill=GREY, font=(jp or FONT_UI, 8), tags="face")
        try:
            key = ("upfox", self.cfg.get("theme"), self.cfg.get("coat"))
            if getattr(self, "_upfox_key", None) != key:
                self._upfox = self.small_fox(1)
                self._upfox_key = key
            cv.create_image(cx, cy + rf * 0.12, image=self._upfox, anchor="n", tags="face")
        except Exception:
            pass
        cv.tag_lower("face")
        self.up_hands()

    def up_hands(self):
        cv = self.up_cv
        if cv is None or not cv.winfo_exists():
            return
        cv.delete("hands")
        cx, cy, R = self.up_geom()
        rf = R - 45
        now = datetime.datetime.now()
        sec = now.second + now.microsecond / 1e6
        ah = math.radians(((now.hour % 12) + now.minute / 60.0 + sec / 3600.0) * 30)
        am = math.radians((now.minute + sec / 60.0) * 6)
        asec = math.radians(int(sec) * 6)

        def hand(a, length, w, tail, fill, outline):
            sx, sy = math.sin(a), -math.cos(a)
            px, py = -sy, sx
            pts = [cx - sx * tail + px * w * 0.6, cy - sy * tail + py * w * 0.6,
                   cx + px * w, cy + py * w,
                   cx + sx * length * 0.82 + px * w * 0.55, cy + sy * length * 0.82 + py * w * 0.55,
                   cx + sx * length, cy + sy * length,
                   cx + sx * length * 0.82 - px * w * 0.55, cy + sy * length * 0.82 - py * w * 0.55,
                   cx - px * w, cy - py * w,
                   cx - sx * tail - px * w * 0.6, cy - sy * tail - py * w * 0.6]
            cv.create_polygon(pts, fill=fill, outline=outline, width=1, tags="hands")
        # now-marker on the ring (when looking at today and this half of the day)
        if self.up_date() == now.date() and (now.hour >= 12) == self.up_pm:
            a = math.radians(((now.hour % 12) + now.minute / 60.0) * 30)
            rr = R - 3
            x, y = cx + rr * math.sin(a), cy - rr * math.cos(a)
            cv.create_oval(x - 5, y - 5, x + 5, y + 5, fill=GLOW, outline="#ffffff", width=1, tags="hands")
        hand(ah, rf * 0.55, 4.5, 12, GOLD, _mixhex(GOLD, "#000000", 0.5))
        hand(am, rf * 0.84, 3.2, 14, INK, _mixhex(INK, "#000000", 0.5))
        sx, sy = math.sin(asec), -math.cos(asec)
        cv.create_line(cx - sx * 20, cy - sy * 20, cx + sx * rf * 0.9, cy + sy * rf * 0.9, fill=self.SHU, width=2, tags="hands")
        fx, fy = cx - sx * 20, cy - sy * 20
        cv.create_oval(fx - 4, fy - 4, fx + 4, fy + 4, fill=GLOW, outline=self.SHU, tags="hands")
        cv.create_oval(cx - 7, cy - 7, cx + 7, cy + 7, fill=GOLD, outline=_mixhex(GOLD, "#000000", 0.5), tags="hands")
        cv.create_oval(cx - 2.5, cy - 2.5, cx + 2.5, cy + 2.5, fill=self.SHU, outline="", tags="hands")

    def up_tick(self, cv):
        if cv is not self.up_cv or not cv.winfo_exists():
            return
        try:
            self.up_hands()
        except tk.TclError:
            return
        ms = 1000 - datetime.datetime.now().microsecond // 1000
        cv.after(max(50, ms + 5), lambda: self.up_tick(cv))

    def up_set_hour(self, h, on):
        L = self.life
        key = str(self.up_day)
        cur = set(int(x) for x in self.free_for(self.up_date()))
        if on:
            cur.add(h)
        else:
            cur.discard(h)
        L["free"][key] = sorted(cur)
        L["free_dates"].pop(self.up_date().isoformat(), None)
        L["free_set"] = True

    def up_press(self, e):
        h = self.up_hit(e.x, e.y)
        if h is None:
            return
        self._up_paint = h not in self.up_hours()
        self._up_painting = True
        self.up_set_hour(h, self._up_paint)
        ui_sound("toggle")
        self.up_draw()

    def up_drag(self, e):
        if not getattr(self, "_up_painting", False):
            return
        h = self.up_hit(e.x, e.y)
        if h is not None and (h in self.up_hours()) != self._up_paint:
            self.up_set_hour(h, self._up_paint)
            self.up_draw()
        self.up_hover(e)

    def up_release(self, e):
        if not getattr(self, "_up_painting", False):
            return
        self._up_painting = False
        self.life_save()
        self.root.after(150, self.replan)

    def up_hover(self, e):
        h = self.up_hit(e.x, e.y)
        if h is None:
            return self.up_info_default()
        day = self.up_date()
        what = [it["task"] for it in tt_today(self.tt, day) if int(it["start"][:2]) == h]
        st = "free for study" if h in self.up_hours() else "not free"
        self.up_info.config(text="%s  %02d:00-%02d:00  ·  %s%s\nClick to %s." % (
            DAY_NAMES[day.weekday()][:3], h, h + 1, st, ("  ·  " + clip(", ".join(what), 40)) if what else "",
            "unmark" if h in self.up_hours() else "mark it free"))

    def up_pick_day(self, i):
        self.up_day = i
        self.dl_render()

    def up_flip(self):
        self.up_pm = not self.up_pm
        self.dl_render()

    def up_copy(self):
        hrs = sorted(self.up_hours())
        for k in range(5):
            self.life["free"][str(k)] = list(hrs)
        self.life["free_set"] = True
        self.life_save()
        self.replan()
        self.dl_status("Copied %s to Monday-Friday." % hours_text(hrs))

    def up_clear(self):
        self.life["free"][str(self.up_day)] = []
        self.life["free_dates"].pop(self.up_date().isoformat(), None)
        self.life["free_set"] = True
        self.life_save()
        self.replan()

    # ==== the Daily page ===========================================================================
    def hub_build_daily(self, pg):
        self.hub_title(pg, "Daily", "Your streak, ema badges, check-ins, flashcards, homework help and wellbeing")
        body = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        body.pack(fill="x", padx=24, pady=14)
        self.daily_body = body
        self.daily_render()

    def daily_refresh(self):
        h = getattr(self, "hub", None)
        if not h or "daily" not in h.get("pages", {}):
            return
        self._daily_dirty = True
        if h.get("page") == "daily":
            try:
                fw = h["win"].focus_get()
            except Exception:
                fw = None
            if not isinstance(fw, (tk.Entry, tk.Text)):
                self.daily_render()

    def daily_render(self):
        body = getattr(self, "daily_body", None)
        if body is None or not body.winfo_exists():
            return
        self._daily_dirty = False
        for ch in body.winfo_children():
            ch.destroy()
        bg = T["card"]
        # stat plaques
        row = tk.Frame(body, bg=PAPER)
        row.pack(fill="x")
        hu = self.hunger()
        tummy = "Full" if hu < 25 else ("Peckish" if hu < 55 else ("Hungry" if hu < 80 else "Starving"))
        stats = [("%d day%s" % (self.streak(), "" if self.streak() == 1 else "s"), "focus streak (炎)"),
                 (fmt_hm(int(self.total_hours() * 60)) if self.total_hours() >= 1 / 60.0 else "0m", "focused in total"),
                 (self.mood_word(), "%s's mood · foxfire %d%%" % (self.fox_name(), self.spirit())),
                 (tummy, "her tummy (focus feeds her)"),
                 ("%d / %d" % (len(self.life["badges"]), len(BADGES)), "ema badges")]
        for i, (big, cap) in enumerate(stats):
            c = self.hub_card(row, shape="ema")
            c.pack(side="left", fill="both", expand=True, padx=(0 if i == 0 else 10, 0))
            tk.Label(c, text=big, bg=bg, fg=ORANGE_D, font=(FONT_UI, 17, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
            tk.Label(c, text=cap, bg=bg, fg=GREY, font=(_jp_font(self.root) or FONT_UI, 8), anchor="w").pack(fill="x", padx=14, pady=(0, 10))
        cols = tk.Frame(body, bg=PAPER)
        cols.pack(fill="x", pady=(12, 0))
        cols.grid_columnconfigure(0, weight=1, uniform="d")
        cols.grid_columnconfigure(1, weight=1, uniform="d")
        left = tk.Frame(cols, bg=PAPER)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 6))
        right = tk.Frame(cols, bg=PAPER)
        right.grid(row=0, column=1, sticky="nsew", padx=(6, 0))
        self.daily_checkin_card(left)
        self.daily_cards_card(left)
        self.daily_well_card(left)
        self.daily_badges_card(right)
        self.daily_homework_card(right)
        self.daily_facts_card(right)

    def daily_checkin_card(self, parent):
        bg = T["card"]
        c = self.hub_card(parent, "How are you today?")
        c.pack(fill="x")
        today = datetime.date.today().isoformat()
        mine = [j for j in self.life["journal"] if j.get("date") == today]
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=14, pady=(0, 4))
        nv = tk.StringVar(value=mine[-1].get("note", "") if mine else "")
        for key, lab, col in MOODS:
            on = bool(mine) and mine[-1].get("mood") == key
            self.tt_btn(r, lab, lambda k=key: self.checkin_save(k, nv.get()), bg=col if on else _mixhex(bg, col, 0.35),
                        fg=ON_ACC if on else INK, size=9, padx=8, pady=1).pack(side="left", padx=2)
        e = self.tt_entry(c, nv, 40)
        e.pack(fill="x", padx=16, pady=(2, 4), ipady=2)
        tk.Label(c, text="Optional note, then tap a mood. It's private, kept only on this PC.", bg=bg, fg=GREY,
                 font=(FONT_UI, 8), anchor="w").pack(fill="x", padx=16)
        # last 14 days of moods
        cv = tk.Canvas(c, height=44, bg=bg, highlightthickness=0)
        cv.pack(fill="x", padx=14, pady=(6, 2))
        by = {}
        for j in self.life["journal"]:
            by[j["date"]] = j["mood"]
        cols = dict((k, col) for k, _, col in MOODS)

        def draw(_e=None):
            cv.delete("all")
            W = max(200, cv.winfo_width())
            step = (W - 10) / 14.0
            for i in range(14):
                d = datetime.date.today() - datetime.timedelta(days=13 - i)
                x = 5 + step * i + step / 2
                m = by.get(d.isoformat())
                cv.create_oval(x - 7, 6, x + 7, 20, fill=cols.get(m, _mixhex(bg, "#000000", 0.25)), outline="")
                cv.create_text(x, 33, text=d.strftime("%a")[0], fill=GREY, font=(FONT_UI, 7))
        cv.bind("<Configure>", draw)
        recent = [j for j in self.life["journal"] if j.get("note")][-3:]
        for j in reversed(recent):
            tk.Label(c, text="%s · %s: %s" % (datetime.date.fromisoformat(j["date"]).strftime("%d %b"), j["mood"].title(),
                                               clip(j["note"], 60)), bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w").pack(fill="x", padx=16)
        tk.Frame(c, bg=bg, height=10).pack()

    def checkin_save(self, mood, note=""):
        today = datetime.date.today().isoformat()
        J = [j for j in self.life["journal"] if j.get("date") != today]
        J.append({"date": today, "mood": mood, "note": (note or "").strip()[:300], "t": int(time.time())})
        self.life["journal"] = J[-400:]
        self.life["last_checkin"] = today
        self.life_save()
        line = random.choice(MOOD_REPLY.get(mood, ["Kon~ thank you for telling me."]))
        self.say(line, 10)
        self.chat_line("Fox", line)
        self.set_mood("happy" if mood in ("great", "good") else "sad", 4)
        beep("happy" if mood in ("great", "good", "okay") else "pet")
        if len(self.life["journal"]) >= 7:
            self.award("journal7")
        w = getattr(self, "checkin_win", None)
        if w is not None:
            try:
                w.destroy()
            except tk.TclError:
                pass
            self.checkin_win = None
        self.daily_refresh()

