        bg = T["card"]
        c = self.hub_card(parent, "Ema badges")
        c.pack(fill="x")
        per = 6
        cw, chh = 74, 92
        rows = (len(BADGES) + per - 1) // per
        cv = tk.Canvas(c, width=per * cw, height=rows * chh, bg=bg, highlightthickness=0)
        cv.pack(padx=12, pady=(0, 4))
        jp = _jp_font(self.root)
        tip = tk.Label(c, text="Hover a plaque to see how to earn it.", bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w")
        tip.pack(fill="x", padx=16, pady=(0, 10))
        for i, (bid, kanji, name, how) in enumerate(BADGES):
            x, y = (i % per) * cw + 6, (i // per) * chh + 4
            got = bid in self.life["badges"]
            wood = "#c98a35" if got else _mixhex(bg, "#000000", 0.25)
            edge = "#7a4a1c" if got else LINE
            pts = [x + 31, y, x + 62, y + 14, x + 62, y + 60, x, y + 60, x, y + 14]
            tg = "b%d" % i
            cv.create_polygon(pts, fill=wood, outline=edge, width=2, tags=tg)
            cv.create_line(x + 22, y + 7, x + 40, y + 7, fill=self.SHU if got else LINE, width=2, tags=tg)
            cv.create_text(x + 31, y + 36, text=kanji if jp else name[:1], fill="#3a2414" if got else GREY,
                           font=(jp or FONT_UI, 20 if jp else 16, "bold"), tags=tg)
            cv.create_text(x + 31, y + 74, text=name, fill=INK if got else GREY, font=(FONT_UI, 7, "bold" if got else "normal"),
                           width=cw - 4, tags=tg)
            msg = ("%s - earned %s. %s" % (name, self.life["badges"][bid], how)) if got else ("%s (locked): %s" % (name, how))
            cv.tag_bind(tg, "<Enter>", lambda e, m=msg: tip.config(text=m))
            cv.tag_bind(tg, "<Leave>", lambda e: tip.config(text="Hover a plaque to see how to earn it."))

