    # ==== the daily check-in card next to her =========================================================
    def open_checkin(self, force=False):
        if self.checkin_win is not None:
            try:
                if self.checkin_win.winfo_exists():
                    self.checkin_win.lift()
                    return
            except tk.TclError:
                pass
        if not force and (self.session or self.lockin):
            return
        w = tk.Toplevel(self.root)
        w.overrideredirect(True)
        w.attributes("-topmost", True)
        w.configure(bg=KEY)
        try:
            w.attributes("-transparentcolor", KEY)
        except tk.TclError:
            pass
        self.checkin_win = w
        f = self.round_frame(w, T["bub"], GOLD, 16, "round", pad=10)
        f.pack(fill="both", expand=True)
        bg = T["bub"]
        nm = self.user_short()
        tk.Label(f, text="Kon kon~ how are you feeling today%s?" % ((", " + nm) if nm else ""), bg=bg, fg=INK,
                 font=(FONT_UI, 11, "bold")).pack(padx=12, pady=(10, 6))
        r = tk.Frame(f, bg=bg)
        r.pack(padx=12)
        nv = tk.StringVar()
        for key, lab, col in MOODS:
            self.tt_btn(r, lab, lambda k=key: self.checkin_save(k, nv.get()), bg=_mixhex(bg, col, 0.55), size=9, padx=7, pady=1
                        ).pack(side="left", padx=2)
        e = self.tt_entry(f, nv, 34)
        e.pack(fill="x", padx=14, pady=(8, 2), ipady=1)
        tk.Label(f, text="(optional note: what's on your mind?)", bg=bg, fg=GREY, font=(FONT_UI, 8)).pack()

        def skip():
            try:
                w.destroy()
            except tk.TclError:
                pass
            self.checkin_win = None
        self.tt_btn(f, "Not now", skip, bg=FIELD, size=8, padx=8, pady=0).pack(pady=(4, 10))
        w.update_idletasks()
        ww, hh = w.winfo_reqwidth(), w.winfo_reqheight()
        x = self.root.winfo_x() + self.W - ww - int(10 * self.U)
        y = self.root.winfo_y() - hh - int(4 * self.U)
        if y < 0:
            x, y = self.root.winfo_x() + self.COLW - ww, self.root.winfo_y() + int(10 * self.U)
        sw, sh = w.winfo_screenwidth(), w.winfo_screenheight()
        w.geometry("+%d+%d" % (max(0, min(sw - ww, x)), max(0, min(sh - hh, y))))
        beep("hello")
        self.set_mood("happy", 3)
        w.after(4 * 60 * 1000, skip)

    # ==== breathing with her foxfire =================================================================
    BREATH = {"calm": ("Calm 4-4-6", [("Breathe in", 4), ("Hold", 4), ("Breathe out", 6)]),
              "sleep": ("Sleepy 4-7-8", [("Breathe in", 4), ("Hold", 7), ("Breathe out", 8)]),
              "box": ("Box 4-4-4-4", [("Breathe in", 4), ("Hold", 4), ("Breathe out", 4), ("Rest", 4)])}

    def open_breathing(self):
        if self.breath_win is not None:
            try:
                if self.breath_win.winfo_exists():
                    self.breath_win.lift()
                    return
            except tk.TclError:
                pass
        w = tk.Toplevel(self.root)
        w.title("Breathe with %s" % self.fox_name())
        w.configure(bg=NIGHT)
        w.attributes("-topmost", True)
        w.resizable(False, False)
        self.style_titlebar(w)
        self.breath_win = w
        S = 360
        cv = tk.Canvas(w, width=S, height=S + 40, bg=NIGHT, highlightthickness=0)
        cv.pack(padx=10, pady=(10, 0))
        ctl = tk.Frame(w, bg=NIGHT)
        ctl.pack(pady=(6, 12))
        pv = tk.StringVar(value=self.cfg.get("breath_pattern", "calm"))
        st = {"t0": None, "token": 0, "rounds": 5}

        def start():
            self.cfg_set("breath_pattern", pv.get())
            st["t0"] = time.monotonic()
            st["token"] += 1
            st["done"] = False
            beep("pet")
            run(st["token"])
        for key in ("calm", "sleep", "box"):
            tk.Radiobutton(ctl, text=self.BREATH[key][0], value=key, variable=pv, bg=NIGHT, fg=INK, selectcolor=FIELD,
                           activebackground=NIGHT, activeforeground=GOLD, font=(FONT_UI, 9), highlightthickness=0).pack(side="left", padx=4)
        self.tt_btn(ctl, "Start", start, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=2).pack(side="left", padx=(10, 10))
        pal = self.pal
        cols = [pal.get("U", "#3d8bff"), pal.get("I", "#8fd8ff"), pal.get("A", "#e8f7ff")]

        def flame(s, now):
            cv.delete("fl")
            cx, cy = S / 2.0, S / 2.0 + 40
            for li, (k, col) in enumerate(((1.0, _mixhex(NIGHT, cols[0], 0.35)), (0.9, cols[0]), (0.66, cols[1]), (0.40, cols[2]))):
                sz = s * k
                pts = []
                wob = math.sin(now * 6.0 + li) * 0.06
                for i in range(48):
                    t = 2 * math.pi * i / 48.0
                    x = math.sin(t) * abs(math.sin(t / 2.0)) ** 1.4
                    y = math.cos(t)
                    pts += [cx + sz * 0.62 * x + wob * sz * (1 + y) * 0.5, cy - sz * 1.2 * y + li * sz * 0.12]
                cv.create_polygon(pts, fill=col, outline="", smooth=True, tags="fl")
            ey = cy + s * 0.05
            for dx in (-0.16, 0.16):
                cv.create_arc(cx + dx * s - 5, ey - 4, cx + dx * s + 5, ey + 4, start=200, extent=140, style="arc",
                              outline=_mixhex(cols[0], "#000000", 0.55), width=2, tags="fl")

        def text(main, sub):
            cv.delete("tx")
            cv.create_text(S / 2.0, 22, text=main, fill=INK, font=(FONT_UI, 16, "bold"), tags="tx")
            cv.create_text(S / 2.0, S + 26, text=sub, fill=GREY, font=(FONT_UI, 10), tags="tx")

        def run(token):
            if token != st["token"] or not cv.winfo_exists():
                return
            now = time.monotonic()
            phases = self.BREATH.get(pv.get(), self.BREATH["calm"])[1]
            cyc = float(sum(d for _, d in phases))
            e = now - st["t0"]
            rnd = int(e // cyc)
            if rnd >= st["rounds"]:
                flame(60, now)
                text("Well done~", "You did %d calm breaths. How do you feel?" % st["rounds"])
                if not st.get("done"):
                    st["done"] = True
                    self.award("breathe")
                    self.stat_add("breaths")
                    beep("done")
                    self.say("Otsukare~ that was lovely. Your shoulders look lighter already, ne~", 8)
                return
            x = e - rnd * cyc
            for name, d in phases:
                if x < d:
                    break
                x -= d
            f = x / float(d)
            ease = (1 - math.cos(math.pi * f)) / 2.0
            lo, hi = 55.0, 125.0
            if name == "Breathe in":
                s = lo + (hi - lo) * ease
            elif name == "Breathe out":
                s = hi - (hi - lo) * ease
            elif name == "Hold":
                s = hi + 2 * math.sin(now * 3)
            else:
                s = lo + 1.5 * math.sin(now * 3)
            flame(s, now)
            text(name + "...", "%d   ·   round %d of %d" % (int(d - x) + 1, rnd + 1, st["rounds"]))
            cv.after(33, lambda: run(token))
        flame(70, time.monotonic())
        text("Breathe with my foxfire", "In as it grows, out as it shrinks. Press Start~")

        def close():
            st["token"] += 1
            self.breath_win = None
            w.destroy()
        w.protocol("WM_DELETE_WINDOW", close)
        w.update_idletasks()
        ww, hh = w.winfo_reqwidth(), w.winfo_reqheight()
        w.geometry("+%d+%d" % ((w.winfo_screenwidth() - ww) // 2, max(0, (w.winfo_screenheight() - hh) // 3)))

