def subject_defs(life=None):
    """Your subjects (the six IB DP ones by default; Notebook > subjects can rename them)."""
    names = (life or {}).get("subject_names") or {}
    return [(sid, names.get(sid, name), short, col, al, tw, sites) for (sid, name, short, col, al, tw, sites) in SUBJECT_DEFS]


def subject_name(sid, life=None, short=False):
    for d in subject_defs(life):
        if d[0] == sid:
            return d[2] if short else d[1]
    return sid or "?"


def clean_title(title):
    t = (title or "").strip()
    for _ in range(2):
        t = TITLE_TAILS.sub("", t)
    t = re.sub(r"^\(\d+\)\s*", "", t)                      # "(3) Inbox" style counters
    return t.strip()


def _has(low, word):
    if word.endswith(" "):
        return (" " + word) in (" " + low + " ")
    return re.search(r"(?<![a-z0-9])" + re.escape(word) + r"(?![a-z0-9])", low) is not None


def classify_subject(text, learned=None):
    """(subject id or None, best score, runner-up score). Names/aliases score 4, study sites 4, learned words 3,
    topic words 1 each (up to 3)."""
    low = (text or "").lower()
    if not low.strip():
        return None, 0, 0
    ck = (low, len(learned or {}), tuple(sorted((learned or {}).items()))[-3:] if learned else ())
    hit = _CLS_CACHE.get(ck)
    if hit is not None:
        return hit
    if len(_CLS_CACHE) > 400:
        _CLS_CACHE.clear()
    _CLS_CACHE[ck] = res = _classify_subject(low, learned)
    return res


_CLS_CACHE = {}


def _classify_subject(low, learned):
    scores = {}
    for (sid, name, short, col, aliases, topics, sites) in SUBJECT_DEFS:
        sc = 0
        if any(_has(low, a) for a in aliases):
            sc += 4
        if any(s in low for s in sites):
            sc += 4
        sc += min(3, sum(1 for w in topics if _has(low, w.strip()) if len(w.strip()) > 1))
        scores[sid] = sc
    for w, sid in (learned or {}).items():
        if sid in scores and _has(low, w):
            scores[sid] += 3
    best = sorted(scores.items(), key=lambda kv: -kv[1])
    if not best or best[0][1] <= 0:
        return None, 0, 0
    return best[0][0], best[0][1], (best[1][1] if len(best) > 1 else 0)


def looks_like_study(title, proc):
    low = (title or "").lower()
    return (proc or "").lower() in STUDY_APPS or any(h in low for h in STUDY_HINTS)


def window_key(title):
    t = clean_title(title).lower()
    t = re.sub(r"\d+", "#", t)
    return re.sub(r"\s+", " ", t)[:70]


def title_words(title):
    """Distinctive words in a window title (used to learn which subject a document belongs to)."""
    out = []
    for w in re.findall(r"[a-zA-Zàâçéèêëîïôûùüÿœ][\w'\-]{3,}", clean_title(title).lower()):
        if w not in _SUBJ_STOP and not w.isdigit() and w not in out:
            out.append(w)
    return out[:4]


# ---- IB command terms (how to answer) --------------------------------------------------------------
COMMAND_TERMS = {
    "define": "Define: give the precise meaning (1-2 marks). One accurate sentence with the key term, no examples needed.",
    "state": "State: give a specific name, value or short answer. No explanation needed.",
    "list": "List: give a sequence of brief answers, no explanation.",
    "identify": "Identify: pick out the answer from a number of possibilities, briefly.",
    "outline": "Outline: give a brief account or summary - a few connected points, each one creditable.",
    "describe": "Describe: give a detailed account - what it is / what happens, step by step. No 'why' needed.",
    "explain": "Explain: give a detailed account including reasons or causes - use 'because', 'therefore', 'this leads to'.",
    "distinguish": "Distinguish: make clear the differences between two or more things - pair each point (A is..., whereas B is...).",
    "compare": "Compare: give similarities between two or more things, referring to both throughout.",
    "compare and contrast": "Compare and contrast: give similarities AND differences, referring to both each time (a table works well).",
    "contrast": "Contrast: give the differences between them, referring to both.",
    "annotate": "Annotate: add brief notes to a diagram or graph.",
    "draw": "Draw: a clear, labelled diagram with straight label lines (pencil, ruler).",
    "label": "Label: add labels to a diagram.",
    "calculate": "Calculate: get a numerical answer showing the working, with units and sensible significant figures.",
    "deduce": "Deduce: reach a conclusion from the information given - show your reasoning.",
    "predict": "Predict: give an expected result, with a reason.",
    "suggest": "Suggest: propose a solution, hypothesis or possible answer (more than one can be right).",
    "analyse": "Analyse: break it down to bring out the essential elements or structure.",
    "analyze": "Analyse: break it down to bring out the essential elements or structure.",
    "discuss": "Discuss: a balanced review with a range of arguments/factors, supported by evidence, ending in a conclusion.",
    "evaluate": "Evaluate: weigh strengths and limitations (assess implications), then judge.",
    "to what extent": "To what extent: consider the merits of an argument, with evidence on both sides, then a clear judgement.",
    "justify": "Justify: give valid reasons or evidence to support an answer or conclusion.",
    "sketch": "Sketch: a rough diagram/graph showing the key features (shape, intercepts, turning points, asymptotes).",
    "show that": "Show that: get the given result, with every step shown - don't skip any working.",
    "hence": "Hence: use the previous part to get the answer.",
    "examine": "Examine: consider an argument or concept in a way that uncovers its assumptions and interrelationships.",
    "comment": "Comment: give a judgement based on a given statement or result.",
}


def command_term(q):
    low = (q or "").lower()
    for k in sorted(COMMAND_TERMS, key=len, reverse=True):
        if re.search(r"(?<![a-z])" + re.escape(k) + r"(?![a-z])", low[:80]):
            return k
    return ""


