# ---- a small French verb conjugator (offline) ---------------------------------------------------------
FR_PRONOUNS = ["je", "tu", "il/elle/on", "nous", "vous", "ils/elles"]
FR_IRREG = {
    "être": (["suis", "es", "est", "sommes", "êtes", "sont"], "été", "ser", "ét", "avoir"),
    "avoir": (["ai", "as", "a", "avons", "avez", "ont"], "eu", "aur", "av", "avoir"),
    "aller": (["vais", "vas", "va", "allons", "allez", "vont"], "allé", "ir", "all", "être"),
    "faire": (["fais", "fais", "fait", "faisons", "faites", "font"], "fait", "fer", "fais", "avoir"),
    "pouvoir": (["peux", "peux", "peut", "pouvons", "pouvez", "peuvent"], "pu", "pourr", "pouv", "avoir"),
    "vouloir": (["veux", "veux", "veut", "voulons", "voulez", "veulent"], "voulu", "voudr", "voul", "avoir"),
    "devoir": (["dois", "dois", "doit", "devons", "devez", "doivent"], "dû", "devr", "dev", "avoir"),
    "prendre": (["prends", "prends", "prend", "prenons", "prenez", "prennent"], "pris", "prendr", "pren", "avoir"),
    "venir": (["viens", "viens", "vient", "venons", "venez", "viennent"], "venu", "viendr", "ven", "être"),
    "savoir": (["sais", "sais", "sait", "savons", "savez", "savent"], "su", "saur", "sav", "avoir"),
    "dire": (["dis", "dis", "dit", "disons", "dites", "disent"], "dit", "dir", "dis", "avoir"),
    "voir": (["vois", "vois", "voit", "voyons", "voyez", "voient"], "vu", "verr", "voy", "avoir"),
    "mettre": (["mets", "mets", "met", "mettons", "mettez", "mettent"], "mis", "mettr", "mett", "avoir"),
    "lire": (["lis", "lis", "lit", "lisons", "lisez", "lisent"], "lu", "lir", "lis", "avoir"),
    "écrire": (["écris", "écris", "écrit", "écrivons", "écrivez", "écrivent"], "écrit", "écrir", "écriv", "avoir"),
    "boire": (["bois", "bois", "boit", "buvons", "buvez", "boivent"], "bu", "boir", "buv", "avoir"),
    "partir": (["pars", "pars", "part", "partons", "partez", "partent"], "parti", "partir", "part", "être"),
    "sortir": (["sors", "sors", "sort", "sortons", "sortez", "sortent"], "sorti", "sortir", "sort", "être"),
    "dormir": (["dors", "dors", "dort", "dormons", "dormez", "dorment"], "dormi", "dormir", "dorm", "avoir"),
}
FR_ETRE_VERBS = {"devenir", "revenir", "monter", "rester", "sortir", "venir", "aller", "naître", "descendre", "entrer",
                 "rentrer", "tomber", "retourner", "arriver", "mourir", "partir"}


def conjugate_fr(verb):
    """Present, passé composé, imparfait and futur simple of a French verb (regular -er/-ir/-re + common irregulars)."""
    v = verb.strip().lower()
    reflexive = v.startswith(("se ", "s'"))
    v = re.sub(r"^(?:se |s')", "", v)
    if v in FR_IRREG:
        pres, pp, fut, imp, aux = FR_IRREG[v]
    elif v.endswith("er"):
        st = v[:-2]
        g = "e" if st.endswith("g") else ""
        st_n = (st[:-1] + "ç") if st.endswith("c") else st
        strong, fut = st, v                                # stem-changing verbs (boot verbs)
        m = re.match(r"^(.*)([eé])([^aeiouéèêy]+)$", st)
        if st.endswith("y") and not st.endswith("ay"):
            strong = st[:-1] + "i"                          # nettoyer -> nettoie
            fut = strong + "er"
        elif v in ("appeler", "rappeler", "jeter", "rejeter", "épeler"):
            strong = st + st[-1]                            # appeler -> appelle
            fut = strong + "er"
        elif m and len(m.group(3)) <= 2:
            strong = m.group(1) + "è" + m.group(3)          # lever -> lève, préférer -> préfère
            if m.group(2) == "e":
                fut = strong + "er"                          # lèverai (préférer keeps préférerai)
        pres = [strong + "e", strong + "es", strong + "e", st_n + g + "ons", st + "ez", strong + "ent"]
        pp, imp, aux = st + "é", st_n + g, "avoir"
    elif v.endswith("ir"):
        st = v[:-2]
        pres = [st + "is", st + "is", st + "it", st + "issons", st + "issez", st + "issent"]
        pp, fut, imp, aux = st + "i", v, st + "iss", "avoir"
    elif v.endswith("re"):
        st = v[:-2]
        pres = [st + "s", st + "s", st, st + "ons", st + "ez", st + "ent"]
        pp, fut, imp, aux = st + "u", v[:-1], st, "avoir"
    else:
        return None
    if v in FR_ETRE_VERBS or reflexive:
        aux = "être"
    aux_f = FR_IRREG[aux][0]
    ends_i = ["ais", "ais", "ait", "ions", "iez", "aient"]
    ends_f = ["ai", "as", "a", "ons", "ez", "ont"]
    refl = ["me", "te", "se", "nous", "vous", "se"]

    def subj(i, word):
        p = FR_PRONOUNS[i]
        if reflexive:
            r = refl[i]
            word = (r[0] + "'" + word) if (r in ("me", "te", "se") and word[:1] in "aeiouéèêh") else r + " " + word
        if i == 0 and word[:1] in "aeiouéèêh":
            return "j'" + word
        return p + " " + word
    agree = ["", "", "(e)", "(e)s", "(e)(s)", "(e)s"] if aux == "être" else [""] * 6
    lines = ["%s (%s)" % (("se " if reflexive else "") + v, "conjugated with être" if aux == "être" else "conjugated with avoir")]
    lines.append("Présent: " + ", ".join(subj(i, pres[i]) for i in range(6)))
    lines.append("Passé composé: " + ", ".join(subj(i, aux_f[i] + " " + pp + agree[i]) for i in range(6)))
    lines.append("Imparfait: " + ", ".join(subj(i, imp + ends_i[i]) for i in range(6)))
    lines.append("Futur simple: " + ", ".join(subj(i, fut + ends_f[i]) for i in range(6)))
    lines.append("Futur proche: je vais %s, nous allons %s" % (("me " + v) if reflexive else v, ("nous " + v) if reflexive else v))
    return "\n".join(lines)


_NOTE_COMMON = set("cell cells approach paper structure function data the and for".split())


def ib_notes_for(sid, q, n=2):
    """The best matching entries from Zenko's offline IB notes for a subject: [(topic, notes)]."""
    qt = set(_terms(q))
    low = q.lower()
    scored = []
    for (s, topic, kw, notes) in IB_NOTES:
        if sid and s != sid:
            continue
        kws = set(k for k in kw.split() if len(k) > 2)
        sc = 0.0
        for k in kws:
            wgt = 0.5 if k in _NOTE_COMMON else 2.0
            if k in qt or (len(k) > 4 and re.search(r"(?<![a-z])" + re.escape(k), low)):
                sc += wgt
            elif len(k) >= 7 and k[:6] in low:
                sc += wgt * 0.75                       # integrate ~ integration, replicate ~ replication
        sc += sum(0.5 if w in _NOTE_COMMON else 2.0 for w in _terms(topic) if w in qt)
        sc += 6 if topic.lower().split(":")[0] in low else 0
        if sc >= 1.5:
            scored.append((sc, topic, notes))
    scored.sort(key=lambda x: -x[0])
    if not scored:
        return []
    top = scored[0][0]
    return [(t, nt) for sc, t, nt in scored[:n] if sc >= max(1.5, top * 0.7)]


def ib_note_cards(sid, q="", n=8):
    """Quick flashcards from the offline notes (one key fact per card), for 'test me' without the smart brain."""
    pool = [e for e in IB_NOTES if e[0] == sid]
    if q:
        hit = ib_notes_for(sid, q, 3)
        if hit:
            pool = [e for e in pool if e[1] in [t for t, _ in hit]]
    cards = []
    for (s, topic, kw, notes) in pool:
        for sent in re.split(r"(?<=[.;])\s+", notes):
            m = re.match(r"^([A-Z][\w\- /()']{2,40}?)(:| = | is | are | means )\s*(.{12,200})$", sent.strip())
            if m:
                term, how, rest = m.group(1).strip(), m.group(2).strip(), m.group(3).strip().rstrip(".;")
                term = re.sub(r"\s*\(.*?\)", "", term)
                verb = "Outline" if how == ":" else "Define"
                cards.append({"q": "%s - %s %s." % (topic, verb, term[:1].lower() + term[1:] if not term[:2].isupper() else term),
                              "a": rest, "long": True, "subject": sid})
    random.shuffle(cards)
    return cards[:n]


def marks_for(given, model):
    """Rough marking for a written answer: how many of the model answer's key words you used. Returns 0..1."""
    key = [w for w in dict.fromkeys(_terms(model)) if len(w) > 3][:14]
    if not key:
        return 1.0 if answer_close(given, model) else 0.0
    g = set(_terms(given))
    gl = given.lower()
    hit = sum(1 for k in key if k in g or (len(k) > 5 and k[:5] in gl))
    return hit / float(len(key))


