def simple_wiki(topic):
    """A plain-words summary from Simple English Wikipedia (great for 'explain like I'm 12')."""
    try:
        api = WEB["wiki_api"].replace("en.wikipedia.org", "simple.wikipedia.org")
        sm = WEB["wiki_sum"].replace("en.wikipedia.org", "simple.wikipedia.org")
        j = http_json("%s?action=query&list=search&srsearch=%s&srlimit=1&format=json" % (api, _q(topic)), 8)
        hits = (j.get("query") or {}).get("search") or []
        if not hits:
            return None
        s = http_json(sm + _q(hits[0]["title"].replace(" ", "_")), 8)
        if not s.get("extract") or s.get("type") == "disambiguation":
            return None
        return {"title": s.get("title", hits[0]["title"]) + " (Simple Wikipedia)",
                "url": (((s.get("content_urls") or {}).get("desktop")) or {}).get("page", ""), "text": s["extract"]}
    except Exception:
        return None


def subject_research(sid, q, n_pages=2):
    """Web pages for a question, searched with the subject's name and with that subject's study sites first."""
    qq = clean_query(q)
    docs = []
    res, eng = search_results("%s %s" % (SUBJECT_QUERY.get(sid, ""), qq), 8)
    sites = []
    for d in SUBJECT_DEFS:
        if d[0] == sid:
            sites = [s.replace(" ", "") for s in d[6]]
    res.sort(key=lambda r: 0 if any(s.split()[0] in r["url"].replace("-", "") for s in sites) else 1)
    picks, seen = [], set()
    for r in res:
        host = urllib.parse.urlparse(r["url"]).netloc.replace("www.", "")
        if host in seen or re.search(r"youtube|tiktok|instagram|facebook|pinterest|reddit\.com/r/.*/comments", host):
            continue
        seen.add(host)
        picks.append(r)
        if len(picks) >= n_pages:
            break
    if picks:
        import concurrent.futures as _cf
        with _cf.ThreadPoolExecutor(max_workers=3) as ex:
            got = list(ex.map(lambda r: page_text(r["url"]), picks))
        for r, (title, text) in zip(picks, got):
            if len(text) >= 300:
                docs.append({"title": r["title"] or title or r["url"], "url": r["url"], "text": text})
    if sid not in ("french", "english"):
        w = wiki_extract("%s %s" % (wiki_topic(qq), SUBJECT_WIKI_HINT.get(sid, "")))
        if w:
            docs.append(w)
    sn = " ".join(r["snippet"].rstrip(".") + "." for r in res[:6] if len(r.get("snippet", "")) > 40)
    if sn:
        docs.append({"title": "search results (%s)" % eng, "url": "", "text": sn})
    return docs


class ZenkoStudy:
    """Study smarts (zenko8): automatic subject tracking, exam-hour credit, missed-session re-planning, goals,
    weak-subject alerts, end-of-day recap, best focus times, distraction report and the subject Notebook.
    Mixed into FoxBuddy before ZenkoLife."""

    # ---- set-up ----------------------------------------------------------------------------------
    def study_init(self):
        L = self.life
        for k in ("slog", "dlog", "hourlog", "win_subj", "subj_words", "goals", "unsorted", "nb_hist"):
            L.setdefault(k, {})
        self.st = {"buf": {}, "credit": {}, "asked": {}, "override": None, "last_flush": time.monotonic(),
                   "title": "", "now": None, "tidy": ""}
        self.nb = None
        self.nb_quiz = None
        self.nb_sid = L.get("nb_last", "overview")
        self._last_fg = None
        self.root.after(20000, self.study_slow_tick)

    def subjects(self):
        return subject_defs(self.life)

    def sname(self, sid, short=True):
        return subject_name(sid, self.life, short)

    # ---- every second: what are you doing right now? -------------------------------------------------
    def study_tick(self):
        fg = self._last_fg
        if not fg:
            return
        title, proc, idle, site = fg
        S = self.st
        limit = max(60, int(self.cfg.get("track_idle_minutes", 6) or 6) * 60)
        if not self.cfg.get("auto_track", True):
            return
        if self.brk or idle >= limit:
            S["buf"] = {}                       # you stepped away: the last few minutes don't count (honest hours)
            S["now"] = None
            return
        what = self.study_classify(title, proc, site)
        S["now"] = what
        if what:
            S["buf"][what] = S["buf"].get(what, 0) + 1
        if idle < 3 and S["buf"]:
            buf, S["buf"] = S["buf"], {}
            self.study_commit(buf)
        now = time.monotonic()
        if now - S["last_flush"] >= 60:
            S["last_flush"] = now
            self.study_flush()

    def study_context_subject(self):
        """A subject from what you told me you're doing: 'I'm studying bio', your focus session, or the planned session now."""
        ov = self.st.get("override")
        if ov and ov[1] > time.time():
            return ov[0]
        s = self.session
        if s:
            sid, sc, _ = classify_subject(s.get("task", ""), self.life["subj_words"])
            if sid and sc >= 1:
                return sid
        now = datetime.datetime.now()
        for it in tt_today(self.tt):
            if not it.get("plan") and not re.search(r"\b(stud|revis|homework|hw)\w*", it.get("task", ""), re.I):
                continue
            try:
                st_, en = tt_window(it)
            except Exception:
                continue
            if st_ - datetime.timedelta(minutes=5) <= now <= en:
                sid, sc, _ = classify_subject(it.get("task", ""), self.life["subj_words"])
                if sid:
                    return sid
        return None

    def study_classify(self, title, proc, site):
        if not title and not proc:
            return None
        low = (title or "").lower()
        if proc in ("zenko.exe",) or low.startswith(APP_NAME.lower()) or (proc.startswith("python") and "zenko" in low):
            h = getattr(self, "hub", None)          # her own Notebook page counts as studying that subject
            if h and h.get("page") == "notebook" and self.nb_sid in dict((d[0], 1) for d in SUBJECT_DEFS):
                return ("s", self.nb_sid)
            return None
        ct = clean_title(title)
        self.st["title"] = ct
        ov = self.st.get("override")
        if ov and ov[1] > time.time() and not site:
            return ("s", ov[0])
        key = window_key(ct)
        ws = self.life["win_subj"].get(key)
        if ws == "-":
            return ("d", site) if site else None
        if ws:
            return ("s", ws)
        sid, sc, sc2 = classify_subject(ct, self.life["subj_words"])
        if sid and sc >= 3 and sc - sc2 >= 2:
            return ("s", sid)
        if site:
            return ("d", site)
        ctx = self.study_context_subject()
        studyish = looks_like_study(ct, proc) or bool(self.session)
        if ctx and (studyish or (sid == ctx)):
            return ("s", ctx)
        if studyish and key:
            return ("u", key, sid or ctx or "")
        return None

    def study_commit(self, buf):
        L, S = self.life, self.st
        today = datetime.date.today().isoformat()
        hl = L["hourlog"].setdefault(today, {}).setdefault(str(datetime.datetime.now().hour), [0, 0])
        for k, n in buf.items():
            if k[0] == "s":
                day = L["slog"].setdefault(today, {})
                day[k[1]] = day.get(k[1], 0) + n
                S["credit"][k[1]] = S["credit"].get(k[1], 0) + n
                hl[0] += n
            elif k[0] == "d":
                day = L["dlog"].setdefault(today, {})
                day[k[1]] = day.get(k[1], 0) + n
                hl[1] += n
            elif k[0] == "u":
                u = L["unsorted"].setdefault(k[1], {"title": S.get("title", "")[:90], "secs": 0, "date": today, "guess": k[2]})
                if u.get("date") != today:
                    u["secs"], u["date"] = 0, today
                u["secs"] += n
                if k[2]:
                    u["guess"] = k[2]
                hl[0] += n
                self.study_maybe_ask(k[1])

    def study_flush(self):
        for sid, secs in list(self.st["credit"].items()):
            if secs >= 60:
                m = int(secs // 60)
                self.st["credit"][sid] = secs - m * 60
                try:
                    self.credit_minutes(sid, m)
                except Exception:
                    pass
        self.study_tidy()
        self.life_save()

    def study_tidy(self):
        """Keep the logs small: 60 days of subjects/distractions, 35 days of hours, unsorted from today only."""
        today = datetime.date.today()
        if self.st.get("tidy") == today.isoformat():
            return
        self.st["tidy"] = today.isoformat()
        L = self.life
        for k, keep in (("slog", 60), ("dlog", 60), ("hourlog", 35)):
            cut = (today - datetime.timedelta(days=keep)).isoformat()
            L[k] = dict((d, v) for d, v in L[k].items() if d >= cut)
        L["unsorted"] = dict((k, v) for k, v in L["unsorted"].items() if v.get("date") == today.isoformat())

    # ---- asking "studying Bio?" with one tap ----------------------------------------------------------
    def study_maybe_ask(self, key):
        u = self.life["unsorted"].get(key)
        if not u or u["secs"] < int(self.cfg.get("ask_after_seconds", 120) or 120) or not self.cfg.get("ask_subject", True):
            return
        now = time.monotonic()
        if now - self.st["asked"].get(key, -9999) < 600 or now - self.st["asked"].get("*", -9999) < 90:
            return
        if self.alerted or self.current_mood() == "alert" or self.lock_eating or self.quiz:
            return
        self.st["asked"][key] = self.st["asked"]["*"] = now
        self.study_ask(key)

    def study_ask(self, key):
        u = self.life["unsorted"].get(key)
        if not u:
            return
        guess = u.get("guess") or ""
        order = [guess] if guess else []
        for d in self.subjects():
            if d[0] not in order:
                order.append(d[0])
        choices = [(("✓ " if sid == guess else "") + self.sname(sid), (lambda s=sid: self.study_sort(key, s))) for sid in order]
        choices.append(("Not study", lambda: self.study_sort(key, None)))
        if guess:
            text = "Kon? Studying %s right now? (“%s”)" % (self.sname(guess), clip(u["title"], 34))
        else:
            text = "Ne~ what are you studying here? (“%s”) Tap one and I'll remember~" % clip(u["title"], 34)
        self.say(text, 45, choices)

    def study_sort(self, key, sid):
        L = self.life
        u = L["unsorted"].pop(key, None) or {"title": "", "secs": 0, "date": datetime.date.today().isoformat()}
        L["win_subj"][key] = sid or "-"
        if len(L["win_subj"]) > 600:
            for k in list(L["win_subj"])[:100]:
                L["win_subj"].pop(k, None)
        if not sid:
            self.life_save()
            self.say("Okay~ I won't count that window. Have fun~", 4)
            return
        aliases = set(a for d in SUBJECT_DEFS for a in d[4])
        for w in title_words(u.get("title", "")):
            if len(w) >= 5 and w not in aliases:
                L["subj_words"][w] = sid
        if len(L["subj_words"]) > 400:
            for k in list(L["subj_words"])[:80]:
                L["subj_words"].pop(k, None)
        secs = int(u.get("secs", 0))
        day = L["slog"].setdefault(u.get("date") or datetime.date.today().isoformat(), {})
        day[sid] = day.get(sid, 0) + secs
        self.st["credit"][sid] = self.st["credit"].get(sid, 0) + secs
        self.study_flush()
        ex = self.exam_for(sid)
        self.set_mood("happy", 3)
        self.say("Yatta~ counted %s to %s%s. I'll remember this one!" % (
            fmt_hm(secs // 60) if secs >= 60 else "it", self.sname(sid),
            (" (and toward “%s”)" % clip(ex["title"], 24)) if ex else ""), 7)
        self.nb_refresh()

    # ---- crediting time toward your exams (the MYA hour counter) ---------------------------------------
    def exam_for(self, sid, specific_only=False):
        """The nearest upcoming exam/deadline this subject counts toward ('Bio MYA'; a plain 'MYA' counts for every subject)."""
        try:
            self.plan_targets()                       # makes sure every deadline has an id
        except Exception:
            pass
        now = datetime.datetime.now()
        cands = []
        for d in load_deadlines():
            if d.get("done") or d.get("kind", "Deadline") not in PLAN_KINDS or not d.get("id"):
                continue
            try:
                due = deadline_due(d)
            except Exception:
                continue
            if due <= now or (due.date() - now.date()).days > 60:
                continue
            s2, sc, _ = classify_subject(d.get("title", ""), self.life["subj_words"])
            if s2 == sid and sc >= 1:
                cands.append((0, due, d))
            elif s2 is None and not specific_only:
                cands.append((1, due, d))
        cands.sort(key=lambda c: (c[0], c[1]))
        return cands[0][2] if cands else None

    def planned_now(self, pid):
        now = datetime.datetime.now()
        for it in tt_today(self.tt):
            if it.get("plan") == pid and not tt_done(it):
                try:
                    st_, en = tt_window(it)
                except Exception:
                    continue
                if st_ - datetime.timedelta(minutes=10) <= now <= en:
                    return it
        return None

    def credit_minutes(self, sid, mins):
        """Add studied minutes to that subject's exam. During a planned session they fill it, and once you've done
        70% of it she ticks it off on your timetable herself."""
        d = self.exam_for(sid)
        if not d or mins <= 0:
            return None
        pid = d["id"]
        it = self.planned_now(pid)
        if it:
            it["auto_s"] = int(it.get("auto_s", 0)) + int(mins * 60)
            if it["auto_s"] >= 0.7 * int(it.get("mins", 50)) * 60:
                self.tt_mark(it, True)
                self.say("Kon! You studied %s through your planned session, so I ticked “%s” off for you~" % (
                    self.sname(sid), clip(it.get("task", ""), 30)), 8)
                beep("ding")
            else:
                save_tt(self.tt)
        else:
            st = self.life["studied"]
            st[pid] = st.get(pid, 0) + mins
        self.life_save()
        try:
            self.up_refresh()
        except Exception:
            pass
        return d

    def log_study(self, sid, mins, day=None):
        """'I studied bio for 2 hours' - add it by hand."""
        L = self.life
        day = day or datetime.date.today().isoformat()
        dd = L["slog"].setdefault(day, {})
        dd[sid] = dd.get(sid, 0) + int(mins * 60)
        d = self.credit_minutes(sid, int(mins))
        self.life_save()
        self.nb_refresh()
        return d

    # ---- numbers for reports -----------------------------------------------------------------------
    def subject_minutes(self, days=7, start=None):
        """{subject: minutes} over the last `days` days (or from `start`, a date, to today)."""
        today = datetime.date.today()
        first = start or (today - datetime.timedelta(days=days - 1))
        out = {}
        for d, v in self.life["slog"].items():
            try:
                if datetime.date.fromisoformat(d) < first:
                    continue
            except Exception:
                continue
            for sid, secs in v.items():
                out[sid] = out.get(sid, 0) + secs / 60.0
        return out

    def week_start(self):
        t = datetime.date.today()
        return t - datetime.timedelta(days=t.weekday())

    def best_hours(self):
        """[(hour, study minutes per active day, on-task fraction)] best first, from the last 4 weeks."""
        agg = {}
        days = 0
        for d, hours in self.life["hourlog"].items():
            days += 1
            for h, (s, x) in hours.items():
                a = agg.setdefault(int(h), [0, 0])
                a[0] += s
                a[1] += x
        out = []
        for h, (s, x) in agg.items():
            if s >= 20 * 60:
                frac = s / float(s + x) if s + x else 0
                out.append((h, s / 60.0 / max(1, days), frac))
        out.sort(key=lambda r: -(r[1] * (0.5 + r[2])))
        return out

    def best_time_text(self):
        b = self.best_hours()
        if not b:
            return "I'm still learning your focus rhythm~ Study a few days with me and I'll tell you your golden hours!"
        top = sorted(h for h, _, _ in b[:2])
        if len(top) == 2 and top[1] - top[0] == 1:
            span = "%02d:00-%02d:00" % (top[0], top[1] + 1)
        else:
            span = " and ".join("%02d:00" % h for h in top)
        frac = sum(f for _, _, f in b[:2]) / len(b[:2])
        worst = min(b, key=lambda r: r[2])
        line = "Your golden focus time is %s (on task %d%% of the time)~" % (span, round(frac * 100))
        if len(b) >= 4 and worst[2] < 0.75:
            line += " You drift the most around %02d:00 (%d%% on task)." % (worst[0], round(worst[2] * 100))
        return line

    def distraction_report(self, days=7):
        today = datetime.date.today()
        cur, prev = {}, {}
        for d, v in self.life["dlog"].items():
            try:
                age = (today - datetime.date.fromisoformat(d)).days
            except Exception:
                continue
            tgt = cur if age < days else (prev if age < 2 * days else None)
            if tgt is None:
                continue
            for site, secs in v.items():
                tgt[site] = tgt.get(site, 0) + secs
        if not cur:
            return "Distraction report: nothing pulled you away this week~ Sugoi! (Or I haven't watched long enough yet.)"
        tot, ptot = sum(cur.values()), sum(prev.values())
        lines = ["Distraction report (last 7 days): %s in total" % fmt_hm(tot // 60) +
                 (" (%s than the week before)" % ("%s less" % fmt_hm((ptot - tot) // 60) if ptot > tot else "%s more" % fmt_hm((tot - ptot) // 60))
                  if ptot else "")]
        for site, secs in sorted(cur.items(), key=lambda kv: -kv[1])[:5]:
            lines.append("• %s: %s" % (site, fmt_hm(secs // 60) if secs >= 60 else "<1m"))
        top = max(cur.items(), key=lambda kv: kv[1])[0]
        lines.append("Tip: %s is your biggest time-eater. Try lock-in mode, or add it to 'Edit distracting sites'~" % top)
        return "\n".join(lines)

    def week_report(self):
        mins = self.subject_minutes(start=self.week_start())
        lines = ["This week (since Monday)~"]
        any_ = False
        for d in self.subjects():
            sid = d[0]
            m = mins.get(sid, 0)
            goal = float(self.life["goals"].get(sid, 0) or 0)
            ex = self.exam_for(sid, specific_only=True)
            bits = []
            if goal:
                bits.append("goal %s" % fmt_hm(int(goal * 60)))
            if ex:
                bits.append("%s %s" % (clip(ex["title"], 22), when_text(ex["date"])))
            if m >= 1 or bits:
                any_ = True
                lines.append("• %s: %s%s" % (self.sname(sid), fmt_hm(int(m)), ("  (" + ", ".join(bits) + ")") if bits else ""))
        if not any_:
            lines.append("No study tracked yet this week. Open your notes and I'll notice which subject it is~")
        return "\n".join(lines)

    def exam_progress(self, d):
        """(minutes studied, minutes needed) toward one deadline."""
        hrs = float(self.life["plan_hours"].get(d["id"], PLAN_HOURS.get(d.get("kind"), 3)))
        return float(self.life["studied"].get(d["id"], 0)), hrs * 60

    # ---- end-of-day recap ----------------------------------------------------------------------------
    def recap_text(self, day=None):
        day = day or datetime.date.today()
        iso = day.isoformat()
        L = self.life
        lines = ["Kon~ your recap for %s:" % day.strftime("%A %d %B")]
        subj = L["slog"].get(iso, {})
        tot = sum(subj.values())
        if subj:
            lines.append("Studied %s: " % fmt_hm(tot // 60) + ", ".join(
                "%s %s" % (self.sname(s), fmt_hm(v // 60)) for s, v in sorted(subj.items(), key=lambda kv: -kv[1]) if v >= 60))
        else:
            lines.append("No subject time tracked today.")
        uns = sum(u.get("secs", 0) for u in L["unsorted"].values() if u.get("date") == iso)
        if uns >= 300:
            lines.append("(+%s I wasn't sure about - sort it on the Notebook page)" % fmt_hm(uns // 60))
        rows = [i for i in tt_today(self.tt, day) if i.get("plan")]
        if rows:
            done = [i for i in rows if tt_done(i, day)]
            missed = [i for i in rows if i.get("missed") and not tt_done(i, day)]
            lines.append("Planned sessions: %d of %d done%s" % (len(done), len(rows),
                         ("; missed: " + ", ".join(clip(i["task"], 26) for i in missed[:3]) + " (I re-planned them)") if missed else ""))
        dist = L["dlog"].get(iso, {})
        if dist:
            site, secs = max(dist.items(), key=lambda kv: kv[1])
            if secs >= 300:
                lines.append("Biggest distraction: %s (%s)" % (site, fmt_hm(secs // 60)))
        tm = day + datetime.timedelta(days=1)
        nxt = tt_today(self.tt, tm)
        if nxt:
            lines.append("Tomorrow: " + "; ".join("%s %s" % (i["start"], clip(i["task"], 28)) for i in nxt[:4]) +
                         (" ...+%d more" % (len(nxt) - 4) if len(nxt) > 4 else ""))
        ups = self.upcoming_deadlines(3)
        if ups:
            d = ups[0]
            got, need = self.exam_progress(d) if d.get("id") else (0, 0)
            lines.append("Next up: %s, %s%s" % (d["title"], when_text(d["date"]),
                         (" - %s of %s studied" % (fmt_hm(int(got)), fmt_hm(int(need)))) if need else ""))
        lines.append(random.choice(["Otsukare~ rest well, you did good today!", "Every minute counts. Proud of you~kon!",
                                    "Tomorrow we go again, ne~? Sleep well!"]) if tot >= 1800 else
                     "Tomorrow's a fresh page. I'll help you start strong~")
        return "\n".join(lines)

    # ---- every 30 s: missed sessions, alerts, recap, golden hour -----------------------------------
    def study_slow_tick(self):
        try:
            self.study_slow()
        except Exception:
            pass
        self.root.after(30000, self.study_slow_tick)

    def study_slow(self):
        self.study_missed()
        if self.brk or self.lockin or idle_seconds() > 120 or self.quiz:
            return
        now = datetime.datetime.now()
        busy = bool(self.session) or self.current_mood() == "alert"
        # end-of-day recap
        rt = str(self.cfg.get("recap_time", "21:00") or "21:00")
        try:
            rh, rm = map(int, rt.split(":"))
        except Exception:
            rh, rm = 21, 0
        if self.cfg.get("recap", True) and not busy and (now.hour, now.minute) >= (rh, rm) and now.hour < 24 and \
                (self.life["slog"].get(now.date().isoformat()) or [i for i in tt_today(self.tt) if i.get("plan")]) and \
                not self.said_today("recap"):
            txt = self.recap_text()
            self.chat_line("Fox", txt)
            self.say("Your day recap is ready~ " + txt.split("\n")[1], 20,
                     [("Show me", lambda: self.open_hub("chat")), ("Thanks!", lambda: None)])
            beep("ding")
            return
        if busy:
            return
        # weak-subject alert (once a day, afternoon/evening)
        if self.cfg.get("weak_alerts", True) and 15 <= now.hour < 21 and not self.life["said"].get("weak") == now.date().isoformat():
            msg = self.weak_subject()
            if msg:
                self.said_today("weak")
                text, sid = msg
                self.say(text, 30, [("25 min %s" % self.sname(sid), lambda s=sid: self.start_session("%s revision" % self.sname(s, False), 25)),
                                    ("Later", lambda: None)])
                return
        # golden hour nudge (once a day)
        if self.cfg.get("golden_hour", True) and now.minute < 10 and not self.life["said"].get("golden") == now.date().isoformat():
            b = self.best_hours()
            if b and now.hour in [h for h, _, _ in b[:2]]:
                today_min = sum(self.life["slog"].get(now.date().isoformat(), {}).values()) / 60.0
                if today_min < 30:
                    self.said_today("golden")
                    w = self.weak_subject(any_=True)
                    sid = w[1] if w else (self.subjects()[0][0])
                    self.say("Kon! It's %02d:00, usually your golden focus hour~ Shall we use it?" % now.hour, 30,
                             [("25 min %s" % self.sname(sid), lambda s=sid: self.start_session("%s revision" % self.sname(s, False), 25)),
                              ("Not now", lambda: None)])

    def weak_subject(self, any_=False):
        """(message, subject) for the subject that most needs time, or None."""
        week = self.subject_minutes(days=7)
        wk_now = self.subject_minutes(start=self.week_start())
        today = datetime.date.today()
        frac_week = (today.weekday() + 1) / 7.0
        worst = None
        for d in self.subjects():
            sid = d[0]
            ex = self.exam_for(sid, specific_only=True)
            goal = float(self.life["goals"].get(sid, 0) or 0)
            days = (datetime.date.fromisoformat(ex["date"]) - today).days if ex else None
            m = week.get(sid, 0)
            if ex and days is not None and days <= 14 and m < 90:
                score = m / 90.0
                text = "Ne~ only %s of %s in the last 7 days, and “%s” is %s. Shall we do some %s now?" % (
                    fmt_hm(int(m)), self.sname(sid), clip(ex["title"], 26), when_text(ex["date"]), self.sname(sid))
            elif goal and today.weekday() >= 2 and wk_now.get(sid, 0) < goal * 60 * frac_week * 0.5:
                score = wk_now.get(sid, 0) / max(1.0, goal * 60 * frac_week)
                text = "Kon~ %s is behind: %s of your %s goal this week. A little session now?" % (
                    self.sname(sid), fmt_hm(int(wk_now.get(sid, 0))), fmt_hm(int(goal * 60)))
            elif any_:
                score = 2 + m / 600.0
                text = ""
            else:
                continue
            if worst is None or score < worst[0]:
                worst = (score, text, sid)
        if not worst or (not worst[1] and not any_):
            return None
        return worst[1], worst[2]

    def study_missed(self):
        """Planned sessions whose time has passed without you doing them: credit any part you did, then re-plan the rest."""
        now = datetime.datetime.now()
        fresh, changed = [], False
        for it in list(self.tt):
            if not it.get("plan") or it.get("missed"):
                continue
            try:
                day = datetime.date.fromisoformat(it.get("date", ""))
                st_, en = tt_window(it, day)
            except Exception:
                continue
            if en > now or tt_done(it, day):
                continue
            a = int(it.get("auto_s", 0))
            if a >= 0.7 * int(it.get("mins", 50)) * 60:
                self.tt_mark(it, True, day)
                continue
            it["missed"] = True
            changed = True
            if a >= 60:
                self.life["studied"][it["plan"]] = self.life["studied"].get(it["plan"], 0) + a // 60
            if now - en < datetime.timedelta(hours=20):
                fresh.append(it)
        if not changed:
            return
        save_tt(self.tt)
        self.life_save()
        if fresh and self.cfg.get("planner", True):
            self.replan()
            it = fresh[0]
            nxt = sorted([i for i in self.tt if i.get("plan") == it["plan"] and not i.get("missed") and not tt_done(i)
                          and i.get("date", "") >= now.date().isoformat()], key=lambda i: (i["date"], i["start"]))
            nxt = [i for i in nxt if tt_window(i, datetime.date.fromisoformat(i["date"]))[0] > now]
            where = ("%s %s" % (when_text(nxt[0]["date"]), nxt[0]["start"])) if nxt else "your next free hour"
            msg = "Uu~ you missed “%s” at %s. No worries, I moved it to %s~" % (clip(it["task"], 30), it["start"], where)
            if len(fresh) > 1:
                msg += " (%d missed sessions re-planned)" % len(fresh)
            self.root.after(1500, lambda: (self.say(msg, 10), self.chat_line("Fox", msg)))

    # ---- chat commands ----------------------------------------------------------------------------
    def subject_in(self, text):
        sid, sc, sc2 = classify_subject(text, self.life["subj_words"])
        return sid if sid and sc >= 1 else None

    def study_route(self, text):
        raw = text.strip()
        low = raw.lower().strip()
        lw = low.rstrip(" !.?~")
        if re.match(r"^(?:open )?(?:my )?(?:notebook|subject notebook|study notebook)$", lw):
            self.root.after(150, lambda: self.open_hub("notebook"))
            return "Opening your study books~ pick one!"
        m = re.match(r"^conjugate\s+(?:the verb\s+)?([a-zàâçéèêëîïôûùüÿœ' ]{2,30})$", lw)
        if m:
            r = conjugate_fr(m.group(1))
            return r if r else "Hmm, I only know regular -er/-ir/-re verbs and the common irregular ones~"
        # "i studied bio for 2 hours", "log 90 min chem", "i was studying bio for the past 2 hours"
        dur = re.search(r"(\d+(?:\.\d+)?|an?|one|two|three|four|five|half an?)\s*(hours?|hrs?|h|minutes?|mins?|m)\b", low)
        future = re.match(r"^(?:i'?m|i am|i will|i'll|i'?m gonna|i'?m going to|gonna|going to|let'?s)\b", lw) and \
            not re.search(r"\b(past|last|already|been|was|did|studied|revised|yesterday)\b", lw)
        if dur and future:
            sid = self.subject_in(re.sub(r"(\d+(?:\.\d+)?)\s*(hours?|hrs?|h|minutes?|mins?|m)\b", " ", low))
            if sid:
                n, unit = dur.group(1), dur.group(2)
                v = 0.5 if n.startswith("half") else (1.0 if n in ("a", "an", "one") else float(WORD_NUM.get(n, n)))
                mins = max(10, min(8 * 60, v * 60 if unit.startswith("h") else v))
                self.st["override"] = (sid, time.time() + mins * 60)
                return "Kon! I'll count the next %s as %s~ Ganbatte! (Want a timer too? Say 'focus %d min on %s')" % (
                    fmt_hm(int(mins)), self.sname(sid), int(mins), self.sname(sid))
        if dur and re.search(r"\b(stud(?:y|ied|ying)|revis(?:e|ed|ing)|did|done|worked|working|log|add|spent)\b", low) and \
                not re.match(r"^(?:how|what|when|should|can|do)\b", low):
            sid = self.subject_in(re.sub(r"(\d+(?:\.\d+)?)\s*(hours?|hrs?|h|minutes?|mins?|m)\b", " ", low))
            if sid:
                n, unit = dur.group(1), dur.group(2)
                v = 0.5 if n.startswith("half") else (1.0 if n in ("a", "an", "one") else float(WORD_NUM.get(n, n)))
                mins = v * 60 if unit.startswith("h") else v
                if 0 < mins <= 16 * 60:
                    day = datetime.date.today()
                    if re.search(r"\byesterday\b", low):
                        day -= datetime.timedelta(days=1)
                    d = self.log_study(sid, mins, day.isoformat())
                    return "Kon! Added %s of %s%s%s~ Yatta!" % (
                        fmt_hm(int(mins)), self.sname(sid), " (yesterday)" if day != datetime.date.today() else "",
                        (" - it counts toward “%s” now" % d["title"]) if d else
                        " (tell me the exam, like 'my bio MYA is on Jan 12', and it'll count toward it too)")
        m = re.match(r"^i'?m (?:now )?(?:studying|revising|doing|working on)\s+(.+)$", lw) or \
            re.match(r"^(?:switch|change) (?:subject )?to\s+(.+)$", lw)
        if m and not dur:
            sid = self.subject_in(m.group(1))
            if sid:
                self.st["override"] = (sid, time.time() + 2 * 3600)
                return "Kon! I'll count your time as %s for the next 2 hours (say 'stop studying' to end it)~" % self.sname(sid)
        if re.match(r"^(?:stop|done|finished) (?:studying|revising)$", lw):
            self.st["override"] = None
            return "Otsukare~ I'll go back to guessing from your windows."
        if re.match(r"^what (?:am i|subject am i) (?:studying|doing)|^which subject", lw):
            w = self.st.get("now")
            if w and w[0] == "s":
                return "Right now I'm counting this as %s~ (“%s”)" % (self.sname(w[1]), clip(self.st.get("title", ""), 40))
            if w and w[0] == "u":
                self.root.after(200, lambda: self.study_ask(w[1]))
                return "I'm not sure yet~ tell me with one tap!"
            return "Hmm, this doesn't look like studying to me. Say 'I'm studying bio' and I'll count it~"
        if re.match(r"^(?:(?:end of (?:the )?day|daily|day|today'?s?|my) )?recap$|^how did i do today|^(?:sum ?up|summary of) (?:my )?day", lw):
            return self.recap_text()
        if re.search(r"distraction report|what (?:distracts|distracted) me|my distractions?$|what wastes my time", lw):
            return self.distraction_report()
        if re.search(r"best (?:focus )?times?|when do i (?:focus|study) best|golden hour|focus rhythm", lw):
            return self.best_time_text()
        if re.search(r"(?:study|weekly|week'?s?) (?:report|hours|stats)|hours this week|how (?:much|long) (?:have|did) i stud", lw):
            return self.week_report()
        m = re.match(r"^(?:set )?(?:my )?(.+?) goal (?:to |is |= |of )?(\d+(?:\.\d+)?)\s*(?:h|hrs?|hours?)(?: a week| per week| weekly)?$", lw) or \
            re.match(r"^(?:i want to (?:do|study) )?(\d+(?:\.\d+)?)\s*(?:h|hrs?|hours?) (?:a|per) week (?:of|for|on) (.+)$", lw)
        if m:
            a, b = m.group(1), m.group(2)
            subj_txt, hrs = (a, b) if not re.match(r"^\d", a) else (b, a)
            sid = self.subject_in(subj_txt)
            if sid:
                self.life["goals"][sid] = float(hrs)
                self.life_save()
                self.nb_refresh()
                return "Goal set: %s of %s every week~ I'll cheer you on (and nudge you if it slips)!" % (fmt_hm(int(float(hrs) * 60)), self.sname(sid))
        m = re.match(r"^(?:eli12|eli5|explain (?:it |this )?(?:to me )?like i'?m (?:12|twelve|5|five|a kid|a child))\s*[:,\-]?\s*(.+)$", raw, re.I | re.S)
        if m:
            return self.nb_ask(self.subject_in(m.group(1)), m.group(1), "eli12", to_chat=True)
        m = re.match(r"^(?:test me|quiz me|ask me questions)(?: on| about)?\s+(.+)$", lw)
        if m and not re.search(r"\b(?:notes?|flashcards?|deck)\b", lw):
            sid = self.subject_in(m.group(1))
            if sid:
                topic = m.group(1)
                self.root.after(200, lambda: (self.open_hub("notebook"), self.nb_show(sid), self.nb_start_test(sid, topic)))
                return "Kon! Opening your %s notebook for a test on %s~" % (self.sname(sid), clip(topic, 30))
        if re.search(r"flashcards? from (?:my )?(?:notes?|file|document|pdf)|make flashcards (?:out )?of (?:my )?notes", lw):
            self.root.after(200, lambda: self.nb_cards_from_file(self.subject_in(low)))
            return "Pick your notes file (PDF, Word, PowerPoint or text) and I'll turn it into flashcards~"
        if re.match(r"^(?:review|practise|practice|redo) (?:my )?mistakes$", lw):
            return self.review_start()
        return None

    # ---- the tutor ---------------------------------------------------------------------------------
    def homework(self, q):
        """Chat 'homework: ...' now uses the subject tutor (she guesses the subject from the question)."""
        q = q.strip()
        if len(q) < 3:
            return "Paste the question after 'homework:' and I'll explain it step by step~"
        return self.nb_ask(self.subject_in(q) or (self.nb_sid if self.nb_sid in dict((d[0], 1) for d in SUBJECT_DEFS) else None), q, "explain", to_chat=True)

    def nb_ask(self, sid, q, mode="explain", to_chat=False, done=None):
        q = (q or "").strip()
        if not q:
            return "Ask me something first~"
        if self.stat_add("homework") >= 5:
            self.award("homework")
        model = self.cfg.get("llm_model") or "llama3.2:3b"
        use_llm = bool(self.cfg.get("llm_enabled", True))
        web = bool(self.cfg.get("web_enabled", True))
        hist = list(self.life["nb_hist"].get(sid or "general", []))[-2:]
        prof = self.user_profile_text()

        def job():
            return self.nb_answer(sid, q, mode, model if use_llm else None, web, hist, prof)

        def fin(res, err):
            if err or not res:
                txt = "Uu~ I got stuck on that one (%s). Try asking a bit differently?" % (err or "no answer")
                srcs = []
            else:
                txt, srcs = res
            if srcs:
                txt += "\n\nSources:\n" + "\n".join("• %s - %s" % (clip(t, 60), u) for t, u in srcs if u)
            if res:
                H = self.life["nb_hist"].setdefault(sid or "general", [])
                H.append({"q": q[:400], "a": txt[:4000], "mode": mode, "t": time.time()})
                del H[:-25]
                self.life_save()
            if to_chat:
                self.fox_reply(txt)
            if done:
                done(txt)
        self.bg(job, fin)
        self.set_mood("focus", 4)
        nm = self.sname(sid, False) if sid else "your question"
        return "Fumu fumu~ thinking about %s%s..." % (nm, " (like you're 12)" if mode == "eli12" else "")

    def nb_answer(self, sid, q, mode, model, web, hist, prof=""):
        """Runs in the background. Returns (answer text, [(title, url)])."""
        name = subject_name(sid, self.life, False) if sid else "your subjects"
        if sid == "french":
            m = re.search(r"conjugat\w*\s+(?:the verb\s+)?[\"“']?([a-zàâçéèêëîïôûùüÿœ' ]{2,30}?)[\"”']?\s*[?.!]*$", q, re.I)
            if m and conjugate_fr(m.group(1)):
                return conjugate_fr(m.group(1)), []
        if sid == "math" or not sid:
            try:
                v = calc_eval(q)
                return "Kon! %s = %s\n(Paper 1 = no calculator, so practise the working by hand too~)" % (q.strip(" =?"), fmt_num(v)), []
            except Exception:
                pass
        notes = ib_notes_for(sid, q, 2) if sid else []
        ct = command_term(q)
        docs = []
        if web:
            try:
                docs = subject_research(sid, q) if sid else []
                if not sid:
                    ans, srcs = research(q)
                    docs = [{"title": t, "url": u, "text": ans} for t, u in srcs[:1]] or [{"title": "web", "url": "", "text": ans}]
            except Exception:
                docs = []
            if mode == "eli12":
                sw = simple_wiki(wiki_topic(clean_query(q)))
                if sw:
                    docs.insert(0, sw)
        names = brain_names() if model else None
        sources = [(d["title"], d["url"]) for d in docs if d.get("url")][:3]
        if names:
            m = self.subject_model(sid, names, model)
            sysmsg = ("You are Zenko, a kind fox-girl study buddy and an expert IB Diploma Programme %s teacher and examiner. "
                      "Stay focused on %s: answer from that subject's point of view at IB DP level, using the current IB syllabus. "
                      "%s %s Be accurate; if you are not sure about a fact, say so. Format with clear Markdown (short headings, **bold** key terms, lists, a table if it helps, maths as LaTeX in $...$). "
                      "You may start with one short 'kon!' but keep the rest clear. %s" % (
                          name, name, SUBJECT_STYLE.get(sid, ""), NB_MODE_PROMPT.get(mode, NB_MODE_PROMPT["explain"]), prof))
            if sid in SYLLABUS_2027:
                sysmsg += " The student sits their exams in May 2027. Course: " + SYLLABUS_2027[sid]
            if sid == "math":
                sysmsg += " Work step by step, show every line of working, and put the final answer on its own last line."
            if ct:
                sysmsg += " The question uses the IB command term '%s': %s" % (ct, COMMAND_TERMS[ct])
            ctx, room = [], 4200
            for t, nt in notes:
                ctx.append("[IB notes: %s] %s" % (t, nt))
                room -= len(nt)
            for i, d in enumerate(docs[:4]):
                chunk = d["text"][:max(0, min(1400, room))]
                if chunk:
                    ctx.append("[%d] %s\n%s" % (i + 1, d["title"], chunk))
                    room -= len(chunk)
            msgs = [{"role": "system", "content": sysmsg}]
            for h in hist:
                msgs += [{"role": "user", "content": h["q"]}, {"role": "assistant", "content": h["a"][:1200]}]
            msgs.append({"role": "user", "content": q + (("\n\nReference material (may be incomplete; correct it if wrong):\n"
                                                          + "\n\n".join(ctx)) if ctx else "")})
            if online_ready():                             # team-up: the online brain finds it, the PC's own model checks it
                try:
                    draft, gsrc = online_chat(msgs, search=True, max_tokens=1400, timeout=90)
                except Exception as ex:
                    ONLINE["last_err"] = str(ex)
                    draft, gsrc = "", []
                if draft:
                    final, who = self.ib_recheck(sid, q, draft, mode, model)
                    note = "(found online by %s%s)" % (online_name(), (", checked for IB DP terms by %s on your PC" % who) if who else "")
                    return final + "\n\n" + note, (gsrc + sources)[:5]
            try:
                j = _ollama_json("/api/chat", {"model": m, "stream": False, "messages": msgs,
                                               "options": {"temperature": 0.3, "num_predict": 900}}, 300)
                txt = ((j.get("message") or {}).get("content") or "").strip()
            except Exception:
                txt = ""
            if txt:
                return txt, sources
        return self.nb_compose(sid, q, mode, ct, notes, docs, bool(names) or not model), sources

    def online_card(self, parent, check, radios, cfg_set, label):
        """Settings: the optional online brain (free key) that teams up with the PC's own models."""
        c = self.hub_card(parent, "Online brain (optional, free)")
        c.pack(fill="x", pady=(12, 0))
        bg = T["card"]

        def note(text, fg=GREY, size=8):
            lab = tk.Label(c, text=text, bg=bg, fg=fg, font=(FONT_UI, size), anchor="w", justify="left", wraplength=360)
            lab.pack(fill="x", padx=14, pady=(2, 2))
            return self.nb_wrap(lab)
        note("When you're online, a free online AI finds the answer (Gemini can also search the web), then your own "
             "models on this PC re-check it so it uses IB DP terms and the 2027 syllabus. Offline, or if the free limit "
             "runs out, Zenko just uses your PC's models like before.", INK, 9)

        def apply():
            online_set(self.cfg)
        ov = tk.BooleanVar(value=bool(self.cfg.get("online_on", False)))
        check(c, "Use it when I'm online", ov, lambda: (cfg_set("online_on", bool(ov.get())), apply()))
        ck = tk.BooleanVar(value=bool(self.cfg.get("online_check", True)))
        check(c, "Re-check with my PC's models", ck, lambda: cfg_set("online_check", bool(ck.get())))
        label(c, "Which one")
        pv = tk.StringVar(value=self.cfg.get("online_provider", "gemini"))
        keyv = tk.StringVar(value=(self.cfg.get("online_keys") or {}).get(pv.get(), ""))

        def set_prov():
            cfg_set("online_provider", pv.get())
            keyv.set((self.cfg.get("online_keys") or {}).get(pv.get(), ""))
            apply()
        for val, txt in ONLINE_PROVIDERS:
            tk.Radiobutton(c, text=txt, value=val, variable=pv, command=set_prov, bg=bg, fg=INK, activebackground=bg,
                           activeforeground=GOLD, selectcolor=FIELD, highlightthickness=0, font=(FONT_UI, 9),
                           anchor="w").pack(fill="x", padx=14)
        label(c, "Your free key (saved only on this PC)")
        kr = tk.Frame(c, bg=bg)
        kr.pack(fill="x", padx=14, pady=(2, 4))
        ke = self.tt_entry(kr, keyv, 18)
        ke.config(show="•")
        ke.pack(side="left")
        status = note("")

        def save_key(_e=None):
            ks = dict(self.cfg.get("online_keys") or {})
            ks[pv.get()] = keyv.get().strip()
            cfg_set("online_keys", ks)
            apply()

        def test():
            save_key()
            if not keyv.get().strip():
                status.config(text="Paste your key first~", fg=GREY)
                return
            was = ONLINE["on"]
            ONLINE["on"], ONLINE["cool"] = True, 0
            status.config(text="Testing...", fg=GREY)

            def fin(r, e):
                ONLINE["on"] = was
                ok, msg = r if r else (False, str(e))
                try:
                    status.config(text=msg, fg=T["start"] if ok else ORANGE)
                except tk.TclError:
                    pass
            self.bg(online_test, fin)
        ke.bind("<FocusOut>", save_key)
        ke.bind("<Return>", save_key)
        self.tt_btn(kr, "Test", test, bg=FIELD, size=8, padx=8, pady=1).pack(side="left", padx=(6, 0))
        self.tt_btn(c, "Get a free key...", lambda: webbrowser.open(ONLINE_SIGNUP.get(pv.get(), ONLINE_SIGNUP["gemini"])),
                    bg=T["start"], size=9, padx=10, pady=2).pack(anchor="w", padx=14, pady=(4, 2))
        note("Gemini key in 1 minute: 1) press 'Get a free key' and sign in with a Google account. 2) Press 'Create API "
             "key'. 3) Copy it, paste it above, press Test. No card needed. Free limits are small but plenty for studying.")
        note("Privacy: with this on, your tutor questions, files you ask about and screenshots you send to chat go to the "
             "online AI. Zenko never sends your screen on its own.", GREY)
        tk.Frame(c, bg=bg, height=8).pack()

    def ib_recheck(self, sid, q, draft, mode="explain", model=""):
        """The user's own Ollama subject model rewrites an online draft so it sticks to IB DP terms and the 2027 syllabus.
        Returns (text, checker model name or None). If no local model is around, the draft is returned as it is."""
        if not self.cfg.get("online_check", True):
            return draft, None
        names = ollama_models()
        if not names:
            return draft, None
        text_names = [n for n in names if "cloud" not in n and not re.search(r"vl|vision|llava|moondream|minicpm-v|embed", n)]
        if not text_names:
            return draft, None
        lm = self.subject_model(sid, text_names, model or self.cfg.get("llm_model") or "") if sid else pick_model(text_names, model)
        name = subject_name(sid, self.life, False) if sid else "IB DP"
        sysmsg = IB_CHECK % (name, SYLLABUS_2027.get(sid, "the IB DP guide for that subject"))
        if mode == "eli12":
            sysmsg += " Keep the simple, friendly style for a 12-year-old, but use the correct IB key terms."
        if sid == "math":
            sysmsg += " Re-check every line of working and the final answer."
        try:
            j = _ollama_json("/api/chat", {"model": lm, "stream": False, "messages": [
                {"role": "system", "content": sysmsg},
                {"role": "user", "content": "Student's question:\n%s\n\nDraft answer:\n%s" % (q[:3000], draft[:6000])}],
                "options": {"temperature": 0.2, "num_predict": 1000}}, 300)
            out = ((j.get("message") or {}).get("content") or "").strip()
        except Exception:
            out = ""
        return (out, lm) if len(out) > 20 else (draft, None)

    def nb_compose(self, sid, q, mode, ct, notes, docs, had_llm=False):
        """Answer without the smart brain: Zenko's IB notes + a summary of the best web pages, shaped by the mode."""
        out = []
        web = summarise_extract(q, docs, n=5 if mode == "exam" else 4, limit=950) if docs else ""
        if mode == "eli12":
            simple = next((d for d in docs if "Simple Wikipedia" in d.get("title", "")), None)
            if simple:
                out.append("In simple words~\n" + _trim_sentences(simple["text"], 4, 520))
            elif web:
                sents = sorted(_sentences(web), key=len)[:3]
                out.append("In simple words~\n" + " ".join(sents))
            if notes:
                out.append("In IB words: " + re.split(r"(?<=\.)\s", notes[0][1])[0])
        elif mode == "exam":
            if ct:
                out.append("Command term - " + COMMAND_TERMS[ct])
            pts = []
            for _, nt in notes[:1]:
                pts += [s.strip() for s in re.split(r"(?<=[.;])\s+", nt) if len(s.strip()) > 25][:4]
            pts += [s for s in _sentences(web)][:4]
            if pts:
                out.append("Mark points:\n" + "\n".join("• " + p for p in pts[:8]))
        else:
            for t, nt in notes:
                out.append("From my IB notes (%s):\n%s" % (t, nt))
            if web:
                out.append("From the web:\n" + web)
            out.append("Exam tip: " + (COMMAND_TERMS[ct] if ct else "use the exact IB terms, and link every point to the question."))
        if not [o for o in out if not o.startswith(("Exam tip", "Command term"))]:
            return ("Uu~ I couldn't find a good answer for that. Try fewer words, or the topic name (like 'cell respiration')."
                    + ("" if self.cfg.get("web_enabled", True) else " Internet lookups are off in Settings."))
        if not had_llm:
            out.append("(For full tutor-style answers, turn on the free smart brain: Settings > Smart brain setup. It stays on your PC.)")
        return ("Kon! " if mode != "exam" else "") + "\n\n".join(out)

    # ---- the Notebook page ---------------------------------------------------------------------------
    def hub_build_notebook(self, pg):
        self.hub_title(pg, "Notebook", "One page per subject: I stay on that subject. Your study time, goals and insights are on Overview")
        wrap = tk.Frame(pg, bg=PAPER)
        wrap.pack(fill="both", expand=True)
        tabs = tk.Canvas(wrap, width=178, bg=PAPER, highlightthickness=0)
        tabs.pack(side="left", fill="y", padx=(18, 0), pady=12)
        right = tk.Frame(wrap, bg=PAPER)
        right.pack(side="left", fill="both", expand=True)
        body = tk.Frame(self.hub_scroller(right), bg=PAPER)
        body.pack(fill="x", padx=(14, 24), pady=12)
        self.nb = {"tabs": tabs, "body": body, "hover": None, "ans": None, "dirty": False}
        tabs.bind("<Configure>", lambda e: self.nb_draw_tabs())
        tabs.bind("<Motion>", self.nb_tab_motion)
        tabs.bind("<Leave>", lambda e: (self.nb.__setitem__("hover", None), self.nb_draw_tabs()))
        tabs.bind("<ButtonRelease-1>", self.nb_tab_click)
        self.nb_render()

    def nb_items(self):
        return [("overview", "Overview", GOLD)] + [(d[0], d[1], d[3]) for d in self.subjects()]

    def nb_draw_tabs(self):
        nb = self.nb
        if not nb:
            return
        cv = nb["tabs"]
        try:
            cv.delete("all")
        except tk.TclError:
            return
        W = int(cv.winfo_width() or 178)
        y = 6
        nb["rects"] = []
        for key, name, col in self.nb_items():
            sel = key == self.nb_sid
            hov = key == nb.get("hover")
            h = 46
            x1 = 8 if sel else (12 if hov else 16)
            fill = T["card"] if sel else (_mixhex(PAPER, T["card"], 0.7) if hov else _mixhex(PAPER, T["card"], 0.45))
            rbox(cv, x1, y, W + 14, y + h, 12, fill=fill, outline=GOLD if sel else LINE, width=2 if sel else 1, step=2)
            cv.create_rectangle(x1 + 1, y + 8, x1 + 6, y + h - 8, fill=col, outline="")
            mins = 0
            if key != "overview":
                mins = self.subject_minutes(start=self.week_start()).get(key, 0)
            cv.create_text(x1 + 16, y + (15 if key != "overview" else h // 2), text=name, anchor="w", fill=GOLD if sel else INK,
                           font=(FONT_UI, 10, "bold"))
            if key != "overview":
                cv.create_text(x1 + 16, y + 32, text="%s this week" % fmt_hm(int(mins)), anchor="w", fill=GREY, font=(FONT_UI, 8))
            nb["rects"].append((y, y + h, key))
            y += h + 6

    def nb_tab_key(self, y):
        for (y1, y2, key) in (self.nb or {}).get("rects", []):
            if y1 <= y <= y2:
                return key
        return None

    def nb_tab_motion(self, e):
        k = self.nb_tab_key(e.y)
        if k != self.nb.get("hover"):
            self.nb["hover"] = k
            self.nb["tabs"].config(cursor="hand2" if k else "")
            self.nb_draw_tabs()

    def nb_tab_click(self, e):
        k = self.nb_tab_key(e.y)
        if k:
            ui_sound("nav")
            self.nb_show(k)

    def nb_show(self, sid):
        self.nb_sid = sid
        self.life["nb_last"] = sid
        if self.nb_quiz and self.nb_quiz.get("sid") != sid:
            self.nb_quiz = None
        self.nb_render()

    def nb_refresh(self):
        nb = self.nb
        if not nb:
            return
        try:
            if not nb["body"].winfo_exists():
                self.nb = None
                return
            fw = nb["body"].winfo_toplevel().focus_get()
        except Exception:
            fw = None
        if isinstance(fw, (tk.Entry, tk.Text)):
            nb["dirty"] = True
            return
        self.nb_render()

    def nb_render(self):
        nb = self.nb
        if not nb:
            return
        body = nb["body"]
        try:
            for ch in body.winfo_children():
                ch.destroy()
        except tk.TclError:
            return
        nb["dirty"] = False
        self.nb_draw_tabs()
        if self.nb_sid == "overview" or self.nb_sid not in dict((d[0], 1) for d in SUBJECT_DEFS):
            self.nb_sid = "overview"
            self.nb_overview(body)
        else:
            self.nb_subject_page(body, self.nb_sid)

    def nb_wrap(self, lab, margin=34):
        """Let a label's text wrap to the width of its card, whatever the window size."""
        par = lab.master
        cv = par
        while cv is not None and cv.winfo_class() != "Canvas":
            cv = cv.master

        def fit(e, l=lab):
            w = e.width
            try:
                if cv is not None and cv.winfo_width() > 50:    # never wider than the visible page (stops a wrap feedback loop)
                    w = min(w, cv.winfo_width() - max(0, par.winfo_rootx() - cv.winfo_rootx()) - 4)
                l.config(wraplength=max(160, w - margin))
            except tk.TclError:
                pass
        par.bind("<Configure>", fit, add="+")
        if cv is not None:
            cv.bind("<Configure>", lambda e: self.root.after_idle(lambda: fit(type("E", (), {"width": par.winfo_width()})) if par.winfo_exists() else None), add="+")
        return lab

    def nb_bar(self, parent, frac, col, w=260, h=10):
        bg = parent.cget("bg")
        cv = tk.Canvas(parent, width=w, height=h + 2, bg=bg, highlightthickness=0)
        rbox(cv, 1, 1, w - 1, h, 99, fill=_mixhex(bg, "#000000", 0.25), outline=LINE, shape="pill", step=2)
        if frac > 0:
            rbox(cv, 1, 1, max(h + 2, 1 + (w - 2) * min(1.0, frac)), h, 99, fill=col, outline="", shape="pill", step=2)
        return cv

    def nb_overview(self, body, stack=False):
        bg = T["card"]
        cols = tk.Frame(body, bg=PAPER)
        cols.pack(fill="x")
        cols.grid_columnconfigure(0, weight=1, uniform="o")
        if not stack:
            cols.grid_columnconfigure(1, weight=1, uniform="o")
        left = tk.Frame(cols, bg=PAPER)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 0 if stack else 6))
        right = tk.Frame(cols, bg=PAPER)
        if stack:
            right.grid(row=1, column=0, sticky="nsew", pady=(6, 0))
        else:
            right.grid(row=0, column=1, sticky="nsew", padx=(6, 0))
        # this week by subject, goals and exams
        c = self.hub_card(left, "This week, by subject")
        c.pack(fill="x")
        wk = self.subject_minutes(start=self.week_start())
        for d in self.subjects():
            sid = d[0]
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=16, pady=(2, 6))
            top = tk.Frame(r, bg=bg)
            top.pack(fill="x")
            tk.Label(top, text=d[1], bg=bg, fg=INK, font=(FONT_UI, 10, "bold"), anchor="w").pack(side="left")
            goal = float(self.life["goals"].get(sid, 0) or 0)
            m = wk.get(sid, 0)
            tk.Label(top, text="%s%s" % (fmt_hm(int(m)), (" / %s goal" % fmt_hm(int(goal * 60))) if goal else ""), bg=bg, fg=GREY,
                     font=(FONT_UI, 9)).pack(side="left", padx=8)
            gv = tk.StringVar(value=("%g" % goal) if goal else "")
            e = tk.Entry(top, textvariable=gv, width=4, font=(FONT_UI, 9), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                         highlightthickness=1, highlightbackground=LINE, highlightcolor=GOLD, justify="center")
            e.pack(side="right")
            tk.Label(top, text="weekly goal (h)", bg=bg, fg=GREY, font=(FONT_UI, 8)).pack(side="right", padx=4)

            def save_goal(_e=None, sid=sid, gv=gv):
                try:
                    v = float(gv.get().strip() or 0)
                except ValueError:
                    return
                self.life["goals"][sid] = max(0.0, min(80.0, v))
                self.life_save()
                self.root.after(50, self.nb_refresh)
            e.bind("<Return>", save_goal)
            e.bind("<FocusOut>", save_goal)
            self.nb_bar(r, (m / (goal * 60.0)) if goal else min(1.0, m / 600.0), d[3], w=300).pack(anchor="w", pady=(2, 0))
            ex = self.exam_for(sid, specific_only=True)
            if ex:
                got, need = self.exam_progress(ex)
                tk.Label(r, text="%s %s: %s of %s studied" % (clip(ex["title"], 28), when_text(ex["date"]), fmt_hm(int(got)), fmt_hm(int(need))),
                         bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w").pack(fill="x")
        gen = [d for d in self.upcoming_deadlines(6) if d.get("id") and classify_subject(d.get("title", ""))[0] is None
               and d.get("kind", "Deadline") in PLAN_KINDS]
        if gen:
            d = gen[0]
            got, need = self.exam_progress(d)
            self.nb_wrap(tk.Label(c, text="All subjects count toward “%s” (%s): %s of %s" % (clip(d["title"], 26), when_text(d["date"]), fmt_hm(int(got)),
                                                                               fmt_hm(int(need))),
                     bg=bg, fg=GOLD, font=(FONT_UI, 9, "bold"), anchor="w", wraplength=300, justify="left")).pack(fill="x", padx=16)
        self.nb_wrap(tk.Label(c, text="I count your time automatically from your windows (notes, PDFs, sites). Forgot to? Say “I studied bio for 2 hours”.",
                 bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w", wraplength=300, justify="left")).pack(fill="x", padx=16, pady=(4, 12))
        # unsorted time
        uns = [(k, u) for k, u in self.life["unsorted"].items() if u.get("secs", 0) >= 60]
        c2 = self.hub_card(left, "Time I wasn't sure about")
        c2.pack(fill="x", pady=(12, 0))
        if not uns:
            tk.Label(c2, text="Nothing to sort~ I knew what you were studying all day!", bg=bg, fg=GREY, font=(FONT_UI, 9),
                     anchor="w").pack(fill="x", padx=16, pady=(0, 12))
        for k, u in sorted(uns, key=lambda kv: -kv[1]["secs"])[:6]:
            r = tk.Frame(c2, bg=bg)
            r.pack(fill="x", padx=16, pady=(0, 8))
            tk.Label(r, text="“%s”  ·  %s" % (clip(u["title"], 46), fmt_hm(u["secs"] // 60)), bg=bg, fg=INK, font=(FONT_UI, 9),
                     anchor="w").pack(fill="x")
            ch = tk.Frame(r, bg=bg)
            ch.pack(fill="x", pady=(2, 0))
            for d in self.subjects():
                self.tt_btn(ch, d[2], lambda k=k, s=d[0]: self.study_sort(k, s), bg=d[3] if d[0] == u.get("guess") else FIELD,
                            size=8, padx=6, pady=0).pack(side="left", padx=(0, 4))
            self.tt_btn(ch, "Not study", lambda k=k: (self.study_sort(k, None), self.nb_refresh()), bg=FIELD, size=8, padx=6,
                        pady=0).pack(side="left")
        # recap
        c3 = self.hub_card(right, "Today so far")
        c3.pack(fill="x")
        self.nb_wrap(tk.Label(c3, text=self.recap_text(), bg=bg, fg=INK, font=(FONT_UI, 9), anchor="w", wraplength=300, justify="left")).pack(
            fill="x", padx=16, pady=(0, 12))
        # best focus times
        c4 = self.hub_card(right, "Your best focus times")
        c4.pack(fill="x", pady=(12, 0))
        cv = tk.Canvas(c4, height=74, bg=bg, highlightthickness=0)
        cv.pack(fill="x", padx=16)
        agg = {}
        for dd, hours in self.life["hourlog"].items():
            for hh, (s_, x_) in hours.items():
                a = agg.setdefault(int(hh), [0, 0])
                a[0] += s_
                a[1] += x_

        def draw(_e=None, agg=agg, cv=cv):
            cv.delete("all")
            W = max(200, cv.winfo_width())
            top = max([v[0] + v[1] for v in agg.values()] or [1])
            bw = (W - 4) / 24.0
            best = [h for h, _, _ in self.best_hours()[:2]]
            for h in range(24):
                s_, x_ = agg.get(h, [0, 0])
                x1 = 2 + h * bw
                hs = 50 * s_ / float(top)
                hx = 50 * x_ / float(top)
                cv.create_rectangle(x1 + 1, 56 - hs, x1 + bw - 1, 56, fill=GOLD if h in best else ORANGE, outline="")
                if hx >= 1:
                    cv.create_rectangle(x1 + 1, 56 - hs - hx, x1 + bw - 1, 56 - hs, fill=GREY, outline="")
                if h % 3 == 0:
                    cv.create_text(x1 + bw / 2, 66, text=str(h), fill=GREY, font=(FONT_UI, 7))
        cv.bind("<Configure>", draw)
        self.nb_wrap(tk.Label(c4, text=self.best_time_text() + "  (orange = study, grey = distracted)", bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w",
                 wraplength=300, justify="left")).pack(fill="x", padx=16, pady=(2, 12))
        # distraction report
        c5 = self.hub_card(right, "Distraction report")
        c5.pack(fill="x", pady=(12, 0))
        self.nb_wrap(tk.Label(c5, text=self.distraction_report(), bg=bg, fg=INK, font=(FONT_UI, 9), anchor="w", wraplength=300,
                              justify="left")).pack(fill="x", padx=16, pady=(0, 8))
        r = tk.Frame(c5, bg=bg)
        r.pack(fill="x", padx=16, pady=(0, 12))
        self.tt_btn(r, "Edit distracting sites...", self.edit_distractions, bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        # tracking settings
        c6 = self.hub_card(right, "How I track")
        c6.pack(fill="x", pady=(12, 0))
        for text, key in (("Count study time automatically from my windows", "auto_track"),
                          ("Ask me with one tap when I'm not sure of the subject", "ask_subject"),
                          ("Weak-subject alerts", "weak_alerts"), ("End-of-day recap (at %s)" % self.cfg.get("recap_time", "21:00"), "recap"),
                          ("Golden-hour nudges at my best focus time", "golden_hour"),
                          ("Pause the focus timer while I'm away from the keyboard", "idle_pause"),
                          ("Quick mistake flashcard during breaks", "break_cards")):
            v = tk.BooleanVar(value=bool(self.cfg.get(key, True)))
            tk.Checkbutton(c6, text=text, variable=v, command=lambda k=key, v=v: (self.cfg.__setitem__(k, bool(v.get())), save_config(self.cfg)),
                           bg=bg, fg=INK, activebackground=bg, activeforeground=GOLD, selectcolor=FIELD, highlightthickness=0,
                           font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=14)
        r = tk.Frame(c6, bg=bg)
        r.pack(fill="x", padx=16, pady=(4, 12))
        tk.Label(r, text="Not counted after", bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="left")
        iv = tk.StringVar(value=str(self.cfg.get("track_idle_minutes", 6)))
        ie = tk.Entry(r, textvariable=iv, width=3, font=(FONT_UI, 9), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                      highlightthickness=1, highlightbackground=LINE, highlightcolor=GOLD, justify="center")
        ie.pack(side="left", padx=4)
        tk.Label(r, text="min with no keyboard/mouse (reading time is kept until then)", bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="left")

        def save_idle(_e=None):
            try:
                self.cfg["track_idle_minutes"] = max(2, min(30, int(iv.get())))
                save_config(self.cfg)
            except ValueError:
                pass
        ie.bind("<Return>", save_idle)
        ie.bind("<FocusOut>", save_idle)

    def nb_subject_page(self, body, sid):
        bg = T["card"]
        d = [x for x in self.subjects() if x[0] == sid][0]
        col = d[3]
        # header
        head = self.hub_card(body)
        head.pack(fill="x")
        r = tk.Frame(head, bg=bg)
        r.pack(fill="x", padx=16, pady=(12, 4))
        inbook = getattr(self, "_book_ctx", False)
        if inbook:                                         # the book's own header already names it: just a quiet line
            tk.Label(r, text="家庭教師 · YOUR TUTOR", bg=bg, fg=_mixhex(GOLD, bg, 0.15), font=(_serif_font(self.root), 9)).pack(side="left")
        else:
            tk.Label(r, text="■", bg=bg, fg=col, font=(FONT_UI, 14)).pack(side="left")
            tk.Label(r, text=d[1], bg=bg, fg=GOLD, font=(FONT_UI, 16, "bold")).pack(side="left", padx=(6, 0))
            wk = self.subject_minutes(start=self.week_start()).get(sid, 0)
            today = self.subject_minutes(days=1).get(sid, 0)
            tk.Label(r, text="today %s · this week %s" % (fmt_hm(int(today)), fmt_hm(int(wk))), bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="right")
        ex = self.exam_for(sid)
        if ex:
            got, need = self.exam_progress(ex)
            rr = tk.Frame(head, bg=bg)
            rr.pack(fill="x", padx=16, pady=(0, 4))
            tk.Label(rr, text="%s · %s · %s of %s" % (clip(ex["title"], 30), when_text(ex["date"]), fmt_hm(int(got)), fmt_hm(int(need))),
                     bg=bg, fg=INK, font=(FONT_UI, 9), anchor="w").pack(side="left")
            self.nb_bar(rr, got / max(1.0, need), col, w=200).pack(side="right")
        hl_ = tk.Label(head, text="I answer as an IB %s tutor: the free smart brain (Ollama) when it's running, plus web search, "
                            "Wikipedia and my own IB notes. Everything stays free." % d[1],
                 bg=bg, fg=GREY, font=((_serif_font(self.root), 10, "italic") if inbook else (FONT_UI, 8)), anchor="w",
                 wraplength=420, justify="left")
        self.nb_wrap(hl_)
        hl_.pack(fill="x", padx=16, pady=(0, 12))
        # ask
        c = self.hub_card(body, "Ask your %s tutor" % d[2])
        c.pack(fill="x", pady=(12, 0))
        t = tk.Text(c, height=4, width=20, font=(FONT_UI, 10), bg=FIELD, fg=INK, insertbackground=INK, relief="flat", wrap="word",
                    highlightthickness=1, highlightbackground=LINE, highlightcolor=GOLD)
        t.pack(fill="x", padx=16, pady=(0, 6))
        draft = (self.nb or {}).get("draft", {}).get(sid, "")
        if draft:
            t.insert("1.0", draft)
        mode = tk.StringVar(value=(self.nb or {}).get("mode", "explain"))
        mr = tk.Frame(c, bg=bg)
        mr.pack(fill="x", padx=16)
        for key, lab in NB_MODES:
            tk.Radiobutton(mr, text=lab, value=key, variable=mode, indicatoron=False, bg=FIELD, fg=INK, selectcolor=col,
                           activebackground=FIELD, activeforeground=GOLD, relief="flat", bd=0, padx=10, pady=3,
                           font=(FONT_UI, 9, "bold"), command=lambda: self.nb.__setitem__("mode", mode.get())).pack(side="left", padx=(0, 6))
        status = tk.Label(c, text="", bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w")
        ans = tk.Text(c, height=14, width=20, font=(FONT_UI, 10), bg=_mixhex(bg, FIELD, 0.5), fg=INK, relief="flat", wrap="word",
                      highlightthickness=0, padx=10, pady=8)
        self.nb["ans"] = ans

        def show(txt):
            try:
                ans.config(state="normal")
                ans.delete("1.0", "end")
                md_insert(ans, txt)
                ans.config(state="disabled")
                status.config(text="")
            except tk.TclError:
                pass

        def ask(_e=None):
            q = t.get("1.0", "end").strip()
            if not q:
                status.config(text="Type a question first~")
                return
            self.nb.setdefault("draft", {})[sid] = q
            if mode.get() == "test":
                self.nb_start_test(sid, q)
                return
            status.config(text=self.nb_ask(sid, q, mode.get(), done=lambda txt: (show(txt), self.nb_hist_refresh(sid))))
        br = tk.Frame(c, bg=bg)
        br.pack(fill="x", padx=16, pady=(8, 4))
        self.tt_btn(br, "Ask", ask, bg=ORANGE, fg=ON_ACC, size=10, padx=16, pady=2).pack(side="left")
        self.tt_btn(br, "Clear", lambda: (t.delete("1.0", "end"), self.nb.setdefault("draft", {}).pop(sid, None)), bg=FIELD, size=9,
                    padx=10, pady=1).pack(side="left", padx=6)
        sv_row = tk.Frame(c, bg=bg)
        self.tt_btn(sv_row, "Save answer as flashcards", lambda: self.nb_cards_from_text(sid, ans.get("1.0", "end")), bg=FIELD, size=8,
                    padx=8, pady=1).pack(side="left")
        t.bind("<Control-Return>", ask)

        def ask_fn(q, m=None):
            t.delete("1.0", "end")
            t.insert("1.0", q)
            if m:
                mode.set(m)
                self.nb["mode"] = m
            ask()
        self.nb["ask_fn"] = ask_fn
        status.pack(fill="x", padx=16)
        ans.pack(fill="x", padx=16, pady=(4, 4))
        sv_row.pack(fill="x", padx=16, pady=(0, 14))
        H = self.life["nb_hist"].get(sid, [])
        show(H[-1]["a"] if H else "Ask anything about %s~ Try the topic chips below, or paste a past-paper question. "
             "Pick 'Like I'm 12' for a simple version, 'Exam answer' for a model answer with mark points, or 'Test me' for a quiz."
             % d[1])
        ans.config(state="disabled")
        # quiz
        self.nb_quiz_card(body, sid)
        if hasattr(self, "sources_card"):
            self.sources_card(body, sid)
        # topics + tools
        c3 = self.hub_card(body, "Topics")
        c3.pack(fill="x", pady=(12, 0))
        tf = tk.Frame(c3, bg=bg)
        tf.pack(fill="x", padx=16, pady=(0, 6))
        row = None
        for i, tp in enumerate(SUBJECT_TOPICS.get(sid, [])):
            if i % 3 == 0:
                row = tk.Frame(tf, bg=bg)
                row.pack(fill="x", pady=2)

            def pick(tp=tp):
                t.delete("1.0", "end")
                t.insert("1.0", ("Test me on " if mode.get() == "test" else "Explain ") + tp)
                ask()
            self.tt_btn(row, tp, pick, bg=FIELD, size=8, padx=8, pady=0).pack(side="left", padx=(0, 5))
        due = [x for x in self.cards_due() if x.get("subject") == sid]
        allc = [x for x in self.life["cards"] if x.get("subject") == sid]
        tr = tk.Frame(c3, bg=bg)
        tr.pack(fill="x", padx=16, pady=(6, 12))
        self.tt_btn(tr, "Flashcards from my notes file...", lambda: self.nb_cards_from_file(sid), bg=T["start"], size=9, padx=10,
                    pady=1).pack(side="left")
        self.tt_btn(tr, "Review my %s mistakes (%d due)" % (d[2], len(due)), lambda: self.nb_start_review(sid), bg=FIELD, size=9,
                    padx=10, pady=1, enabled=bool(due)).pack(side="left", padx=6)
        tk.Label(tr, text="%d %s card%s saved" % (len(allc), d[2], "" if len(allc) == 1 else "s"), bg=bg, fg=GREY,
                 font=(FONT_UI, 8)).pack(side="left", padx=6)
        # history
        c4 = self.hub_card(body, "Earlier pages")
        c4.pack(fill="x", pady=(12, 0))
        hf = tk.Frame(c4, bg=bg)
        hf.pack(fill="x", padx=16, pady=(0, 12))
        self.nb["hist"] = (hf, show)
        self.nb_hist_refresh(sid)

    def nb_hist_refresh(self, sid):
        nb = self.nb
        if not nb or "hist" not in nb:
            return
        hf, show = nb["hist"]
        try:
            for ch in hf.winfo_children():
                ch.destroy()
        except tk.TclError:
            return
        bg = hf.cget("bg")
        H = self.life["nb_hist"].get(sid, [])
        if not H:
            tk.Label(hf, text="Your questions and my answers are saved here, one page per subject~", bg=bg, fg=GREY,
                     font=(FONT_UI, 9), anchor="w").pack(fill="x")
        for h in reversed(H[-10:]):
            when = datetime.datetime.fromtimestamp(h.get("t", 0)).strftime("%d %b %H:%M")
            lab = tk.Label(hf, text="%s · %s" % (when, clip(h["q"].replace("\n", " "), 80)), bg=bg, fg=INK, font=(FONT_UI, 9),
                           anchor="w", cursor="hand2")
            lab.pack(fill="x", pady=1)
            lab.bind("<Button-1>", lambda e, a=h["a"]: show(a))
            lab.bind("<Enter>", lambda e, l=lab: l.config(fg=GOLD))
            lab.bind("<Leave>", lambda e, l=lab: l.config(fg=INK))

    # ---- test me (in the notebook) -----------------------------------------------------------------
    def nb_quiz_card(self, body, sid):
        bg = T["card"]
        Q = self.nb_quiz if (self.nb_quiz and self.nb_quiz.get("sid") == sid) else None
        if not Q:
            return
        c = self.hub_card(body, "Test: %s" % clip(Q["topic"], 50))
        c.pack(fill="x", pady=(12, 0))
        if Q.get("loading"):
            tk.Label(c, text="Writing your questions~ (a few seconds)", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(
                fill="x", padx=16, pady=(0, 12))
            return
        cards = Q["cards"]
        if Q["i"] >= len(cards):
            sc = Q["score"]
            tk.Label(c, text="Done! %g of %d. %s" % (sc, len(cards), "Sugoi~ perfect!" if sc >= len(cards) else
                                                      "The ones you missed are saved - I'll bring them back until you get them right~"),
                     bg=bg, fg=INK, font=(FONT_UI, 10, "bold"), anchor="w", wraplength=440, justify="left").pack(fill="x", padx=16)
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=16, pady=(8, 12))
            self.tt_btn(r, "New test on this", lambda: self.nb_start_test(sid, Q["topic"]), bg=ORANGE, fg=ON_ACC, size=9, padx=10,
                        pady=1).pack(side="left")
            self.tt_btn(r, "Close", lambda: (setattr(self, "nb_quiz", None), self.nb_render()), bg=FIELD, size=9, padx=10,
                        pady=1).pack(side="left", padx=6)
            return
        card = cards[Q["i"]]
        tk.Label(c, text="Q%d/%d%s  ·  score %g" % (Q["i"] + 1, len(cards), "  (a past mistake)" if card.get("mistake") else "", Q["score"]),
                 bg=bg, fg=GREY, font=(FONT_UI, 8), anchor="w").pack(fill="x", padx=16)
        tk.Label(c, text=card["q"], bg=bg, fg=INK, font=(FONT_UI, 11, "bold"), anchor="w", wraplength=440, justify="left").pack(
            fill="x", padx=16, pady=(2, 6))
        e = tk.Text(c, height=3 if card.get("long") else 1, font=(FONT_UI, 10), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                    wrap="word", highlightthickness=1, highlightbackground=LINE, highlightcolor=GOLD)
        e.pack(fill="x", padx=16)
        fb = tk.Label(c, text=Q.get("fb", ""), bg=bg, fg=GOLD, font=(FONT_UI, 9), anchor="w", wraplength=440, justify="left")

        def check(_e=None, skip=False):
            given = "" if skip else e.get("1.0", "end").strip()
            if not given and not skip:
                fb.config(text="Type your answer (or press Skip)~")
                return "break"
            if card.get("long"):
                f = marks_for(given, card["a"]) if given else 0.0
                ok = f >= 0.45
                part = 0.25 <= f < 0.45
            else:
                ok = bool(given) and answer_close(given, card["a"])
                part = False
            Q["score"] += 1 if ok else (0.5 if part else 0)
            Q["fb"] = ("Correct! Yatta~ " if ok else ("Partly there~ " if part else ("Skipped. " if skip else "Not quite~ "))) + \
                "Model answer: " + card["a"]
            self.nb_mistake(card, ok, sid)
            if ok:
                beep("happy")
            Q["i"] += 1
            self.nb_render()
            return "break"
        e.bind("<Return>", lambda ev: None if card.get("long") else check())
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=16, pady=(6, 4))
        self.tt_btn(r, "Check", check, bg=ORANGE, fg=ON_ACC, size=9, padx=12, pady=1).pack(side="left")
        self.tt_btn(r, "Hint", lambda: fb.config(text="Hint: starts with “%s”, about %d words~" % (
            card["a"][:max(2, len(card["a"]) // 8)], len(card["a"].split()))), bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=6)
        self.tt_btn(r, "Skip", lambda: check(skip=True), bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        self.tt_btn(r, "Stop", lambda: (setattr(self, "nb_quiz", None), self.nb_render()), bg=FIELD, size=9, padx=10, pady=1).pack(side="right")
        fb.pack(fill="x", padx=16, pady=(4, 12))
        self.root.after(80, lambda: (e.focus_set() if e.winfo_exists() else None))

    def nb_mistake(self, card, ok, sid):
        """Past-mistake memory: wrong answers go into your deck (tagged with the subject) and come back until you get them."""
        try:
            self.srs_update({"q": card["q"], "a": card["a"], "id": card.get("id")}, ok, from_deck=bool(card.get("id")))
        except Exception:
            return
        for c in self.life["cards"]:
            if c["q"] == card["q"] and c["a"] == card["a"]:
                c["subject"] = sid
                if card.get("long"):
                    c["long"] = True
        self.life_save()

    def nb_start_test(self, sid, topic):
        topic = re.sub(r"^(?:test me|quiz me)(?: on| about)?\s*", "", (topic or "").strip(), flags=re.I) or self.sname(sid, False)
        self.nb_quiz = {"sid": sid, "topic": topic, "cards": [], "i": 0, "score": 0, "loading": True}
        if self.nb_sid != sid:
            self.nb_sid = sid
        self.nb_render()
        model = self.cfg.get("llm_model") if self.cfg.get("llm_enabled", True) else None
        web = bool(self.cfg.get("web_enabled", True))
        Q = self.nb_quiz

        def job():
            return self.nb_make_test(sid, topic, model, web)

        def fin(res, err):
            if self.nb_quiz is not Q:
                return
            cards = res or []
            if not cards:
                self.nb_quiz = None
                self.nb_render()
                self.say("Uu~ I couldn't make questions on that. Try a topic name, like 'cell respiration'~", 6)
                return
            Q.update(cards=cards, loading=False)
            self.nb_render()
        self.bg(job, fin)

    def nb_make_test(self, sid, topic, model, web):
        """Up to 6 questions: your due past mistakes on this subject first, then fresh IB-style questions."""
        out = []
        for c in self.cards_due():
            if c.get("subject") == sid and len(out) < 2:
                out.append({"q": c["q"], "a": c["a"], "id": c["id"], "long": c.get("long", len(c["a"].split()) > 5), "mistake": True})
        names = brain_names() if model else None
        if names:
            try:
                m = pick_model(names, model)
                name = subject_name(sid, self.life, False)
                j = _ollama_json("/api/chat", {"model": m, "stream": False, "format": "json", "online": True,
                                               "options": {"temperature": 0.5, "num_predict": 1100},
                                               "messages": [{"role": "system", "content":
                                                             "You are an IB Diploma %s examiner. %s" % (name, SUBJECT_STYLE.get(sid, ""))},
                                                            {"role": "user", "content":
                                                             "Write 5 IB-style exam questions on '%s' for IB DP %s, mixing command terms "
                                                             "(define, state, outline, explain, calculate where it fits). Each needs a model "
                                                             "answer: an exact short answer, or 1-3 sentences with the key mark points. Reply as "
                                                             "JSON {\"cards\":[{\"q\":\"question\",\"a\":\"model answer\"}]}" % (topic, name)}]}, 180)
                got = json.loads(json_latex_fix((j.get("message") or {}).get("content", "{}"))).get("cards") or []
                for c in got:
                    if c.get("q") and c.get("a"):
                        a = str(c["a"]).strip()
                        out.append({"q": str(c["q"]).strip(), "a": a, "long": len(a.split()) > 5})
            except Exception:
                pass
        if len(out) < 4:
            out += ib_note_cards(sid, topic, 6 - len(out))
        if len(out) < 4 and web:
            try:
                title, text = wiki_long("%s %s" % (topic, SUBJECT_WIKI_HINT.get(sid, "")))
                out += make_flashcards(title or topic, text, 6 - len(out))
            except Exception:
                pass
        return out[:6]

    def nb_start_review(self, sid):
        due = [c for c in self.cards_due() if c.get("subject") == sid][:10]
        if not due:
            return
        self.nb_quiz = {"sid": sid, "topic": "your %s mistakes" % self.sname(sid), "i": 0, "score": 0, "loading": False,
                        "cards": [{"q": c["q"], "a": c["a"], "id": c["id"], "long": c.get("long", len(c["a"].split()) > 5),
                                   "mistake": True} for c in due]}
        self.nb_render()

    # ---- flashcards from your notes ----------------------------------------------------------------
    def nb_cards_from_file(self, sid=None):
        try:
            from tkinter import filedialog
            path = filedialog.askopenfilename(title="Pick your notes", filetypes=[
                ("Notes", "*.pdf *.docx *.pptx *.txt *.md *.rtf *.html"), ("All files", "*.*")])
        except Exception:
            path = ""
        if not path:
            return
        model = self.cfg.get("llm_model") if self.cfg.get("llm_enabled", True) else None

        def job():
            text, _ = read_any_file(path)
            s = sid or classify_subject(os.path.basename(path) + " " + text[:3000], self.life["subj_words"])[0]
            return s, self.cards_from_text(text, model, s), os.path.basename(path)

        def fin(res, err):
            if err or not res:
                self.fox_reply("Uu~ I couldn't read that file (%s)." % (err or "empty"))
                return
            s, cards, name = res
            self.nb_save_cards(s, cards, name)
        self.say("Reading your notes~ making flashcards...", 6)
        self.bg(job, fin)

    def nb_cards_from_text(self, sid, text):
        text = (text or "").strip()
        if len(text) < 60:
            self.say("Ask me something first, then I can turn the answer into cards~", 5)
            return
        cards = self.cards_from_text(text, None, sid)
        self.nb_save_cards(sid, cards, "this answer")

    def cards_from_text(self, text, model, sid):
        """Flashcards from notes: the smart brain if it's on, else definitions ('Term: meaning', 'X is Y') and fill-the-blanks."""
        cards = []
        names = brain_names() if model else None
        if names:
            try:
                m = pick_model(names, model)
                j = _ollama_json("/api/chat", {"model": m, "stream": False, "format": "json", "online": True,
                                               "options": {"temperature": 0.3, "num_predict": 1400},
                                               "messages": [{"role": "user", "content":
                                                             "Make up to 12 study flashcards from these %s notes for an IB DP student. "
                                                             "Test the key definitions, processes and facts. Reply as JSON "
                                                             "{\"cards\":[{\"q\":\"question\",\"a\":\"short answer\"}]}.\n\n%s"
                                                             % (subject_name(sid, self.life, False) if sid else "study", text[:7000])}]}, 240)
                got = json.loads(json_latex_fix((j.get("message") or {}).get("content", "{}"))).get("cards") or []
                cards = [{"q": str(c["q"]).strip(), "a": str(c["a"]).strip()} for c in got if c.get("q") and c.get("a")]
            except Exception:
                cards = []
        if len(cards) < 4:
            seen = set(c["q"] for c in cards)
            for line in re.split(r"[\n\r]+|(?<=[.!?])\s+", text):
                line = line.strip(" •-*\t")
                m = re.match(r"^([A-Za-zÀ-ÿ][\w\-' ()/]{1,50}?)\s*(?::|=| - | – | — )\s*(.{6,220})$", line) or \
                    re.match(r"^((?:The |An? )?[A-Za-zÀ-ÿ][\w\-' ]{2,40}?) (?:is|are|refers to|means) (?:the |an? )?(.{12,200}?)[.]?$", line)
                if m and len(m.group(1).split()) <= 6:
                    q = "What is %s?" % m.group(1).strip().rstrip(":").lower() if not m.group(1).strip().lower().startswith(("the ", "a ", "an ")) \
                        else "What is %s?" % m.group(1).strip().lower()
                    if q not in seen:
                        seen.add(q)
                        cards.append({"q": q, "a": m.group(2).strip().rstrip(".")})
                if len(cards) >= 14:
                    break
        if len(cards) < 6:
            cards += make_flashcards(subject_name(sid, self.life, False) if sid else "notes", text.replace("\n", " "), 8 - len(cards))
        return cards[:15]

    def nb_save_cards(self, sid, cards, name):
        if not cards:
            self.fox_reply("Hmm, I couldn't find card-shaped facts in %s. Notes like 'Osmosis: water moving...' work best~" % name)
            return
        today = datetime.date.today().isoformat()
        have = set((c["q"], c["a"]) for c in self.life["cards"])
        n = 0
        for c in cards:
            if (c["q"], c["a"]) in have:
                continue
            self.life["cards"].append({"id": "%x" % random.getrandbits(36), "q": c["q"][:240], "a": c["a"][:240], "box": 0, "wrong": 0,
                                       "right": 0, "added": today, "due": today, "subject": sid or "",
                                       "long": len(c["a"].split()) > 5, "from": name[:60]})
            n += 1
        self.life_save()
        self.daily_refresh()
        msg = "Kon! Made %d flashcard%s from %s%s~ Say 'review flashcards', or test yourself on the Notebook page." % (
            n, "" if n == 1 else "s", name, (" for %s" % self.sname(sid)) if sid else "")
        self.fox_reply(msg)
        self.nb_refresh()

    # ---- a mistake card during breaks ---------------------------------------------------------------
    def study_on_break(self):
        if self.cfg.get("break_cards", True):
            due = sorted(self.cards_due(), key=lambda c: -c.get("wrong", 0))
            if due:
                c = due[0]
                self.root.after(12000, lambda: self.break_card(c) if self.brk else None)

    def break_card(self, card):
        def reveal():
            self.say("Answer: %s\nDid you remember it?" % clip(card["a"], 120), 30,
                     [("I knew it!", lambda: (self.srs_update(card, True, True), self.say("Sugoi~ that one's sticking!", 4))),
                      ("Forgot", lambda: (self.srs_update(card, False, True), self.say("I'll bring it back tomorrow, ne~", 4)))])
        self.say("Quick one from your mistakes while you rest~\n%s" % clip(card["q"], 110), 40,
                 [("Show answer", reveal), ("Skip", lambda: None)])


