def fr_norm(s):
    s = unicodedata.normalize("NFD", (s or "").lower().strip())
    s = "".join(c for c in s if unicodedata.category(c) != "Mn").replace("œ", "oe")
    s = re.sub(r"^(le|la|les|l'|un|une|des|to)\s*", "", s)
    return re.sub(r"[^a-z' ]+", " ", s).strip()


def bio_norm(s):
    s = unicodedata.normalize("NFD", (s or "").lower())
    return re.sub(r"[^a-z0-9]", "", "".join(c for c in s if unicodedata.category(c) != "Mn"))


def fr_match(guess, answer):
    """(right?, accents perfect?) for a typed answer. Any of the '/' or ',' alternatives counts."""
    g = (guess or "").strip().lower()
    if not g:
        return False, False
    alts = [a.strip() for a in re.split(r"[/,]", re.sub(r"\(.*?\)", "", answer))] + [answer]
    for a in alts:
        if not a:
            continue
        if g == a.lower() or g == re.sub(r"^(le|la|les|l')\s*", "", a.lower()):
            return True, True
        if fr_norm(g) and fr_norm(g) == fr_norm(a):
            return True, False
    return False, False


# ---- Psychology (2027 guide): concepts, contexts, approaches, class practicals ----------------------------------------------
PSY_CONCEPTS = {
    "Bias": "Systematic distortion: in thinking (cognitive biases), in research (researcher, participant, sampling bias) or in theories.",
    "Causality": "Can we say X causes Y? Only experiments show cause and effect; correlations and observations can't.",
    "Change": "How behaviour, the brain and cultures change over time (development, neuroplasticity, acculturation, treatment).",
    "Measurement": "How psychologists measure things they can't see (memory, stress, attachment): operationalisation, validity, reliability.",
    "Perspective": "Biological, cognitive and sociocultural approaches see the same behaviour differently; so do cultures and individuals.",
    "Responsibility": "Ethics towards participants and society: consent, deception, debriefing, right to withdraw, how findings are used.",
}
PSY_CONTEXTS = ["Health and well-being", "Human development", "Human relationships", "Learning and cognition"]
PSY_APPROACHES = ["biological", "cognitive", "sociocultural"]
PSY_TOPICS = {
    "Health and well-being": ["stress", "depression", "addiction", "the effect of social support on health", "treatment of a disorder"],
    "Human development": ["attachment", "the development of empathy", "cognitive development in children", "identity in adolescence"],
    "Human relationships": ["conformity", "prejudice and discrimination", "romantic relationships", "prosocial behaviour", "group conflict"],
    "Learning and cognition": ["reconstructive memory", "decision-making", "the role of emotion in memory", "social learning", "neuroplasticity"],
}
PSY_PRACTICALS = [("Health and well-being", "Interview", "structured, semi-structured or focus group"),
                  ("Human development", "Observation", "naturalistic or controlled, overt or covert, participant or non-participant"),
                  ("Human relationships", "Survey/questionnaire", "closed and open questions, at least 10 participants"),
                  ("Learning and cognition", "Experiment", "true or quasi-experiment, at least 5 participants")]
PSY_TERMS = [
    ("Internal validity", "The study measures what it claims to, without confounding variables."),
    ("Ecological validity", "How well findings apply to real-life settings."),
    ("Reliability", "Getting consistent results when the study or measure is repeated."),
    ("Operationalisation", "Defining a variable so it can be measured (e.g. 'stress' = cortisol level)."),
    ("Demand characteristics", "Participants guess the aim and change their behaviour."),
    ("Researcher bias", "The researcher's expectations influence the results or their interpretation."),
    ("Random sampling", "Every member of the target population has an equal chance of being picked."),
    ("Opportunity sampling", "Using whoever is available at the time."),
    ("Self-selected sampling", "Participants volunteer, e.g. by answering an advert."),
    ("Independent samples", "Different participants in each condition."),
    ("Repeated measures", "The same participants take part in every condition."),
    ("Quasi-experiment", "The IV is a naturally occurring characteristic (like age or gender), so participants aren't randomly allocated."),
    ("Triangulation", "Using several methods, researchers or sources to check credibility in qualitative research."),
    ("Informed consent", "Participants agree after being told what the study involves."),
    ("Debriefing", "Explaining the true aim afterwards, especially after deception."),
    ("Transferability", "Whether qualitative findings apply to other settings or people."),
    ("Covert observation", "Participants don't know they are being observed."),
    ("Focus group", "A group interview of about 3-8 people discussing a topic."),
]


def psy_prompt(rng=random):
    c = rng.choice(list(PSY_CONCEPTS))
    ctx = rng.choice(PSY_CONTEXTS)
    top = rng.choice(PSY_TOPICS[ctx])
    ap = rng.choice(PSY_APPROACHES)
    forms = ["To what extent does %s affect what we can conclude about %s? (concept: %s)",
             "Discuss %s in research on %s from the %s approach.",
             "Evaluate one study of %s with reference to %s.",
             "How has the concept of %s shaped how psychologists study %s?"]
    i = rng.randrange(4)
    if i == 0:
        q = forms[0] % (c.lower(), top, c)
    elif i == 1:
        q = forms[1] % (c.lower(), top, ap)
    elif i == 2:
        q = forms[2] % (top, c.lower())
    else:
        q = forms[3] % (c.lower(), top)
    return {"concept": c, "context": ctx, "topic": top, "q": q, "hint": PSY_CONCEPTS[c]}


# ---- Chemistry + Maths: generated practice problems (question, answer, worked solution, guide topic) -----------------------
CHEM_M = [("H₂O", 18.02), ("CO₂", 44.01), ("NaCl", 58.44), ("CaCO₃", 100.09), ("NaOH", 40.00), ("H₂SO₄", 98.08),
          ("C₆H₁₂O₆", 180.18), ("NH₃", 17.04), ("MgO", 40.30), ("CuSO₄", 159.62), ("HCl", 36.46), ("CH₄", 16.05)]


def _sf(x, n=3):
    if x == 0:
        return "0"
    return ("%%.%dg" % n) % x


def chem_problem(rng=random):
    k = rng.randrange(8)
    if k == 0:
        f, M = rng.choice(CHEM_M)
        m = rng.choice([2.5, 5.0, 10.0, 12.6, 25.0, 4.4, 8.0, 36.0])
        n = m / M
        return {"q": "How many moles are in %s g of %s? (M = %s g mol⁻¹)" % (m, f, M), "a": n, "unit": "mol",
                "sol": "n = m / M = %s / %s = %s mol" % (m, M, _sf(n)), "topic": "Structure 1.4 The mole"}
    if k == 1:
        n = rng.choice([0.05, 0.1, 0.125, 0.2, 0.25, 0.5])
        v = rng.choice([100, 200, 250, 500, 1000])
        c = n / (v / 1000)
        return {"q": "%s mol of solute is dissolved to make %d cm³ of solution. Concentration in mol dm⁻³?" % (n, v), "a": c,
                "unit": "mol dm⁻³", "sol": "V = %d/1000 = %s dm³; c = n/V = %s / %s = %s mol dm⁻³" % (v, _sf(v / 1000), n, _sf(v / 1000), _sf(c)),
                "topic": "Structure 1.4 Concentration"}
    if k == 2:
        c1 = rng.choice([0.5, 1.0, 2.0])
        v1 = rng.choice([10, 20, 25, 50])
        v2 = rng.choice([100, 250, 500])
        c2 = c1 * v1 / v2
        return {"q": "%d cm³ of %s mol dm⁻³ HCl is diluted to %d cm³. New concentration?" % (v1, c1, v2), "a": c2, "unit": "mol dm⁻³",
                "sol": "c₁V₁ = c₂V₂ → c₂ = %s × %d / %d = %s mol dm⁻³" % (c1, v1, v2, _sf(c2)), "topic": "Structure 1.4 Dilution"}
    if k == 3:
        n = rng.choice([0.1, 0.25, 0.5, 1.0, 2.0])
        T = rng.choice([273, 298, 300, 350])
        p = rng.choice([100, 101.3, 150, 200])
        V = n * 8.31 * T / p
        return {"q": "Volume (dm³) of %s mol of ideal gas at %d K and %s kPa? (R = 8.31 J K⁻¹ mol⁻¹)" % (n, T, p), "a": V, "unit": "dm³",
                "sol": "pV = nRT → V = nRT/p = %s × 8.31 × %d / %s = %s dm³ (kPa with dm³ keeps the units matched)" % (n, T, p, _sf(V)),
                "topic": "Structure 1.5 Ideal gases"}
    if k == 4:
        e = rng.choice([1, 2, 3, 4, 5])
        a = rng.choice([1.0, 2.0, 5.0])
        h = a * 10 ** -e
        ph = -_m.log10(h)
        return {"q": "pH of a strong acid solution with [H⁺] = %s × 10⁻%d mol dm⁻³?" % (a, e), "a": ph, "unit": "",
                "sol": "pH = −log₁₀[H⁺] = −log₁₀(%s) = %s" % (_sf(h), _sf(ph)), "topic": "Reactivity 3.1 pH"}
    if k == 5:
        m = rng.choice([50, 100, 150, 200])
        dT = rng.choice([4.5, 6.0, 8.2, 10.0, 12.5])
        q = m * 4.18 * dT
        return {"q": "%d g of water warms by %s °C. Heat absorbed in J? (c = 4.18 J g⁻¹ K⁻¹)" % (m, dT), "a": q, "unit": "J",
                "sol": "Q = mcΔT = %d × 4.18 × %s = %s J" % (m, dT, _sf(q, 4)), "topic": "Reactivity 1.1 Measuring enthalpy changes"}
    if k == 6:
        th = rng.choice([5.0, 8.0, 10.0, 12.5, 20.0])
        act = round(th * rng.uniform(0.55, 0.95), 2)
        y = act / th * 100
        return {"q": "Theoretical yield %s g, actual yield %s g. Percentage yield?" % (th, act), "a": y, "unit": "%",
                "sol": "%% yield = actual / theoretical × 100 = %s / %s × 100 = %s%%" % (act, th, _sf(y)), "topic": "Reactivity 2.1 Yield"}
    f, M = rng.choice(CHEM_M)
    n = rng.choice([0.02, 0.05, 0.15, 0.3, 1.5])
    m = n * M
    return {"q": "Mass in g of %s mol of %s? (M = %s g mol⁻¹)" % (n, f, M), "a": m, "unit": "g",
            "sol": "m = nM = %s × %s = %s g" % (n, M, _sf(m)), "topic": "Structure 1.4 The mole"}


def math_problem(rng=random):
    k = rng.randrange(9)
    if k == 0:
        u1, d, n = rng.randint(-5, 12), rng.choice([2, 3, 4, 5, -2, -3]), rng.randint(8, 30)
        a = u1 + (n - 1) * d
        return {"q": "Arithmetic sequence: u₁ = %d, d = %d. Find u%s." % (u1, d, _subs(n)), "a": a,
                "sol": "uₙ = u₁ + (n−1)d = %d + %d×%d = %d" % (u1, n - 1, d, a), "topic": "1 Number and algebra: sequences", "p": 1}
    if k == 1:
        u1, d, n = rng.randint(1, 10), rng.randint(2, 6), rng.randint(10, 25)
        s = n * (2 * u1 + (n - 1) * d) / 2
        return {"q": "Find the sum of the first %d terms of %d, %d, %d, ..." % (n, u1, u1 + d, u1 + 2 * d), "a": s,
                "sol": "Sₙ = n/2 (2u₁ + (n−1)d) = %d/2 × (%d + %d) = %s" % (n, 2 * u1, (n - 1) * d, fmt_num(s)),
                "topic": "1 Number and algebra: series", "p": 1}
    if k == 2:
        u1, r = rng.choice([1, 2, 3, 5]), rng.choice([2, 3, 0.5])
        n = rng.randint(5, 9)
        s = u1 * (r ** n - 1) / (r - 1)
        return {"q": "Geometric series: u₁ = %s, r = %s. Find S%s." % (u1, r, _subs(n)), "a": s,
                "sol": "Sₙ = u₁(rⁿ − 1)/(r − 1) = %s(%s^%d − 1)/(%s − 1) = %s" % (u1, r, n, r, fmt_num(round(s, 4))),
                "topic": "1 Number and algebra: geometric series", "p": 2}
    if k == 3:
        a, n, b, x = rng.randint(2, 6), rng.randint(2, 4), rng.randint(-6, 6), rng.randint(-3, 3)
        v = a * n * x ** (n - 1) + b
        return {"q": "f(x) = %dx%s %s %dx. Find f′(%d)." % (a, _sup(n), "+" if b >= 0 else "−", abs(b), x), "a": v,
                "sol": "f′(x) = %dx%s %s %d, so f′(%d) = %d" % (a * n, _sup(n - 1) if n > 2 else "", "+" if b >= 0 else "−", abs(b), x, v),
                "topic": "5 Calculus: differentiation", "p": 1}
    if k == 4:
        a, b = rng.randint(1, 4), rng.randint(-5, 5)
        lo, hi = 0, rng.randint(1, 3)
        v = a * (hi ** 3 - lo ** 3) / 3 + b * (hi - lo)
        return {"q": "Evaluate ∫ from %d to %d of (%dx² %s %d) dx." % (lo, hi, a, "+" if b >= 0 else "−", abs(b)), "a": v,
                "sol": "= [%s x³ %s %dx] from %d to %d = %s" % (_frac(a, 3), "+" if b >= 0 else "−", abs(b), lo, hi, fmt_num(round(v, 4))),
                "topic": "5 Calculus: definite integrals", "p": 1}
    if k == 5:
        a, b, c = rng.choice([1, 2, 3, -1]), rng.randint(-8, 8), rng.randint(-6, 9)
        D = b * b - 4 * a * c
        n = 2 if D > 0 else (1 if D == 0 else 0)
        return {"q": "How many real roots does %s have? (answer 0, 1 or 2)" % _quad(a, b, c), "a": n,
                "sol": "Δ = b² − 4ac = %d − 4(%d)(%d) = %d → %s" % (b * b, a, c, D, ["no real roots", "one repeated root", "two real roots"][n]),
                "topic": "2 Functions: quadratics", "p": 1}
    if k == 6:
        b, kk = rng.choice([2, 3, 5, 10]), rng.randint(2, 4)
        x = b ** kk
        return {"q": "Solve log%s(x) = %d." % (_subs(b), kk), "a": x, "sol": "x = %d^%d = %d" % (b, kk, x),
                "topic": "1 Number and algebra: logarithms", "p": 1}
    if k == 7:
        n, r = rng.randint(5, 9), rng.randint(2, 4)
        a = rng.choice([1, 2, 3])
        v = _m.comb(n, r) * a ** (n - r)
        return {"q": "Find the coefficient of x%s in the expansion of (%s + x)%s." % (_sup(r), a, _sup(n)), "a": v,
                "sol": "ⁿCᵣ a^(n−r) = C(%d,%d) × %d^%d = %d × %d = %d" % (n, r, a, n - r, _m.comb(n, r), a ** (n - r), v),
                "topic": "1 Number and algebra: binomial theorem", "p": 1}
    a, b, C = rng.randint(4, 12), rng.randint(4, 12), rng.choice([30, 45, 60, 75, 110, 120])
    c = _m.sqrt(a * a + b * b - 2 * a * b * _m.cos(_m.radians(C)))
    return {"q": "Triangle: a = %d cm, b = %d cm, angle C = %d°. Find c (3 s.f.)." % (a, b, C), "a": c,
            "sol": "Cosine rule: c² = a² + b² − 2ab cos C = %d + %d − %d cos %d° → c = %s cm" % (a * a, b * b, 2 * a * b, C, _sf(c)),
            "topic": "3 Geometry and trigonometry: cosine rule", "p": 2}


def _subs(n):
    return str(n).translate(str.maketrans("0123456789-", "₀₁₂₃₄₅₆₇₈₉₋"))


def _sup(n):
    return str(n).translate(str.maketrans("0123456789-", "⁰¹²³⁴⁵⁶⁷⁸⁹⁻")) if n != 1 else ""


def _frac(a, b):
    g = _m.gcd(a, b)
    a, b = a // g, b // g
    return str(a) if b == 1 else "%d/%d" % (a, b)


def _quad(a, b, c):
    s = ("x²" if a == 1 else "−x²" if a == -1 else "%dx²" % a)
    if b:
        s += " %s %sx" % ("+" if b > 0 else "−", "" if abs(b) == 1 else abs(b))
    if c:
        s += " %s %d" % ("+" if c > 0 else "−", abs(c))
    return s + " = 0"


def num_answer(text):
    """A typed number: 3.5, -2, 1/3, 2.5e-3, 3 x 10^-4, 45%."""
    t = (text or "").strip().lower().replace("−", "-").replace(",", ".").replace("%", "").replace(" ", "")
    t = re.sub(r"(?:x|\*|×)10\^?(-?\d+)", r"e\1", t)
    m = re.match(r"^(-?\d+)/(\d+)$", t)
    if m:
        return int(m.group(1)) / int(m.group(2))
    try:
        return float(t)
    except ValueError:
        pass
    try:
        return float(calc_eval(t))
    except Exception:
        return None


def close_enough(got, want):
    if got is None:
        return False
    if want == 0:
        return abs(got) < 1e-6
    return abs(got - want) <= max(0.012 * abs(want), 0.006)


