# ---- shelf art (zenko10): pixel-painted textures for the bookshelf scene, made with the built-in PNG writer -----------
def _h01(x, y, s=0):
    """A cheap repeatable hash -> 0..1 (for stars, washi fibres, wood grain)."""
    n = (x * 374761393 + y * 668265263 + s * 2147483647) & 0xFFFFFFFF
    n = ((n ^ (n >> 13)) * 1274126177) & 0xFFFFFFFF
    return ((n ^ (n >> 16)) & 0xFFFF) / 65535.0


def _rgb_mix(a, b, t):
    t = max(0.0, min(1.0, t))
    return (int(a[0] + (b[0] - a[0]) * t), int(a[1] + (b[1] - a[1]) * t), int(a[2] + (b[2] - a[2]) * t))


def px_photo(w, h, fn, zoom=1):
    """A PhotoImage from fn(x, y) -> (r, g, b) or (r, g, b, a) or None (clear), zoomed by whole steps."""
    rows = []
    for y in range(h):
        row = []
        for x in range(w):
            c = fn(x, y)
            if c is None:
                row.append((0, 0, 0, 0))
            elif len(c) == 3:
                row.append((c[0], c[1], c[2], 255))
            else:
                row.append(c)
        rows.append(row)
    img = tk.PhotoImage(data=base64.b64encode(_png(rows, 1)))
    return img.zoom(zoom, zoom) if zoom > 1 else img


def shelf_sky(w, h):
    """The night behind the shelf: indigo sky, stars, the moon, misty mountains with a little torii, a wooden floor."""
    top, mid, low = (9, 12, 34), (27, 25, 72), (58, 34, 78)
    moon = (w * 0.86, h * 0.17, max(6.0, h * 0.075))
    floor = int(h * 0.86)

    def ridge(x, base, amp, s):
        return base + amp * (0.55 * _m.sin(x * 0.045 + s) + 0.3 * _m.sin(x * 0.11 + 2 * s) + 0.15 * _m.sin(x * 0.27 + s))
    tx = int(w * 0.16)

    def f(x, y):
        if y >= floor:
            plank = (y - floor) // 3
            g_ = 0.5 + 0.5 * _h01(x // 9 + plank * 7, plank, 3)
            c = _rgb_mix((44, 26, 20), (78, 48, 32), g_ * 0.6 + (0.25 if (y - floor) % 3 == 0 else 0))
            if (x + plank * 5) % 23 == 0:
                c = (34, 20, 16)
            return c
        t = y / float(floor)
        c = _rgb_mix(top, mid, t / 0.6) if t < 0.6 else _rgb_mix(mid, low, (t - 0.6) / 0.4)
        # moon + glow
        dx, dy = x - moon[0], y - moon[1]
        d = _m.sqrt(dx * dx + dy * dy)
        if d < moon[2]:
            cr = 0.10 if _h01(int(x / 2), int(y / 2), 5) > 0.82 else 0.0
            return _rgb_mix((255, 244, 214), (214, 200, 168), cr + 0.25 * (dx + dy) / (2 * moon[2]) + 0.1)
        if d < moon[2] * 4:
            c = _rgb_mix(c, (120, 110, 170), 0.35 * (1 - (d - moon[2]) / (moon[2] * 3)) ** 2)
        # stars (some twinkle in two sizes)
        if t < 0.62:
            r_ = _h01(x, y, 11)
            if r_ > 0.9965:
                return (255, 250, 220) if r_ > 0.999 else (170, 180, 230)
        # far and near mountains
        if y > ridge(x, h * 0.60, h * 0.06, 1.3):
            c = _rgb_mix(c, (40, 34, 86), 0.75)
        if y > ridge(x, h * 0.70, h * 0.05, 4.1):
            c = _rgb_mix(c, (26, 20, 52), 0.85)
            # a tiny red torii on the near ridge
            ry = ridge(tx, h * 0.70, h * 0.05, 4.1)
            if abs(x - tx) <= 5 and ry - 8 <= y <= ry:
                if y in (int(ry - 8), int(ry - 7)) or (y == int(ry - 5) and abs(x - tx) <= 4) or abs(x - tx) in (3, 4):
                    return (196, 44, 58)
        # a band of mist near the floor
        if t > 0.8:
            c = _rgb_mix(c, (92, 70, 120), (t - 0.8) / 0.2 * 0.5)
        return c
    return f


def book_art(col, cw, ch, hover=False):
    """A book cover in pixels: washi gradient with fibres, seigaiha waves, gold foil frame and corner guards, stab
    binding, a golden kitsune mask crest, and the page block showing on the side and bottom. Returns fn(x, y)."""
    base = _hex_rgb(col)
    dark = _rgb_mix(base, (0, 0, 0), 0.55)
    deep = _rgb_mix(base, (0, 0, 0), 0.30)
    light = _rgb_mix(base, (255, 255, 255), 0.22 if hover else 0.12)
    gold, gold_l, gold_d = (212, 175, 55), (255, 226, 130), (140, 104, 28)
    cream, line = (244, 234, 210), (214, 198, 160)
    PW = 3                                      # page block thickness
    cx1, cy1 = cw - PW, ch - PW                 # cover ends here
    sp = max(5, cw // 10)                       # spine strip
    mask = ["K.........K", "KK.......KK", "KwK.....KwK", "KwwKKKKKwwK", "KwwwwwwwwwK", "KwrwwwwwrwK",
            "KwKKwwwKKwK", ".KwwwwwwwK.", "..KwwrwwK..", "...KwwwK...", "....KKK...."]
    mx0, my0 = sp + int((cx1 * 0.60 - sp) / 2) - 5, int(ch * 0.15)
    holes = [int(cy1 * k) for k in (0.12, 0.37, 0.62, 0.87)]
    r_w = max(3.0, cw / 14.0)

    def f(x, y):
        # page block (seen on the right and bottom)
        if x >= cx1 or y >= cy1:
            if x < PW or y < PW or (x >= cx1 and y >= cy1 and (x - cx1) + (y - cy1) > PW):
                return None
            if x >= cx1 and y < cy1:
                return line if (y + x) % 3 == 0 else cream
            if y >= cy1 and x < cx1:
                return line if (x + y) % 3 == 0 else cream
            return line
        # cover outline
        if x == 0 or y == 0 or x == cx1 - 1 or y == cy1 - 1:
            return dark
        # spine strip with yotsume-toji stitching
        if x < sp:
            c = _rgb_mix(deep, dark, 0.35 + 0.25 * _h01(x, y // 3, 2))
            hx = sp // 2
            if any(abs(y - hy) <= 0 for hy in holes) and x <= hx:
                return (238, 226, 196)
            if x == hx and holes[0] <= y <= holes[-1]:
                return (238, 226, 196) if y % 2 == 0 else (200, 186, 150)
            if x == sp - 1:
                return _rgb_mix(dark, (0, 0, 0), 0.2)
            return c
        # washi gradient + fibres
        t = (x / float(cx1) * 0.45 + y / float(cy1) * 0.55)
        c = _rgb_mix(light, deep, t)
        fib = _h01(x // 3, y, 7)
        if fib > 0.93:
            c = _rgb_mix(c, (255, 255, 255), 0.10)
        elif fib < 0.05:
            c = _rgb_mix(c, (0, 0, 0), 0.08)
        # seigaiha waves on the lower part
        if y > cy1 * 0.60:
            row = int((cy1 - y) / (r_w * 0.8))
            ox = (r_w if row % 2 else 0)
            cxw = round((x - sp + ox) / (2 * r_w)) * 2 * r_w - ox + sp
            cyw = cy1 - row * r_w * 0.8
            d = _m.sqrt((x - cxw) ** 2 + (y - cyw) ** 2)
            if y <= cyw and any(abs(d - r_w * k) < 0.55 for k in (1.0, 0.62, 0.28)):
                c = _rgb_mix(c, (255, 240, 200), 0.22)
        # gold foil frame (double line) with a shimmer
        L, R, T_, B = sp + 2, cx1 - 3, 2, cy1 - 3
        on_outer = (x in (L, R) and T_ <= y <= B) or (y in (T_, B) and L <= x <= R)
        on_inner = (x in (L + 2, R - 2) and T_ + 2 <= y <= B - 2) or (y in (T_ + 2, B - 2) and L + 2 <= x <= R - 2)
        if on_outer:
            return gold_l if (x + y) % 7 == 0 else gold
        if on_inner:
            return gold_d
        # corner guards (kanagu) on the two outer corners
        for (ccx, ccy, sx, sy) in ((R, T_, -1, 1), (R, B, -1, -1)):
            ddx, ddy = (x - ccx) * sx, (y - ccy) * sy
            if 0 <= ddx and 0 <= ddy and ddx + ddy <= 5:
                return gold_l if ddx + ddy <= 1 else (gold if ddx + ddy < 5 else gold_d)
        # the kitsune mask crest
        mxr, myr = x - mx0, y - my0
        if 0 <= myr < len(mask) and 0 <= mxr < len(mask[0]):
            m_ = mask[myr][mxr]
            if m_ == "K":
                return gold_d
            if m_ == "w":
                return gold_l if (mxr + myr) % 5 == 0 else gold
            if m_ == "r":
                return (200, 30, 50)
        return c
    return f


def lantern_art(w, h):
    """A red paper chochin lantern (ribbed), black lacquer caps."""
    def f(x, y):
        cap = max(2, h // 9)
        if y < cap or y >= h - cap:
            if abs(x - w / 2.0) > w * 0.36:
                return None
            return (30, 22, 22) if (x + y) % 5 else (70, 58, 50)
        u = (x + 0.5 - w / 2.0) / (w / 2.0)
        v = (y + 0.5 - h / 2.0) / ((h - 2 * cap) / 2.0)
        bulge = 1.0 - 0.18 * v * v
        if abs(u) > bulge:
            return None
        rib = (y - cap) % 4 == 0
        lit = 1.0 - abs(u) * 0.55
        c = _rgb_mix((120, 16, 24), (238, 64, 52), lit)
        c = _rgb_mix(c, (255, 190, 120), 0.35 * max(0.0, 1 - abs(u) * 2) * (1 - abs(v)))
        if rib:
            c = _rgb_mix(c, (60, 10, 14), 0.45)
        if abs(u) > bulge - 0.12:
            c = _rgb_mix(c, (40, 6, 10), 0.4)
        return c
    return f


def glow_art(r, col=(255, 170, 80), strength=0.55):
    """A soft round glow with real transparency."""
    def f(x, y):
        d = _m.sqrt((x + 0.5 - r) ** 2 + (y + 0.5 - r) ** 2) / r
        if d >= 1:
            return None
        a = int(255 * strength * (1 - d) ** 2)
        return (col[0], col[1], col[2], a) if a > 2 else None
    return f


