def petal_soft(r, alpha=0.5):
    """A blurred sakura petal: a pink blob with a soft edge (it reads as out of focus, far behind the shelf)."""
    def f(x, y):
        dx, dy = (x + 0.5 - r) / r, (y + 0.5 - r) / (r * 0.75)
        d = _m.sqrt(dx * dx + dy * dy)
        if d >= 1:
            return None
        a = int(255 * alpha * (1 - d) ** 1.6)
        return (246, 178, 200, a) if a > 3 else None
    return f


def washi_art(w, h):
    """Warm washi paper for the hanging scroll: soft fibres and a faint darkening at the edges."""
    def f(x, y):
        c = (238, 226, 198)
        e = min(x, w - 1 - x, y, h - 1 - y)
        if e < 3:
            c = _rgb_mix(c, (200, 182, 146), (3 - e) / 4.0)
        r_ = _h01(x // 2, y, 21)
        if r_ > 0.92:
            c = _rgb_mix(c, (255, 250, 236), 0.6)
        elif r_ < 0.06:
            c = _rgb_mix(c, (196, 178, 140), 0.35)
        return c
    return f


def spaced(t, gap=" "):
    """L E T T E R - S P A C E D small-caps-ish headings."""
    return gap.join(t)


_FONTS = {}


def _pick_font(root, key, names, fallback):
    if key not in _FONTS:
        _FONTS[key] = fallback
        try:
            import tkinter.font as tkfont
            have = {f.lower(): f for f in tkfont.families(root)}
            for n in names:
                if n.lower() in have:
                    _FONTS[key] = have[n.lower()]
                    break
        except Exception:
            pass
    return _FONTS[key]


def _serif_font(root):
    """An elegant serif for headings (Windows has Georgia / Cambria / Palatino)."""
    return _pick_font(root, "serif", ("Georgia", "Cambria", "Palatino Linotype", "Book Antiqua", "Garamond", "Constantia",
                                      "Liberation Serif", "DejaVu Serif", "FreeSerif"), FONT_UI)


def _mincho_font(root):
    """A brush-like Japanese serif (Mincho) for kanji; falls back to the Japanese gothic font."""
    return _pick_font(root, "mincho", ("Yu Mincho", "游明朝", "MS PMincho", "MS Mincho", "Noto Serif JP", "Noto Serif CJK JP",
                                       "IPAMincho", "IPAPMincho"), _jp_font(root) or FONT_UI)


