VISION_FAMILIES = ["qwen2.5vl", "qwen3-vl", "qwen2.5-vl", "gemma3", "gemma4", "llama3.2-vision", "minicpm-v", "granite3.2-vision",
                   "mistral-small3.1", "mistral-small3.2", "llava", "llava-llama3", "llava-phi3", "bakllava", "moondream"]
VISION_PULL = "qwen2.5vl:3b"


def pick_vision(names, wanted=""):
    """The vision model to use: the one in Settings if installed, else any installed model that can see images."""
    if not names:
        return None
    if wanted and wanted in names:
        return wanted
    base = (wanted or "").split(":")[0]
    hit = [n for n in names if base and n.split(":")[0] == base]
    if hit:
        return hit[0]
    for fam in VISION_FAMILIES:
        for n in names:
            b, _, tag = n.partition(":")
            if b == fam and "cloud" not in n and not (fam in ("gemma3", "gemma4") and tag.startswith(("1b", "270m"))):
                return n
    return None


def rgb_png(w, h, rgb, level=3):
    """Raw RGB bytes (top row first) -> PNG bytes."""
    import zlib
    import struct
    stride = w * 3
    raw = b"".join(b"\x00" + bytes(rgb[y * stride:(y + 1) * stride]) for y in range(h))

    def chunk(t, d):
        c = struct.pack(">I", len(d)) + t + d
        return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
    return b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)) + \
        chunk(b"IDAT", zlib.compress(raw, level)) + chunk(b"IEND", b"")


def dib_to_png(data):
    """A Windows clipboard DIB (BITMAPINFOHEADER + pixels, 24 or 32 bit) -> PNG bytes."""
    import struct
    hs, w, h, planes, bpp, comp = struct.unpack_from("<IiiHHI", data, 0)
    clr = struct.unpack_from("<I", data, 32)[0]
    if bpp not in (24, 32):
        raise ValueError("unsupported %d-bit picture" % bpp)
    off = hs + (12 if comp == 3 and hs == 40 else 0) + clr * 4
    top_down = h < 0
    h = abs(h)
    stride = ((w * bpp + 31) // 32) * 4
    px = memoryview(data)[off:off + stride * h]
    out = bytearray(w * h * 3)
    step = bpp // 8
    for row in range(h):
        src = px[(row if top_down else h - 1 - row) * stride:][:w * step]
        dst = row * w * 3
        out[dst + 0:dst + w * 3:3] = src[2::step]
        out[dst + 1:dst + w * 3:3] = src[1::step]
        out[dst + 2:dst + w * 3:3] = src[0::step]
    return rgb_png(w, h, out)


def clipboard_image():
    """(image bytes, name) from the clipboard: a copied screenshot (Win+Shift+S, PrtScn) or a copied image file. Windows only."""
    if not IS_WIN:
        return None
    import ctypes.wintypes as wt
    u, k = ctypes.windll.user32, ctypes.windll.kernel32
    u.GetClipboardData.restype = ctypes.c_void_p
    k.GlobalLock.restype = ctypes.c_void_p
    k.GlobalLock.argtypes = [ctypes.c_void_p]
    k.GlobalUnlock.argtypes = [ctypes.c_void_p]
    k.GlobalSize.restype = ctypes.c_size_t
    k.GlobalSize.argtypes = [ctypes.c_void_p]
    CF_DIB, CF_HDROP = 8, 15
    if not (u.IsClipboardFormatAvailable(CF_DIB) or u.IsClipboardFormatAvailable(CF_HDROP)):
        return None
    if not u.OpenClipboard(None):
        return None
    try:
        if u.IsClipboardFormatAvailable(CF_HDROP):
            sh = ctypes.windll.shell32
            sh.DragQueryFileW.argtypes = [ctypes.c_void_p, wt.UINT, ctypes.c_wchar_p, wt.UINT]
            hd = u.GetClipboardData(CF_HDROP)
            n = sh.DragQueryFileW(hd, 0xFFFFFFFF, None, 0)
            for i in range(n):
                buf = ctypes.create_unicode_buffer(520)
                sh.DragQueryFileW(hd, i, buf, 520)
                p = buf.value
                if p.lower().endswith((".png", ".jpg", ".jpeg")):
                    with open(p, "rb") as f:
                        return f.read(), os.path.basename(p)
        if u.IsClipboardFormatAvailable(CF_DIB):
            hm = u.GetClipboardData(CF_DIB)
            p = k.GlobalLock(hm)
            if p:
                try:
                    data = ctypes.string_at(p, k.GlobalSize(hm))
                finally:
                    k.GlobalUnlock(hm)
                return dib_to_png(data), "screenshot.png"
    finally:
        u.CloseClipboard()
    return None


def image_dims(data):
    """(w, h) of a PNG or JPEG, or None."""
    import struct
    try:
        if data[:8] == b"\x89PNG\r\n\x1a\n":
            return struct.unpack(">II", data[16:24])
        if data[:2] == b"\xff\xd8":
            i = 2
            while i < len(data):
                if data[i] != 0xFF:
                    i += 1
                    continue
                mk = data[i + 1]
                ln = struct.unpack(">H", data[i + 2:i + 4])[0]
                if mk in (0xC0, 0xC1, 0xC2):
                    h, w = struct.unpack(">HH", data[i + 5:i + 9])
                    return w, h
                i += 2 + ln
    except Exception:
        pass
    return None


