ONLINE_SIGNUP = {
    "gemini": "https://aistudio.google.com/apikey",
    "groq": "https://console.groq.com/keys",
    "openrouter": "https://openrouter.ai/keys",
}
GEMINI_MODELS = ["gemini-2.5-flash", "gemini-flash-latest", "gemini-2.0-flash"]
OPENAI_LIKE = {
    "groq": ("https://api.groq.com/openai/v1/chat/completions", "llama-3.3-70b-versatile",
             "meta-llama/llama-4-scout-17b-16e-instruct"),
    "openrouter": ("https://openrouter.ai/api/v1/chat/completions", "meta-llama/llama-3.3-70b-instruct:free",
                   "google/gemma-3-27b-it:free"),
}
_NET = urllib.request.build_opener()               # online brain: normal internet (school/home proxy settings respected)


def ib_msgs(messages):
    """Every brain answers in IB DP terminology: add the rule to the system message (once)."""
    msgs = [dict(m) for m in (messages or [])]
    if any("Terminology rule:" in (m.get("content") or "") for m in msgs):
        return msgs
    if msgs and msgs[0].get("role") == "system":
        msgs[0]["content"] = (msgs[0].get("content") or "") + "\n\n" + IB_RULE
    else:
        msgs.insert(0, {"role": "system", "content": IB_RULE})
    return msgs


def online_ready():
    """True when the online brain is switched on, has a key, and isn't cooling down after a rate limit."""
    return bool(ONLINE.get("on") and (ONLINE.get("keys") or {}).get(ONLINE.get("provider"), "").strip()
                and time.time() >= ONLINE.get("cool", 0))


def online_set(cfg):
    ONLINE["on"] = bool(cfg.get("online_on", False))
    ONLINE["provider"] = cfg.get("online_provider", "gemini") if cfg.get("online_provider") in dict(ONLINE_PROVIDERS) else "gemini"
    ONLINE["keys"] = dict(cfg.get("online_keys") or {})
    ONLINE["model"] = (cfg.get("online_model") or "").strip()


def online_name():
    p = ONLINE.get("provider", "gemini")
    if p == "gemini":
        return ONLINE.get("model") or ONLINE.get("gem_model") or "Gemini"
    return ONLINE.get("model") or OPENAI_LIKE[p][1].split("/")[-1]


def _img_mime(b64s):
    return "image/jpeg" if b64s[:4] == "/9j/" else "image/png"


def _post_json(url, body, headers, timeout):
    req = urllib.request.Request(url, data=json.dumps(body).encode("utf-8"), method="POST",
                                 headers=dict({"content-type": "application/json", "user-agent": "Zenko"}, **headers))
    try:
        with _NET.open(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        try:
            detail = json.loads(e.read().decode("utf-8", "replace"))
            detail = (detail.get("error") or {}).get("message") or str(detail)
        except Exception:
            detail = ""
        if e.code == 429:
            ONLINE["cool"] = time.time() + 90                 # free limit hit: use the PC's own models for a bit
            raise RMError("RATE")
        if e.code in (401, 403):
            raise RMError("KEY: " + clip(detail or "the key was refused", 120))
        raise RMError("HTTP %d %s" % (e.code, clip(detail, 160)))


def online_chat(messages, json_mode=False, search=False, timeout=90, max_tokens=1500, temperature=0.3):
    """One answer from the online brain. messages use Ollama's shape (role/content/images as base64).
    Returns (text, [(title, url)] web sources). Raises on any failure, so callers can fall back to Ollama."""
    if not online_ready():
        raise RMError("OFFLINE")
    prov = ONLINE["provider"]
    key = ONLINE["keys"][prov].strip()
    messages = ib_msgs(messages)
    if prov == "gemini":
        system = "\n\n".join(m["content"] for m in messages if m.get("role") == "system")
        contents = []
        for m in messages:
            if m.get("role") == "system":
                continue
            parts = [{"text": m.get("content") or " "}]
            for im in m.get("images") or []:
                parts.append({"inline_data": {"mime_type": _img_mime(im), "data": im}})
            role = "model" if m.get("role") == "assistant" else "user"
            if contents and contents[-1]["role"] == role:
                contents[-1]["parts"] += parts
            else:
                contents.append({"role": role, "parts": parts})
        gen = {"temperature": temperature, "maxOutputTokens": max(1024, max_tokens)}
        if json_mode and not search:
            gen["responseMimeType"] = "application/json"
        body = {"contents": contents, "generationConfig": gen}
        if system:
            body["system_instruction"] = {"parts": [{"text": system}]}
        if search:
            body["tools"] = [{"google_search": {}}]
        models = [ONLINE["model"]] if ONLINE.get("model") else \
            ([ONLINE["gem_model"]] if ONLINE.get("gem_model") else []) + [m for m in GEMINI_MODELS if m != ONLINE.get("gem_model")]
        last = None
        for mdl in models:
            url = "https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent" % mdl
            try:
                j = _post_json(url, body, {"x-goog-api-key": key}, timeout)
            except RMError as e:
                last = e
                if str(e).startswith("HTTP 404") or (str(e).startswith("HTTP 400") and "tools" in body):
                    if str(e).startswith("HTTP 400"):               # this model/plan can't search: answer without it
                        body.pop("tools", None)
                        try:
                            j = _post_json(url, body, {"x-goog-api-key": key}, timeout)
                        except RMError as e2:
                            last = e2
                            continue
                    else:
                        continue
                else:
                    raise
            cand = (j.get("candidates") or [{}])[0]
            txt = "".join(p.get("text", "") for p in ((cand.get("content") or {}).get("parts") or []) if not p.get("thought"))
            srcs = []
            for ch in ((cand.get("groundingMetadata") or {}).get("groundingChunks") or []):
                w = ch.get("web") or {}
                if w.get("uri"):
                    srcs.append((w.get("title") or "web", w["uri"]))
            if txt.strip():
                ONLINE["gem_model"] = mdl
                return _strip_think(txt), srcs[:4]
            last = RMError("EMPTY")
        raise last or RMError("EMPTY")
    url, text_model, vis_model = OPENAI_LIKE[prov]
    has_img = any(m.get("images") for m in messages)
    out = []
    for m in messages:
        if m.get("images"):
            parts = [{"type": "text", "text": m.get("content") or ""}] + [
                {"type": "image_url", "image_url": {"url": "data:%s;base64,%s" % (_img_mime(im), im)}} for im in m["images"]]
            out.append({"role": m["role"], "content": parts})
        else:
            out.append({"role": m["role"], "content": m.get("content") or ""})
    body = {"model": ONLINE.get("model") or (vis_model if has_img else text_model), "messages": out,
            "temperature": temperature, "max_tokens": max_tokens}
    if json_mode:
        body["response_format"] = {"type": "json_object"}
    j = _post_json(url, body, {"authorization": "Bearer " + key}, timeout)
    txt = (((j.get("choices") or [{}])[0].get("message") or {}).get("content") or "")
    if not txt.strip():
        raise RMError("EMPTY")
    return _strip_think(txt), []


def online_test():
    """A tiny request to check the key works. Returns (ok, message)."""
    try:
        t, _ = online_chat([{"role": "user", "content": "Reply with just: kon kon"}], timeout=30, max_tokens=50)
        return True, "Connected to %s~ (%s)" % (online_name(), clip(t.strip(), 40))
    except Exception as e:
        e = str(e)
        if e == "RATE":
            return False, "The free limit is used up for now. Try again in a minute."
        if e.startswith("KEY"):
            return False, "That key didn't work. Copy it again from the sign-up page (it's one long line)."
        return False, "Couldn't reach it (%s). Your school network might block it; I'll use your PC's models instead." % clip(e, 80)


