_GREEK = set()
for _g, _c in zip("alpha beta gamma delta epsilon varepsilon zeta eta theta vartheta iota kappa lambda mu nu xi pi rho sigma "
                  "tau upsilon phi varphi chi psi omega Gamma Delta Theta Lambda Xi Pi Sigma Phi Psi Omega".split(),
                  "αβγδεεζηθϑικλμνξπρστυφφχψωΓΔΘΛΞΠΣΦΨΩ"):
    _TEX[_g] = _c
    _GREEK.add(_g)


def _brace(s, i):
    """The {...} group starting at s[i] (or one character). Returns (content, next index)."""
    while i < len(s) and s[i] == " ":
        i += 1
    if i >= len(s):
        return "", i
    if s[i] != "{":
        if s[i] == "\\":
            m = re.match(r"\\[A-Za-z]+", s[i:])
            if m:
                return m.group(0), i + len(m.group(0))
        return s[i], i + 1
    depth, j = 0, i
    while j < len(s):
        if s[j] == "{":
            depth += 1
        elif s[j] == "}":
            depth -= 1
            if depth == 0:
                return s[i + 1:j], j + 1
        j += 1
    return s[i + 1:], len(s)


def tex_segments(s, tags=()):
    """Simple LaTeX -> readable text: fractions, roots, Greek, arrows, sub/superscripts (as raised/lowered text),
    \\ce{} chemistry. Returns [(text, tags)]."""
    out = []

    def matrix(m):
        env, body = m.group(1), m.group(2)
        rows = [r.strip() for r in re.split(r"\\\\(?:\[[^\]]*\])?", body) if r.strip()]
        rows = [", ".join(c.strip() for c in r.split("&")) for r in rows]
        if env == "cases":
            return "{ " + ";  ".join(rows) + " }"
        L, R = {"pmatrix": ("(", ")"), "bmatrix": ("[", "]"), "Bmatrix": ("{", "}"), "vmatrix": ("|", "|"),
                "Vmatrix": ("‖", "‖")}.get(env, ("(", ")"))
        return L + "; ".join(rows) + R
    s = re.sub(r"\\begin\{([pbBvV]?matrix|smallmatrix|cases)\}(.*?)\\end\{\1\}", matrix, s, flags=re.S)

    def add(t, extra=()):
        if t:
            out.append((t, tuple(tags) + tuple(extra)))
    i, buf = 0, ""
    while i < len(s):
        ch = s[i]
        if ch == "\\":
            m = re.match(r"\\(mathbb\{[A-Z]\}|[A-Za-z]+|.)", s[i:])
            name = m.group(1)
            i += len(m.group(0))
            if name in ("begin", "end"):                 # environments (aligned, cases, pmatrix...): keep the content
                env, i = _brace(s, i)
                if name == "begin" and env in ("array", "tabular") and i < len(s) and s[i] == "{":
                    _, i = _brace(s, i)
                if name == "end":
                    buf += "\n"
            elif name in ("binom", "dbinom", "tbinom", "choose"):
                a, i = _brace(s, i)
                b, i = _brace(s, i)
                add(buf)
                buf = ""
                add("(")
                out.extend(tex_segments(a, tags))
                add(" C ")
                out.extend(tex_segments(b, tags))
                add(")")
            elif name in ("color", "textcolor", "phantom", "hphantom", "vphantom", "label", "tag"):
                _, i = _brace(s, i)
                if name in ("color", "textcolor"):
                    a, i = _brace(s, i)
                    out_ = tex_segments(a, tags)
                    add(buf)
                    buf = ""
                    out.extend(out_)
            elif name in ("boxed", "fbox", "underline", "mathcal", "mathscr", "mathfrak", "mathsf", "mathtt", "textit",
                          "emph", "textsf", "texttt", "text", "mathrm", "textrm", "mathbf", "textbf", "mathit",
                          "operatorname", "mbox", "boldsymbol", "bm", "hbox", "textnormal", "mathop", "ensuremath"):
                a, i = _brace(s, i)
                add(buf)
                buf = ""
                if name in ("text", "textrm", "mbox", "hbox", "textnormal", "textit", "emph", "textsf", "texttt"):
                    add(a)
                else:
                    out.extend(tex_segments(a, tags))
            elif name in ("dot", "ddot", "tilde", "widetilde", "widehat", "overrightarrow", "overleftarrow", "underbrace",
                          "overbrace", "check", "breve", "acute", "grave"):
                a, i = _brace(s, i)
                mark = {"dot": "\u0307", "ddot": "\u0308", "tilde": "\u0303", "widetilde": "\u0303", "widehat": "\u0302",
                        "overrightarrow": "\u20d7", "overleftarrow": "\u20d6", "check": "\u030c", "breve": "\u0306",
                        "acute": "\u0301", "grave": "\u0300"}.get(name, "")
                buf += a + mark
            elif name in ("hline", "cline", "nonumber", "notag", "noindent", "centering", "small", "large", "Large",
                          "normalsize", "scriptstyle", "textstyle", "nolimits", "middle", "bigl", "bigr", "Bigl", "Bigr",
                          "biggl", "biggr", "Biggl", "Biggr", "Big", "bigg", "Bigg"):
                pass
            elif name in ("frac", "dfrac", "tfrac", "cfrac"):
                a, i = _brace(s, i)
                b, i = _brace(s, i)
                add(buf)
                buf = ""
                simple = lambda x: re.fullmatch(r"[\w.]+", x or "") is not None
                out.extend(tex_segments(a if simple(a) else "(" + a + ")", tags))
                add("/")
                out.extend(tex_segments(b if simple(b) else "(" + b + ")", tags))
            elif name == "sqrt":
                n = ""
                if i < len(s) and s[i] == "[":
                    k = s.find("]", i)
                    n, i = s[i + 1:k], k + 1
                a, i = _brace(s, i)
                add(buf)
                buf = ""
                if n:
                    add(n.translate(_SUP))
                add("√(")
                out.extend(tex_segments(a, tags))
                add(")")
            elif name in ("ce", "pu"):
                a, i = _brace(s, i)
                add(buf)
                buf = ""
                out.extend(chem_segments(a, tags))
            elif name in ("left", "right", "big", "displaystyle", "limits", ","):
                buf += " " if name == "," else ""
                if name in ("left", "right") and i < len(s) and s[i] == ".":
                    i += 1
            elif name in ("overline", "bar", "vec", "hat"):
                a, i = _brace(s, i)
                buf += a + {"overline": "\u0305", "bar": "\u0304", "vec": "\u20d7", "hat": "\u0302"}[name]
            elif name in (";", ":", "!", " "):
                buf += " "
            elif name in ("{", "}", "$", "_", "#", "&"):
                buf += name
            elif name == "\\":
                buf += "\n"
            else:
                buf += _TEX.get(name, name)
                if name in _GREEK and re.match(r" +[A-Za-z0-9](?![A-Za-z])", s[i:]):    # \Delta H -> ΔH
                    while i < len(s) and s[i] == " ":
                        i += 1
        elif ch in "^_":
            a, i = _brace(s, i + 1)
            add(buf)
            buf = ""
            sub = ch == "_"
            if a in ("\\circ", "\\degree", "o") and not sub and (a != "o" or not buf[-1:].isalpha()):
                add("°")
                continue
            inner = tex_segments(a, ())
            for t, tg in inner:
                add(t, tg + ("md_sub" if sub else "md_sup",))
        elif ch in "{}":
            i += 1
        elif ch == "~":
            buf += " "
            i += 1
        elif ch == "&":
            buf += " "
            i += 1
        else:
            buf += ch
            i += 1
    add(buf)
    return out


def chem_segments(s, tags=()):
    """H2SO4 / Fe^{3+} / CO3^2- -> lowered and raised text, arrows for -> and <=>."""
    s = s.replace("<=>", "⇌").replace("<->", "⇌").replace("->", "→").replace("<-", "←")
    out = []
    for m in re.finditer(r"(\^\{?[0-9]*[+-]\}?|\^[0-9]+)|((?<=[A-Za-z)\]])[0-9]+)|([^\^0-9]+|[0-9]+)", s):
        if m.group(1):
            out.append((m.group(1).strip("^{}"), tuple(tags) + ("md_sup",)))
        elif m.group(2):
            out.append((m.group(2), tuple(tags) + ("md_sub",)))
        else:
            out.append((m.group(3), tuple(tags)))
    return out


_INLINE = re.compile(
    r"(?P<code>`+)(?P<codet>.+?)(?P=code)"
    r"|\$\$(?P<dm>.+?)\$\$|\\\[(?P<bm>.+?)\\\]|\\\((?P<pm>.+?)\\\)|(?<![\w$\\])\$(?=\S)(?P<m>[^$\n]*?\S)\$(?!\d)"
    r"|\*\*\*(?P<bi>.+?)\*\*\*|___(?P<bi2>.+?)___"
    r"|\*\*(?P<b>.+?)\*\*|(?<!\w)__(?P<b2>.+?)__(?!\w)"
    r"|(?<![\w*])\*(?P<i>[^\s*](?:.*?[^\s*])?)\*(?![\w*])|(?<![\w_])_(?P<i2>[^\s_](?:.*?[^\s_])?)_(?![\w_])"
    r"|~~(?P<s>.+?)~~"
    r"|\\ce\{(?P<ce>[^}]*(?:\{[^}]*\}[^}]*)*)\}"
    r"|(?<=[\w)\]])\^(?:\{(?P<sp>[^}]*)\}|(?P<sp2>[0-9]+[+-]?|[+-]|[a-z]\b))"
    r"|(?<=[A-Za-z)\]])_\{(?P<sb>[^}]*)\}"
    r"|\[(?P<lt>[^\]]+)\]\((?P<lu>https?://[^)\s]+)\)"
    r"|<sup>(?P<sup>.*?)</sup>|<sub>(?P<sub>.*?)</sub>|<b>(?P<hb>.*?)</b>|<i>(?P<hi>.*?)</i>|<br\s*/?>(?P<br>)",
    re.S)


def md_inline(text, tags=()):
    out = []
    pos = 0
    for m in _INLINE.finditer(text):
        if m.start() > pos:
            out.append((text[pos:m.start()], tuple(tags)))
        pos = m.end()
        g = m.groupdict()
        if g["codet"] is not None:
            out.append((g["codet"], tuple(tags) + ("md_code",)))
        elif g["dm"] or g["bm"] or g["pm"] or g["m"]:
            out.extend(tex_segments((g["dm"] or g["bm"] or g["pm"] or g["m"]).strip(), tuple(tags) + ("md_math",)))
        elif g["bi"] or g["bi2"]:
            out.extend(md_inline(g["bi"] or g["bi2"], tuple(tags) + ("md_bi",)))
        elif g["b"] or g["b2"] or g["hb"]:
            out.extend(md_inline(g["b"] or g["b2"] or g["hb"], tuple(tags) + ("md_b",)))
        elif g["i"] or g["i2"] or g["hi"]:
            out.extend(md_inline(g["i"] or g["i2"] or g["hi"], tuple(tags) + ("md_i",)))
        elif g["s"]:
            out.extend(md_inline(g["s"], tuple(tags) + ("md_s",)))
        elif g["ce"] is not None:
            out.extend(chem_segments(g["ce"], tuple(tags)))
        elif g["sp"] is not None or g["sp2"] is not None:
            out.extend(tex_segments(g["sp"] if g["sp"] is not None else g["sp2"], tuple(tags) + ("md_sup",)))
        elif g["sb"] is not None:
            out.extend(tex_segments(g["sb"], tuple(tags) + ("md_sub",)))
        elif g["lt"]:
            out.append((g["lt"], tuple(tags) + ("md_link", "url:" + g["lu"])))
        elif g["sup"] is not None:
            out.append((g["sup"], tuple(tags) + ("md_sup",)))
        elif g["sub"] is not None:
            out.append((g["sub"], tuple(tags) + ("md_sub",)))
        elif g["br"] is not None:
            out.append(("\n", tuple(tags)))
    if pos < len(text):
        out.append((text[pos:], tuple(tags)))
    # tidy stray emphasis marks a model left behind (e.g. ****word or a lone **)
    fixed = []
    for t, tg in out:
        if "md_code" in tg or "md_math" in tg or "md_pre" in tg or any(x.startswith("url:") for x in tg):
            fixed.append((t, tg))
            continue
        t = re.sub(r"\*{2,}", "", t)
        t = re.sub(r"\$\$|(?<!\\)\$(?!\d)", "", t)           # stray math delimiters a model left open
        if re.search(r"\\[A-Za-z]{2,}|\\[{}()\[\],;!]|[\w)\]]\^\{", t):     # bare LaTeX without $...$
            t = re.sub(r"\\[()\[\]]", "", t)
            for t2, tg2 in tex_segments(t.replace("~", "\x01"), tg):
                fixed.append((t2.replace("\x01", "~"), tg2))
            continue
        fixed.append((t, tg))
    return fixed


def _plain_inline(t):
    return "".join(x for x, _ in md_inline(t))


def md_segments(text, base=()):
    """Markdown (headings, nested/numbered lists, tables, code blocks, quotes, rules, links, strikethrough, LaTeX)
    -> [(text, tags)] for a Tk Text widget."""
    text = (text or "").replace("\r\n", "\n")
    # JSON-mode replies can turn \frac into a form feed + "rac", \beta into a backspace...: put the backslashes back
    text = text.replace("\x0c", "\\f").replace("\x08", "\\b").replace("\x0b", "\\v")
    text = re.sub(r"\t(?=(?:imes|heta|ext|an\b|au\b|riangle|o\b|herefore|ilde|frac|extbf|extit))", r"\\t", text)
    text = re.sub(r"\r(?=(?:ightarrow|ho\b|ight\b|angle|ceil|floor|vert|m\b))", r"\\r", text)
    text = re.sub(r"\*{4,}", "**", text)
    lines = text.split("\n")
    out = []
    base = tuple(base)
    i = 0
    while i < len(lines):
        ln = lines[i]
        st = ln.strip()
        if st.startswith("```"):
            j = i + 1
            code = []
            while j < len(lines) and not lines[j].strip().startswith("```"):
                code.append(lines[j])
                j += 1
            out.append(("\n".join(code) + "\n", base + ("md_pre",)))
            i = j + 1
            continue
        if st.startswith("$$") and st.count("$$") == 1:
            j = i + 1
            eq = [st[2:]]
            while j < len(lines) and "$$" not in lines[j]:
                eq.append(lines[j])
                j += 1
            if j < len(lines):
                eq.append(lines[j].replace("$$", ""))
            out.append(("    ", base))
            out.extend(tex_segments(" ".join(x.strip() for x in eq if x.strip()), base + ("md_math",)))
            out.append(("\n", base))
            i = j + 1
            continue
        if st.startswith("|") and st.count("|") >= 2:
            rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                r = lines[i].strip().strip("|")
                if not re.fullmatch(r"[\s:|-]+", r):
                    rows.append([_plain_inline(c.strip()) for c in r.split("|")])
                i += 1
            ncol = max(len(r) for r in rows) if rows else 0
            rows = [r + [""] * (ncol - len(r)) for r in rows]
            wid = [min(40, max(len(r[k]) for r in rows)) for k in range(ncol)]
            for n, r in enumerate(rows):
                cells = [clip(c, 40).ljust(wid[k]) for k, c in enumerate(r)]
                out.append(("  " + "  │  ".join(cells) + "\n", base + (("md_th",) if n == 0 else ("md_table",))))
                if n == 0 and len(rows) > 1:
                    out.append(("  " + "──┼──".join("─" * w for w in wid) + "\n", base + ("md_table",)))
            continue
        m = re.match(r"^(#{1,6})\s+(.*?)\s*#*\s*$", st)
        if m:
            lvl = min(3, len(m.group(1)))
            out.extend(md_inline(m.group(2), base + ("md_h%d" % lvl,)))
            out.append(("\n", base))
            i += 1
            continue
        if re.fullmatch(r"(?:[-*_]\s*){3,}", st):
            out.append(("─" * 30 + "\n", base + ("md_hr",)))
            i += 1
            continue
        m = re.match(r"^\s*>\s?(.*)$", ln)
        if m:
            out.append(("▎ ", base + ("md_quote",)))
            out.extend(md_inline(m.group(1), base + ("md_quote",)))
            out.append(("\n", base))
            i += 1
            continue
        m = re.match(r"^(\s*)([-*+•])\s+(.*)$", ln)
        if m:
            lvl = min(3, len(m.group(1).replace("\t", "    ")) // 2)
            out.append(("•◦▪▫"[lvl] + " ", base + ("md_li%d" % lvl, "md_bullet")))
            out.extend(md_inline(m.group(3), base + ("md_li%d" % lvl,)))
            out.append(("\n", base))
            i += 1
            continue
        m = re.match(r"^(\s*)(\d+|[a-z])([.)])\s+(.*)$", ln)
        if m:
            lvl = min(3, len(m.group(1).replace("\t", "    ")) // 2)
            out.append((m.group(2) + m.group(3) + " ", base + ("md_li%d" % lvl, "md_num")))
            out.extend(md_inline(m.group(4), base + ("md_li%d" % lvl,)))
            out.append(("\n", base))
            i += 1
            continue
        out.extend(md_inline(ln, base))
        out.append(("\n", base))
        i += 1
    while out and out[-1][0] == "\n":
        out.pop()
    fixed = []
    for t, tg in out:                                      # Tk shows one font per character: merge the font tags
        if any(x.startswith("md_h") for x in tg):
            tg = tuple(x for x in tg if x not in ("md_b", "md_i", "md_bi"))
        elif "md_b" in tg and "md_i" in tg:
            tg = tuple(x for x in tg if x not in ("md_b", "md_i")) + ("md_bi",)
        fixed.append((t, tg))
    return fixed


def md_plain(text):
    """The same text without any Markdown marks (for bubbles, speech and saved history)."""
    segs = md_segments(text)
    return "".join(t.translate(_SUP) if "md_sup" in tg else t.translate(_SUB) if "md_sub" in tg else t for t, tg in segs)


def md_tags(t, size=10, fg=None):
    """Set up the rich-text tags on a Text widget once."""
    try:
        if getattr(t, "_md_ready", False):
            return
        t._md_ready = True
    except Exception:
        pass
    fg = fg or INK
    ui = FONT_UI
    mono = "Consolas" if IS_WIN else "Courier"
    serif = _serif_font(t)
    t.tag_configure("md_b", font=(ui, size, "bold"))
    t.tag_configure("md_i", font=(ui, size, "italic"))
    t.tag_configure("md_bi", font=(ui, size, "bold italic"))
    t.tag_configure("md_s", overstrike=True)
    t.tag_configure("md_h1", font=(serif, size + 6), foreground=GOLD, spacing1=8, spacing3=4)
    t.tag_configure("md_h2", font=(serif, size + 4), foreground=GOLD, spacing1=6, spacing3=3)
    t.tag_configure("md_h3", font=(ui, size + 1, "bold"), foreground=fg, spacing1=4, spacing3=2)
    t.tag_configure("md_code", font=(mono, size), background=FIELD, foreground=GOLD)
    t.tag_configure("md_pre", font=(mono, size - 1), background=FIELD, lmargin1=12, lmargin2=12, spacing1=2, spacing3=2)
    t.tag_configure("md_quote", foreground=GREY, font=(serif, size, "italic"), lmargin1=6, lmargin2=20)
    for k in range(4):
        t.tag_configure("md_li%d" % k, lmargin1=8 + 18 * k, lmargin2=22 + 18 * k, spacing1=1)
    t.tag_configure("md_bullet", foreground=GOLD)
    t.tag_configure("md_num", foreground=GOLD, font=(ui, size, "bold"))
    t.tag_configure("md_table", font=(mono, size - 1), lmargin1=6)
    t.tag_configure("md_th", font=(mono, size - 1, "bold"), foreground=GOLD, lmargin1=6)
    t.tag_configure("md_hr", foreground=LINE)
    t.tag_configure("md_link", foreground=T.get("start", GOLD), underline=True)
    t.tag_configure("md_math", font=(serif, size + 1, "italic"))
    t.tag_configure("md_sup", offset=max(3, size // 2 - 1), font=(serif, max(7, size - 3)))
    t.tag_configure("md_sub", offset=-max(2, size // 3), font=(serif, max(7, size - 3)))
    for k in ("md_sup", "md_sub", "md_link"):
        t.tag_raise(k)
    t.tag_bind("md_link", "<Enter>", lambda e: t.config(cursor="hand2"))
    t.tag_bind("md_link", "<Leave>", lambda e: t.config(cursor=""))


def md_bind_links(t, segs):
    for _, tg in segs:
        for x in tg:
            if x.startswith("url:"):
                try:
                    t.tag_bind(x, "<Button-1>", lambda e, u=x[4:]: webbrowser.open(u))
                except tk.TclError:
                    pass


def md_insert(t, text, base=(), index="end", size=10):
    """Insert rich text at index (the widget must be in state normal)."""
    md_tags(t, size)
    segs = md_segments(text, base)
    md_bind_links(t, segs)
    for s_, tg in segs:
        t.insert(index if index != "1.0" else "end", s_, tg)
    return segs


