def _bulk_k(y):
    """How much wider the upper body is drawn at height y: big traps and shoulders, very wide lats, a tighter waist."""
    if y < 22:
        return 1.0
    if y < 31:
        return 1.0 + (y - 22) / 9.0 * 0.38                     # thick neck into the traps
    if y < 52:
        return 1.38 if y < 46 else 1.38 - (y - 46) / 6.0 * 0.04
    if y < 82:
        return 1.34 - (y - 52) / 30.0 * 0.22                    # lats taper down into the waist
    return 1.12


def _body_grid(view):
    regs = BODY_FRONT if view == "front" else BODY_BACK
    g = [[None] * BODY_W for _ in range(BODY_H)]
    for y in range(BODY_H):
        for x in range(BODY_W):
            px = x + 0.5 - BODY_OX
            if px > 36:
                px = 72 - px
            py = y + 0.5 - BODY_OY
            tx = 36 - (36 - px) / _bulk_k(py)                    # a broad, bodybuilder build: the drawing is widened
            hx = 36 - (36 - px) / 1.12
            lx = 27.5 - (27.5 - (px + 1.6)) / (1.24 if py < 133 else (1.1 if py < 142 else 1.26))
            ax = px + 4.6 + max(0.0, py - 44) * 0.07           # arms sit out under the big shoulders...
            ax = 15.2 - (15.2 - ax) / (1.48 if py < 66 else 1.3)  # ...and are thicker (big biceps and triceps)
            for name, poly in regs:
                q = ax if name in _ARM else (lx if name in _LEGS else (hx if name in _HIPS else tx))
                if _pt_in(poly, q, py):
                    g[y][x] = name
    # the head (with a kitsune mask on the front, its red cord and ears on the back)
    for y in range(0, 32):
        for x in range(BODY_W):
            if ((x + 0.5 - 36 - BODY_OX) / 8.8) ** 2 + ((y + 0.5 - 15.5) / 11.2) ** 2 <= 1:
                g[y][x] = "head"
    for ex in (29.5 + BODY_OX, 42.5 + BODY_OX):                                     # the mask's fox ears
        for y in range(0, 10):
            w_ = (y + 1) * 0.62
            for x in range(BODY_W):
                if abs(x + 0.5 - ex) <= w_ * 0.5 and g[y][x] is None:
                    g[y][x] = "ear"
    return g


_SKINLIKE = ("neck", "elbow", "hand", "knee", "head")


def body_frames(view, targets, accent=(232, 84, 62), frames=4, done=()):
    """Pixel art of the body (front or back) as a list of fn(x, y) painters, one per glow frame."""
    g = _body_grid(view)
    lines = set()
    for (x0, y0), (x1, y1) in BODY_LINES[view]:
        n = int(max(abs(x1 - x0), abs(y1 - y0)) * 2) + 1
        for k in range(n + 1):
            t = k / float(n)
            x, y = x0 + (x1 - x0) * t, y0 + (y1 - y0) * t + BODY_OY
            for xx in (int(36 - (36 - x) * (1.3 if y < 90 + BODY_OY else 1.2)) + BODY_OX,
                       int(36 + (36 - x) * (1.3 if y < 90 + BODY_OY else 1.2)) + BODY_OX):
                if 0 <= xx < BODY_W and 0 <= int(y) < BODY_H:
                    lines.add((xx, int(y)))
    done = set(done)
    targets = set(targets) - done
    gold = [(104, 72, 22), (176, 130, 50), (232, 188, 92), (250, 220, 146), (255, 244, 212)]
    stone = [(78, 72, 128), (138, 130, 182), (186, 180, 220), (226, 222, 246), (246, 244, 255)]
    skin = [(84, 76, 118), (150, 138, 176), (198, 188, 216), (230, 224, 242), (248, 244, 255)]
    hot = [(110, 26, 40), _rgb_mix(accent, (40, 0, 20), 0.35), accent, _rgb_mix(accent, (255, 214, 160), 0.45),
           _rgb_mix(accent, (255, 248, 226), 0.75)]
    shorts = [(12, 14, 38), (26, 34, 84), (40, 54, 118), (62, 84, 160), (90, 116, 196)]
    tabi = [(110, 108, 136), (190, 190, 212), (232, 232, 244), (250, 250, 255), (255, 255, 255)]
    outline = (18, 14, 40)

    def reg(x, y):
        return g[y][x] if 0 <= x < BODY_W and 0 <= y < BODY_H else None

    # where each pixel sits across its muscle (0 = left/top edge, 1 = right/bottom edge): round, sculpted shading
    hu = [[0.5] * BODY_W for _ in range(BODY_H)]
    vu = [[0.5] * BODY_W for _ in range(BODY_H)]
    for y in range(BODY_H):
        x = 0
        while x < BODY_W:
            r = g[y][x]
            x2 = x
            while x2 + 1 < BODY_W and g[y][x2 + 1] == r:
                x2 += 1
            if r is not None:
                for k in range(x, x2 + 1):
                    hu[y][k] = (k - x + 0.5) / (x2 - x + 1)
            x = x2 + 1
    for x in range(BODY_W):
        y = 0
        while y < BODY_H:
            r = g[y][x]
            y2 = y
            while y2 + 1 < BODY_H and g[y2 + 1][x] == r:
                y2 += 1
            if r is not None:
                for k in range(y, y2 + 1):
                    vu[k][x] = (k - y + 0.5) / (y2 - y + 1)
            y = y2 + 1

    aura = {}
    if targets:
        for y in range(BODY_H):
            for x in range(BODY_W):
                if reg(x, y) is None:
                    best = 9
                    for dy in range(-3, 4):
                        for dx in range(-3, 4):
                            if reg(x + dx, y + dy) in targets:
                                best = min(best, abs(dx) + abs(dy))
                    if best <= 4:
                        aura[(x, y)] = best

    def paint(phase):
        pulse = 0.5 + 0.5 * _m.sin(phase * 2 * _m.pi)

        def f(x, y):
            r = reg(x, y)
            if r is None:
                d = aura.get((x, y))
                if d is None:
                    return None
                a = int((60 + 80 * pulse) * (1 - (d - 1) / 4.0))
                return (min(255, accent[0] + 20), min(255, accent[1] + 80), min(255, accent[2] + 60), a) if a > 4 else None
            nb = [reg(x - 1, y), reg(x + 1, y), reg(x, y - 1), reg(x, y + 1)]
            if None in nb:
                return outline
            if r == "ear":
                inner = abs(x + 0.5 - BODY_OX - (29.5 if x < 36 + BODY_OX else 42.5)) < 1.2 and y > 3
                return (226, 64, 82) if inner else (240, 236, 250)
            if r in _SKINLIKE:
                pal = skin
            elif r == "shorts":
                pal = shorts
            elif r == "glutes":
                pal = [_rgb_mix(a, b, 0.82 + 0.15 * pulse) for a, b in zip(shorts, hot)] if r in targets else (
                    [_rgb_mix(a, b, 0.75) for a, b in zip(shorts, gold)] if r in done else shorts)
            elif r == "tabi":
                pal = tabi
            else:
                pal = hot if r in targets else (gold if r in done else stone)
            # round shading: light from the top left, a rim of shadow on the far side, dithered between
            u = hu[y][x] * 0.7 + vu[y][x] * 0.3
            dith = (x + y) % 2
            if u < 0.16:
                k = 4 if vu[y][x] < 0.5 else 3
            elif u < 0.34:
                k = 3 if dith or u < 0.25 else 2
            elif u < 0.62:
                k = 2
            elif u < 0.78:
                k = 1 if dith else 2
            else:
                k = 1
            sep = any(n_ not in (None, r) for n_ in nb)
            if sep and r not in ("shorts", "tabi", "glutes", "torso", "legbase"):
                if reg(x + 1, y) not in (r, None) or reg(x, y + 1) not in (r, None):
                    k = 0                                       # the groove between two muscles
            if (x, y) in lines and r not in ("shorts", "tabi") + _SKINLIKE:
                k = 0 if r in targets else 1
            c = pal[k]
            if r in targets and r != "glutes" and k >= 3:
                c = _rgb_mix(c, (255, 250, 232), 0.3 * pulse)
            yy = y - BODY_OY
            if r == "shorts" and yy in (80, 81):                # a gold obi-style waistband
                c = (238, 200, 110) if yy == 80 else (168, 128, 56)
            if r == "shorts" and view == "front" and 33 <= x - BODY_OX <= 38 and 84 <= yy <= 92 and (x + yy) % 3 == 0:
                c = shorts[3]
            if r == "tabi" and x - BODY_OX in (29, 42) and yy >= 168:     # tabi socks: the split toe
                c = tabi[0]
            if r == "head":
                c = _rgb_mix((248, 246, 255), (176, 170, 214), max(0.0, hu[y][x] - 0.55) * 1.6)
                if view == "front":                             # the kitsune mask
                    for (ax, ay, col) in MASK_PIX:
                        if (x == ax + BODY_OX or x == 71 - ax + BODY_OX) and yy == ay:
                            c = col
                else:
                    if yy in (14, 15):                          # the mask cord, tied at the back
                        c = (222, 46, 64) if yy == 14 else (150, 24, 40)
                    if 34 <= x - BODY_OX <= 37 and 15 <= yy <= 21 and (x + yy) % 2 == 0:
                        c = (222, 46, 64)
            return c
        return f
    return [paint(k / float(frames)) for k in range(frames)]


