_FOOD_NUM = {"a": 1, "an": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "half": 0.5, "a half": 0.5,
             "couple of": 2, "a couple of": 2, "few": 3, "a few": 3, "some": 1, "double": 2}
_FOOD_UNITS = {"g": 1, "gram": 1, "grams": 1, "gm": 1, "kg": 1000, "ml": 1, "l": 1000, "oz": 28.35}
_SERVING_WORDS = r"(?:cups?|bowls?|plates?|slices?|pieces?|pcs|servings?|portions?|glass(?:es)?|cans?|bars?|scoops?|" \
                 r"tbsp|tablespoons?|tsp|teaspoons?|handfuls?|packs?|packets?|small|medium|large|big)"


def _food_words(text):
    """Lower-case words, with simple plurals made singular (sandwiches -> sandwich, cookies -> cookie)."""
    out = []
    for w_ in re.sub(r"[^a-z ]", " ", (text or "").lower()).split():
        if len(w_) > 4 and w_.endswith("ies"):
            w_ = w_[:-3] + "y" if w_ not in ("cookies", "smoothies", "brownies") else w_[:-1]
        elif len(w_) > 4 and w_.endswith(("ches", "shes", "oes")):
            w_ = w_[:-2]
        elif len(w_) > 3 and w_.endswith("s") and not w_.endswith(("ss", "us", "is")):
            w_ = w_[:-1]
        out.append(w_)
    return out


_FOOD_INDEX = None


def food_find(text):
    """The best food-table match in text: (entry, matched name) or (None, ''). The dish name wins over an ingredient
    ('chicken sandwiches' is a sandwich), plurals and small typos ('bryani') are forgiven."""
    global _FOOD_INDEX
    if _FOOD_INDEX is None:
        _FOOD_INDEX = [(e, n, " ".join(_food_words(n))) for e in FOODS for n in e[0]]
    singles = {nn for _, _, nn in _FOOD_INDEX if " " not in nn}
    words = []
    for w_ in _food_words(text):                             # forgive typos first: bryani -> biryani
        if len(w_) >= 5 and w_ not in singles:
            m = difflib.get_close_matches(w_, list(singles), 1, 0.8)
            if m:
                w_ = m[0]
        words.append(w_)
    t = " " + " ".join(words) + " "
    best, name, key = None, "", (-1, -1)
    for e, n, nn in _FOOD_INDEX:
        k = t.find(" " + nn + " ")
        if k >= 0:
            sc = (k + len(nn), len(nn))                      # the last-mentioned (head) noun, then the longest name
            if sc > key:
                best, name, key = e, n, sc
    return best, name


def _clean_num(s):
    s = re.sub(r"(\d),(\d{3})(?!\d)", r"\1\2", s)            # 1,400 -> 1400
    return re.sub(r"(\d),(\d{1,2})(?!\d)", r"\1.\2", s)      # 1,5 -> 1.5


def food_sane(kcal, prot):
    """No single food is 230,000 kcal: keep every estimate believable."""
    kcal = max(0, min(3000, int(round(kcal or 0))))
    prot = max(0.0, min(200.0, float(prot or 0), kcal / 4.0 if kcal else 0.0))
    return kcal, round(prot, 1)


def food_estimate(text):
    """Split 'what I ate' into items and estimate each from the table.
    Returns ([(label, kcal, protein, known)], unknown_parts)."""
    text = _clean_num(text or "")
    text = re.sub(r"\([^)]*\)", lambda m: m.group(0).replace(",", " ").replace(" and ", " & "), text)
    for e in FOODS:                                          # keep dishes like "rice and peas" in one piece
        for n in e[0]:
            if " and " in n:
                text = re.sub(re.escape(n), n.replace(" and ", "_n_"), text, flags=re.I)
    parts = [p.strip().replace("_n_", " and ") for p in re.split(r",|;|\n|\+|\band\b|\bwith\b|(?<!\()&", text, flags=re.I)
             if p.strip()]
    out, unknown = [], []
    for p in parts:
        low = p.lower()
        ek = re.search(r"(\d+(?:\.\d+)?)\s*(?:kcal|calories|calorie|cals?)\b", low)
        ep = re.search(r"(\d+(?:\.\d+)?)\s*g(?:rams?)?\s*(?:of\s+)?protein", low)
        e, nm = food_find(re.sub(r"\d+(?:\.\d+)?\s*(?:kcal|calories|calorie|cals?|g(?:rams?)?\s*(?:of\s+)?protein)\b", " ", low))
        label = p.strip().capitalize()
        if ek:                                               # they told me the calories: trust them
            kcal = float(ek.group(1))
            prot = float(ep.group(1)) if ep else (kcal * (e[4] / float(e[3])) if e and e[3] else kcal * 0.04)
            k_, p_ = food_sane(kcal, prot)
            out.append((label, k_, p_, True))
            continue
        if not e:
            unknown.append(p)
            continue
        rest = re.sub(r"\d+(?:\.\d+)?\s*g(?:rams?)?\s*(?:of\s+)?protein", " ", low)
        qty, grams = 1.0, None
        mg = re.search(r"(\d+(?:\.\d+)?)\s*(kg|g|grams?|gm|ml|l|oz)\b", rest)
        mq = re.search(r"(?<![\d.])(\d+(?:\.\d+)?|\d+/\d+)(?!\s*(?:kg|g|grams?|gm|ml|l|oz)\b)(?![\d.])", rest)
        cnt = None
        if mq:
            v = mq.group(1)
            cnt = (float(v.split("/")[0]) / float(v.split("/")[1])) if "/" in v else float(v)
            if not 0 < cnt <= 20:                            # '1000' is not a count of portions
                cnt = None
        if mg:
            grams = min(2500.0, float(mg.group(1)) * _FOOD_UNITS[mg.group(2) if mg.group(2) in _FOOD_UNITS else "g"])
            if cnt and re.search(r"\beach\b", rest):
                grams = min(2500.0, grams * cnt)
        else:
            if cnt:
                qty = cnt
            else:
                for w_, v in sorted(_FOOD_NUM.items(), key=lambda kv: -len(kv[0])):
                    if re.search(r"\b%s\b" % re.escape(w_), rest):
                        qty = v
                        break
            if re.search(r"\b(?:large|big|huge)\b", rest):
                qty *= 1.4
            elif re.search(r"\bsmall\b", rest) and "small bag" not in e[1]:
                qty *= 0.7
        _, serving, g_, kcal, prot = e
        k = qty if grams is None else grams / float(g_)
        k_, p_ = food_sane(kcal * k, prot * k)
        if ep:
            p_ = food_sane(k_, float(ep.group(1)))[1]
        out.append(("%s (%s)" % (label, ("%dg" % grams) if grams else "%s × %s" % (fmt_num(round(qty, 2)), serving)),
                    k_, p_, True))
    return out, unknown


def calorie_plan(kg, cm, age=17, sex=""):
    """A gentle plan for a teen who wants to lose fat and build muscle: upkeep, a small deficit, protein.
    Returns dict or None if weight is missing."""
    if not kg:
        return None
    prot = (round(kg * 1.6), round(kg * 2.0))
    if not cm:
        return {"protein": prot}
    base = 10 * kg + 6.25 * cm - 5 * age
    base += 5 if sex == "m" else (-161 if sex == "f" else -78)
    upkeep = int(round(base * 1.55 / 10.0) * 10)                   # school + 3 or more workouts a week
    floor = 2000 if sex == "m" else (1800 if sex == "f" else 1900)          # never too low for a growing teen
    target = max(floor, upkeep - 300)
    return {"upkeep": upkeep, "target": int(round(target / 10.0) * 10), "protein": prot}


class ZenkoBooks:
    """zenko9: the diary bookshelf (one book per subject + study diary + grades), each book's practice corner,
    the 'something urgent' delay, the grade tracker and the sleep / burnout guard."""

    def books_init(self):
        L = self.life
        L.setdefault("grades", [])
        L.setdefault("fr_vocab", {})
        L.setdefault("book_state", {})
        self.nb_sid = "shelf"
        self._delay = None
        self._sleep = {"nag": 0.0, "snooze": 0.0, "last": None, "studying": 0.0}
        self.book_imgs = {}
        self.root.after(25000, self.books_slow_tick)

    # =================================================================================================
    #  急 Something urgent: push the rest of today back, pause the timer, remind when it's time
    # =================================================================================================
    def delay_schedule(self, mins, why="", only=None, pause=True):
        mins = int(max(1, min(240, mins)))
        now = datetime.datetime.now()
        d = now.date().isoformat()
        snap = json.loads(json.dumps(self.tt))
        moved, dropped, extra = [], [], []
        for it in tt_today(self.tt):
            if tt_done(it) or (only is not None and id(it) not in only):
                continue
            try:
                st_, en = tt_window(it)
            except Exception:
                continue
            if st_ < now - datetime.timedelta(minutes=5) and not (only is not None and en > now):
                continue
            ns = st_ + datetime.timedelta(minutes=mins)
            if ns.date() != now.date():
                dropped.append(it["task"])
                continue
            hm = ns.strftime("%H:%M")
            if it.get("daily"):
                it.setdefault("skip", []).append(d)
                c = dict(it)
                c.pop("daily", None)
                c.update(date=d, start=hm, done=[], skip=[], delayed=True)
                extra.append(c)
            else:
                it["start"] = hm
                it["delayed"] = True
            moved.append((it["task"], hm))
        self.tt.extend(extra)
        save_tt(self.tt)
        paused = False
        s = self.session
        if s and not s.get("paused") and pause:
            s["paused"] = True
            self.alerted, self.dist_run = False, 0.0
            self.draw_panel()
            paused = True
        old = self._delay
        if old and old.get("job"):
            try:
                self.root.after_cancel(old["job"])
            except Exception:
                pass
        job = self.root.after(mins * 60 * 1000, self.delay_over)
        # chained delays keep the very first snapshot, so Undo goes all the way back
        self._delay = {"snap": old["snap"] if old else snap, "paused": paused or bool(old and old.get("paused")),
                       "job": job, "until": time.time() + mins * 60, "mins": mins, "why": why}
        self.tt_changed()
        bits = []
        if paused:
            bits.append("your focus timer is paused")
        if moved:
            first = moved[0]
            bits.append("%d thing%s moved back %d min (next: “%s” at %s)" % (
                len(moved), "" if len(moved) == 1 else "s", mins, clip(first[0], 26), first[1]))
        else:
            bits.append("nothing on today's timetable moved" if only is not None else
                        "nothing else on today's timetable needed moving")
        msg = "急! Go~ " + ", ".join(bits) + "."
        if dropped:
            msg += " %s won't fit before midnight, so I left %s." % (", ".join(clip(x, 20) for x in dropped[:2]),
                                                                    "it" if len(dropped) == 1 else "them")
        msg += " I'll call you back in %d min." % mins
        return msg

    def delay_over(self):
        D = self._delay
        if not D:
            return
        D["job"] = None
        beep("ding")
        self.set_mood("happy", 3)
        ch = []
        if self.session and self.session.get("paused") and D.get("paused"):
            ch.append(("Resume timer", self.delay_resume))
        else:
            ch.append(("I'm back", self.delay_resume))
        ch += [("+10 min", lambda: self.say(self.delay_schedule(10), 9)), ("Undo the move", self.delay_undo)]
        self.say("Okaeri~ the %d min are up. Ready to carry on?" % D["mins"], 30, choices=ch)

    def delay_resume(self):
        D, self._delay = self._delay, None
        s = self.session
        if D and D.get("paused") and s and s.get("paused"):
            s["paused"] = False
            self.draw_panel()
            self.say("Back to work! Ganbatte~", 5)
        else:
            self.say("Welcome back~ your timetable is already shifted.", 5)

    def delay_undo(self):
        D, self._delay = self._delay, None
        if not D:
            return "There's no delay to undo~"
        if D.get("job"):
            try:
                self.root.after_cancel(D["job"])
            except Exception:
                pass
        self.tt[:] = D["snap"]
        save_tt(self.tt)
        self.tt_changed()
        s = self.session
        if D.get("paused") and s and s.get("paused"):
            s["paused"] = False
            self.draw_panel()
        self.say("Undone: your timetable is back how it was.", 6)
        return "Undone: your timetable is back how it was."

    def tt_changed(self):
        for f in (self.tt_refresh, lambda: self.hub_refresh_page("timetable")):
            try:
                f()
            except Exception:
                pass

    def hub_refresh_page(self, name):
        h = getattr(self, "hub", None)
        if h and h.get("page") == name:
            try:
                self.hub_after_show(name)
            except Exception:
                pass

    def delay_menu(self, m):
        """The 急 cascade for the right-click menu (and the timetable button)."""
        sub = tk.Menu(m, tearoff=0)
        for n in (10, 15, 20, 30, 45, 60, 90):
            sub.add_command(label="%d min" % n if n < 60 else ("%g hour%s" % (n / 60.0, "" if n == 60 else "s")),
                            command=lambda n=n: self.say(self.delay_schedule(n), 10))
        if self._delay:
            sub.add_separator()
            sub.add_command(label="I'm back", command=self.delay_resume)
            sub.add_command(label="Undo the delay", command=self.delay_undo)
        return sub

    def delay_popup(self, widget):
        m = tk.Menu(self.root, tearoff=0)
        try:
            m.config(bg=FIELD, fg=INK, activebackground=ORANGE, activeforeground=ON_ACC)
        except tk.TclError:
            pass
        sub = self.delay_menu(m)
        try:
            x, y = widget.winfo_rootx(), widget.winfo_rooty() + widget.winfo_height()
            sub.tk_popup(x, y)
        finally:
            try:
                sub.grab_release()
            except Exception:
                pass

    # =================================================================================================
    #  chat
    # =================================================================================================
    def books_route(self, text):
        raw = text.strip()
        low = raw.lower()
        lw = low.rstrip(" !.?~")
        if re.match(r"^(?:undo|cancel) (?:the |my )?(?:delay|push ?back|postpone)", lw):
            return self.delay_undo()
        if re.match(r"^(?:i'?m back|im back|back now|done,? i'?m back)$", lw) and self._delay:
            self.delay_resume()
            return "Okaeri~"
        dur = re.search(r"(\d+(?:\.\d+)?|an?|one|half an?)\s*(hours?|hrs?|h|minutes?|mins?|m)\b", low)
        urgent = re.search(r"\b(delay|postpone|push (?:back|everything|my)|shift (?:my|the|everything)|something (?:came|has come) up|"
                           r"something urgent|need to (?:talk|speak|help|go|run|call|eat)|have to (?:talk|speak|help|go|call)|"
                           r"gotta (?:talk|go|help)|my (?:mum|mom|dad|parents) (?:need|want|called))\b", low)
        if urgent and not re.search(r"\b(timer|remind me)\b.*\bin\b", low):
            if dur:
                n, u = dur.group(1), dur.group(2)
                n = {"a": 1, "an": 1, "one": 1, "half a": 0.5, "half an": 0.5}.get(n, None) or float(n)
                mins = n * 60 if u.startswith("h") else n
                return self.delay_schedule(mins, raw)
            if re.search(r"\b(delay|postpone|push|shift|urgent|came up|need to|have to|gotta)\b", low):
                self.say("急? How long do you need?", 25,
                         choices=[("%d min" % n, lambda n=n: self.say(self.delay_schedule(n, raw), 10)) for n in (10, 20, 30, 60)])
                return "How long do you need? Tap a time on my bubble, or say 'delay 20 min'."
        # grades: "i got 34/40 in bio paper 1", "got a 6 on my chem mya", "bio mya 72%"
        g = self.grade_from_text(raw)
        if g:
            return g
        if re.match(r"^(?:open |show )?(?:my )?(?:grades?|results|grade tracker|marks|seiseki|成績)(?: book)?$", lw):
            self.root.after(150, lambda: self.book_open("grades", anim=False))
            return "Here's your 成績 book~"
        if re.match(r"^(?:open |start |do )?(?:my )?(?:a )?(?:french )?vocab(?:ulary)?(?: drill| practice| test| quiz)?$", lw):
            self.root.after(150, lambda: self.book_open("french", anim=False))
            return "Vocab drill in your 仏語 book~ allons-y!"
        m = re.match(r"^(?:open )?(?:my )?(\w+(?: \w+)?) (?:book|diary)$", lw)
        if m:
            k = {"diary": "diary", "study": "diary", "study diary": "diary", "grade": "grades", "grades": "grades"}.get(m.group(1)) \
                or self.subject_in(m.group(1))
            if k:
                self.root.after(150, lambda: self.book_open(k, anim=False))
                return "Opening your %s book~" % dict((b[0], b[1]) for b in BOOKS)[k]
        if re.match(r"^(?:open )?(?:my )?(?:book ?shelf|books|study books|hondana|本棚)$", lw):
            self.root.after(150, lambda: self.book_open("shelf"))
            return "Your bookshelf~"
        m = re.match(r"^(?:set |change )?(?:my )?bed ?time(?: to| is|:| at)?\s*(\d{1,2})(?::|\.)?(\d{2})?\s*(am|pm)?$", lw)
        if m:
            h, mi = int(m.group(1)), int(m.group(2) or 0)
            if m.group(3) == "pm" and h < 12:
                h += 12
            if m.group(3) == "am" and h == 12:
                h = 0
            if h > 23 or mi > 59:
                return "That doesn't look like a time~ try 'bedtime 22:30'."
            self.cfg_set("bedtime", "%02d:%02d" % (h, mi))
            self.cfg_set("sleep_guard", True)
            return "Bedtime set to %02d:%02d. I'll start the wind-down 30 min before~ oyasumi practice!" % (h, mi)
        if re.match(r"^(?:is it |how'?s (?:the |my )?|check (?:the )?)?(?:download(?:ing)?|model download|pull)(?: status| progress)?$", lw) \
                or re.match(r"^how do i know (?:it'?s|its|if it'?s) downloading$", lw):
            if getattr(self, "_pull", None):
                return "%s: %s" % (self._pull["name"], self.pull_text())
            return "Nothing is downloading right now~ press 'Get ...' in a study book's Tutor brain card to start one."
        if re.match(r"^(?:get|download|install) (?:my |your |the )?(?:eyes|vision(?: model)?|screenshot reader)$", lw):
            self.brain_pull(self.cfg.get("vision_model") or VISION_PULL)
            return ("Downloading my eyes (%s, about 3 GB, free). I'll show the progress here and pop up when it's done~"
                    % (self.cfg.get("vision_model") or VISION_PULL))
        if re.match(r"^(?:give me )?(?:a )?(?:bio(?:logy)? fact|syllabus fact)$", lw):
            f = random.choice(BIO_FACTS)
            return "%s %s: %s" % (f[0], f[1], f[2].replace("[", "").replace("]", ""))
        if re.match(r"^(?:give me )?(?:an? )?(?:english|writing|essay|paper 1|paper 2) tip$", lw):
            t = random.choice(ENGLISH_TIPS)
            return "%s tip: %s" % t
        return None

    # =================================================================================================
    #  本棚 the bookshelf
    # =================================================================================================
    def book_meta(self, key):
        for b in BOOKS:
            if b[0] == key:
                col = b[5]
                if not col:
                    col = next((d[3] for d in self.subjects() if d[0] == key), GOLD)
                return {"key": key, "kanji": b[1], "reading": b[2], "name": b[3], "coat": b[4], "col": col}
        return None

    def hub_build_notebook(self, pg):
        host = tk.Frame(pg, bg=PAPER)
        host.pack(fill="both", expand=True)
        self.nb = {"host": host, "hover": None, "ans": None, "dirty": False, "anim": None}
        if self.nb_sid not in BOOK_KEYS:
            self.nb_sid = "shelf"
        self.nb_render()

    def nb_show(self, sid):
        self.book_open("diary" if sid == "overview" else sid, anim=False)

    def book_open(self, key, anim=True):
        """Show the shelf ('shelf') or open a book (with the opening animation when it's clicked on the shelf)."""
        if key != "shelf" and key not in BOOK_KEYS:
            return
        h = getattr(self, "hub", None)
        if not (h and h["win"].winfo_exists() and h.get("page") == "notebook"):
            self.open_hub("notebook")
        if self.nb_quiz and self.nb_quiz.get("sid") != key:
            self.nb_quiz = None
        if anim and key != "shelf" and self.nb and self.nb.get("shelf"):
            self.book_anim(key)
            return
        self.nb_sid = key
        if key != "shelf":
            self.life["nb_last"] = key
        self.nb_render()

    def nb_refresh(self):
        nb = self.nb
        if not nb:
            return
        try:
            if not nb["host"].winfo_exists():
                self.nb = None
                return
            fw = nb["host"].winfo_toplevel().focus_get()
        except Exception:
            fw = None
        if nb.get("anim"):
            return
        if isinstance(fw, (tk.Entry, tk.Text)):
            nb["dirty"] = True
            return
        self.nb_render()

    def nb_render(self):
        nb = self.nb
        if not nb:
            return
        host = nb["host"]
        try:
            for ch in host.winfo_children():
                ch.destroy()
        except tk.TclError:
            return
        nb["dirty"] = False
        nb["shelf"] = None
        nb.pop("teach", None)
        nb.pop("ask_fn", None)
        if self.nb_sid not in BOOK_KEYS:
            self.nb_sid = "shelf"
            self.shelf_build(host)
        else:
            self.book_build(host, self.nb_sid)

    def nb_draw_tabs(self):
        pass

    # ---- the shelf -----------------------------------------------------------------------------------
    def shelf_build(self, host):
        cv = tk.Canvas(host, bg="#0b0f2a", highlightthickness=0, cursor="")
        cv.pack(fill="both", expand=True)
        self.nb["shelf"] = cv
        self.nb["hover"] = None
        self.nb["fx"] = {"petals": [], "t": 0, "lift": {}, "items": {}}
        if not hasattr(self, "shelf_imgs"):
            self.shelf_imgs = {}
        cv.bind("<Configure>", lambda e: self.shelf_draw())
        cv.bind("<Motion>", self.shelf_motion)
        cv.bind("<Leave>", lambda e: self.shelf_hover(None))
        cv.bind("<ButtonRelease-1>", self.shelf_click)
        cv.after(120, self.shelf_tick)

    def shelf_img(self, key, make):
        img = self.shelf_imgs.get(key)
        if img is None:
            if len(self.shelf_imgs) > 60:
                self.shelf_imgs = {}
            img = self.shelf_imgs[key] = make()
        return img

    def shelf_layout(self, W, H):
        n_row = (len(BOOKS) + 1) // 2
        bw = int(max(84, min(132, (W - 300) / n_row - 30)))
        bw = int(max(72, min(bw, (H - 262) / 2 / 1.42)))
        bw -= bw % 2
        bh = int(bw * 1.42)
        bh -= bh % 2
        gap = int(max(24, min(48, (W - 320 - n_row * bw) / (n_row + 1))))
        total = n_row * bw + (n_row - 1) * gap
        x0 = (W - total) // 2
        top = 124
        rows = [top + 18, top + 18 + bh + 46]
        spots = []
        for i, b in enumerate(BOOKS):
            r, c = divmod(i, n_row)
            spots.append((b[0], x0 + c * (bw + gap), rows[r], bw, bh))
        return spots, x0, total, rows, bw, bh

    def shelf_cabinet(self, w, h, rows_y, bh):
        """Pixel tansu: lacquered frame, dark back boards, two shelves, gold fittings. w/h in 2x pixels."""
        wood_l, wood, wood_d = (128, 78, 46), (92, 52, 30), (52, 28, 18)
        back, back_d = (30, 20, 28), (22, 14, 20)
        gold, gold_l = (196, 160, 72), (236, 208, 132)
        planks = [((y + bh) // 2, (y + bh) // 2 + 5) for y in rows_y]
        fr = 4

        def grain(x, y, base):
            g_ = 0.5 + 0.5 * _m.sin(y * 0.9 + 3 * _m.sin(x * 0.07 + y * 0.05)) * 0.5 + 0.15 * _h01(x // 4, y, 9)
            return _rgb_mix(base, wood_l, g_ * 0.4)

        def f(x, y):
            edge = x < fr or x >= w - fr or y < fr or y >= h - fr
            for (p1, p2) in planks:
                if p1 <= y < p2 and not edge:
                    if y == p1:
                        return wood_l
                    if y == p2 - 1:
                        return wood_d
                    return grain(x, y * 3, wood)
            if edge:
                c = grain(y if x < fr or x >= w - fr else x, x if x < fr or x >= w - fr else y, wood)
                if x in (0, w - 1) or y in (0, h - 1):
                    return wood_d
                for (cx_, cy_) in ((0, 0), (w - 1, 0), (0, h - 1), (w - 1, h - 1)):
                    if abs(x - cx_) < 7 and abs(y - cy_) < 7:
                        return gold_l if (x + y) % 6 == 0 else gold
                return c
            c = back if (x // 16) % 2 == 0 else _rgb_mix(back, back_d, 0.5)
            if x % 16 == 0:
                c = back_d
            for (p1, p2) in planks + [(fr, fr)]:
                if 0 <= y - p2 < 12:
                    c = _rgb_mix(c, (6, 3, 6), 0.55 * (1 - (y - p2) / 12.0))
            return c
        return f

    def shelf_draw(self):
        nb = self.nb
        cv = nb and nb.get("shelf")
        if not cv:
            return
        try:
            cv.delete("all")
            W, H = max(560, cv.winfo_width()), max(460, cv.winfo_height())
        except tk.TclError:
            return
        jp = _mincho_font(self.root)
        serif = _serif_font(self.root)
        spots, x0, total, rows, bw, bh = self.shelf_layout(W, H)
        nb["spots"] = spots
        F = nb["fx"]
        F["box"] = (W, H)
        F["items"] = {}
        # 1. the night (painted at 1/4 size and zoomed: chunky but calm)
        w4, h4 = W // 4 + 1, H // 4 + 1
        cv.create_image(0, 0, anchor="nw", image=self.shelf_img(("sky", w4, h4), lambda: px_photo(w4, h4, shelf_sky(w4, h4), 4)))
        # 2. drifting petals live here, BEHIND everything else (soft, blurred, slow)
        if not F["petals"]:
            F["petals"] = [[random.uniform(0, W), random.uniform(0, H), random.uniform(0.35, 1.0), random.uniform(0, 6.28), None]
                           for _ in range(9)]
        soft = [self.shelf_img(("petal_soft", i), lambda i=i: px_photo(9, 9, petal_soft(4.5, 0.55 - 0.2 * i), 2)) for i in (0, 1)]
        for p in F["petals"]:
            p[4] = cv.create_image(p[0], p[1], image=soft[0 if p[2] > 0.7 else 1], tags="petal")
        # 3. title block: vertical kanji, a fine gold rule, quiet serif type
        cv.create_text(44, 26, text="\n".join("本棚"), anchor="n", fill="#e9cf8a", font=(jp, 22), justify="center")
        cv.create_line(70, 30, 70, 92, fill="#8f7a45")
        cv.create_text(86, 34, text=spaced("THE LIBRARY"), anchor="w", fill="#c8ad6a", font=(serif, 9))
        cv.create_text(86, 58, text="Zenko's study books", anchor="w", fill="#f3ead6", font=(serif, 19))
        cv.create_text(86, 84, text="Choose a volume, and I'll open it for you.", anchor="w", fill="#a9a2c4", font=(serif, 10, "italic"))
        # 4. the cabinet
        L, R = x0 - 36, x0 + total + 36
        T_ = rows[0] - 28
        B = rows[1] + bh + 20
        cw2, ch2 = (R - L) // 2, (B - T_) // 2
        rel = [y - T_ for y in rows]
        cv.create_image(L, T_, anchor="nw", image=self.shelf_img(("cab", cw2, ch2, tuple(rel), bh),
                                                                lambda: px_photo(cw2, ch2, self.shelf_cabinet(cw2, ch2, rel, bh), 2)))
        # a slim shimenawa along the top, three paper shide
        ry = T_ - 3
        for i, x in enumerate(range(L - 4, R + 6, 6)):
            sag = 5 * _m.sin(_m.pi * (x - L + 4) / float(R - L + 8))
            cv.create_oval(x - 4, ry + sag - 3, x + 4, ry + sag + 3, fill="#cdb67c" if i % 2 else "#a88d55", outline="")
        for k in (1, 2, 3):
            sx = L + (R - L) * k / 4.0
            y1 = ry + 5 * _m.sin(_m.pi * k / 4.0) + 3
            pts = [sx - 4, y1, sx + 4, y1, sx + 4, y1 + 6, sx, y1 + 6, sx, y1 + 12, sx + 4, y1 + 12, sx + 4, y1 + 18,
                   sx - 4, y1 + 18, sx - 4, y1 + 12, sx, y1 + 12, sx, y1 + 6, sx - 4, y1 + 6]
            cv.create_polygon(pts, fill="#f4efe3", outline="")
        # lanterns on little wooden arms at the cabinet's top corners
        lw, lh = 12, 18
        for i, (ax, lx) in enumerate(((L, L - 30), (R, R + 30))):
            if lx < 18 or lx > W - 18:
                continue
            cv.create_line(ax, T_ + 6, lx, T_ + 6, fill="#4a2c18", width=4)
            ly = T_ + 6 + 12 + lh * 3 // 2
            cv.create_line(lx, T_ + 6, lx, ly - lh * 3 // 2, fill="#2a1a12", width=1)
            cv.create_image(lx, ly, image=self.shelf_img(("glow", 60), lambda: px_photo(60, 60, glow_art(30, (255, 170, 80), 0.35), 2)))
            cv.create_image(lx, ly, image=self.shelf_img(("lan", lw, lh), lambda: px_photo(lw, lh, lantern_art(lw, lh), 3)))
        # 5. the books (each one's items share a tag so the hover lift can glide them)
        wk = self.subject_minutes(start=self.week_start())
        for key, x, y, w, h in spots:
            b = self.book_meta(key)
            tag = "bk_" + key
            lift = F["lift"].get(key, 0.0)
            yy = y - lift
            gd = w // 2 + 26
            glow = cv.create_image(x + w / 2, yy + h / 2, image=self.shelf_img(("bglow", w), lambda gd=gd: px_photo(
                gd, gd, glow_art(gd / 2.0, (255, 214, 140), 0.55), 3)), tags=(tag,),
                state="normal" if nb.get("hover") == key else "hidden")
            cv.create_rectangle(x + 4, y + 3, x + w + 4, y + h + 1, fill="#000000", outline="", stipple="gray50")
            rx = x + w * 0.72
            cv.create_polygon(rx, yy + h - 4, rx + 5, yy + h - 4, rx + 5, yy + h + 12, rx + 2.5, yy + h + 9, rx, yy + h + 12,
                              fill="#b0122b" if key != "grades" else "#c9a24a", outline="", tags=(tag,))
            cw_, ch_ = w // 2, h // 2
            cv.create_image(x, yy, anchor="nw", tags=(tag,), image=self.shelf_img(
                ("cover", key, cw_, ch_), lambda b=b, cw_=cw_, ch_=ch_: px_photo(cw_, ch_, book_art(b["col"], cw_, ch_, False), 2)))
            self.book_labels(cv, x, yy, w - 6, h - 6, key, tag)
            if key in dict((d[0], 1) for d in SUBJECT_DEFS):
                sub = "%s this week" % fmt_hm(int(wk.get(key, 0)))
            elif key == "grades":
                n_ = len(self.life["grades"])
                sub = "%d result%s" % (n_, "" if n_ == 1 else "s")
            elif key == "bible":
                sub = "Hebrew · Greek · notes"
            else:
                sub = "time · goals · sleep"
            cv.create_text(x + w / 2, y + h + 21, text=sub, fill="#bfae8a", font=(serif, 8, "italic"))
            F["items"][key] = glow
        # 6. the legend: a horizontal hanging scroll (makimono) under the shelf
        self.shelf_scroll(cv, W / 2, min(H - 40, B + 46), min(W - 120, 600))

    def shelf_scroll(self, cv, cx, cy, sw):
        """A makimono: washi paper between two lacquered rollers with gold caps, indigo mounting at the edges."""
        jp = _mincho_font(self.root)
        serif = _serif_font(self.root)
        ph = 52
        x1, x2 = cx - sw / 2, cx + sw / 2
        pw = int(sw) // 2
        cv.create_rectangle(x1 + 4, cy - ph / 2 + 5, x2 + 4, cy + ph / 2 + 5, fill="#000000", outline="", stipple="gray50")
        cv.create_image(x1, cy - ph / 2, anchor="nw", image=self.shelf_img(("washi", pw, ph // 2),
                                                                         lambda: px_photo(pw, ph // 2, washi_art(pw, ph // 2), 2)))
        for yb in (cy - ph / 2, cy + ph / 2 - 5):
            cv.create_rectangle(x1, yb, x2, yb + 5, fill="#27305e", outline="")
            cv.create_line(x1, yb + (5 if yb < cy else 0), x2, yb + (5 if yb < cy else 0), fill="#b8975a")
        for xr in (x1 - 7, x2 - 7):
            cv.create_rectangle(xr, cy - ph / 2 - 6, xr + 14, cy + ph / 2 + 6, fill="#2a160d", outline="#120905")
            cv.create_line(xr + 4, cy - ph / 2 - 4, xr + 4, cy + ph / 2 + 4, fill="#5b3420")
            for yy in (cy - ph / 2 - 10, cy + ph / 2 + 6):
                cv.create_rectangle(xr + 1, yy, xr + 13, yy + 4, fill="#c9a24a", outline="#7a5a1a")
        self.nb["scroll"] = {
            "k": cv.create_text(x1 + 28, cy - 8, text="", anchor="w", fill="#3a1f12", font=(jp, 13)),
            "t": cv.create_text(x1 + 28, cy - 8, text="", anchor="w", fill="#2a1a12", font=(serif, 12)),
            "d": cv.create_text(x1 + 28, cy + 12, text="", anchor="w", fill="#6b5236", font=(serif, 9, "italic")),
            "x1": x1}
        self.shelf_scroll_text()

    def shelf_scroll_text(self):
        nb = self.nb
        S = nb.get("scroll")
        cv = nb.get("shelf")
        if not S or not cv:
            return
        hov = nb.get("hover")
        if hov:
            b = self.book_meta(hov)
            k, t = b["kanji"], b["name"]
            if hov in dict((d[0], 1) for d in SUBJECT_DEFS):
                wk = self.subject_minutes(start=self.week_start()).get(hov, 0)
                due = 0
                try:
                    due = sum(1 for c_ in self.cards_due() if c_.get("subject") == hov)
                except Exception:
                    pass
                d = "%s this week   ·   %d card%s due   ·   %s" % (fmt_hm(int(wk)), due, "" if due == 1 else "s",
                                                                    BOOK_PRACTICE.get(hov, "").split("·")[-1].strip())
            else:
                d = BOOK_PRACTICE.get(hov, "").split("·")[-1].strip()
        else:
            k, t, d = "案内", "How to use the library", "Click a volume to open it   ·   or say 'open my bio book', 'vocab drill', 'my grades'"
        try:
            cv.itemconfigure(S["k"], text=k)
            kx = cv.bbox(S["k"])
            cv.coords(S["t"], (kx[2] + 10) if kx else S["x1"] + 28, cv.coords(S["k"])[1])
            cv.itemconfigure(S["t"], text=t)
            cv.itemconfigure(S["d"], text=d)
        except tk.TclError:
            pass

    def book_labels(self, cv, x, y, w, h, key, tag=""):
        """The parts of a cover that need crisp type: the daisen slip with vertical kanji, the hanko, the name plate."""
        b = self.book_meta(key)
        jp = _mincho_font(self.root)
        serif = _serif_font(self.root)
        tags = ("book", tag) if tag else ("book",)
        sp = max(10, w // 10)
        dw = max(18, int(w / 4.0))
        dx = x + w - dw - max(8, w // 9)
        dy = y + max(9, h // 12)
        dh = h * 0.47
        cv.create_rectangle(dx, dy, dx + dw, dy + dh, fill="#f6efdf", outline="#a98d55", tags=tags)
        cv.create_rectangle(dx + 2, dy + 2, dx + dw - 2, dy + dh - 2, outline="#e0d0a6", tags=tags)
        fs = int(max(9, min(19, dw * 0.6)))
        cv.create_text(dx + dw / 2, dy + dh / 2, text="\n".join(b["kanji"]), fill="#1e1010", font=(jp, fs),
                       justify="center", tags=tags)
        hs = max(9, w // 8)
        hx, hy = dx - hs - 4, dy + dh - hs
        cv.create_rectangle(hx, hy, hx + hs, hy + hs, fill="#b8122a", outline="", tags=tags)
        cv.create_text(hx + hs / 2, hy + hs / 2 + 1, text="狐", fill="#fbe9e9", font=(jp, max(6, int(hs * 0.52))), tags=tags)
        py_ = y + h - 21
        cv.create_rectangle(x + sp + 6, py_, x + w - 8, py_ + 14, fill="#1a0e09", outline="#a98d55", tags=tags)
        cv.create_text(x + sp + (w - sp) / 2 + 1, py_ + 7, text=clip(b["name"], 22), fill="#f0deb4",
                       font=(serif, 7 if w < 112 else 8), tags=tags)

    def shelf_hover(self, k):
        nb = self.nb
        if not nb or k == nb.get("hover"):
            return
        old, nb["hover"] = nb.get("hover"), k
        cv = nb.get("shelf")
        try:
            cv.config(cursor="hand2" if k else "")
            for kk, gid in nb["fx"]["items"].items():
                cv.itemconfigure(gid, state="normal" if kk == k else "hidden")
        except tk.TclError:
            return
        self.shelf_scroll_text()

    def shelf_fx_draw(self):
        pass

    def shelf_tick(self):
        """One calm step: petals drift slowly behind the shelf, books glide up and down to their hover height."""
        nb = self.nb
        cv = nb and nb.get("shelf")
        if not cv:
            return
        try:
            if not cv.winfo_exists():
                return
        except tk.TclError:
            return
        F = nb.get("fx", {})
        if not nb.get("anim") and F.get("box"):
            W, H = F["box"]
            try:
                for p in F["petals"]:
                    p[3] += 0.025
                    p[0] += 0.28 * p[2] + 0.22 * _m.sin(p[3])
                    p[1] += 0.22 * p[2]
                    if p[1] > H + 12 or p[0] > W + 12:
                        p[0], p[1] = random.uniform(-W * 0.2, W * 0.9), -12
                    if p[4]:
                        cv.coords(p[4], p[0], p[1])
                for key, *_r in nb.get("spots", []):
                    cur = F["lift"].get(key, 0.0)
                    goal = 7.0 if nb.get("hover") == key else 0.0
                    if abs(goal - cur) > 0.05:
                        nxt = cur + (goal - cur) * 0.35
                        if abs(goal - nxt) < 0.3:
                            nxt = goal
                        cv.move("bk_" + key, 0, -(nxt - cur))
                        F["lift"][key] = nxt
            except tk.TclError:
                return
        cv.after(40, self.shelf_tick)

    def book_cover(self, cv, x, y, w, h, key, tag="", pattern=True):
        b = self.book_meta(key)
        jp = _jp_font(self.root) or FONT_UI
        col = b["col"]
        cover = _mixhex(col, "#000000", 0.28)
        lite = _mixhex(col, "#ffffff", 0.18)
        tags = ("book", tag) if tag else ("book",)
        cv.create_rectangle(x + 4, y + 5, x + w + 4, y + h + 5, fill="#000000", outline="", stipple="gray50", tags=tags)
        cv.create_rectangle(x, y, x + w, y + h, fill=cover, outline=_mixhex(cover, "#000000", 0.4), tags=tags)
        if pattern and w > 50:
            # seigaiha waves on the lower half of the cover
            r = max(6, w // 9)
            yy = y + h - 4
            row = 0
            while yy > y + h * 0.52:
                off = (r if row % 2 else 0)
                xx = x - off
                while xx < x + w + r:
                    for k in (1.0, 0.66, 0.33):
                        rr = r * k
                        if xx - rr >= x + max(6, w // 11) + 1 and xx + rr <= x + w - 1:
                            cv.create_arc(xx - rr, yy - rr, xx + rr, yy + rr, start=0, extent=180, style="arc",
                                          outline=_mixhex(cover, lite, 0.45), tags=tags)
                    xx += 2 * r
                yy -= r * 0.75
                row += 1
            cv.create_rectangle(x, y + h - 2, x + w, y + h, fill=cover, outline="", tags=tags)
        # stab binding (yotsume toji) along the spine
        cv.create_rectangle(x, y, x + max(6, w // 11), y + h, fill=_mixhex(cover, "#000000", 0.3), outline="", tags=tags)
        sx = x + max(6, w // 11) / 2 + 1
        for i in range(4):
            sy = y + h * (0.12 + 0.253 * i)
            cv.create_line(x, sy, sx + 4, sy, fill="#f0e6cc", width=1, tags=tags)
            cv.create_oval(sx + 2, sy - 2, sx + 6, sy + 2, fill="#f0e6cc", outline="", tags=tags)
        # daisen: the white title slip with vertical kanji
        if w > 50:
            dw = max(18, w // 4.2)
            dx = x + w - dw - max(6, w // 10)
            dy = y + max(8, h // 14)
            dh = h * 0.5
            cv.create_rectangle(dx, dy, dx + dw, dy + dh, fill="#f6efdc", outline="#c9b98e", tags=tags)
            cv.create_rectangle(dx + 2, dy + 2, dx + dw - 2, dy + dh - 2, outline="#d9cba3", tags=tags)
            fs = int(max(9, min(19, dw * 0.62)))
            cv.create_text(dx + dw / 2, dy + dh / 2, text="\n".join(b["kanji"]), fill="#2a1717", font=(jp, fs, "bold"),
                           justify="center", tags=tags)
            # hanko seal
            hs = max(10, w // 7)
            hx, hy = dx - hs - 4, dy + dh - hs
            cv.create_rectangle(hx, hy, hx + hs, hy + hs, fill="#c8102e", outline="#8a0b20", tags=tags)
            cv.create_text(hx + hs / 2, hy + hs / 2 + 1, text="狐", fill="#ffffff", font=(jp, max(6, int(hs * 0.5)), "bold"), tags=tags)
            # english name on the cover's foot
            cv.create_rectangle(x + max(6, w // 11) + 4, y + h - 26, x + w - 6, y + h - 8, fill=_mixhex(cover, "#000000", 0.35),
                                outline="", tags=tags)
            cv.create_text(x + max(6, w // 11) + (w - max(6, w // 11)) / 2, y + h - 17, text=clip(b["name"], 20), fill="#f6efdc",
                           font=(FONT_UI, 7 if w < 110 else 8, "bold"), tags=tags)

    def shelf_key(self, x, y):
        for key, bx, by, w, h in (self.nb or {}).get("spots", []):
            if bx <= x <= bx + w and by - 10 <= y <= by + h:
                return key
        return None

    def shelf_motion(self, e):
        if self.nb.get("anim"):
            return
        self.shelf_hover(self.shelf_key(e.x, e.y))

    def shelf_click(self, e):
        if self.nb.get("anim"):
            return
        k = self.shelf_key(e.x, e.y)
        if k:
            ui_sound("nav")
            self.book_open(k)

    # ---- the opening animation -----------------------------------------------------------------------
    def book_anim(self, key):
        nb = self.nb
        cv = nb["shelf"]
        spot = next((s for s in nb.get("spots", []) if s[0] == key), None)
        if not spot:
            self.nb_sid = key
            self.nb_render()
            return
        _, x, y, w, h = spot
        W, H = cv.winfo_width(), cv.winfo_height()
        w2 = int(min(W * 0.3, (H - 60) / 1.4))
        h2 = int(w2 * 1.4)
        cx, cy = W / 2, (H - h2) / 2
        nb["anim"] = True
        steps_a, steps_b = 9, 12
        b = self.book_meta(key)
        cover = _mixhex(b["col"], "#000000", 0.28)
        inside = _mixhex(b["col"], "#ffffff", 0.55)
        paper = "#f6efdc"
        ui_sound("nav")

        def frame(i):
            if not cv.winfo_exists():
                return
            cv.delete("anim")
            cv.create_rectangle(0, 0, W, H, fill="#000000", outline="", stipple="gray50", tags="anim")
            if i < steps_a:
                t = (i + 1) / steps_a
                t = 1 - (1 - t) ** 3
                bx = x + (cx - w2 / 2 - x) * t
                by = y + (cy - y) * t
                bw = w + (w2 - w) * t
                bh = h + (h2 - h) * t
                self.book_cover(cv, bx, by, bw, bh, key, tag="anim", pattern=i == steps_a - 1)
            else:
                t = (i - steps_a + 1) / steps_b
                sx = cx                       # the spine ends up in the middle of the spread
                slide = (1 - t) * (w2 / 2)    # the closed book slides right so its spine lands mid-screen
                spine = sx - w2 / 2 + (w2 / 2) * min(1.0, t * 1.4)
                # right page (revealed)
                cv.create_rectangle(spine, cy, spine + w2, cy + h2, fill=paper, outline="#c9b98e", tags="anim")
                for k in range(1, 9):
                    ly = cy + h2 * k / 9
                    cv.create_line(spine + 12, ly, spine + w2 - 12, ly, fill="#e3d6b4", tags="anim")
                ang = _m.pi * t
                cw = w2 * _m.cos(ang)
                skew = h2 * 0.06 * _m.sin(ang)
                if cw >= 0:
                    pts = [spine, cy, spine + cw, cy - skew, spine + cw, cy + h2 + skew, spine, cy + h2]
                    cv.create_polygon(pts, fill=cover, outline=_mixhex(cover, "#000000", 0.4), tags="anim")
                else:
                    # left page under the swinging cover
                    lw = -cw
                    cv.create_rectangle(spine - w2, cy, spine, cy + h2, fill=paper, outline="#c9b98e", tags="anim")
                    pts = [spine, cy, spine - lw, cy - skew, spine - lw, cy + h2 + skew, spine, cy + h2]
                    cv.create_polygon(pts, fill=inside, outline=_mixhex(inside, "#000000", 0.3), tags="anim")
                cv.create_line(spine, cy, spine, cy + h2, fill=_mixhex(cover, "#000000", 0.3), width=3, tags="anim")
                _ = slide
            if i + 1 < steps_a + steps_b:
                cv.after(22 if i < steps_a else 26, lambda: frame(i + 1))
            else:
                cv.after(90, finish)

        def finish():
            if self.nb:
                self.nb["anim"] = None
            self.nb_sid = key
            self.life["nb_last"] = key
            self.nb_render()
        frame(0)

    # =================================================================================================
    #  an open book: Zenko teaching on the left page, the tutor on the right
    # =================================================================================================
    def book_build(self, host, key):
        """An open book, laid out like a fine printed book: a quiet header with a gold rule, generous margins, sections
        separated by space and hairlines instead of boxes."""
        b = self.book_meta(key)
        jp = _mincho_font(self.root)
        serif = _serif_font(self.root)
        col = b["col"]
        cover = _mixhex(col, "#000000", 0.45)
        page = T["card"]
        hdr = tk.Frame(host, bg=PAPER)
        hdr.pack(fill="x", padx=28, pady=(16, 0))
        back = tk.Label(hdr, text="←  本棚", bg=PAPER, fg=GREY, font=(jp, 10), cursor="hand2")
        back.pack(side="left", anchor="s", pady=(0, 6))
        back.bind("<Button-1>", lambda e: self.book_open("shelf"))
        back.bind("<Enter>", lambda e: back.config(fg=GOLD))
        back.bind("<Leave>", lambda e: back.config(fg=GREY))
        tk.Label(hdr, text=b["kanji"], bg=PAPER, fg=_mixhex(col, "#ffffff", 0.25), font=(jp, 24)).pack(side="left", padx=(26, 12))
        tb = tk.Frame(hdr, bg=PAPER)
        tb.pack(side="left", anchor="s")
        tk.Label(tb, text=spaced(b["reading"].upper()), bg=PAPER, fg=GREY, font=(serif, 8)).pack(anchor="w")
        tk.Label(tb, text=b["name"], bg=PAPER, fg=INK, font=(serif, 18)).pack(anchor="w")
        right = tk.Frame(hdr, bg=PAPER)
        right.pack(side="right", anchor="s", pady=(0, 6))
        if key in dict((d[0], 1) for d in SUBJECT_DEFS):
            wk = self.subject_minutes(start=self.week_start()).get(key, 0)
            today = self.subject_minutes(days=1).get(key, 0)
            tk.Label(right, text="Today  %s     This week  %s" % (fmt_hm(int(today)), fmt_hm(int(wk))), bg=PAPER, fg=GREY,
                     font=(serif, 9, "italic")).pack(side="right")
        others = tk.Frame(right, bg=PAPER)
        others.pack(side="right", padx=(0, 22))
        for k2 in BOOK_KEYS:
            if k2 == key:
                continue
            m2 = self.book_meta(k2)
            lab = tk.Label(others, text=m2["kanji"], bg=PAPER, fg=_mixhex(m2["col"], PAPER, 0.15), font=(jp, 9), padx=3, cursor="hand2")
            lab.pack(side="left")
            lab.bind("<Button-1>", lambda e, k2=k2: self.book_open(k2, anim=False))
            lab.bind("<Enter>", lambda e, l=lab: l.config(fg=GOLD))
            lab.bind("<Leave>", lambda e, l=lab, c=m2["col"]: l.config(fg=_mixhex(c, PAPER, 0.15)))
        rule = tk.Canvas(host, height=10, bg=PAPER, highlightthickness=0)
        rule.pack(fill="x", padx=28, pady=(6, 10))
        rule.bind("<Configure>", lambda e, c=rule: (c.delete("all"), c.create_line(0, 5, e.width, 5, fill=_mixhex(GOLD, PAPER, 0.45)),
                                                     c.create_rectangle(0, 3, 46, 7, fill=_mixhex(col, "#ffffff", 0.1), outline="")))
        # the book: a slim cover edge, a hairline of gold, two pages with a soft gutter shadow
        book = tk.Frame(host, bg=cover)
        book.pack(fill="both", expand=True, padx=24, pady=(0, 18))
        goldf = tk.Frame(book, bg=_mixhex("#d4af37", cover, 0.35))
        goldf.pack(fill="both", expand=True, padx=4, pady=4)
        inner = tk.Frame(goldf, bg=page)
        inner.pack(fill="both", expand=True, padx=1, pady=1)
        left = tk.Frame(inner, bg=page, width=380)
        left.pack(side="left", fill="y")
        left.pack_propagate(False)
        inner.bind("<Configure>", lambda e, l=left: l.config(width=max(360, min(440, int(e.width * 0.42)))), add="+")
        for t_ in (0.30, 0.18, 0.08):                      # the gutter: page curving into the spine
            tk.Frame(inner, bg=_mixhex(page, "#000000", t_), width=2).pack(side="left", fill="y")
        for t_ in (0.10, 0.04):
            tk.Frame(inner, bg=_mixhex(page, "#000000", t_), width=2).pack(side="left", fill="y")
        rightp = tk.Frame(inner, bg=page)
        rightp.pack(side="left", fill="both", expand=True)
        lin = self.hub_scroller(left)
        rin = self.hub_scroller(rightp)
        for w_ in (lin, rin):
            w_.config(bg=page)
            try:
                w_.master.config(bg=page, width=80)          # small request: the page's real width decides
                w_.master.master.config(bg=page)
            except tk.TclError:
                pass
        lbody = tk.Frame(lin, bg=page)
        lbody.pack(fill="x", padx=(18, 14), pady=(16, 22))
        rbody = tk.Frame(rin, bg=page)
        rbody.pack(fill="x", padx=(22, 22), pady=(12, 26))
        self.nb["body"] = rbody
        self._book_ctx = True
        try:
            self.teach_build(lbody, key)
            pc = self.hub_card(lbody, BOOK_PRACTICE.get(key, "Practice"))
            pc.pack(fill="x", pady=(10, 0))
            try:
                getattr(self, "practice_" + key)(pc, key)
            except Exception as ex:
                tk.Label(pc, text="(this practice page hit a snag: %s)" % ex, bg=pc.cget("bg"), fg=GREY,
                         font=(FONT_UI, 8)).pack(padx=14, pady=8)
            if key in dict((d[0], 1) for d in SUBJECT_DEFS):
                self.brain_card(lbody, key)
                self.nb_subject_page(rbody, key)
            elif key == "diary":
                self.nb_overview(rbody, stack=True)
            else:
                self.grades_page(rbody)
        finally:
            self._book_ctx = False
        for body in (lbody, rbody):
            cv = body.master.master
            cv.bind("<Configure>", lambda e, b=body, c=cv: self.root.after_idle(lambda: self.book_fit(b, c)), add="+")
            self.root.after(60, lambda b=body, c=cv: self.book_fit(b, c))

    def book_fit(self, body, cv):
        """Keep a book page inside its paper: a row of buttons that is too wide breaks onto a second line, and a long
        label wraps, so nothing is ever cut off at the edge of the page."""
        try:
            if not body.winfo_exists():
                return
            body.update_idletasks()
            right = cv.winfo_rootx() + cv.winfo_width() - 6
        except tk.TclError:
            return

        def room(w):
            r = right - w.winfo_rootx()
            return min(r, w.winfo_width()) if w.winfo_width() > 1 else r

        def walk(w):
            for ch in w.winfo_children():
                try:
                    cls = ch.winfo_class()
                    if cls == "Label" and ch.winfo_reqwidth() > room(ch) + 2 and len(str(ch.cget("text"))) > 30:
                        ch.config(wraplength=max(150, room(ch) - 4), justify="left")
                    elif cls == "Frame" and ch.winfo_reqwidth() > room(ch) + 2:
                        kids = [k for k in ch.winfo_children() if k.winfo_manager() == "pack"]
                        if len(kids) >= 2 and all(k.pack_info().get("side") == "left" for k in kids):
                            self.book_reflow(ch, kids, room(ch))
                            continue
                        walk(ch)
                    elif cls == "Frame":
                        walk(ch)
                except tk.TclError:
                    pass
        walk(body)

    def book_reflow(self, row, kids, avail):
        """Turn a packed row into a wrapped grid that fits avail pixels."""
        info = []
        for k in kids:
            pi = k.pack_info()
            info.append((k, pi.get("padx", 0), pi.get("pady", 0)))
            k.pack_forget()
        r = c = x = 0
        for k, px, py in info:
            pxw = sum(px) if isinstance(px, (tuple, list)) else 2 * int(px or 0)
            w = k.winfo_reqwidth() + pxw
            if c and x + w > avail:
                r, c, x = r + 1, 0, 0
            k.grid(row=r, column=c, sticky="w", padx=px, pady=(py if r == 0 else (4, 0)))
            c += 1
            x += w

    def book_section(self, parent, title=None):
        """Inside a book, sections are set like a printed page: a kanji + serif heading, a hairline, lots of air
        (hub_card hands over to this while a book is being built)."""
        page = T["card"]
        f = tk.Frame(parent, bg=page)
        if title:
            jp = _mincho_font(self.root)
            serif = _serif_font(self.root)
            row = tk.Frame(f, bg=page)
            row.pack(fill="x", padx=16, pady=(22, 4))
            kan, _, eng = title.partition(" · ")
            if not eng:
                kan, eng = "", title
            if kan:
                tk.Label(row, text=kan, bg=page, fg=_mixhex(GOLD, page, 0.1), font=(jp, 12)).pack(side="left", padx=(0, 10))
            tk.Label(row, text=eng, bg=page, fg=INK, font=(serif, 13), anchor="w").pack(side="left")
            ln = tk.Frame(f, bg=_mixhex(LINE, page, 0.25), height=1)
            ln.pack(fill="x", padx=16, pady=(4, 12))
        else:
            tk.Frame(f, bg=page, height=10).pack(fill="x")
        return f

