    def teach_line(self, key):
        b = self.book_meta(key)
        if key == "diary":
            return "Kon! This is our 日記: your study time, goals and how you're sleeping~"
        if key == "grades":
            return "Kon! Write your results in here whenever you get them back. I'll keep the trends~"
        return "Kon! Sensei Zenko here. Today in %s: do the practice below, then ask me anything on the right page~" % b["kanji"]

    def teach_say(self, text=None, secs=4.0, board=None, happy=False):
        T_ = (self.nb or {}).get("teach")
        if not T_:
            return
        try:
            if text is not None:
                T_["line"].config(text=clip(text, 220))
            if board is not None:
                T_["cv"].itemconfig(T_["board"], text=clip(board, 60))
        except tk.TclError:
            return
        T_["talk"] = time.time() + secs
        if happy:
            T_["happy"] = time.time() + 2.0

    def teach_step(self):
        T_ = (self.nb or {}).get("teach")
        if not T_:
            return
        cv = T_["cv"]
        try:
            if not cv.winfo_exists():
                return
        except tk.TclError:
            return
        T_["i"] += 1
        i = T_["i"]
        now = time.time()
        if now < T_.get("happy", 0):
            st_ = "giggle" if i % 2 else "happy"
        elif now < T_["talk"]:
            st_ = "happy" if i % 2 else "idle"
        else:
            st_ = "blink" if i % 17 == 0 else "idle"
        try:
            cv.itemconfig(T_["fox"], image=self.book_fox(T_["key"], st_, (i // 2) % 8))
            wig = 3 * _m.sin(i * 0.9) if now < T_["talk"] else 1.2 * _m.sin(i * 0.3)
            cv.coords(T_["ptr"], 140, 112, 188 + wig, 66 - wig)
            cv.coords(T_["tip"], 185 + wig, 63 - wig, 191 + wig, 69 - wig)
        except tk.TclError:
            return
        cv.after(170 if now < T_["talk"] else 260, self.teach_step)

    def nb_ask(self, sid, q, mode="explain", to_chat=False, done=None):
        if not to_chat and self.nb and self.nb.get("teach"):
            self.teach_say("Fumu fumu~ let me think about that...", 30, board=clip(q, 50))

        def fin(txt):
            if done:
                done(txt)
            first = re.split(r"(?<=[.!?])\s", (txt or "").replace("\n", " ").replace("Kon! ", ""))[0]
            self.teach_say(first or "There~", min(9, 2.5 + len(txt or "") / 220.0))
        return super().nb_ask(sid, q, mode, to_chat, fin)

    def book_ask(self, q, mode="explain"):
        f = (self.nb or {}).get("ask_fn")
        if f:
            f(q, mode)

