    def src_add(self, sid):
        try:
            from tkinter import filedialog
        except Exception:
            return
        paths = filedialog.askopenfilenames(parent=self.hub["win"], title="Add sources for %s" % self.sname(sid, False),
                                            filetypes=[("Notes and slides", "*.pdf *.docx *.pptx *.txt *.md *.rtf *.html *.png *.jpg *.jpeg"),
                                                       ("All files", "*.*")])
        if not paths:
            return
        vm = self.cfg.get("vision_model", "") if hasattr(self, "cfg") else ""

        def job():
            got, bad = [], []
            for p in paths:
                try:
                    txt, _ = read_any_file(p, vm)
                    txt = re.sub(r"[ \t]+", " ", txt or "")
                    txt = re.sub(r"\n{3,}", "\n\n", txt).strip()
                    if len(txt) < 40:
                        bad.append((os.path.basename(p), "no readable text (a scanned PDF? try a photo of the page instead)"))
                        continue
                    got.append({"id": "%x%04x" % (int(time.time() * 1000), random.randrange(65536)), "name": os.path.basename(p),
                                "path": p, "added": time.time(), "words": len(txt.split()), "text": txt[:400000]})
                except Exception as ex:
                    bad.append((os.path.basename(p), str(ex)))
            return got, bad

        def fin(res, err):
            if err or not res:
                self.say("Couldn't read that (%s)" % err, 8)
                return
            got, bad = res
            items = self.src_load(sid) + got
            self.src_save(sid, items)
            msg = "Added %d file%s to your %s sources~" % (len(got), "" if len(got) == 1 else "s", self.sname(sid)) if got else ""
            if bad:
                msg += " Couldn't read: " + "; ".join("%s (%s)" % (clip(n, 24), clip(e, 60)) for n, e in bad[:2])
            self.say(msg.strip(), 9)
            self.nb_render()
        self.say("Reading your files~", 4)
        self.bg(job, fin)

    def src_remove(self, sid, iid):
        self.src_save(sid, [i for i in self.src_load(sid) if i["id"] != iid])
        self.nb_render()

    # ---- the engine ------------------------------------------------------------------------------------
    @staticmethod
    def src_passages(items, size=900):
        """[(source name, passage text)] in reading order: paragraphs packed into ~size-char passages."""
        out = []
        for it in items:
            buf = ""
            for para in re.split(r"\n\s*\n|\n(?=[A-Z0-9•\-\*])", it["text"]):
                para = para.strip()
                if not para:
                    continue
                if len(buf) + len(para) > size and buf:
                    out.append((it["name"], buf.strip()))
                    buf = ""
                while len(para) > size * 1.6:
                    out.append((it["name"], para[:size]))
                    para = para[size:]
                buf += para + "\n"
            if buf.strip():
                out.append((it["name"], buf.strip()))
        return out

    @staticmethod
    def src_rank(passages, query, k=6):
        """BM25-ish ranking of passages for a question."""
        def toks(t):
            return [w for w in re.findall(r"[a-zA-ZÀ-ÿ0-9]{2,}", t.lower()) if w not in _STOP]
        q = set(toks(query))
        if not q:
            return passages[:k]
        docs = [toks(p[1]) for p in passages]
        N = len(docs) or 1
        df = {}
        for dd in docs:
            for w in set(dd):
                df[w] = df.get(w, 0) + 1
        avg = sum(len(dd) for dd in docs) / float(N) or 1.0
        scored = []
        for i, dd in enumerate(docs):
            tf = {}
            for w in dd:
                tf[w] = tf.get(w, 0) + 1
            s = 0.0
            for w in q:
                pre = [x for x in tf if len(w) > 4 and x.startswith(w[:5])] if w not in tf else [w]
                f = sum(tf[x] for x in pre)
                if f:
                    idf = _m.log(1 + (N - df.get(w, 1) + 0.5) / (df.get(w, 1) + 0.5))
                    s += idf * f * 2.2 / (f + 1.2 * (0.25 + 0.75 * len(dd) / avg))
            scored.append((s, i))
        top = [i for s, i in sorted(scored, reverse=True)[:k] if s > 0]
        return [passages[i] for i in sorted(top)] or passages[:min(k, 2)]

    @staticmethod
    def src_key_sentences(text, n=10):
        sents = [s.strip() for s in re.split(r"(?<=[.!?])\s+|\n", text) if 40 <= len(s.strip()) <= 320]
        if not sents:
            return []
        freq = {}
        for w in re.findall(r"[a-zA-Z]{3,}", text.lower()):
            if w not in _STOP:
                freq[w] = freq.get(w, 0) + 1
        def score(s):
            ws = [w for w in re.findall(r"[a-zA-Z]{3,}", s.lower()) if w not in _STOP]
            return sum(freq.get(w, 0) ** 0.5 for w in ws) / (len(ws) ** 0.6 + 1) + (1.5 if re.search(r"\b(is|are|means|called|defined)\b", s) else 0)
        best = sorted(range(len(sents)), key=lambda i: -score(sents[i]))[:n]
        return [sents[i] for i in sorted(best)]

    def src_local(self, sid, kind, items, q=None):
        """No smart brain: an extractive study guide / briefing / answer, still with citations."""
        name = self.sname(sid, False)
        allt = "\n\n".join(i["text"] for i in items)
        if kind == "ask":
            sents = [(it["name"], s_.strip()) for it in items for s_ in re.split(r"(?<=[.!?])\s+|\n", it["text"]) if len(s_.strip()) > 25]
            P = self.src_rank(sents, q, 4)
            if not P:
                return "I couldn't find that in your sources~"
            out = ["From your sources:"]
            for i, (nm, p) in enumerate(P, 1):
                out.append("[%d] %s" % (i, p))
            out.append("\nSources: " + "; ".join("[%d] %s" % (i, nm) for i, (nm, _) in enumerate(P, 1)))
            out.append("(Turn on the free smart brain for a written answer: Settings > Smart brain setup.)")
            return "\n".join(out)
        if kind == "brief":
            pts = self.src_key_sentences(allt, 8)
            return "Briefing: %s\n\n" % name + "\n".join("• " + p for p in pts)
        lines = ["# %s study notes" % name, "From: " + ", ".join(i["name"] for i in items), ""]
        for it in items:
            heads = [h.strip(" #•-*") for h in it["text"].split("\n")
                     if 3 < len(h.strip()) < 70 and (h.strip().isupper() or re.match(r"^(\d+(\.\d+)*|[A-Z]\d\.\d)\s+\w", h.strip())
                                                     or (h.strip().istitle() and len(h.split()) <= 8)) and not h.strip().endswith(".")]
            lines.append("## %s" % it["name"])
            if heads:
                lines.append("Outline: " + " · ".join(dict.fromkeys(heads[:14])))
            for s in self.src_key_sentences(it["text"], 10):
                lines.append("• " + s)
            lines.append("")
        terms = []
        for m in re.finditer(r"(?m)^\s*[•\-\*]?\s*([A-Za-z][\w\- ]{2,40}?)\s*(?::| - | – )\s*(.{10,200})$", allt):
            terms.append((m.group(1).strip(), m.group(2).strip()))
        for m in re.finditer(r"([A-Z][a-z]+(?: [a-z]+){0,3}) (?:is|are) (?:the |an? )?(.{15,160}?)\.", allt):
            terms.append((m.group(1), m.group(2)))
        seen, tl = set(), []
        for t, dfn in terms:
            if t.lower() not in seen and len(tl) < 14:
                seen.add(t.lower())
                tl.append("• %s: %s" % (t, dfn))
        if tl:
            lines += ["## Key terms"] + tl + [""]
        qs = ["Define %s." % t.split(":")[0][2:] for t in tl[:4]] + ["Outline %s." % h for h in []]
        if qs:
            lines += ["## Practise"] + ["• " + x for x in qs]
        lines.append("\n(These notes are picked straight from your files. With the free smart brain on, I write a full study guide.)")
        return "\n".join(lines)

    def src_llm(self, sid, kind, items, q, model, P):
        name = self.sname(sid, False)
        names = brain_names()
        if not names:
            return None
        m = self.subject_model(sid, names, model)
        sysmsg = ("You are Zenko, an expert IB Diploma %s teacher. The student sits exams in May 2027. %s Use ONLY the "
                  "student's sources given to you; never invent facts. Use Markdown headings and bullet lists." % (
                      name, SYLLABUS_2027.get(sid, "")))

        def chat(prompt, n=1400):
            j = _ollama_json("/api/chat", {"model": m, "stream": False, "messages": [
                {"role": "system", "content": sysmsg}, {"role": "user", "content": prompt}],
                "options": {"temperature": 0.25, "num_predict": n, "num_ctx": 8192}, "online": True}, 600)
            return ((j.get("message") or {}).get("content") or "").strip()
        if kind == "ask":
            ctx = "\n\n".join("[%d] (%s)\n%s" % (i, nm, p) for i, (nm, p) in enumerate(P, 1))
            ans = chat("Sources:\n%s\n\nQuestion: %s\n\nAnswer from the sources and cite them like [1] or [2][3]. If they don't "
                       "cover it, say 'Not in your sources' and then give a short answer marked (outside your sources)." % (ctx, q), 900)
            return ans + "\n\nSources: " + "; ".join("[%d] %s" % (i, nm) for i, (nm, _) in enumerate(P, 1)) if ans else None
        passages = self.src_passages(items, 5200)
        if len(passages) > 6:
            step = len(passages) / 6.0
            passages = [passages[int(i * step)] for i in range(6)]
        guide = ("Write a study guide with these sections: OVERVIEW (3-4 sentences); KEY IDEAS (short headings with bullet "
                 "points, keep every formula, date, named study or example); KEY TERMS (term - definition); PRACTISE (5 exam-style "
                 "questions using IB command terms like define, outline, explain, evaluate); WATCH OUT (things students mix up).")
        if kind == "brief":
            guide = "Write a briefing: the 6-8 most important points as bullets, then a 3-sentence summary."
        if len(passages) == 1:
            self._src_job["msg"] = "Writing your notes..."
            return chat("Source (%s):\n%s\n\n%s" % (passages[0][0], passages[0][1], guide), 1600)
        parts = []
        for i, (nm, p) in enumerate(passages, 1):
            self._src_job["msg"] = "Reading part %d of %d..." % (i, len(passages))
            parts.append(chat("From this part of '%s', write compact study notes (headings + bullets, key terms with "
                              "definitions, any formulas, dates or studies). Only use this text:\n\n%s" % (nm, p), 700))
        self._src_job["msg"] = "Putting it all together..."
        return chat("Here are partial notes from the student's sources:\n\n%s\n\nCombine them into one clean document. %s"
                    % ("\n\n---\n\n".join(parts), guide), 1800)

    def src_run(self, sid, kind, q=None):
        J = getattr(self, "_src_job", None)
        if J and not J.get("end"):
            self.say("I'm still working on the last one~ (%s)" % J.get("msg", ""), 5)
            return
        items = self.src_load(sid)
        if not items:
            self.say("Add a file to your sources first~", 5)
            return
        model = self.cfg.get("llm_model") or "llama3.2:3b"
        use = bool(self.cfg.get("llm_enabled", True))
        J = self._src_job = {"sid": sid, "kind": kind, "msg": "Reading your sources...", "end": None, "t0": time.time()}
        P = self.src_rank(self.src_passages(items), q, 6) if kind == "ask" else None

        def job():
            if kind == "cards":
                src = (self.life.get("src_out", {}).get(sid) or {}).get("text") or "\n\n".join(i["text"] for i in items)
                J["msg"] = "Making flashcards..."
                return self.cards_from_text(src[:9000], model if use else None, sid)
            txt = None
            if use:
                try:
                    txt = self.src_llm(sid, kind, items, q, model, P)
                except Exception:
                    txt = None
            return txt or self.src_local(sid, kind, items, q)

        def fin(res, err):
            J["end"] = time.time()
            if err or not res:
                J["msg"] = "Uu~ that didn't work (%s)" % (err or "no result")
                self.src_watch()
                return
            if kind == "cards":
                self.nb_save_cards(sid, res, "your sources")
                J["msg"] = "Saved %d flashcards~" % len(res)
            else:
                head = {"notes": "", "brief": "", "ask": "Q: %s\n\n" % q}[kind]
                self.life.setdefault("src_out", {})[sid] = {"kind": kind, "text": (head + res)[:30000], "t": time.time()}
                self.life_save()
                J["msg"] = "Done in %ds~" % (J["end"] - J["t0"])
                self.teach_say("Here you go~ your %s." % {"notes": "study notes", "brief": "briefing", "ask": "answer"}[kind], 4, happy=True)
            self.src_watch()
            self.root.after(600, self.nb_refresh)
        self.bg(job, fin)
        self.teach_say("Fumu fumu~ reading your files...", 20)
        self.src_watch()

    def src_watch(self):
        J = getattr(self, "_src_job", None)
        U = (self.nb or {}).get("src_ui")
        if not J:
            return
        if U and U[0] == J["sid"]:
            try:
                if U[1].winfo_exists():
                    dots = "." * (1 + int(time.time() * 2) % 3) if not J.get("end") else ""
                    U[1].config(text="%s%s %s" % (J["msg"], dots, "" if J.get("end") else "(%ds)" % (time.time() - J["t0"])))
            except tk.TclError:
                pass
        if not J.get("end"):
            self.root.after(500, self.src_watch)

    def src_export(self, sid):
        last = self.life.get("src_out", {}).get(sid)
        if not last:
            return
        folder = os.path.join(os.path.expanduser("~"), "Documents", "Zenko notes")
        try:
            os.makedirs(folder, exist_ok=True)
            fn = os.path.join(folder, "%s %s %s.md" % (self.sname(sid), {"notes": "notes", "brief": "briefing", "ask": "answer"}.get(
                last["kind"], "notes"), datetime.datetime.now().strftime("%Y-%m-%d %H%M")))
            with open(fn, "w", encoding="utf-8") as f:
                f.write(last["text"])
            self.say("Saved to Documents > Zenko notes~", 6)
            if IS_WIN:
                os.startfile(folder)
        except Exception as ex:
            self.say("Couldn't save (%s)" % ex, 6)

    # =================================================================================================
    #  screenshots in chat: paste (Ctrl+V), pick a file or snip the screen; she reads it, then thinks about it
    # =================================================================================================
    def chat_attach_menu(self, widget):
        m = tk.Menu(self.root, tearoff=0)
        try:
            m.config(bg=FIELD, fg=INK, activebackground=ORANGE, activeforeground=ON_ACC)
        except tk.TclError:
            pass
        m.add_command(label="Paste screenshot  (Ctrl+V)", command=self.chat_paste)
        m.add_command(label="Choose an image...", command=self.chat_pick_image)
        m.add_command(label="Snap my whole screen", command=self.chat_snap)
        try:
            m.tk_popup(widget.winfo_rootx(), widget.winfo_rooty() - 4 - 3 * 24)
        finally:
            m.grab_release()

    def chat_paste(self, _e=None):
        try:
            got = clipboard_image()
        except Exception as ex:
            got = None
            if _e is None:
                self.chat_status("Couldn't read the clipboard (%s)" % ex)
        if not got:
            if _e is None:
                self.chat_status("No picture on the clipboard. Take one with Win+Shift+S, then press Ctrl+V here~")
            return None                                    # let a normal text paste happen
        self.chat_set_attachment(*got)
        return "break"

    def chat_pick_image(self):
        try:
            from tkinter import filedialog
        except Exception:
            return
        p = filedialog.askopenfilename(parent=self.chat["win"] if self.chat else self.root, title="Pick a screenshot",
                                       filetypes=[("Pictures", "*.png *.jpg *.jpeg"), ("All files", "*.*")])
        if not p:
            return
        try:
            with open(p, "rb") as f:
                data = f.read(25_000_000)
        except OSError as ex:
            self.chat_status("Couldn't open it (%s)" % ex)
            return
        if not image_dims(data):
            self.chat_status("I can read PNG and JPG pictures~")
            return
        self.chat_set_attachment(data, os.path.basename(p))

    def chat_snap(self):
        wins = []
        for w_ in (getattr(self, "hub", None) or {}).get("win"), (self.chat or {}).get("win"):
            try:
                if w_ is not None and w_.winfo_exists() and w_.state() != "withdrawn":
                    w_.withdraw()
                    wins.append(w_)
            except tk.TclError:
                pass

        def grab():
            try:
                png = grab_screen_png(1600)[0]
            except Exception as ex:
                png = None
                self.chat_status("Couldn't snap the screen (%s)" % ex)
            for w_ in wins:
                try:
                    w_.deiconify()
                except tk.TclError:
                    pass
            if png:
                self.chat_set_attachment(png, "my screen.png")
        self.root.after(380, grab)

    def chat_status(self, txt):
        c = self.chat
        try:
            if c and c["status"].winfo_exists():
                c["status"].config(text=txt)
        except tk.TclError:
            pass

    def chat_set_attachment(self, data, name):
        self.chat_att = {"data": data, "name": name, "thumb": None}
        c = self.chat
        if not c:
            return
        bar = c.get("attbar")
        try:
            if not bar or not bar.winfo_exists():
                return
            for ch in bar.winfo_children():
                ch.destroy()
            thumb = self.chat_thumb(data, 90)
            self.chat_att["thumb"] = thumb
            if thumb:
                tk.Label(bar, image=thumb, bg=PAPER, bd=0).pack(side="left", padx=(0, 8))
            dims = image_dims(data)
            tk.Label(bar, text="%s%s attached. Ask about it, or just press Send~" % (
                clip(name, 30), (" (%d×%d)" % dims) if dims else ""), bg=PAPER, fg=INK, font=(FONT_UI, 9)).pack(side="left")
            x = tk.Label(bar, text="✕", bg=PAPER, fg=GREY, font=(FONT_UI, 10), cursor="hand2")
            x.pack(side="left", padx=8)
            x.bind("<Button-1>", lambda e: self.chat_clear_attachment())
            bar.pack(fill="x", padx=c.get("pad", (24, 24)), pady=(4, 0), before=c["row"])
            c["entry"].focus_set()
        except tk.TclError:
            pass

    def chat_clear_attachment(self):
        self.chat_att = None
        c = self.chat
        try:
            if c and c.get("attbar") and c["attbar"].winfo_exists():
                for ch in c["attbar"].winfo_children():
                    ch.destroy()
                c["attbar"].pack_forget()
        except tk.TclError:
            pass

    def chat_thumb(self, data, max_side):
        """A small PhotoImage of a PNG (Tk can't show JPEGs, so those get no preview)."""
        if data[:8] != b"\x89PNG\r\n\x1a\n":
            return None
        try:
            img = tk.PhotoImage(data=base64.b64encode(data))
            k = max(1, int(_m.ceil(max(img.width(), img.height()) / float(max_side))))
            return img.subsample(k, k) if k > 1 else img
        except tk.TclError:
            return None

    def chat_image(self, q, att):
        """She reads the screenshot with her eyes (local vision model), then thinks about it with the best brain she has
        for that subject, so maths/science questions get proper working, not just a description."""
        self.chat_line("You", "%s   [%s]" % (q, att["name"]))
        c = self.chat
        thumb = self.chat_thumb(att["data"], 260)
        if thumb and c and not self._chat_typing and not self._chat_q:
            try:
                t = c["txt"]
                t.config(state="normal")
                t.image_create("end", image=thumb, padx=4, pady=4)
                t.insert("end", "\n\n")
                t.config(state="disabled")
                t.see("end")
                self._chat_imgs = (getattr(self, "_chat_imgs", []) + [thumb])[-12:]
            except tk.TclError:
                pass
        want = self.cfg.get("vision_model", "") or VISION_PULL
        textm = self.cfg.get("llm_model") or "llama3.2:3b"
        prof = self.user_profile_text() or ""
        learned = self.life.get("subj_words")
        P = {"msg": "Looking at your screenshot..."}

        def job():
            if online_ready():                             # online: it reads + solves (with web search), the PC's model checks IB terms
                P["msg"] = "Reading it online with %s..." % online_name()
                try:
                    sysmsg = ("You are Zenko, a kind fox-girl study buddy and an expert IB Diploma tutor. The student (IB DP, exams "
                              "May 2027, subjects: %s) sent a screenshot. Work out what it is, then answer their question properly: "
                              "solve or explain problems step by step with IB command terms and mark-scheme style points; for an "
                              "error message or website, say what it means and what to do; if it lists dates or deadlines, list "
                              "them. Be accurate. Format with clear Markdown (short headings, **bold** key terms, lists, a table if it helps, maths as LaTeX in $...$). %s" % (
                                  ", ".join(subject_name(d[0], self.life, False) for d in SUBJECT_DEFS), prof))
                    draft, gsrc = online_chat([{"role": "system", "content": sysmsg},
                                               {"role": "user", "content": "My question: " + q,
                                                "images": [base64.b64encode(att["data"]).decode()]}],
                                              search=True, max_tokens=1500, timeout=120)
                except Exception as ex:
                    ONLINE["last_err"] = str(ex)
                    draft, gsrc = "", []
                if draft:
                    sid0 = classify_subject(q + "\n" + draft, learned)[0]
                    who = None
                    if sid0 and self.cfg.get("llm_enabled", True):
                        P["msg"] = "Checking it against the IB syllabus on your PC..."
                        draft, who = self.ib_recheck(sid0, q, draft, "explain", textm)
                    note = "(read online by %s%s)" % (online_name(), (", checked for IB DP terms by %s on your PC" % who) if who else "")
                    if gsrc:
                        note += "\nSources:\n" + "\n".join("• %s - %s" % (clip(t, 60), u) for t, u in gsrc)
                    return draft + "\n\n" + note, None, None
                P["msg"] = "Online brain is busy, using your PC's eyes..."
            names = ollama_models()
            if names is None:
                raise RMError("NO_OLLAMA")
            vm = pick_vision(names, want)
            if not vm:
                raise RMError("NO_VISION")
            P["msg"] = "Reading it with %s..." % vm
            seen = ollama_vision(SHOT_READ, [att["data"]], vm, timeout=300)
            sid = classify_subject(q + "\n" + seen, learned)[0]
            tm = None
            if self.cfg.get("llm_enabled", True):
                text_names = [n for n in names if n != vm and "cloud" not in n and not re.search(r"vl|vision|llava|moondream|minicpm-v|embed", n)]
                tm = self.subject_model(sid, text_names, textm) if text_names else None
            if tm:
                P["msg"] = "Thinking it through with %s..." % tm
                name = subject_name(sid, self.life, False) if sid else "their studies"
                sysmsg = ("You are Zenko, a kind fox-girl study buddy and an expert IB Diploma tutor. The student (IB DP, exams "
                          "May 2027) sent a screenshot. Your eyes already read it for you (below). Work out what it is, then "
                          "answer the question properly: solve or explain problems step by step with IB command terms and "
                          "mark-scheme style points; for an error message or website, say what it means and what to do; if "
                          "it lists dates or deadlines, list them and offer to add them to the planner. Be accurate, and say "
                          "if part of the reading looks garbled. Format with clear Markdown (short headings, **bold** key terms, lists, a table if it helps, maths as LaTeX in $...$). %s %s" % (
                              ("Subject: %s. %s" % (name, SYLLABUS_2027.get(sid, ""))) if sid else "", prof))
                j = _ollama_json("/api/chat", {"model": tm, "stream": False, "messages": [
                    {"role": "system", "content": sysmsg},
                    {"role": "user", "content": "My question: %s\n\nWhat the screenshot shows:\n%s" % (q, seen[:6000])}],
                    "options": {"temperature": 0.3, "num_predict": 1000}}, 300)
                ans = ((j.get("message") or {}).get("content") or "").strip()
                if ans:
                    return ans, vm, tm
            P["msg"] = "Answering..."
            ans = ollama_vision("%s\n\nAnswer the student's question about this screenshot clearly and correctly, step by step "
                                "if it's a problem. Question: %s" % (prof, q), [att["data"]], vm, timeout=300)
            return ans or seen, vm, None

        def fin(res, err):
            self.chat_status("")
            if err:
                e = str(err)
                if e == "NO_OLLAMA":
                    msg = ("To read screenshots I need the free Ollama app running on your PC (Settings > Smart brain setup). "
                           "Everything stays on your computer.")
                elif e.startswith("NO_VISION"):
                    msg = ("I need my 'eyes' first: a free vision model (%s, about 3 GB, one time). Say 'get my eyes' and I'll "
                           "download it with a progress bar~" % VISION_PULL)
                else:
                    msg = "I couldn't read that screenshot (%s)." % e
                self.fox_reply(msg)
                return
            ans, vm, tm = res
            if vm is None:
                self.fox_reply(ans)
            else:
                self.fox_reply(ans + "\n\n(read with %s%s)" % (vm, (", answered with %s" % tm) if tm else ""))
            self.set_mood("happy", 2)

        def tick():
            if P.get("done"):
                return
            self.chat_status(P["msg"] + "." * (1 + int(time.time() * 2) % 3))
            self.root.after(500, tick)
        self.bg(job, lambda r, e: (P.__setitem__("done", True), fin(r, e)))
        self.set_mood("focus", 6)
        tick()

