    def _p_label(self, c, text="", fg=None, size=9, bold=False, wrap=320, pady=(0, 4)):
        lab = tk.Label(c, text=text, bg=c.cget("bg"), fg=fg or INK, font=(FONT_UI, size, "bold" if bold else "normal"),
                       anchor="w", justify="left", wraplength=wrap)
        lab.pack(fill="x", padx=14, pady=pady)
        return lab

    def _p_entry(self, c, width=26):
        v = tk.StringVar()
        e = self.tt_entry(c, v, width)
        e.pack(anchor="w", padx=14, pady=(2, 4))
        return v, e

    # ---- 生物 Bio: a syllabus fact, then a cloze quiz on it ----------------------------------------------
    def practice_bio(self, c, key):
        bs = self.life["book_state"].setdefault("bio", {"seen": [], "right": 0})
        code = self._p_label(c, "", fg=GOLD, size=8, bold=True)
        fact = self._p_label(c, "", size=10)
        v, e = self._p_entry(c, 24)
        fb = self._p_label(c, "", fg=GREY, size=8)
        row = tk.Frame(c, bg=c.cget("bg"))
        row.pack(fill="x", padx=14, pady=(2, 12))
        S = {"f": None, "quiz": False}

        def pick():
            seen = bs["seen"][-30:]
            pool = [f for f in BIO_FACTS if f[2] not in seen] or BIO_FACTS
            f = random.choice(pool)
            bs["seen"] = (seen + [f[2]])[-30:]
            S["f"], S["quiz"] = f, False
            code.config(text="%s · %s" % (f[0], f[1]))
            fact.config(text=f[2].replace("[", "").replace("]", ""))
            v.set("")
            e.pack_forget()
            fb.config(text="Read it, then tap 'Quiz me' and I'll hide the key word~")
            self.teach_say("Did you know? %s" % f[1], 3, board="%s %s" % (f[0], f[1]))
            self.life_save()

        def quiz():
            f = S["f"]
            S["quiz"] = True
            fact.config(text=re.sub(r"\[.*?\]", "_____", f[2]))
            e.pack(anchor="w", padx=14, pady=(2, 4), after=fact)
            e.focus_set()
            fb.config(text="Type the missing word(s), then Enter.")

        def check(_e=None):
            f = S["f"]
            if not S["quiz"]:
                quiz()
                return
            want = re.search(r"\[(.*?)\]", f[2]).group(1)
            got = v.get().strip()
            g_, w_ = bio_norm(got), bio_norm(want)
            if not g_:
                return
            ok = g_ == w_ or (len(g_) > 3 and w_.startswith(g_)) or (len(w_) > 5 and difflib.SequenceMatcher(None, g_, w_).ratio() > 0.85)
            if ok:
                bs["right"] = bs.get("right", 0) + 1
                fb.config(text="正解! Correct~ (%d right so far)" % bs["right"], fg=T.get("good", GOLD))
                self.teach_say("Sugoi! That's straight from %s." % f[0], 2.5, happy=True)
                beep("happy") if self.cfg.get("book_sounds", False) else None
            else:
                fb.config(text="Not quite: it's “%s”. I saved it to your Bio deck~" % want, fg=GREY)
                self.nb_mistake({"q": "%s %s: %s" % (f[0], f[1], re.sub(r"\[.*?\]", "_____", f[2])), "a": want}, False, "bio")
                self.teach_say("Close! The word was %s." % want, 3)
            fact.config(text=f[2].replace("[", "").replace("]", ""))
            S["quiz"] = False
            self.life_save()
        e.bind("<Return>", check)
        self.tt_btn(row, "Quiz me", check, bg=ORANGE, fg=ON_ACC, size=9, padx=10, pady=1).pack(side="left")
        self.tt_btn(row, "Next fact", pick, bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=6)
        self.tt_btn(row, "Explain more", lambda: S["f"] and self.book_ask("Explain %s (%s)" % (S["f"][1], S["f"][0])),
                    bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        self._p_label(c, "Facts follow the topic codes of the 2023 Biology guide (your exams in 2027 use it).", fg=GREY, size=7,
                      pady=(0, 10))
        pick()

    # ---- 化学 / 数学: generated problems with worked solutions ----------------------------------------
    def practice_chem(self, c, key):
        self._drill(c, key, chem_problem, "Every problem is new. Answers within about 1% count (3 s.f. is fine).")

    def practice_math(self, c, key):
        self._drill(c, key, math_problem, "Every problem is new. P1 = do it without a calculator; P2 = GDC allowed.")

    def _drill(self, c, key, gen, note):
        bs = self.life["book_state"].setdefault(key, {"right": 0, "tries": 0, "streak": 0, "best": 0})
        top = self._p_label(c, "", fg=GOLD, size=8, bold=True)
        q = self._p_label(c, "", size=10)
        v, e = self._p_entry(c, 18)
        fb = self._p_label(c, "", fg=GREY, size=8)
        sol = self._p_label(c, "", fg=INK, size=9)
        row = tk.Frame(c, bg=c.cget("bg"))
        row.pack(fill="x", padx=14, pady=(2, 6))
        score = self._p_label(c, "", fg=GREY, size=8)
        self._p_label(c, note, fg=GREY, size=7, pady=(0, 10))
        S = {"p": None, "done": False}

        def show_score():
            score.config(text="%d / %d right · streak %d · best streak %d" % (bs["right"], bs["tries"], bs["streak"], bs["best"]))

        def new():
            p = gen()
            S["p"], S["done"] = p, False
            tag = " · %s" % ("P1 style" if p.get("p") == 1 else "P2 style") if "p" in p else ""
            top.config(text=p["topic"] + tag)
            q.config(text=p["q"])
            v.set("")
            fb.config(text="Type your answer%s, then Enter." % (" (in %s)" % p["unit"] if p.get("unit") else ""), fg=GREY)
            sol.config(text="")
            e.focus_set()
            self.teach_say("Try this one~", 2, board=p["topic"].split(":")[-1].strip())
            show_score()

        def check(_e=None):
            p = S["p"]
            if S["done"]:
                new()
                return
            got = num_answer(v.get())
            if got is None:
                fb.config(text="Type a number (like 0.25, 3/4, 2.5e-3)~")
                return
            S["done"] = True
            bs["tries"] += 1
            if close_enough(got, p["a"]):
                bs["right"] += 1
                bs["streak"] += 1
                bs["best"] = max(bs["best"], bs["streak"])
                fb.config(text="正解! Correct~ (Enter for the next one)", fg=GOLD)
                self.teach_say("Yatta! %d in a row~" % bs["streak"] if bs["streak"] > 1 else "Yatta! Correct~", 2.5, happy=True)
            else:
                bs["streak"] = 0
                fb.config(text="Not quite: the answer is %s %s. Working below. (Enter for a new one)" % (
                    fmt_num(round(p["a"], 4)), p.get("unit", "")), fg=GREY)
                sol.config(text=p["sol"])
                self.nb_mistake({"q": p["q"], "a": p["sol"]}, False, key)
                self.teach_say("Let's look at the working together~", 3)
            self.life_save()
            show_score()
        e.bind("<Return>", check)
        self.tt_btn(row, "Check", check, bg=ORANGE, fg=ON_ACC, size=9, padx=10, pady=1).pack(side="left")
        self.tt_btn(row, "Show working", lambda: S["p"] and sol.config(text=S["p"]["sol"]), bg=FIELD, size=9, padx=10,
                    pady=1).pack(side="left", padx=6)
        self.tt_btn(row, "New problem", new, bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        new()

    # ---- 仏語 French: vocab drill by theme (Leitner boxes) ----------------------------------------------
    def practice_french(self, c, key):
        bs = self.life["book_state"].setdefault("french", {"theme": "All", "dir": "en-fr", "right": 0})
        V = self.life["fr_vocab"]
        bg = c.cget("bg")
        th = tk.Frame(c, bg=bg)
        th.pack(fill="x", padx=14, pady=(0, 4))
        tv = tk.StringVar(value=bs.get("theme", "All"))
        names = ["All"] + list(FR_VOCAB)
        short = {"All": "Tout", "Identités": "Identités", "Expériences": "Expériences", "Ingéniosité humaine": "Ingéniosité",
                 "Organisation sociale": "Org. sociale", "Partager la planète": "Planète"}
        for i, n in enumerate(names):
            if i in (0, 3):
                r = tk.Frame(th, bg=bg)
                r.pack(fill="x", pady=1)
            tk.Radiobutton(r, text=short[n], value=n, variable=tv, indicatoron=False, bg=FIELD, fg=INK, selectcolor="#d65f8f",
                           activebackground=FIELD, relief="flat", bd=0, padx=6, pady=2, font=(FONT_UI, 8, "bold"),
                           command=lambda: (bs.__setitem__("theme", tv.get()), new())).pack(side="left", padx=(0, 4))
        dv = tk.StringVar(value=bs.get("dir", "en-fr"))
        dr = tk.Frame(c, bg=bg)
        dr.pack(fill="x", padx=14, pady=(2, 4))
        for val, lab in (("en-fr", "English → French"), ("fr-en", "French → English")):
            tk.Radiobutton(dr, text=lab, value=val, variable=dv, indicatoron=False, bg=FIELD, fg=INK, selectcolor=GOLD,
                           activebackground=FIELD, relief="flat", bd=0, padx=6, pady=1, font=(FONT_UI, 8),
                           command=lambda: (bs.__setitem__("dir", dv.get()), new())).pack(side="left", padx=(0, 4))
        prompt = self._p_label(c, "", size=13, bold=True, pady=(6, 0))
        hint = self._p_label(c, "", fg=GREY, size=8)
        v, e = self._p_entry(c, 26)
        fb = self._p_label(c, "", fg=GREY, size=9)
        row = tk.Frame(c, bg=bg)
        row.pack(fill="x", padx=14, pady=(2, 6))
        prog = self._p_label(c, "", fg=GREY, size=8, pady=(0, 10))
        S = {"w": None, "done": False, "last": None}

        def pool():
            t = bs.get("theme", "All")
            items = []
            for n, ws in FR_VOCAB.items():
                if t in ("All", n):
                    items += [(n, fr, en) for fr, en in ws]
            return items

        def progress():
            p = pool()
            known = sum(1 for _, fr, _e in p if V.get(fr, 0) >= 3)
            prog.config(text="Learned %d / %d words in %s (a word counts after 3 right in a row)" % (
                known, len(p), short[bs.get("theme", "All")]))

        def new():
            p = pool()
            p2 = [x for x in p if x[1] != S["last"]] or p
            low = min(V.get(x[1], 0) for x in p2)
            cand = [x for x in p2 if V.get(x[1], 0) <= low + 1]
            w = random.choice(cand)
            S["w"], S["done"], S["last"] = w, False, w[1]
            if bs.get("dir") == "fr-en":
                prompt.config(text=w[1])
                hint.config(text="%s · what does it mean in English?" % w[0])
            else:
                prompt.config(text=w[2])
                hint.config(text="%s · in French (with le/la if it's a noun)" % w[0])
            v.set("")
            fb.config(text="")
            e.focus_set()
            self.teach_say(None, 1.5, board=w[0])
            progress()

        def check(_e=None):
            if S["done"]:
                new()
                return
            n, fr, en = S["w"]
            if not v.get().strip():
                return
            S["done"] = True
            if bs.get("dir") == "fr-en":
                ok = any(fr_norm(v.get()) == fr_norm(a) for a in re.split(r"[,/]", re.sub(r"\(.*?\)", "", en))) or \
                    fr_norm(v.get()) == fr_norm(en)
                perfect = ok
            else:
                ok, perfect = fr_match(v.get(), fr)
            if ok:
                V[fr] = V.get(fr, 0) + 1
                bs["right"] = bs.get("right", 0) + 1
                fb.config(text=("Très bien~ " if perfect else "Oui! Watch the accents: ") + "%s = %s" % (fr, en), fg=GOLD)
                self.teach_say("Très bien!", 2, happy=True)
            else:
                V[fr] = 0
                fb.config(text="Presque~ %s = %s" % (fr, en), fg=GREY)
                self.nb_mistake({"q": "French: %s" % en, "a": fr}, False, "french")
                self.teach_say("%s... say it with me: %s" % (en, fr), 3)
            self.life_save()
            progress()
        e.bind("<Return>", check)
        self.tt_btn(row, "Check", check, bg=ORANGE, fg=ON_ACC, size=9, padx=10, pady=1).pack(side="left")
        self.tt_btn(row, "Skip", new, bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=6)
        new()

    # ---- 心理 Psych: concept lens prompts + a research-methods quiz --------------------------------------
    def practice_psych(self, c, key):
        bg = c.cget("bg")
        head = self._p_label(c, "", fg=GOLD, size=8, bold=True)
        q = self._p_label(c, "", size=10)
        hint = self._p_label(c, "", fg=GREY, size=8)
        row = tk.Frame(c, bg=bg)
        row.pack(fill="x", padx=14, pady=(2, 10))
        S = {"p": None}

        def new():
            p = psy_prompt()
            S["p"] = p
            head.config(text="Concept: %s · Context: %s" % (p["concept"], p["context"]))
            q.config(text=p["q"])
            hint.config(text="%s: %s" % (p["concept"], p["hint"]))
            self.teach_say(None, 1.5, board=p["concept"].lower())
        self.tt_btn(row, "New prompt", new, bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        self.tt_btn(row, "Plan it with me", lambda: S["p"] and self.book_ask(
            "Help me plan an answer (not write it for me): " + S["p"]["q"], "exam"), bg=ORANGE, fg=ON_ACC, size=9, padx=10,
            pady=1).pack(side="left", padx=6)
        new()
        tk.Frame(c, bg=LINE, height=1).pack(fill="x", padx=14, pady=(0, 8))
        self._p_label(c, "研究法 · Research methods quiz", fg=GOLD, size=9, bold=True)
        mq = self._p_label(c, "", size=9)
        opts = tk.Frame(c, bg=bg)
        opts.pack(fill="x", padx=14)
        mfb = self._p_label(c, "", fg=GREY, size=8, pady=(4, 6))
        bs = self.life["book_state"].setdefault("psych", {"right": 0, "tries": 0})

        def mnew():
            for ch in opts.winfo_children():
                ch.destroy()
            term, dfn = random.choice(PSY_TERMS)
            wrong = random.sample([t for t, _ in PSY_TERMS if t != term], 3)
            ch_ = wrong + [term]
            random.shuffle(ch_)
            mq.config(text="Which term? “%s”" % dfn)
            mfb.config(text="%d / %d right" % (bs["right"], bs["tries"]), fg=GREY)

            def pick(t):
                bs["tries"] += 1
                if t == term:
                    bs["right"] += 1
                    mfb.config(text="正解! %s. (%d / %d) Next one coming~" % (term, bs["right"], bs["tries"]), fg=GOLD)
                    self.teach_say("Sugoi~", 1.5, happy=True)
                else:
                    mfb.config(text="That's %s; the answer was %s. (%d / %d)" % (t, term, bs["right"], bs["tries"]), fg=GREY)
                    self.nb_mistake({"q": "Psych methods: %s" % dfn, "a": term}, False, "psych")
                self.life_save()
                c.after(1600, lambda: opts.winfo_exists() and mnew())
            for i, t in enumerate(ch_):
                if i % 2 == 0:
                    r = tk.Frame(opts, bg=bg)
                    r.pack(fill="x", pady=1)
                self.tt_btn(r, t, lambda t=t: pick(t), bg=FIELD, size=8, padx=6, pady=0).pack(side="left", padx=(0, 4))
        mnew()
        tk.Frame(c, bg=LINE, height=1).pack(fill="x", padx=14, pady=(4, 8))
        self._p_label(c, "Class practicals (one per context)", fg=GOLD, size=9, bold=True)
        self._p_label(c, "\n".join("• %s: %s (%s)" % p for p in PSY_PRACTICALS), size=8)
        self._p_label(c, "Psychology follows the NEW guide (first exams 2027): 6 concepts, 4 contexts, 3 approaches, "
                         "research proposal IA.", fg=GREY, size=7, pady=(2, 10))

