        e.pack(side="left")
        tk.Label(row, text="kg", bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="left", padx=(4, 8))
        msg = tk.Label(c, text="", bg=bg, fg=GREY, font=(serif, 10, "italic"), anchor="w", justify="left", wraplength=320)

        def log(_e=None):
            t = v.get().strip().lower().replace(",", ".")
            m = re.match(r"^(\d{2,3}(?:\.\d)?)\s*(kg|lbs?|pounds)?$", t)
            if not m:
                msg.config(text="Type your weight like 68.5 (or 150 lb)")
                return
            kg = float(m.group(1)) * (0.4536 if (m.group(2) or "").startswith(("lb", "pound")) else 1)
