    # ---- food --------------------------------------------------------------------------------------
    def gym_food_today(self):
        return self.gym()["food"].setdefault(datetime.date.today().isoformat(), [])

    def gym_food_add(self, text, done=None):
        """Estimate a meal: the built-in food table first, then the smart brain for anything it doesn't know."""
        items, unknown = food_estimate(text)
        F = self.gym_food_today()
        for lab, kcal, prot, _ in items:
            F.append({"t": lab, "kcal": kcal, "p": prot, "src": "table"})
        G = self.gym()
        for k_ in sorted(G["food"])[:-60]:
            G["food"].pop(k_, None)
        self.life_save()
        if not unknown:                                    # done() is only called when the brain had to help
            return sum(i[1] for i in items), []
        model = self.cfg.get("llm_model") or "llama3.2:3b"

        def job():
            names = brain_names() if self.cfg.get("llm_enabled", True) or online_ready() else None
            if not names:
                return None
            m = pick_model(names, model)
            j = _ollama_json("/api/chat", {"model": m, "stream": False, "format": "json", "online": True,
                                           "options": {"temperature": 0.1, "num_predict": 400}, "messages": [
                {"role": "system", "content": "You estimate food energy for a food diary. Use typical portion sizes when "
                                              "none is given. Be realistic, not low. Reply ONLY JSON: {\"items\": [{\"food\": "
                                              "\"name and portion\", \"kcal\": number, \"protein_g\": number}]}"},
                {"role": "user", "content": "; ".join(unknown)}]}, 120)
            d = json.loads(json_latex_fix((j.get("message") or {}).get("content") or "{}"))
            out = []
            for it in (d.get("items") or [])[:12]:
                try:
                    k = max(0, min(3000, int(float(it.get("kcal") or 0))))
                    p = max(0.0, min(200.0, float(it.get("protein_g") or 0)))
                except (TypeError, ValueError):
                    continue
                out.append((clip(str(it.get("food") or "food").capitalize(), 60), k, round(p, 1)))
            return out

        def fin(res, err):
            if res:
                for lab, k, p in res:
                    self.gym_food_today().append({"t": lab + " (estimate)", "kcal": k, "p": p, "src": "brain"})
                self.life_save()
            self.gym_refresh()
            if done:
                done(None if res else ("I couldn't estimate: %s. Try a simpler name or a weight, like '150 g rice'."
                                       % ", ".join(clip(u, 30) for u in unknown)))
        self.bg(job, fin)
        return sum(i[1] for i in items), unknown

