# portion words -> grams (or ml) for one of them, when a food is looked up online
_PORTION_G = {"cup": 200, "cups": 200, "bowl": 220, "bowls": 220, "katori": 150, "katoris": 150, "plate": 330,
              "plates": 330, "glass": 250, "glasses": 250, "mug": 300, "tbsp": 15, "tablespoon": 15, "tablespoons": 15,
              "tsp": 5, "teaspoon": 5, "teaspoons": 5, "handful": 30, "handfuls": 30, "scoop": 30, "scoops": 30,
              "slice": 30, "slices": 30, "can": 330, "cans": 330, "bottle": 500, "bottles": 500, "packet": 60,
              "packets": 60, "pack": 60, "packs": 60}
FOOD_ONLINE = {"usda": "https://api.nal.usda.gov/fdc/v1/foods/search",
               "off": "https://world.openfoodfacts.org/cgi/search.pl"}
if os.environ.get("FOX_FOOD_BASE"):                      # testing hook: a local stub
    FOOD_ONLINE = {"usda": os.environ["FOX_FOOD_BASE"] + "/usda", "off": os.environ["FOX_FOOD_BASE"] + "/off"}
FOOD_CACHE = os.path.join(DATA_DIR, "food_cache.json")


def _num(v):
    """A number from JSON or text ('43,4' -> 43.4), or None."""
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(_clean_num(str(v)).replace(",", "").strip())
    except (TypeError, ValueError):
        return None


def food_portion(part):
    """'2 bowls of chicken biryani' -> ('chicken biryani', grams or None, count, portion word)."""
    low = _clean_num(part.lower().strip())
    grams, cnt, unit = None, 1.0, ""
    m = re.search(r"(\d+(?:\.\d+)?)\s*(kg|g|grams?|gm|gms|ml|l|litres?|liters?|oz)\b", low)
    if m:
        v = float(m.group(1))
        u = m.group(2)
        grams = v * (1000 if u in ("kg", "l") or u.startswith(("litre", "liter")) else 28.35 if u == "oz" else 1)
        low = low[:m.start()] + " " + low[m.end():]
    m = re.search(r"(?<![\d.])(\d+(?:\.\d+)?|\d+/\d+)(?![\d.])", low)
    if m:
        v = m.group(1)
        cnt = float(v.split("/")[0]) / float(v.split("/")[1]) if "/" in v else float(v)
        if not 0 < cnt <= 20:
            cnt = 1.0
        low = low[:m.start()] + " " + low[m.end():]
    else:
        for w_, v in sorted(_FOOD_NUM.items(), key=lambda kv: -len(kv[0])):
            if re.search(r"\b%s\b" % re.escape(w_), low):
                cnt = v
                low = re.sub(r"\b%s\b" % re.escape(w_), " ", low, 1)
                break
    m = re.search(r"\b(%s)\b" % "|".join(sorted(map(re.escape, _PORTION_G), key=len, reverse=True)), low)
    if m:
        unit = m.group(1)
        low = low[:m.start()] + " " + low[m.end():]
    size = 1.0
    if re.search(r"\b(?:large|big|huge)\b", low):
        size = 1.4
    elif re.search(r"\bsmall\b", low):
        size = 0.7
    name = re.sub(r"\b(?:of|a|an|the|some|large|big|huge|small|medium|piece|pieces|pcs|serving|servings|portion|"
                  r"portions|homemade|home made|for (?:breakfast|lunch|dinner)|i ate|ate|had)\b", " ", low)
    name = re.sub(r"[^a-z' &-]", " ", name)
    name = re.sub(r"\s+", " ", name).strip()
    if grams is None and unit:
        grams = _PORTION_G[unit] * cnt * size
    elif grams is not None and cnt and re.search(r"\beach\b", part.lower()):
        grams *= cnt
    return name, grams, (cnt * size if grams is None else cnt), unit


def _food_cache():
    try:
        with open(FOOD_CACHE, encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return {}


def _food_ok(k, p):
    """Believable per-100 g values: protein can't give more energy than the food has."""
    return k is not None and p is not None and 0 <= k <= 920 and 0 <= p <= 95 and p * 4 <= k * 1.12 + 4


def _food_score(name, words):
    nw = set(re.findall(r"[a-z]+", name.lower()))
    hit = sum(1 for w_ in words if w_ in nw or (w_.endswith("s") and w_[:-1] in nw))
    return hit / float(len(words) or 1) - 0.02 * max(0, len(nw) - len(words))


def food_online(name, timeout=9):
    """Look a food up on the internet (free, no account): USDA FoodData Central (DEMO_KEY), then Open Food Facts.
    Returns dict(name, kcal100, p100, serving, src) or None. Answers are cached on this PC."""
    key = re.sub(r"\s+", " ", (name or "").lower()).strip()
    if len(key) < 2:
        return None
    cache = _food_cache()
    if key in cache:
        return cache[key] or None
    words = [w_ for w_ in re.findall(r"[a-z]+", key) if w_ not in ("with", "and", "of", "in")]
    best, best_sc = None, 0.45
    try:                                                     # USDA: generic foods and dishes, per 100 g
        url = "%s?api_key=DEMO_KEY&pageSize=12&query=%s&dataType=%s" % (
            FOOD_ONLINE["usda"], _q(key), _q("Survey (FNDDS),SR Legacy,Foundation"))
        j = http_json(url, timeout)
        for f in (j.get("foods") or [])[:12]:
            k = p = None
            for n in f.get("foodNutrients") or []:
                nm, un = str(n.get("nutrientName", "")), str(n.get("unitName", "")).upper()
                if nm.startswith("Energy") and un == "KCAL" and k is None:
                    k = _num(n.get("value"))
                elif nm == "Protein" and p is None:
                    p = _num(n.get("value"))
            if not _food_ok(k, p):
                continue
            desc = str(f.get("description") or "")
            sc = _food_score(desc, words) + (0.05 if f.get("dataType") == "Survey (FNDDS)" else 0)
            if sc > best_sc:
                best, best_sc = {"name": desc.capitalize()[:60], "kcal100": round(k, 1), "p100": round(p, 1),
                                 "serving": None, "src": "USDA"}, sc
    except Exception:
        pass
    if best_sc < 0.99:
        try:                                                 # Open Food Facts: packaged foods (Indian brands too)
            url = "%s?search_terms=%s&search_simple=1&action=process&json=1&page_size=15&fields=%s" % (
                FOOD_ONLINE["off"], _q(key), "product_name,brands,nutriments,serving_quantity")
            j = http_json(url, timeout)
            for pr in (j.get("products") or [])[:15]:
                nu = pr.get("nutriments") or {}
                k = _num(nu.get("energy-kcal_100g"))
                if k is None and _num(nu.get("energy_100g")) is not None:
                    k = _num(nu.get("energy_100g")) / 4.184
                p = _num(nu.get("proteins_100g"))
                if not _food_ok(k, p) or not pr.get("product_name"):
                    continue
                nm = str(pr["product_name"])
                sc = _food_score(nm, words) - 0.04
                if sc > best_sc:
                    sv = _num(pr.get("serving_quantity"))
                    best, best_sc = {"name": (nm + (" (%s)" % pr["brands"].split(",")[0] if pr.get("brands") else ""))[:60],
                                     "kcal100": round(k, 1), "p100": round(p, 1),
                                     "serving": sv if sv and 5 <= sv <= 800 else None, "src": "Open Food Facts"}, sc
        except Exception:
            pass
    if best is not None or True:
        cache[key] = best
        if len(cache) > 400:
            for k_ in list(cache)[:100]:
                cache.pop(k_, None)
        try:
            os.makedirs(DATA_DIR, exist_ok=True)
            with open(FOOD_CACHE + ".tmp", "w", encoding="utf-8") as f:
                json.dump(cache, f)
            os.replace(FOOD_CACHE + ".tmp", FOOD_CACHE)
        except Exception:
            pass
    return best


def food_lookup_part(part):
    """One part of a meal looked up online -> (label, kcal, protein, info dict) or None."""
    name, grams, cnt, unit = food_portion(part)
    if not name:
        return None
    hit = food_online(name)
    if not hit:
        return None
    if grams is None:
        grams = (hit.get("serving") or 100.0) * cnt
    grams = max(1.0, min(2500.0, grams))
    k_, p_ = food_sane(hit["kcal100"] * grams / 100.0, hit["p100"] * grams / 100.0)
    lab = "%s (%dg · %s)" % (part.strip().capitalize()[:40], int(round(grams)), hit["src"])
    return lab, k_, p_, {"g": round(grams), "k100": hit["kcal100"], "p100": hit["p100"], "src": hit["src"],
                         "match": hit["name"]}


