def _note(n):
    return _NOTE.get(n) or 440.0 * 2 ** ((("C C# D D# E F F# G G# A A# B".split().index(n[:-1])) - 9) / 12.0 + int(n[-1]) - 4)


def extra_sound_parts(kind):
    """zenko14's interaction sounds (koto, bells, wood, bamboo...) on top of the older ones."""
    if kind == "i_koto_up":
        return [(i * 0.07, _koto(_note(n), 0.5, 0.7, i + 2), 0.45) for i, n in enumerate(("D5", "E5", "A5"))]
    if kind == "i_koto_down":
        return [(i * 0.08, _koto(_note(n), 0.5, 0.6, i + 5), 0.45) for i, n in enumerate(("B5", "A5", "E5"))]
    if kind == "i_koto_trill":
        return [(i * 0.045, _koto(_note(("A5", "B5")[i % 2]), 0.25, 0.8, i), 0.3) for i in range(6)]
    if kind == "i_suzu_roll":
        return _suzu(0.0, 7, 13)
    if kind == "i_suzu_one":
        return _suzu(0.0, 2, 21) + [(0.12, _koto(_note("E6"), 0.4, 0.8), 0.25)]
    if kind == "i_furin2":
        return _furin(0.0, 2637.0, 0.38) + _furin(0.18, 1975.5, 0.25)
    if kind == "i_mokugyo":                 # the round wooden temple block
        return [(i * 0.16, _tap(620 + 40 * i, 0.09), 0.7) for i in range(2)]
    if kind == "i_hyoshigi":                # two wooden clappers
        return [(0.0, _tap(1900, 0.05), 0.7), (0.11, _tap(2100, 0.05), 0.6)]
    if kind == "i_bubble":
        return [(i * 0.06, _pop(500 + 160 * i, 1300 + 220 * i, 0.06), 0.4) for i in range(3)]
    if kind == "i_sparkle":
        return [(i * 0.05, _bell(_note(n), 0.5, ((1, 0.5), (2.76, 0.18)), 0.25, i), 0.28)
                for i, n in enumerate(("A6", "E6", "B5", "E6"))]
    if kind == "i_shamisen":                # a dry, twangy pluck: koto with less brightness and a quick slide
        return [(0.0, _koto(_note("E5"), 0.35, 0.95, 9), 0.55), (0.1, _koto(_note("B5"), 0.45, 0.95, 4), 0.45)]
    if kind == "i_purr":                    # a soft, happy little rumble
        out, ph = [], 0.0
        for i in range(int(0.55 * SR)):
            t = i / float(SR)
            ph += 2 * math.pi * (92 + 6 * math.sin(t * 9)) / SR
            amp = (0.55 + 0.45 * math.sin(2 * math.pi * 24 * t)) * min(1.0, t / 0.05) * min(1.0, (0.55 - t) / 0.12)
            out.append(amp * (math.sin(ph) + 0.4 * math.sin(2 * ph)))
        return [(0.0, out, 0.5)]
    if kind == "i_flute":                   # a breathy bamboo flute (shakuhachi-ish) note
        rnd = random.Random(4)
        out, ph, lp = [], 0.0, 0.0
        for i in range(int(0.6 * SR)):
            t = i / float(SR)
            ph += 2 * math.pi * _note("A5") * (1 + 0.01 * math.sin(2 * math.pi * 5 * t)) / SR
            lp = lp * 0.8 + rnd.uniform(-1, 1) * 0.2
            env = min(1.0, t / 0.08) * min(1.0, (0.6 - t) / 0.2)
            out.append(env * (0.8 * math.sin(ph) + 0.15 * math.sin(2 * ph) + 0.35 * lp))
        return [(0.0, out, 0.4)]
    if kind == "i_taiko_tap":
        return [(0.0, _drum(150, 0.18), 0.6), (0.12, _tap(1500, 0.04), 0.3)]
    if kind == "i_chime_pair":
        return _arp(["E5", "B5"], step=0.12, dur=0.6, gain=0.45)
    return _extra_sound_parts_base(kind)


