def ib_count_words(text):
    """Words like a word processor counts them (numbers and hyphenated words count once)."""
    return len(re.findall(r"[A-Za-zÀ-ÿ0-9]+(?:[-'’][A-Za-zÀ-ÿ0-9]+|(?<=\d)[.,]\d+)*", text or ""))


