class _Ras:
    """A tiny RGB raster for painting pixel-art scenes (fast PNG out, no PIL needed)."""

    def __init__(self, w, h, col=(0, 0, 0)):
        self.w, self.h = w, h
        self.b = bytearray(bytes(col) * (w * h))

    def put(self, x, y, c, a=1.0):
        x, y = int(x), int(y)
        if 0 <= x < self.w and 0 <= y < self.h:
            i = (y * self.w + x) * 3
            b = self.b
            if a >= 1.0:
                b[i], b[i + 1], b[i + 2] = c[0], c[1], c[2]
            elif a > 0:
                b[i] = int(b[i] + (c[0] - b[i]) * a)
                b[i + 1] = int(b[i + 1] + (c[1] - b[i + 1]) * a)
                b[i + 2] = int(b[i + 2] + (c[2] - b[i + 2]) * a)

    def get(self, x, y):
        i = (int(y) * self.w + int(x)) * 3
        return self.b[i], self.b[i + 1], self.b[i + 2]

    def rect(self, x0, y0, x1, y1, c, a=1.0):
        for y in range(max(0, int(y0)), min(self.h, int(y1))):
            for x in range(max(0, int(x0)), min(self.w, int(x1))):
                self.put(x, y, c, a)

    def disc(self, cx, cy, r, c, a=1.0, sy=1.0):
        r2 = r * r
        for y in range(int(cy - r * sy) - 1, int(cy + r * sy) + 2):
            dy = (y + 0.5 - cy) / sy
            for x in range(int(cx - r) - 1, int(cx + r) + 2):
                dx = x + 0.5 - cx
                if dx * dx + dy * dy <= r2:
                    self.put(x, y, c, a)

    def poly(self, pts, c, a=1.0):
        ys = [p[1] for p in pts]
        n = len(pts)
        for y in range(max(0, int(min(ys))), min(self.h, int(max(ys)) + 1)):
            yc = y + 0.5
            xs = []
            for i in range(n):
                x0, y0 = pts[i]
                x1, y1 = pts[(i + 1) % n]
                if (y0 <= yc < y1) or (y1 <= yc < y0):
                    xs.append(x0 + (yc - y0) * (x1 - x0) / (y1 - y0))
            xs.sort()
            for k in range(0, len(xs) - 1, 2):
                for x in range(int(round(xs[k])), int(round(xs[k + 1]))):
                    self.put(x, y, c, a)

    def line(self, x0, y0, x1, y1, c, w=1.0, a=1.0):
        d = max(abs(x1 - x0), abs(y1 - y0), 1)
        steps = int(d * 1.5) + 1
        r = w / 2.0
        for i in range(steps + 1):
            t = i / float(steps)
            x, y = x0 + (x1 - x0) * t, y0 + (y1 - y0) * t
            if w <= 1.2:
                self.put(x, y, c, a)
            else:
                self.disc(x, y, r, c, a)

    def photo(self, zoom=1):
        img = tk.PhotoImage(data=base64.b64encode(self.png()))
        return img.zoom(zoom, zoom) if zoom > 1 else img

    def png(self):
        import zlib
        import struct
        row = self.w * 3
        raw = b"".join(b"\x00" + bytes(self.b[y * row:(y + 1) * row]) for y in range(self.h))

        def chunk(t, d):
            c = struct.pack(">I", len(d)) + t + d
            return c + struct.pack(">I", zlib.crc32(t + d) & 0xffffffff)
        png = b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", self.w, self.h, 8, 2, 0, 0, 0)) + \
            chunk(b"IDAT", zlib.compress(raw, 1)) + chunk(b"IEND", b"")
        return png


def _lerp3(a, b, t):
    t = max(0.0, min(1.0, t))
    return (int(a[0] + (b[0] - a[0]) * t), int(a[1] + (b[1] - a[1]) * t), int(a[2] + (b[2] - a[2]) * t))


_BAYER = [[0, 8, 2, 10], [12, 4, 14, 6], [3, 11, 1, 9], [15, 7, 13, 5]]


def _dith(x, y, a):
    """Ordered-dither test: True when a pixel at (x, y) should take a colour with coverage a (0..1)."""
    return a > (_BAYER[y & 3][x & 3] + 0.5) / 16.0


def _shade(c, f):
    return (max(0, min(255, int(c[0] * f))), max(0, min(255, int(c[1] * f))), max(0, min(255, int(c[2] * f))))


def garden_scene(w, h, stage, growth, health, grove=0, seed=7, lit=False):
    """zenko16: the Zen garden painted as pixel art. A quiet moonlit karesansui: misty blue mountains, a plastered
    temple wall with a tiled roof, pines and bamboo behind it, raked gravel that ripples around mossy rocks, a stone
    lantern, a water basin, a small still pond, and your tree on a moss island in the middle.
    No big flat colour blocks: everything is shaded in 3-4 tones with dithered edges.
    stage 0-8, growth 0-1 inside the stage, health 0-1. Returns (_Ras, layout dict)."""
    R = _Ras(w, h)
    rnd = random.Random(seed)
    hy = int(h * 0.50)                                        # foot of the wall = back edge of the gravel
    # ---- sky: deep indigo to a soft lavender haze (dithered bands, the classic pixel-art look) ----
    stops = [(0.0, (11, 13, 36)), (0.40, (24, 30, 70)), (0.72, (58, 64, 116)), (0.90, (104, 104, 152)),
             (1.0, (142, 136, 176))]
    sky_h = hy
    for y in range(sky_h):
        t = y / float(max(1, sky_h - 1))
        for k in range(len(stops) - 1):
            if stops[k][0] <= t <= stops[k + 1][0]:
                a0, c0 = stops[k]
                a1, c1 = stops[k + 1]
                f = (t - a0) / max(1e-6, (a1 - a0))
                break
        q = f * 5
        row = (y * w) * 3
        for x in range(w):
            ff = 1 if (q - int(q)) > (_BAYER[y & 3][x & 3] + 0.5) / 16.0 else 0
            col = _lerp3(c0, c1, (int(q) + ff) / 5.0)
            i = row + x * 3
            R.b[i], R.b[i + 1], R.b[i + 2] = col
    for _ in range(int(w * h / 330)):                         # stars, a few twinkle-crosses
        x, y = rnd.randrange(w), int(rnd.random() ** 1.8 * hy * 0.62)
        a = rnd.uniform(0.25, 0.85)
        R.put(x, y, (236, 236, 255), a)
        if a > 0.78 and rnd.random() < 0.35:
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                R.put(x + dx, y + dy, (200, 206, 255), 0.35)
    mx_, my_, mr = w * 0.79, h * 0.15, max(5.0, h * 0.062)    # the moon, with a dithered halo
    for y in range(int(my_ - mr * 3.4), int(my_ + mr * 3.4)):
        for x in range(int(mx_ - mr * 3.4), int(mx_ + mr * 3.4)):
            d = math.hypot(x + 0.5 - mx_, y + 0.5 - my_) / mr
            if 1.0 < d < 3.4 and 0 <= x < w and 0 <= y < h:
                a = (1 - (d - 1) / 2.4) ** 2
                R.put(x, y, (150, 152, 204), a * 0.22)
    R.disc(mx_, my_, mr, (238, 234, 216))
    R.disc(mx_ - mr * 0.12, my_ - mr * 0.12, mr * 0.86, (248, 246, 232))
    for cx_, cy_, cr in ((-0.32, -0.18, 0.2), (0.22, 0.30, 0.15), (0.34, -0.36, 0.09), (-0.05, 0.12, 0.07)):
        R.disc(mx_ + cx_ * mr, my_ + cy_ * mr, mr * cr, (220, 216, 200), 0.8)
    for k in range(4):                                        # long thin clouds drifting past the moon
        cy = my_ + (k - 1.5) * mr * 1.1 + rnd.uniform(-1.5, 1.5)
        x0 = rnd.uniform(w * 0.48, w * 0.72)
        L = rnd.uniform(w * 0.16, w * 0.34)
        for x in range(int(x0), int(min(w, x0 + L))):
            t = (x - x0) / L
            s = math.sin(math.pi * t)
            R.put(x, cy, (150, 150, 200), 0.40 * s)
            if s > 0.45:
                R.put(x, cy + 1, (44, 48, 96), 0.40 * s)

    # ---- mountains: three soft ridges, paler with distance, mist between them ----
    def ridge(base, amp, s, col, edge, snow=0.0):
        tops = []
        for x in range(w):
            top = base - amp * (0.55 * math.sin(x * 0.019 + s) + 0.30 * math.sin(x * 0.051 + 2.1 * s) +
                                0.15 * math.sin(x * 0.13 + s * 0.7))
            tops.append(top)
            for y in range(max(0, int(top)), hy + 1):
                c = col
                if y < top + 1.5:
                    c = edge
                elif snow and y < top + snow * (0.6 + 0.4 * math.sin(x * 0.4)) and top < base - amp * 0.35:
                    c = _lerp3(edge, (214, 212, 236), 0.6)
                R.put(x, y, c)
        return tops

    def mist(yc, hh, a0, col=(150, 150, 196)):
        for y in range(int(yc - hh), int(yc + hh) + 1):
            if not 0 <= y < h:
                continue
            a = a0 * (1 - abs((y - yc) / max(1.0, hh)))
            for x in range(w):
                aa = a * (0.75 + 0.25 * math.sin(x * 0.045 + y * 0.6))
                if _dith(x, y, aa * 1.6):
                    R.put(x, y, col, 0.55)
    # a tall, distant sacred peak on the left
    pk_x, pk_top = w * 0.27, hy - h * 0.33
    for y in range(int(pk_top), hy):
        t = (y - pk_top) / float(hy - pk_top)
        half = (0.02 + t * 0.9) * w * 0.25
        for x in range(int(pk_x - half), int(pk_x + half) + 1):
            col = _lerp3((104, 104, 156), (82, 84, 136), t)
            if x < pk_x - half + 1.2 or x > pk_x + half - 1.2:
                col = _lerp3(col, (130, 130, 178), 0.5)
            if t < 0.20 + 0.05 * math.sin(x * 0.9):
                col = _lerp3((222, 222, 240), (168, 168, 206), t * 3.5)
                if x > pk_x + 1:                               # shadow side of the snow
                    col = _shade(col, 0.86)
            R.put(x, y, col)
    mist(hy - h * 0.17, h * 0.05, 0.35)
    ridge(hy - h * 0.13, h * 0.05, 1.3, (74, 78, 128), (96, 98, 150))
    mist(hy - h * 0.09, h * 0.04, 0.30)
    ridge(hy - h * 0.07, h * 0.035, 3.1, (52, 58, 102), (70, 76, 122))
    # a small, dark pagoda far away on the right ridge (silhouette only)
    px_ = int(w * 0.90)
    pb = hy - h * 0.085
    for k in range(4):
        ww = max(3, int(w * (0.028 - k * 0.0045)))
        yb = pb - k * h * 0.03
        R.rect(px_ - ww // 2 + 1, yb - h * 0.022, px_ + ww // 2, yb, (40, 44, 78))
        R.poly([(px_ - ww * 0.8, yb - h * 0.022), (px_ + ww * 0.8, yb - h * 0.022), (px_ + ww * 0.35, yb - h * 0.034),
                (px_ - ww * 0.35, yb - h * 0.034)], (34, 38, 70))
    R.rect(px_, pb - h * 0.17, px_ + 1, pb - h * 0.12, (34, 38, 70))

    # ---- behind the wall: cloud-pruned pines and bamboo, as dark layered shapes ----
    wall_top = int(hy - h * 0.085)
    pine_d, pine_m, pine_l = (22, 36, 46), (30, 50, 58), (44, 70, 74)

    def cloud_pad(x, y, r, sy=0.45):
        R.disc(x, y + r * 0.18, r * 1.05, pine_d, sy=sy)
        R.disc(x - r * 0.1, y, r, pine_m, sy=sy)
        R.disc(x - r * 0.35, y - r * sy * 0.35, r * 0.55, pine_l, sy=sy)
    for k, (px0, ht) in enumerate(((0.06, 0.20), (0.40, 0.16), (0.63, 0.19))):
        bx = w * px0 + rnd.uniform(-4, 4)
        top = wall_top - h * ht
        R.line(bx, wall_top + 2, bx + w * 0.01, top + h * 0.03, (34, 28, 34), max(1.5, h * 0.012))
        for j in range(4):
            yy = top + j * h * ht * 0.24
            xx = bx + (w * 0.035 if j % 2 else -w * 0.03) * (0.6 + j * 0.15)
            R.line(bx + w * 0.005, yy + h * 0.02, xx, yy, (34, 28, 34), max(1.0, h * 0.006))
            cloud_pad(xx, yy, max(4.0, w * (0.035 - j * 0.003)))
    for k in range(9):                                        # bamboo grove on the far right
        bx = int(w * 0.75 + k * w * 0.024 + rnd.uniform(-2, 2))
        top = wall_top - h * rnd.uniform(0.14, 0.26)
        col = rnd.choice([(40, 70, 62), (48, 82, 70), (34, 60, 56)])
        for y in range(int(top), wall_top + 2):
            R.put(bx, y, col)
            R.put(bx + 1, y, _shade(col, 0.8))
            if (y - int(top)) % max(5, int(h * 0.04)) == 0:
                R.put(bx, y, _shade(col, 1.35))
                R.put(bx + 1, y, _shade(col, 1.1))
        for j in range(3):                                    # leaf sprays
            ly = top + j * h * 0.04 + rnd.uniform(0, 3)
            sg = 1 if (k + j) % 2 else -1
            for q in range(5):
                R.put(bx + sg * (q + 1), ly + q * 0.45, (58, 96, 80))
                R.put(bx + sg * (q + 1), ly + q * 0.45 + 1, (36, 64, 58), 0.8)

    # ---- the temple wall (tsuiji-bei): plaster with five lines and a tiled roof ----
    roof_h = max(3, int(h * 0.022))
    for y in range(wall_top, hy):
        t = (y - wall_top) / float(max(1, hy - wall_top))
        for x in range(w):
            c = _lerp3((112, 112, 138), (86, 86, 112), t)
            if _BAYER[y & 3][x & 3] > 13:
                c = _shade(c, 1.05)
            R.put(x, y, c)
    for k in range(5):                                        # the five horizontal lines of a temple wall
        yy = wall_top + roof_h + 2 + k * 2
        if yy < hy - 2:
            for x in range(w):
                R.put(x, yy, (150, 150, 172), 0.55)
    for x in range(0, w, max(6, int(w * 0.11))):              # posts
        R.rect(x, wall_top + roof_h, x + 1, hy, (70, 68, 92), 0.7)
    R.rect(0, wall_top - 1, w, wall_top + roof_h, (36, 38, 58))
    for x in range(w):                                        # tile ridge with a cool moonlit edge
        R.put(x, wall_top - 2, (64, 68, 100))
        if x % 3 == 0:
            R.put(x, wall_top + roof_h - 1, (24, 26, 42))
    for x in range(0, w, 3):
        R.put(x, wall_top + 1, (52, 56, 84))
    for y in range(hy - 3, hy):                               # soft shadow at the foot of the wall
        for x in range(w):
            R.put(x, y, (40, 40, 64), 0.25 + 0.15 * (y - hy + 3))

    # ---- raked gravel: parallel lines that ripple in rings around the rocks and the moss island ----
    cx = int(w * 0.50)
    tb = int(h * 0.79)                                        # where the trunk meets the ground
    isl = (cx, tb + h * 0.012, w * 0.16, h * 0.055)           # the moss island under the tree
    rocks = [(w * 0.29, h * 0.66, w * 0.050, h * 0.030, 1.0), (w * 0.335, h * 0.675, w * 0.024, h * 0.016, 0.55),
             (w * 0.70, h * 0.64, w * 0.040, h * 0.024, 0.85), (w * 0.115, h * 0.935, w * 0.030, h * 0.020, 0.7)]
    rings = [isl] + [(r[0], r[1], r[2] * 1.15, r[3] * 1.15) for r in rocks]
    pond = (w * 0.82, h * 0.86, w * 0.13, h * 0.058)
    sand_l, sand_m, sand_d = (164, 168, 198), (132, 136, 170), (100, 104, 140)
    gh = float(h - hy)
    for y in range(hy, h):
        u = (y - hy) / gh
        sp = 3.0 + 4.2 * u                                     # rake spacing grows toward you (perspective)
        par = (u ** 0.9) * gh / sp
        shade_f = 0.80 + 0.20 * u                              # gravel near the wall is in shadow
        for x in range(w):
            v = par + 0.18 * math.sin(x * 0.05)
            best = None
            for (ex, ey, erx, ery) in rings:
                e = math.hypot((x + 0.5 - ex) / erx, (y + 0.5 - ey) / ery)
                if e < 1.62:
                    dd = (e - 1.0) * ery * 1.5 / (3.0 + 4.2 * max(0.0, min(1.0, (ey - hy) / gh)))
                    if best is None or dd < best:
                        best = dd
            if best is not None and best >= 0:
                v = best
            f = v - math.floor(v)
            if f < 0.26:
                c = sand_d
            elif f < 0.40:
                c = sand_l
            else:
                c = sand_m
            i = (y * w + x) * 3
            c = _shade(c, shade_f)
            R.b[i], R.b[i + 1], R.b[i + 2] = c
    # a little edge of mossy ground along the bottom
    for x in range(w):
        top = h - h * (0.035 + 0.012 * math.sin(x * 0.07) + 0.006 * math.sin(x * 0.23))
        for y in range(int(top), h):
            c = (38, 66, 56) if y > top + 1 else (60, 96, 74)
            R.put(x, y, c)
            if _BAYER[y & 3][x & 3] > 12 and y > top + 1:
                R.put(x, y, (50, 84, 66))

    # ---- moss under the rocks and the island ----
    def moss(ex, ey, rx, ry):
        for y in range(int(ey - ry) - 1, int(ey + ry) + 2):
            for x in range(int(ex - rx) - 1, int(ex + rx) + 2):
                if not (0 <= x < w and 0 <= y < h):
                    continue
                e = math.hypot((x + 0.5 - ex) / rx, (y + 0.5 - ey) / ry)
                wob = 0.035 * math.sin(x * 0.7 + y * 1.1)
                if e < 1.0 + wob:
                    t = (y - (ey - ry)) / (2 * ry)
                    c = _lerp3((70, 112, 82), (34, 62, 52), t)
                    if e > 0.86 + wob:
                        c = (52, 88, 66) if t < 0.5 else (30, 52, 46)
                    elif _BAYER[y & 3][x & 3] > 11:
                        c = _shade(c, 1.18)
                    R.put(x, y, c)
    moss(*isl)
    for (rx_, ry_, rw_, rh_, sc) in rocks:
        moss(rx_, ry_ + rh_ * 0.35, rw_ * 1.05, rh_ * 0.75)
    # ---- rocks: three tones, a moonlit top edge and a moss cap ----
    for (rx_, ry_, rw_, rh_, sc) in rocks:
        top = ry_ - rh_ * 2.4 * sc
        pts = [(rx_ - rw_, ry_), (rx_ - rw_ * 0.85, ry_ - rh_ * 1.2 * sc), (rx_ - rw_ * 0.35, top),
               (rx_ + rw_ * 0.25, top + rh_ * 0.3), (rx_ + rw_ * 0.9, ry_ - rh_ * 1.0 * sc), (rx_ + rw_, ry_)]
        R.poly(pts, (78, 80, 98))
        R.poly([(rx_ + rw_ * 0.05, top + rh_ * 0.2), (rx_ + rw_ * 0.25, top + rh_ * 0.3), (rx_ + rw_ * 0.9, ry_ - rh_ * 1.0 * sc),
                (rx_ + rw_, ry_), (rx_ + rw_ * 0.2, ry_)], (56, 58, 76))
        R.poly([(rx_ - rw_ * 0.85, ry_ - rh_ * 1.2 * sc), (rx_ - rw_ * 0.35, top), (rx_ - rw_ * 0.1, top + rh_ * 0.5),
                (rx_ - rw_ * 0.6, ry_ - rh_ * 0.9 * sc)], (112, 114, 134))
        R.line(rx_ - rw_ * 0.85, ry_ - rh_ * 1.2 * sc, rx_ - rw_ * 0.35, top, (150, 152, 172))
        R.line(rx_ - rw_ * 0.35, top, rx_ + rw_ * 0.25, top + rh_ * 0.3, (134, 136, 158))
        for _ in range(int(rw_ * 1.2)):                        # moss on the top
            mx2 = rx_ + rnd.uniform(-rw_ * 0.6, rw_ * 0.2)
            my2 = top + rh_ * rnd.uniform(0.15, 0.6)
            R.put(mx2, my2, rnd.choice([(72, 116, 84), (96, 140, 96), (58, 96, 72)]))
        for k in range(int(rw_ * 2)):                          # contact shadow on the moss
            R.put(rx_ - rw_ + k, ry_ + 1, (24, 40, 36), 0.6)

    # ---- stepping stones from the front to the island ----
    for k in range(4):
        sx = cx - w * 0.10 + k * w * 0.032 + (k % 2) * 2
        sy = h * 0.975 - k * h * 0.035
        if sy < tb + h * 0.05:
            break
        R.disc(sx, sy + 1, max(3.0, w * 0.016), (70, 72, 92), sy=0.42)
        R.disc(sx, sy, max(3.0, w * 0.015), (124, 126, 146), sy=0.40)
        R.disc(sx - 1, sy - 1, max(2.0, w * 0.010), (150, 152, 170), sy=0.36)

    # ---- the still pond (right): dark water, a stone rim, the moon's reflection and lily pads ----
    pcx, pcy, prx, pry = pond
    for y in range(int(pcy - pry) - 2, int(pcy + pry) + 3):
        for x in range(int(pcx - prx) - 2, int(pcx + prx) + 3):
            if not (0 <= x < w and 0 <= y < h):
                continue
            d = math.hypot((x + 0.5 - pcx) / prx, (y + 0.5 - pcy) / pry)
            if d <= 1.0:
                t = (y - pcy + pry) / (2 * pry)
                col = _lerp3((26, 32, 64), (16, 20, 44), t)
                if d > 0.84:
                    col = (94, 96, 116) if y < pcy else (66, 68, 88)
                    if _BAYER[y & 3][x & 3] > 12:
                        col = _shade(col, 1.2)
                elif y < pcy - pry * 0.55 and _dith(x, y, 0.25):
                    col = (36, 44, 82)                         # the far bank reflected
                R.put(x, y, col)
    for k in range(5):                                        # moon reflection, broken into ripples
        yy = pcy - pry * 0.35 + k * 2
        ww = prx * (0.16 - k * 0.025)
        R.rect(pcx + prx * 0.25 - ww, yy, pcx + prx * 0.25 + ww, yy + 1, (220, 220, 236), 0.55 - k * 0.08)
    for lx, ly in ((-0.45, 0.25), (-0.15, 0.48), (0.55, 0.30)):
        R.disc(pcx + lx * prx, pcy + ly * pry, max(2.0, pry * 0.20), (46, 96, 72), sy=0.55)
        R.disc(pcx + lx * prx - 0.6, pcy + ly * pry - 0.5, max(1.2, pry * 0.12), (70, 128, 90), sy=0.5)
    R.put(pcx - 0.45 * prx, pcy + 0.25 * pry - 1, (238, 220, 232))  # a single white lotus bud
    R.put(pcx - 0.45 * prx + 1, pcy + 0.25 * pry - 1, (214, 190, 210))

    # ---- stone lantern (ishi-doro) on the left, softly lit ----
    lanterns = []
    lx, ly = w * 0.19, h * 0.80
    s = max(1.0, h / 190.0)
    st, st_l, st_d = (100, 102, 120), (140, 142, 160), (66, 68, 86)
    R.disc(lx, ly + 1, 9 * s, (24, 40, 36), 0.6, sy=0.3)
    R.rect(lx - 5 * s, ly - 2 * s, lx + 5 * s, ly, st_d)
    R.rect(lx - 5 * s, ly - 2 * s, lx - 3.5 * s, ly, st)
    R.rect(lx - 1.6 * s, ly - 12 * s, lx + 1.6 * s, ly - 2 * s, st)
    R.rect(lx + 0.6 * s, ly - 12 * s, lx + 1.6 * s, ly - 2 * s, st_d)
    R.rect(lx - 5 * s, ly - 14 * s, lx + 5 * s, ly - 12 * s, st)
    R.rect(lx - 5 * s, ly - 14 * s, lx + 5 * s, ly - 13.5 * s, st_l)
    R.rect(lx - 3.6 * s, ly - 20 * s, lx + 3.6 * s, ly - 14 * s, st)
    R.rect(lx - 2.2 * s, ly - 19 * s, lx + 2.2 * s, ly - 15 * s, (255, 206, 130))
    R.rect(lx - 1.0 * s, ly - 18 * s, lx + 1.0 * s, ly - 16 * s, (255, 236, 186))
    R.poly([(lx - 7.5 * s, ly - 20 * s), (lx + 7.5 * s, ly - 20 * s), (lx + 2.2 * s, ly - 25 * s), (lx - 2.2 * s, ly - 25 * s)],
           st)
    R.line(lx - 7.5 * s, ly - 20 * s, lx - 2.2 * s, ly - 25 * s, st_l)
    R.rect(lx - 7.5 * s, ly - 20 * s, lx + 7.5 * s, ly - 19.4 * s, st_d)
    R.rect(lx - 1 * s, ly - 27.5 * s, lx + 1 * s, ly - 25 * s, st)
    lanterns.append((lx, ly - 17 * s))
    rxl, ryl = w * 0.11, h * 0.06                              # a warm pool of light on the gravel
    for y in range(int(ly - ryl), int(ly + ryl) + 1):
        for x in range(int(lx - rxl), int(lx + rxl) + 1):
            if 0 <= x < w and hy <= y < h:
                d = ((x + 0.5 - lx) / rxl) ** 2 + ((y + 0.5 - ly) / ryl) ** 2
                if d < 1.0 and _dith(x, y, (1.0 - d) * 0.9):
                    R.put(x, y, (255, 196, 128), 0.16 * (1.0 - d) + 0.04)

    # ---- water basin (tsukubai) with a bamboo spout, front left ----
    bx, by = w * 0.065, h * 0.90
    br = max(5.0, w * 0.034)
    R.disc(bx, by + br * 0.5, br * 1.15, (24, 40, 36), 0.6, sy=0.35)
    R.disc(bx, by, br, (92, 94, 112), sy=0.62)
    R.disc(bx - br * 0.2, by - br * 0.12, br * 0.8, (118, 120, 138), sy=0.55)
    R.disc(bx, by - br * 0.22, br * 0.6, (22, 28, 56), sy=0.32)
    R.disc(bx + br * 0.15, by - br * 0.28, br * 0.16, (200, 204, 226), 0.6, sy=0.4)
    sx0 = bx - br * 2.2                                       # the spout (kakei)
    sy0 = by - br * 1.25
    R.line(sx0, sy0, bx - br * 0.25, sy0 + br * 0.2, (124, 140, 96), max(1.5, br * 0.22))
    R.line(sx0, sy0 - br * 0.08, bx - br * 0.25, sy0 + br * 0.1, (168, 182, 120), 1.0)
    R.rect(sx0 + br * 0.4, sy0 - 1, sx0 + br * 0.55, by + br * 0.3, (84, 98, 70))
    for k in range(int(br * 0.9)):                            # a thin stream of water
        R.put(bx - br * 0.22, sy0 + br * 0.25 + k * 0.9, (190, 210, 240), 0.55)

    # ---- grown trees join the grove: little sakura on the wall's far side ----
    for k in range(min(grove, 6)):
        gx = int(w * (0.20 + 0.11 * k)) if k < 3 else int(w * (0.58 + 0.07 * (k - 3)))
        gb = wall_top
        R.rect(gx, gb - h * 0.03, gx + 1, gb, (40, 30, 40))
        for d in range(5):
            R.disc(gx + rnd.uniform(-3, 3), gb - h * 0.04 + rnd.uniform(-2, 2), max(2.0, h * 0.014),
                   rnd.choice([(214, 168, 196), (232, 188, 210), (190, 140, 176)]))

    # ---- the tree ----
    tips = _garden_tree(R, cx, tb, w, h, stage, growth, health, seed)
    lay = {"tree": (cx, tb), "tips": tips, "lanterns": lanterns, "pond": pond, "horizon": hy, "ground": hy,
           "torii": (cx, wall_top), "moon": (mx_, my_, mr), "wall": wall_top, "basin": (bx, by, br),
           "breath": (cx, (wall_top - h * 0.30 + hy - h * 0.08) / 2.0)}
    return R, lay


def _garden_tree(R, cx, tb, w, h, stage, growth, health, seed):
    """Paint the tree (seed -> sprout -> bonsai in a pot -> a great sakura with a shimenawa rope)."""
    rnd = random.Random(seed * 31 + stage)
    s = h / 260.0
    wilt = 1.0 - max(0.0, min(1.0, health))
    bark, bark_d = _lerp3((92, 62, 52), (70, 66, 64), wilt * 0.6), _lerp3((58, 36, 34), (44, 42, 42), wilt * 0.6)
    leaf = _lerp3((86, 168, 104), (150, 128, 70), wilt * 0.9)
    leaf_d = _lerp3((44, 108, 74), (104, 82, 50), wilt * 0.9)
    pink = [_lerp3(c, (170, 140, 120), wilt * 0.85) for c in ((255, 196, 214), (246, 160, 192), (255, 226, 236), (226, 124, 168))]
    tips = []
    potted = 1 <= stage <= 5
    if stage == 0:                                            # a mound with a glowing seed
        R.disc(cx, tb, 14 * s, (56, 40, 34), sy=0.35)
        R.disc(cx, tb - 2 * s, 9 * s, (76, 54, 44), sy=0.3)
        for k, a in ((5.0, 0.12), (3.2, 0.2), (2.0, 0.4)):
            R.disc(cx, tb - 4 * s, k * s, (255, 216, 120), a * (0.4 + 0.6 * health))
        R.disc(cx, tb - 4 * s, 1.4 * s, (255, 244, 190))
        return [(cx, tb - 4 * s, 0)]
    if potted:                                                # a glazed indigo bonsai pot on a stone stand
        pw, ph_ = (16 + stage * 7) * s, (6 + stage * 1.6) * s
        R.rect(cx - pw * 0.7, tb + 2 * s, cx + pw * 0.7, tb + 6 * s, (84, 82, 98))
        R.rect(cx - pw * 0.6, tb + 6 * s, cx - pw * 0.45, tb + 12 * s, (70, 68, 84))
        R.rect(cx + pw * 0.45, tb + 6 * s, cx + pw * 0.6, tb + 12 * s, (70, 68, 84))
        R.poly([(cx - pw / 2, tb - ph_), (cx + pw / 2, tb - ph_), (cx + pw * 0.42, tb + 2 * s), (cx - pw * 0.42, tb + 2 * s)],
               (46, 66, 120))
        R.rect(cx - pw / 2 - 1, tb - ph_ - 1.5 * s, cx + pw / 2 + 1, tb - ph_ + 0.5 * s, (210, 172, 92))
        R.rect(cx - pw * 0.45, tb - ph_ + 2 * s, cx + pw * 0.45, tb - ph_ + 3 * s, (74, 98, 160))
        R.rect(cx - pw / 2, tb - ph_ - 0.5 * s - 1, cx + pw / 2, tb - ph_ + 0.5 * s, (60, 46, 40))
        base = tb - ph_
    else:
        R.disc(cx, tb + 2 * s, 46 * s, (30, 56, 48), sy=0.22)  # mossy roots
        for k in range(7):
            a = math.pi * (0.05 + 0.9 * k / 6.0)
            R.line(cx, tb, cx + math.cos(a) * 34 * s * (0.6 + rnd.random() * 0.5), tb + math.sin(a) * 4 * s,
                   bark_d, 2.4 * s)
        base = tb
    if stage == 1:                                            # a sprout with two leaves
        ht = (8 + growth * 6) * s
        R.line(cx, base, cx, base - ht, (110, 170, 90), max(1.0, 1.2 * s))
        droop = wilt * 4 * s
        for sg in (-1, 1):
            R.disc(cx + sg * 3.2 * s, base - ht + droop * 0.5, 2.6 * s, leaf, sy=0.55)
            R.disc(cx + sg * 3.6 * s, base - ht + droop * 0.5 - 0.6 * s, 1.4 * s, _lerp3(leaf, (220, 255, 200), 0.3), sy=0.5)
        return [(cx, base - ht, 0)]
    g = (stage - 2 + growth) / 6.0                            # 0 .. 1 from seedling to sacred tree
    trunk_len = (16 + 64 * g ** 0.8) * s
    thick = (1.6 + 10 * g) * s
    depth = 2 + min(5, int(stage * 0.7))
    droop = wilt * 0.35
    clusters = []

    def branch(x, y, ang, L, th, d):
        bend = droop * 0.6 * (1 - d / float(depth + 1))
        ang2 = ang + bend if math.cos(ang) >= 0 else ang - bend
        x1, y1 = x + math.cos(ang2) * L, y + math.sin(ang2) * L
        R.line(x, y, x1, y1, bark, max(1.0, th))
        if th > 2.5:
            R.line(x + th * 0.25, y, x1 + th * 0.2, y1, bark_d, max(1.0, th * 0.35))
        if d <= 0 or L < 3 * s:
            clusters.append((x1, y1, d))
            return
        n = 2 if rnd.random() < 0.7 else 3
        for k in range(n):
            spread = rnd.uniform(0.32, 0.62) * (1 if k % 2 else -1) + (rnd.uniform(-0.2, 0.2) if n == 3 and k == 2 else 0)
            branch(x1, y1, ang2 + spread, L * rnd.uniform(0.66, 0.8), th * 0.66, d - 1)
        if d <= 2:
            clusters.append((x1, y1, d))
    if potted:                                                # bonsai: a graceful S-curved trunk
        pts = [(cx, base)]
        for k in range(1, 5):
            t = k / 4.0
            pts.append((cx + math.sin(t * 3.2 + 0.4) * trunk_len * 0.22, base - trunk_len * t))
        for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
            R.line(x0, y0, x1, y1, bark, thick * (1.0 - 0.18 * (y0 - base) / -trunk_len if trunk_len else 1))
        R.line(pts[0][0] + thick * 0.25, pts[0][1], pts[-1][0] + thick * 0.1, pts[-1][1], bark_d, max(1.0, thick * 0.3))
        for k, (x, y) in enumerate(pts[1:], 1):
            for sg in ((-1, 1) if k >= 2 else (1,)):
                branch(x, y, -math.pi / 2 + sg * rnd.uniform(0.9, 1.3), trunk_len * 0.38 * (1.1 - k * 0.12), thick * 0.5,
                       max(1, depth - 2))
        branch(pts[-1][0], pts[-1][1], -math.pi / 2 + rnd.uniform(-0.2, 0.2), trunk_len * 0.25, thick * 0.45, max(1, depth - 2))
    else:
        branch(cx, base, -math.pi / 2 + rnd.uniform(-0.06, 0.06), trunk_len * 0.55, thick, depth)
    keep = 0.35 + 0.65 * health
    blossom = stage >= 6 or (stage == 5 and growth > 0.4)
    rr0 = (2.4 + 5.0 * g) * s * (0.55 + 0.45 * health)
    if blossom and stage >= 6 and clusters:                   # fill the inside of the crown too, not just the rim
        xs = [c[0] for c in clusters]
        ys = [c[1] for c in clusters]
        top, mid = min(ys), (min(xs) + max(xs)) / 2.0
        for _ in range(len(clusters) // 2):
            a = rnd.choice(clusters)
            t = rnd.uniform(0.25, 0.8)
            clusters.append((mid + (a[0] - mid) * t, a[1] + (base - trunk_len * 0.75 - a[1]) * t * 0.5, 3))
        clusters.sort(key=lambda c: (c[1], c[0]))
    for (x, y, d) in clusters:
        rr = rr0 * rnd.uniform(0.65, 1.15)
        if rnd.random() > keep:
            continue
        if potted and not blossom:                            # bonsai foliage: flat, layered pads
            R.disc(x, y + 1, rr * 1.5, leaf_d, sy=0.5)
            R.disc(x - rr * 0.2, y - rr * 0.15, rr * 1.25, leaf, sy=0.45)
            R.disc(x - rr * 0.5, y - rr * 0.35, rr * 0.6, _lerp3(leaf, (210, 240, 190), 0.35), sy=0.4)
            tips.append((x, y, d))
            continue
        cols = pink if blossom else [leaf, leaf_d, _lerp3(leaf, (210, 240, 190), 0.3)]
        if stage == 5 and blossom:                            # buds: mostly green with pink dots
            R.disc(x, y, rr, leaf_d)
            for _ in range(4):
                R.disc(x + rnd.uniform(-rr, rr), y + rnd.uniform(-rr, rr), max(1.0, rr * 0.25), pink[1])
            tips.append((x, y, d))
            continue
        R.disc(x + rr * 0.25, y + rr * 0.25, rr * 1.05, cols[-1] if blossom else leaf_d)
        R.disc(x, y, rr, cols[0])
        for _ in range(3):
            R.disc(x + rnd.uniform(-rr, rr) * 0.7, y + rnd.uniform(-rr, rr) * 0.7, rr * 0.45, rnd.choice(cols[:3]))
        R.disc(x - rr * 0.35, y - rr * 0.35, rr * 0.35, cols[2] if blossom else _lerp3(leaf, (220, 255, 210), 0.4))
        if blossom:                                           # loose petals at the edge, and a few shadowy gaps
            for _ in range(5):
                a = rnd.uniform(0, 6.283)
                R.put(x + math.cos(a) * rr * 1.25, y + math.sin(a) * rr * 1.2, cols[2])
            R.put(x + rr * 0.3, y + rr * 0.1, _lerp3(cols[3], (60, 30, 50), 0.4))
            R.put(x + rr * 0.32, y + rr * 0.12 + 1, _lerp3(cols[3], (60, 30, 50), 0.4))
        tips.append((x, y, d))
    if blossom and stage >= 6:                                # petals that already fell on the moss
        for _ in range(int(40 * health) + 6):
            R.put(cx + rnd.gauss(0, 30 * s), tb + rnd.uniform(-3, 9) * s, rnd.choice(pink[:3]), 0.85)
    if stage >= 8:                                            # sacred tree: a shimenawa rope with zigzag shide
        ry = base - trunk_len * 0.22
        rw = thick * 0.75
        for x in range(int(cx - rw), int(cx + rw) + 1):
            t = (x - cx + rw) / (2 * rw)
            yy = ry + math.sin(math.pi * t) * 2 * s
            R.rect(x, yy, x + 1, yy + 2.4 * s, (226, 196, 120))
            if int(x) % 3 == 0:
                R.put(x, yy + 1, (170, 140, 80))
        for k in (-0.5, 0.0, 0.5):
            sx = cx + k * rw
            for j in range(4):
                R.rect(sx + (j % 2) * 1.5 * s, ry + 2.5 * s + j * 2 * s, sx + (j % 2) * 1.5 * s + 2 * s, ry + 4 * s + j * 2 * s,
                       (250, 250, 244))
    return tips


class FoxBuddy(ZenkoGym, ZenkoBooks, ZenkoStudy, ZenkoLife, ZenkoExtras):
    def __init__(self):
        make_dpi_aware()
        self.cfg = load_config()
        online_set(self.cfg)
        apply_theme(self.cfg.get("theme", "snow"))
        self.pal = self.make_pal()
        self.root = tk.Tk()
        self.style_menus()
        set_ui_font(self.root, self.cfg.get("app_font", ""))
        self.root.title(APP_NAME)
        self.root.overrideredirect(True)
        self.root.attributes("-topmost", True)
        try:
            self.root.attributes("-transparentcolor", KEY)
        except tk.TclError:
            pass
        self.root.config(bg=KEY)

        self.U = dpi_scale()
        SOUND["on"] = bool(self.cfg.get("sound", True))
        SOUND["ui"] = bool(self.cfg.get("ui_sounds", True))
        SOUND["vol"] = int(self.cfg.get("sound_volume", 2) or 2)
        prepare_sounds()
        prepare_voice_clips()
        for cls in ("Checkbutton", "Radiobutton"):
            self.root.bind_class(cls, "<ButtonRelease-1>", lambda e: ui_sound("toggle"), "+")
        self.compute_dims()

        self.canvas = tk.Canvas(self.root, width=self.W, height=self.H, bg=KEY,
                                highlightthickness=0, bd=0)
        self.canvas.pack()
        self.make_fox_items()

        self.images = {}
        self.orb_imgs = {}
        self.motes = []
        self._tails_n = (0.0, 3)
        self.session = None
        self.mood_override = None
        self.mood_until = 0.0
        self.sleeping = False
        self.dist_run = 0.0
        self.alerted = False
        self.level = 0
        self.last_nag = 0.0
        self.passive_run = 0.0
        self.last_suggest = -9999.0
        self.last_tick = time.monotonic()
        self.next_blink = time.monotonic() + 3
        self.next_ear, self.ear_until = time.monotonic() + 5, 0.0
        self.next_lick, self.lick_until = time.monotonic() + 14, 0.0
        self.blink_until = 0.0
        self.bubble_job = None
        self._bub = None
        self.dialog = None
        self.drag = None

        self.tt = load_tt()
        self.tt_win = None
        self.tt_day = 0
        self.announced = set()
        self._tt_last = 0.0
        self.chat = None
        self.chat_hist = []
        self.chat_log = []
        self.hub = None
        self.tt_W, self.tt_maxh = 552, 330
        self.ext_q = queue.Queue()
        self.voice = LocalVoice() if "LocalVoice" in globals() else VoiceEngine()
        self.speaker = Speaker()
        self.spotify = Spotify(self.cfg.get("spotify_client_id", ""))
        self.key_state = {}
        self.voice_pending = False
        self.voice_mode = "chat"
        self.voice_reply_until = 0.0
        self.screen_busy = False
        self.listening_ui = False
        self.music_playing = False
        self.hub_music = None
        self.music_now = None
        self.music_polling = False
        self.last_song = None
        self.player = None             # what the belly tablet shows (from the Spotify window and/or account)
        self.song_memory = None        # last song name seen (Spotify hides it while paused)
        self.tab_flash = (None, 0.0)
        self._tab_key = None
        self.brk = None
        self.active_run = 0.0
        self.last_break_nag = -9999.0
        self.warned = False
        self._belly_key = None
        self.llm_q = queue.Queue()
        self.llm_busy = False
        self.llm_hist = []
        self._chat_miss = None
        self._llm_text = ""
        self.web_q = queue.Queue()
        self.web_busy = False
        self.brain_win = None
        self.extras_init()
        self.life_init()
        self.study_init()
        self.books_init()
        self.place_window()
        self.bind_events()
        self.build_menu()
        self.animate()
        self.tick()
        self.poll_llm()
        self.poll_web()
        self.poll_ext()
        self.root.after(1500, self.vv_autostart)
        self.hotkey_loop()
        self.root.after(3000, self.music_poll)
        self.root.after(1200, self.player_poll)
        self.battery, self.batt_warned, self._batt_key = None, set(), None
        self.dl_review, self.last_file, self.dl_body, self.dl_status_lab = None, None, None, None
        self.root.after(1500, self.battery_tick)
        self.root.after(15000, self.deadline_reminders)
        self.root.after(800, lambda: drop_files_hook(self.root, self.on_files_dropped))
        self.keep_on_top()
        beep("hello")
        if self.cfg.get("open_hub_on_start", True):
            self.root.after(250, self.open_hub)          # zenko20: the window comes up sooner
        if self.user_short():
            self.say("%s Hi %s. Double-click me to focus, or middle-click to chat." % (self.catchphrase(), self.user_short()), 8)
        else:
            self.say("%s I'm %s, Inari's little focus fox. Tell me your name in the 'You' tab, then double-click me to focus."
                     % (self.catchphrase(), self.fox_name()), 9)

    # ---- window -----------------------------------------------------------------
    def place_window(self):
        l, t, r, b = work_area(self.root)
        x, y = self.cfg.get("x"), self.cfg.get("y")
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        if x is None or y is None or not (-self.W < x < sw) or not (0 <= y < sh):
            x = r - self.W - int(6 * self.U)
            y = b - self.H - int(2 * self.U)
        self.root.geometry("%dx%d+%d+%d" % (self.W, self.H, x, y))

    def keep_on_top(self):
        try:
            self.root.attributes("-topmost", True)
            self.root.lift()
            if self._bub:
                self.bubwin.lift()
        except tk.TclError:
            pass
        self.root.after(2500, self.keep_on_top)

    def bind_events(self):
        c = self.canvas
        c.bind("<ButtonPress-1>", self.on_press)
        c.bind("<B1-Motion>", self.on_motion)
        c.bind("<ButtonRelease-1>", self.on_release)
        c.bind("<Double-Button-1>", lambda e: self.open_dialog())
        c.bind("<Button-3>", self.on_menu)
        c.bind("<Button-2>", lambda e: self.open_hub("chat"))

    def on_press(self, e):
        self.drag = (e.x_root - self.root.winfo_x(), e.y_root - self.root.winfo_y(), e.x_root, e.y_root, False)

    def on_motion(self, e):
        if not self.drag:
            return
        dx, dy, sx, sy, moved = self.drag
        if moved or abs(e.x_root - sx) + abs(e.y_root - sy) > 4:
            self.root.geometry("+%d+%d" % (e.x_root - dx, e.y_root - dy))
            self.drag = (dx, dy, sx, sy, True)

    def on_release(self, e):
        if not self.drag:
            return
        moved = self.drag[4]
        self.drag = None
        if moved:
            self.cfg["x"], self.cfg["y"] = self.root.winfo_x(), self.root.winfo_y()
            save_config(self.cfg)
            self.roam = None
            self.roam_pause_until = time.monotonic() + 300
        elif self.tablet_hit(e.x, e.y):
            self.tablet_press(self.tablet_hit(e.x, e.y))
        elif e.x >= self.COLW:                       # a click on the fox itself (head, nose, belly, tails react differently)
            self.fox_clicked(e.x, e.y)

    # ---- sprites & animation ----------------------------------------------------
    def bubble_family(self):
        return FONT_UI if self.cfg.get("bubble_font", "app") == "app" else UI_FONT

    def accessories(self):
        """Which extras the fox wears right now."""
        acc = []
        out = list(self.cfg.get("outfit", []))
        if (self.session and self.cfg.get("glasses_in_session", True)) or "glasses_always" in out:
            acc.append("glasses")
        acc += [a for a in out if a in ("flower", "bow", "crown", "headband", "mask")]
        acc += [a for a in self.lock_extra_acc() if a not in acc]
        if self.player and self.player.get("playing") and self.cfg.get("headphones_with_music", True):
            acc.append("headphones")
        if self.cfg.get("scarf"):
            acc.append("scarf")
        if self.gym_look_on():                             # gym look while the Exercise tab is open
            acc = [a for a in acc if a not in ("headband", "towel")] + ["headband", "towel"]
        return tuple(acc)

    def is_curled(self):
        return bool(self.sleeping and not self.brk and self.cfg.get("curl_when_away", True)
                    and not (self.mood_override and time.monotonic() < self.mood_until))

    def make_fox_items(self):
        """Canvas layers, back to front: tails, body, (belly / tablet / battery drawn later), foxfire wisps."""
        c = self.canvas
        self.tail_item = c.create_image(self.COLW, self.fox_y, anchor="nw")
        self.fox_item = c.create_image(self.COLW, self.fox_y, anchor="nw")
        self.orb_items = [c.create_image(0, 0, anchor="nw", tags="orb", state="hidden") for _ in range(3)]

    def tail_count(self):
        """A zenko grows tails with wisdom: 3 to start, one more for every 20 focused minutes today (up to 9)."""
        t, n = self._tails_n
        if time.monotonic() - t < 20:
            return n
        mode = str(self.cfg.get("tails", "grow"))
        if mode.isdigit():
            n = max(1, min(9, int(mode)))
        else:
            n = max(3, min(9, 3 + today_focus_minutes() // 20))
        self._tails_n = (time.monotonic(), n)
        return n

    def get_image(self, state, tail, frame, look=(0, 0, 0, 0), acc=(), hx=0, ear=0):
        if state.startswith(("qwalk", "rig")):
            key = (state, self.tail_count(), acc)
            img = self.images.get(key)
            if img is None:
                if len(self.images) > 360:
                    lru_trim(self.images, 300)
                img = sprite_photo([rig_rows(state, self.tail_count(), acc)], self.pal, self.Z)
                self.images[key] = img
            return img
        if False:
            pass
        else:
            key = ("curl", frame, acc, self.tail_count()) if state == "curl" else (state, frame, look, acc, hx, ear)
        img = self.images.get(key)
        if img is None:
            if len(self.images) > 360:
                lru_trim(self.images, 300)
            if state.startswith("qwalk"):
                rows = build_walk34(int(state[-1]), self.tail_count(), left=state[5] == "L")
            else:
                rows = build_curl(frame, acc, self.tail_count()) if state == "curl" else build_frame(state, tail, frame, look, acc, hx, ear)
            img = sprite_photo([rows], self.pal, self.Z)
            self.images[key] = img
        return img

    def get_tails(self, n, frame):
        key = ("tails", n, frame)
        img = self.images.get(key)
        if img is None:
            img = sprite_photo([build_tails(n, frame)], self.pal, self.Z)
            self.images[key] = img
        return img

    def get_orb(self, style, frame):
        key = (style, frame, self.Z)
        img = self.orb_imgs.get(key)
        if img is None:
            pal = dict(self.pal)
            if style == "angry":
                pal.update(A="#fff3c4", I="#ffb02e", U="#ff3b1f")
            elif style == "sleep":
                pal.update(A=self.pal["I"], I=self.pal["U"], U=_mixhex(self.pal["U"], "#000000", 0.35))
            img = sprite_photo([foxfire_rows(frame)], pal, self.Z)
            self.orb_imgs[key] = img
        return img

    def look_vec(self, mood):
        """(eye shift x, eye shift y, snout shift x, snout shift y) so the fox looks/points at your mouse."""
        if not self.cfg.get("look_at_mouse", True) or mood == "sleep":
            return (0, 0, 0, 0)
        try:
            px, py = self.root.winfo_pointerxy()
            cx = self.root.winfo_x() + self.COLW + 36 * self.Z
            cy = self.root.winfo_y() + self.fox_y + 30 * self.Z
        except tk.TclError:
            return (0, 0, 0, 0)
        dx, dy = px - cx, py - cy
        t = 70 * self.U
        lx = 1 if dx > t else (-1 if dx < -t else 0)
        ly = 1 if dy > 1.6 * t else (-1 if dy < -1.6 * t else 0)
        sx = lx * (2 if abs(dx) > 5 * t else 1)
        sy = -1 if ly < 0 else 0
        return (lx, ly, sx, sy)

    def belly_text(self):
        if self.brk:
            left = int(max(0, self.brk["planned"] - self.brk["elapsed"]))
            return "%02d:%02d" % (left // 60, left % 60)
        sess = self.session
        if sess:
            if sess["paused"] and int(time.time()) % 2:
                return ""                                           # blink while paused
            left = int(max(0, sess["planned"] - sess["elapsed"]))
            if left >= 3600:
                return "%d:%02d" % (left // 3600, left % 3600 // 60)
            return "%02d:%02d" % (left // 60, left % 60)
        now = datetime.datetime.now()
        if self.cfg.get("clock_24h", True):
            return now.strftime("%H:%M")
        return "%d:%02d" % (now.hour % 12 or 12, now.minute)

    def belly_music(self):
        """'~ TITLE - ARTIST' for the scrolling song bar, or None."""
        m = self.music_now
        if not (m and m.get("playing") and self.cfg.get("belly_music", True)) or self.session or self.brk:
            return None
        import unicodedata
        raw = "%s - %s" % (m.get("title", ""), m.get("artist", ""))
        raw = unicodedata.normalize("NFKD", raw).encode("ascii", "ignore").decode().upper()
        return "~ " + "".join(ch if ch in FONT35 else " " for ch in raw).strip()

    def draw_belly(self, dx, dy):
        text = self.belly_text()
        glyphs = [FONT35[ch] for ch in text if ch in FONT35]
        cols = []                                                    # the text as pixel columns
        for g in glyphs:
            for cx in range(len(g[0])):
                cols.append([g[r][cx] == "#" for r in range(5)])
            cols.append([False] * 5)
        if cols:
            cols.pop()
        W = 17                                                       # clock text on the ema plaque: 17 font columns
        if len(cols) <= W:
            off, window = 0, [None] * ((W - len(cols)) // 2) + cols
        else:
            loop = cols + [[False] * 5] * 8
            off = int((time.monotonic() - getattr(self, "_belly_t0", 0.0)) / 0.11) % len(loop)
            window = [loop[(off + i) % len(loop)] for i in range(W)]
        ink = self.pal.get("b") or self.pal.get("B") or "#000000"
        key = (text, off, dx, dy, self.Z, ink)
        if key == self._belly_key:
            return
        self._belly_key = key
        c = self.canvas
        c.delete("belly")
        Z = self.Z * 2
        for i, col in enumerate(window[:W]):
            if not col:
                continue
            for r in range(5):
                if col[r]:
                    px = self.COLW + dx + BELLY_X * self.Z + i * Z
                    py = self.fox_y + dy + BELLY_Y * self.Z + r * Z
                    c.create_rectangle(px, py, px + Z, py + Z, fill=ink, outline="", tags="belly")

    def set_mood(self, mood, secs):
        self.mood_override = mood
        self.mood_until = time.monotonic() + secs

    def clear_mood(self):
        self.mood_override = None

    def current_mood(self):
        now = time.monotonic()
        if self.mood_override and now < self.mood_until:
            return self.mood_override
        if self.brk or self.sleeping:
            return "sleep"
        if self.session:
            return "sad" if self.session["paused"] else "focus"
        return "idle"

    def animate(self):
        now = time.monotonic()
        mood = self.current_mood()
        Z = self.Z
        speed = 0.07 if mood == "alert" else (0.32 if mood == "sleep" else 0.15)
        tframe = int(now / speed) % 8                                 # tail fan sways through 8 frames
        frame = int(now / 0.6) % 2
        dx = dy = 0
        state = mood
        hx, ear = self.idle_moves(now, mood)
        if mood in ("idle", "focus"):
            if now >= self.next_blink:
                self.blink_until = now + (0.15 if self.cfg.get("idle_blink", True) else 0.0)
                self.next_blink = now + random.uniform(2.5, 5.5)
            if now < self.lick_until and mood == "idle":
                state = "lick" if int(now / 0.22) % 2 else "lick2"   # grooming her paw
            elif now < self.blink_until:
                state = "blink"
        elif mood == "alert":
            state = "alert" if int(now / 0.3) % 2 == 0 else "alert2"
            dx = Z if int(now / 0.08) % 2 else -Z                     # a cross little stamp-stamp
        elif mood == "happy":
            hx = 1 if int(now / 0.16) % 2 else -1                     # happy wiggle
        look = self.look_vec(mood)
        acc = self.accessories()
        curled = mood == "sleep" and self.is_curled()
        if curled:
            state, look, dx, dy = "curl", (0, 0, 0, 0), 0, 0
            frame = int(now / 1.6) % 2
            acc = tuple(a for a in acc if a == "headphones")
        st = {"state": state, "hx": hx, "ear": ear, "look": look, "frame": frame, "acc": acc, "curled": curled,
              "tframe": tframe, "n": self.tail_count(), "dxf": 0, "dyf": 0}
        if (self.play or self.sulk_until) and not self.brk:
            if curled and self.play:
                curled = st["curled"] = False
                st["acc"] = acc = self.accessories()
            st = self.play_pose(now, st)
        st = self.life_pose(now, st)
        tframe = st.get("tframe", tframe)
        self._pose = st
        state, hx, ear, look, acc = st["state"], st["hx"], st["ear"], st["look"], st["acc"]
        dx += st.get("dxf", 0) * Z
        dy += st.get("dyf", 0) * Z
        c = self.canvas
        walking = state.startswith(("qwalk", "rig"))
        if walking:
            c.itemconfigure(self.tail_item, state="hidden",      # her tails are part of the walking picture
                            image=self.get_tails(self.tail_count(), 0))  # (always a live image, even after a look change)
            c.itemconfigure(self.fox_item, image=self.get_image(state, "up", 0, acc=acc))
            c.coords(self.fox_item, self.COLW + dx, self.fox_y + dy)
            if self._belly_key is not None:                      # the ema timer is set down while she walks
                c.delete("belly")
                self._belly_key = None
            self.draw_tablet(dx, dy, False)
            self.draw_battery(dx, dy, True)
            self.draw_foxfire(now, mood, False)
            c.tag_raise("prop")
            if self._bub:
                self.bubble_place()
            self.root.after(60, self.animate)
            return
        if curled:
            c.itemconfigure(self.tail_item, state="hidden")
        else:
            c.itemconfigure(self.tail_item, image=self.get_tails(self.tail_count(), tframe), state="normal")
            c.coords(self.tail_item, self.COLW + dx, self.fox_y + dy)
        c.itemconfigure(self.fox_item, image=self.get_image(state, "up", frame, look, acc, hx, ear))
        c.coords(self.fox_item, self.COLW + dx, self.fox_y + dy)
        show_tab = bool(self.player) and self.cfg.get("belly_music", True) and state != "curl"
        if state == "curl" or show_tab:
            if self._belly_key is not None:
                c.delete("belly")
                self._belly_key = None
        else:
            self.draw_belly(dx, dy)
        self.draw_tablet(dx, dy, show_tab)
        self.draw_battery(dx, dy, state == "curl")
        if st.get("hide_fire"):
            for it in self.orb_items:
                c.itemconfigure(it, state="hidden")
        else:
            self.draw_foxfire(now, mood, curled)
        c.tag_raise("prop")
        if self._bub:
            self.bubble_place()
        self.root.after(60, self.animate)

    def idle_moves(self, now, mood):
        """(head sway, ear flick): a slow side-to-side sway, an ear twitch now and then, and sometimes a paw lick."""
        if mood not in ("idle", "focus", "sad"):
            return 0, 0
        live = {"calm": 0.6, "lively": 1.6}.get(self.cfg.get("idle_lively", "normal"), 1.0)
        s = math.sin(now * (0.55 if mood == "focus" else 0.8) * live)
        hx = (1 if s > 0.55 else (-1 if s < -0.55 else 0)) if self.cfg.get("idle_sway", True) else 0
        if now >= self.next_ear:
            self.ear_until = now + (0.32 if self.cfg.get("idle_ears", True) else 0.0)
            self.next_ear = now + random.uniform(4.0, 10.0) / live
        ear = 1 if now < self.ear_until and (self.ear_until - now) > 0.12 else 0
        if not self.cfg.get("idle_lick", True):
            self.lick_until = 0.0
            self.next_lick = now + 30
        if mood == "idle" and now >= self.next_lick and now >= self.lick_until:
            self.lick_until = now + random.uniform(1.8, 2.8)
            self.next_lick = now + random.uniform(16.0, 34.0)
        if now < self.lick_until:
            hx = 0
        return hx, ear

    def draw_foxfire(self, now, mood, curled):
        """Kitsune-bi (foxfire): wisps drifting round the fox, plus twinkling motes in the tails."""
        c, Z = self.canvas, self.Z
        on = bool(self.cfg.get("foxfire", True))
        if not on:
            for it in self.orb_items:
                c.itemconfigure(it, state="hidden")
            if self.motes:
                c.delete("mote")
                self.motes = []
            return
        style = "angry" if mood == "alert" else ("sleep" if mood == "sleep" else "calm")
        spd = {"angry": 2.6, "sleep": 0.35, "calm": 1.0}[style] * (1.8 if mood == "happy" else 1.0)
        anchors = ((2, 16, 0.0), (66, 2, 2.1), (98, 22, 4.2)) if not curled else ((88, 30, 0.0), (6, 34, 3.0))
        for i, it in enumerate(self.orb_items):
            if i >= len(anchors) or (style == "sleep" and i > 0 and not curled):
                c.itemconfigure(it, state="hidden")
                continue
            ax, ay, ph = anchors[i]
            t = now * spd + ph
            x = ax + 3.0 * math.sin(t * 0.9) + (1.5 * math.sin(now * 23 + i) if style == "angry" else 0)
            y = ay + 2.5 * math.sin(t * 1.7 + i) - (2.0 * math.sin(t * 0.5) if style == "sleep" else 0)
            fr = int(now * (11 if style == "angry" else 6) + i * 2) % 4
            c.itemconfigure(it, image=self.get_orb(style, fr), state="normal")
            c.coords(it, self.COLW + int(x) * Z, self.fox_y + int(y) * Z)
        c.tag_raise("orb")
        # motes: little sparks that wink on and off
        keep = []
        for (it, born, life) in self.motes:
            if now - born > life:
                c.delete(it)
            else:
                keep.append((it, born, life))
        self.motes = keep
        if len(self.motes) < (2 if curled else 5) and random.random() < 0.25:
            if curled:
                x, y = random.uniform(40, 100), random.uniform(42, 60)
            else:
                a = math.radians(random.uniform(5, 88))
                r = random.uniform(30, 52)
                x, y = TAIL_BASE[0] + r * math.cos(a), TAIL_BASE[1] - r * math.sin(a)
            x0, y0 = self.COLW + int(x) * Z, self.fox_y + int(y) * Z
            col = random.choice((self.pal["I"], self.pal["A"], self.pal.get("x", "#fff3b8")))
            it = c.create_rectangle(x0, y0, x0 + Z, y0 + Z, fill=col, outline="", tags="mote")
            self.motes.append((it, now, random.uniform(0.3, 0.9)))

    # ---- speech bubble & timer panel -------------------------------------------
    def pixel_box(self, x1, y1, x2, y2, tag, fill=None, shape="round", cv=None):
        """A lacquered box with round pixel-stepped corners, a double gold rim and a little gold knot on top."""
        fill = fill or T["bub"]
        c, U = cv or self.canvas, self.U
        r = int(16 * U)
        st = max(2, int(2 * U))
        w = max(2, int(2 * U))
        box = rbox(c, x1, y1, x2, y2, r, fill=fill, outline=GOLD, width=w, tags=tag, shape=shape, step=st)
        i = int(5 * U)
        rbox(c, x1 + i, y1 + i, x2 - i, y2 - i, max(2, r - i), fill="", outline=_mixhex(fill, GOLD, 0.35), width=1,
             tags=tag, shape=shape, step=st)
        j = max(2, int(2 * U))
        mxx = (x1 + x2) // 2                                   # a small mizuhiki knot centred on the top rim
        for (cx, k) in ((mxx - 3 * j, 1), (mxx + 3 * j, 1), (mxx, 2)):
            c.create_oval(cx - k * j, y1 - k * j + 1, cx + k * j, y1 + k * j + 1, fill=GOLD if k == 2 else _mixhex(GOLD, fill, 0.3),
                          outline="", tags=tag)
        return box

    # The speech bubble lives in its own little see-through window (zenko8), so it can sit on whichever side of her
    # has room on the screen: left of her (the usual), right of her, above or below, and it follows her as she walks.
    def bubble_window(self):
        w = getattr(self, "bubwin", None)
        if w is not None:
            try:
                if w.winfo_exists():
                    return w, self.bubcv
            except tk.TclError:
                pass
        w = tk.Toplevel(self.root)
        w.withdraw()
        w.overrideredirect(True)
        try:
            w.attributes("-topmost", True)
        except tk.TclError:
            pass
        try:
            w.attributes("-transparentcolor", KEY)
        except tk.TclError:
            pass
        w.config(bg=KEY)
        cv = tk.Canvas(w, bg=KEY, highlightthickness=0, bd=0)
        cv.pack(fill="both", expand=True)
        cv.bind("<Button-1>", self.bubble_click)
        self.bubwin, self.bubcv = w, cv
        self._bub = None
        return w, cv

    def bubble_click(self, e):
        b = self._bub
        if not b:
            return
        hit = self.bubcv.find_overlapping(e.x - 1, e.y - 1, e.x + 1, e.y + 1)
        for i, (x1, y1, x2, y2, fn) in enumerate(b.get("chips", [])):
            if x1 <= e.x <= x2 and y1 <= e.y <= y2:
                ui_sound("tap")
                self.bubble_hide()
                try:
                    fn()
                except Exception:
                    pass
                return
        if hit and not b.get("chips"):
            self.bubble_hide()                       # tap a plain bubble to dismiss it

    def bubble_hide(self):
        if self.bubble_job:
            try:
                self.root.after_cancel(self.bubble_job)
            except Exception:
                pass
            self.bubble_job = None
        self._bub = None
        try:
            self.bubcv.delete("all")
            self.bubwin.withdraw()
        except Exception:
            pass

    def say(self, text, secs=9, choices=None):
        """Show a speech bubble. choices = [(label, function)] adds one-tap buttons under the text."""
        U = self.U
        try:
            win, cv = self.bubble_window()
        except Exception:
            return
        if self.bubble_job:
            try:
                self.root.after_cancel(self.bubble_job)
            except Exception:
                pass
        cv.delete("all")
        text = clip(text, 160 if choices else 240)
        pad = int(13 * U)
        maxw = int(206 * U)
        tail = int(15 * U)
        m = tail + int(4 * U)                                  # margin round the box (room for the tail on any side)
        fam = self.bubble_family()
        t = cv.create_text(0, 0, text=text, font=(fam, 10, "bold"), fill=T["bubink"], width=maxw, anchor="nw", tags="txt")
        x1, y1, x2, y2 = cv.bbox(t)
        tw, th = x2 - x1, y2 - y1
        chips, rows, cx, cy, ch = [], [], 0, 0, int(22 * U)
        for (label, fn) in (choices or []):
            it = cv.create_text(0, 0, text=label, font=(fam, 9, "bold"), anchor="nw")
            a, b_, c_, d = cv.bbox(it)
            cv.delete(it)
            w = (c_ - a) + int(18 * U)
            if cx and cx + w > maxw:
                cx, cy = 0, cy + ch + int(6 * U)
            chips.append((cx, cy, w, label, fn))
            cx += w + int(6 * U)
        chips_h = (cy + ch + int(8 * U)) if chips else 0
        chips_w = max([c[0] + c[2] for c in chips] or [0])
        bw, bh = max(tw, chips_w) + 2 * pad, th + 2 * pad + chips_h
        cv.coords(t, m + pad, m + pad)
        self._bub = {"bw": bw, "bh": bh, "m": m, "tail": tail, "side": None, "pos": None, "chips": []}
        for (ox, oy, w, label, fn) in chips:
            X1, Y1 = m + pad + ox, m + pad + th + int(8 * U) + oy
            rbox(cv, X1, Y1, X1 + w, Y1 + ch, 99, fill=ORANGE, outline=GOLD, width=1, tags="chip", shape="pill", step=max(2, int(U)))
            cv.create_text(X1 + w // 2, Y1 + ch // 2, text=label, font=(fam, 9, "bold"), fill=ON_ACC, tags="chip")
            self._bub["chips"].append((X1, Y1, X1 + w, Y1 + ch, fn))
        cv.config(width=bw + 2 * m, height=bh + 2 * m)
        self.bubble_place(force=True)
        try:
            win.deiconify()
            win.lift()
        except tk.TclError:
            pass
        self.bubble_job = self.root.after(int(secs * 1000), self.bubble_hide)

    def bubble_spot(self):
        """Where the bubble fits best right now: (side, window x, window y)."""
        b, U, Z = self._bub, self.U, self.Z
        rx, ry = self.root.winfo_x(), self.root.winfo_y()
        fx, fy = rx + self.COLW, ry + self.fox_y                # top-left of her sprite on the screen
        head_x = fx + int(36 * Z)
        l, t, r, bt = monitor_area(head_x, fy + int(40 * Z), self.root)
        bw, bh, m, gap = b["bw"], b["bh"], b["m"], int(4 * U)
        cy2 = ry + self.H - self.PH - int(16 * U)               # the usual bubble bottom (just above the timer panel)
        cands = []
        # 1) left of her, tail pointing at her cheek
        x2 = fx - int(14 * U)
        y2 = min(bt - gap, max(t + gap + bh, cy2))
        cands.append(("left", x2 - bw, y2 - bh, x2 - bw >= l + gap))
        # 2) right of her head, just above her tails
        x1 = fx + int(68 * Z) + int(10 * U)
        y2r = min(bt - gap, max(t + gap + bh, fy + int(34 * Z)))
        cands.append(("right", x1, y2r - bh, x1 + bw <= r - gap))
        # 3) above her ears / 4) below her paws
        ax1 = max(l + gap, min(r - gap - bw, head_x - bw // 2))
        cands.append(("above", ax1, fy + int(2 * Z) - int(14 * U) - bh, fy + int(2 * Z) - int(14 * U) - bh >= t + gap))
        cands.append(("below", ax1, fy + self.FH + int(14 * U), fy + self.FH + int(14 * U) + bh <= bt - gap))
        side, bx, by = next(((sd, x, y) for sd, x, y, ok in cands if ok), cands[0][:3])
        bx = max(l + gap, min(r - gap - bw, bx))                 # never past the edge of the screen
        by = max(t + gap, min(bt - gap - bh, by))
        return side, bx - m, by - m, head_x, fy + int(26 * Z)

    def bubble_place(self, force=False):
        b = self._bub
        if not b:
            return
        try:
            side, wx, wy, hx, hy = self.bubble_spot()
        except Exception:
            return
        if not force and b["pos"] == (wx, wy) and b["side"] == side and b.get("aim") == (hx, hy):
            return
        cv, U, m, tail = self.bubcv, self.U, b["m"], b["tail"]
        bw, bh = b["bw"], b["bh"]
        if force or b["side"] != side or b.get("aim") != (hx, hy):
            cv.delete("frame")
            X1, Y1, X2, Y2 = m, m, m + bw, m + bh
            self.pixel_box(X1, Y1, X2, Y2, "frame", cv=cv)
            w = max(2, int(2 * U))
            fill = T["bub"]
            ax, ay = hx - wx, hy - wy                            # her head, in bubble-window coordinates
            if side in ("left", "right"):
                py = max(Y1 + int(16 * U), min(Y2 - int(16 * U), ay if side == "right" else Y2 - int(18 * U)))
                ex = X2 if side == "left" else X1
                tip = ex + (tail - 2 if side == "left" else -(tail - 2))
                cv.create_polygon(ex, py - int(8 * U), tip, py + int(4 * U), ex, py + int(9 * U),
                                  fill=fill, outline=GOLD, width=w, joinstyle="miter", tags="frame")
                cv.create_line(ex, py - int(8 * U) + w, ex, py + int(9 * U) - w, fill=fill, width=w + 1, tags="frame")
            else:
                px = max(X1 + int(18 * U), min(X2 - int(18 * U), ax))
                ey = Y2 if side == "above" else Y1
                tip = ey + (tail - 2 if side == "above" else -(tail - 2))
                cv.create_polygon(px - int(8 * U), ey, px + int(3 * U), tip, px + int(9 * U), ey,
                                  fill=fill, outline=GOLD, width=w, joinstyle="miter", tags="frame")
                cv.create_line(px - int(8 * U) + w, ey, px + int(9 * U) - w, ey, fill=fill, width=w + 1, tags="frame")
            cv.tag_lower("frame")
            b["side"], b["aim"] = side, (hx, hy)
        if b["pos"] != (wx, wy):
            try:
                self.bubwin.geometry("%dx%d+%d+%d" % (bw + 2 * m, bh + 2 * m, wx, wy))
            except tk.TclError:
                pass
            b["pos"] = (wx, wy)

    def draw_panel(self):
        c, U, s = self.canvas, self.U, self.session
        c.delete("panel")
        if not s:
            return
        x2 = self.COLW - int(14 * U)
        x1 = int(6 * U)
        y2 = self.H - int(8 * U)
        y1 = y2 - self.PH
        self.pixel_box(x1, y1, x2, y2, "panel", shape="leaf")
        left = max(0, s["planned"] - s["elapsed"])
        m, sec = divmod(int(left), 60)
        pad = int(13 * U)
        c.create_text(x1 + pad, y1 + int(7 * U), text=clip(s["task"], 26), anchor="nw",
                      font=(self.bubble_family(), 9, "bold"), fill=T["bubink"], tags="panel")
        label = "%02d:%02d" % (m, sec) + ("  paused" if s["paused"] else ("  away" if s.get("idle_paused") else ""))
        c.create_text(x1 + pad, y1 + int(19 * U), text=label, anchor="nw",
                      font=(self.bubble_family(), 15, "bold"), fill=GOLD if not s["paused"] else GREY, tags="panel")
        on = max(0, s["elapsed"] - s["dist"] - s["away"])
        c.create_text(x2 - pad, y1 + int(14 * U), anchor="ne", justify="right",
                      text="on task %dm\noff task %dm" % (on // 60, s["dist"] // 60),
                      font=(self.bubble_family(), 8), fill=GREY, tags="panel")
        bx1, bx2 = x1 + pad, x2 - pad
        by1, by2 = y2 - int(14 * U), y2 - int(8 * U)
        frac = min(1.0, s["elapsed"] / float(s["planned"]))
        st = max(2, int(U))
        rbox(c, bx1, by1, bx2, by2, 99, outline=_mixhex(T["bub"], GOLD, 0.5), fill=_mixhex(T["bub"], "#000000", 0.3),
             tags="panel", shape="pill", step=st)
        if frac > 0:
            fx = bx1 + (bx2 - bx1) * frac
            if fx - bx1 > 2 * st:
                rbox(c, bx1 + 1, by1 + 1, fx, by2 - 1, 99, fill=ORANGE, tags="panel", shape="pill", step=st)
            k = max(2, int(2 * U))
            c.create_oval(fx - k - 1, by1 - k, fx + k + 1, by2 + k, outline="", fill=GLOW, tags="panel")
            c.create_oval(fx - k // 2, by1 + 1, fx + k // 2, by2 - 1, outline="", fill="#ffffff", tags="panel")

    # ---- focus sessions ---------------------------------------------------------
    def open_dialog(self):
        if not tk or (self.dialog and self.dialog.winfo_exists()):
            if self.dialog:
                self.dialog.lift()
            return
        if self.session:
            self.say("We're already in a session. Right-click me to pause or stop it.", 6)
            return
        d = tk.Toplevel(self.root)
        self.dialog = d
        ui_sound("open")
        d.title("Zenko - new focus session")
        d.attributes("-topmost", True)
        d.resizable(False, False)
        d.configure(bg=GOLD)
        self.style_titlebar(d)
        frm = tk.Frame(d, bg=PAPER, padx=20, pady=16)
        frm.pack(padx=1, pady=1)
        hdr = tk.Frame(frm, bg=PAPER)
        hdr.grid(row=0, column=0, columnspan=4, sticky="w", pady=(0, 10))
        self.dlg_icon = self.small_fox(1, PAPER)
        tk.Label(hdr, image=self.dlg_icon, bg=PAPER).pack(side="left", padx=(0, 10))
        tt = tk.Frame(hdr, bg=PAPER)
        tt.pack(side="left")
        tk.Label(tt, text="Begin a focus ritual", bg=PAPER, fg=GOLD, font=(FONT_UI, 15, "bold")).pack(anchor="w")
        tk.Label(tt, text="I'll guard you from distractions.", bg=PAPER, fg=GREY, font=(FONT_UI, 10)).pack(anchor="w")
        hint = learned_hint() if self.cfg.get("learn_habits", True) else ""
        if hint:
            tk.Label(tt, text=hint, bg=PAPER, fg=_mixhex(GREY, GOLD, 0.4), font=(FONT_UI, 9, "italic"),
                     wraplength=330, justify="left").pack(anchor="w")
        tk.Label(frm, text="What are you working on?", bg=PAPER, fg=INK, font=(FONT_UI, 10)).grid(row=1, column=0, columnspan=4, sticky="w")
        task = tk.StringVar(value=self.cfg.get("last_task", ""))
        entry = self.tt_entry(frm, task, 42)
        entry.grid(row=2, column=0, columnspan=4, pady=(4, 12), sticky="ew", ipady=3)
        tk.Label(frm, text="Minutes", bg=PAPER, fg=INK, font=(FONT_UI, 10)).grid(row=3, column=0, sticky="w")
        m = tk.StringVar(value=str(self.cfg.get("last_minutes", 25)))
        self.tt_entry(frm, m, 6).grid(row=3, column=1, sticky="w", ipady=2)
        pre = tk.Frame(frm, bg=PAPER)
        pre.grid(row=3, column=2, columnspan=2, sticky="e")
        for v in (15, 25, 45, 60):
            self.tt_btn(pre, str(v), lambda v=v: m.set(str(v)), bg=FIELD, size=9, padx=8, pady=1).pack(side="left", padx=2)

        def go(_e=None):
            try:
                minutes = max(1, min(240, int(float(m.get()))))
            except ValueError:
                minutes = 25
            name = task.get().strip() or "Focus session"
            self.cfg["last_task"], self.cfg["last_minutes"] = task.get().strip(), minutes
            save_config(self.cfg)
            d.destroy()
            self.start_session(name, minutes)

        self.tt_btn(frm, "Start", go, bg=ORANGE, fg=ON_ACC, size=12, padx=20, pady=5
                    ).grid(row=4, column=0, columnspan=4, pady=(16, 0), sticky="ew")
        d.bind("<Return>", go)
        d.bind("<Escape>", lambda e: d.destroy())
        d.update_idletasks()
        x = (d.winfo_screenwidth() - d.winfo_width()) // 2
        y = (d.winfo_screenheight() - d.winfo_height()) // 3
        d.geometry("+%d+%d" % (x, y))
        d.after(80, lambda: (d.focus_force(), entry.focus_set()))

    def start_session(self, task, minutes, item=None):
        self.session = {"task": task, "planned": minutes * 60.0, "elapsed": 0.0, "dist": 0.0,
                        "away": 0.0, "paused": False,
                        "last_motiv": 0.0, "half": False, "final": False, "item": item}
        self.dist_run, self.alerted, self.level, self.last_nag = 0.0, False, 0, 0.0
        self.sleeping = False
        self.clear_mood()
        self.set_mood("happy", 2)
        beep("start")
        self.say("Let's go! %d min on “%s”. I'm watching." % (minutes, clip(task, 40)), 7)
        self.draw_panel()
        self.last_tick = time.monotonic()
        self.music_session_hook("start")
        self.root.after(300, self.music_apply)

    def end_session(self, completed):
        s, self.session = self.session, None
        if not s:
            return
        self.music_session_hook("stop")
        self.root.after(300, self.music_apply)
        focused = max(0.0, s["elapsed"] - s["dist"] - s["away"])
        add_stats(focused)
        try:
            self.life_session_done(s, completed, focused)
        except Exception:
            pass
        if self.cfg.get("learn_habits", True) and s["elapsed"] >= 120:
            learn_session(s["planned"] / 60.0, focused / 60.0, completed, s["dist"] / 60.0)
        if completed and s.get("item") is not None:
            self.tt_mark(s["item"], True)
        self.canvas.delete("panel")
        self.alerted = False
        self.clear_mood()
        if completed:
            self.set_mood("happy", 9)
            beep("done")
            verdict = "Spotless!" if s["dist"] < 60 else ("Not bad." if s["dist"] < s["planned"] * 0.25 else "We'll do better.")
            self.say("Done! %d min on “%s”. Off-task: %d min. %s" %
                     (mins(s["planned"]), clip(s["task"], 30), s["dist"] // 60, verdict), 14)
            if self.pomo_session_done(True):
                pass
            elif self.cfg.get("auto_break_after_session", True) and not self.brk:
                bm = int(self.cfg.get("break_minutes", 5)) * (2 if s["planned"] >= 3000 else 1)
                self.root.after(7000, lambda: self.start_break(bm) if not (self.session or self.brk) else None)
        else:
            self.pomo_session_done(False)
            self.set_mood("sad", 4)
            beep("sad")
            self.say("Stopped. You focused for %d min. Come back soon." % (focused // 60), 8)

    def toggle_pause(self):
        s = self.session
        if not s:
            return
        s["paused"] = not s["paused"]
        self.clear_mood()
        self.alerted, self.dist_run = False, 0.0
        self.say("Paused. Don't wander off..." if s["paused"] else "Back to work!", 5)
        self.draw_panel()

    # ---- the watcher ------------------------------------------------------------
    def is_distracting(self, title, proc):
        t = (title or "").lower()
        if not t and not proc:
            return None
        for a in self.cfg["allow"]:
            if a and a.lower() in t:
                return None
        for k in self.cfg["distractions"]:
            if k and k.lower() in t:
                return PRETTY.get(k.lower(), k.strip().title())
        for p in self.cfg["distraction_apps"]:
            if p and p.lower() == proc:
                return os.path.splitext(proc)[0].title()
        return None

    def pick_nag(self, ctx):
        mode = self.cfg.get("mode", "mixed")
        lvl = min(self.level, 3) - 1
        if mode == "gentle":
            pool = NAGS["gentle"][lvl]
        elif mode == "savage":
            pool = NAGS["savage"][lvl]
        else:  # mixed: starts kind, gets blunt
            pool = NAGS["gentle"][0] if self.level == 1 else (
                random.choice([NAGS["gentle"][1], NAGS["savage"][1]]) if self.level == 2 else NAGS["savage"][min(lvl, 2)])
        msg = random.choice(pool).format(**ctx)
        name = self.user_short()
        if name and random.random() < 0.35:
            msg = name + ", " + msg[:1].lower() + msg[1:]
        return msg

    def user_short(self):
        return (self.cfg.get("user_name") or "").strip().split(" ")[0]

    def user_profile_text(self):
        c = self.cfg
        bits = []
        if c.get("user_name"):
            bits.append("The user's name is %s." % c["user_name"].strip())
        if c.get("user_role"):
            bits.append("They are: %s." % c["user_role"].strip())
        if c.get("user_studying"):
            bits.append("They are working on / studying: %s." % c["user_studying"].strip())
        if c.get("user_goals"):
            bits.append("Their goals: %s." % c["user_goals"].strip())
        if c.get("user_notes"):
            bits.append("Other things they told you: %s" % c["user_notes"].strip()[:600])
        try:
            fb = self.facts_for_brain()
            if fb:
                bits.append(fb)
        except Exception:
            pass
        return " ".join(bits)

    def nag(self, site):
        s = self.session
        self.level += 1
        self.last_nag = time.monotonic()
        ctx = {"task": clip(s["task"], 28), "site": site, "planned": mins(s["planned"]),
               "elapsed": mins(s["elapsed"]), "left": mins(max(0, s["planned"] - s["elapsed"])),
               "dist": mins(s["dist"])}
        self.set_mood("alert", 3600)
        if self.cfg.get("learn_habits", True):
            learn_distraction(site)
        self.say(self.pick_nag(ctx), 11)
        if self.cfg.get("sound"):
            beep("nag")

    def tick(self):
        try:
            self._tick()
        except Exception:
            pass
        try:
            self.extras_tick()
        except Exception:
            pass
        try:
            self.life_tick()
        except Exception:
            pass
        try:
            self.study_tick()
        except Exception:
            pass
        self.root.after(1000, self.tick)

    def _tick(self):
        now = time.monotonic()
        dt = max(0.0, min(now - self.last_tick, 5.0))
        self.last_tick = now
        title, proc = foreground_info()
        idle = idle_seconds()
        site = self.is_distracting(title, proc)
        self._last_fg = (title, proc, idle, site)
        away = idle >= self.cfg["idle_minutes"] * 60
        s = self.session
        self.check_timetable(now)
        self.break_tick(dt, idle, now)
        if self.brk:
            return

        if self.sleeping and not away and idle < 3:
            self.sleeping = False
            self.say("Welcome back! Let's keep going." if s else "Hi again!", 5)
        if away and not self.sleeping:
            self.sleeping = True
            if s and not s["paused"]:
                self.say("Still there? I'll keep the timer running.", 8)

        if s:
            if s["paused"]:
                return
            if away and self.cfg.get("idle_pause", True):
                if not s.get("idle_paused"):              # idle detection: the timer waits for you
                    s["idle_paused"] = True
                    self.draw_panel()
                if self.alerted:
                    self.alerted, self.dist_run = False, 0.0
                    self.clear_mood()
                return
            if s.get("idle_paused"):
                s["idle_paused"] = False
                self.say("Okaeri~ I paused your timer while you were away. Carrying on!", 5)
            s["elapsed"] += dt
            if away:
                s["away"] += dt
                if self.alerted:                     # walked off: stop being cross
                    self.alerted, self.dist_run = False, 0.0
                    self.clear_mood()
            elif site:
                s["dist"] += dt
                self.dist_run += dt
                if self.dist_run >= self.cfg["grace_seconds"]:
                    if not self.alerted:
                        self.alerted, self.level = True, 0
                        self.nag(site)
                    elif now - self.last_nag >= self.cfg["nag_every_seconds"]:
                        self.nag(site)
                self.maybe_close(s, site, proc)
            else:
                if self.alerted:
                    self.alerted = False
                    self.clear_mood()
                    self.set_mood("happy", 4)
                    beep("happy")
                    self.say(random.choice(PRAISE), 5)
                self.dist_run = 0.0
                self.maybe_motivate(s, now)
            if s["elapsed"] >= s["planned"]:
                self.end_session(True)
            else:
                self.draw_panel()
        elif self.cfg.get("watch_without_session"):
            if site and not away:
                self.passive_run += dt
                if self.passive_run >= self.cfg["passive_minutes"] * 60 and now - self.last_suggest > 900:
                    self.last_suggest = now
                    self.set_mood("alert", 6)
                    self.say(random.choice(SUGGEST).format(site=site), 10)
                    if self.cfg.get("sound"):
                        beep("nag")
            else:
                self.passive_run = 0.0

    # ---- right-click menu -------------------------------------------------------
    def build_menu(self):
        self.menu = tk.Menu(self.root, tearoff=0)
        self.mode_var = tk.StringVar(value=self.cfg.get("mode", "mixed"))
        self.sound_var = tk.BooleanVar(value=bool(self.cfg.get("sound", True)))
        self.watch_var = tk.BooleanVar(value=bool(self.cfg.get("watch_without_session", True)))
        self.auto_var = tk.BooleanVar(value=autostart_enabled())
        self.close_var = tk.BooleanVar(value=bool(self.cfg.get("auto_close", True)))
        self.look_var = tk.BooleanVar(value=bool(self.cfg.get("look_at_mouse", True)))

    def style_menus(self):
        """Dark lacquer menus to match (Windows may still draw some parts natively)."""
        for k, v in (("*Menu.background", FIELD), ("*Menu.foreground", INK), ("*Menu.activeBackground", ORANGE),
                     ("*Menu.activeForeground", ON_ACC), ("*Menu.selectColor", GOLD), ("*Menu.disabledForeground", GREY)):
            self.root.option_add(k, v)

    def on_menu(self, e):
        m = self.menu
        m.delete(0, "end")
        try:
            m.config(bg=FIELD, fg=INK, activebackground=ORANGE, activeforeground=ON_ACC, selectcolor=GOLD,
                     disabledforeground=GREY)
        except tk.TclError:
            pass
        s = self.session
        m.add_command(label="Today: %d min focused" % today_focus_minutes(), state="disabled")
        m.add_separator()
        if s:
            m.add_command(label="Resume" if s["paused"] else "Pause", command=self.toggle_pause)
            m.add_command(label="Stop session", command=lambda: self.end_session(False))
        else:
            m.add_command(label="Start focus session...", command=self.open_dialog)
        item = self.focus_item()
        if item and not s:
            m.add_command(label="Start timetable item: %s (%d min)" % (clip(item["task"], 22), item["mins"]),
                          command=lambda: self.start_session(item["task"], item["mins"], item))
        m.add_separator()
        m.add_command(label="Open %s window" % APP_NAME, command=self.open_hub)
        m.add_command(label="Chat with the fox...", command=lambda: self.open_hub("chat"))
        if hasattr(self, "conv_start"):
            m.add_command(label="Stop talking" if getattr(self, "conv", None) else "Talk with her out loud",
                          command=self.conv_start)
            m.add_command(label="Breathe with me (Zen garden)", command=lambda: self.open_hub("garden"))
        m.add_command(label="Today's timetable...", command=lambda: self.open_hub("timetable"))
        m.add_cascade(label="急 Something urgent (push my day back)", menu=self.delay_menu(m))
        if self._delay:
            m.add_command(label="I'm back (resume)", command=self.delay_resume)
        if self.brk:
            m.add_command(label="End break", command=lambda: self.end_break(False))
        else:
            m.add_command(label="Take a %d-min break" % int(self.cfg.get("break_minutes", 5)), command=self.start_break)
        m.add_command(label="Export timetable as PDF (reMarkable)...", command=self.export_pdf)
        m.add_separator()
        self.menu_extras(m)
        m.add_separator()
        sizes = tk.Menu(m, tearoff=0)
        self.size_var = tk.IntVar(value=int(self.cfg.get("size", 4)))
        for label, val in (("Tiny", 3), ("Small", 4), ("Medium", 5), ("Large", 6)):
            sizes.add_radiobutton(label=label, value=val, variable=self.size_var,
                                  command=lambda: self.set_size(self.size_var.get()))
        m.add_cascade(label="Fox size", menu=sizes)
        themes = tk.Menu(m, tearoff=0)
        self.theme_var = tk.StringVar(value=self.cfg.get("theme", "snow"))
        for val, label in FUR_NAMES:
            themes.add_radiobutton(label=label, value=val, variable=self.theme_var,
                                   command=lambda: self.set_theme(self.theme_var.get()))
        m.add_cascade(label="Fox colours", menu=themes)
        modes = tk.Menu(m, tearoff=0)
        for label, val in (("Gentle", "gentle"), ("Mixed (kind, then savage)", "mixed"), ("Savage", "savage")):
            modes.add_radiobutton(label=label, value=val, variable=self.mode_var, command=self.save_prefs)
        m.add_cascade(label="Fox mood", menu=modes)
        m.add_checkbutton(label="Sound", variable=self.sound_var, command=self.save_prefs)
        m.add_checkbutton(label="Nag me even without a session", variable=self.watch_var, command=self.save_prefs)
        m.add_checkbutton(label="Auto-close distractions (in a session)", variable=self.close_var, command=self.save_prefs)
        m.add_checkbutton(label="Fox looks at my mouse", variable=self.look_var, command=self.save_prefs)
        if IS_WIN:
            m.add_checkbutton(label="Start with Windows", variable=self.auto_var,
                              command=lambda: set_autostart(self.auto_var.get()))
        m.add_separator()
        self.web_var = tk.BooleanVar(value=bool(self.cfg.get("web_enabled", True)))
        m.add_checkbutton(label="Internet lookups (weather, search...)", variable=self.web_var, command=self.toggle_web)
        m.add_command(label="Smart brain (offline AI) setup...", command=self.open_brain)
        m.add_command(label="Edit settings (distraction list)...", command=self.edit_settings)
        m.add_command(label="Reload settings", command=self.reload_settings)
        m.add_separator()
        m.add_command(label="Quit", command=self.quit)
        try:
            self.root.focus_force()
            m.tk_popup(e.x_root, e.y_root)
        finally:
            m.grab_release()

    def save_prefs(self):
        self.cfg["mode"] = self.mode_var.get()
        self.cfg["sound"] = bool(self.sound_var.get())
        SOUND["on"] = self.cfg["sound"]
        self.cfg["watch_without_session"] = bool(self.watch_var.get())
        self.cfg["auto_close"] = bool(self.close_var.get())
        self.cfg["look_at_mouse"] = bool(self.look_var.get())
        save_config(self.cfg)

    def edit_settings(self):
        save_config(self.cfg)
        try:
            os.startfile(CONFIG_PATH)       # opens in Notepad on Windows
        except Exception:
            self.say("Settings file: " + CONFIG_PATH, 10)

    def reload_settings(self):
        self.cfg = load_config()
        online_set(self.cfg)
        self.mode_var.set(self.cfg["mode"])
        self.sound_var.set(bool(self.cfg["sound"]))
        SOUND["on"] = bool(self.cfg["sound"])
        self.watch_var.set(bool(self.cfg["watch_without_session"]))
        self.close_var.set(bool(self.cfg.get("auto_close", True)))
        self.look_var.set(bool(self.cfg.get("look_at_mouse", True)))
        self.set_theme(self.cfg.get("theme", "snow"), announce=False)
        self.say("Settings reloaded.", 4)

    def quit(self):
        try:
            self.bgm.stop()
        except Exception:
            pass
        if self.session:
            self.end_session(False)
        try:
            self.voice.stop()
            self.speaker.restart()
        except Exception:
            pass
        voicevox_stop_engine()
        self.root.destroy()


    # ---- size -------------------------------------------------------------------
    def compute_dims(self):
        U = self.U
        self.Z = max(1, int(round((float(self.cfg["size"]) - 2) * U)))  # size of one fine sprite pixel
        self.FW, self.FH = W_ * self.Z, H_ * self.Z
        self.COLW = int(250 * U)
        self.PH = int(58 * U)                                           # timer panel height
        self.W = self.COLW + self.FW
        self.H = max(self.FH + int(20 * U), int(230 * U))
        self.fox_y = self.H - self.FH - int(2 * U)

    def set_size(self, n):
        self.cfg["size"] = int(n)
        old_w, old_h = self.W, self.H
        x, y = self.root.winfo_x(), self.root.winfo_y()
        self.compute_dims()
        self.images = {}
        self.orb_imgs = {}
        self.motes = []
        self._tab_key = self._batt_key = None
        self.canvas.config(width=self.W, height=self.H)
        self.canvas.delete("all")
        self.make_fox_items()
        nx, ny = x + old_w - self.W, y + old_h - self.H
        self.root.geometry("%dx%d+%d+%d" % (self.W, self.H, nx, ny))
        self.cfg["x"], self.cfg["y"] = nx, ny
        save_config(self.cfg)
        self._belly_key = None
        self.draw_panel()

    # ---- pep talks --------------------------------------------------------------
    def maybe_motivate(self, s, now):
        if self.alerted or now - self.last_nag < 20:
            return
        left = max(0.0, s["planned"] - s["elapsed"])
        frac = s["elapsed"] / float(s["planned"])
        every = max(1.0, float(self.cfg.get("motivate_every_minutes", 5))) * 60
        pool = None
        if left <= 60 and not s["final"] and s["planned"] >= 180:
            s["final"], s["last_motiv"], pool = True, s["elapsed"], FINAL
        elif frac >= 0.5 and not s["half"] and s["planned"] >= 300:
            s["half"], s["last_motiv"], pool = True, s["elapsed"], HALFWAY
        elif s["elapsed"] - s["last_motiv"] >= every:
            s["last_motiv"], pool = s["elapsed"], MOTIV
        if pool:
            self.set_mood("happy", 2.5)
            beep("ding")
            self.say(random.choice(pool).format(task=clip(s["task"], 24), left=mins(left)), 8)

    # ---- timetable --------------------------------------------------------------
    def tt_mark(self, it, done, day=None):
        today = (day or datetime.date.today()).isoformat()
        lst = it.setdefault("done", [])
        if done and today not in lst:
            lst.append(today)
        if not done and today in lst:
            lst.remove(today)
        save_tt(self.tt)
        self.tt_refresh()
        try:
            self.life_tt_marked(it, done, today)
        except Exception:
            pass

    def focus_item(self):
        """The timetable item that is on right now, or the next one coming up."""
        now = datetime.datetime.now()
        for it in tt_today(self.tt):
            if not tt_done(it) and tt_window(it)[1] > now:
                return it
        return None

    def tt_text(self):
        rows = tt_today(self.tt)
        if not rows:
            return "Nothing scheduled today. Try: add 4pm study 45"
        return "\n".join("%s  %s (%d min)%s" % (i["start"], i["task"], i["mins"], "  [done]" if tt_done(i) else "")
                         for i in rows)

    def tt_from_text(self, text):
        low = text.lower()
        tm = re.search(r"\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b|\b(\d{1,2}):(\d{2})\b", low)
        if not tm:
            return None
        start = parse_clock(tm.group(0))
        if not start:
            return None
        rest = (low[:tm.start()] + " " + low[tm.end():])
        mm = re.search(r"\b(\d{1,3})\s*(?:min|mins|minutes|m)\b", rest) or re.search(r"\bfor\s+(\d{1,3})\b", rest)
        length = int(mm.group(1)) if mm else 30
        if not mm:
            mm = re.search(r"\b(\d{1,3})\s*$", rest.strip())
            if mm:
                rest = rest.strip()
        if mm:
            length = int(mm.group(1))
            rest = rest[:mm.start()] + " " + rest[mm.end():]
        daily = bool(re.search(r"\b(daily|every ?day)\b", rest))
        tomorrow = "tomorrow" in rest
        task = re.sub(r"\b(add|schedule|daily|every ?day|tomorrow|today|at|for|to my timetable|timetable)\b", " ", rest)
        task = re.sub(r"\s+", " ", task).strip(" ,.-")
        if not task:
            return "What's the task? e.g. add 4pm study renal 45"
        date = datetime.date.today() + datetime.timedelta(days=1 if tomorrow else 0)
        self.tt.append({"start": start, "mins": max(1, min(480, length)), "task": task.capitalize(),
                        "daily": daily, "date": date.isoformat(), "done": []})
        save_tt(self.tt)
        self.tt_refresh()
        return "Added %s – %s (%d min)%s." % (start, task.capitalize(), length,
                                                  ", every day" if daily else (" for tomorrow" if tomorrow else ""))

    def check_timetable(self, now):
        if now - self._tt_last < 10:
            return
        self._tt_last = now
        dt = datetime.datetime.now()
        for it in tt_today(self.tt):
            if tt_done(it):
                continue
            diff = (tt_window(it)[0] - dt).total_seconds()
            key = (dt.date().isoformat(), it["start"], it["task"])
            if 0 < diff <= 300 and (key, "pre") not in self.announced:
                self.announced.add((key, "pre"))
                self.say("Heads up: “%s” at %s (in %d min)." % (clip(it["task"], 30), it["start"], mins(diff)), 9)
                beep("ding")
                return
            if -600 <= diff <= 0 and (key, "now") not in self.announced:
                self.announced.add((key, "now"))
                self.set_mood("happy", 3)
                beep("happy")
                self.say("Timetable: time for “%s” (%d min). Right-click me > Start timetable item!" %
                         (clip(it["task"], 30), it["mins"]), 12)
                return

    # ---- timetable window -------------------------------------------------------
    def small_fox(self, zoom, bg=None):
        """The fox with its tails, as a picture for headers and dialogs (transparent background)."""
        return sprite_photo([build_tails(self.tail_count(), 0, shadow=False), build_frame("happy", "up", 0)], self.pal, zoom)

    def tt_btn(self, parent, text, cmd, bg=None, fg=None, size=10, padx=10, pady=3, enabled=True):
        """A rounded pixel button (see PixelButton)."""
        bg = bg or FIELD
        if bg == "white":
            bg = FIELD
        return PixelButton(parent, text, cmd, bg, fg or INK, size, padx, pady, enabled)

    def tt_entry(self, parent, var, width):
        return tk.Entry(parent, textvariable=var, width=width, relief="flat", bg=FIELD, fg=INK,
                        font=(FONT_UI, 11), highlightthickness=1, highlightbackground=LINE,
                        highlightcolor=GOLD, insertbackground=INK, selectbackground=ORANGE, selectforeground=ON_ACC)

    def open_timetable(self, parent=None):
        top = parent is None
        if top and self.tt_win and self.tt_win.winfo_exists():
            self.tt_win.lift()
            self.tt_refresh()
            return
        self.tt_day = 0
        self.tt_W, self.tt_maxh = (552, 330) if top else (700, 420)
        if top:
            w = tk.Toplevel(self.root)
            w.title("Zenko - my day")
            w.attributes("-topmost", True)
            w.resizable(False, False)
            w.bind("<Escape>", lambda e: w.destroy())
        else:
            w = parent
        self.tt_win = w
        w.configure(bg=PAPER)

        hb = T["banner"]
        hdr = tk.Frame(w, bg=hb)
        hdr.pack(fill="x")
        self.tt_icon = self.small_fox(1)
        tk.Label(hdr, image=self.tt_icon, bg=hb).pack(side="left", padx=(14, 8), pady=6)
        mid = tk.Frame(hdr, bg=hb)
        mid.pack(side="left", fill="x", expand=True)
        self.tt_title = tk.Label(mid, bg=hb, fg=INK, font=(FONT_UI, 18, "bold"), anchor="w")
        self.tt_title.pack(anchor="w")
        self.tt_sub = tk.Label(mid, bg=hb, fg=GREY, font=(FONT_UI, 10), anchor="w")
        self.tt_sub.pack(anchor="w")
        nav = tk.Frame(hdr, bg=hb)
        nav.pack(side="right", padx=12)
        ub = self.tt_btn(nav, "急 Delay", lambda: self.delay_popup(ub), bg=ORANGE, fg=ON_ACC, size=9)
        ub.pack(side="left", padx=(2, 10))
        self.tt_btn(nav, "< Prev", lambda: self.tt_nav(-1), size=9).pack(side="left", padx=2)
        self.tt_btn(nav, "Today", lambda: self.tt_nav(0), size=9).pack(side="left", padx=2)
        self.tt_btn(nav, "Next >", lambda: self.tt_nav(1), size=9).pack(side="left", padx=2)
        tk.Frame(w, bg=GOLD, height=1).pack(fill="x")

        self.tt_bar = tk.Canvas(w, width=self.tt_W + 4, height=14, bg=PAPER, highlightthickness=0)
        self.tt_bar.pack(padx=12, pady=(10, 2))

        wrap = tk.Frame(w, bg=PAPER)
        wrap.pack(fill="both", expand=True, padx=(12, 4), pady=2)
        cv = tk.Canvas(wrap, width=self.tt_W, height=200, bg=PAPER, highlightthickness=0)
        sb = tk.Scrollbar(wrap, command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        cv.grid(row=0, column=0)
        sb.grid(row=0, column=1, sticky="ns")
        inner = tk.Frame(cv, bg=PAPER)
        wid = cv.create_window((0, 0), window=inner, anchor="nw")
        inner.bind("<Configure>", lambda e: cv.configure(scrollregion=cv.bbox("all")))
        cv.bind("<Configure>", lambda e: cv.itemconfigure(wid, width=e.width))
        self.tt_cv, self.tt_sb, self.tt_inner = cv, sb, inner

        def wheel(e):
            if w.winfo_exists() and str(w.winfo_containing(e.x_root, e.y_root)).startswith(str(w)):
                cv.yview_scroll(-1 if e.delta > 0 else 1, "units")
        if top:
            w.bind_all("<MouseWheel>", wheel)
        elif self.hub:
            self.hub["scrollers"].append(cv)

        # ---- add form
        foot_bg = T["foot"]
        tk.Frame(w, bg=LINE, height=1).pack(fill="x", pady=(6, 0))
        foot = tk.Frame(w, bg=foot_bg)
        foot.pack(fill="x")
        tk.Label(foot, text="Add to this day", bg=foot_bg, fg=INK, font=(FONT_UI, 10, "bold")
                 ).grid(row=0, column=0, columnspan=3, sticky="w", padx=12, pady=(8, 2))
        self.tt_btn(foot, "Export PDF", self.export_pdf, bg=FIELD, size=8, padx=8, pady=1
                    ).grid(row=0, column=3, columnspan=2, sticky="e", padx=8, pady=(8, 2))
        t_var, k_var, m_var, d_var = tk.StringVar(), tk.StringVar(), tk.StringVar(value="30"), tk.BooleanVar()
        msg = tk.StringVar()
        tk.Label(foot, text="Time (4pm or 16:30)", bg=foot_bg, fg=GREY, font=(FONT_UI, 8)
                 ).grid(row=1, column=0, sticky="w", padx=(12, 0))
        tk.Label(foot, text="What are you doing?", bg=foot_bg, fg=GREY, font=(FONT_UI, 8)
                 ).grid(row=1, column=1, sticky="w", padx=8)
        tk.Label(foot, text="Minutes", bg=foot_bg, fg=GREY, font=(FONT_UI, 8)
                 ).grid(row=1, column=2, sticky="w")
        te = self.tt_entry(foot, t_var, 9)
        te.grid(row=2, column=0, padx=(12, 0), sticky="w")
        ke = self.tt_entry(foot, k_var, 30)
        ke.grid(row=2, column=1, padx=8, sticky="w")
        self.tt_entry(foot, m_var, 5).grid(row=2, column=2, sticky="w")
        quick = tk.Frame(foot, bg=foot_bg)
        quick.grid(row=3, column=0, columnspan=3, sticky="w", padx=12, pady=(6, 0))
        for v in (15, 30, 45, 60, 90):
            self.tt_btn(quick, "%d" % v, lambda v=v: m_var.set(str(v)), bg=FIELD, size=9, padx=7, pady=1
                        ).pack(side="left", padx=(0, 4))
        tk.Checkbutton(foot, text="every day", variable=d_var, bg=foot_bg, activebackground=foot_bg, selectcolor=FIELD,
                       activeforeground=INK, font=(FONT_UI, 10), fg=INK).grid(row=3, column=3, padx=8, pady=(6, 0))

        def add(_e=None):
            st = parse_clock(t_var.get())
            if not st or not k_var.get().strip():
                msg.set("Enter a time like 2pm or 14:30, and what you're doing.")
                return
            try:
                ln = max(1, min(480, int(float(m_var.get()))))
            except ValueError:
                ln = 30
            day = datetime.date.today() + datetime.timedelta(days=self.tt_day)
            self.tt.append({"start": st, "mins": ln, "task": k_var.get().strip(), "daily": bool(d_var.get()),
                            "date": day.isoformat(), "done": []})
            save_tt(self.tt)
            msg.set("")
            k_var.set("")
            t_var.set("")
            self.tt_refresh()
            te.focus_set()
        self.tt_btn(foot, "+ Add", add, bg=ORANGE, fg=ON_ACC, size=11, padx=16, pady=4
                    ).grid(row=2, column=3, rowspan=1, padx=8)
        tk.Label(foot, textvariable=msg, bg=foot_bg, fg=T["bad"], font=(FONT_UI, 9)
                 ).grid(row=4, column=0, columnspan=6, sticky="w", padx=12, pady=(2, 8))
        ke.bind("<Return>", add)
        te.bind("<Return>", lambda e: ke.focus_set())

        self.tt_refresh()
        if top:
            w.update_idletasks()
            w.geometry("+%d+%d" % ((w.winfo_screenwidth() - w.winfo_width()) // 2,
                                   max(10, (w.winfo_screenheight() - w.winfo_height()) // 4)))
        te.focus_set()

        def auto():
            if w.winfo_exists():
                self.tt_refresh()
                w.after(30000, auto)
        w.after(30000, auto)

    def tt_nav(self, d):
        self.tt_day = 0 if d == 0 else self.tt_day + d
        self.tt_refresh()

    def tt_start(self, it):
        if self.session:
            self.say("Finish or stop the current session first.", 5)
            return
        if isinstance(self.tt_win, tk.Toplevel) and self.tt_win.winfo_exists():
            self.tt_win.destroy()
        self.start_session(it["task"], it["mins"], it)

    def tt_delete(self, it):
        if it.get("daily") and not messagebox.askyesno(
                "Delete", "This item repeats every day.\nDelete it from all days?", parent=self.tt_win):
            return
        if it in self.tt:
            self.tt.remove(it)
        save_tt(self.tt)
        self.tt_refresh()

    def tt_refresh(self):
        w = self.tt_win
        if not w or not w.winfo_exists():
            return
        today_d = datetime.date.today()
        day = today_d + datetime.timedelta(days=self.tt_day)
        is_today = self.tt_day == 0
        rows = tt_today(self.tt, day)
        now = datetime.datetime.now()
        names = {0: "Today", 1: "Tomorrow", -1: "Yesterday"}
        self.tt_title.config(text="%s  ·  %s" % (names.get(self.tt_day, day.strftime("%A")), day.strftime("%d %b")))
        done_n = sum(1 for i in rows if tt_done(i, day))
        sub = "%d of %d done  ·  %s planned" % (done_n, len(rows), fmt_hm(sum(i["mins"] for i in rows))) \
            if rows else "Nothing planned yet"
        nxt = self.focus_item() if is_today else None
        if nxt:
            sub += "  ·  next: %s" % nxt["start"]
        self.tt_sub.config(text=sub)
        bar = self.tt_bar
        bar.delete("all")
        self.glow_bar(bar, 1, 2, self.tt_W + 3, 12, done_n / float(len(rows)) if rows else 0.0)

        for c in self.tt_inner.winfo_children():
            c.destroy()
        if not rows:
            tk.Label(self.tt_inner, text="A blank day!\nAdd your first item below.", bg=PAPER, fg=GREY,
                     font=(FONT_UI, 12), pady=26).pack(fill="x")
        for it in rows:
            self.tt_card(it, day, now)
        self.tt_inner.update_idletasks()
        h = self.tt_inner.winfo_reqheight()
        self.tt_cv.config(height=max(110, min(h, self.tt_maxh)))
        if h > self.tt_maxh:
            self.tt_sb.grid()
        else:
            self.tt_sb.grid_remove()

    def tt_card(self, it, day, now):
        today = day == datetime.date.today()
        st, en = tt_window(it, day)
        done = tt_done(it, day)
        status = ""
        if done:
            status, bg, accent = "done", T["donebg"], T["good"]
        elif today and st <= now < en:
            status, bg, accent = "NOW", T["nowbg"], ORANGE
        elif today and en <= now:
            status, bg, accent = "missed", T["missbg"], T["bad"]
        elif today and (st - now).total_seconds() <= 3600:
            status, bg, accent = "in %d min" % mins((st - now).total_seconds()), T["soonbg"], ORANGE_D
        else:
            bg, accent = T["card"], T["edge"]
        card = self.round_frame(self.tt_inner, bg, accent if status else LINE, r=12, notch=5)
        card.pack(fill="x", pady=4, padx=(0, 8))
        tk.Frame(card, bg=accent, width=5).pack(side="left", fill="y", padx=(8, 0), pady=7)
        tb = tk.Frame(card, bg=bg)
        tb.pack(side="left", padx=(10, 6), pady=8)
        tk.Label(tb, text=it["start"], bg=bg, fg=GOLD if not done else GREY, font=("Consolas", 16, "bold")).pack(anchor="w")
        tk.Label(tb, text="until " + en.strftime("%H:%M"), bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(anchor="w")
        mid = tk.Frame(card, bg=bg)
        mid.pack(side="left", fill="x", expand=True, padx=6)
        tk.Label(mid, text=clip(it["task"], 30), bg=bg, fg=GREY if done else INK, anchor="w",
                 font=(FONT_UI, 12, "bold overstrike" if done else "bold")).pack(anchor="w")
        meta = fmt_hm(it["mins"]) + ("   ·   repeats daily" if it.get("daily") else "")
        tk.Label(mid, text=meta, bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(anchor="w")
        right = tk.Frame(card, bg=bg)
        right.pack(side="right", padx=8, pady=6)
        if status:
            tk.Label(right, text=status, bg=accent, fg=ON_ACC, font=(FONT_UI, 8, "bold"), padx=7
                     ).pack(anchor="e", pady=(0, 4))
        row = tk.Frame(right, bg=bg)
        row.pack(anchor="e")
        can_start = today and not done
        self.tt_btn(row, "Start", lambda: self.tt_start(it), bg=T["start"], size=9, padx=8, pady=1,
                    enabled=can_start).pack(side="left", padx=2)
        self.tt_btn(row, "Undo" if done else "Done", lambda: self.tt_mark(it, not done, day), bg=T["donebtn"], size=9, padx=8, pady=1
                    ).pack(side="left", padx=2)
        self.tt_btn(row, "Delete", lambda: self.tt_delete(it), bg=T["delbtn"], size=9, padx=8, pady=1
                    ).pack(side="left", padx=2)

    # ---- ask the fox ------------------------------------------------------------
    def open_chat(self, parent=None):
        top = parent is None
        if top and self.chat and self.chat["win"].winfo_exists():
            self.chat["win"].lift()
            self.chat["entry"].focus_set()
            return
        if top:
            w = tk.Toplevel(self.root)
            w.title("Zenko - chat")
            w.attributes("-topmost", True)
        else:
            w = parent
        w.configure(bg=PAPER)
        pad = (8, 8) if top else (24, 24)
        txt = tk.Text(w, width=58 if top else 20, height=15 if top else 10, wrap="word", font=(FONT_UI, 11),
                      bg=T["card"], fg=INK, padx=16, pady=12, state="disabled", relief="flat", spacing1=2, spacing3=4,
                      highlightthickness=1, highlightbackground=LINE, selectbackground=ORANGE, selectforeground=ON_ACC)
        if not top:
            chips = tk.Frame(w, bg=PAPER)
            chips.pack(fill="x", padx=24, pady=(12, 0))
            for lab, cmd in (("Weather", "weather"), ("Time left", "time left"), ("What's next", "next"),
                             ("Headlines", "news"), ("What's playing", "what's playing"), ("My notes", "notes"), ("Help", "help")):
                self.tt_btn(chips, lab, lambda c=cmd: self.chat_send(c), bg=T["start"], size=9, padx=9, pady=1
                            ).pack(side="left", padx=(0, 6))
        txt.pack(fill="both", expand=True, padx=pad, pady=(10, 0))
        status = tk.Label(w, text="", bg=PAPER, fg=GREY, font=(FONT_UI, 9, "italic"), anchor="w")
        status.pack(fill="x", padx=pad)
        txt.tag_configure("you", foreground=ORANGE_D, font=(FONT_UI, 11, "bold"))
        txt.tag_configure("foxname", foreground=GOLD, font=(FONT_UI, 11, "bold"))
        txt.tag_configure("fox", foreground=INK)
        attbar = tk.Frame(w, bg=PAPER)
        row = tk.Frame(w, bg=PAPER)
        row.pack(fill="x", padx=pad, pady=(0, 14 if not top else 8))
        var = tk.StringVar()
        ent = self.tt_entry(row, var, 40)
        ent.pack(side="left", fill="x", expand=True, ipady=3)
        self.chat = {"win": w, "txt": txt, "entry": ent, "status": status, "mic": None, "attbar": attbar, "row": row, "pad": pad}
        self._chat_q, self._chat_typing = [], False
        self.chat_att = None

        def send(_e=None):
            q = var.get().strip()
            att = getattr(self, "chat_att", None)
            if att:
                var.set("")
                self.chat_clear_attachment()
                self.chat_image(q or "What's in this screenshot? Help me with it.", att)
                return
            if q:
                var.set("")
                self.chat_send(q)
        ent.bind("<Return>", send)
        ent.bind("<Control-v>", self.chat_paste)
        ent.bind("<Control-V>", self.chat_paste)
        self.tt_btn(row, "Send", send, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=3).pack(side="left", padx=(8, 0))
        mic = self.tt_btn(row, "Mic", lambda: self.voice_toggle("chat"), bg=T["start"], size=10, padx=12, pady=3)
        mic.pack(side="left", padx=(6, 0))
        self.chat["mic"] = mic
        if hasattr(self, "conv_start"):
            talk = self.tt_btn(row, "Talk", self.conv_start, bg=T["start"], size=10, padx=12, pady=3)
            talk.pack(side="left", padx=(6, 0))
            self.chat["talk"] = talk
        ib = self.tt_btn(row, "Image", lambda: self.chat_attach_menu(ib), bg=T["start"], size=10, padx=12, pady=3)
        ib.pack(side="left", padx=(6, 0))
        self.tt_btn(row, "Screen", lambda: (self.chat_line("You", "look at my screen"),
                                            self.chat_line("Fox", self.ask_screen("What is on my screen? Help me with it.", typed=True))),
                    bg=T["start"], size=10, padx=12, pady=3).pack(side="left", padx=(6, 0))
        if top:
            w.update_idletasks()
            sw, sh = w.winfo_screenwidth(), w.winfo_screenheight()
            w.geometry("+%d+%d" % (max(0, sw - w.winfo_width() - 40), max(0, sh - w.winfo_height() - 360)))
        for who, t in self.chat_log:
            self._chat_insert(who, t)
        if not self.chat_log:
            self.chat_line("Fox", "Hi! Type 'help' to see what I can do.")
        w.after(80, lambda: (w.focus_force() if top else None, ent.focus_set()))

    def chat_send(self, q, typed=True):
        self.chat_line("You", q)
        learning = self.cfg.get("learn_style", True)
        ans = self.answer_local(q)
        if ans is None:
            alt = expand_shorthand(q)                       # your slang / shorthand -> plain words, then try again
            if alt.lower() != q.lower():
                ans = self.answer_local(alt)
        if ans is None:
            self._chat_miss = (q, time.time())
            self.ask_llm(q)
            return
        if "\n" not in ans and len(ans) < 160 and not ans.endswith("..."):
            ans = fox_voice(ans, "sad" if re.match(r"(no |nothing|i couldn|i can'?t|sorry)", ans, re.I) else "happy")
        miss, self._chat_miss = self._chat_miss, None
        if miss and learning and time.time() - miss[1] < 120 and abs(len(miss[0].split()) - len(q.split())) <= 1:
            got = learn_aliases_from(miss[0], q)            # you rephrased what I didn't get: learn your words
            if got:
                ans += "\n(Kon! Noted~ when you say '%s' you mean '%s'.)" % got[0]
        self.chat_line("Fox", ans)
        self.say(ans.split("\n")[0], 8)
        self.set_mood("happy", 1.5)

    def chat_line(self, who, text):
        self.chat_log.append((who, text))
        self.chat_log = self.chat_log[-200:]
        self._chat_put(who, text)
        if who == "You":
            ui_sound("send")
        else:
            self.root.after(260, lambda: ui_sound("reply"))
        if who == "Fox" and self.should_speak(text):
            self.speak(md_plain(text))

    def _chat_insert(self, who, text):
        c = self.chat
        if not c or not c["win"].winfo_exists():
            return
        t = c["txt"]
        t.config(state="normal")
        t.insert("end", ("You" if who == "You" else self.fox_name()) + ":  ", "you" if who == "You" else "foxname")
        if who == "You":
            t.insert("end", text + "\n\n", "fox")
        else:
            md_insert(t, text, ("fox",))
            t.insert("end", "\n\n", "fox")
        t.config(state="disabled")
        t.see("end")

    def _chat_put(self, who, text):
        c = self.chat
        if not c or not c["win"].winfo_exists():
            return
        self._chat_q.append((who, text))
        self._chat_pump()

    def _chat_pump(self):
        """Show messages one after another; the fox's replies are typed out letter by letter."""
        c = self.chat
        if self._chat_typing or not c or not c["win"].winfo_exists():
            return
        while self._chat_q:
            who, text = self._chat_q.pop(0)
            if who == "You" or len(text) < 3:
                self._chat_insert(who, text)
                continue
            t = c["txt"]
            t.config(state="normal")
            t.insert("end", self.fox_name() + ":  ", "foxname")
            t.config(state="disabled")
            self._chat_typing = True
            step = max(2, len(text) // 45)
            md_tags(t)
            segs = md_segments(text, ("fox",))
            md_bind_links(t, segs)
            chunks = [(sg[k:k + step], tg) for sg, tg in segs for k in range(0, len(sg), step)]

            def tick(i=0, chunks=chunks, t=t):
                try:
                    if not t.winfo_exists():
                        self._chat_typing = False
                        return
                    t.config(state="normal")
                    t.insert("end", chunks[i][0], chunks[i][1])
                    t.config(state="disabled")
                    t.see("end")
                except IndexError:
                    pass
                except tk.TclError:
                    self._chat_typing = False
                    return
                if i + 1 < len(chunks):
                    self.root.after(14, lambda: tick(i + 1))
                else:
                    t.config(state="normal")
                    t.insert("end", "\n\n", "fox")
                    t.config(state="disabled")
                    t.see("end")
                    self._chat_typing = False
                    self._chat_pump()
            tick()
            return

    def answer_local(self, text):
        cmd = fix_first(text)                                  # first word spell-fixed, task names untouched
        low = fix_typos(text).lower().strip()                  # spell-fixed copy used to recognise commands
        s = self.session
        if self.quiz and not re.match(r"^(help|commands)$", low):
            r = self.quiz_answer(text)
            if r is not None:
                return r
        if low in ("help", "?", "commands"):
            return HELP
        m = re.match(r"^(?:learn|teach(?: you| me)?|remember)\s*[:,]?\s*(.+?)\s*(?:=>|->|=)\s*(.+)$", text.strip(), re.I) or \
            re.match(r"^when i say\s+[\"']?(.+?)[\"']?\s*,?\s*(?:you )?(?:say|reply|answer|respond)(?: with)?\s+(.+)$", text.strip(), re.I)
        if m:
            learn_reply(m.group(1), m.group(2))
            return "Kon! Kon! Yatta, learned it! When you say '%s' I'll answer that. (Say 'forget %s' to undo.)" % (
                m.group(1).strip(), m.group(1).strip())
        m = re.match(r"^(?:when|if) i (?:say|type|write)\s+[\"']?(.+?)[\"']?\s*,?\s*i (?:mean|meant)\s+[\"']?(.+?)[\"']?\s*\.?$",
                     text.strip(), re.I)
        if m and len(m.group(1).split()) <= 3:
            learn_alias(m.group(1), m.group(2))
            return "Kon kon~ got it: '%s' means '%s'. I'll understand that from now on~kon!" % (m.group(1).strip(), m.group(2).strip())
        if re.match(r"^forget (?:my (?:style|slang|shorthand)|how i (?:talk|type|speak|write))\b", low):
            d = load_learned()
            d.pop("style", None)
            save_learned(d)
            return "Okay~ I've forgotten your shorthand. Fresh start, kon!"
        if re.search(r"my (?:slang|shorthand)\b|what shorthand|what(?:'s| is) my (?:style|slang)", low):
            return shorthand_summary()
        if re.search(r"what (?:did|have) you (?:look(?:ed)? up|search(?:ed)?|find|found)|what have you searched", low):
            looked = facts_recent(8)
            return ("Fumu fumu~ recently I looked up: " + "; ".join(looked) + ". Ask again and I'll remember (for 12 hours)!") if looked \
                else "Ne~ I haven't looked anything up yet. Ask me anything!"
        lf = self.life_forget(text)
        if lf:
            return lf
        m = re.match(r"^forget\s+(.+)$", text.strip(), re.I)
        if m:
            what = m.group(1).strip()
            n = forget_reply("everything" if what.lower() in ("everything", "everything you learned", "all") else what)
            return "Poof~ forgotten!" if n else "Ne~? I hadn't learned '%s'." % m.group(1).strip()
        if re.search(r"what (have|did) you learn|what do you know about me|my habits|what have you noticed", low):
            return learned_summary()
        taught = learned_reply(text)
        if taught:
            return taught
        m = re.match(r"(?:set |change )?(?:my )?home ?(?:city|town)(?: to| is|:)?\s+(.+)$", text.strip(), re.I)
        if m:
            self.cfg["home_city"] = m.group(1).strip(" .")[:60]
            save_config(self.cfg)
            return "Home city set to %s. Now 'weather' will use it." % self.cfg["home_city"]
        m = re.match(r"(?:set |change )?(?:my )?(?:temp(?:erature)?)? ?unit(?: to| is|:)?\s*([cf])\w*\s*$", low)
        if m:
            self.cfg["temp_unit"] = m.group(1).upper()
            save_config(self.cfg)
            return "Temperatures will be shown in °%s." % self.cfg["temp_unit"]
        gr = self.gym_route(text)
        if gr:
            return gr
        br = self.books_route(text)
        if br:
            return br
        sr = self.study_route(text)
        if sr:
            return sr
        lr = self.life_route(text)
        if lr:
            return lr
        xr = self.extra_route(text)
        if xr:
            return xr
        ar = self.app_route(text)
        if ar:
            return ar
        dr = self.deadline_route(text)
        if dr:
            return dr
        if re.match(r"^(?:how(?:'s| is| much)? (?:my |the )?)?battery\b|^battery (?:level|left|status)", low):
            return self.battery_text()
        sr = screen_route(text)
        if sr:
            return self.ask_screen(sr, typed=True)
        mr = spotify_route(text)
        if mr:
            return self.music(*mr) or "On it..."
        nr = self.notes_route(text)
        if nr:
            return nr
        wr = web_route(text) if not re.match(r"(add|schedule|start)\b", cmd.lower()) else None
        if wr:
            return self.start_web(*wr)
        if re.match(r"(add|schedule)\b", low):
            r = self.tt_from_text(cmd)
            if r:
                return r
        if re.search(r"time left|how long|how much time|remaining", low):
            if s:
                left = int(max(0, s["planned"] - s["elapsed"]))
                return "%d min %02d s left on “%s”." % (left // 60, left % 60, s["task"])
            return "No session running. Say 'start reading 25' or double-click me."
        if re.search(r"time ?table|\bagenda\b|my day|today'?s plan|^(show |open |view |see |what'?s )?(my |the |today'?s )?schedule\s*\??$", low):
            self.open_hub("timetable")
            return "Today:\n" + self.tt_text()
        if re.search(r"^(what'?s |whats )?next\b|what now|what should i (do|work)", low):
            it = self.focus_item()
            return ("Next: %s at %s (%d min)." % (it["task"], it["start"], it["mins"])) if it \
                else "Nothing left on today's timetable. Add something: add 4pm study 45"
        m = re.match(r"start\b\s*(.*)", cmd.lower().strip())
        if m:
            if s:
                return "A session is already running. Say 'stop' first."
            rest = m.group(1)
            mm = re.search(r"(\d{1,3})\s*(?:min|mins|minutes|m)?\s*$", rest)
            length = int(mm.group(1)) if mm else int(self.cfg.get("last_minutes", 25))
            task = (rest[:mm.start()] if mm else rest).strip(" ,.-") or "Focus session"
            self.start_session(task.capitalize(), max(1, min(240, length)))
            return "Started %d min on “%s”. Go!" % (length, task.capitalize())
        if low in ("pause", "resume"):
            if not s:
                return "No session running."
            if (low == "pause") != s["paused"]:
                self.toggle_pause()
            return "Paused." if s["paused"] else "Resumed."
        if low in ("stop", "end", "quit session"):
            if not s:
                return "No session running."
            self.end_session(False)
            return "Session stopped."
        if re.search(r"how am i doing|stats|today'?s focus|how much have i", low):
            return "Today you've focused for %d min." % today_focus_minutes()
        if re.search(r"motivat|inspire me|cheer me|encourage me|i can'?t do this|too hard|give up", low):
            pool = MOTIV if s else [m for m in MOTIV if "{left}" not in m]
            return random.choice(pool).format(task=s["task"] if s else "your work",
                                              left=mins(max(0, s["planned"] - s["elapsed"])) if s else 0)
        if re.search(r"^tips?\b|focus (tip|advice)|help me focus|procrastinat", low):
            return random.choice(TIPS)
        if re.search(r"\b(jokes?|funny|laugh)\b", low):
            return random.choice(JOKES) + " " + random.choice(["Ehehe~", "Kon kon~!", "Ehehe~ kon!"])
        if re.search(r"(end|stop|finish|over).{0,6}\bbreak\b|back to work", low):
            if not self.brk:
                return "No break running."
            self.end_break(False)
            return "Break ended."
        if re.search(r"(take|start|begin|need|want|have|give me).{0,12}\bbreak\b|\bbreak (now|time)\b|^break$|^rest$", low):
            return self.start_break()
        if re.search(r"\b(export|pdf)\b.{0,30}(timetable|schedule|day|remarkable)|remarkable (pdf|export)|send .{0,20}remarkable", low):
            self.export_pdf()
            return "Exporting today's timetable as a PDF for your reMarkable..."
        if re.search(r"\bbreak\b|\btired\b|\brest\b", low):
            return random.choice(BREAK)
        if re.search(r"who are you|your name|what are you|what can you do", low):
            return ("%s I'm %s, a zenko: one of the good foxes who serve Inari, the kami of rice and good fortune. "
                    "I watch for distractions, run your timer, keep your timetable and cheer you on. "
                    "Type 'help' for commands." % (self.catchphrase(), self.fox_name()))
        if re.search(r"\b(zenko|inari|legend|foxfire|tails?)\b.{0,20}\?|tell me about (zenko|inari|the legend)|\blegend\b", low):
            return random.choice(LORE)
        m = re.match(r"(hi|hello|hey|heya|hiya|yo|sup|wassup|howdy|hola|ohayo|gm|good (?:morning|afternoon|evening))\b", low)
        if m:
            g = m.group(1)
            g = "Hi" if g in ("hi", "hello", "hey") else g.capitalize()
            nm = self.user_short()
            return "%s%s! Ready to focus? Type 'start studying 25' or open the timetable, ne~?" % (
                random.choice(["Kon kon~", "Konkon~", "Waai~", "Kon"]), (" " + nm) if nm else "")
        if re.match(r"(thanks|thank you|thx|ty\b|tysm)", low):
            return random.choice(["Ehehe~ anytime! Now back to work~kon!", "Kon kon~ happy to help! Back to it, ne?",
                                  "Yatta~ anytime! Now let's focus, kon!"])
        return learned_reply(text, fuzzy=True)


    # ---- theme ------------------------------------------------------------------
    def set_theme(self, name, announce=True):
        self.cfg["theme"] = name
        apply_theme(name)
        self.style_menus()
        self.pal = self.make_pal()
        self.images = {}
        self.orb_imgs = {}
        self._belly_key = self._tab_key = self._batt_key = None
        save_config(self.cfg)
        self.draw_panel()
        h = getattr(self, "hub", None)
        if h and h["win"].winfo_exists():
            page = h["page"]
            self.root.after(60, lambda: (self.hub_close(), self.open_hub(page)))
        if announce:
            self.say("New look: %s!" % dict(FUR_NAMES).get(name, name), 5)

    # ---- breaks -----------------------------------------------------------------
    def break_tick(self, dt, idle, now):
        if self.brk:
            self.brk["elapsed"] += dt
            if self.brk["elapsed"] >= self.brk["planned"]:
                self.end_break(True)
            return
        if idle >= 180:
            self.active_run = 0.0                  # you already stepped away long enough: that counts as a break
        elif idle < 120:
            self.active_run += dt
        limit = float(self.cfg.get("break_after_minutes", 50)) * 60
        if limit > 0 and self.active_run >= limit and now - self.last_break_nag > 900:
            self.last_break_nag = now
            self.set_mood("happy", 3)
            beep("ding")
            self.say(BREAK_NUDGE % (mins(self.active_run), int(self.cfg.get("break_minutes", 5))), 14)

    def start_break(self, minutes=None):
        m = int(minutes or self.cfg.get("break_minutes", 5))
        sess = self.session
        resume = bool(sess and not sess["paused"])
        if sess and resume:
            sess["paused"] = True
        self.brk = {"planned": m * 60.0, "elapsed": 0.0, "resume": resume}
        self.music_session_hook("break")
        self.active_run = 0.0
        self.alerted, self.dist_run = False, 0.0
        self.clear_mood()
        beep("happy")
        self.say("Break time! %d min. Stretch, drink water, look away from the screen." % m, 10)
        try:
            self.study_on_break()
        except Exception:
            pass
        return "Break started: %d min. I'll wake you when it's over." % m

    def end_break(self, done):
        b, self.brk = self.brk, None
        if not b:
            return
        sess = self.session
        if sess and b.get("resume"):
            sess["paused"] = False
        self.last_tick = time.monotonic()
        self.clear_mood()
        self.set_mood("happy", 3)
        beep("happy")
        self.say(("Break over! Ready to go?" if done else "Break ended. Back to it!") +
                 (" Your session is running again." if sess and b.get("resume") else ""), 8)
        self.pomo_break_done()

    # ---- auto-close distractions ------------------------------------------------
    def maybe_close(self, s, site, proc):
        if not self.cfg.get("auto_close", True):
            return
        limit = float(self.cfg.get("close_after_seconds", 60))
        warn_at = limit - min(15.0, limit / 2.0)
        if self.dist_run < warn_at:
            self.warned = False
            return
        if self.dist_run < limit:
            if not self.warned:
                self.warned = True
                self.say("Closing %s in %d seconds unless you go back to “%s”!" %
                         (site, int(limit - self.dist_run), clip(s["task"], 24)), 8)
                beep("nag")
            return
        title2, proc2 = foreground_info()                       # re-check: only close what you're still looking at
        if not self.is_distracting(title2, proc2):
            return
        self.dist_run, self.warned = 0.0, False
        if proc2 in BROWSERS:
            kind = "tab"
        elif proc2 in [p.lower() for p in self.cfg.get("distraction_apps", [])]:
            kind = "window"
        else:
            self.say("I can't close %s safely. Please close it yourself and get back to “%s”." %
                     (site, clip(s["task"], 24)), 8)
            return
        if close_distraction(kind):
            s["closed"] = s.get("closed", 0) + 1
            self.set_mood("alert", 2)
            beep("nag")
            self.say("Closed %s. Back to “%s”!" % (site, clip(s["task"], 28)), 8)
        else:
            self.say("I couldn't close %s. Please close it yourself." % site, 8)

    # ---- reMarkable-friendly export ---------------------------------------------
    def export_pdf(self):
        day = datetime.date.today() + datetime.timedelta(days=getattr(self, "tt_day", 0))
        rows = [(i["start"], i["task"], i["mins"], tt_done(i, day)) for i in tt_today(self.tt, day)]
        if not rows:
            self.say("Nothing to export yet. Add some timetable items first.", 6)
            return None
        folder = os.path.join(os.path.expanduser("~"), "Documents")
        if not os.path.isdir(folder):
            folder = DATA_DIR
        try:
            os.makedirs(folder, exist_ok=True)
            path = os.path.join(folder, "Zenko_timetable_%s.pdf" % day.isoformat())
            make_timetable_pdf(path, day.strftime("Timetable - %A %d %B %Y"), rows)
        except Exception as e:
            self.say("Couldn't save the PDF: %s" % e, 8)
            return None
        self.say("Saved %s in %s. Import it with the reMarkable desktop app." % (os.path.basename(path), folder), 12)
        beep("happy")
        try:
            os.startfile(folder)
        except Exception:
            pass
        return path

    # ---- offline smart brain (Ollama on this PC) --------------------------------
    def llm_context(self):
        sess = self.session
        ctx = "No focus session is running."
        if sess:
            ctx = "A focus session is running: %s, %d min left." % (
                sess["task"], mins(max(0, sess["planned"] - sess["elapsed"])))
        learned = learned_summary().replace("\n", " ") if self.cfg.get("learn_habits", True) and load_learned()["sessions"] else ""
        al = shorthand_aliases() if self.cfg.get("learn_style", True) else {}
        talk = ("The user's shorthand: " + ", ".join("%s = %s" % kv for kv in list(al.items())[-10:]) + ".") if al else ""
        return "%s %s Today's timetable: %s. Time now: %s. %s %s" % (
            self.user_profile_text(), ctx, self.tt_text().replace("\n", "; "), datetime.datetime.now().strftime("%H:%M"),
            ("What Zenko has learned about the user: " + learned) if learned else "", talk)

    def ask_llm(self, text):
        if not self.cfg.get("llm_enabled", True):
            self.chat_line("Fox", self.lookup_or_fallback(text, brain_hint=False))
            return
        if self.llm_busy:
            self.chat_line("Fox", "One thing at a time, please - still thinking!")
            return
        self.llm_busy = True
        self.chat_line("Fox", "(thinking...)")
        self.set_mood("happy", 1.5)
        threading.Thread(target=self.llm_worker, daemon=True,
                         args=(text, self.llm_context(), self.cfg.get("llm_model") or "llama3.2:3b",
                               list(self.llm_hist))).start()

    def llm_worker(self, text, ctx, model, hist):
        try:
            names = brain_names()
            if names is None:
                self.llm_q.put(("none", text))
                return
            if not names:
                self.llm_q.put(("err", "Ollama is running but has no model yet. Open Command Prompt and run:  "
                                       "ollama pull llama3.2:3b"))
                return
            if model not in names:
                base = model.split(":")[0]
                model = ([n for n in names if n.split(":")[0] == base] or names)[0]
            msgs = [{"role": "system", "content": BRAIN_PROMPT + "\n\nContext: " + ctx}] + hist + \
                   [{"role": "user", "content": text}]
            j = _ollama_json("/api/chat", {"model": model, "messages": msgs, "stream": False, "format": "json", "online": True,
                                           "options": {"temperature": 0.2, "num_predict": 300}}, 180)
            self.llm_q.put(("ok", (text, (j.get("message") or {}).get("content", ""))))
        except Exception as e:
            self.llm_q.put(("err", "The smart brain had a problem (%s)." % e))

    def poll_llm(self):
        try:
            while True:
                kind, payload = self.llm_q.get_nowait()
                self.llm_busy = False
                if kind == "none":
                    msg = self.lookup_or_fallback(payload)
                elif kind == "err":
                    msg = payload
                else:
                    text, raw = payload
                    d = parse_brain(raw)
                    self.llm_hist += [{"role": "user", "content": text}, {"role": "assistant", "content": raw}]
                    self.llm_hist = self.llm_hist[-6:]
                    self._llm_text = text
                    if str(d.get("action") or "chat").lower() == "chat" and self.can_auto_search() and wants_lookup(text) and \
                            re.search(r"not sure|don'?t know|do not know|no idea|can'?t (?:browse|access|check)|cannot (?:browse|access)|"
                                      r"as of my|my (?:knowledge|training)|real[- ]time|i'?m unable|not able to", str(d.get("reply") or ""), re.I):
                        msg = self.start_web("search", (text, text, False))   # the brain wasn't sure: look it up instead
                    else:
                        msg = self.run_action(d.get("action"), d.get("args"), d.get("reply"))
                self.chat_line("Fox", msg)
                self.say(md_plain(msg).split("\n")[0], 12)
                self.set_mood("happy", 2)
                beep("sad" if kind == "err" else "hello")
        except queue.Empty:
            pass
        self.root.after(250, self.poll_llm)

    def can_auto_search(self):
        return bool(self.cfg.get("web_enabled", True) and self.cfg.get("auto_search", True))

    def lookup_or_fallback(self, q, brain_hint=True):
        """She doesn't know: search the web for questions and topics, otherwise admit it nicely."""
        if self.can_auto_search() and wants_lookup(q):
            return self.start_web("search", (q, q, False))
        return random.choice(FALLBACK) + (NO_BRAIN if brain_hint or not self.cfg.get("llm_enabled", True) else "")

    def run_action(self, act, args, reply):
        act = str(act or "chat").lower().strip()
        args = args if isinstance(args, dict) else {}
        reply = str(reply or "").strip()

        def num(v, d):
            try:
                return int(float(v))
            except (TypeError, ValueError):
                return d
        if act == "start_session":
            if self.session:
                return "A session is already running. Say 'stop' first."
            task = str(args.get("task") or "Focus session").strip()[:60] or "Focus session"
            m = max(1, min(240, num(args.get("minutes"), int(self.cfg.get("last_minutes", 25)))))
            self.start_session(task[:1].upper() + task[1:], m)
            return reply or "Started %d min on “%s”. Go!" % (m, task)
        if act == "add_item":
            st = parse_clock(str(args.get("time") or ""))
            task = str(args.get("task") or "").strip()
            if not st or not task:
                return reply or "I couldn't work out the time or the task. Try: add 4pm study 45"
            tomorrow = bool(args.get("tomorrow"))
            day = datetime.date.today() + datetime.timedelta(days=1 if tomorrow else 0)
            ln = max(1, min(480, num(args.get("minutes"), 30)))
            self.tt.append({"start": st, "mins": ln, "task": task[:1].upper() + task[1:], "daily": bool(args.get("daily")),
                            "date": day.isoformat(), "done": []})
            save_tt(self.tt)
            self.tt_refresh()
            return reply or "Added %s – %s (%d min)." % (st, task, ln)
        direct = {"show_timetable": "timetable", "time_left": "time left", "next": "next", "stats": "stats",
                  "pause": "pause", "resume": "resume", "stop": "stop"}
        if act in direct:
            return self.answer_local(direct[act]) or reply or "Done."
        if act == "break":
            return self.start_break(num(args.get("minutes"), 0) or None)
        if act == "music":
            do = str(args.get("do") or "play").lower()
            if do == "volume":
                return self.music("volume", num(args.get("volume"), 50)) or "On it..."
            if do in ("stop", "off"):
                do = "pause"
            if do not in ("play", "pause", "next", "previous", "now"):
                do = "play"
            return self.music(do, str(args.get("query") or "") if do == "play" else None) or "On it..."
        if act == "open_app":
            return open_app(str(args.get("name") or ""))
        if act == "deadlines":
            return self.deadline_route("what's due") or reply
        if act == "add_deadline":
            try:
                d = datetime.date.fromisoformat(str(args.get("date", ""))[:10])
            except ValueError:
                return "When is it? e.g. 'add exam renal 12 Dec'."
            title = str(args.get("title") or "Deadline").strip()
            tm = str(args.get("time") or "")
            self.add_deadline(title, d.isoformat(), tm if re.match(r"^\d\d:\d\d$", tm) else "")
            return "Added: %s on %s (%s)." % (title, d.strftime("%a %d %b"), when_text(d.isoformat()))
        if act == "screen":
            return self.ask_screen(str(args.get("question") or "What is on my screen?"), typed=True)
        if act == "notes":
            do = str(args.get("do") or "list").lower()
            if do == "list":
                return self.notes_route("notes")
            if do not in ("show", "summary", "quiz", "ask"):
                do = "summary"
            return self.notes_llm(do, str(args.get("name") or ""), str(args.get("question") or ""))
        if act in ("weather", "time", "news", "search", "convert"):
            if act == "convert":
                try:
                    arg = (float(args.get("amount")), str(args.get("from") or ""), str(args.get("to") or ""))
                except (TypeError, ValueError):
                    return reply or "Try: convert 100 usd to eur"
            elif act == "news":
                arg = str(args.get("topic") or "").strip()
            elif act == "search":
                arg = (str(args.get("query") or self._llm_text or "").strip(), self._llm_text or "", False)
            else:
                arg = str(args.get("city") or "").strip()
            self.start_web(act, arg)
            return reply or "Checking..."
        return reply or random.choice(FALLBACK)

    # ---- the main Zenko window (sidebar app) ------------------------------------
    def tint(self, hex_color, amt):
        c = hex_color.lstrip("#")
        v = [int(c[i:i + 2], 16) for i in (0, 2, 4)]
        v = [int(x + (255 - x) * amt) if amt >= 0 else int(x * (1 + amt)) for x in v]
        return "#%02x%02x%02x" % tuple(max(0, min(255, x)) for x in v)

    def round_frame(self, parent, bg=None, edge=None, r=12, shape="round", pad=4, notch=0):
        """A frame that looks like a rounded pixel card: a canvas behind its children draws the shape."""
        bg = bg or T["card"]
        edge = edge or LINE
        try:
            pbg = parent.cget("bg")
        except tk.TclError:
            pbg = PAPER
        try:
            pbg = getattr(parent, "_zk_fill", None) or pbg
        except Exception:
            pass
        f = tk.Frame(parent, bg=pbg, padx=pad, pady=pad)
        f._zk_fill = bg
        cv = tk.Canvas(f, bg=pbg, highlightthickness=0, bd=0)
        cv._zk_bg = True
        cv.place(x=0, y=0, relwidth=1, relheight=1)
        cv.tk.call("lower", cv._w)

        def draw(_e=None):
            cv.delete("all")
            W, H = cv.winfo_width(), cv.winfo_height()
            if W < 8 or H < 8:
                return
            rbox(cv, 0, 0, W - 1, H - 1, r, fill=bg, outline=edge, shape=shape, notch=notch)
            k = SHAPES.get(shape, SHAPES["round"])(r)[0][1]        # a faint lit rim along the top edge
            cv.create_line(min(k + 2, W // 2), 1, max(W - 1 - min(r, W // 2) - 2, W // 2), 1, fill=_mixhex(bg, INK, 0.10))
        cv.bind("<Configure>", draw)
        return f

    def hub_card(self, parent, title=None, bg=None, shape="round"):
        if getattr(self, "_book_ctx", False):
            return self.book_section(parent, title)
        bg = bg or T["card"]
        f = self.round_frame(parent, bg, LINE, 14 if shape == "leaf" else 12, shape)
        if title:
            row = tk.Frame(f, bg=bg)
            row.pack(fill="x", padx=16, pady=(12, 6))
            tk.Label(row, text="\u25c6", bg=bg, fg=GOLD, font=(FONT_UI, 7)).pack(side="left", padx=(0, 6))
            tk.Label(row, text=title, bg=bg, fg=GOLD, font=(FONT_TITLE or FONT_UI, 13 if FONT_TITLE else 11, "bold"), anchor="w").pack(side="left")
        return f

    def glow_bar(self, cv, x1, y1, x2, y2, frac):
        """A slim progress bar: dark trough, foxfire fill with a bright head."""
        rbox(cv, x1, y1, x2, y2, 99, outline=LINE, fill=_mixhex(T["card"], "#000000", 0.25), shape="pill")
        if frac > 0:
            fx = x1 + 1 + (x2 - x1 - 2) * min(1.0, frac)
            if fx - x1 > 6:
                rbox(cv, x1 + 1, y1 + 1, fx, y2 - 1, 99, fill=ORANGE, shape="pill")
                cv.create_line(x1 + 5, y1 + 2, fx - 4, y1 + 2, fill=_mixhex(ORANGE, "#ffffff", 0.4))
            cv.create_oval(fx - 3, y1 - 1, fx + 3, y2 + 1, outline="", fill=GLOW)

    def mix(self, c1, c2, t):
        a, b = c1.lstrip("#"), c2.lstrip("#")
        v = [int(int(a[i:i + 2], 16) * (1 - t) + int(b[i:i + 2], 16) * t) for i in (0, 2, 4)]
        return "#%02x%02x%02x" % tuple(v)

    def fade_bg(self, widgets, c1, c2, steps=7, delay=22):
        def step(i):
            col = self.mix(c1, c2, min(1.0, i / float(steps)))
            for wd in widgets:
                try:
                    wd.config(bg=col)
                except tk.TclError:
                    return
            if i < steps:
                self.root.after(delay, lambda: step(i + 1))
        step(1)

    def style_titlebar(self, win):
        """Windows 10/11: colour the title bar and window border to match the app (silently ignored elsewhere)."""
        if not IS_WIN:
            return
        try:
            win.update_idletasks()
            hwnd = ctypes.windll.user32.GetParent(win.winfo_id()) or win.winfo_id()
            dwm = ctypes.windll.dwmapi

            def put(attr, val):
                v = ctypes.c_int(val)
                dwm.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(v), 4)

            def bgr(h):
                h = h.lstrip("#")
                return int(h[4:6], 16) << 16 | int(h[2:4], 16) << 8 | int(h[0:2], 16)
            put(20, 1)                  # dark title bar
            put(35, bgr(NIGHT))         # caption colour
            put(36, bgr(INK))           # caption text
            put(34, bgr(GOLD))          # window border
            put(33, 2)                  # rounded corners
        except Exception:
            pass

    def hub_scroller(self, pg):
        box = tk.Frame(pg, bg=PAPER)
        box.pack(fill="both", expand=True)
        box.grid_rowconfigure(0, weight=1)
        box.grid_columnconfigure(0, weight=1)
        cv = tk.Canvas(box, bg=PAPER, highlightthickness=0)
        sb = tk.Scrollbar(box, command=cv.yview)
        cv.configure(yscrollcommand=sb.set)
        cv.grid(row=0, column=0, sticky="nsew")
        sb.grid(row=0, column=1, sticky="ns")
        inner = tk.Frame(cv, bg=PAPER)
        wid = cv.create_window((0, 0), window=inner, anchor="nw")

        def conf(_e=None):
            cv.configure(scrollregion=cv.bbox("all"))
            if inner.winfo_reqheight() > cv.winfo_height() + 2:
                sb.grid()
            else:
                sb.grid_remove()
        cv.bind("<Configure>", lambda e: (cv.itemconfigure(wid, width=e.width), conf()))
        inner.bind("<Configure>", conf)
        self.hub["scrollers"].append(cv)
        return inner

    def open_hub(self, page=None):
        h = getattr(self, "hub", None)
        if h and h["win"].winfo_exists():
            h["win"].deiconify()
            h["win"].lift()
            try:
                h["win"].focus_force()
            except tk.TclError:
                pass
            self.hub_show(page or h["page"])
            return
        w = tk.Toplevel(self.root)
        w.title(APP_NAME)
        w.configure(bg=NIGHT)
        if time.monotonic() - getattr(self, "_hub_closed_t", 0.0) > 1.5:      # not when it's just being rebuilt
            ui_sound("open")
        sw, sh = w.winfo_screenwidth(), w.winfo_screenheight()
        W, H = min(int(sw * 0.88), 1320), min(int(sh * 0.88), 900)
        w.geometry("%dx%d+%d+%d" % (W, H, (sw - W) // 2, max(0, (sh - H) // 3)))
        w.minsize(min(980, sw - 40), min(640, sh - 80))
        try:
            self.app_icon = tk.PhotoImage(data=base64.b64encode(icon_png(64, self.cfg.get("theme", "snow"))))
            w.iconphoto(True, self.app_icon)
        except Exception:
            pass
        ico = os.path.join(getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__))), "zenko.ico")
        if IS_WIN and os.path.exists(ico):
            try:
                w.iconbitmap(ico)
            except tk.TclError:
                pass
        borderless = bool(self.cfg.get("borderless", True))
        if borderless:
            self.make_borderless(w)
        else:
            self.style_titlebar(w)
        w.protocol("WM_DELETE_WINDOW", self.hub_close)

        side = tk.Frame(w, bg=NIGHT, width=244)
        side.pack(side="left", fill="y")
        side.pack_propagate(False)
        sb = tk.Canvas(side, bg=NIGHT, highlightthickness=0)
        sb.place(x=0, y=0, relwidth=1, relheight=1)
        self.hub = {"win": w, "pages": {}, "nav": {}, "page": None, "scrollers": [], "snow": sb, "flakes": [],
                    "logo_cache": {}, "tip_t0": time.monotonic(), "tip_i": random.randrange(len(TIPS)),
                    "anim": 0, "blink_at": time.monotonic() + 2, "blink_until": 0.0, "logo_key": None,
                    "logo_zoom": 2 if H >= 780 else 1, "stars": [], "hover": None, "pill_y": None, "pill_to": None}
        self.hub_status = _CanvasText(sb)
        right = tk.Frame(w, bg=PAPER)
        right.pack(side="left", fill="both", expand=True)
        if borderless:
            self.hub_titlebar(right)
            self.hub_make_drag(sb)
            self.hub_resize_edges(w)
            w.after(60, lambda: self.round_corners(w))
        w.after(300, lambda: drop_files_hook(w, self.on_files_dropped))
        self.hub_fade_in(w)
        tk.Frame(right, bg=LINE, height=1).pack(side="bottom", fill="x")
        tipbar = tk.Frame(right, bg=NIGHT)
        tipbar.pack(side="bottom", fill="x")
        self.hub["tip"] = tk.Label(tipbar, text="", bg=NIGHT, fg=NIGHT, font=(FONT_UI, 10), anchor="w", padx=18, pady=7)
        self.hub["tip"].pack(fill="x")
        tipbar.lift()
        stage = tk.Frame(right, bg=PAPER)
        stage.pack(fill="both", expand=True)
        self.hub["main"] = stage
        self.hub["navkeys"] = [("home", "Home"), ("timetable", "Timetable"), ("deadlines", "Upcoming"), ("reminders", "Reminders"),
                               ("notebook", "Study books"),
                               ("daily", "Daily"), ("exercise", "Exercise"), ("garden", "Zen garden"),
                               ("map", "World map"), ("screen", "Screen time"), ("chat", "Chat"), ("notes", "Notes"), ("you", "You"), ("customize", "Customize"),
                               ("settings", "Settings")]
        sb.bind("<Configure>", lambda e: self.hub_side_draw())
        sb.bind("<Motion>", self.hub_side_motion, add="+")
        sb.bind("<Leave>", lambda e: self.hub_hover(None, False))
        sb.bind("<ButtonRelease-1>", self.hub_side_click, add="+")

        def wheel(e):
            try:
                wd = w.winfo_containing(e.x_root, e.y_root)
            except Exception:
                return
            while wd is not None:
                if wd in self.hub["scrollers"]:
                    wd.yview_scroll(-1 if e.delta > 0 else 1, "units")
                    return
                wd = getattr(wd, "master", None)
        w.bind_all("<MouseWheel>", wheel)
        self.hub_show(page or "home")
        self.hub_tick()
        self.hub_anim()

