    def hub_side_layout(self):
        h = self.hub
        z = h["logo_zoom"]
        top = 14
        logo_h = H_ * z
        title_y = top + logo_h + 8
        nav_y = title_y + 66
        try:
            hh = h["snow"].winfo_height()
        except Exception:
            hh = 900
        n = len(h.get("navkeys") or []) or 9
        rowh = 42 if hh >= nav_y + n * 42 + 160 else (36 if hh >= nav_y + n * 36 + 130 else 32)
        return z, top, title_y, nav_y, rowh

    def hub_side_draw(self):
        """Paint the night sky: gradient, stars, moon, hills and a torii gate; then the menu."""
        h = self.hub
        if not h:
            return
        cv = h["snow"]
        W, Hh = cv.winfo_width(), cv.winfo_height()
        if W < 50 or Hh < 50:
            return
        cv.delete("bg", "nav", "deco")
        top, bot = T["night"], T["night2"]
        for y in range(0, Hh, 2):
            cv.create_rectangle(0, y, W, y + 2, fill=_mixhex(top, bot, y / float(Hh)), outline="", tags="bg")
        rnd = random.Random(7)
        h["stars"] = []
        for i in range(46):
            x, y = rnd.uniform(4, W - 4), rnd.uniform(4, Hh * 0.8)
            s = rnd.choice((1, 1, 1, 2, 2, 3))
            it = cv.create_rectangle(x, y, x + s, y + s, fill=_mixhex(top, INK, rnd.uniform(0.25, 0.8)), outline="", tags="bg")
            h["stars"].append((it, rnd.uniform(0, 6.28), rnd.uniform(0.6, 2.2)))
        # crescent moon with a soft halo
        mx_, my_ = W - 46, 46
        if not h.get("moon"):
            moon = _mixhex(GOLD, "#ffffff", 0.55)
            h["moon"] = (aa_photo(72, 72, [("circle", 36, 36, 33, (GOLD, 0.05)), ("circle", 36, 36, 26, (GOLD, 0.07)),
                                           ("circle", 36, 36, 20, (GOLD, 0.08))]),
                         aa_photo(72, 72, [("circle", 36, 36, 15, moon), ("circle", 30, 36, 4, (_mixhex(moon, GOLD, 0.5), 0.5)),
                                           ("circle", 39, 44, 2.5, (_mixhex(moon, GOLD, 0.5), 0.45)),
                                           ("circle", 45, 30, 14, None)]))
        cv.create_image(mx_ - 36, my_ - 36, image=h["moon"][0], anchor="nw", tags="bg")
        cv.create_image(mx_ - 36, my_ - 36, image=h["moon"][1], anchor="nw", tags="bg")
        # hills and a torii gate at the bottom
        far = _mixhex(bot, ORANGE, 0.10)
        near = _mixhex(bot, "#000000", 0.45)
        pts = [0, Hh]
        for x in range(0, W + 12, 12):
            pts += [x, Hh - 64 - 18 * math.sin(x / 38.0) - 8 * math.sin(x / 13.0)]
        cv.create_polygon(pts + [W, Hh], fill=far, outline="", tags="bg")
        pts = [0, Hh]
        for x in range(0, W + 12, 12):
            pts += [x, Hh - 36 - 10 * math.sin(x / 27.0 + 1.3)]
        cv.create_polygon(pts + [W, Hh], fill=near, outline="", tags="bg")
        red = _mixhex("#e8463c", top, 0.18)
        dark = _mixhex(red, "#000000", 0.35)
        tx, ty, k = 40, Hh - 40, 3
        for (x, y, w_, h_, col) in ((-1, -21, 26, 2, red), (0, -19, 24, 1, dark), (-2, -22, 2, 1, red), (25, -22, 2, 1, red),
                                    (2, -16, 20, 2, red), (4, -19, 2, 19, red), (18, -19, 2, 19, red), (11, -19, 2, 3, red),
                                    (4, -14, 2, 14, dark), (18, -14, 2, 14, dark), (3, -1, 4, 1, near), (17, -1, 4, 1, near)):
            cv.create_rectangle(tx + x * k / 2.0, ty + y * k / 2.0, tx + (x + w_) * k / 2.0, ty + (y + h_) * k / 2.0,
                                fill=col, outline="", tags="bg")
        for lx in (W - 60, W - 30):                                 # two little stone lanterns with a warm glow
            ly = Hh - 30
            cv.create_rectangle(lx - 1, ly - 14, lx + 7, ly - 12, fill=near, outline="", tags="bg")
            cv.create_rectangle(lx, ly - 12, lx + 6, ly - 6, fill=_mixhex(GOLD, "#ff9a3a", 0.3), outline="", tags="bg")
            cv.create_rectangle(lx + 1, ly - 6, lx + 5, ly, fill=near, outline="", tags="bg")
        # title
        z, top_, title_y, nav_y, rowh = self.hub_side_layout()
        cv.create_text(W // 2, title_y + 16, text="  ".join(self.fox_name().upper()), fill=GOLD,
                       font=(FONT_UI, 20 if len(self.fox_name()) <= 7 else 14, "bold"), tags="deco")
        jp = _jp_font(self.root)
        sub = self.catchphrase().lower()
        if jp:
            cv.create_text(W // 2, title_y + 44, text="\u5584\u72d0  \u00b7  " + sub, fill=_mixhex(top, INK, 0.6),
                           font=(jp, 9), tags="deco")
        else:
            cv.create_text(W // 2, title_y + 44, text=sub, fill=_mixhex(top, INK, 0.6), font=(FONT_UI, 9), tags="deco")
        cv.create_line(W // 2 - 70, title_y + 58, W // 2 + 70, title_y + 58, fill=_mixhex(top, GOLD, 0.35), tags="deco")
        cv.create_polygon(W // 2, title_y + 55, W // 2 + 3, title_y + 58, W // 2, title_y + 61, W // 2 - 3, title_y + 58,
                          fill=GOLD, outline="", tags="deco")
        h["logo_key"] = None
        if "logo_items" not in h or not cv.find_withtag("logo"):
            h["logo_items"] = (cv.create_image(0, 0, anchor="nw", tags="logo"), cv.create_image(0, 0, anchor="nw", tags="logo"))
        lw = W_ * z
        for it in h["logo_items"]:
            cv.coords(it, (W - lw) // 2 + 6, top_)
        cv.tag_raise("logo")
        self.hub_side_nav()
        self.hub_status.place(24, Hh - 150, W - 40)
        cv.tag_raise("flake")
        cv.tag_raise("status")

    def hub_side_nav(self):
        h = self.hub
        cv = h["snow"]
        W = cv.winfo_width()
        cv.delete("nav")
        z, top_, title_y, nav_y, rowh = self.hub_side_layout()
        base = T["night"]
        page = h.get("page")
        keys = [k for k, _ in h["navkeys"]]
        # the selected 'pill' (it glides between items)
        if page in keys:
            ty = nav_y + keys.index(page) * rowh
            y = h["pill_y"] if h["pill_y"] is not None else ty
            h["pill_to"] = ty
            fillc, edge = _mixhex(base, ORANGE, 0.30), _mixhex(base, GOLD, 0.55)
            rbox(cv, 14, y + 3, W - 14, y + rowh - 3, 99, fill=fillc, outline=edge, tags=("nav", "pill"), shape="pill")
            cy_ = y + rowh // 2
            cv.create_polygon(W - 30, cy_ - 4, W - 26, cy_, W - 30, cy_ + 4, W - 34, cy_, fill=GOLD, outline="", tags=("nav", "pill"))
            h["pill_y"] = y
        hv = h.get("hover")
        if hv in keys and hv != page:
            y = nav_y + keys.index(hv) * rowh
            rbox(cv, 14, y + 3, W - 14, y + rowh - 3, 99, fill=_mixhex(base, INK, 0.08), outline=_mixhex(base, INK, 0.16),
                 tags="nav", shape="pill")
        for i, (key, label) in enumerate(h["navkeys"]):
            y = nav_y + i * rowh
            on = key == page
            col = INK if on else (_mixhex(base, INK, 0.85) if key == hv else _mixhex(base, INK, 0.6))
            icol = GOLD if on else col
            for r, row in enumerate(self.NAV_ICONS.get(key, [])):
                for c_, ch in enumerate(row):
                    if ch == "#":
                        x0, y0 = 32 + c_ * 2, y + rowh // 2 - 9 + r * 2
                        cv.create_rectangle(x0, y0, x0 + 2, y0 + 2, fill=icol, outline="", tags="nav")
            cv.create_text(62, y + rowh // 2, text=label, anchor="w", fill=col,
                           font=(FONT_UI, 12, "bold" if on else "normal"), tags="nav")

    def hub_side_key(self, y):
        h = self.hub
        if not h:
            return None
        z, top_, title_y, nav_y, rowh = self.hub_side_layout()
        i = int((y - nav_y) // rowh)
        if y >= nav_y and 0 <= i < len(h["navkeys"]):
            return h["navkeys"][i][0]
        return None

    def hub_side_motion(self, e):
        k = self.hub_side_key(e.y)
        if self.hub and k != self.hub.get("hover"):
            self.hub_hover(k, True)
        try:
            self.hub["snow"].config(cursor="hand2" if k else "")
        except (tk.TclError, TypeError):
            pass

    def hub_side_click(self, e):
        h = self.hub
        if not h or (h.get("drag_moved")):
            return
        k = self.hub_side_key(e.y)
        if k:
            if k != h.get("page"):
                ui_sound("nav")
            self.hub_show(k)

    def hub_hover(self, key, on):
        h = self.hub
        if not h:
            return
        h["hover"] = key if on else None
        self.hub_side_nav()

    def hub_close(self):
        h = getattr(self, "hub", None)
        if h:
            if self.tt_win is h["pages"].get("timetable"):
                self.tt_win = None
            self.chat = None
            self.hub_music = None
            self.notes_widgets = None
            self.notes_body = None
            self.dl_body = None
            self.dl_status_lab = None
            self.cz_cv = None
            self.up_cv = None
            self.daily_body = None
            try:
                self.root.unbind_all("<MouseWheel>")
                h["win"].destroy()
            except tk.TclError:
                pass
            self._hub_closed_t = time.monotonic()
        self.hub = None

    def hub_show(self, name):
        h = self.hub
        if not h or not h["win"].winfo_exists():
            return
        old = h["page"]
        if old == name:
            return self.hub_after_show(name)
        order = ["home", "timetable", "deadlines", "reminders", "notebook", "daily", "exercise", "garden", "map", "screen", "chat", "notes", "you", "customize",
                 "settings"]
        direction = 1 if (old is None or order.index(name) > order.index(old)) else -1
        h["anim"] += 1
        token = h["anim"]
        if old and old in h["pages"]:
            h["pages"][old].place_forget()
        h["page"] = name
        if name not in h["pages"]:
            pg = tk.Frame(h["main"], bg=PAPER)
            h["pages"][name] = pg
            getattr(self, "hub_build_" + name)(pg)
        pg = h["pages"][name]
        self.hub_side_nav()
        steps = 9

        def slide(i):
            if not self.hub or self.hub["anim"] != token or not pg.winfo_exists():
                return
            t = i / float(steps)
            off = int(46 * (1 - t) ** 3 * direction) if old else 0
            pg.place(x=off, y=0, relwidth=1, relheight=1)
            if i < steps:
                pg.after(16, lambda: slide(i + 1))
        slide(0)
        self.hub_after_show(name)

    def hub_after_show(self, name):
        h = self.hub
        if name == "notes" and not (rm_tool() and rm_paired()) and getattr(self, "notes_body", None) is not None:
            self.notes_render()
        if name == "timetable":
            self.tt_refresh()
        elif name == "home":
            self.hub_refresh_home(force=True)
            self.hub_intro()
        elif name == "chat" and self.chat:
            self.chat["entry"].focus_set()
        elif name == "daily" and getattr(self, "_daily_dirty", False):
            self.daily_render()
        elif name == "notebook" and self.nb:
            self.nb_refresh()

    def hub_intro(self):
        """Count-up numbers and growing bars each time Home is shown."""
        t0 = time.monotonic()
        self._count_until = t0 + 0.7
        fm = today_focus_minutes()
        rows = tt_today(self.tt, datetime.date.today())
        done = sum(1 for i in rows if tt_done(i, datetime.date.today()))
        token = self.hub["anim"]

        def step():
            if not self.hub or self.hub["anim"] != token or "home" not in self.hub["pages"]:
                return
            t = min(1.0, (time.monotonic() - t0) / 0.65)
            e = 1 - (1 - t) ** 3
            try:
                self.hub_stat["focus"][0].config(text="%d min" % round(fm * e))
                self.hub_stat["plan"][0].config(text="%d / %d" % (round(done * e), len(rows)))
                self.hub_draw_week(e)
            except tk.TclError:
                return
            if t < 1.0:
                self.root.after(28, step)
        step()

    def hub_anim(self):
        h = getattr(self, "hub", None)
        if not h or not h["win"].winfo_exists():
            return
        now = time.monotonic()
        cv = h["snow"]
        W, Hh = cv.winfo_width(), cv.winfo_height()
        if W < 100:
            h["win"].after(50, self.hub_anim)
            return
        # --- twinkling stars
        for it, ph, sp in h["stars"][::3]:
            a = 0.5 + 0.5 * math.sin(now * sp + ph)
            cv.itemconfigure(it, fill=_mixhex(T["night"], INK, 0.2 + 0.65 * a))
        # --- drifting particles: snow, sakura petals, fireflies, embers or star-dust
        style = PARTICLES.get(self.cfg.get("theme", "snow"), "snow")
        col = {"snow": "#e6eeff", "petals": "#ffb8d6", "stars": GOLD, "fireflies": _mixhex(GOLD, GLOW, 0.3),
               "embers": ORANGE, "leaves": "#d9703a", "rain": "#9fb8e8"}.get(style, "#e6eeff")
        if h.get("pstyle") != style:
            cv.delete("flake")
            h["flakes"], h["pstyle"] = [], style
        if not self.cfg.get("sidebar_particles", True):
            if h["flakes"]:
                cv.delete("flake")
                h["flakes"] = []
        else:
            if not h["flakes"]:
                for _ in range(26):
                    x, y = random.uniform(0, W), random.uniform(0, Hh)
                    sz = random.choice((2, 2, 3, 3, 4))
                    shade_ = self.mix(T["night"], col, random.uniform(0.45, 0.95))
                    it = cv.create_rectangle(x, y, x + sz, y + sz, fill=shade_, outline="", tags="flake")
                    h["flakes"].append([it, x, y, random.uniform(0.3, 1.1), random.uniform(0, 6.28), sz, shade_])
            for f in h["flakes"]:
                it, x, y, v, ph, sz, c0 = f
                ph += 0.05
                if style in ("stars", "fireflies"):
                    a = abs(math.sin(ph * (0.5 if style == "stars" else 0.9)))
                    cv.itemconfigure(it, fill=self.mix(T["night"], col, 0.15 + 0.85 * a))
                    if style == "fireflies":
                        x += 0.35 * math.sin(ph * 0.7)
                        y -= 0.18 * v
                elif style == "rain":
                    y += 5.5 + 2.5 * v
                else:
                    y += v * (1 if style in ("snow", "petals", "leaves") else -1) * (0.55 if style in ("petals", "leaves") else 0.9)
                    x += (0.45 if style in ("petals", "leaves") else 0.2) * math.sin(ph)
                if y > Hh + 6:
                    y, x = -6, random.uniform(0, W)
                elif y < -6:
                    y, x = Hh + 6, random.uniform(0, W)
                f[1], f[2], f[4] = x, y, ph
                w_ = sz + (1 if style in ("petals", "leaves") and int(ph * 2) % 2 else 0)
                if style == "rain":
                    cv.coords(it, x, y, x + 1, y + 3 * sz)
                else:
                    cv.coords(it, x, y, x + w_, y + sz)
            cv.tag_raise("flake")
        # --- the menu pill glides to the chosen item
        if h.get("pill_to") is not None and h.get("pill_y") is not None and abs(h["pill_to"] - h["pill_y"]) > 0.5:
            dy = (h["pill_to"] - h["pill_y"]) * 0.32
            h["pill_y"] += dy if abs(dy) > 0.5 else (h["pill_to"] - h["pill_y"])
            cv.move("pill", 0, 0)
            self.hub_side_nav()
        # --- animated logo fox (tails sway, blinks, wears what the desktop fox wears)
        mood = self.current_mood()
        state = mood if mood in STATES else "idle"
        if state in ("idle", "focus"):
            if now >= h["blink_at"]:
                h["blink_until"] = now + 0.15
                h["blink_at"] = now + random.uniform(2.5, 5.5)
            if now < h["blink_until"]:
                state = "blink"
        tf = int(now / (0.08 if mood == "alert" else 0.17)) % 8
        frame = int(now / 0.6) % 2
        acc = self.accessories()
        curl = mood == "sleep" and self.is_curled()
        if curl:
            state, acc = "curl", tuple(a for a in acc if a == "headphones")
            frame = int(now / 1.6) % 2
        n = self.tail_count()
        lhx = 0
        if state in ("idle", "focus", "blink"):
            sw = math.sin(now * 0.8)
            lhx = 1 if sw > 0.55 else (-1 if sw < -0.55 else 0)
        key = (state, tf if not curl else -1, frame, acc, n, lhx)
        if key != h["logo_key"] and h.get("logo_items"):
            h["logo_key"] = key
            z = h["logo_zoom"]
            cache = h["logo_cache"]
            if len(cache) > 120:
                cache.clear()
            tk_ = ("t", n, tf)
            if not curl and tk_ not in cache:
                cache[tk_] = sprite_photo([build_tails(n, tf, shadow=False)], self.pal, z)
            bk = ("b", state, frame if state in ("happy", "sleep", "alert", "alert2", "curl") else 0, acc, n if curl else 0, lhx)
            if bk not in cache:
                rows = build_curl(bk[2], acc, n) if curl else build_frame(state, "up", bk[2], None, acc, lhx)
                cache[bk] = sprite_photo([rows], self.pal, z)
            ti, bi = h["logo_items"]
            if curl:
                cv.itemconfigure(ti, state="hidden")
            else:
                cv.itemconfigure(ti, image=cache[tk_], state="normal")
            cv.itemconfigure(bi, image=cache[bk])
            off = 0
            z_, top_, *_ = self.hub_side_layout()
            x0 = (W - W_ * z_) // 2 + 6
            for it in (ti, bi):
                cv.coords(it, x0, top_ + off)
        # --- pulsing start button
        btn = getattr(self, "hub_go_btn", None)
        if btn is not None and h["page"] == "home" and not self.session:
            try:
                if btn.winfo_exists():
                    t = round((1 + math.sin(now * 3.2)) / 2 * 10) / 10.0      # 11 shades: redraw only when it shows
                    btn.config(bg=self.mix(ORANGE, _mixhex(ORANGE, "#ffffff", 0.3), t))
            except tk.TclError:
                pass
        # --- rotating tip with fade
        e = now - h["tip_t0"]
        if e > 9.0:
            h["tip_t0"] = now
            h["tip_i"] = (h["tip_i"] + 1) % len(TIPS)
            e = 0
        a = min(1.0, e / 0.6) if e < 8.0 else max(0.0, (9.0 - e) / 1.0)
        tip = ("\u2726  " + TIPS[h["tip_i"]], self.mix(NIGHT, _mixhex(INK, GOLD, 0.25), round(0.85 * a, 2)))
        if h.get("tip_now") != tip:
            h["tip_now"] = tip
            h["tip"].config(text=tip[0], fg=tip[1])
        # --- chat "thinking" dots
        c = self.chat
        if c and c.get("status") is not None:
            try:
                busy = self.llm_busy or self.web_busy
                stx = ("Zenko is thinking" + "." * (int(now * 3) % 4)) if busy else ""
                if c.get("status_now") != stx:
                    c["status_now"] = stx
                    c["status"].config(text=stx)
            except tk.TclError:
                pass
        h["win"].after(50, self.hub_anim)

    def hub_draw_week(self, f=1.0):
        cv = getattr(self, "hub_week", None)
        if cv is None:
            return
        st = load_stats()
        cv.delete("all")
        days = [datetime.date.today() - datetime.timedelta(days=i) for i in range(6, -1, -1)]
        vals = [int(st.get(d.isoformat(), 0) // 60) for d in days]
        top = max(vals + [30])
        cv.create_line(4, 100, 266, 100, fill=LINE)
        for i, (d, v) in enumerate(zip(days, vals)):
            x = 10 + i * 37
            hgt = max(2, 85 * v / float(top) * f) if v else 2
            col = ORANGE if i == 6 else _mixhex(T["card"], ORANGE, 0.38)
            rr = int(min(8, hgt / 2))
            cv.create_polygon(round_pts(x, 100 - hgt, x + 26, 100, rr, 2, [("round", rr), ("round", rr), ("round", 0), ("round", 0)]),
                              fill=col, outline="")
            if hgt > 6:
                cv.create_line(x + rr, 100 - hgt + 2, x + 26 - rr, 100 - hgt + 2, fill=_mixhex(col, "#ffffff", 0.45))
            if i == 6 and v:
                cv.create_rectangle(x + 10, 100 - hgt - 6, x + 16, 100 - hgt - 2, fill=GLOW, outline="")
            if v and f > 0.95:
                cv.create_text(x + 13, 100 - hgt - 12, text=str(v), fill=INK, font=(FONT_UI, 8, "bold"))
            cv.create_text(x + 13, 115, text=d.strftime("%a")[:2], fill=GOLD if i == 6 else GREY, font=(FONT_UI, 8))

    def hub_title(self, pg, title, sub=""):
        """A night-sky banner: soft gradient, stars, seigaiha waves, gold rule, big title."""
        cv = tk.Canvas(pg, height=96, bg=T["banner"], highlightthickness=0)
        cv.pack(fill="x")
        lab = _CanvasText(cv)
        lab.text = sub

        def draw(_e=None):
            W = cv.winfo_width()
            if W < 20:
                return
            cv.delete("all")
            Hh = 96
            for y in range(Hh):
                cv.create_line(0, y, W, y, fill=_mixhex(NIGHT, T["banner"], y / float(Hh)))
            x0 = max(0, W - 340)
            cache = self.__dict__.setdefault("_seig", {})
            key = (NIGHT, T["banner"], ORANGE)
            if key not in cache:
                cache.clear()
                cache[key] = seigaiha_photo(340, Hh, NIGHT, T["banner"], _mixhex(T["banner"], ORANGE, 0.30))
            cv.create_image(x0, 0, image=cache[key], anchor="nw")
            rnd = random.Random(len(title))
            for _ in range(18):
                sx, sy = rnd.uniform(0, W * 0.75), rnd.uniform(4, 60)
                cv.create_rectangle(sx, sy, sx + 2, sy + 2, fill=_mixhex(NIGHT, INK, rnd.uniform(0.2, 0.6)), outline="")
            cv.create_text(28, 20, text=title, anchor="nw", fill=INK, font=(FONT_UI, 21, "bold"))
            lab.item = None
            lab.place(30, 60, W - 60)
            cv.itemconfigure(lab.item, fill=GREY)
            cv.create_line(0, Hh - 2, W, Hh - 2, fill=_mixhex(T["banner"], GOLD, 0.6))
            cv.create_line(0, Hh - 1, W, Hh - 1, fill=_mixhex(PAPER, "#000000", 0.2))
            cv.create_polygon(28, Hh - 6, 32, Hh - 2, 28, Hh + 2, 24, Hh - 2, fill=GOLD, outline="")
        cv.bind("<Configure>", draw)
        if self.cfg.get("borderless", True):
            self.hub_make_drag(cv)
        return lab

    # -- Home
    def hub_build_home(self, pg):
        hr = datetime.datetime.now().hour
        greet = "Good morning" if hr < 12 else ("Good afternoon" if hr < 18 else "Good evening")
        self.hub_title(pg, greet + (", " + self.user_short() if self.user_short() else ""),
                       datetime.date.today().strftime("%A, %d %B %Y"))
        body = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        body.pack(fill="x", padx=24, pady=14)
        row = tk.Frame(body, bg=PAPER)
        row.pack(fill="x")
        self.hub_stat = {}
        for i, key in enumerate(("focus", "plan", "next", "due")):
            c = self.hub_card(row, shape="ema")
            c.pack(side="left", fill="both", expand=True, padx=(0 if i == 0 else 10, 0))
            big = tk.Label(c, text="-", bg=T["card"], fg=ORANGE_D, font=(FONT_UI, 20, "bold"), anchor="w")
            big.pack(fill="x", padx=14, pady=(10, 0))
            cap = tk.Label(c, text="", bg=T["card"], fg=GREY, font=(FONT_UI, 9), anchor="w")
            cap.pack(fill="x", padx=14, pady=(0, 10))
            self.hub_stat[key] = (big, cap)
        mid = tk.Frame(body, bg=PAPER)
        mid.pack(fill="both", expand=True, pady=(12, 0))
        leftcol = tk.Frame(mid, bg=PAPER)
        leftcol.pack(side="left", fill="both", expand=True)
        self.hub_sess = self.hub_card(leftcol, shape="leaf")
        self.hub_sess.pack(fill="x")
        self.hub_next = self.hub_card(leftcol, "Coming up today")
        self.hub_next.pack(fill="both", expand=True, pady=(12, 0))
        self.hub_next_body = tk.Frame(self.hub_next, bg=T["card"])
        self.hub_next_body.pack(fill="both", expand=True, padx=14, pady=(0, 10))
        self._hub_next_key = None
        right = tk.Frame(mid, bg=PAPER)
        right.pack(side="left", fill="y", padx=(12, 0))
        wk = self.hub_card(right, "Last 7 days (focus minutes)")
        wk.pack(fill="x")
        self.hub_week = tk.Canvas(wk, width=270, height=130, bg=T["card"], highlightthickness=0)
        self.hub_week.pack(padx=12, pady=(0, 10))
        qa = self.hub_card(right, "Quick ask")
        qa.pack(fill="x", pady=(12, 0))
        grid = tk.Frame(qa, bg=T["card"])
        grid.pack(padx=12, pady=(0, 12))
        for i, (lab, cmd) in enumerate((("Weather", "weather"), ("Headlines", "news"), ("Study tip", "tip"),
                                        ("Motivate me", "motivate me"))):
            self.tt_btn(grid, lab, lambda c=cmd: self.hub_ask(c), bg=T["start"], size=9, padx=10, pady=3
                        ).grid(row=i // 2, column=i % 2, padx=3, pady=3, sticky="ew")
        self.hub_music_card(right)
        self._hub_key = None
        self._count_until = 0.0

    def hub_ask(self, text):
        self.hub_show("chat")
        self.chat_send(text)

    def hub_refresh_home(self, force=False):
        h = self.hub
        if not h or "home" not in h["pages"] or not hasattr(self, "hub_stat"):
            return
        s, b = self.session, self.brk
        key = (bool(s), bool(s and s["paused"]), bool(b), self.cfg.get("theme"))
        if force or key != self._hub_key:
            self._hub_key = key
            self.hub_build_session_card()
        fm = today_focus_minutes()
        rows = tt_today(self.tt, datetime.date.today())
        done = sum(1 for i in rows if tt_done(i, datetime.date.today()))
        nxt = self.focus_item()
        if time.monotonic() > self._count_until:
            self.hub_stat["focus"][0].config(text="%d min" % fm)
            self.hub_stat["plan"][0].config(text="%d / %d" % (done, len(rows)))
        self.hub_stat["focus"][1].config(text="focused today")
        self.hub_stat["plan"][1].config(text="timetable items done")
        self.hub_stat["next"][0].config(text=nxt["start"] if nxt else "-")
        self.hub_stat["next"][1].config(text=clip(nxt["task"], 26) if nxt else "nothing left today")
        if int(time.time()) % 5 == 0 or self.hub_stat["due"][0].cget("text") == "-":
            up = self.upcoming_deadlines(1)
            self.hub_stat["due"][0].config(text=when_text(up[0]["date"]).capitalize() if up else "None")
            self.hub_stat["due"][1].config(text=clip(up[0]["title"], 26) if up else "no deadlines - drop a file")
        if s:
            left = max(0, s["planned"] - s["elapsed"])
            self.hub_timer.config(text=("%02d" + (":" if int(time.time()) % 2 == 0 else " ") + "%02d") % (left // 60, left % 60))
            cv = self.hub_bar
            cv.delete("all")
            wd = max(10, cv.winfo_width() - 4)
            self.glow_bar(cv, 2, 5, wd, 15, s["elapsed"] / max(1.0, s["planned"]))
            self.hub_sess_info.config(text="Off-task so far: %d min   ·   distractions closed: %d" % (
                s["dist"] // 60, s.get("closed", 0)))
        elif b:
            left = max(0, b["planned"] - b["elapsed"])
            self.hub_timer.config(text="%02d:%02d" % (left // 60, left % 60))
        today_d = datetime.date.today()
        now = datetime.datetime.now()
        nk = tuple((i["start"], i["task"], tt_done(i, today_d)) for i in rows)
        if nk != self._hub_next_key:
            self._hub_next_key = nk
            for ch in self.hub_next_body.winfo_children():
                ch.destroy()
            shown = 0
            for i in rows:
                if tt_done(i, today_d):
                    continue
                shown += 1
                if shown > 5:
                    break
                r = tk.Frame(self.hub_next_body, bg=T["card"])
                r.pack(fill="x", pady=2)
                tk.Label(r, text=i["start"], bg=T["card"], fg=ORANGE_D, font=("Consolas", 12, "bold"), width=6,
                         anchor="w").pack(side="left")
                tk.Label(r, text=clip(i["task"], 34), bg=T["card"], fg=INK, font=(FONT_UI, 10), anchor="w"
                         ).pack(side="left")
                tk.Label(r, text=fmt_hm(i["mins"]), bg=T["card"], fg=GREY, font=(FONT_UI, 9)).pack(side="right")
            if not shown:
                tk.Label(self.hub_next_body, text="Nothing left on today's timetable. Add something in the Timetable tab.",
                         bg=T["card"], fg=GREY, font=(FONT_UI, 10), anchor="w", wraplength=380, justify="left").pack(fill="x", pady=6)
        wk = (fm, today_d.isoformat())
        if wk != getattr(self, "_wk_key", None) and time.monotonic() > self._count_until:
            self._wk_key = wk
            self.hub_draw_week(1.0)

    def hub_build_session_card(self):
        c = self.hub_sess
        for ch in c.winfo_children():
            if not getattr(ch, "_zk_bg", False):
                ch.destroy()
        s, b = self.session, self.brk
        bg = T["card"]
        if s or b:
            tk.Label(c, text=("On a break" if (b and not s) or b else ("Paused" if s["paused"] else "Focusing")),
                     bg=bg, fg=GREY, font=(FONT_UI, 10, "bold"), anchor="w").pack(fill="x", padx=18, pady=(14, 0))
            tk.Label(c, text="Break" if b else clip(s["task"], 34), bg=bg, fg=INK, font=(FONT_UI, 18, "bold"),
                     anchor="w").pack(fill="x", padx=18)
            self.hub_timer = tk.Label(c, text="--:--", bg=bg, fg=GOLD, font=("Consolas", 46, "bold"), anchor="w")
            self.hub_timer.pack(fill="x", padx=18)
            self.hub_bar = tk.Canvas(c, height=20, bg=bg, highlightthickness=0)
            self.hub_sess_info = tk.Label(c, text="", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w")
            if s and not b:
                self.hub_bar.pack(fill="x", padx=18, pady=(0, 4))
                self.hub_sess_info.pack(fill="x", padx=18)
            btns = tk.Frame(c, bg=bg)
            btns.pack(anchor="w", padx=18, pady=14)
            if b:
                self.tt_btn(btns, "End break", lambda: self.end_break(False), bg=T["start"], size=11, padx=16, pady=4
                            ).pack(side="left", padx=(0, 8))
            else:
                self.tt_btn(btns, "Resume" if s["paused"] else "Pause", self.toggle_pause, bg=T["start"], size=11,
                            padx=16, pady=4).pack(side="left", padx=(0, 8))
                self.tt_btn(btns, "Stop", lambda: self.end_session(False), bg=T["delbtn"], size=11, padx=16, pady=4
                            ).pack(side="left", padx=(0, 8))
                self.tt_btn(btns, "Take a break", self.start_break, bg=FIELD, size=11, padx=16, pady=4).pack(side="left")
            return
        tk.Label(c, text="Start a focus session", bg=bg, fg=INK, font=(FONT_UI, 16, "bold"), anchor="w"
                 ).pack(fill="x", padx=18, pady=(14, 2))
        tk.Label(c, text="I'll watch for distractions and keep you company.", bg=bg, fg=GREY, font=(FONT_UI, 10),
                 anchor="w").pack(fill="x", padx=18, pady=(0, 10))
        task = tk.StringVar(value=self.cfg.get("last_task", ""))
        mv = tk.StringVar(value=str(self.cfg.get("last_minutes", 25)))
        tk.Label(c, text="What are you working on?", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=18)
        te = self.tt_entry(c, task, 40)
        te.pack(fill="x", padx=18, pady=(2, 10))
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=18)
        tk.Label(r, text="Minutes", bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="left")
        self.tt_entry(r, mv, 5).pack(side="left", padx=(8, 12))
        for v in (15, 25, 45, 60, 90):
            self.tt_btn(r, str(v), lambda v=v: mv.set(str(v)), bg=FIELD, size=9, padx=8, pady=1).pack(side="left", padx=2)

        def go(_e=None):
            try:
                n = max(1, min(240, int(float(mv.get()))))
            except ValueError:
                n = 25
            name = task.get().strip() or "Focus session"
            self.cfg["last_task"], self.cfg["last_minutes"] = task.get().strip(), n
            save_config(self.cfg)
            self.start_session(name, n)
        te.bind("<Return>", go)
        self.hub_go_btn = self.tt_btn(c, "\u2726  Start focusing", go, bg=ORANGE, fg=ON_ACC, size=13, padx=24, pady=8)
        self.hub_go_btn.pack(anchor="w", padx=18, pady=(14, 6))
        it = self.focus_item()
        if it:
            tk.Label(c, text="On your timetable: %s %s (%d min)" % (it["start"], clip(it["task"], 26), it["mins"]),
                     bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=18)
            self.tt_btn(c, "Start that instead", lambda: self.start_session(it["task"], it["mins"], it),
                        bg=T["start"], size=9, padx=10, pady=2).pack(anchor="w", padx=18, pady=(4, 12))

