    def edit_distractions(self):
        d = tk.Toplevel(self.root)
        d.title(APP_NAME + " - distracting sites")
        d.attributes("-topmost", True)
        d.configure(bg=PAPER)
        tk.Label(d, text="One site or app word per line. A window title containing it counts as a distraction.",
                 bg=PAPER, fg=INK, font=(FONT_UI, 10), wraplength=380, justify="left").pack(padx=14, pady=(12, 4))
        t = tk.Text(d, width=44, height=16, font=("Consolas", 10), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                    highlightthickness=1, highlightbackground=LINE)
        t.pack(padx=14, pady=4)
        t.insert("1.0", "\n".join(self.cfg.get("distractions", [])))

        def save():
            items = [x.strip().lower() for x in t.get("1.0", "end").splitlines() if x.strip()]
            self.cfg["distractions"] = items
            save_config(self.cfg)
            d.destroy()
            self.say("Saved %d distracting sites." % len(items), 5)
        self.tt_btn(d, "Save", save, bg=ORANGE, fg=ON_ACC, size=11, padx=18, pady=4).pack(pady=(4, 12))

    def hub_tick(self):
        h = getattr(self, "hub", None)
        if not h or not h["win"].winfo_exists():
            return
        s, b = self.session, self.brk
        if s:
            left = max(0, s["planned"] - s["elapsed"])
            txt = "%s\n%02d:%02d left" % (clip(s["task"], 22), left // 60, left % 60)
        elif b:
            txt = "On a break"
        else:
            txt = "Idle  ·  %d min focused today" % today_focus_minutes()
        self.hub_status.config(text=txt)
        if h["page"] == "home":
            self.hub_refresh_home()
            if int(time.time()) % 8 == 0:
                self.music_refresh()
        h["win"].after(1000, self.hub_tick)

    # ==== extras: background jobs ===================================================
    def bg(self, fn, done=None):
        """Run fn() in a thread; done(result, error) is called back on the UI thread."""
        def run():
            try:
                res, err = fn(), None
            except Exception as e:
                res, err = None, e
            if done:
                self.ext_q.put((done, res, err))
        threading.Thread(target=run, daemon=True).start()

    def poll_ext(self):
        try:
            while True:
                done, res, err = self.ext_q.get_nowait()
                try:
                    done(res, err)
                except tk.TclError:
                    pass
        except queue.Empty:
            pass
        try:
            while True:
                kind, val = self.voice.q.get_nowait()
                self.on_voice_event(kind, val)
        except queue.Empty:
            pass
        self.root.after(80, self.poll_ext)

    def fox_reply(self, msg, speak=False):
        """Show a reply in chat + bubble, and speak it if wanted."""
        if speak:
            self.voice_reply_until = max(self.voice_reply_until, time.monotonic() + 5)
        self.chat_line("Fox", msg)
        self.say(md_plain(msg).split("\n")[0], 12)

    # ==== voice ========================================================================
    def speak(self, text):
        if self.cfg.get("speak_mode", "voice") == "off":
            return
        self.speaker.say(text, self.cfg.get("tts_voice", ""), int(self.cfg.get("tts_speed", 0)), int(self.cfg.get("tts_pitch", 0) or 0))

    def speak_test(self):
        if not IS_WIN:
            self.say("Talking only works on Windows.", 5)
            return
        self.speaker.say("Kon kon! Hi %s! This is how I sound. Ready to focus?" % (self.user_short() or "there"),
                         self.cfg.get("tts_voice", ""), int(self.cfg.get("tts_speed", 0)), int(self.cfg.get("tts_pitch", 0) or 0))

        def check(n=0):
            p = self.speaker.problem()
            if p:
                self.say(p, 12)
                self.chat_line("Fox", "Voice test failed: " + p)
            elif self.speaker.status in ("loading", "downloading") and n < 40:
                if n == 0 and self.speaker.status == "downloading":
                    self.say("Downloading that voice (one time, ~60 MB)...", 8)
                self.root.after(1500, lambda: check(n + 1))
            elif self.speaker.status in ("loading", "downloading"):
                self.say("That voice is taking too long to load. The download may be blocked here: "
                         "try a Windows voice instead.", 12)
            elif n == 0:
                kind = "Windows voice (direct)" if isinstance(self.speaker.proc, SapiVoice) else (
                    "natural voice" if str(self.cfg.get("tts_voice", "")).startswith("piper:") else "Windows voice (PowerShell)")
                self.say("Did you hear me? I used the %s. If not, check the volume and the "
                         "playback device in Windows." % kind, 10)
        self.root.after(2500, check)

    def should_speak(self, text):
        mode = self.cfg.get("speak_mode", "voice")
        if mode == "off" or not text:
            return False
        if text.strip() in ("(thinking...)", "Looking that up...", "Checking...", "On it...", "Looking at your screen...") \
                or text.startswith(("(thinking", "Reading “")):
            return False
        if mode == "always":
            return True
        if self.voice_reply_until > time.monotonic():
            self.voice_reply_until = 0.0
            return True
        return False

    def hotkey_loop(self):
        if IS_WIN and self.cfg.get("voice_enabled", True):
            for mode, key in (("chat", self.cfg.get("voice_key", "Right Ctrl")),
                              ("screen", self.cfg.get("screen_key", "F8"))):
                vk = HOTKEYS.get(key)
                if not vk:
                    continue
                down = key_down(vk)
                now = time.monotonic()
                t0 = self.key_state.get(mode + "_t")
                if down and t0 is None:
                    self.key_state[mode + "_t"] = now
                    v = self.voice
                    if v.kind in ("whisper", "local") and v.alive() and v.ready and not v.listening:
                        self.voice_mode = mode
                        v.press()                                  # record from the very first moment
                        self.key_state[mode + "_early"] = True
                elif down and t0 and now - t0 >= 0.35 and not self.key_state.get(mode):
                    self.key_state[mode] = True                    # held: it's push-to-talk, not Ctrl+C
                    if self.key_state.get(mode + "_early"):
                        self.voice_began(mode)
                    else:
                        self.voice_press(mode)
                elif not down and t0 is not None:
                    if self.key_state.get(mode):
                        self.voice_release()
                    elif self.key_state.get(mode + "_early"):
                        self.voice.cancel()                        # just a quick tap (e.g. Ctrl+C)
                    self.key_state[mode] = False
                    self.key_state[mode + "_t"] = None
                    self.key_state[mode + "_early"] = False
        self.root.after(40, self.hotkey_loop)

    def voice_began(self, mode):
        self.voice_mode = mode
        self.speaker.hush()
        if mode == "screen":
            self.screen_shot_early = None
            self.bg(lambda: grab_screen_png(), lambda r, e: setattr(self, "screen_shot_early", r if not e else None))
        self.voice_ui(True)

    def voice_press(self, mode="chat"):
        if self.voice.listening:
            return
        self.voice_mode = mode
        self.speaker.hush()
        if mode == "screen":
            self.screen_shot_early = None
            self.bg(lambda: grab_screen_png(), lambda r, e: setattr(self, "screen_shot_early", r if not e else None))
        if not self.voice.alive() or not self.voice.ready:
            if not self.voice.alive():
                if not self.voice.start(self.cfg.get("voice_engine", "auto"), self.cfg.get("whisper_model", "small.en")):
                    return
            self.voice_pending = True
            self.say("Waking up my ears... (first time takes a few seconds)", 6)
            return
        self.voice.press()
        self.voice_ui(True)

    def voice_release(self):
        if self.voice_pending and self.voice_mode != "button":
            self.voice_pending = False
            self.say("My ears are ready now. Hold the key and talk.", 6)
            return
        self.voice.release()

    def voice_toggle(self, mode="chat"):
        """Mic button: click to talk, click again to stop (Windows speech stops by itself)."""
        if self.voice.listening:
            self.voice.release()
        else:
            self.voice_press("button" if mode == "chat" else mode)

    def voice_ui(self, on):
        self.listening_ui = on
        if on:
            self.set_mood("focus", 30)
            self.say("Listening..." + (" (release the key when done)" if self.voice.kind == "whisper" else ""), 30)
        else:
            self.clear_mood()
        c = self.chat
        if c and c.get("mic") is not None:
            try:
                c["mic"].config(text="Listening" if on else "Mic", bg="#e5484d" if on else T["start"],
                                fg="#ffffff" if on else INK)
            except tk.TclError:
                pass

    def on_voice_event(self, kind, val):
        if kind == "status":
            if val == "ready" and self.voice_pending:
                self.voice_pending = False
                self.voice.press()
                self.voice_ui(True)
            elif val == "stopped":
                self.voice_ui(False)
                self.voice_status = ""
            return
        if kind == "error":
            self.voice_ui(False)
            self.fox_reply(str(val))
            return
        if kind == "text":
            self.voice_ui(False)
            t = (val or "").strip()
            if not t:
                self.say("I didn't catch that. Try again?", 5)
                return
            if self.voice_mode == "screen":
                self.chat_line("You", "(voice, looking at screen) " + t)
                self.ask_screen(t, spoken=True, shot=getattr(self, "screen_shot_early", None))
            else:
                self.voice_reply_until = time.monotonic() + 120
                self.chat_send(t, typed=False)

    def install_whisper(self, done):
        py = system_python()
        if not py:
            done(None, RuntimeError("I couldn't find Python on this PC. Install it from python.org first."))
            return

        def job():
            r = run_hidden([py, "-m", "pip", "install", "--upgrade", "faster-whisper", "sounddevice", "numpy"], timeout=1800)
            if r.returncode != 0:
                tail = (r.stderr or b"").decode("utf-8", "replace").strip().splitlines()[-1:] or ["unknown error"]
                raise RuntimeError("pip failed: " + tail[0][:200])
            return True
        self.bg(job, done)

    # ==== screen buddy ================================================================
    def ask_screen(self, question, spoken=False, shot=None, typed=False):
        if not IS_WIN and shot is None:
            return "Looking at the screen works on Windows."
        if self.screen_busy:
            return "Still looking at the last one..."
        self.screen_busy = True
        model = self.cfg.get("vision_model", "qwen2.5vl:3b")
        hub = getattr(self, "hub", None)
        hide = typed and hub and hub["win"].winfo_exists() and hub["win"].state() != "withdrawn"

        def capture_then_ask():
            def job():
                png, (iw, ih), (sw, sh) = shot if shot else grab_screen_png()
                prompt = SCREEN_PROMPT.replace("%s Answer", (self.user_profile_text() or "").replace("%", "%%") + " Answer") % (iw, ih)
                raw = ollama_vision(question, [png], model, timeout=240, system=prompt, fmt="json")
                d = parse_brain(raw)
                pt = d.get("point")
                spot = None
                if isinstance(pt, (list, tuple)) and len(pt) >= 2:
                    try:
                        x, y = float(pt[0]), float(pt[1])
                        if 0 <= x <= iw and 0 <= y <= ih:
                            spot = (int(x * sw / iw), int(y * sh / ih), str(d.get("label") or "")[:30])
                    except (TypeError, ValueError):
                        spot = None
                return str(d.get("answer") or d.get("reply") or raw or "I looked but I'm not sure.").strip(), spot

            def done(res, err):
                self.screen_busy = False
                if hide:
                    try:
                        hub["win"].deiconify()
                    except tk.TclError:
                        pass
                if err:
                    e = str(err)
                    if e == "NO_OLLAMA":
                        msg = "To look at your screen I need the free Ollama app running (Settings > Smart brain)."
                    elif e.startswith("NO_VISION"):
                        msg = ("I need my 'eyes' first. Open Command Prompt and run:  ollama pull %s   "
                               "(about 3 GB, one time)." % model)
                    else:
                        msg = "I couldn't read the screen (%s)." % e
                    self.fox_reply(msg)
                    return
                ans, spot = res
                self.fox_reply(ans, speak=spoken or self.cfg.get("speak_mode") == "always")
                if spot:
                    self.show_pointer(*spot)
            self.bg(job, done)
        self.say("Let me look...", 6)
        self.set_mood("focus", 6)
        if hide:
            hub["win"].withdraw()
            self.root.after(350, capture_then_ask)
        else:
            capture_then_ask()
        return "Looking at your screen..."

    def show_pointer(self, x, y, label=""):
        """A little fox-coloured arrow flies from the fox to (x, y) on screen and points at it."""
        old = getattr(self, "pointer_win", None)
        if old is not None:
            try:
                old.destroy()
            except tk.TclError:
                pass
        p = tk.Toplevel(self.root)
        self.pointer_win = p
        p.overrideredirect(True)
        p.attributes("-topmost", True)
        key = "#ff00ff"
        p.configure(bg=key)
        try:
            p.attributes("-transparentcolor", key)
        except tk.TclError:
            pass
        U = max(1.0, self.U)
        Wp, Hp = int(220 * U), int(64 * U)
        cv = tk.Canvas(p, width=Wp, height=Hp, bg=key, highlightthickness=0)
        cv.pack()
        s = 2 * U
        arrow = [(0, 0), (0, 13), (3, 10), (5, 15), (7, 14), (5, 9), (9, 9)]
        cv.create_polygon([c * s + 3 for xy in arrow for c in xy], fill=ORANGE, outline=NIGHT, width=max(2, int(U * 2)))
        if label:
            f = (FONT_UI, 10, "bold")
            tx = int(26 * U)
            t = cv.create_text(tx + 8, int(30 * U), text=label, anchor="w", fill=INK, font=f)
            bx = cv.bbox(t)
            r = cv.create_rectangle(bx[0] - 7, bx[1] - 4, bx[2] + 7, bx[3] + 4, fill=T["bub"], outline=GOLD, width=2)
            cv.tag_raise(t, r)
        cv.bind("<Button-1>", lambda e: p.destroy())
        fx = self.root.winfo_rootx() + self.COLW + self.FW // 2
        fy = self.root.winfo_rooty() + self.fox_y
        t0 = time.monotonic()

        def step():
            if not p.winfo_exists():
                return
            t = (time.monotonic() - t0) / 0.75
            if t < 1:
                e = 1 - (1 - t) ** 3
                cx, cy = fx + (x - fx) * e, fy + (y - fy) * e - 60 * (1 - (2 * e - 1) ** 2)
            else:
                bob = 4 * U * abs(((time.monotonic() * 2) % 2) - 1)
                cx, cy = x + bob, y + bob
            p.geometry("%dx%d+%d+%d" % (Wp, Hp, int(cx - 3), int(cy - 3)))
            if time.monotonic() - t0 < 10:
                p.after(16, step)
            else:
                p.destroy()
        step()

    # ==== Spotify =====================================================================
    def music(self, action, arg=None, quiet=False):
        sp = self.spotify
        sp.client_id = self.cfg.get("spotify_client_id", "").strip()
        if not sp.connected():
            msg = "Spotify isn't connected yet. Settings > Spotify (one-time setup, about 3 minutes)."
            if not quiet:
                self.fox_reply(msg)
            return msg

        if action == "play" and arg:
            pre = self.find_preset(arg)
            if pre:
                return self.play_preset(pre, quiet)

        def job():
            if action == "volume_rel":
                n = sp.now() or {}
                return sp.do("volume", (n.get("volume") or 50) + int(arg))
            return sp.do(action, arg)

        def done(res, err):
            if quiet and err is None:
                self.root.after(400, self.music_refresh)
                return
            self.fox_reply(str(err) if err else res)
            self.music_refresh()
            self.root.after(800, lambda: self.bg(self.spotify.now, lambda r, e: setattr(self, "music_now", r) if not e else None))
        self.bg(job, done)
        return None

    def spotify_connect(self, status_label=None):
        self.spotify.client_id = self.cfg.get("spotify_client_id", "").strip()
        if status_label:
            status_label.config(text="Opening Spotify in your browser... approve it there.")

        def done(res, err):
            msg = str(err) if err else "Spotify connected! Try: play focus music"
            if status_label is not None:
                try:
                    status_label.config(text=msg)
                except tk.TclError:
                    pass
            self.fox_reply(msg)
            self.music_refresh()
        self.bg(lambda: self.spotify.login(), done)

    def music_refresh(self):
        h = getattr(self, "hub", None)
        if not h or not getattr(self, "hub_music", None) or not self.spotify.connected():
            return

        def done(res, err):
            try:
                lab, sub = self.hub_music
                if err:
                    lab.config(text="Spotify")
                    sub.config(text=str(err)[:60])
                elif not res:
                    lab.config(text="Nothing playing")
                    sub.config(text="Open Spotify, or type: play focus music")
                else:
                    lab.config(text=clip(res["title"], 30))
                    sub.config(text=("" if res["playing"] else "Paused · ") + clip(res["artist"], 34))
                    self.music_playing = res["playing"]
                    self.music_pp_show()
            except (tk.TclError, ValueError):
                pass
        self.bg(self.spotify.now, done)

    # ---- the music tablet on the fox's belly ----
    def player_poll(self):
        """Every 1.5 s: is Spotify open, what's on, playing or paused?"""
        try:
            win = spotify_window()
        except Exception:
            win = None
        api = self.music_now
        p = None
        if win is not None:
            p = dict(win)
            if p["title"]:
                self.song_memory = (p["title"], p["artist"])
            elif api and api.get("title"):
                p["title"], p["artist"] = api["title"], api.get("artist", "")
                p["playing"] = p["playing"] or bool(api.get("playing"))
            elif self.song_memory:
                p["title"], p["artist"] = self.song_memory
        elif api and api.get("title"):
            p = {"playing": bool(api.get("playing")), "title": api["title"], "artist": api.get("artist", "")}
        if p is not None and not p.get("title"):
            p["title"] = "Spotify"
        if p and p.get("playing"):
            sid = (p.get("title"), p.get("artist"))
            if sid != self.last_song and p.get("title") != "Spotify":
                self.last_song = sid
                if self.cfg.get("announce_songs", True) and not self.session:
                    self.say("~ %s%s" % (p["title"], (", by " + p["artist"]) if p.get("artist") else ""), 6)
        self.player = p
        self.root.after(1500, self.player_poll)

    def tablet_grid(self):
        """The music tablet as a fine-pixel picture: (rows of palette letters, scroll offset, flashed button)."""
        p = self.player or {}
        W, H = TAB_W, TAB_H
        g = [["."] * W for _ in range(H)]
        for y in range(H):
            for x in range(W):
                dx, dy = min(x, W - 1 - x), min(y, H - 1 - y)
                if dx + dy < 2 or (dx == 0 and dy < 3) or (dy == 0 and dx < 3):
                    continue                                     # rounded corners
                edge = dx == 0 or dy == 0 or (dx == 1 and dy == 1) or (dx + dy == 2)
                g[y][x] = "K" if edge else ("z" if (dx < 3 or dy < 3) else "y")
        for x in range(4, W - 4):                                # a soft highlight along the top bezel
            g[1][x] = "f"
        import unicodedata
        raw = p.get("title", "")
        if p.get("artist"):
            raw += " - " + p["artist"]
        raw = unicodedata.normalize("NFKD", raw).encode("ascii", "ignore").decode().upper()
        text = "".join(ch if ch in FONT35 else " " for ch in raw).strip() or "SPOTIFY"
        cols = []
        for ch in text:
            gl = FONT35[ch]
            for cx in range(len(gl[0])):
                cols.append([gl[r][cx] == "#" for r in range(5)])
            cols.append([False] * 5)
        vis = W - 10
        off = 0
        if len(cols) - 1 <= vis:
            pad = (vis - len(cols) + 1) // 2
            window = [[False] * 5] * pad + cols[:-1]
        else:
            loop = cols + [[False] * 5] * 8
            off = int(time.monotonic() / 0.12) % len(loop)
            window = [loop[(off + i) % len(loop)] for i in range(vis)]
        for i, col in enumerate(window[:vis]):
            for r in range(5):
                if col[r]:
                    g[5 + r][5 + i] = "H"
        playing = bool(p.get("playing"))
        for i in range(5, W - 5):                                 # a little progress line under the title
            g[12][i] = "v" if playing and i < 5 + int((time.monotonic() / 3.0) % 1.0 * (W - 10)) else "f"
        fl, ft = self.tab_flash
        flash = fl if time.monotonic() - ft < 0.18 else None
        # buttons: previous, a round green play/pause, next
        cx, cy = 20.5, 18.5
        for y in range(14, 23):
            for x in range(15, 27):
                d = math.hypot(x + 0.5 - cx, y + 0.5 - cy)
                if d <= 4.6:
                    g[y][x] = ("H" if flash == "playpause" else "v") if d <= 3.8 else "u"
        if playing:
            for y in range(16, 21):
                for x in (18, 19, 22, 23):
                    g[y][x] = "y"
        else:
            for k, y in enumerate(range(16, 21)):
                for x in range(19, 19 + (k + 1 if k < 3 else 5 - k)):
                    g[y][x] = "y"
        ink = {n: ("v" if flash == n else "H") for n in ("previous", "next")}
        for k, y in enumerate(range(15, 22)):
            w_ = 4 - abs(k - 3)
            for x in range(12 - w_, 12):
                g[y][x] = ink["previous"]
            g[y][6] = g[y][7] = ink["previous"]
            for x in range(29, 29 + w_):
                g[y][x] = ink["next"]
            g[y][33] = g[y][34] = ink["next"]
        return g, off, flash

    def draw_tablet(self, dx, dy, show):
        c = self.canvas
        if not show:
            if self._tab_key is not None:
                c.delete("tablet")
                self._tab_key = None
            return
        g, off, flash = self.tablet_grid()
        p = self.player or {}
        key = (p.get("title"), p.get("artist"), p.get("playing"), off, flash, dx, dy, self.Z, INK,
               int(time.monotonic() / 3.0 * (TAB_W - 10)) if p.get("playing") else 0)
        if key == self._tab_key:
            return
        self._tab_key = key
        # her paws hold the top edge (drawn in her own colours, so no dark blocks)
        rows = [r[:] for r in g]
        full = [["."] * TAB_W for _ in range(TAB_H + 3)]
        for y, r in enumerate(rows):
            full[y + 3] = r
        for pcx in (14.5, 27.5):
            for y in range(0, 8):
                for x in range(int(pcx) - 5, int(pcx) + 6):
                    d = ((x + 0.5 - pcx) / 4.2) ** 2 + ((y + 0.5 - 3.6) / 3.0) ** 2
                    if 0 <= x < TAB_W:
                        if d <= 1.0:
                            full[y][x] = "n" if (y >= 4 or (x + y) % 3) else "N"
                        elif d <= 1.45 and full[y][x] in (".", "z", "f", "K"):
                            full[y][x] = "K"
            for tx in (pcx - 1.5, pcx + 0.5):
                full[5][int(round(tx))] = "K"
        pal = dict(self.pal)
        pal.update(TAB_PAL)
        self._tab_img = sprite_photo([["".join(r) for r in full]], pal, self.Z)
        c.delete("tablet")
        ox = self.COLW + dx + TAB_X * self.Z
        oy = self.fox_y + dy + (TAB_Y - 3) * self.Z
        c.create_image(ox, oy, image=self._tab_img, anchor="nw", tags="tablet")

    def tablet_hit(self, x, y):
        if not (self.player and self.cfg.get("belly_music", True)) or self.is_curled():
            return None
        sx = ((x - self.COLW) / float(self.Z) - TAB_X) / TAB_B
        sy = ((y - self.fox_y) / float(self.Z) - TAB_Y) / TAB_B
        if not (0 <= sx < TAB_W and 0 <= sy < TAB_H):
            return None
        if sy >= 13:
            for name, (x0, x1) in TAB_BUTTONS.items():
                if x0 - 1 <= sx <= x1 + 1:
                    return name
        return "screen"

    def tablet_press(self, name):
        self.tab_flash = (name, time.monotonic())
        if name == "screen":
            p = self.player or {}
            self.say("~ %s%s" % (p.get("title", "Spotify"), (", by " + p["artist"]) if p.get("artist") else ""), 6)
            return
        beep("pet")
        p = self.player or {}
        if self.spotify.connected():
            act = {"previous": "previous", "next": "next"}.get(name) or ("pause" if p.get("playing") else "play")
            self.music(act, "" if act == "play" else None, quiet=True)
        else:
            media_key(name)
        if name == "playpause" and self.player:
            self.player["playing"] = not self.player.get("playing")
        if name in ("next", "previous"):
            self.root.after(900, lambda: setattr(self, "last_song", None))

    def music_poll(self):
        """Every few seconds: what's Spotify playing? (drives the headphones and the belly song bar)"""
        if self.spotify.connected() and not self.music_polling:
            self.music_polling = True
            self.spotify.client_id = self.cfg.get("spotify_client_id", "").strip()

            def done(res, err):
                self.music_polling = False
                if err:
                    return
                self.music_now = res
                if res and res.get("playing"):
                    sid = (res.get("title"), res.get("artist"))
                    if sid != self.last_song:
                        self.last_song = sid
                        if self.cfg.get("announce_songs", True) and not self.session:
                            self.say("~ %s, by %s" % (res["title"], res["artist"]), 6)
            self.bg(self.spotify.now, done)
        self.root.after(7000, self.music_poll)

    def music_session_hook(self, event):
        """Optional: start your focus playlist with a session, pause it for breaks / at the end."""
        if not self.cfg.get("spotify_auto", False) or not self.spotify.connected():
            return
        if event == "start":
            pl = self.cfg.get("spotify_focus_playlist", "").strip()
            self.music("play", pl, quiet=True) if pl else self.music("play", "", quiet=True)
        else:
            self.music("pause", quiet=True)

    # ==== reMarkable notes ===========================================================
    def notes_llm(self, task, name, question=""):
        nm, path = notes_find(name) if name else (None, None)
        if not path:
            idx = notes_index()
            if not idx:
                return "No notes read yet. Open the Notes tab, pick a notebook and press 'Read'."
            if not name and len(idx) == 1:
                nm, path = list(idx.items())[0]
            else:
                return "Which notebook? I have: " + ", ".join(sorted(idx)[:12])
        with open(path, encoding="utf-8") as f:
            body = f.read()
        if task == "show":
            return "%s:\n%s" % (nm, body[:1500] + ("..." if len(body) > 1500 else ""))
        instr = {"summary": "Summarise these notes as 5-8 crisp high-yield bullet points.",
                 "quiz": "Write 3 short exam-style questions from these notes, then the answers after a line 'Answers:'.",
                 "ask": "Answer this question using only these notes (say so if they don't cover it): " + question}[task]
        model = self.cfg.get("llm_model") or "llama3.2:3b"

        def job():
            names = brain_names()
            if names is None:
                raise RuntimeError("Ollama isn't running, so I can't think about your notes. Here they are instead:\n"
                                   + body[:900])
            m = model if model in names else ([n for n in names if n.split(":")[0] == model.split(":")[0]] or names or [model])[0]
            j = _ollama_json("/api/chat", {"model": m, "stream": False, "options": {"temperature": 0.3, "num_predict": 600}, "online": True,
                                           "messages": [{"role": "system", "content": ("You help the user with their own handwritten notes. " + self.user_profile_text() + " Plain text, no markdown headings.")},
                                                        {"role": "user", "content": instr + "\n\nNOTES (" + nm + "):\n" + body[:7000]}]}, 240)
            return (j.get("message") or {}).get("content", "").strip()
        self.bg(job, lambda r, e: self.fox_reply(str(e) if e else r))
        return "Reading “%s”..." % nm

    def notes_route(self, text):
        low = text.lower().strip(" ?.!")
        if re.match(r"^(?:my |list (?:my )?|show (?:my )?)?(?:remarkable )?notes(?: list)?$|^(?:which|what) notes do (?:i|you) have", low):
            idx = notes_index()
            return ("Notes I've read: " + ", ".join(sorted(idx))) if idx else \
                "No notes read yet. Open the Notes tab to connect your reMarkable."
        m = re.match(r"^(?:summari[sz]e|summary of) (?:my )?(?:notes? )?(?:on |about |for )?(.*)$", low)
        if m and ("note" in low or notes_find(m.group(1))[0]):
            return self.notes_llm("summary", re.sub(r"\bnotes?\b", "", m.group(1)).strip())
        m = re.match(r"^quiz me (?:on |about )?(?:my )?(?:notes? )?(?:on |about )?(.*)$", low)
        if m:
            return self.notes_llm("quiz", re.sub(r"\bnotes?\b", "", m.group(1)).strip())
        m = re.match(r"^(?:read|show|open) (?:me )?(?:my )?notes? (?:on |about |for |called )?(.+)$", low)
        if m:
            return self.notes_llm("show", m.group(1))
        m = re.match(r"^ask (?:my )?notes?(?: on| about)? ?([^:]*):\s*(.+)$|^ask (?:my )?notes (.+)$", low)
        if m:
            if m.group(3):
                return self.notes_llm("ask", "", m.group(3))
            return self.notes_llm("ask", m.group(1), m.group(2))
        return None

    # ==== premium borderless window =================================================
    def win_hwnd(self, w):
        try:
            return ctypes.windll.user32.GetParent(w.winfo_id()) or w.winfo_id()
        except Exception:
            return None

    def make_borderless(self, w):
        """No Windows title bar: our own controls, rounded corners (Windows 11), still in the taskbar."""
        w.overrideredirect(True)
        if not IS_WIN:
            return
        try:
            hwnd = self.win_hwnd(w)
            GWL_EXSTYLE, WS_EX_APPWINDOW, WS_EX_TOOLWINDOW = -20, 0x00040000, 0x00000080
            u = ctypes.windll.user32
            ex = u.GetWindowLongW(hwnd, GWL_EXSTYLE)
            u.SetWindowLongW(hwnd, GWL_EXSTYLE, (ex & ~WS_EX_TOOLWINDOW) | WS_EX_APPWINDOW)
            w.withdraw()
            w.after(30, w.deiconify)
        except Exception:
            pass

    def round_corners(self, w):
        if not IS_WIN:
            return
        try:
            hwnd = self.win_hwnd(w)
            dwm = ctypes.windll.dwmapi

            def put(attr, val):
                v = ctypes.c_int(val)
                return dwm.DwmSetWindowAttribute(hwnd, attr, ctypes.byref(v), 4)

            def bgr(h):
                h = h.lstrip("#")
                return int(h[4:6], 16) << 16 | int(h[2:4], 16) << 8 | int(h[0:2], 16)
            put(33, 2)                       # DWMWCP_ROUND: smooth anti-aliased corners
            put(34, bgr(_mixhex(NIGHT, GOLD, 0.45)))  # thin gold border
            put(20, 1)
        except Exception:
            pass

    def hub_titlebar(self, parent):
        """Slim custom title bar with minimise / maximise / close, drag to move, double-click to maximise."""
        h = self.hub
        bar = tk.Frame(parent, bg=NIGHT, height=34)
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)
        tk.Label(bar, text="\u2726  " + APP_NAME.upper(), bg=NIGHT, fg=_mixhex(NIGHT, GOLD, 0.7),
                 font=(FONT_UI, 9, "bold")).pack(side="left", padx=16)
        self.hub_make_drag(bar.winfo_children()[-1])
        btns = tk.Frame(bar, bg=NIGHT)
        btns.pack(side="right", fill="y")

        def mk(kind, cmd, hover):
            c = tk.Canvas(btns, width=46, height=34, bg=NIGHT, highlightthickness=0, cursor="hand2")
            c.pack(side="left")
            col = _mixhex(NIGHT, INK, 0.8)
            if kind == "min":
                c.create_line(18, 17, 28, 17, fill=col, width=1.4)
            elif kind == "max":
                c.create_rectangle(18, 12, 28, 22, outline=col, width=1.4)
            else:
                c.create_line(18, 12, 28, 22, fill=col, width=1.4)
                c.create_line(28, 12, 18, 22, fill=col, width=1.4)
            c.bind("<Enter>", lambda e: c.config(bg=hover))
            c.bind("<Leave>", lambda e: c.config(bg=NIGHT))
            c.bind("<ButtonRelease-1>", lambda e: cmd())
            return c
        mk("min", self.hub_minimize, _mixhex(NIGHT, INK, 0.12))
        mk("max", self.hub_toggle_max, _mixhex(NIGHT, INK, 0.12))
        mk("close", self.hub_close, "#e5484d")
        self.hub_make_drag(bar)
        bar.bind("<Double-Button-1>", lambda e: self.hub_toggle_max())
        return bar

    def hub_make_drag(self, widget):
        def press(e):
            h = self.hub
            if not h:
                return
            w = h["win"]
            if self.hub_zone(e):
                h["drag"] = None
                return
            if h.get("maxed"):
                # restore and keep the window under the cursor
                gw, gh = h["restore"][0], h["restore"][1]
                h["maxed"] = False
                rx = e.x_root - gw // 2
                w.geometry("%dx%d+%d+%d" % (gw, gh, rx, max(0, e.y_root - 15)))
            h["drag"] = (e.x_root - w.winfo_x(), e.y_root - w.winfo_y())
            h["drag_moved"] = False
            h["drag_at"] = (e.x_root, e.y_root)

        def move(e):
            h = self.hub
            if not h or not h.get("drag") or h.get("rs"):
                return
            if not h.get("drag_moved"):
                ax, ay = h.get("drag_at", (e.x_root, e.y_root))
                if abs(e.x_root - ax) + abs(e.y_root - ay) < 5:
                    return
                h["drag_moved"] = True
            dx, dy = h["drag"]
            h["win"].geometry("+%d+%d" % (e.x_root - dx, max(0, e.y_root - dy)))
        widget.bind("<ButtonPress-1>", press, add="+")
        widget.bind("<B1-Motion>", move, add="+")

    def hub_minimize(self):
        h = self.hub
        if not h:
            return
        w = h["win"]
        if IS_WIN and self.cfg.get("borderless", True):
            try:
                ctypes.windll.user32.ShowWindow(self.win_hwnd(w), 6)      # SW_MINIMIZE
                return
            except Exception:
                pass
        try:
            if self.cfg.get("borderless", True):
                w.overrideredirect(False)
                w.iconify()
                w.bind("<Map>", lambda e: (w.overrideredirect(True), w.unbind("<Map>")) if w.state() == "normal" else None)
            else:
                w.iconify()
        except tk.TclError:
            w.withdraw()

    def hub_toggle_max(self):
        h = self.hub
        if not h:
            return
        w = h["win"]
        if h.get("maxed"):
            gw, gh, gx, gy = h["restore"]
            w.geometry("%dx%d+%d+%d" % (gw, gh, gx, gy))
            h["maxed"] = False
        else:
            h["restore"] = (w.winfo_width(), w.winfo_height(), w.winfo_x(), w.winfo_y())
            l, t, r, b = work_area(w)
            w.geometry("%dx%d+%d+%d" % (r - l, b - t, l, t))
            h["maxed"] = True

    def hub_zone(self, e):
        """Which window edge the mouse is on ('r', 'b', 'rb', 'l', 'lb' or '')."""
        h = self.hub
        if not h or h.get("maxed") or not self.cfg.get("borderless", True):
            return ""
        w = h["win"]
        x, y = e.x_root - w.winfo_rootx(), e.y_root - w.winfo_rooty()
        W, H = w.winfo_width(), w.winfo_height()
        z = ("l" if x <= 5 else "r" if x >= W - 6 else "") + ("b" if y >= H - 6 else "")
        return z

    def hub_resize_edges(self, w):
        """Borderless windows have no frame, so resizing is done by grabbing any edge (left/right/bottom)."""
        CUR = {"r": ("size_we", "sb_h_double_arrow"), "l": ("size_we", "sb_h_double_arrow"),
               "b": ("size_ns", "sb_v_double_arrow"), "rb": ("size_nw_se", "bottom_right_corner"),
               "lb": ("size_ne_sw", "bottom_left_corner")}
        st = {"cur": None}

        def set_cursor(widget, zone):
            if st["cur"] and st["cur"][0] is not widget:
                try:
                    st["cur"][0].config(cursor=st["cur"][1])
                except tk.TclError:
                    pass
                st["cur"] = None
            if zone:
                if st["cur"] is None:
                    try:
                        st["cur"] = (widget, widget.cget("cursor"))
                    except tk.TclError:
                        return
                for c in CUR[zone]:
                    try:
                        widget.config(cursor=c)
                        break
                    except tk.TclError:
                        continue
            elif st["cur"]:
                try:
                    st["cur"][0].config(cursor=st["cur"][1])
                except tk.TclError:
                    pass
                st["cur"] = None

        def motion(e):
            if self.hub and not self.hub.get("rs"):
                set_cursor(e.widget, self.hub_zone(e))

        def press(e):
            z = self.hub_zone(e)
            if z:
                self.hub["rs"] = (z, e.x_root, e.y_root, w.winfo_width(), w.winfo_height(), w.winfo_x(), w.winfo_y())
                self.hub["drag"] = None

        def drag(e):
            rs = self.hub.get("rs") if self.hub else None
            if not rs:
                return
            z, x0, y0, W0, H0, X0, Y0 = rs
            dx, dy = e.x_root - x0, e.y_root - y0
            W1, H1, X1 = W0, H0, X0
            if "r" in z:
                W1 = max(900, W0 + dx)
            if "l" in z:
                W1 = max(900, W0 - dx)
                X1 = X0 + (W0 - W1)
            if "b" in z:
                H1 = max(600, H0 + dy)
            w.geometry("%dx%d+%d+%d" % (W1, H1, X1, Y0))

        def release(e):
            if self.hub:
                self.hub["rs"] = None
        tag = str(w)
        w.bind("<Motion>", motion, add="+")
        w.bind("<ButtonPress-1>", press, add="+")
        w.bind("<B1-Motion>", drag, add="+")
        w.bind("<ButtonRelease-1>", release, add="+")

    def hub_fade_in(self, w):
        try:
            w.attributes("-alpha", 0.0)
        except tk.TclError:
            return
        t0 = time.monotonic()

        def step():
            try:
                a = min(1.0, (time.monotonic() - t0) / 0.22)
                w.attributes("-alpha", 1 - (1 - a) ** 2)
                if a < 1:
                    w.after(15, step)
            except tk.TclError:
                pass
        step()

    # ==== files & deadlines ==========================================================
    def on_files_dropped(self, paths):
        paths = [p for p in paths if os.path.isfile(p)][:8]
        if not paths:
            return
        self.import_files(paths)

    def pick_files(self):
        from tkinter import filedialog
        fs = filedialog.askopenfilenames(title="Pick your exam schedule, syllabus or calendar",
                                         filetypes=[("Documents", "*.pdf *.docx *.xlsx *.pptx *.txt *.csv *.ics *.md *.png *.jpg *.jpeg"),
                                                    ("All files", "*.*")])
        if fs:
            self.import_files(list(fs))

    def import_files(self, paths):
        self.open_hub("deadlines")
        self.dl_status("Reading %s..." % ", ".join(os.path.basename(p) for p in paths))
        self.say("Ooh, a file! Let me read it...", 6)
        self.set_mood("focus", 8)
        use_llm = self.cfg.get("llm_enabled", True)
        model = self.cfg.get("llm_model") or "llama3.2:3b"
        vm = self.cfg.get("vision_model", "qwen2.5vl:3b")
        day_first = self.cfg.get("date_day_first", True)

        def job():
            found, notes, texts = [], [], []
            for p in paths:
                name = os.path.basename(p)
                try:
                    text, ready = read_any_file(p, vm)
                except Exception as e:
                    notes.append("%s: %s" % (name, e))
                    continue
                texts.append((name, text))
                items = ready
                if items is None:
                    items = extract_deadlines(text, day_first)
                    if use_llm:
                        try:
                            smart = llm_deadlines(text, model)
                        except Exception:
                            smart = None
                        if smart:
                            have = {(i["date"]) for i in smart}
                            items = smart + [i for i in items if i["date"] not in have]
                for it in items:
                    it["source"] = name
                found += items
                if not items:
                    notes.append("%s: no dates found" % name)
            return found, notes, texts

        def done(res, err):
            if err:
                self.dl_status("Couldn't read that: %s" % err)
                return
            found, notes, texts = res
            if texts:
                self.last_file = texts[-1]
            existing = {(d["title"].lower(), d["date"]) for d in load_deadlines()}
            found = [f for f in found if (f["title"].lower(), f["date"]) not in existing]
            self.dl_review = found
            msg = ("Found %d date%s. Tick the ones to keep, fix anything, then press Add." % (len(found), "" if len(found) == 1 else "s")
                   if found else "No new deadlines found.")
            if notes:
                msg += "  (" + "; ".join(notes)[:200] + ")"
            self.dl_status(msg)
            self.say(("I found %d date%s in there - check the Upcoming page. (Say 'summarise that file' for a summary.)"
                      % (len(found), "" if len(found) == 1 else "s"))
                     if found else "I read it~ no dates in there, so here's a summary!", 8)
            if not found and texts:
                self.root.after(600, lambda: self.fox_reply(self.deadline_route("summarise that file") or ""))
            self.dl_render()
        self.bg(job, done)

    def dl_status(self, text):
        lab = getattr(self, "dl_status_lab", None)
        try:
            if lab is not None and lab.winfo_exists():
                lab.config(text=text)
        except tk.TclError:
            pass

    def add_deadline(self, title, date_iso, time_s="", kind=None, source="typed"):
        items = load_deadlines()
        items.append({"id": "%x" % random.getrandbits(40), "title": title.strip()[:90], "date": date_iso,
                      "time": time_s, "kind": kind or guess_kind(title), "source": source, "done": False})
        save_deadlines(items)
        self.dl_render()
        self.root.after(200, self.plan_maybe)

    def upcoming_deadlines(self, n=99):
        today = datetime.date.today().isoformat()
        return [d for d in load_deadlines() if not d.get("done") and d.get("date", "") >= today][:n]

    def deadline_reminders(self):
        """Once a day: tell me what's coming up in the next few days."""
        today = datetime.date.today().isoformat()
        if self.cfg.get("last_deadline_note") != today:
            soon = [d for d in self.upcoming_deadlines(10) if (datetime.date.fromisoformat(d["date"]) - datetime.date.today()).days <= 3]
            if soon:
                self.cfg["last_deadline_note"] = today
                save_config(self.cfg)
                first = soon[0]
                more = (" (+%d more this week)" % (len(soon) - 1)) if len(soon) > 1 else ""
                self.say("Heads up: %s is %s%s." % (first["title"], when_text(first["date"]), more), 12)
                beep("ding")
        self.root.after(30 * 60 * 1000, self.deadline_reminders)

    def deadline_route(self, text):
        low = text.lower().strip(" ?.!")
        if re.match(r"^(?:my |show (?:my )?|list (?:my )?|any |upcoming |what'?s (?:coming )?(?:up|due)|whats due|what is due|when is my next)"
                     r"(?:deadlines?|exams?|tests?|due dates?|calendar|assignments?)?\b.*$", low) and \
                re.search(r"deadline|exam|test|due|calendar|assignment|coming up", low):
            up = self.upcoming_deadlines(6)
            if not up:
                return "Nothing coming up. Drop your exam schedule on me (or the Upcoming page) and I'll add the dates."
            self.root.after(200, lambda: self.open_hub("deadlines"))
            return "Coming up:\n" + "\n".join("• %s - %s (%s)" % (d["title"], datetime.date.fromisoformat(d["date"]).strftime("%a %d %b"),
                                                                when_text(d["date"])) for d in up)
        m = re.match(r"^add (?:a )?(?:deadline|exam|test|quiz|assignment)[:\s]+(.+)$", text.strip(), re.I)
        if m:
            rest = m.group(1)
            ds = find_dates(rest, None, self.cfg.get("date_day_first", True))
            if not ds:
                return "When is it? e.g. 'add exam renal block on 12 Dec 9am'."
            d, s, e = ds[0]
            t, span = find_time(rest)
            title = rest
            for a, b in sorted([(s, e)] + ([span] if span else []), reverse=True):
                title = title[:a] + " " + title[b:]
            title = re.sub(r"\b(on|by|at|due)\s*$", "", re.sub(r"\s+", " ", title).strip(), flags=re.I).strip(" -,")
            word = re.match(r"^add (?:a )?(\w+)", text.strip(), re.I).group(1).lower()
            if word in ("exam", "test", "quiz", "assignment") and guess_kind(title) == "Deadline":
                title = (title + " " + word).strip()
            title = title[:1].upper() + title[1:]
            self.add_deadline(title, d.isoformat(), t)
            return "Added: %s on %s (%s)." % (title, d.strftime("%a %d %b %Y"), when_text(d.isoformat()))
        if re.match(r"^(?:summari[sz]e|explain|what'?s in|read) (?:that|the|this|my) (?:file|document|pdf)", low):
            lf = getattr(self, "last_file", None)
            if not lf:
                return "Drop a file on me first."
            name, body = lf
            model = self.cfg.get("llm_model") or "llama3.2:3b"

            def job():
                names = ollama_models() if self.cfg.get("llm_enabled", True) else None
                if not names:
                    return self.summarise_offline(name, body)
                m_ = model if model in names else (names or [model])[0]
                j = _ollama_json("/api/chat", {"model": m_, "stream": False, "options": {"num_predict": 500},
                                               "messages": [{"role": "system", "content": "Summarise this document in 5-8 short bullet points. " + self.user_profile_text()},
                                                            {"role": "user", "content": body[:8000]}]}, 240)
                return (j.get("message") or {}).get("content", "").strip()
            self.bg(job, lambda r, e: self.fox_reply(str(e) if e else r))
            return "Reading “%s”..." % name
        return None

    # ---- the Deadlines page ----
    def hub_build_deadlines(self, pg):
        self.hub_title(pg, "Upcoming", "Exams, deadlines and your study plan. Mark your free hours on the clock and I'll plan "
                                       "study sessions. Drop a file (exam schedule, syllabus) anywhere to add dates.")
        body = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        body.pack(fill="x", padx=24, pady=14)
        self.dl_body = body
        self.dl_month = datetime.date.today().replace(day=1)
        self.dl_day = None
        self.dl_render()

    def dl_render(self):
        body = getattr(self, "dl_body", None)
        if body is None or not body.winfo_exists():
            return
        for ch in body.winfo_children():
            ch.destroy()
        bg = T["card"]
        top = self.hub_card(body)
        top.pack(fill="x")
        r = tk.Frame(top, bg=bg)
        r.pack(fill="x", padx=16, pady=12)
        self.tt_btn(r, "Add from a file...", self.pick_files, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=3).pack(side="left")
        tk.Label(r, text="   or type an exam:", bg=bg, fg=GREY, font=(FONT_UI, 10)).pack(side="left")
        nv = tk.StringVar()
        ent = self.tt_entry(r, nv, 38)
        ent.pack(side="left", padx=8, ipady=2)

        def add_typed(_e=None):
            q = nv.get().strip()
            if not q:
                return
            res = self.life_add_typed(q)
            nv.set("")
            self.dl_status(res or "")
        ent.bind("<Return>", add_typed)
        self.tt_btn(r, "Add", add_typed, bg=T["start"], size=10, padx=12, pady=2).pack(side="left")
        self.dl_status_lab = tk.Label(top, text="e.g.  Renal block exam 12 Dec 9am   ·   Files: PDF, Word, Excel, "
                                                "PowerPoint, text, .ics calendar, photos", bg=bg, fg=GREY,
                                      font=(FONT_UI, 9), anchor="w", justify="left", wraplength=900)
        self.dl_status_lab.pack(fill="x", padx=16, pady=(0, 10))
        rev = getattr(self, "dl_review", None)
        if rev:
            self.dl_review_card(body, rev)
        try:
            self.up_row(body)
        except Exception as e:
            tk.Label(body, text="(The clock couldn't be drawn: %s)" % e, bg=PAPER, fg=GREY).pack()
        row = tk.Frame(body, bg=PAPER)
        row.pack(fill="x", pady=(12, 0))
        cal = self.hub_card(row)
        cal.pack(side="left", fill="y")
        self.dl_calendar(cal)
        lst = self.hub_card(row, "Coming up" if not self.dl_day else "On " + self.dl_day.strftime("%A %d %B"))
        lst.pack(side="left", fill="both", expand=True, padx=(12, 0))
        self.dl_list(lst)

    def dl_review_card(self, body, rev):
        bg = T["card"]
        c = self.hub_card(body, "Found in your file - keep which?")
        c.pack(fill="x", pady=(12, 0))
        rows = []
        for it in rev[:40]:
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=16, pady=1)
            keep = tk.BooleanVar(value=True)
            tk.Checkbutton(r, variable=keep, bg=bg, activebackground=bg, selectcolor=FIELD).pack(side="left")
            tv = tk.StringVar(value=it["title"])
            self.tt_entry(r, tv, 40).pack(side="left", padx=(0, 8))
            dv = tk.StringVar(value=it["date"])
            self.tt_entry(r, dv, 11).pack(side="left", padx=(0, 6))
            mv = tk.StringVar(value=it.get("time", ""))
            self.tt_entry(r, mv, 6).pack(side="left", padx=(0, 8))
            tk.Label(r, text=it.get("kind", ""), bg=bg, fg=ORANGE_D, font=(FONT_UI, 9, "bold")).pack(side="left")
            tk.Label(r, text="  " + when_text(it["date"]), bg=bg, fg=GREY, font=(FONT_UI, 9)).pack(side="left")
            rows.append((keep, tv, dv, mv, it))
        b = tk.Frame(c, bg=bg)
        b.pack(fill="x", padx=16, pady=(8, 12))

        def add_sel():
            n = 0
            items = load_deadlines()
            for keep, tv, dv, mv, it in rows:
                if not keep.get():
                    continue
                try:
                    d = datetime.date.fromisoformat(dv.get().strip())
                except ValueError:
                    ds = find_dates(dv.get(), None, self.cfg.get("date_day_first", True))
                    if not ds:
                        continue
                    d = ds[0][0]
                t = mv.get().strip()
                items.append({"id": "%x" % random.getrandbits(40), "title": tv.get().strip()[:90] or it["title"],
                              "date": d.isoformat(), "time": t if re.match(r"^\d\d:\d\d$", t) else "",
                              "kind": it.get("kind") or guess_kind(tv.get()), "source": it.get("source", ""), "done": False})
                n += 1
            save_deadlines(items)
            self.dl_review = None
            self.dl_render()
            self.root.after(200, self.plan_maybe)
            self.dl_status("Added %d deadline%s." % (n, "" if n == 1 else "s"))
            self.say("Added %d deadline%s. I'll remind you as they get close." % (n, "" if n == 1 else "s"), 7)
            self.set_mood("happy", 3)

        def discard():
            self.dl_review = None
            self.dl_render()
        self.tt_btn(b, "Add selected", add_sel, bg=ORANGE, fg=ON_ACC, size=10, padx=16, pady=3).pack(side="left")
        self.tt_btn(b, "Discard", discard, bg=FIELD, size=10, padx=12, pady=3).pack(side="left", padx=8)

    def dl_calendar(self, c):
        bg = T["card"]
        m0 = self.dl_month
        head = tk.Frame(c, bg=bg)
        head.pack(fill="x", padx=14, pady=(12, 6))

        def shift(k):
            y, mo = m0.year + (m0.month - 1 + k) // 12, (m0.month - 1 + k) % 12 + 1
            self.dl_month = datetime.date(y, mo, 1)
            self.dl_render()
        self.tt_btn(head, "<", lambda: shift(-1), bg=FIELD, size=10, padx=8, pady=0).pack(side="left")
        tk.Label(head, text=m0.strftime("%B %Y"), bg=bg, fg=INK, font=(FONT_UI, 13, "bold"), width=15).pack(side="left", padx=6)
        self.tt_btn(head, ">", lambda: shift(1), bg=FIELD, size=10, padx=8, pady=0).pack(side="left")
        cell, gap = 46, 4
        cv = tk.Canvas(c, width=7 * (cell + gap), height=7 * (cell + gap) - 10, bg=bg, highlightthickness=0)
        cv.pack(padx=14, pady=(0, 12))
        for i, dname in enumerate(["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]):
            cv.create_text(i * (cell + gap) + cell / 2, 10, text=dname, fill=GREY, font=(FONT_UI, 9, "bold"))
        by_day = {}
        for d in load_deadlines():
            if not d.get("done"):
                by_day.setdefault(d["date"], []).append(d)
        today = datetime.date.today()
        start = m0 - datetime.timedelta(days=m0.weekday())
        for k in range(42):
            day = start + datetime.timedelta(days=k)
            col, rowi = k % 7, k // 7
            x, y = col * (cell + gap), 24 + rowi * (cell + gap)
            inmonth = day.month == m0.month
            items = by_day.get(day.isoformat(), [])
            fill = FIELD if inmonth else T["card"]
            if day == today:
                fill = T["nowbg"]
            if self.dl_day == day:
                fill = T["start"]
            outline = GOLD if day == today else (ORANGE if items else LINE)
            r = cv.create_rectangle(x, y, x + cell, y + cell, fill=fill, outline=outline, width=2 if (items or day == today) else 1)
            t = cv.create_text(x + 6, y + 5, text=str(day.day), anchor="nw", fill=INK if inmonth else GREY,
                               font=(FONT_UI, 9, "bold" if day == today else "normal"))
            tags = [r, t]
            if items:
                urgent = any(i.get("kind") in ("Exam", "Quiz") for i in items)
                for j in range(min(3, len(items))):
                    tags.append(cv.create_oval(x + 7 + j * 10, y + cell - 13, x + 14 + j * 10, y + cell - 6,
                                               fill=T["bad"] if urgent else ORANGE, outline=""))
            for tg in tags:
                cv.tag_bind(tg, "<Button-1>", lambda e=None, d=day: self.dl_pick_day(d))
        if self.dl_day:
            self.tt_btn(c, "Show all", lambda: self.dl_pick_day(None), bg=FIELD, size=9, padx=10, pady=1).pack(pady=(0, 12))

    def dl_pick_day(self, d):
        self.dl_day = None if (d is None or d == self.dl_day) else d
        self.dl_render()

    def dl_list(self, c):
        bg = T["card"]
        items = load_deadlines()
        today = datetime.date.today().isoformat()
        if self.dl_day:
            show = [d for d in items if d["date"] == self.dl_day.isoformat()]
        else:
            overdue = [d for d in items if d["date"] < today and not d.get("done")]
            show = overdue[-5:] + [d for d in items if d["date"] >= today and not d.get("done")]
        if not show:
            tk.Label(c, text="Nothing here yet. Drop your exam schedule on this window or on the fox.", bg=bg, fg=GREY,
                     font=(FONT_UI, 10), anchor="w").pack(fill="x", padx=16, pady=(4, 16))
            return
        for d in show[:30]:
            late = d["date"] < today
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=16, pady=3)
            dt = datetime.date.fromisoformat(d["date"])
            badge = tk.Frame(r, bg=T["bad"] if late else (ORANGE if d.get("kind") in ("Exam", "Quiz") else T["start"]), width=52, height=44)
            badge.pack(side="left")
            badge.pack_propagate(False)
            fgc = ON_ACC if (late or d.get("kind") in ("Exam", "Quiz")) else INK
            tk.Label(badge, text=dt.strftime("%d"), bg=badge["bg"], fg=fgc, font=(FONT_UI, 13, "bold")).pack(pady=(2, 0))
            tk.Label(badge, text=dt.strftime("%b").upper(), bg=badge["bg"], fg=fgc, font=(FONT_UI, 7, "bold")).pack()
            mid = tk.Frame(r, bg=bg)
            mid.pack(side="left", fill="x", expand=True, padx=10)
            tk.Label(mid, text=d["title"], bg=bg, fg=INK, font=(FONT_UI, 11, "bold"), anchor="w").pack(fill="x")
            sub = "%s  ·  %s%s" % (d.get("kind", ""), ("overdue - " if late else "") + when_text(d["date"]),
                                    ("  ·  " + d["time"]) if d.get("time") else "")
            tk.Label(mid, text=sub, bg=bg, fg=T["bad"] if late else GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x")

            def mark(i=d["id"] if d.get("id") else None, title=d["title"], date=d["date"], delete=False):
                its = load_deadlines()
                for x in its:
                    if (x.get("id") == i and i) or (x["title"] == title and x["date"] == date):
                        if delete:
                            its.remove(x)
                        else:
                            x["done"] = True
                        break
                save_deadlines(its)
                self.dl_render()
                self.root.after(200, self.plan_maybe)
            self.tt_btn(r, "Done", lambda f=mark: f(), bg=T["donebtn"], size=9, padx=8, pady=1).pack(side="right", padx=2)
            self.tt_btn(r, "Delete", lambda f=mark: f(delete=True), bg=T["delbtn"], size=9, padx=8, pady=1).pack(side="right", padx=2)
        tk.Frame(c, bg=bg, height=10).pack()

    # ==== apps =====================================================================
    def app_route(self, text):
        m = re.match(r"^(?:please )?(?:open|launch|run|start up|fire up)\s+(?:my |the )?(.+?)\s*[.!?]*$",
                     text.strip(), re.I)
        if not m:
            return None
        target = m.group(1).lower().strip()
        pages = {"timetable": "timetable", "schedule": "timetable", "reminders": "reminders", "ema": "reminders", "chat": "chat", "notes": "notes", "settings": "settings",
                 "deadlines": "deadlines", "calendar": "deadlines", "exams": "deadlines", "home": "home",
                 "upcoming": "deadlines", "study plan": "deadlines", "planner": "deadlines", "clock": "deadlines",
                 "daily": "daily", "badges": "daily", "journal": "daily", "flashcards": "daily",
                 "profile": "you", "you": "you", "dashboard": "home"}
        if target in pages and not (target == "calendar" and re.search(r"outlook|windows|google", text, re.I)):
            self.open_hub(pages[target])
            return "Here you go."
        if target in ("zenko", "window", "app"):
            self.open_hub()
            return "Here I am."
        return open_app(target)

    # ==== battery ==================================================================
    def battery_tick(self):
        st = battery_status()
        self.battery = st
        if st and self.cfg.get("battery_on_tail", True):
            pct, charging = st
            warn = 10 if pct <= 10 else (20 if pct <= 20 else None)
            if charging or pct > 25:
                self.batt_warned = set()
            elif warn and warn not in self.batt_warned:
                self.batt_warned.add(warn)
                self.set_mood("sad", 4)
                beep("sad")
                self.say("My tail says %d%% battery! Plug in the charger%s." % (pct, " NOW" if warn == 10 else ""), 12)
        self._batt_key = None
        self.root.after(30000, self.battery_tick)

    def draw_battery(self, dx, dy, curled=False):
        st = getattr(self, "battery", None) if self.cfg.get("battery_on_tail", True) else None
        key = (st, dx, dy, curled, self.Z, INK)
        if key == getattr(self, "_batt_key", None):
            return
        self._batt_key = key
        c = self.canvas
        c.delete("batt")
        if not st:
            return
        pct, charging = st
        Z = self.Z * 2
        bx, by = (60, 66) if not curled else (58, 50)               # fine sprite pixel position: at the base of the tails
        ox, oy = self.COLW + dx + bx * self.Z, self.fox_y + dy + by * self.Z
        w, h = 8 * Z, 5 * Z
        dark = self.pal.get("K", "#222222")
        c.create_rectangle(ox, oy, ox + w, oy + h, fill=_mixhex(T["night"], "#000000", 0.2), outline=GOLD,
                           width=max(1, self.Z), tags="batt")
        c.create_rectangle(ox + w, oy + Z * 1.5, ox + w + Z, oy + h - Z * 1.5, fill=GOLD, outline="", tags="batt")
        col = "#5fd39a" if pct > 50 else ("#f2c14e" if pct > 20 else "#ff5468")
        fillw = max(Z, int((w - 2 * Z) * pct / 100.0))
        c.create_rectangle(ox + Z, oy + Z, ox + Z + fillw, oy + h - Z, fill=col, outline="", tags="batt")
        c.create_rectangle(ox + Z, oy + Z, ox + Z + fillw, oy + Z + max(1, self.Z), fill=_mixhex(col, "#ffffff", 0.5), outline="", tags="batt")
        if charging:
            pts = [ox + 4.5 * Z, oy + 0.6 * Z, ox + 2.6 * Z, oy + 2.7 * Z, ox + 4 * Z, oy + 2.7 * Z,
                   ox + 3.3 * Z, oy + 4.4 * Z, ox + 5.4 * Z, oy + 2.2 * Z, ox + 4 * Z, oy + 2.2 * Z]
            c.create_polygon(pts, fill="#ffe066", outline=dark, width=1, tags="batt")

    def battery_text(self):
        st = getattr(self, "battery", None)
        if not st:
            return "No battery (desktop PC)."
        return "Battery: %d%%%s." % (st[0], ", charging" if st[1] else "")

    # ==== music presets ============================================================
    def find_preset(self, q):
        q = re.sub(r"\bfavorite\b", "favourite", q.lower())
        q = re.sub(r"\b(my|the|preset|please|music|some)\b", " ", q)
        q = re.sub(r"\s+", " ", q).strip()
        if not q:
            return None
        presets = [p for p in self.cfg.get("music_presets", []) if p.get("value")]
        m = re.match(r"^(?:number |no\.? ?|#)?(\d)$", q)
        if m:
            i = int(m.group(1)) - 1
            allp = self.cfg.get("music_presets", [])
            return allp[i] if 0 <= i < len(allp) and allp[i].get("value") else None
        best, sc = None, 0.0
        for p in presets:
            name = re.sub(r"\bfavorite\b", "favourite", p.get("name", "").lower())
            s = difflib.SequenceMatcher(None, q, name).ratio() + (0.4 if q in name or name in q else 0)
            if s > sc:
                best, sc = p, s
        return best if sc >= 0.8 else None

    def play_preset(self, p, quiet=False):
        sp = self.spotify
        val, kind = p.get("value", "").strip(), p.get("kind", "playlist")

        def job():
            uri = spotify_link_to_uri(val)
            if uri:
                if uri.startswith("spotify:track:"):
                    sp.call("PUT", "/me/player/play", body={"uris": [uri]})
                else:
                    sp.call("PUT", "/me/player/play", body={"context_uri": uri})
                return "Playing your “%s” preset." % p.get("name", "")
            if kind == "playlist":
                return sp.play_query(val + " playlist")
            if kind in ("album", "artist"):
                res = sp.api("GET", "/search", {"q": val, "type": kind, "limit": 1}) or {}
                its = [i for i in ((res.get(kind + "s") or {}).get("items") or []) if i]
                if not its:
                    return "I couldn't find “%s” on Spotify." % val
                sp.call("PUT", "/me/player/play", body={"context_uri": its[0]["uri"]})
                return "Playing %s “%s”." % (kind, its[0].get("name"))
            return sp.play_query(val)
        self.bg(job, lambda r, e: (None if quiet and not e else self.fox_reply(str(e) if e else r), self.music_refresh()))
        return "On it..."

    # ==== "You" page: what the fox knows about you ===================================
    def hub_build_you(self, pg):
        self.hub_title(pg, "About you", "Tell the fox about yourself. It uses this to talk to you and give better help.")
        body = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        body.pack(fill="x", padx=24, pady=14)
        bg = T["card"]
        c = self.hub_card(body, "Profile")
        c.pack(fill="x")
        fields = (("user_name", "Your name (the fox calls you by your first name)", 30, 1),
                  ("user_role", "What do you do? (e.g. 'pathology professor', 'medical student')", 50, 1),
                  ("user_studying", "What are you working on or studying these days?", 60, 2),
                  ("user_goals", "Your goals (exams, deadlines, habits...)", 60, 3),
                  ("user_notes", "Anything else the fox should know (how you like to be spoken to, your routine...)", 60, 5))
        widgets = {}
        st = tk.Label(c, text="", bg=bg, fg=ORANGE_D, font=(FONT_UI, 9, "bold"), anchor="w")

        def save(_e=None):
            for k, (kind, w) in widgets.items():
                v = w.get() if kind == "e" else w.get("1.0", "end")
                self.cfg[k] = v.strip()[:1200]
            save_config(self.cfg)
            st.config(text="Saved. " + ("Nice to meet you, %s!" % self.user_short() if self.user_short() else ""))
        for key, lab, width, lines in fields:
            tk.Label(c, text=lab, bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=16, pady=(8, 2))
            if lines == 1:
                v = tk.StringVar(value=self.cfg.get(key, ""))
                e = self.tt_entry(c, v, width)
                e.pack(anchor="w", padx=16)
                e.bind("<FocusOut>", save)
                e.bind("<Return>", save)
                widgets[key] = ("e", v)
            else:
                t = tk.Text(c, height=lines, width=width, wrap="word", font=(FONT_UI, 11), bg=FIELD, fg=INK,
                            relief="flat", highlightthickness=1, highlightbackground=LINE, highlightcolor=ORANGE,
                            padx=6, pady=4, insertbackground=INK)
                t.insert("1.0", self.cfg.get(key, ""))
                t.pack(fill="x", padx=16)
                t.bind("<FocusOut>", save)
                widgets[key] = ("t", t)
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=16, pady=(12, 4))
        self.tt_btn(r, "Save", save, bg=ORANGE, fg=ON_ACC, size=11, padx=18, pady=3).pack(side="left")
        st.pack(fill="x", padx=16, pady=(0, 12))
        c2 = self.hub_card(body, "How it's used")
        c2.pack(fill="x", pady=(12, 0))
        tk.Label(c2, text=("Your name appears in greetings, nudges and the fox's voice. Everything here is sent only to "
                           "the offline smart brain on this PC (Ollama), so its answers, note summaries and screen help "
                           "fit you. It's stored in Zenko's settings on this PC and never uploaded."),
                 bg=bg, fg=INK, font=(FONT_UI, 10), anchor="w", justify="left", wraplength=700).pack(fill="x", padx=16, pady=(0, 14))
        c3 = self.hub_card(body, "What Zenko has learned")
        c3.pack(fill="x", pady=(12, 0))
        lv = tk.BooleanVar(value=bool(self.cfg.get("learn_habits", True)))

        def set_learn():
            self.cfg["learn_habits"] = bool(lv.get())
            save_config(self.cfg)
        tk.Checkbutton(c3, text="Let Zenko learn my habits (kept only on this PC)", variable=lv, command=set_learn, bg=bg, fg=INK,
                       selectcolor=FIELD, activebackground=bg, activeforeground=INK, font=(FONT_UI, 10), anchor="w",
                       highlightthickness=0, bd=0).pack(fill="x", padx=14, pady=(0, 2))
        sv = tk.BooleanVar(value=bool(self.cfg.get("learn_style", True)))

        def set_style():
            self.cfg["learn_style"] = bool(sv.get())
            save_config(self.cfg)
        tk.Checkbutton(c3, text="Let Zenko learn my shorthand, e.g. sched = timetable (kept only on this PC)", variable=sv,
                       command=set_style, bg=bg, fg=INK, selectcolor=FIELD, activebackground=bg, activeforeground=INK,
                       font=(FONT_UI, 10), anchor="w", highlightthickness=0, bd=0).pack(fill="x", padx=14, pady=(0, 6))
        info = tk.Label(c3, text=learned_summary(), bg=bg, fg=INK, font=(FONT_UI, 10), anchor="w", justify="left", wraplength=700)
        info.pack(fill="x", padx=16)
        tk.Label(c3, text="Teach her in Chat:  learn: good morning = Ohayo! Let's get to work.    "
                          "Undo with:  forget good morning\nShorthand:  when I say sched I mean timetable.    "
                          "Ask her:  what's my shorthand?   what did you look up?", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w", justify="left",
                 wraplength=700).pack(fill="x", padx=16, pady=(6, 0))
        r3 = tk.Frame(c3, bg=bg)
        r3.pack(fill="x", padx=16, pady=(8, 12))

        def wipe():
            forget_reply("everything")
            info.config(text=learned_summary())
            self.say("Okay, I've forgotten everything I learned. Fresh start!", 5)
        self.tt_btn(r3, "Forget everything", wipe, bg=T["delbtn"], size=9, padx=10, pady=2).pack(side="left")

    # ==== Notes page (reMarkable) ===================================================
    def hub_build_notes(self, pg):
        self.hub_title(pg, "reMarkable notes", "Read your handwritten notebooks, then summarise, search or quiz yourself")
        body = tk.Frame(self.hub_scroller(pg), bg=PAPER)
        body.pack(fill="x", padx=24, pady=14)
        self.notes_body = body
        self.notes_render()

    def notes_render(self):
        body = getattr(self, "notes_body", None)
        if body is None or not body.winfo_exists():
            return
        for ch in body.winfo_children():
            ch.destroy()
        bg = T["card"]
        lab = lambda p, t, **k: tk.Label(p, text=t, bg=bg, fg=k.get("fg", INK), font=k.get("font", (FONT_UI, 10)),
                                         anchor="w", justify="left", wraplength=k.get("wrap", 640))
        if not rm_tool() or not rm_paired():
            c = self.hub_card(body, "Connect your reMarkable (one time)")
            c.pack(fill="x")
            lab(c, "Uses your Connect subscription through rmapi, a free open-source helper. Your notes are "
                   "downloaded to this PC only and read here.", fg=GREY).pack(fill="x", padx=14)
            st = lab(c, "", fg=ORANGE_D)
            r1 = tk.Frame(c, bg=bg)
            r1.pack(fill="x", padx=14, pady=(10, 4))
            done1 = bool(rm_tool())
            lab(r1, ("1.  Helper installed" if done1 else "1.  Download the helper (about 10 MB)"),
                font=(FONT_UI, 11, "bold")).pack(side="left")
            if not done1:
                def inst():
                    st.config(text="Downloading rmapi...")
                    self.bg(rm_install_tool, lambda r, e: (st.config(text=str(e) if e else "Installed."), None if e else self.notes_render()))
                self.tt_btn(r1, "Download", inst, bg=T["start"], size=9, padx=10, pady=1).pack(side="left", padx=10)

                def manual():
                    webbrowser.open("https://github.com/ddvk/rmapi/releases/latest")
                    st.config(text="In your browser, download the Windows file (its name contains 'windows'), "
                                   "then press 'I downloaded it' and pick that file.")

                def pick():
                    from tkinter import filedialog
                    f = filedialog.askopenfilename(title="Pick the rmapi download (.zip or rmapi.exe)",
                                                   initialdir=os.path.join(os.path.expanduser("~"), "Downloads"),
                                                   filetypes=[("rmapi", "*.zip *.exe"), ("All files", "*.*")])
                    if not f:
                        return
                    try:
                        rm_install_from_file(f)
                        self.notes_render()
                    except Exception as e:
                        st.config(text=str(e))
                self.tt_btn(r1, "Download manually", manual, bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
                self.tt_btn(r1, "I downloaded it", pick, bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=6)
            r2 = tk.Frame(c, bg=bg)
            r2.pack(fill="x", padx=14, pady=4)
            lab(r2, "2.  Get a one-time code", font=(FONT_UI, 11, "bold")).pack(side="left")
            self.tt_btn(r2, "Open my.remarkable.com", lambda: webbrowser.open("https://my.remarkable.com/device/desktop/connect"),
                        bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=10)
            r3 = tk.Frame(c, bg=bg)
            r3.pack(fill="x", padx=14, pady=(4, 6))
            lab(r3, "3.  Paste the code", font=(FONT_UI, 11, "bold")).pack(side="left")
            cv = tk.StringVar()
            self.tt_entry(r3, cv, 14).pack(side="left", padx=10)

            def pair():
                if not rm_tool():
                    self.notes_render()                  # show the Download buttons again
                    return
                st.config(text="Connecting...")
                self.bg(lambda: rm_pair(cv.get()), lambda r, e: (st.config(text=str(e)) if e else self.notes_render()))
            self.tt_btn(r3, "Connect", pair, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=2).pack(side="left")
            st.pack(fill="x", padx=14, pady=(0, 12))
            self.notes_tips(body)
            return
        top = tk.Frame(body, bg=PAPER)
        top.pack(fill="x")
        # left: cloud browser
        c = self.hub_card(top, "On your reMarkable")
        c.pack(side="left", fill="both", expand=True)
        path_lab = lab(c, "/", fg=GREY)
        path_lab.pack(fill="x", padx=14)
        lb = tk.Listbox(c, height=13, font=(FONT_UI, 11), bg=FIELD, fg=INK, relief="flat", highlightthickness=1,
                        highlightbackground=LINE, selectbackground=ORANGE, selectforeground=ON_ACC, activestyle="none")
        lb.pack(fill="both", expand=True, padx=14, pady=6)
        st = lab(c, "", fg=ORANGE_D)
        row = tk.Frame(c, bg=bg)
        row.pack(fill="x", padx=14, pady=(0, 4))
        state = {"path": "/", "items": []}

        def load(path):
            st.config(text="Loading...")

            def done(res, err):
                if err:
                    st.config(text=str(err))
                    return
                state["path"], state["items"] = path, res
                path_lab.config(text=path)
                lb.delete(0, "end")
                for k, n in res:
                    lb.insert("end", (n + "  /") if k == "d" else n)
                st.config(text="%d items. Double-click a folder to open it." % len(res))
            self.bg(lambda: rm_ls(path), done)

        def sel():
            i = lb.curselection()
            return state["items"][i[0]] if i else None

        def opened(_e=None):
            it = sel()
            if it and it[0] == "d":
                load((state["path"].rstrip("/") + "/" + it[1]) if state["path"] != "/" else "/" + it[1])

        def up():
            p = state["path"].rstrip("/")
            load(p.rsplit("/", 1)[0] or "/")

        def read():
            it = sel()
            if not it or it[0] != "f":
                st.config(text="Pick a notebook first.")
                return
            full = (state["path"].rstrip("/") + "/" + it[1]) if state["path"] != "/" else "/" + it[1]
            name = rm_safe(it[1])
            vm = self.cfg.get("vision_model", "qwen2.5vl:3b")

            def prog(msg):
                self.ext_q.put((lambda r, e, m=msg: st.config(text=m), None, None))

            def job():
                prog("Downloading “%s”..." % it[1])
                docp = rm_download(full)
                prog("Reading pages...")
                try:
                    md = rm_read_doc(docp, vm, prog)
                except RMError as e:
                    if str(e) == "NEED_RMSCENE":
                        py = system_python()
                        if getattr(sys, "frozen", False) or not py:
                            raise RMError("This build can't read notebooks yet: rebuild with build_exe.bat (it now adds the reader).")
                        prog("Installing the free notebook reader (rmscene)...")
                        r = run_hidden([py, "-m", "pip", "install", "rmscene"], timeout=600)
                        if r.returncode != 0:
                            raise RMError("Couldn't install rmscene. Run:  pip install rmscene")
                        import importlib
                        importlib.invalidate_caches()
                        md = rm_read_doc(docp, vm, prog)
                    else:
                        raise
                with open(os.path.join(RM_NOTES, name + ".md"), "w", encoding="utf-8") as f:
                    f.write("# %s\n\n%s\n" % (it[1], md))
                return name

            def done(res, err):
                st.config(text=str(err) if err else "Done! “%s” is in My notes." % res)
                if not err:
                    self.notes_show(res)
            self.bg(job, done)
        lb.bind("<Double-Button-1>", opened)
        self.tt_btn(row, "Up", up, bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))
        self.tt_btn(row, "Refresh", lambda: load(state["path"]), bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))
        self.tt_btn(row, "Read this notebook", read, bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=2).pack(side="left")
        st.pack(fill="x", padx=14, pady=(2, 12))
        # right: notes already read
        c2 = self.hub_card(top, "My notes (read)")
        c2.pack(side="left", fill="both", expand=True, padx=(12, 0))
        lb2 = tk.Listbox(c2, height=6, font=(FONT_UI, 11), bg=FIELD, fg=INK, relief="flat", highlightthickness=1,
                         highlightbackground=LINE, selectbackground=ORANGE, selectforeground=ON_ACC, activestyle="none")
        lb2.pack(fill="x", padx=14, pady=6)
        txt = tk.Text(c2, height=11, wrap="word", font=(FONT_UI, 10), bg=FIELD, fg=INK, insertbackground=INK, relief="flat",
                      highlightthickness=1, highlightbackground=LINE, padx=8, pady=6)
        txt.pack(fill="both", expand=True, padx=14)
        r2 = tk.Frame(c2, bg=bg)
        r2.pack(fill="x", padx=14, pady=(6, 12))
        self.notes_widgets = (lb2, txt)

        def cur():
            i = lb2.curselection()
            return lb2.get(i[0]) if i else None

        def act(task):
            n = cur()
            if not n:
                return
            self.hub_show("chat")
            self.chat_line("You", {"summary": "summarise my notes on ", "quiz": "quiz me on "}[task] + n)
            self.chat_line("Fox", self.notes_llm(task, n))
        lb2.bind("<<ListboxSelect>>", lambda e: cur() and self.notes_show(cur(), select=False))
        self.tt_btn(r2, "Summarise", lambda: act("summary"), bg=T["start"], size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))
        self.tt_btn(r2, "Quiz me", lambda: act("quiz"), bg=T["start"], size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))
        self.tt_btn(r2, "Open folder", lambda: os.startfile(RM_NOTES) if IS_WIN else None, bg=FIELD, size=9, padx=10,
                    pady=1).pack(side="left")
        self.notes_list_refresh()
        load("/")
        self.notes_tips(body)

    def notes_tips(self, body):
        c = self.hub_card(body, "Reading handwriting")
        c.pack(fill="x", pady=(12, 0))
        vm = self.cfg.get("vision_model", "qwen2.5vl:3b")
        tk.Label(c, text=("Typed text is read instantly. Handwriting is read on this PC by a free vision model in Ollama. "
                          "Install it once (about 3 GB) by running this in Command Prompt:"), bg=T["card"], fg=GREY,
                 font=(FONT_UI, 10), anchor="w", justify="left", wraplength=640).pack(fill="x", padx=14)
        r = tk.Frame(c, bg=T["card"])
        r.pack(fill="x", padx=14, pady=(6, 12))
        cmd = "ollama pull " + vm
        tk.Label(r, text=cmd, bg=FIELD, fg=INK, font=("Consolas", 11), padx=8, pady=3,
                 highlightthickness=1, highlightbackground=LINE).pack(side="left")
        self.tt_btn(r, "Copy", lambda: (self.root.clipboard_clear(), self.root.clipboard_append(cmd), self.say("Copied!", 3)),
                    bg=FIELD, size=9, padx=10, pady=1).pack(side="left", padx=8)
        tk.Label(c, text="Tip: chat with  'summarise my notes on renal'  ·  'quiz me on GI'  ·  'ask notes: what causes RPGN?'",
                 bg=T["card"], fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=14, pady=(0, 12))

    def notes_list_refresh(self):
        w = getattr(self, "notes_widgets", None)
        if not w:
            return
        lb2, txt = w
        try:
            lb2.delete(0, "end")
            for n in sorted(notes_index()):
                lb2.insert("end", n)
        except tk.TclError:
            pass

    def notes_show(self, name, select=True):
        w = getattr(self, "notes_widgets", None)
        if select:
            self.notes_list_refresh()
        if not w:
            return
        lb2, txt = w
        path = notes_index().get(name)
        if not path:
            return
        try:
            with open(path, encoding="utf-8") as f:
                body = f.read()
            txt.config(state="normal")
            txt.delete("1.0", "end")
            txt.insert("1.0", body)
            if select:
                items = lb2.get(0, "end")
                if name in items:
                    lb2.selection_clear(0, "end")
                    lb2.selection_set(items.index(name))
        except (OSError, tk.TclError):
            pass

    # ==== settings cards for the extras =============================================
    def hub_settings_extras(self, left, right, check, radios, label, cfg_set):
        bg = T["card"]
        # Voice
        c = self.hub_card(left, "Voice and screen buddy")
        c.pack(fill="x", pady=(12, 0))
        vv = tk.BooleanVar(value=bool(self.cfg.get("voice_enabled", True)))
        check(c, "Push-to-talk hotkeys on", vv, lambda: cfg_set("voice_enabled", bool(vv.get())))
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=14, pady=(4, 0))
        for text, key, default in (("Hold to talk", "voice_key", "Right Ctrl"), ("Hold to ask about screen", "screen_key", "F8")):
            tk.Label(r, text=text, bg=bg, fg=INK, font=(FONT_UI, 10)).pack(side="left")
            v = tk.StringVar(value=self.cfg.get(key, default))
            om = tk.OptionMenu(r, v, *HOTKEYS.keys(), command=lambda val, k=key: cfg_set(k, val))
            om.config(bg=FIELD, fg=INK, activebackground=T["hover"], activeforeground=INK, highlightbackground=LINE, relief="flat", highlightthickness=1, font=(FONT_UI, 9), width=9)
            om.pack(side="left", padx=(6, 14))
        label(c, "Speech engine")
        eng = tk.StringVar(value=self.cfg.get("voice_engine", "auto"))
        radios(c, (("Best available", "auto"), ("Windows built-in", "windows"), ("Whisper", "whisper")), eng,
               lambda: (cfg_set("voice_engine", eng.get()), self.voice.stop()))
        label(c, "Whisper accuracy (bigger = more accurate, slower; downloads once)")
        wm = tk.StringVar(value=self.cfg.get("whisper_model", "small.en"))
        radios(c, (("Fast", "base.en"), ("Accurate", "small.en"), ("Best", "medium.en")), wm,
               lambda: (cfg_set("whisper_model", wm.get()), cfg_set("whisper_model_set", True), self.voice.stop()))
        st = tk.Label(c, text="", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w", justify="left", wraplength=420)

        def check_engine():
            st.config(text="Checking...")

            def done(ok, e):
                if ok:
                    msg = "Whisper is installed. "
                    if self.voice.alive() and self.voice.kind:
                        msg += "In use now: %s." % ("Whisper (%s)" % self.cfg.get("whisper_model") if self.voice.kind == "whisper"
                                                    else "Windows built-in (switch the engine above to Whisper)")
                    else:
                        msg += "It starts the next time you talk."
                else:
                    msg = ("Whisper isn't installed for the Python I can see, so Windows' built-in speech is used "
                           "(less accurate). Press Install Whisper.")
                st.config(text=msg)
            self.bg(whisper_ready, done)

        def inst():
            st.config(text="Installing Whisper... this can take a few minutes. You can keep working.")
            self.install_whisper(lambda r, e: (st.config(text=str(e) if e else "Whisper installed! First use downloads its model."),
                                               self.voice.stop()))
        rr = tk.Frame(c, bg=bg)
        rr.pack(fill="x", padx=14, pady=(4, 2))
        self.tt_btn(rr, "Install Whisper", inst, bg=T["start"], size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))
        self.tt_btn(rr, "Test my voice", lambda: self.voice_toggle("chat"), bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        st.pack(fill="x", padx=14, pady=(4, 0))
        label(c, "Screen buddy 'eyes' (Ollama vision model)")
        vm = tk.StringVar(value=self.cfg.get("vision_model", "qwen2.5vl:3b"))
        e = self.tt_entry(c, vm, 20)
        e.pack(anchor="w", padx=14, pady=(2, 12))
        e.bind("<FocusOut>", lambda ev: cfg_set("vision_model", vm.get().strip() or "qwen2.5vl:3b"))
        check_engine()

        # The fox's own voice
        c = self.hub_card(left, "Fox's voice")
        c.pack(fill="x", pady=(12, 0))
        label(c, "Fox talks back")
        sm = tk.StringVar(value=self.cfg.get("speak_mode", "voice"))
        radios(c, (("Off", "off"), ("When I talk", "voice"), ("Always", "always")), sm,
               lambda: (cfg_set("speak_mode", sm.get()), self.speaker.hush()))
        label(c, "Voice")
        choices = [("Windows default", "")] + [("Natural: " + n, "piper:" + v) for n, v in PIPER_VOICES]
        cur = self.cfg.get("tts_voice", "")
        if cur and cur not in [v for _, v in choices]:
            choices.append(("Windows: " + cur[4:], cur))
        names = {v: n for n, v in choices}
        voice_v = tk.StringVar(value=names.get(cur, "Windows default"))
        om = tk.OptionMenu(c, voice_v, *[n for n, _ in choices])
        om.config(bg=FIELD, fg=INK, activebackground=T["hover"], activeforeground=INK, highlightbackground=LINE, relief="flat", highlightthickness=1, font=(FONT_UI, 10), width=32, anchor="w")
        om.pack(anchor="w", padx=14, pady=(2, 0))
        vst = tk.Label(c, text="", bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w", justify="left", wraplength=420)

        def pick(name):
            val = {n: v for n, v in choices}.get(name, "")
            cfg_set("tts_voice", val)
            self.speaker.stop()
            if val.startswith("piper:"):
                def ok(ready, e):
                    if ready:
                        vst.config(text="Natural voice: the first time, it downloads (~60 MB), then works offline.")
                        self.speak_test()
                    else:
                        vst.config(text="Natural voices need a free add-on. Press 'Install natural voices' first.")
                self.bg(piper_ready, ok)
            else:
                vst.config(text="")
                self.speak_test()

        def refill(names_found, e):
            if not names_found:
                return
            m = om["menu"]
            for vn in names_found:
                key = "win:" + vn
                if key in [v for _, v in choices]:
                    continue
                choices.append(("Windows: " + vn, key))
                m.add_command(label="Windows: " + vn, command=lambda n="Windows: " + vn: (voice_v.set(n), pick(n)))
        m = om["menu"]
        m.delete(0, "end")
        for n, _ in choices:
            m.add_command(label=n, command=lambda n=n: (voice_v.set(n), pick(n)))
        self.bg(windows_voices, refill)
        label(c, "Speed")
        sp = tk.Scale(c, from_=-3, to=3, orient="horizontal", showvalue=False, length=240, width=14, sliderlength=26,
                      bg=ORANGE, fg=INK, troughcolor=FIELD, highlightthickness=0, bd=1, sliderrelief="flat",
                      activebackground=ORANGE_D,
                      command=lambda v: cfg_set("tts_speed", int(float(v))))
        sp.set(int(self.cfg.get("tts_speed", 0)))
        sp.pack(anchor="w", padx=14, pady=(2, 0))
        ticks = tk.Frame(c, bg=bg, width=240, height=16)
        ticks.pack(anchor="w", padx=14)
        for txt, rx, anc in (("slower", 0.0, "w"), ("normal", 0.5, "n"), ("faster", 1.0, "e")):
            tk.Label(ticks, text=txt, bg=bg, fg=GREY, font=(FONT_UI, 8)).place(relx=rx, y=0, anchor="n" if anc == "n" else ("nw" if anc == "w" else "ne"))
        sp.bind("<ButtonRelease-1>", lambda e: (self.speaker.stop(), self.speak_test()))
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=14, pady=(6, 2))
        self.tt_btn(r, "Test voice", self.speak_test, bg=T["start"], size=9, padx=10, pady=1).pack(side="left", padx=(0, 6))

        def inst_piper():
            py = system_python()
            if not py:
                vst.config(text="I couldn't find Python on this PC.")
                return
            vst.config(text="Installing natural voices (free, offline)... a few minutes.")

            def job():
                rr = run_hidden([py, "-m", "pip", "install", "--upgrade", "piper-tts"], timeout=1800)
                if rr.returncode != 0:
                    raise RuntimeError("pip failed: " + ((rr.stderr or b"").decode("utf-8", "replace").strip().splitlines() or ["?"])[-1][:200])
            self.bg(job, lambda res, e: vst.config(text=str(e) if e else "Installed! Now pick a 'Natural' voice above."))
        self.tt_btn(r, "Install natural voices", inst_piper, bg=FIELD, size=9, padx=10, pady=1).pack(side="left")
        vst.pack(fill="x", padx=14, pady=(4, 12))

        # Spotify
        c = self.hub_card(right, "Spotify")
        c.pack(fill="x", pady=(12, 0))
        sst = tk.Label(c, text="", bg=bg, fg=ORANGE_D, font=(FONT_UI, 9, "bold"), anchor="w", justify="left", wraplength=420)
        if not self.spotify.connected():
            tk.Label(c, text=("One-time setup (uses your Premium account):\n"
                              "1. Open the Spotify dashboard, log in, Create app (any name).\n"
                              "2. Redirect URI: paste the one below. Tick 'Web API'. Save.\n"
                              "3. Copy the app's Client ID here, then press Connect."),
                     bg=bg, fg=INK, font=(FONT_UI, 9), anchor="w", justify="left").pack(fill="x", padx=14)
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=14, pady=(6, 2))
            self.tt_btn(r, "Open dashboard", lambda: webbrowser.open("https://developer.spotify.com/dashboard"),
                        bg=FIELD, size=9, padx=8, pady=1).pack(side="left", padx=(0, 6))
            self.tt_btn(r, "Copy redirect URI", lambda: (self.root.clipboard_clear(), self.root.clipboard_append(SPOTIFY_REDIRECT),
                                                          sst.config(text="Copied: " + SPOTIFY_REDIRECT)),
                        bg=FIELD, size=9, padx=8, pady=1).pack(side="left")
        label(c, "Client ID")
        cid = tk.StringVar(value=self.cfg.get("spotify_client_id", ""))
        ce = self.tt_entry(c, cid, 34)
        ce.pack(anchor="w", padx=14, pady=(2, 4))
        ce.bind("<FocusOut>", lambda ev: cfg_set("spotify_client_id", cid.get().strip()))
        r = tk.Frame(c, bg=bg)
        r.pack(fill="x", padx=14, pady=(2, 4))
        if self.spotify.connected():
            sst.config(text="Connected.")

            def disc():
                self.spotify.forget()
                sst.config(text="Disconnected.")
            self.tt_btn(r, "Disconnect", disc, bg=T["delbtn"], size=9, padx=10, pady=1).pack(side="left")
        else:
            self.tt_btn(r, "Connect", lambda: (cfg_set("spotify_client_id", cid.get().strip()), self.spotify_connect(sst)),
                        bg=ORANGE, fg=ON_ACC, size=10, padx=14, pady=2).pack(side="left")
        sa = tk.BooleanVar(value=bool(self.cfg.get("spotify_auto", False)))
        check(c, "Play music when a focus session starts (pause on breaks)", sa, lambda: cfg_set("spotify_auto", bool(sa.get())))
        label(c, "Focus playlist (name of one of yours, or a search like 'lofi beats')")
        fp = tk.StringVar(value=self.cfg.get("spotify_focus_playlist", ""))
        fe = self.tt_entry(c, fp, 30)
        fe.pack(anchor="w", padx=14, pady=(2, 4))
        fe.bind("<FocusOut>", lambda ev: cfg_set("spotify_focus_playlist", fp.get().strip()))
        sst.pack(fill="x", padx=14, pady=(2, 12))

        # Music presets
        c = self.hub_card(right, "Music presets  (say 'play focus', 'play my favourite song'...)")
        c.pack(fill="x", pady=(12, 0))
        tk.Label(c, text="Type a name to search, or paste a Spotify link (in Spotify: Share > Copy link).",
                 bg=bg, fg=GREY, font=(FONT_UI, 9), anchor="w").pack(fill="x", padx=14)
        presets = self.cfg.setdefault("music_presets", [dict(name="Preset %d" % (i + 1), kind="playlist", value="") for i in range(3)])
        while len(presets) < 3:
            presets.append(dict(name="Preset %d" % (len(presets) + 1), kind="playlist", value=""))
        pst = tk.Label(c, text="", bg=bg, fg=ORANGE_D, font=(FONT_UI, 9, "bold"), anchor="w")
        kinds = {"Playlist": "playlist", "Song": "track", "Album": "album", "Artist": "artist"}
        for i, ps in enumerate(presets[:3]):
            r = tk.Frame(c, bg=bg)
            r.pack(fill="x", padx=14, pady=3)
            nv = tk.StringVar(value=ps.get("name", ""))
            kv_ = tk.StringVar(value={v: k for k, v in kinds.items()}.get(ps.get("kind", "playlist"), "Playlist"))
            pval = tk.StringVar(value=ps.get("value", ""))

            def save_p(_e=None, i=i, nv=nv, kv_=kv_, pval=pval):
                presets[i].update(name=nv.get().strip() or "Preset %d" % (i + 1), kind=kinds.get(kv_.get(), "playlist"),
                                  value=pval.get().strip())
                cfg_set("music_presets", presets)
            ne = self.tt_entry(r, nv, 13)
            ne.pack(side="left")
            om = tk.OptionMenu(r, kv_, *kinds.keys(), command=lambda v, f=save_p: f())
            om.config(bg=FIELD, fg=INK, activebackground=T["hover"], activeforeground=INK, highlightbackground=LINE, relief="flat", highlightthickness=1, font=(FONT_UI, 9), width=7)
            om.pack(side="left", padx=4)
            ve = self.tt_entry(r, pval, 20)
            ve.pack(side="left", padx=(0, 4))
            for e_ in (ne, ve):
                e_.bind("<FocusOut>", save_p)
                e_.bind("<Return>", save_p)

            def use_now(i=i, pval=pval, kv_=kv_, f=save_p):
                n = self.music_now
                if not n or not n.get("uri"):
                    pst.config(text="Play something on Spotify first.")
                    return
                pval.set(n["uri"])
                kv_.set("Song")
                f()
                pst.config(text="Saved “%s” to this preset." % n.get("title", ""))
            self.tt_btn(r, "Play", lambda f=save_p, i=i: (f(), self.play_preset(presets[i])), bg=T["start"], size=9,
                        padx=8, pady=1).pack(side="left", padx=2)
