    # ==== Home: music card ===========================================================
    def music_icons(self):
        """Smooth (anti-aliased) round music buttons, made once per theme."""
        key = (T["card"], ORANGE, INK)
        if getattr(self, "_mus_key", None) == key:
            return self._mus_img
        card, fld, hov = T["card"], T["start"], _mixhex(T["start"], "#ffffff", 0.14)

        def btn(kind, big, hover):
            S = 48 if big else 38
            c = S / 2.0
            r = c - 2
            fill = (_mixhex(ORANGE, "#ffffff", 0.15) if hover else ORANGE) if big else (hov if hover else fld)
            ink = ON_ACC if big else INK
            sh = [("circle", c, c + 1.2, r, (_mixhex(card, "#000000", 0.5), 0.6)), ("circle", c, c, r, fill),
                  ("ring", c, c, r, 1.2, (GOLD if hover else _mixhex(fill, "#ffffff", 0.25), 0.9))]
            k = S / 38.0
            if kind == "prev":
                sh += [("poly", [(c + 5 * k, c - 6 * k), (c + 5 * k, c + 6 * k), (c - 4 * k, c)], ink),
                       ("rrect", c - 7 * k, c - 6 * k, c - 4.5 * k, c + 6 * k, 1, ink)]
            elif kind == "next":
                sh += [("poly", [(c - 5 * k, c - 6 * k), (c - 5 * k, c + 6 * k), (c + 4 * k, c)], ink),
                       ("rrect", c + 4.5 * k, c - 6 * k, c + 7 * k, c + 6 * k, 1, ink)]
            elif kind == "play":
                sh += [("poly", [(c - 3.5 * k, c - 7 * k), (c - 3.5 * k, c + 7 * k), (c + 7 * k, c)], ink)]
            else:
                sh += [("rrect", c - 5.5 * k, c - 6.5 * k, c - 1.5 * k, c + 6.5 * k, 1.2, ink),
                       ("rrect", c + 1.5 * k, c - 6.5 * k, c + 5.5 * k, c + 6.5 * k, 1.2, ink)]
            return aa_photo(S, S, sh, _hex_rgb(card))
        imgs = {}
        for kind in ("prev", "next", "play", "pause"):
            big = kind in ("play", "pause")
            imgs[kind] = (btn(kind, big, False), btn(kind, big, True))
        disc = [("circle", 32, 33, 30, (_mixhex(card, "#000000", 0.5), 0.6)), ("circle", 32, 32, 30, "#16151c")]
        for rr in (26, 22.5, 19, 15.5):
            disc.append(("ring", 32, 32, rr, 0.8, ("#ffffff", 0.07)))
        disc += [("ring", 32, 32, 29.5, 1.0, (GOLD, 0.5)), ("circle", 32, 32, 10, ORANGE),
                 ("circle", 32, 32, 6.5, (_mixhex(ORANGE, "#ffffff", 0.3), 0.6)), ("circle", 32, 32, 2.2, card),
                 ("poly", [(14, 15), (22, 9), (25, 12), (17, 18)], ("#ffffff", 0.10))]
        imgs["disc"] = aa_photo(64, 64, disc, _hex_rgb(card))
        self._mus_key, self._mus_img = key, imgs
        return imgs

    def hub_music_card(self, parent):
        c = self.hub_card(parent, "Music")
        c.pack(fill="x", pady=(12, 0))
        bg = T["card"]
        imgs = self.music_icons()
        top = tk.Frame(c, bg=bg)
        top.pack(fill="x", padx=14)
