    # ---- internet lookups (only when asked) ---------------------------------------
    def toggle_web(self):
        self.cfg["web_enabled"] = bool(self.web_var.get())
        save_config(self.cfg)
        self.say("Internet lookups are %s." % ("on" if self.cfg["web_enabled"] else "off"), 5)

    def start_web(self, kind, arg):
        if not self.cfg.get("web_enabled", True):
            return "Internet lookups are switched off. Right-click me > Internet lookups to turn them on."
        if self.web_busy:
            return "One lookup at a time, please - still fetching!"
        if kind in ("weather", "time") and not arg:
            arg = self.cfg.get("home_city") or ""
            if not arg:
                return "Which city? Try 'weather in Paris' or 'home city Paris'."
        if kind == "search":
            if not isinstance(arg, tuple):
                arg = (str(arg), str(arg), True)
            if not arg[0].strip():
                return "Search for what? Try 'search black holes'."
        self.web_busy = True
        self.set_mood("happy", 1.5)
        threading.Thread(target=self.web_worker, args=(kind, arg, self.cfg.get("temp_unit", "C")), daemon=True).start()
        if kind == "search":
            return random.choice(["Hmm hmm~ I don't know that one yet! Let me sniff around the web...",
                                  "Ne~ I don't know that yet... let me search the web, kon!"]) if not arg[2] else \
                random.choice(["Kon! Searching the web and reading the top pages~", "Fumu fumu~ let me look that up, kon!"])
        return "Looking that up..."

    def do_research(self, query, question, explicit):
        """Runs in the background: search, read, summarise (smart brain if it's on), remember for a while."""
        if not explicit:
            old = fact_recall(question)
            if old:
                return old + "\n(Ehehe~ I looked this up earlier, so I remembered it!)"
        model = None
        if self.cfg.get("llm_enabled", True):
            model = pick_model(ollama_models() or [], self.cfg.get("llm_model") or "llama3.2:3b")
        ans, src = research(query, question, model, FOX_VOICE)
        out = research_text(ans, src, random.choice(["Kon! Yatta, I found it~", "Kon kon~ here's what I found!"]) if explicit
                            else random.choice(["Kon! I didn't know that, so I sniffed around the web~",
                                                "Uwaa~ I had to look that one up! Here's what I found, kon:"]))
        if self.cfg.get("learn_habits", True):
            fact_store(question, out)
        return out

    def web_worker(self, kind, arg, unit):
        try:
            if kind == "weather":
                out = weather_text(arg, unit)
            elif kind == "time":
                out = time_text(arg)
            elif kind == "news":
                out = news_text(arg)
            elif kind == "convert":
                out = convert_text(*arg)
            else:
                out = self.do_research(*arg)
            self.web_q.put(("ok", out))
        except WebError as e:
            self.web_q.put(("err", str(e)))
        except Exception as e:
            self.web_q.put(("err", "Something went wrong with that lookup (%s)." % e))

    def poll_web(self):
        try:
            while True:
                kind, msg = self.web_q.get_nowait()
                self.web_busy = False
                if kind == "err":
                    msg = fox_voice(msg, "sad", tail=False)
                self.chat_line("Fox", msg)
                self.say(msg.split("\n")[0], 14)
                self.set_mood("happy", 2)
                beep("sad" if kind == "err" else "hello")
        except queue.Empty:
            pass
        self.root.after(250, self.poll_web)

    def open_brain(self):
        if self.brain_win and self.brain_win.winfo_exists():
            self.brain_win.lift()
            return
        w = tk.Toplevel(self.root)
        self.brain_win = w
        w.title("Zenko - smart brain")
        w.attributes("-topmost", True)
        w.configure(bg=PAPER)
        w.resizable(False, False)
        self.style_titlebar(w)
        tk.Label(w, text="\u2726  Smart brain   \u00b7   free, offline, optional", bg=T["banner"], fg=GOLD,
                 font=(FONT_UI, 13, "bold"), anchor="w", padx=14, pady=9).pack(fill="x")
        status = tk.StringVar()
        tk.Label(w, textvariable=status, bg=PAPER, fg=INK, font=(FONT_UI, 10, "bold"), justify="left",
                 anchor="w", padx=14, pady=8, wraplength=500).pack(fill="x")
        steps = ("Switch it on (one time):\n"
                 "1.  Install Ollama - a free, open-source app that runs AI models on your own PC.\n"
                 "     Download it ONLY from ollama.com (copies on other sites can be unsafe).\n"
                 "2.  Open Command Prompt and type:   ollama pull llama3.2:3b\n"
                 "     (about 2 GB, downloaded once; needs about 3 GB of free RAM)\n"
                 "     Slow, or not much RAM free? Use the smaller one instead:  ollama pull llama3.2:1b\n"
                 "3.  Leave Ollama running (it starts with Windows). Then chat with me:\n"
                 "     I'll understand typos and everyday wording, e.g. \"remind me to study renal at 5 for an hour\",\n"
                 "     and I'll write much better summaries when I search the web for you.\n\n"
                 "It all runs on this PC. I only talk to Ollama at 127.0.0.1 (this computer) -\n"
                 "the brain itself never goes online and nothing costs money.")
        tk.Label(w, text=steps, bg=PAPER, fg=INK, font=(FONT_UI, 10), justify="left", anchor="w",
                 padx=14, pady=2).pack(fill="x")

        def check():
            names = ollama_models()
            if names is None:
                status.set("Status: Ollama not detected. Without it I still understand typos and all the normal commands.")
            elif not names:
                status.set("Status: Ollama is running, but no model is installed yet (step 2).")
            else:
                status.set("Status: ready!  Installed: %s" % ", ".join(names[:4]))
        enable = tk.BooleanVar(value=bool(self.cfg.get("llm_enabled", True)))

        def toggle():
            self.cfg["llm_enabled"] = bool(enable.get())
            save_config(self.cfg)
        bar = tk.Frame(w, bg=PAPER)
        bar.pack(fill="x", padx=14, pady=(10, 12))
        self.tt_btn(bar, "Open ollama.com", lambda: webbrowser.open("https://ollama.com/download"), size=9
                    ).pack(side="left", padx=(0, 6))
        self.tt_btn(bar, "Check again", check, size=9).pack(side="left", padx=6)
        self.tt_btn(bar, "Test it", lambda: (self.open_chat(), self.ask_llm("hello, are you working?")), size=9
                    ).pack(side="left", padx=6)
        tk.Checkbutton(bar, text="Use smart brain", variable=enable, command=toggle, bg=PAPER, selectcolor=FIELD,
                       activebackground=PAPER, activeforeground=INK, font=(FONT_UI, 10), fg=INK).pack(side="left", padx=10)
        check()
        w.update_idletasks()
        w.geometry("+%d+%d" % ((w.winfo_screenwidth() - w.winfo_width()) // 2, w.winfo_screenheight() // 5))

    def run(self):
        self.root.mainloop()




