def screen_excluded(text, words):
    t = (text or "").lower()
    for w in words or ():
        w = (w or "").strip().lower()
        if w and re.search(r"(?<![a-z0-9])" + re.escape(w) + r"(?![a-z0-9])", t):
            return True
    return False


def screen_site(title):
    """A browser window title -> a short site name ('YouTube'), or '' when it can't tell."""
    t = _SCREEN_BROWSER_TAIL.sub("", (title or "").strip())
    t = re.sub(r"\s+and \d+ more pages?$", "", t, flags=re.I)
    parts = [p.strip() for p in re.split(r"\s+[-\u2013\u2014|\u00b7:]\s+", t) if p.strip()]
    if len(parts) >= 2 and _SCREEN_PROFILE.match(parts[-1]):
        parts = parts[:-1]
        t = " - ".join(parts)
    for rx, name in _SCREEN_SITES_RX:
        if rx.search(t):
            return name
    if len(parts) >= 2 and 2 <= len(parts[-1]) <= 28 and len(parts[-1].split()) <= 4:
        return parts[-1]
    return "Other websites"


def screen_classify(title, proc, own=False, exclude=(), private_hwnd=False):
    """What to count for this foreground window: (app, site or '', is_media), or None when it must not be recorded
    (private / incognito windows, anything on the exclusion list, the lock screen)."""
    title, proc = (title or "").strip(), (proc or "").lower()
    if own:
        return ("Zenko", "", False)
    if not title and not proc:
        return None
    if private_hwnd or _SCREEN_PRIVATE.search(title):
        return None
    base = proc[:-4] if proc.endswith(".exe") else proc
    if screen_excluded(title, exclude) or screen_excluded(base, exclude):
        return None
    app = SCREEN_APP_NAMES.get(proc)
    if app is None:
        app = (base.replace("_", " ").replace("-", " ").strip().title() or title[:28]) if base else title[:28]
    if not app:
        return None
    site = screen_site(title) if proc in BROWSERS else ""
    return (app, site, (site or app) in SCREEN_MEDIA)


def screen_fmt(secs):
    m = int(round(secs / 60.0))
    if m < 1:
        return "<1m" if secs > 0 else "0m"
    h, m = divmod(m, 60)
    return ("%dh %02dm" % (h, m)) if h else ("%dm" % m)


def screen_fmt_long(secs):
    m = int(round(secs / 60.0))
    h, m = divmod(m, 60)
    if h and m:
        return "%d hour%s %d min" % (h, "" if h == 1 else "s", m)
    if h:
        return "%d hour%s" % (h, "" if h == 1 else "s")
    return "%d min" % m


def screen_fg_window():
    """(hwnd, pid) of the foreground window (Windows), so private windows and Zenko's own windows are recognised."""
    if not IS_WIN:
        return 0, 0
    try:
        hwnd = user32.GetForegroundWindow()
        pid = ctypes.c_ulong()
        user32.GetWindowThreadProcessId(hwnd, ctypes.byref(pid))
        return int(hwnd or 0), int(pid.value)
    except Exception:
        return 0, 0


