_ORB_CACHE = {}
BREATH_TINT = {"in": (200, 222, 255), "hold": (226, 214, 255), "rest": (214, 210, 240), "out": (190, 236, 226),
               "top": (232, 236, 255)}


def breath_orb_photo(r, z, phase):
    """The breathing orb as pixel art (r in scene pixels, shown zoomed by z): a soft moon-glass disc, a bright rim
    and a stepped halo. Cached, because it only has ~30 sizes."""
    r = max(3, int(r))
    key = (r, z, phase)
    img = _ORB_CACHE.get(key)
    if img is not None:
        return img
    tint = BREATH_TINT.get(phase, (210, 220, 255))
    R2 = int(r * 1.5) + 2
    n = 2 * R2 + 1
    rows = []
    for y in range(n):
        row = []
        for x in range(n):
            d = math.hypot(x - R2, y - R2) / float(r)
            a = 0.0
            c = tint
            if d <= 1.0:
                if d > 1.0 - 1.6 / r:
                    a, c = 0.95, _lerp3(tint, (255, 255, 255), 0.55)
                elif d > 1.0 - 2.6 / r:
                    a = 0.45
                else:
                    a = 0.10 + 0.16 * (1 - d) ** 2
                    if d < 0.35 and _dith(x, y, (0.35 - d) * 1.2):
                        a += 0.06
            elif d < 1.5:
                q = (1 - (d - 1.0) / 0.5) ** 2 * 0.30
                a = 0.0 if not _dith(x, y, q * 2.6) else 0.22
            row.append((c[0], c[1], c[2], int(255 * min(1.0, a))))
        rows.append(row)
    im = tk.PhotoImage(data=base64.b64encode(_png(rows, 6)))
    if z > 1:
        im = im.zoom(z, z)
    if len(_ORB_CACHE) > 160:
        _ORB_CACHE.clear()
    _ORB_CACHE[key] = im
    return im


def breath_sizes(steps):
    """For each step, the orb size (0.35 small .. 1.0 full) it starts and ends at."""
    ends = []
    for k, (ph, _) in enumerate(steps):
        nxt = steps[(k + 1) % len(steps)][0]
        if ph == "in":
            ends.append(0.82 if nxt == "top" else 1.0)
        elif ph == "top":
            ends.append(1.0)
        elif ph == "out":
            ends.append(0.35)
        else:
            ends.append(None)
    for k in range(len(ends)):
        if ends[k] is None:
            ends[k] = ends[k - 1] if ends[k - 1] is not None else 0.35
    starts = [ends[k - 1] for k in range(len(ends))]
    return starts, ends


