class MicError(Exception):
    pass


class MicRecorder:
    """Records 16 kHz mono 16-bit audio from the default microphone in a thread.
    auto_stop: end by itself once you've spoken and then paused (~1.2 s), or after 8 s of silence.
    on_end: called (from the thread) when it stops by itself."""
    RATE = 16000

    def __init__(self, auto_stop=False, on_end=None, max_secs=40):
        self.auto_stop, self.on_end, self.max_secs = auto_stop, on_end, max_secs
        self.chunks = []
        self.err = None
        self.heard = False
        self._stop = threading.Event()
        self._th = None

    def start(self):
        self._th = threading.Thread(target=self._run, daemon=True)
        self._th.start()

    def stop(self):
        """Stop and return the recorded PCM bytes."""
        self._stop.set()
        if self._th and self._th is not threading.current_thread():
            self._th.join(3)
        return b"".join(self.chunks)

    def _vad(self, data, st):
        import array
        a = array.array("h")
        a.frombytes(data[:len(data) - (len(data) % 2)])
        if not a:
            return False
        rms = math.sqrt(sum(v * v for v in a[::4]) / float(len(a[::4]) or 1))
        st["n"] += 1
        if st["n"] <= 3:
            st["floor"] = (st["floor"] * (st["n"] - 1) + rms) / st["n"]
            return False
        loud = rms > max(st["floor"] * 2.6, 380)
        if loud:
            st["loud"] += 1
            st["quiet"] = 0
            if st["loud"] >= 2:
                self.heard = True
        else:
            st["quiet"] += 1
            st["floor"] = st["floor"] * 0.97 + rms * 0.03
        if not self.auto_stop:
            return False
        secs = st["n"] * 0.1
        if self.heard and st["quiet"] >= 12:
            return True
        if not self.heard and secs >= 8:
            return True
        return secs >= self.max_secs

    def _run(self):
        st = {"n": 0, "floor": 0.0, "loud": 0, "quiet": 0}
        auto = False
        try:
            if IS_WIN:
                auto = self._run_win(st)
            else:
                auto = self._run_other(st)
        except MicError as e:
            self.err = str(e)
        except Exception as e:
            self.err = "The microphone didn't work (%s)." % e
        if (auto or self.err) and self.on_end:
            try:
                self.on_end()
            except Exception:
                pass

    def _run_win(self, st):
        from ctypes import c_void_p, c_uint32, c_ushort, c_size_t, c_uint, byref, sizeof, POINTER

        class WAVEFORMATEX(ctypes.Structure):
            _fields_ = [("wFormatTag", c_ushort), ("nChannels", c_ushort), ("nSamplesPerSec", c_uint32),
                        ("nAvgBytesPerSec", c_uint32), ("nBlockAlign", c_ushort), ("wBitsPerSample", c_ushort),
                        ("cbSize", c_ushort)]

        class WAVEHDR(ctypes.Structure):
            _fields_ = [("lpData", c_void_p), ("dwBufferLength", c_uint32), ("dwBytesRecorded", c_uint32),
                        ("dwUser", c_size_t), ("dwFlags", c_uint32), ("dwLoops", c_uint32), ("lpNext", c_void_p),
                        ("reserved", c_size_t)]
        wm = ctypes.WinDLL("winmm")
        wm.waveInOpen.argtypes = [POINTER(c_void_p), c_uint, POINTER(WAVEFORMATEX), c_size_t, c_size_t, c_uint32]
        for fn in ("waveInPrepareHeader", "waveInUnprepareHeader", "waveInAddBuffer"):
            getattr(wm, fn).argtypes = [c_void_p, POINTER(WAVEHDR), c_uint]
        for fn in ("waveInStart", "waveInStop", "waveInReset", "waveInClose"):
            getattr(wm, fn).argtypes = [c_void_p]
        fmt = WAVEFORMATEX(1, 1, self.RATE, self.RATE * 2, 2, 16, 0)
        h = c_void_p()
        rc = wm.waveInOpen(byref(h), 0xFFFFFFFF, byref(fmt), 0, 0, 0)
        if rc != 0:
            raise MicError("I can't open a microphone (Windows said %d). Check one is plugged in, and that "
                           "Settings > Privacy > Microphone lets desktop apps use it." % rc)
        n_buf, size = 8, self.RATE * 2 // 10                 # eight 100 ms buffers
        bufs = [ctypes.create_string_buffer(size) for _ in range(n_buf)]
        hdrs = []
        for b in bufs:
            hd = WAVEHDR()
            hd.lpData = ctypes.cast(b, c_void_p)
            hd.dwBufferLength = size
            wm.waveInPrepareHeader(h, byref(hd), sizeof(WAVEHDR))
            wm.waveInAddBuffer(h, byref(hd), sizeof(WAVEHDR))
            hdrs.append(hd)
        auto = False
        try:
            wm.waveInStart(h)
            i = 0
            while not self._stop.is_set():
                hd = hdrs[i]
                if hd.dwFlags & 1:                            # WHDR_DONE
                    data = ctypes.string_at(bufs[i], hd.dwBytesRecorded)
                    self.chunks.append(data)
                    hd.dwBytesRecorded = 0
                    hd.dwFlags &= ~1                          # clear WHDR_DONE ourselves before handing it back
                    wm.waveInAddBuffer(h, byref(hd), sizeof(WAVEHDR))
                    i = (i + 1) % n_buf
                    if self._vad(data, st):
                        auto = True
                        break
                else:
                    time.sleep(0.01)
        finally:
            wm.waveInStop(h)
            wm.waveInReset(h)
            for hd in hdrs:
                wm.waveInUnprepareHeader(h, byref(hd), sizeof(WAVEHDR))
            wm.waveInClose(h)
        return auto

    def _run_other(self, st):
        """Off Windows (only used for testing): FOX_FAKE_MIC_WAV plays a file in as if spoken, else arecord."""
        fake = os.environ.get("FOX_FAKE_MIC_WAV")
        if fake and os.path.exists(fake):
            with open(fake, "rb") as f:
                pcm = f.read()[44:]
            step = self.RATE * 2 // 10
            for k in range(0, len(pcm), step):
                if self._stop.is_set():
                    return False
                data = pcm[k:k + step]
                self.chunks.append(data)
                time.sleep(0.02)
                if self._vad(data, st):
                    return True
            return True
        exe = shutil.which("arecord")
        if not exe:
            raise MicError("Talking out loud works on Windows.")
        p = subprocess.Popen([exe, "-q", "-f", "S16_LE", "-c1", "-r", str(self.RATE), "-t", "raw"], stdout=subprocess.PIPE)
        try:
            while not self._stop.is_set():
                data = p.stdout.read(self.RATE * 2 // 10)
                if not data:
                    break
                self.chunks.append(data)
                if self._vad(data, st):
                    return True
        finally:
            p.terminate()
        return False


def mic_peak(pcm):
    """The loudest sample in 16-bit PCM (checks every 7th sample, quick)."""
    import array
    a = array.array("h")
    a.frombytes(pcm[:len(pcm) - (len(pcm) % 2)])
    return max((abs(v) for v in a[::7]), default=0)


def pcm_to_wav(pcm, path, rate=16000):
    import struct
    with open(path, "wb") as f:
        f.write(b"RIFF" + struct.pack("<I", 36 + len(pcm)) + b"WAVEfmt " +
                struct.pack("<IHHIIHH", 16, 1, 1, rate, rate * 2, 2, 16) + b"data" + struct.pack("<I", len(pcm)) + pcm)
    return path


def stt_paths(model_key="fast", extra_dir=""):
    """(whisper-cli.exe, model .bin) when the offline speech engine is set up, else (cli or None, model or None)."""
    cli = model = None
    want = STT_MODELS.get(model_key, STT_MODELS["fast"])[0]
    models = []
    for root in [d for d in (extra_dir, STT_DIR) if d and os.path.isdir(d)]:
        base_depth = root.rstrip("\\/").count(os.sep)
        for dp, dn, fn in os.walk(root):
            if dp.count(os.sep) - base_depth > 3:
                dn[:] = []
                continue
            low = {f.lower(): f for f in fn}
            if not cli:
                for name in ("whisper-cli.exe", "whisper-cli", "main.exe"):
                    if name in low and (name != "main.exe" or "whisper.dll" in low):
                        cli = os.path.join(dp, low[name])
                        break
            for f in fn:
                if f.lower().startswith("ggml-") and f.lower().endswith(".bin"):
                    models.append(os.path.join(dp, f))
    if models:
        exact = [m for m in models if os.path.basename(m) == want]
        model = exact[0] if exact else max(models, key=lambda m: os.path.getsize(m))
    fake = os.environ.get("FOX_FAKE_WHISPER")                # testing off Windows
    if fake:
        cli, model = fake, model or fake
    return cli, model


def stt_ready(model_key="fast", extra_dir=""):
    cli, model = stt_paths(model_key, extra_dir)
    return bool(cli and model)


def _download(url, dest, sha256="", min_size=0, progress=None, label=""):
    import hashlib
    req = urllib.request.Request(url, headers={"User-Agent": "Zenko"})
    h = hashlib.sha256()
    tmp = dest + ".part"
    try:
        with urllib.request.urlopen(req, timeout=40) as r, open(tmp, "wb") as f:
            total = int(r.headers.get("Content-Length") or 0)
            got = 0
            while True:
                chunk = r.read(262144)
                if not chunk:
                    break
                f.write(chunk)
                h.update(chunk)
                got += len(chunk)
                if progress and total:
                    progress(label, got / float(total))
    except Exception as e:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise WebError("The download of %s didn't finish (%s). The network may block it: see Settings > Talk for "
                       "how to add the files by hand." % (label or os.path.basename(dest), e.__class__.__name__))
    if sha256 and h.hexdigest().lower() != sha256.lower():
        os.remove(tmp)
        raise WebError("%s didn't match its checksum, so I threw it away." % (label or "The download"))
    if os.path.getsize(tmp) < min_size:
        os.remove(tmp)
        raise WebError("%s came back too small (probably a blocked page instead of the file)." % (label or "The download"))
    os.replace(tmp, dest)
    return dest


def stt_install(model_key="fast", progress=None):
    """Download whisper.cpp (Windows build, ~5 MB) and one English model (~57 MB) into STT_DIR. Returns the paths."""
    os.makedirs(STT_DIR, exist_ok=True)
    cli, model = stt_paths(model_key)
    if not cli:
        url, sha = "https://github.com/%s/releases/latest/download/%s" % (STT_REPO, STT_ZIP_NAME), ""
        try:
            j = _github_api("https://api.github.com/repos/%s/releases/latest" % STT_REPO)
            for a in j.get("assets") or []:
                if a.get("name", "").lower() == STT_ZIP_NAME:
                    url = a.get("browser_download_url") or url
                    d = str(a.get("digest") or "")
                    sha = d.split(":", 1)[1] if d.lower().startswith("sha256:") else ""
        except Exception:
            pass
        zp = _download(url, os.path.join(STT_DIR, STT_ZIP_NAME), sha, 500000, progress, "the speech engine")
        bin_dir = os.path.join(STT_DIR, "bin")
        os.makedirs(bin_dir, exist_ok=True)
        try:
            with zipfile.ZipFile(zp) as z:
                for m in z.infolist():
                    name = m.filename.replace("\\", "/")
                    if name.endswith("/") or ".." in name.split("/") or name.startswith("/"):
                        continue
                    out = os.path.join(bin_dir, *name.split("/"))
                    os.makedirs(os.path.dirname(out), exist_ok=True)
                    with z.open(m) as src, open(out, "wb") as dst:
                        shutil.copyfileobj(src, dst)
        except zipfile.BadZipFile:
            raise WebError("The speech engine download was damaged. Try again later.")
        finally:
            try:
                os.remove(zp)
            except OSError:
                pass
    cli, model = stt_paths(model_key)
    want = STT_MODELS.get(model_key, STT_MODELS["fast"])
    if not model or os.path.basename(model) != want[0]:
        dest = os.path.join(STT_DIR, want[0])
        _download(STT_MODEL_URL % want[0], dest, "", want[1] * 1000000 // 2, progress, "the English model")
        with open(dest, "rb") as f:
            if f.read(4) != b"lmgg":
                os.remove(dest)
                raise WebError("The model file isn't a whisper model (the network may have sent a web page instead).")
    cli, model = stt_paths(model_key)
    if not cli:
        raise WebError("I couldn't find whisper-cli.exe in the speech engine download.")
    return cli, model


def stt_transcribe(wav, model_key="fast", extra_dir=""):
    cli, model = stt_paths(model_key, extra_dir)
    if not (cli and model):
        raise WebError("My offline ears aren't set up yet (Settings > Talk with Zenko).")
    threads = max(1, min(4, (os.cpu_count() or 2) - 1))
    out_base = os.path.splitext(wav)[0] + "_text"
    try:
        os.remove(out_base + ".txt")
    except OSError:
        pass
    # zenko17: newer whisper.cpp builds print nothing to the console with -np, so the words also go to a .txt file
    args = [cli, "-m", model, "-f", wav, "-l", "en", "-nt", "-np", "-t", str(threads), "--prompt", STT_PROMPT,
            "-otxt", "-of", out_base]
    if os.environ.get("FOX_FAKE_WHISPER"):
        args = [sys.executable, cli, wav]
    r = run_hidden(args, timeout=240, cwd=os.path.dirname(os.path.abspath(cli)))
    out = (r.stdout or b"").decode("utf-8", "replace")
    try:
        with open(out_base + ".txt", encoding="utf-8", errors="replace") as f:
            txt_file = f.read()
        if txt_file.strip():
            out = txt_file
    except OSError:
        pass
    text = " ".join(ln.strip() for ln in out.splitlines() if ln.strip() and not ln.startswith(("whisper_", "main:", "system_info")))
    text = re.sub(r"\[[^\]]*\]|\((?:music|noise|silence|inaudible|blank_audio|laughs?|applause)[^)]*\)", " ", text, flags=re.I)
    text = re.sub(r"\s+", " ", text).strip()
    if r.returncode != 0 and not text:
        err = (r.stderr or b"").decode("utf-8", "replace").strip().splitlines()[-1:] or ["unknown error"]
        raise WebError("The speech engine stopped with an error: %s" % err[0][:160])
    return text


class LocalVoice(VoiceEngine):
    """VoiceEngine plus the built-in offline engine (kind 'local'): winmm microphone + whisper.cpp.
    Used first whenever it is set up; otherwise everything works exactly as before."""

    def __init__(self):
        super().__init__()
        self._on = False
        self.rec = None
        self.auto_stop = False
        self.busy = False
        self.model_key = "fast"
        self.extra_dir = ""

    def alive(self):
        if self.kind == "local":
            return self._on
        return super().alive()

    def start(self, prefer="auto", model="base.en"):
        if self.alive():
            return True
        if prefer in ("auto", "local") and stt_ready(self.model_key, self.extra_dir):
            self.kind, self._on, self.ready = "local", True, True
            self.q.put(("status", "ready"))
            return True
        if prefer == "local":
            self.q.put(("error", "My offline ears aren't set up yet. Settings > Talk with Zenko > Set up (one time)."))
            return False
        return super().start(prefer, model)

    def press(self):
        if self.kind != "local":
            return super().press()
        if not self._on or self.listening or self.busy:
            return False
        self.listening = True
        self.rec = MicRecorder(auto_stop=self.auto_stop, on_end=self._auto_end)
        self.auto_stop = False                               # one-shot: push-to-talk keys never auto-stop
        self.rec.start()
        self.q.put(("status", "listening"))
        return True

    def _auto_end(self):
        self._finish(self.rec)

    def release(self):
        if self.kind != "local":
            return super().release()
        if self.listening and self.rec:
            self._finish(self.rec)

    def _finish(self, rec):
        if rec is None or rec is not self.rec or getattr(rec, "_done", False):
            return
        rec._done = True
        self.rec = None
        pcm = rec.stop()
        self.listening = False
        if rec.err:
            self.q.put(("error", rec.err))
            return
        if len(pcm) >= 16000 and mic_peak(pcm) < 24:
            self.q.put(("error", "I only heard total silence. Is the microphone muted? Check Windows Settings > Privacy & "
                                 "security > Microphone > 'Let desktop apps access your microphone', and the input device "
                                 "in Settings > System > Sound."))
            return
        if len(pcm) < 16000 * 2 * 0.4 or (rec.auto_stop and not rec.heard):
            self.q.put(("text", ""))
            return
        self.busy = True
        self.q.put(("status", "transcribing"))

        def work():
            try:
                wav = pcm_to_wav(pcm, os.path.join(_ext_dir("speech_tmp"), "said.wav"))
                t = stt_transcribe(wav, self.model_key, self.extra_dir)
                self.q.put(("text", t))
            except Exception as e:
                self.q.put(("error", str(e)))
            finally:
                self.busy = False
        threading.Thread(target=work, daemon=True).start()

    def cancel(self):
        if self.kind != "local":
            return super().cancel()
        rec, self.rec = self.rec, None
        if rec:
            rec._done = True
            rec.stop()
        if self.listening:
            self.listening = False
            self.q.put(("status", "cancelled"))

    def stop(self):
        if self.kind == "local":
            self.cancel()
            self._on = False
            self.kind = None
            return
        super().stop()
        self.kind = None


# ---- her reply, spoken with VOICEVOX (anime voice) -------------------------------------------------------------
_VV_SAY = {"gen": 0}


def vv_say_text(text):
    """Make a reply speakable: no Markdown/LaTeX/emoji, short sentences, at most ~260 characters."""
    t = md_plain(text or "")
    t = re.sub(r"\$[^$]*\$|\\\(.*?\\\)|https?://\S+", " ", t)
    t = re.sub(r"[~*_`#>|\[\]{}]", " ", t)
    t = "".join(ch for ch in t if ord(ch) < 0x2600 or 0x3000 <= ord(ch) <= 0x9fff)
    t = re.sub(r"\s+", " ", t).strip()
    parts = re.split(r"(?<=[.!?。！？])\s+", t)
    out, n = [], 0
    for p in parts:
        if not p:
            continue
        if n + len(p) > 260 and out:
            break
        out.append(p)
        n += len(p)
    return out


VV_CACHE_MAX = 500


def _vv_cached_wav(p, speaker):
    """VOICEVOX audio for one sentence, from the disk cache when she has said it before (no wait at all)."""
    import hashlib
    d = _ext_dir("speech_cache")
    key = hashlib.sha1(("%s|%s|v1" % (speaker, p)).encode("utf-8")).hexdigest()[:20]
    path = os.path.join(d, key + ".wav")
    try:
        if os.path.getsize(path) > 1000:
            try:
                os.utime(path, None)
            except OSError:
                pass
            return path
    except OSError:
        pass
    data = voicevox_wav(p, speaker, pitch=0.04, speed=1.05)
    with open(path + ".part", "wb") as f:
        f.write(data)
    os.replace(path + ".part", path)
    try:
        names = [os.path.join(d, n) for n in os.listdir(d) if n.endswith(".wav")]
        if len(names) > VV_CACHE_MAX:
            names.sort(key=lambda n: os.path.getmtime(n))
            for n in names[:len(names) - VV_CACHE_MAX + 50]:
                os.remove(n)
    except OSError:
        pass
    return path


def vv_speak(text, speaker, done=None):
    """Speak with VOICEVOX in a thread. Every sentence is made (or taken from the cache) FIRST; then done(seconds)
    is called and the whole line plays in one go, so the bubble and her voice start together. done(-1) means
    VOICEVOX isn't running. Returns False when there is nothing to say."""
    if not IS_WIN:
        return False
    _VV_SAY["gen"] += 1
    gen = _VV_SAY["gen"]
    parts = vv_say_text(text)
    if not parts:
        return False

    def run():
        import winsound
        import wave
        paths = []
        for p in parts:
            if _VV_SAY["gen"] != gen:
                return
            try:
                paths.append(_vv_cached_wav(p, speaker))
            except Exception:
                if not paths:
                    if done:
                        done(-1)
                    return
                break
        if _VV_SAY["gen"] != gen:
            return
        play, secs = paths[0], 0.0
        try:
            if len(paths) > 1:
                play = os.path.join(_ext_dir("speech_tmp"), "reply%d.wav" % (gen % 2))
                with wave.open(play, "wb") as out:
                    for k, pth in enumerate(paths):
                        with wave.open(pth, "rb") as w:
                            if k == 0:
                                out.setparams(w.getparams())
                            out.writeframes(w.readframes(w.getnframes()))
            with wave.open(play, "rb") as w:
                secs = w.getnframes() / float(w.getframerate() or 24000)
        except Exception:
            play, secs = paths[0], len(parts[0]) / 12.0
        if done:
            done(secs)
        if _VV_SAY["gen"] != gen or JPV.get("muted"):
            return
        winsound.PlaySound(play, winsound.SND_FILENAME | winsound.SND_NODEFAULT)   # blocking, in this thread
    threading.Thread(target=run, daemon=True).start()
    return True


def vv_hush():
    _VV_SAY["gen"] += 1
    if IS_WIN:
        try:
            import winsound
            winsound.PlaySound(None, 0)
        except Exception:
            pass


