    # =================================================================================================
    #  exam countdown on her ema plaque
    # =================================================================================================
    def exam_date(self):
        try:
            return datetime.date.fromisoformat(str(self.cfg.get("exam_date") or EXAM_DATE_DEFAULT))
        except ValueError:
            return datetime.date.fromisoformat(EXAM_DATE_DEFAULT)

    def exam_days(self):
        return (self.exam_date() - datetime.date.today()).days

    def belly_text(self):
        """Every minute or so, between the clock, the plaque scrolls 'D-152 TO EXAMS'."""
        if self.session or self.brk or not self.cfg.get("ema_countdown", True) or self.belly_music():
            self._ema_t0 = 0.0
            return super().belly_text()
        d = self.exam_days()
        if d < 0 or d > 400:
            return super().belly_text()
        txt = "TODAY: EXAMS! GANBATTE" if d == 0 else "D-%d TO EXAMS" % d
        now = time.monotonic()
        dur = (len(txt) * 4 + 8) * 0.11 + 0.3
        if self._ema_t0 and now - self._ema_t0 < dur:
            self._belly_t0 = self._ema_t0
            return txt
        if now - (self._ema_t0 or 0) > 55 + dur and int(time.time()) % 60 < 2:
            self._ema_t0 = now
            self._belly_t0 = now
            return txt
        return super().belly_text()

    # =================================================================================================
    #  flashcards from Study book chats, and pop quizzes when you're idle
    # =================================================================================================
    def nb_ask(self, sid, q, mode="explain", to_chat=False, done=None):
        def wrapped(txt):
            if done:
                done(txt)
            try:
                if self.cfg.get("auto_cards", True) and mode in ("explain", "eli12", "exam") and txt and \
                        not txt.startswith("Uu~"):
                    self.auto_cards(sid, q, txt)
            except Exception:
                pass
        return super().nb_ask(sid, q, mode, to_chat, wrapped)

    def auto_cards(self, sid, q, txt):
        """Two or three flashcards from a tutor answer, saved quietly to the spaced-repetition deck."""
        body = txt.split("\n\nSources:")[0]
        body = md_plain(body) if "md_plain" in globals() else body
        cards = self.cards_from_text(body, None, sid)
        good = [c for c in cards if 3 <= len(c["a"]) <= 160 and "___" not in c["a"]][:3]
        if not good and len(body) > 80:
            first = re.split(r"(?<=[.!?])\s+", body.strip())[0]
            if 20 <= len(first) <= 220:
                good = [{"q": clip(q.strip().rstrip("?") + "?", 200), "a": first}]
        if not good:
            return
        today = datetime.date.today().isoformat()
        have = set((c["q"], c["a"]) for c in self.life["cards"])
        n = 0
        for c in good:
            if (c["q"], c["a"]) in have:
                continue
            self.life["cards"].append({"id": "%x" % random.getrandbits(36), "q": c["q"][:240], "a": c["a"][:240], "box": 0,
                                       "wrong": 0, "right": 0, "added": today,
                                       "due": (datetime.date.today() + datetime.timedelta(days=1)).isoformat(),
                                       "subject": sid or "", "from": "Study book chat"})
            n += 1
        if n:
            self.life_save()
            self.daily_refresh()
            self.say("I saved %d flashcard%s from that answer. I'll quiz you tomorrow~" % (n, "" if n == 1 else "s"), 5)

    def idle_quiz_check(self):
        if not self.cfg.get("idle_quiz", True) or self.session or self.brk or self.lockin or self.quiz:
            return
        if idle_seconds() > 90 or self.bubble_job is not None or self.sleeping:
            return
        gap = float(self.cfg.get("idle_quiz_gap", 35)) * 60
        if time.monotonic() - self._quiz_offer_t < gap:
            return
        now = datetime.datetime.now()
        if now.hour < 7 or now.hour >= 22:
            return
        day = now.date().isoformat()
        cnt = self.life.setdefault("quiz_offers", {})
        if cnt.get(day, 0) >= 6:
            return
        due = sorted(self.cards_due(), key=lambda c: (c.get("box", 0), -c.get("wrong", 0)))
        if not due:
            return
        self._quiz_offer_t = time.monotonic()
        cnt.clear()
        cnt[day] = self.life.get("quiz_offers", {}).get(day, 0) + 1
        self.life["quiz_offers"] = {day: cnt[day]}
        self.life_save()
        card = random.choice(due[:4])

        def reveal():
            self.say("Answer: %s\nDid you remember it?" % clip(card["a"], 120), 30,
                     [("I knew it!", lambda: (self.srs_update(card, True, True), self.say("Sugoi~ that one's sticking!", 4))),
                      ("Forgot", lambda: (self.srs_update(card, False, True), self.say("I'll bring it back soon, ne~", 4)))])

        def later():
            self._quiz_offer_t = time.monotonic() + 60 * 60
        tag = (" (%s)" % self.sname(card["subject"], False)) if card.get("subject") else ""
        self.say("Pop quiz~%s\n%s" % (tag, clip(card["q"], 110)), 40,
                 [("Show answer", reveal), ("Later", later)])

    # =================================================================================================
    #  IA / EE / TOK tracker (on the Upcoming page)
    # =================================================================================================
    def ib_tasks(self):
        return self.life.setdefault("ibtasks", [])

    def ib_add(self, kind, subject="", title="", due="", target=None, unit=None):
        k = dict((x[0], x) for x in IB_TASK_KINDS).get(kind, IB_TASK_KINDS[-1])
        if kind == "ia" and subject in IB_IA_DEFAULTS:
            u, tg = IB_IA_DEFAULTS[subject]
        else:
            u, tg = k[2], k[3]
        t = {"id": "%x" % random.getrandbits(32), "kind": kind, "subject": subject, "unit": unit or u,
             "target": int(target if target is not None else tg), "words": 0, "title": title or (
                 ("%s IA" % self.sname(subject, False)) if kind == "ia" and subject else k[1]),
             "due": due, "stages": [], "updated": datetime.date.today().isoformat(), "hist": []}
        self.ib_tasks().append(t)
        self.life_save()
        return t

    def ib_find(self, text):
        low = text.lower()
        best = None
        for t in self.ib_tasks():
            words = [t["kind"].replace("_", " "), t["title"].lower()]
            if t["kind"] == "ee" and re.search(r"\b(?:ee|extended essay)\b", low):
                return t
            if t["kind"] == "tok_essay" and re.search(r"\btok\b(?! exhibition)", low):
                best = best or t
            if t["kind"] == "tok_exh" and re.search(r"\btok exhibition\b|\bexhibition\b", low):
                return t
            if t["kind"] == "ia" and re.search(r"\bia\b|internal assessment|exploration", low):
                sid = self.subject_in(text) if hasattr(self, "subject_in") else None
                if sid and sid == t.get("subject"):
                    return t
                if not sid:
                    best = best or t
            if t["title"].lower() in low:
                return t
        return best

    def ib_set_words(self, t, n):
        n = max(0, int(n))
        old = t.get("words", 0)
        t["words"] = n
        t["updated"] = datetime.date.today().isoformat()
        t.setdefault("hist", []).append([t["updated"], n])
        del t["hist"][:-30]
        self.life_save()
        self.ib_refresh()
        tg = t.get("target") or 0
        if t.get("unit") == "pages":
            return "%s: %d page%s logged~" % (t["title"], n, "" if n == 1 else "s")
        msg = "%s: %s words%s." % (t["title"], fmt_num(n), (" of %s" % fmt_num(tg)) if tg else "")
        if tg and n > tg:
            msg += " That's over the limit by %s: the examiner stops reading at %s, so trim it~" % (fmt_num(n - tg), fmt_num(tg))
        elif n > old:
            msg += " +%s since last time. Yatta~" % fmt_num(n - old)
        return msg

    def ib_count_file(self, t):
        from tkinter import filedialog
        p = filedialog.askopenfilename(title="Pick your %s draft" % t["title"],
                                       filetypes=[("Drafts", "*.docx *.txt *.md *.pdf *.rtf *.odt"), ("All files", "*.*")])
        if not p:
            return

        def job():
            txt, _ = read_any_file(p)
            return ib_count_words(txt)

        def fin(n, err):
            if err or n is None:
                self.say("Uu~ I couldn't read that file. Try saving it as .docx or .txt~", 6)
                return
            t["file"] = p
            self.say(self.ib_set_words(t, n) + " (counted from your file, including headings and references: "
                     "check what your guide counts)", 10)
        self.bg(job, fin)

    def ib_nudge_check(self):
        if not self.cfg.get("ib_nudges", True) or self.session or self.lockin:
            return
        now = datetime.datetime.now()
        if now.hour < 15 or now.hour >= 21 or idle_seconds() > 120:
            return
        today = now.date()
        for t in self.ib_tasks():
            if not t.get("due") or "Final" in t.get("stages", []):
                continue
            try:
                due = datetime.date.fromisoformat(t["due"])
            except ValueError:
                continue
            days = (due - today).days
            if days < 0 or days > 30:
                continue
            try:
                quiet = (today - datetime.date.fromisoformat(t.get("updated") or today.isoformat())).days
            except ValueError:
                quiet = 0
            if days <= 3 or (days <= 14 and quiet >= 4) or (quiet >= 7):
                if self.said_today("ibnudge_" + t["id"]):
                    continue
                left = (t.get("target") or 0) - t.get("words", 0)
                nxt = next((s for s in IB_STAGES if s not in t.get("stages", [])), "Final")
                if days <= 3:
                    line = "Kon! Your %s is due in %d day%s. Next step: %s. Want a lock-in for it?" % (
                        t["title"], days, "" if days == 1 else "s", nxt.lower())
                else:
                    line = "Your %s hasn't moved in %d days (due %s). Even 20 minutes on the %s helps~" % (
                        t["title"], quiet, due.strftime("%d %b"), nxt.lower())
                if left > 0 and t.get("unit") == "words" and t.get("words"):
                    line += " (%s words to go)" % fmt_num(left)
                self.say(line, 14, [("Lock in 30 min", lambda: self.lockin_start(30)), ("Later", lambda: None)])
                return

    def dl_render(self):
        super().dl_render()
        body = getattr(self, "dl_body", None)
        if body is None or not body.winfo_exists():
            return
        try:
            self.ib_card(body)
        except Exception as e:
            tk.Label(body, text="(The IA/EE/TOK tracker couldn't be drawn: %s)" % e, bg=PAPER, fg=GREY).pack()

    def ib_refresh(self):
        ui = self.ib_ui
        if ui and ui.winfo_exists():
            try:
                self.dl_render()
            except tk.TclError:
                pass

