        self.ib_ui = c
        d = self.exam_days()
        top = tk.Frame(c, bg=bg)
        top.pack(fill="x", padx=16, pady=(0, 6))
        tk.Label(top, text=("%d days until your first exam (%s). It scrolls on her ema plaque too." % (
            d, self.exam_date().strftime("%d %b %Y"))) if d >= 0 else "Exams are done. Otsukaresama~",
            bg=bg, fg=GREY, font=(serif, 10, "italic"), anchor="w", justify="left").pack(side="left", fill="x")
        add = tk.Frame(c, bg=bg)
        add.pack(fill="x", padx=16, pady=(2, 8))
        tk.Label(add, text="Add:", bg=bg, fg=INK, font=(FONT_UI, 10)).pack(side="left", padx=(0, 6))
        subj = [s[0] for s in SUBJECT_DEFS]
