    # =================================================================================================
    #  the Focus garden (its own tab)
    # =================================================================================================
    def garden(self):
        return self.life["garden"]

    def garden_stage(self, xp=None):
        xp = self.garden()["xp"] if xp is None else xp
        i = 0
        for k, st in enumerate(GARDEN_STAGES):
            if xp >= st[0]:
                i = k
        nxt = GARDEN_STAGES[i + 1][0] if i + 1 < len(GARDEN_STAGES) else None
        lo = GARDEN_STAGES[i][0]
        g = min(1.0, (xp - lo) / float(nxt - lo)) if nxt else min(1.0, (xp - lo) / 600.0)
        return i, g, nxt

    def garden_health(self):
        """1.0 = thriving. One day off is a free rest day; after that each skipped day costs a quarter."""
        G = self.garden()
        act = G.get("active") or []
        if not act:
            return float(G.get("health", 1.0))
        try:
            last = datetime.date.fromisoformat(act[-1])
        except ValueError:
            return float(G.get("health", 1.0))
        missed = (datetime.date.today() - last).days - 1
        eff = max(0, missed - 1)
        return max(0.0, min(1.0, float(G.get("health", 1.0)) - 0.25 * eff))

    def _garden_add_core(self, minutes, kind):
        if minutes < 3:
            return
        G = self.garden()
        before = self.garden_stage()[0]
        h = self.garden_health()
        G["xp"] = round(float(G.get("xp", 0)) + minutes, 1)
        G["health"] = min(1.0, h + (0.5 if kind == "lockin" else 0.35))
        today = datetime.date.today().isoformat()
        if not G["active"] or G["active"][-1] != today:
            G["active"].append(today)
            del G["active"][:-120]
        G["log"].append({"d": today, "t": datetime.datetime.now().strftime("%H:%M"), "m": int(round(minutes)), "k": kind})
        del G["log"][:-60]
        self.life_save()
        after = self.garden_stage()[0]
        if after > before:
            st = GARDEN_STAGES[after]
            self.root.after(9000, lambda: self.say("Kon! Your garden tree grew: %s (%s) %s~ Come see it in the Garden tab!"
                                                   % (st[1], st[3], "*sparkle*"), 10,
                                                   [("Show me", lambda: self.open_hub("garden"))]))
        self.garden_refresh()

    def garden_check(self):
        """Once a day: if the tree is thirsty, she mentions it (gently)."""
        h = self.garden_health()
        if h < 0.76 and not self.session and idle_seconds() < 120 and 10 <= datetime.datetime.now().hour < 21:
            if not self.said_today("garden_thirsty"):
                self.say("Your garden tree is %s... One lock-in today will perk it right up~" %
                         ("drooping a little" if h >= 0.5 else "wilting" if h > 0 else "very wilted"), 10,
                         [("Lock in 30 min", lambda: self.lockin_start(30)), ("Show me", lambda: self.open_hub("garden"))])

    def garden_plant_new(self):
        G = self.garden()
        i, g, nxt = self.garden_stage()
        if i < len(GARDEN_STAGES) - 1:
            return
        G["grove"].append({"planted": G.get("planted"), "done": datetime.date.today().isoformat(), "xp": G["xp"]})
        G["xp"] = 0.0
        G["seed"] = random.randrange(1, 9999)
        G["planted"] = datetime.date.today().isoformat()
        self.life_save()
        self.say("Your sacred tree joins the grove on the hills~ and a new seed goes in the ground. Kon!", 8)
        self.garden_refresh(rebuild=True)

    def lockin_stop(self, done=False, quiet=False):
        L = self.lockin
        r = super().lockin_stop(done, quiet)
        if L:
            mins_ = (time.time() - float(L.get("t0", time.time()))) / 60.0
            if done or mins_ >= 5:
                try:
                    self.garden_add(mins_ if done else mins_ * 0.8, "lockin")
                except Exception:
                    pass
        return r

    def end_session(self, completed):
        s = self.session
        r = super().end_session(completed)
        if s and not self.lockin and s.get("task") != "Lock-in":
            focused = max(0.0, s["elapsed"] - s["dist"] - s["away"]) / 60.0
            if completed or focused >= 10:
                try:
                    self.garden_add(focused * 0.6, "focus")
                except Exception:
                    pass
        return r

    def hub_build_garden(self, pg):
        self.hub_title(pg, "Zen garden", "禅 · Breathe here before an exam or before sleep. Your focus sessions grow "
                                         "the tree.")
        body = tk.Frame(pg, bg=PAPER)
        body.pack(fill="both", expand=True, padx=20, pady=(12, 14))
        body.grid_rowconfigure(0, weight=1)
        body.grid_columnconfigure(0, weight=1)
        frame = tk.Frame(body, bg=_mixhex(LINE, "#000000", 0.2), padx=1, pady=1)    # a thin, quiet mat around the scene
        frame.grid(row=0, column=0, sticky="nsew")
        cv = tk.Canvas(frame, bg="#0a0922", highlightthickness=0, width=420, height=300)
        cv.pack(fill="both", expand=True)
        side = tk.Frame(body, bg=PAPER, width=300)
        side.grid(row=0, column=1, sticky="ns", padx=(14, 0))
        side.pack_propagate(False)
        sc = self.hub_scroller(side)
        self.garden_ui = {"cv": cv, "side": side, "panel": sc, "body": body, "key": None, "img": None, "anim": 0,
                          "petals": [], "flies": [], "koi": [], "sprite": None, "zk": None, "lay": None}
        cv.bind("<Configure>", lambda e: self.garden_draw_later())
        self.garden_panel()

    def garden_refresh(self, rebuild=False):
        ui = self.garden_ui
        if not ui or not ui["cv"].winfo_exists():
            return
        if rebuild:
            ui["key"] = None
        self.garden_draw_later()
        self.garden_panel()

    def garden_draw_later(self):
        ui = self.garden_ui
        if not ui:
            return
        if ui.get("job"):
            try:
                self.root.after_cancel(ui["job"])
            except Exception:
                pass
        ui["job"] = self.root.after(120, self.garden_draw)

    def garden_draw(self):
        ui = self.garden_ui
        if not ui or not ui["cv"].winfo_exists():
            return
        ui["job"] = None
        cv = ui["cv"]
        W, H = cv.winfo_width(), cv.winfo_height()
        if W < 80 or H < 80:
            return
        # side panel width follows the window
        try:
            sw = int(260 + 60 * max(0.0, min(1.0, (self.zk_f - 0.85) / 0.6)))
            if abs(int(ui["side"].cget("width")) - sw) > 4:
                ui["side"].configure(width=sw)
        except tk.TclError:
            pass
        z = max(2, int(round(max(W / 420.0, H / 250.0))))
        rw, rh = int(math.ceil(W / float(z))), int(math.ceil(H / float(z)))
        G = self.garden()
        i, g, nxt = self.garden_stage()
        hp = self.garden_health()
        key = (rw, rh, z, i, round(g, 1), round(hp, 2), len(G["grove"]), G["seed"], T.get("night"))
        if key != ui["key"]:
            R, lay = garden_scene(rw, rh, i, g, hp, grove=len(G["grove"]), seed=G["seed"])
            try:
                ui["zk"] = self.garden_zenko(R, lay, z, W, H, i, hp)   # shadow goes into the painting itself
            except Exception:
                ui["zk"] = None
            ui["img"] = R.photo(z)
            ui["R"] = R
            ui["lay"], ui["z"], ui["key"] = lay, z, key
            cv.delete("all")
            cv.create_image(0, 0, image=ui["img"], anchor="nw", tags="scene")
            self.garden_overlay_setup()
        if not ui.get("anim_on"):
            ui["anim_on"] = True
            self.garden_anim()

    def garden_overlay_setup(self):
        """The living bits on top of the painting: foxfire, fireflies, falling petals, koi, lantern glow, Zenko."""
        ui = self.garden_ui
        cv, lay, z = ui["cv"], ui["lay"], ui["z"]
        W, H = cv.winfo_width(), cv.winfo_height()
        rnd = random.Random(3)
        i, g, nxt = self.garden_stage()
        hp = self.garden_health()
        if "glow" not in ui:
            ui["glow"] = aa_photo(40, 40, [("circle", 20, 20, 19, ("#ffcf7a", 0.10)), ("circle", 20, 20, 12, ("#ffcf7a", 0.16)),
                                           ("circle", 20, 20, 6, ("#ffe7b0", 0.5)), ("circle", 20, 20, 2.5, "#fff6dc")])
            ui["fox"] = aa_photo(36, 36, [("circle", 18, 18, 17, ("#7fd8ff", 0.10)), ("circle", 18, 18, 10, ("#9fe4ff", 0.2)),
                                          ("circle", 18, 18, 5, ("#d6f6ff", 0.6)), ("circle", 18, 18, 2, "#ffffff")])
            ui["lglow"] = aa_photo(90, 90, [("circle", 45, 45, 44, ("#ffb35a", 0.06)), ("circle", 45, 45, 30, ("#ffb35a", 0.08)),
                                            ("circle", 45, 45, 16, ("#ffcf8a", 0.12))])
        ui["lamps"] = []
        for (lx, ly) in lay["lanterns"]:
            ui["lamps"].append(cv.create_image(lx * z, ly * z, image=ui["lglow"], tags="fx"))
        ui["flies"] = []
        for k in range(9):
            x, y = rnd.uniform(0.05, 0.95) * W, rnd.uniform(lay["horizon"] * z * 0.9, H * 0.95)
            img = ui["fox"] if k < 3 else ui["glow"]
            ui["flies"].append([cv.create_image(x, y, image=img, tags="fx"), x, y, rnd.uniform(0, 6.28), rnd.uniform(0.4, 1.0)])
        ui["koi"] = []
        pcx, pcy, prx, pry = lay["pond"]
        for k, col in enumerate(("#ff7a3d", "#fff2e6", "#ffb347")):
            ui["koi"].append([cv.create_polygon(0, 0, 0, 0, 0, 0, fill=col, outline="", tags="fx"),
                              cv.create_oval(0, 0, 0, 0, fill=_mixhex(col, "#c8372d", 0.5) if k == 1 else col, outline="", tags="fx"),
                              rnd.uniform(0, 6.28), rnd.uniform(0.25, 0.45) * (1 if k % 2 else -1), 0.45 + 0.15 * k])
        ui["petals"] = []
        blossom = i >= 6 or (i == 5 and g > 0.4)
        ui["petal_rate"] = (0.6 + 1.6 * hp) if blossom else (0.5 if hp < 0.6 and i >= 2 else 0.0)
        ui["petal_col"] = ["#ffd1e1", "#ffb3cd", "#ffe4ee"] if blossom and hp >= 0.4 else ["#c4955a", "#a8794a", "#d8b07a"]
        # Zenko sitting by the tree, lit by the lanterns, with grass in front of her paws
        zk = ui.get("zk")
        ui["sprite"] = None
        if zk:
            ui["sprite"] = zk["photo"]
            ui["zk_item"] = cv.create_image(zk["x"], zk["y"], image=zk["photo"], anchor="nw", tags="fx")
            if zk.get("front"):
                cv.create_image(zk["fx"], zk["fy"], image=zk["front"], anchor="nw", tags="fx")
        ui["mists"] = []
        self.breath_items()
        cv.tag_raise("fx")

    def garden_zenko(self, R, lay, z, W, H, stage, hp):
        """Paint Zenko's depth cues into the garden: she is lit by the scene (cool moonlight, warm lantern rim,
        darker toward the ground), casts a soft contact shadow onto the moss, sits a little in front of the tree,
        and has a few grass blades in front of her paws. Returns where to put her sprite and the grass overlay."""
        pose = "sleep" if hp < 0.35 else ("happy" if hp >= 0.95 and stage >= 6 else "idle")
        rows = build_frame(pose, 0, 0, (0, 0, 0, 0), (), 0, 0)
        layers = [build_tails(self.tail_count(), 0, shadow=False), rows]
        sh, sw = len(rows), len(rows[0])
        px = [[None] * sw for _ in range(sh)]
        for L in layers:
            for y, row in enumerate(L):
                line = px[y]
                for x, ch in enumerate(row):
                    if ch != ".":
                        col = self.pal.get(ch)
                        if col:
                            line[x] = _hex_rgb(col)
        ys = [y for y in range(sh) if any(px[y])]
        xs = [x for x in range(sw) if any(px[y][x] for y in range(sh))]
        if not ys or not xs:
            return None
        y0, y1, x0, x1 = ys[0], ys[-1], xs[0], xs[-1]
        fh = y1 - y0 + 1
        # where she sits in the scene (scene pixels): a little left of the trunk and just in front of it
        rw, rh = R.w, R.h
        tx, tb = lay["tree"]
        feet_x, feet_y = rw * 0.355, tb + rh * 0.045
        # size from depth: the nearer the bottom of the picture, the bigger (about a quarter of the view)
        depth = (feet_y - lay["horizon"]) / max(1.0, rh - lay["horizon"])
        target = rh * z * (0.17 + 0.10 * depth)
        zs = max(1, int(round(target / fh)))
        # light: the nearest lantern warms one side, moonlight cools the top of her head
        lamps = lay.get("lanterns") or [(rw * 0.16, rh * 0.7)]
        lx, ly = min(lamps, key=lambda p: abs(p[0] - feet_x))
        warm_left = lx < feet_x
        dist = abs(lx - feet_x) / max(1.0, rw)
        warm_a = max(0.18, 0.55 - dist * 1.2)
        amb = (0.86, 0.84, 0.99)
        warm, cool = (255, 186, 112), (205, 216, 255)

        def solid(x, y):
            return 0 <= x < sw and 0 <= y < sh and px[y][x] is not None
        out = []
        for y in range(sh):
            line = []
            t = (y - y0) / float(max(1, fh - 1))
            ao = 1.0 - 0.30 * max(0.0, (t - 0.62) / 0.38)            # darker where she meets the ground
            for x in range(sw):
                c = px[y][x]
                if c is None:
                    line.append((0, 0, 0, 0))
                    continue
                r, g, b = c[0] * amb[0] * ao, c[1] * amb[1] * ao, c[2] * amb[2] * ao
                lum = 0.3 * c[0] + 0.59 * c[1] + 0.11 * c[2]
                if lum > 60:
                    side = -1 if warm_left else 1
                    if not solid(x + side, y) or not solid(x + 2 * side, y):
                        a = warm_a if not solid(x + side, y) else warm_a * 0.5
                        r, g, b = r + (warm[0] - r) * a, g + (warm[1] - g) * a, b + (warm[2] - b) * a
                    elif not solid(x, y - 1) or not solid(x - side, y):
                        a = 0.28
                        r, g, b = r + (cool[0] - r) * a, g + (cool[1] - g) * a, b + (cool[2] - b) * a
                line.append((min(255, int(r)), min(255, int(g)), min(255, int(b)), 255))
            out.append(line)
        img = tk.PhotoImage(data=base64.b64encode(_png(out, 1)))
        photo = img.zoom(zs, zs) if zs > 1 else img
        # screen position: paws on the chosen ground spot
        cxs = (x0 + x1) / 2.0
        sx = int(feet_x * z - cxs * zs)
        sy = int(feet_y * z - (y1 + 1) * zs)
        # contact shadow on the moss (into the painting), stretched away from the lantern
        fw = (x1 - x0 + 1) * zs / float(z)
        scx, scy = feet_x, feet_y - 0.5
        push = (fw * 0.18) * (1 if warm_left else -1)
        for yy in range(int(scy - fw * 0.18) - 1, int(scy + fw * 0.18) + 2):
            for xx in range(int(scx - fw * 0.75 + min(0, push)) - 1, int(scx + fw * 0.75 + max(0, push)) + 2):
                dx = (xx + 0.5 - (scx + push * 0.5)) / (fw * 0.62 + abs(push) * 0.5)
                dy = (yy + 0.5 - scy) / (fw * 0.15)
                d = dx * dx + dy * dy
                if d < 1.0 and 0 <= xx < rw and 0 <= yy < rh:
                    a = (1.0 - d) ** 0.7 * 0.78
                    if d < 0.3:
                        a = max(a, 0.7)
                    if a < 0.25 and _BAYER[yy % 4][xx % 4] / 16.0 > a * 3:
                        continue
                    R.put(xx, yy, (6, 8, 22), a)
        # grass blades in front of her paws (drawn over the sprite) so she sits IN the garden, not on top of it
        gw, gh = int(fw * 1.0) + 6, max(5, int(rh * 0.032))
        front = None
        if gw > 4:
            rnd = random.Random(int(feet_x * 7 + rh))
            gp = [[(0, 0, 0, 0)] * gw for _ in range(gh)]
            base = R.get(min(rw - 1, int(feet_x + fw * 0.6)), min(rh - 1, int(feet_y + 2)))
            greens = [tuple(max(0, min(255, int(c * f + o))) for c in base) for f, o in
                      ((1.15, 6), (1.35, 10), (0.9, 0), (1.6, 14))]
            clumps = [rnd.uniform(0.05, 0.95) * gw for _ in range(max(3, gw // 9))]
            for cxp in clumps:
                n = rnd.randint(3, 6)
                for k in range(n):
                    fan = (k - (n - 1) / 2.0) * 0.55
                    hgt = int(gh * rnd.uniform(0.45, 1.0))
                    col = rnd.choice(greens)
                    for j in range(hgt):
                        yy = gh - 1 - j
                        xx = int(round(cxp + fan * j * 0.6))
                        if 0 <= xx < gw:
                            tip = j >= hgt - 1
                            c2 = tuple(min(255, v + 22) for v in col) if tip else col
                            gp[yy][xx] = c2 + (255,)
            gimg = tk.PhotoImage(data=base64.b64encode(_png(gp, 1)))
            front = gimg.zoom(z, z) if z > 1 else gimg
        fxp = int((feet_x - gw / 2.0) * z)
        fyp = int((feet_y + 1) * z - gh * z)
        return {"photo": photo, "x": sx, "y": sy, "zs": zs, "front": front, "fx": fxp, "fy": fyp, "feet": (feet_x, feet_y)}

    def garden_anim(self):
        ui = self.garden_ui
        h = getattr(self, "hub", None)
        if not ui or not ui["cv"].winfo_exists():
            return
        if not h or h.get("page") != "garden" or ui.get("lay") is None:
            ui["anim_on"] = False
            if getattr(self, "breath", None):
                self.breath_stop(quiet=True)                   # you left the garden: the breathing session ends
            return
        cv, lay, z = ui["cv"], ui["lay"], ui["z"]
        W, H = cv.winfo_width(), cv.winfo_height()
        t = time.monotonic()
        try:
            self.breath_frame()
            for k, it in enumerate(ui["lamps"]):
                f = 0.5 + 0.5 * math.sin(t * 3.1 + k * 1.7) * math.sin(t * 1.3 + k)
                cv.itemconfigure(it, state="normal" if f > -0.6 else "hidden")
            for fl in ui["flies"]:
                it, x, y, ph, sp = fl
                fl[3] += 0.02 * sp
                nx = x + math.sin(fl[3] * 1.3) * 26 * sp
                ny = y + math.sin(fl[3] * 2.1 + 1) * 14 * sp
                cv.coords(it, nx, ny)
                cv.itemconfigure(it, state="normal" if math.sin(t * 1.7 + ph * 3) > -0.55 else "hidden")
            pcx, pcy, prx, pry = lay["pond"]
            for kq in ui["koi"]:
                body, head, ang, spd, rad = kq
                kq[2] += spd * 0.035
                a = kq[2]
                x = (pcx + math.cos(a) * prx * rad) * z
                y = (pcy + math.sin(a) * pry * rad) * z
                dx, dy = -math.sin(a) * (1 if spd > 0 else -1), math.cos(a) * 0.45 * (1 if spd > 0 else -1)
                L = 4.5 * z
                tail = math.sin(t * 8 + rad * 10) * 0.6
                cv.coords(body, x + dx * L, y + dy * L, x - dx * L + (-dy) * L * 0.35, y - dy * L + dx * L * 0.35 + tail * z,
                          x - dx * L - (-dy) * L * 0.35, y - dy * L - dx * L * 0.35 + tail * z)
                cv.coords(head, x + dx * L * 0.6 - z * 1.2, y + dy * L * 0.6 - z * 1.0, x + dx * L * 0.6 + z * 1.2,
                          y + dy * L * 0.6 + z * 1.0)
            for m in ui.get("mists", []):
                it, sp = m
                cv.move(it, sp, 0)
                if cv.coords(it)[0] > W:
                    cv.move(it, -W - 260, 0)
            # petals / leaves
            rate = ui.get("petal_rate", 0)
            if rate and random.random() < rate * 0.12 and len(ui["petals"]) < 46:
                tips = lay.get("tips") or [(lay["tree"][0], lay["tree"][1] - 40)]
                tx, ty, _ = random.choice(tips)
                x, y = tx * z + random.uniform(-6, 6) * z, ty * z
                s_ = random.uniform(1.4, 2.4) * max(1.0, z * 0.6)
                it = cv.create_polygon(x, y, x + s_, y - s_ * 0.6, x + s_ * 1.8, y, x + s_, y + s_ * 0.5,
                                       fill=random.choice(ui["petal_col"]), outline="", tags="fx")
                ui["petals"].append([it, random.uniform(0.25, 0.6) * z, random.uniform(0, 6.28), lay["tree"][1] * z +
                                     random.uniform(0, H * 0.18)])
            keep = []
            for p in ui["petals"]:
                it, vy, ph, floor = p
                p[2] += 0.08
                cv.move(it, math.sin(p[2]) * 0.9 * z * 0.5 + 0.25 * z, vy)
                c = cv.coords(it)
                if c and c[1] < floor:
                    keep.append(p)
                else:
                    cv.delete(it)
            ui["petals"] = keep
        except tk.TclError:
            return
        self.root.after(50, self.garden_anim)

